var __index = {"config":{"lang":["en"],"separator":"[\\s\\-]+","pipeline":["stopWordFilter"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"index.html","title":"AYON UI Qt","text":"<p>A Qt Widget library addon for AYON that provides UI components matching AYON's frontend design system.</p>"},{"location":"index.html#overview","title":"Overview","text":"<p>This addon provides a comprehensive library of Qt widgets styled to match AYON's React-based frontend. It enables developers to create consistent, professional-looking UIs across all AYON tools and applications.</p>"},{"location":"index.html#features","title":"Features","text":"<ul> <li>AYON-styled QStyle: Custom <code>AYONStyle</code> class that provides consistent theming</li> <li>Reusable Components: Buttons, containers, labels, text boxes, combo boxes, and more</li> <li>Variant Support: Multiple style variants for each component (surface, tonal, filled, etc.)</li> <li>Easy Integration: Simple API to apply styling to widget trees</li> </ul>"},{"location":"index.html#installation","title":"Installation","text":""},{"location":"index.html#as-an-ayon-addon","title":"As an AYON Addon","text":"<ol> <li> <p>Build the package:    <code>bash    python create_package.py</code></p> </li> <li> <p>Upload the generated <code>dist/ui_qt-{version}.zip</code> to your AYON server.</p> </li> <li> <p>Enable the addon in AYON Studio Settings.</p> </li> </ol>"},{"location":"index.html#for-development","title":"For Development","text":"<ol> <li>Clone the repository</li> <li> <p>Install dependencies:    <code>bash    uv sync</code></p> </li> <li> <p>Run tests:    <code>bash    uv run pytest</code></p> </li> </ol>"},{"location":"index.html#usage","title":"Usage","text":""},{"location":"index.html#basic-usage","title":"Basic Usage","text":"<pre><code>from ayon_ui_qt.style import get_ayon_style, style_widget_and_siblings\nfrom ayon_ui_qt.components import AYButton, AYContainer, AYLabel\n\n# Create a styled container with buttons\ncontainer = AYContainer(\n   layout=AYContainer.Layout.VBox,\n   variant=AYContainer.Variants.Low,\n   layout_margin=10,\n   layout_spacing=8,\n)\n\n# Add styled widgets\nbutton = AYButton(\"Click me\", variant=AYButton.Variants.Filled)\ncontainer.add_widget(button)\n\nlabel = AYLabel(\"Status\", icon=\"check_circle\", icon_color=\"#00ff00\")\ncontainer.add_widget(label)\n\n# Apply AYON styling to widget tree\nstyle_widget_and_siblings(container)\n</code></pre>"},{"location":"index.html#button-variants","title":"Button Variants","text":"<pre><code>from ayon_ui_qt.components import AYButton\n\n# Available variants: surface, tonal, filled, tertiary, text, nav, nav-small, danger\nAYButton(\"Surface\", variant=AYButton.Variants.Surface)\nAYButton(\"Filled\", variant=AYButton.Variants.Filled)\nAYButton(\"Danger\", variant=AYButton.Variants.Danger, icon=\"delete\")\n</code></pre>"},{"location":"index.html#container-layouts","title":"Container Layouts","text":"<pre><code>from ayon_ui_qt.components import AYContainer\n\n# Horizontal layout\nh_container = AYContainer(layout=AYContainer.Layout.HBox)\n\n# Vertical layout\nv_container = AYContainer(layout=AYContainer.Layout.VBox)\n\n# Grid layout\ngrid_container = AYContainer(layout=AYContainer.Layout.Grid)\n</code></pre>"},{"location":"index.html#project-structure","title":"Project Structure","text":"<pre><code>ayon-ui-qt/\n\u251c\u2500\u2500 client/\n\u2502   \u2514\u2500\u2500 ayon_ui_qt/          # Client-side addon code\n\u2502       \u251c\u2500\u2500 __init__.py      # Main module exports\n\u2502       \u251c\u2500\u2500 addon.py         # AYON addon integration\n\u2502       \u251c\u2500\u2500 version.py       # Version info\n\u2502       \u251c\u2500\u2500 ayon_style.py    # Custom QStyle implementation\n\u2502       \u251c\u2500\u2500 ayon_style.json  # Style definitions\n\u2502       \u251c\u2500\u2500 components/      # UI components\n\u2502       \u251c\u2500\u2500 resources/       # Assets and test data\n\u2502       \u2514\u2500\u2500 vendor/          # Vendored dependencies\n\u251c\u2500\u2500 server/\n\u2502   \u251c\u2500\u2500 __init__.py          # Server-side addon\n\u2502   \u2514\u2500\u2500 settings.py          # Server settings\n\u251c\u2500\u2500 package.py               # AYON package definition\n\u251c\u2500\u2500 version.py               # Root version\n\u251c\u2500\u2500 create_package.py        # Build script\n\u251c\u2500\u2500 pyproject.toml           # Python package config\n\u2514\u2500\u2500 README.md\n</code></pre>"},{"location":"index.html#available-components","title":"Available Components","text":"Component Description <code>AYButton</code> Styled push button with variants <code>AYContainer</code> Layout container (HBox, VBox, Grid) <code>AYFrame</code> Styled frame widget <code>AYLabel</code> Label with icon support <code>AYTextBox</code> Rich text editor with markdown <code>AYComboBox</code> Styled combo box <code>AYUserImage</code> User avatar display <code>AYComment</code> Comment display widget <code>AYEntityPath</code> Entity path breadcrumb <code>AYEntityThumbnail</code> Entity thumbnail button"},{"location":"index.html#development","title":"Development","text":""},{"location":"index.html#running-tests","title":"Running Tests","text":"<pre><code># Run individual component tests\nuv run python -m ayon_ui_qt.components.buttons\nuv run python -m ayon_ui_qt.style\n</code></pre>"},{"location":"index.html#building-the-package","title":"Building the Package","text":"<pre><code>python create_package.py\n</code></pre> <p>The package will be created at <code>dist/ui_qt-{version}.zip</code>.</p>"},{"location":"index.html#license","title":"License","text":"<p>Apache-2.0</p>"},{"location":"index.html#contributing","title":"Contributing","text":"<p>Contributions are welcome! Please follow the coding standards defined in the project's <code>.kilocode/rules/coding_standards.md</code>.</p>"},{"location":"autoapi/summary.html","title":"Summary","text":"<ul> <li>client<ul> <li>ayon_ui_qt<ul> <li>addon</li> <li>color_utils</li> <li>components<ul> <li>buttons</li> <li>check_box</li> <li>checkbox_handler</li> <li>combo_box</li> <li>comment</li> <li>comment_completion</li> <li>container</li> <li>entity_card</li> <li>entity_path</li> <li>entity_thumbnail</li> <li>filter</li> <li>frame</li> <li>gallery_dialog</li> <li>label</li> <li>layouts</li> <li>line_edit</li> <li>qss_override</li> <li>screenshot_capture</li> <li>scroll_area</li> <li>slicer</li> <li>table_filter</li> <li>table_model</li> <li>table_view</li> <li>tag</li> <li>tag_selector</li> <li>task_queue</li> <li>task_queue_monitor</li> <li>text_box</li> <li>text_edit</li> <li>tree_model</li> <li>tree_view</li> <li>user_image</li> </ul> </li> <li>data_models</li> <li>image_cache</li> <li>style</li> <li>tester</li> <li>utils</li> <li>variants</li> <li>vendor<ul> <li>qtmaterialsymbols<ul> <li>browser</li> <li>exceptions</li> <li>iconic_font</li> <li>resources</li> <li>structures</li> <li>utils</li> <li>version</li> </ul> </li> </ul> </li> <li>version</li> </ul> </li> </ul> </li> <li>server</li> </ul>"},{"location":"autoapi/client/ayon_ui_qt/index.html","title":"ayon_ui_qt","text":"<p>AYON UI Qt - A Qt Widget library styled for AYON.</p> <p>This module provides Qt widgets that match AYON's frontend design system, enabling consistent UI across all AYON tools and applications.</p>"},{"location":"autoapi/client/ayon_ui_qt/index.html#client.ayon_ui_qt.UIQtAddon","title":"<code>UIQtAddon</code>","text":"<p>               Bases: <code>AYONAddon</code></p> <p>Addon providing AYON-styled Qt widgets.</p> <p>This addon provides a library of Qt widgets that match AYON's frontend design system, enabling consistent UI across all AYON tools.</p> Source code in <code>client/ayon_ui_qt/addon.py</code> <pre><code>class UIQtAddon(AYONAddon):\n    \"\"\"Addon providing AYON-styled Qt widgets.\n\n    This addon provides a library of Qt widgets that match AYON's\n    frontend design system, enabling consistent UI across all\n    AYON tools.\n    \"\"\"\n\n    name = \"ui_qt\"\n    title = \"AYON UI Qt\"\n    version = __version__\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/addon.html","title":"addon","text":"<p>AYON addon definition for UI Qt library.</p> <p>This module provides the client-side addon integration with AYON.</p>"},{"location":"autoapi/client/ayon_ui_qt/addon.html#client.ayon_ui_qt.addon.UIQtAddon","title":"<code>UIQtAddon</code>","text":"<p>               Bases: <code>AYONAddon</code></p> <p>Addon providing AYON-styled Qt widgets.</p> <p>This addon provides a library of Qt widgets that match AYON's frontend design system, enabling consistent UI across all AYON tools.</p> Source code in <code>client/ayon_ui_qt/addon.py</code> <pre><code>class UIQtAddon(AYONAddon):\n    \"\"\"Addon providing AYON-styled Qt widgets.\n\n    This addon provides a library of Qt widgets that match AYON's\n    frontend design system, enabling consistent UI across all\n    AYON tools.\n    \"\"\"\n\n    name = \"ui_qt\"\n    title = \"AYON UI Qt\"\n    version = __version__\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/color_utils.html","title":"color_utils","text":""},{"location":"autoapi/client/ayon_ui_qt/color_utils.html#client.ayon_ui_qt.color_utils.compute_color_for_contrast","title":"<code>compute_color_for_contrast(background, foreground, min_contrast_ratio=4.5)</code>  <code>cached</code>","text":"<p>Adjust foreground color to achieve minimum contrast with background.</p> <p>Preserves the hue and saturation of the original foreground color, adjusting only the lightness to achieve the required contrast ratio.</p> <p>Parameters:</p> Name Type Description Default <code>background</code> <code>tuple</code> <p>The background color to contrast against.</p> required <code>foreground</code> <code>tuple</code> <p>The foreground color to adjust.</p> required <code>min_contrast_ratio</code> <code>float</code> <p>Target minimum contrast ratio (default 4.5:1).</p> <code>4.5</code> <p>Returns:</p> Type Description <code>QColor</code> <p>A QColor with the same hue/saturation but adjusted lightness</p> <code>QColor</code> <p>to meet the contrast requirement. Returns original if already</p> <code>QColor</code> <p>sufficient.</p> Source code in <code>client/ayon_ui_qt/color_utils.py</code> <pre><code>@lru_cache(maxsize=256)\ndef compute_color_for_contrast(\n    background: tuple,  # (r, g, b, a)\n    foreground: tuple,  # (r, g, b, a)\n    min_contrast_ratio: float = 4.5,\n) -&gt; QColor:\n    \"\"\"Adjust foreground color to achieve minimum contrast with background.\n\n    Preserves the hue and saturation of the original foreground color,\n    adjusting only the lightness to achieve the required contrast ratio.\n\n    Args:\n        background: The background color to contrast against.\n        foreground: The foreground color to adjust.\n        min_contrast_ratio: Target minimum contrast ratio (default 4.5:1).\n\n    Returns:\n        A QColor with the same hue/saturation but adjusted lightness\n        to meet the contrast requirement. Returns original if already\n        sufficient.\n    \"\"\"\n\n    bg_lum = relative_luminance(*background)\n    fg_lum = relative_luminance(*foreground)\n\n    # Check if already sufficient\n    current_ratio = contrast_ratio(bg_lum, fg_lum)\n    if current_ratio &gt;= min_contrast_ratio:\n        # print(f\"Final ratio: {current_ratio}: {QColor(*foreground).name()}\")\n        return QColor(*foreground)\n\n    fg_col = QColor(*foreground)\n\n    # Get HSL components (hue, saturation preserved)\n    h = fg_col.hslHueF()\n    s = fg_col.hslSaturationF()\n    original_l = fg_col.lightnessF()\n\n    # Determine if we should lighten or darken based on background\n    # Use luminance midpoint (0.1791 for 4.5:1 contrast with both black/white)\n    should_lighten = bg_lum &lt; 0.1791\n\n    # Binary search for optimal lightness\n    if should_lighten:\n        low, high = original_l, 1.0\n        # return QColor(\"white\")\n    else:\n        low, high = 0.0, original_l\n        # return QColor(\"black\")\n\n    result = QColor(\n        fg_col.red(),\n        fg_col.green(),\n        fg_col.blue(),\n        fg_col.alpha(),\n    )\n    original_alpha = result.alpha()\n\n    # Binary search (8 iterations gives ~0.4% precision)\n    for _ in range(8):\n        mid = (low + high) * 0.5\n        result.setHslF(h if h &gt;= 0 else 0.0, s, mid)\n        result.setAlpha(original_alpha)  # Preserve alpha\n\n        test_lum = relative_luminance(*result.toRgb().toTuple())\n        test_ratio = contrast_ratio(bg_lum, test_lum)\n\n        if test_ratio &gt;= min_contrast_ratio:\n            if should_lighten:\n                high = mid  # Can use darker shade\n            else:\n                low = mid  # Can use lighter shade\n        else:\n            if should_lighten:\n                low = mid  # Need lighter\n            else:\n                high = mid  # Need darker\n\n    # Final adjustment to ensure we meet the threshold\n    final_l = high if should_lighten else low\n    result.setHslF(h if h &gt;= 0 else 0.0, s, max(0.0, min(1.0, final_l)))\n    result.setAlpha(original_alpha)  # Preserve alpha\n\n    # Verify and fallback to black/white if HSL adjustment isn't enough\n    final_ratio = contrast_ratio(\n        bg_lum, relative_luminance(*result.toRgb().toTuple())\n    )\n    if final_ratio &lt; min_contrast_ratio:\n        # HSL adjustment insufficient (saturated colors can't reach target)\n        # Fall back to black or white\n        white_ratio = 1.05 / (bg_lum + 0.05)\n        black_ratio = (bg_lum + 0.05) * 20.0\n        result = (\n            QColor(255, 255, 255, original_alpha)\n            if white_ratio &gt; black_ratio\n            else QColor(0, 0, 0, original_alpha)\n        )\n    # print(f\"Final ratio: {final_ratio}: {result.name()}\")\n    return result\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/color_utils.html#client.ayon_ui_qt.color_utils.contrast_ratio","title":"<code>contrast_ratio(lum1, lum2)</code>","text":"<p>Calculate the contrast ratio between two relative luminance values per WCAG 2.1.</p> <p>The contrast ratio ranges from 1:1 (no contrast) to 21:1 (maximum, black vs white). WCAG recommends: - 4.5:1 minimum for normal text (AA) - 7:1 minimum for enhanced contrast (AAA) - 3:1 minimum for large text or UI components</p> Source code in <code>client/ayon_ui_qt/color_utils.py</code> <pre><code>def contrast_ratio(lum1: float, lum2: float) -&gt; float:\n    \"\"\"Calculate the contrast ratio between two relative luminance values\n    per WCAG 2.1.\n\n    The contrast ratio ranges from 1:1 (no contrast) to 21:1 (maximum,\n    black vs white). WCAG recommends:\n    - 4.5:1 minimum for normal text (AA)\n    - 7:1 minimum for enhanced contrast (AAA)\n    - 3:1 minimum for large text or UI components\n    \"\"\"\n    if lum1 &gt; lum2:\n        return (lum1 + 0.05) / (lum2 + 0.05)\n    return (lum2 + 0.05) / (lum1 + 0.05)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/color_utils.html#client.ayon_ui_qt.color_utils.relative_luminance","title":"<code>relative_luminance(r, g, b, _)</code>  <code>cached</code>","text":"<p>Calculate relative luminance of a color, i.e. sRGB luminance in linear space.</p> Source code in <code>client/ayon_ui_qt/color_utils.py</code> <pre><code>@lru_cache(maxsize=256)\ndef relative_luminance(r: int, g: int, b: int, _) -&gt; float:\n    \"\"\"Calculate relative luminance of a color, i.e. sRGB luminance in\n    linear space.\n    \"\"\"\n    comp = [r, g, b]\n    for i in range(3):\n        comp[i] /= 255\n        if comp[i] &lt;= 0.03928:\n            comp[i] /= 12.92\n        else:\n            comp[i] = ((comp[i] + 0.055) / 1.055) ** 2.4\n    return comp[0] * 0.2126 + comp[1] * 0.7152 + comp[2] * 0.0722\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/data_models.html","title":"data_models","text":""},{"location":"autoapi/client/ayon_ui_qt/data_models.html#client.ayon_ui_qt.data_models.ActivityData","title":"<code>ActivityData</code>  <code>dataclass</code>","text":"<p>Simple dataclass to cache representation data.</p> Source code in <code>client/ayon_ui_qt/data_models.py</code> <pre><code>@dataclass\nclass ActivityData:\n    \"\"\"Simple dataclass to cache representation data.\"\"\"\n\n    representation_id: str = \"\"\n    hash: int = field(init=False)\n    activity_list: list[\n        CommentModel | VersionPublishModel | StatusChangeModel\n    ] = field(default_factory=list)\n\n    def __post_init__(self):\n        \"\"\"Compute the hash of the activity list.\"\"\"\n        self.hash = hash(tuple(self.activity_list))\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/data_models.html#client.ayon_ui_qt.data_models.ActivityData.__post_init__","title":"<code>__post_init__()</code>","text":"<p>Compute the hash of the activity list.</p> Source code in <code>client/ayon_ui_qt/data_models.py</code> <pre><code>def __post_init__(self):\n    \"\"\"Compute the hash of the activity list.\"\"\"\n    self.hash = hash(tuple(self.activity_list))\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/data_models.html#client.ayon_ui_qt.data_models.CommentCategory","title":"<code>CommentCategory</code>  <code>dataclass</code>","text":"<p>Model for powerpack <code>activity_categories</code> settings</p> Source code in <code>client/ayon_ui_qt/data_models.py</code> <pre><code>@dataclass\nclass CommentCategory:\n    \"\"\"Model for powerpack `activity_categories` settings\"\"\"\n\n    name: str\n    color: str\n    access: dict[str, Any]\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/data_models.html#client.ayon_ui_qt.data_models.CommentModel","title":"<code>CommentModel</code>  <code>dataclass</code>","text":"Source code in <code>client/ayon_ui_qt/data_models.py</code> <pre><code>@dataclass(unsafe_hash=True)\nclass CommentModel:\n    activity_id: str = \"\"\n    user_full_name: str = \"\"\n    user_name: str = \"\"\n    user_src: str = \"\"\n    comment: str = \"\"  # type: ignore\n    category: str = \"\"\n    category_color: str = \"\"\n    comment_date: str = \"\"\n    short_date: str = field(init=False, hash=False)\n    type: ActivityCategory = field(\n        init=False, default=ActivityCategory.COMMENT, hash=False\n    )\n    files: list[FileModel] = field(default_factory=list, hash=False)\n    annotations: list[AnnotationModel] = field(\n        default_factory=list, hash=False\n    )\n    _comment: str = field(init=False, repr=False)\n\n    def __post_init__(self):\n        \"\"\"Set the date if not set and compute the short date.\"\"\"\n        if not self.comment_date:\n            self.comment_date = datetime.now(timezone.utc).isoformat()\n\n        self.short_date = short_date(self.comment_date)\n\n    @property\n    def comment(self):  # noqa: F811\n        return self._comment\n\n    @comment.setter\n    def comment(self, value: str):\n        \"\"\"Check if the comment contains a checklist.\"\"\"\n        if re.search(RE_HAS_CHECKLIST, str(value)):\n            self.type = ActivityCategory.COMMENT | ActivityCategory.CHECKLIST\n        self._comment = value\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/data_models.html#client.ayon_ui_qt.data_models.CommentModel.__post_init__","title":"<code>__post_init__()</code>","text":"<p>Set the date if not set and compute the short date.</p> Source code in <code>client/ayon_ui_qt/data_models.py</code> <pre><code>def __post_init__(self):\n    \"\"\"Set the date if not set and compute the short date.\"\"\"\n    if not self.comment_date:\n        self.comment_date = datetime.now(timezone.utc).isoformat()\n\n    self.short_date = short_date(self.comment_date)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/data_models.html#client.ayon_ui_qt.data_models.FileModel","title":"<code>FileModel</code>  <code>dataclass</code>","text":"<p>Model for activity attached files.</p> <p>Attachments could be images, there could be also preview available for them.</p> Source code in <code>client/ayon_ui_qt/data_models.py</code> <pre><code>@dataclass\nclass FileModel:\n    \"\"\"Model for activity attached files.\n\n    Attachments could be images, there could be also preview available for\n    them.\n    \"\"\"\n\n    id: str\n    mime: str\n    local_path: str = \"\"\n    thumb_local_path: str = \"\"\n    frame: int = 0\n    start_frame: int = 0  # for sequences, to compute the actual frame number\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/data_models.html#client.ayon_ui_qt.data_models.ProjectData","title":"<code>ProjectData</code>  <code>dataclass</code>","text":"<p>Model to pass project data - anatomy, users, teams</p> Source code in <code>client/ayon_ui_qt/data_models.py</code> <pre><code>@dataclass\nclass ProjectData:\n    \"\"\"Model to pass project data - anatomy, users, teams\"\"\"\n\n    project_name: str\n    users: List[User]\n    teams: List[Team]\n    anatomy: dict[str, Any]\n    comment_category: List[CommentCategory]\n    current_user: Optional[User]\n\n    @staticmethod\n    def not_set():\n        ns = \"PROJECT NOT SET\"\n        return ProjectData(\n            project_name=ns,\n            users=[],\n            teams=[],\n            anatomy={},\n            comment_category=[],\n            current_user=None,\n        )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/data_models.html#client.ayon_ui_qt.data_models.User","title":"<code>User</code>  <code>dataclass</code>","text":"<p>Data model for user</p> Source code in <code>client/ayon_ui_qt/data_models.py</code> <pre><code>@dataclass\nclass User:\n    \"\"\"Data model for user\"\"\"\n\n    name: str\n    short_name: str\n    full_name: str\n    email: str\n    avatar_url: str = \"\"\n    avatar_local_path: str = \"\"\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/data_models.html#client.ayon_ui_qt.data_models.VersionData","title":"<code>VersionData</code>  <code>dataclass</code>","text":"<p>Model to pass enhanced version data</p> Source code in <code>client/ayon_ui_qt/data_models.py</code> <pre><code>@dataclass\nclass VersionData:\n    \"\"\"Model to pass enhanced version data\"\"\"\n\n    id: str\n    name: str\n    author: str\n    tags: list[str]\n    status: str\n    product_name: str\n    task_name: str\n    priority: str\n    folder_path: str\n    assignees: list[str]\n    attrib: dict[str, str]\n    thumbnail_id: str = \"\"\n    thumbnail_local_path: str = \"\"\n\n    @staticmethod\n    def not_set():\n        ns = \"VERSION NOT SET\"\n        return VersionData(\n            id=ns,\n            name=ns,\n            author=ns,\n            tags=[],\n            status=ns,\n            product_name=ns,\n            task_name=ns,\n            priority=ns,\n            folder_path=ns,\n            assignees=[],\n            attrib={},\n            thumbnail_id=\"\",\n            thumbnail_local_path=\"\",\n        )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/image_cache.html","title":"image_cache","text":""},{"location":"autoapi/client/ayon_ui_qt/image_cache.html#client.ayon_ui_qt.image_cache.ImageCache","title":"<code>ImageCache</code>","text":"<p>Process- and thread-safe LRU image cache backed by SQLite.</p> <p>Stores image files on disk and tracks metadata in a SQLite database. Eviction is based on least-recently-used (LRU) access time.</p> Concurrency model <ul> <li>Each thread gets its own <code>sqlite3.Connection</code> via   <code>threading.local()</code>.  SQLite WAL journal mode allows multiple   readers to proceed concurrently across both threads and OS processes;   writers are serialised by SQLite's internal file-level locking, with   a 10-second busy-timeout handling contention.</li> <li>Cache-miss work (calling file_closure and copying the file) is   serialised per cache key via a per-key <code>threading.Lock</code>.   Threads requesting different keys proceed fully in parallel; threads   requesting the same key during a miss wait for exactly one download   to complete and then read the already-populated entry.</li> </ul> Environment variables <p>AYON_IMG_CACHE_DIR: Parent directory for the AYON_IMG_CACHE folder.                     Defaults to the system temp directory. AYON_IMG_CACHE_SIZE: Override default cache size in MB. AYON_IMG_CACHE_CLEAR_ON_STARTUP: Clear all cache files on startup.</p> <p>Attributes:</p> Name Type Description <code>cache_path</code> <code>Path</code> <p>Directory where cached files are stored.</p> <code>max_size_in_MB</code> <code>int</code> <p>Maximum cache size in megabytes.</p> <code>max_size_bytes</code> <code>int</code> <p>Maximum cache size in bytes.</p> Source code in <code>client/ayon_ui_qt/image_cache.py</code> <pre><code>class ImageCache:\n    \"\"\"Process- and thread-safe LRU image cache backed by SQLite.\n\n    Stores image files on disk and tracks metadata in a SQLite database.\n    Eviction is based on least-recently-used (LRU) access time.\n\n    Concurrency model:\n        - Each thread gets its own ``sqlite3.Connection`` via\n          ``threading.local()``.  SQLite WAL journal mode allows multiple\n          readers to proceed concurrently across both threads and OS processes;\n          writers are serialised by SQLite's internal file-level locking, with\n          a 10-second busy-timeout handling contention.\n        - Cache-miss work (calling *file_closure* and copying the file) is\n          serialised **per cache key** via a per-key ``threading.Lock``.\n          Threads requesting different keys proceed fully in parallel; threads\n          requesting the same key during a miss wait for exactly one download\n          to complete and then read the already-populated entry.\n\n    Environment variables:\n        AYON_IMG_CACHE_DIR: Parent directory for the AYON_IMG_CACHE folder.\n                            Defaults to the system temp directory.\n        AYON_IMG_CACHE_SIZE: Override default cache size in MB.\n        AYON_IMG_CACHE_CLEAR_ON_STARTUP: Clear all cache files on startup.\n\n    Attributes:\n        cache_path (Path): Directory where cached files are stored.\n        max_size_in_MB (int): Maximum cache size in megabytes.\n        max_size_bytes (int): Maximum cache size in bytes.\n    \"\"\"\n\n    _instance: ImageCache | None = None\n    _lock: threading.Lock = threading.Lock()\n\n    @classmethod\n    def get_instance(\n        cls,\n        cache_path: str | Path | None = None,\n        max_size_in_MB: int = 500,\n    ) -&gt; ImageCache:\n        \"\"\"Return the singleton cache instance, creating it if needed.\n\n        NOTE: `cache_path` and `max_size_in_MB` are only used on the first\n              call. Subsequent calls return the same instance regardless of\n              the arguments.\n\n        Args:\n            cache_path: Directory path for storing cached files.\n            max_size_in_MB: Maximum cache size in megabytes.\n\n        Returns:\n            The singleton ImageCache instance.\n\n        Raises:\n            ValueError: If max_size_in_MB is not positive.\n        \"\"\"\n        with cls._lock:\n            if cls._instance is not None:\n                return cls._instance\n            if max_size_in_MB &lt;= 0:\n                raise ValueError(\"max_size_in_MB must be positive\")\n            instance = object.__new__(cls)\n            instance._initialize(cache_path, max_size_in_MB)\n            cls._instance = instance\n            return cls._instance\n\n    # ------------------------------------------------------------------\n    # Initialisation\n    # ------------------------------------------------------------------\n\n    @staticmethod\n    def _check_sqlite_version() -&gt; None:\n        \"\"\"Raise RuntimeError if the runtime SQLite is too old.\n\n        WAL journal mode requires SQLite \u2265 3.7.0 (released 2010).  Any\n        reasonably modern Python 3 installation satisfies this requirement,\n        but distributions that link CPython against a very old system SQLite\n        could fail at the PRAGMA call without a clear error message.  This\n        check surfaces the problem at initialisation time.\n\n        Raises:\n            RuntimeError: If the runtime SQLite version is below 3.7.0.\n        \"\"\"\n        min_version = (3, 7, 0)\n        if sqlite3.sqlite_version_info &lt; min_version:\n            raise RuntimeError(\n                f\"ImageCache requires SQLite &gt;= {'.'.join(map(str, min_version))};\"\n                f\" found {sqlite3.sqlite_version}\"\n            )\n\n    def _get_tmp_dir(self) -&gt; Path:\n        tmp = Path(os.environ.get(\"AYON_IMG_CACHE_DIR\", tempfile.gettempdir()))\n        tmp = tmp / \"AYON_IMG_CACHE\"\n        tmp.mkdir(parents=True, exist_ok=True)\n        if os.name != \"nt\":\n            os.chmod(tmp, 0o700)\n        logger.info(f\"AYON image cache: {tmp} ({self.max_size_in_MB} MB)\")\n        return tmp\n\n    def _initialize(\n        self,\n        cache_path: str | Path | None,\n        max_size_in_MB: int,\n    ) -&gt; None:\n        \"\"\"Initialise the cache instance.\n\n        Args:\n            cache_path: Directory path for storing cached files.\n            max_size_in_MB: Maximum cache size in megabytes.\n        \"\"\"\n        self._check_sqlite_version()\n\n        raw = os.environ.get(\"AYON_IMG_CACHE_SIZE\")\n        if raw is not None:\n            self.max_size_in_MB = _parse_positive_int(\n                raw, \"AYON_IMG_CACHE_SIZE\"\n            )\n        else:\n            self.max_size_in_MB = _parse_positive_int(\n                max_size_in_MB, \"max_size_in_MB\"\n            )\n        self.max_size_bytes = self.max_size_in_MB * 1024 * 1024\n\n        self.cache_path = (\n            Path(cache_path) if cache_path else self._get_tmp_dir()\n        )\n        self.cache_path.mkdir(parents=True, exist_ok=True)\n\n        self._db_path = self.cache_path / _DB_FILENAME\n\n        # Per-thread connection storage.\n        self._local = threading.local()\n\n        # Guards both _key_locks and _all_connections.\n        self._meta_lock = threading.Lock()\n\n        # Per-key locks that serialise cache-miss work for the same key.\n        # WeakValueDictionary ensures locks are garbage-collected once no\n        # thread holds a reference, preventing unbounded growth.\n        self._key_locks: weakref.WeakValueDictionary[str, threading.Lock] = (\n            weakref.WeakValueDictionary()\n        )\n\n        # Registry of every connection ever opened so they can all be\n        # closed at process exit.\n        self._all_connections: list[sqlite3.Connection] = []\n\n        # Initialise the schema using the calling thread's connection.\n        setup_conn = self._get_conn()\n        self._set_wal_mode(setup_conn)\n        setup_conn.execute(_CREATE_TABLE_SQL)\n        setup_conn.execute(_CREATE_INDEX_SQL)\n        setup_conn.commit()\n\n        if \"AYON_IMG_CACHE_CLEAR_ON_STARTUP\" in os.environ:\n            self._clear_all_files()\n\n        self._validate_cache_files()\n        self._cleanup_legacy_files()\n\n        atexit.register(self._close_all_connections)\n\n    def _clear_all_files(self) -&gt; None:\n        \"\"\"Delete every file in the cache directory and reset the DB.\"\"\"\n        conn = self._get_conn()\n        count = 0\n        for entry in os.scandir(self.cache_path):\n            if entry.is_file() and entry.name != self._db_path.name:\n                if _DB_FILENAME in entry.path:\n                    continue\n                try:\n                    os.remove(entry.path)\n                    count += 1\n                except OSError as exc:\n                    logger.warning(f\"Could not remove {entry.path}: {exc}\")\n        conn.execute(\"DELETE FROM cache\")\n        conn.commit()\n        logger.info(f\"AYON image cache: cleared ({count} files removed)\")\n\n    def _cleanup_legacy_files(self) -&gt; None:\n        \"\"\"Remove legacy JSON metadata files left from the previous version.\"\"\"\n        for name in (\"cache_metadata.json\", \"cache_metadata.json.lock\"):\n            legacy = self.cache_path / name\n            if legacy.exists():\n                try:\n                    legacy.unlink()\n                    logger.debug(f\"Removed legacy cache file: {legacy}\")\n                except OSError as exc:\n                    logger.warning(\n                        f\"Could not remove legacy file {legacy}: {exc}\"\n                    )\n\n    def _set_wal_mode(\n        self,\n        conn: sqlite3.Connection,\n        retries: int = 5,\n        base_delay: float = 0.1,\n    ) -&gt; None:\n        \"\"\"Switch the database to WAL journal mode with retries.\n\n        ``PRAGMA journal_mode=WAL`` requires an exclusive lock on the\n        database file.  Under heavy concurrent process startup the lock\n        may not be available even though ``busy_timeout`` is set, so we\n        retry with linear back-off.\n\n        Args:\n            conn: The connection to use for setting WAL mode.\n            retries: Maximum number of attempts.\n            base_delay: Seconds to wait between attempts (multiplied\n                by the attempt number).\n        \"\"\"\n        for attempt in range(retries):\n            try:\n                conn.execute(\"PRAGMA journal_mode=WAL\")\n                return\n            except sqlite3.OperationalError:\n                if attempt == retries - 1:\n                    raise\n                time.sleep(base_delay * (attempt + 1))\n\n    # ------------------------------------------------------------------\n    # Connection management\n    # ------------------------------------------------------------------\n\n    def _open_connection(self) -&gt; sqlite3.Connection:\n        \"\"\"Open and configure a new SQLite connection.\n\n        WAL journal mode is **not** set here; it is a one-time,\n        exclusive-lock operation performed during initialisation via\n        ``_set_wal_mode``.  Once set, WAL mode is stored in the database\n        file header and all subsequent connections inherit it automatically.\n\n        Returns:\n            A new ``sqlite3.Connection`` configured with busy_timeout.\n        \"\"\"\n        return sqlite3.connect(str(self._db_path), timeout=10)\n\n    def _get_conn(self) -&gt; sqlite3.Connection:\n        \"\"\"Return the per-thread SQLite connection, creating it if needed.\n\n        Each thread gets its own connection, which avoids the need for an\n        application-level lock on reads.  New connections are registered in\n        ``_all_connections`` so they can be closed at process exit.\n\n        Returns:\n            The ``sqlite3.Connection`` for the calling thread.\n        \"\"\"\n        conn = getattr(self._local, \"conn\", None)\n        if conn is None:\n            conn = self._open_connection()\n            self._local.conn = conn\n            with self._meta_lock:\n                self._all_connections.append(conn)\n        return conn\n\n    def _close_all_connections(self) -&gt; None:\n        \"\"\"Close every per-thread connection opened by this instance.\n\n        Registered with ``atexit`` during initialisation.\n        \"\"\"\n        with self._meta_lock:\n            for conn in self._all_connections:\n                try:\n                    conn.close()\n                except Exception:\n                    logger.debug(\n                        \"Exception while closing cache DB connection\",\n                        exc_info=True,\n                    )\n            self._all_connections.clear()\n\n    # ------------------------------------------------------------------\n    # Per-key locking\n    # ------------------------------------------------------------------\n\n    def _get_key_lock(self, key: str) -&gt; threading.Lock:\n        \"\"\"Return the per-key lock for *key*, creating it if needed.\n\n        Args:\n            key: The cache key.\n\n        Returns:\n            A ``threading.Lock`` dedicated to *key*.\n        \"\"\"\n        with self._meta_lock:\n            lock = self._key_locks.get(key)\n            if lock is None:\n                lock = threading.Lock()\n                self._key_locks[key] = lock\n            return lock\n\n    # ------------------------------------------------------------------\n    # Internal DB helpers\n    # ------------------------------------------------------------------\n\n    def _lookup(self, key: str) -&gt; Path | None:\n        \"\"\"Return the cached ``Path`` for *key* without updating metadata.\n\n        Purges the DB row and returns ``None`` if the file is missing on disk.\n\n        Args:\n            key: The cache key to look up.\n\n        Returns:\n            Absolute ``Path`` to the cached file, or ``None`` on a miss.\n        \"\"\"\n        conn = self._get_conn()\n        row = conn.execute(\n            \"SELECT file_path FROM cache WHERE key = ?\", (key,)\n        ).fetchone()\n        if row is None:\n            return None\n        cached_path = Path(row[0])\n        if cached_path.exists():\n            return cached_path\n        logger.debug(f\"Cached file missing for key '{key}': purging row\")\n        conn.execute(\"DELETE FROM cache WHERE key = ?\", (key,))\n        conn.commit()\n        return None\n\n    def _touch(self, key: str) -&gt; None:\n        \"\"\"Increment the access counter and refresh last_accessed for *key*.\n\n        This is a best-effort metadata update for LRU ordering.  If the row\n        has been removed between a preceding ``_lookup`` and this call (e.g.\n        by a concurrent eviction), the ``UPDATE`` matches zero rows and is\n        silently discarded \u2014 LRU accuracy is not required to be exact.\n\n        Args:\n            key: The cache key to update.\n        \"\"\"\n        conn = self._get_conn()\n        conn.execute(\n            \"UPDATE cache \"\n            \"SET access_count = access_count + 1, last_accessed = ? \"\n            \"WHERE key = ?\",\n            (time.time(), key),\n        )\n        conn.commit()\n\n    # ------------------------------------------------------------------\n    # Public API\n    # ------------------------------------------------------------------\n\n    def get(self, key: str, file_closure: Callable) -&gt; str:\n        \"\"\"Return the cached file path for *key*, caching it if necessary.\n\n        Cache hits are served via a fast path that requires no application-\n        level locking; SQLite WAL mode allows concurrent reads across threads\n        and processes.\n\n        On a cache miss, a per-key lock is acquired so that only one thread\n        calls *file_closure* for a given key at a time.  After acquiring the\n        lock the database is re-checked: if another thread already populated\n        the entry the result is returned immediately without calling the\n        closure again.\n\n        *file_closure* is called **outside** any database transaction, so a\n        slow I/O operation (e.g. a network download) does not block threads\n        that are requesting different keys.\n\n        Args:\n            key: Unique identifier for the cached file.\n            file_closure: Callable returning the path to the source file.\n                          Called only on a cache miss.\n\n        Returns:\n            Absolute path to the cached file as a string.\n\n        Raises:\n            ValueError: If *key* is empty or *file_closure* returns a path\n                        that does not exist.\n            IOError: If the file cannot be copied into the cache.\n        \"\"\"\n        if not key:\n            raise ValueError(\"Cache key cannot be empty\")\n\n        # ------------------------------------------------------------------\n        # ------------------------------------------------------------------\n        # Fast path: pure SELECT \u2014 concurrent reads across threads/processes\n        # proceed without blocking each other in WAL mode.  _touch is a\n        # separate best-effort write; LRU accuracy does not need to be exact.\n        # ------------------------------------------------------------------\n        cached_path = self._lookup(key)\n        if cached_path is not None:\n            self._touch(key)\n            logger.debug(f\"Cache hit for key '{key}'\")\n            return str(cached_path)\n\n        # ------------------------------------------------------------------\n        # Slow path: acquire the per-key lock, then double-check.\n        # Only threads requesting the same key are serialised here; threads\n        # requesting different keys proceed fully in parallel.\n        # ------------------------------------------------------------------\n        with self._get_key_lock(key):\n            # Double-check: another thread may have populated the entry\n            # while we were waiting for the key lock.\n            cached_path = self._lookup(key)\n            if cached_path is not None:\n                self._touch(key)\n                logger.debug(f\"Cache hit for key '{key}' (after key lock)\")\n                return str(cached_path)\n\n            # True miss: call the closure outside any database transaction.\n            logger.debug(f\"Cache miss for key '{key}', calling file_closure\")\n            source_path = Path(file_closure())\n\n            if not source_path.exists():\n                raise ValueError(\n                    f\"Loader returned non-existent file: {source_path}\"\n                )\n\n            cache_filename = self._generate_cache_filename(key, source_path)\n            cached_path = self.cache_path / cache_filename\n\n            self._atomic_copy(source_path, cached_path)\n\n            conn = self._get_conn()\n            file_size = cached_path.stat().st_size\n            conn.execute(\n                \"INSERT OR REPLACE INTO cache \"\n                \"(key, file_path, size_bytes, access_count, last_accessed) \"\n                \"VALUES (?, ?, ?, 1, ?)\",\n                (key, str(cached_path), file_size, time.time()),\n            )\n            conn.commit()\n\n        # Eviction runs outside the per-key lock: it can be slow (file I/O +\n        # bulk DB DELETE) and must not block other threads querying this key.\n        self._evict_if_needed()\n\n        logger.debug(f\"Cached file for key '{key}': {cached_path}\")\n        return str(cached_path)\n\n    def has(self, key: str) -&gt; bool:\n        \"\"\"Return True if *key* is cached and its file exists on disk.\n\n        Args:\n            key: Cache key to check.\n\n        Returns:\n            True if the key is present and the file exists, else False.\n        \"\"\"\n        return self._lookup(key) is not None\n\n    def get_path(self, key: str) -&gt; str | None:\n        \"\"\"Return the cached file path for *key* if it exists, else None.\n\n        Updates access metadata when the entry is found.\n\n        Args:\n            key: Cache key to look up.\n\n        Returns:\n            Absolute path string to the cached file, or None.\n        \"\"\"\n        cached_path = self._lookup(key)\n        if cached_path is None:\n            return None\n        self._touch(key)\n        return str(cached_path)\n\n    # ------------------------------------------------------------------\n    # Internal helpers\n    # ------------------------------------------------------------------\n\n    def _atomic_copy(self, src: Path, dst: Path) -&gt; None:\n        \"\"\"Copy *src* to *dst* atomically using a temp file + os.replace().\n\n        The temporary file is created in the same directory as *dst* so that\n        ``os.replace`` is an atomic rename on the same filesystem.\n\n        Args:\n            src: Source file path.\n            dst: Destination file path.\n\n        Raises:\n            IOError: If the copy or rename fails.\n        \"\"\"\n        fd, tmp_name = tempfile.mkstemp(dir=self.cache_path, suffix=\".tmp\")\n        os.close(fd)\n        tmp_path = Path(tmp_name)\n        try:\n            shutil.copy2(src, tmp_path)\n            os.replace(tmp_path, dst)\n        except OSError as exc:\n            tmp_path.unlink(missing_ok=True)\n            raise IOError(f\"Failed to cache file: {exc}\") from exc\n\n    def set_path(self, key: str, file_path: str) -&gt; Path:\n        \"\"\"Manually set a cache entry for a given key and file path.\"\"\"\n        with self._access_lock:\n            source_path = Path(file_path)\n            if not source_path.exists():\n                raise ValueError(\n                    f\"Provided file does not exist: {source_path}\"\n                )\n\n            cache_filename = self._generate_cache_filename(key, source_path)\n            cached_path = self.cache_path / cache_filename\n\n            try:\n                with open(source_path, \"rb\") as src:\n                    with open(cached_path, \"wb\") as dst:\n                        dst.write(src.read())\n            except IOError as e:\n                raise IOError(f\"Failed to set cache file: {e}\") from e\n\n            file_size = cached_path.stat().st_size\n            self._metadata[key] = {\n                \"file_path\": str(cached_path),\n                \"size_bytes\": file_size,\n                \"access_count\": 0,\n                \"last_accessed\": time.time(),\n            }\n            self._evict_if_needed()\n            return cached_path\n\n    def _generate_cache_filename(self, key: str, source_path: Path) -&gt; str:\n        \"\"\"Build a cache filename from a SHA-256 hash of *key*.\n\n        Args:\n            key: The cache key.\n            source_path: The original file (used only to preserve extension).\n\n        Returns:\n            Filename string with the original extension.\n        \"\"\"\n        key_hash = hashlib.sha256(key.encode()).hexdigest()\n        extension = source_path.suffix\n        return f\"{key_hash}{extension}\"\n\n    def _evict_if_needed(self) -&gt; None:\n        \"\"\"Evict LRU entries until cache size is at 90 % of the limit.\"\"\"\n        conn = self._get_conn()\n        current_size = self._get_cache_size()\n\n        if current_size &lt;= self.max_size_bytes:\n            return\n\n        target_size = int(self.max_size_bytes * 0.9)\n        logger.info(\n            f\"Cache size ({current_size} bytes) exceeds limit \"\n            f\"({self.max_size_bytes} bytes). Evicting to {target_size} bytes\"\n        )\n\n        rows = conn.execute(\n            \"SELECT key, file_path, size_bytes FROM cache ORDER BY last_accessed ASC\"\n        ).fetchall()\n\n        keys_to_delete: list[str] = []\n        for evict_key, file_path_str, size_bytes in rows:\n            if current_size &lt;= target_size:\n                break\n            # Acquire the per-key lock non-blocking: skip keys that are\n            # currently being served by another thread so we do not delete\n            # a file that a concurrent get() is about to return.\n            key_lock = self._get_key_lock(evict_key)\n            if not key_lock.acquire(blocking=False):\n                logger.debug(\n                    f\"Skipping eviction of key '{evict_key}' \"\n                    \"(lock held by another thread)\"\n                )\n                continue\n            try:\n                file_path = Path(file_path_str)\n                if file_path.exists():\n                    file_path.unlink()\n                current_size -= size_bytes\n                keys_to_delete.append(evict_key)\n                logger.debug(f\"Evicted cache entry for key '{evict_key}'\")\n            except OSError as exc:\n                logger.warning(f\"Failed to delete cache file: {exc}\")\n            finally:\n                key_lock.release()\n\n        if keys_to_delete:\n            placeholders = \",\".join(\"?\" * len(keys_to_delete))\n            conn.execute(\n                f\"DELETE FROM cache WHERE key IN ({placeholders})\",\n                keys_to_delete,\n            )\n            conn.commit()\n\n    def _get_cache_size(self) -&gt; int:\n        \"\"\"Return the total size of all cached entries in bytes.\n\n        Returns:\n            Total bytes recorded in the database.\n        \"\"\"\n        conn = self._get_conn()\n        row = conn.execute(\n            \"SELECT COALESCE(SUM(size_bytes), 0) FROM cache\"\n        ).fetchone()\n        return int(row[0])\n\n    def _validate_cache_files(self) -&gt; None:\n        \"\"\"Remove DB entries whose files no longer exist on disk.\"\"\"\n        conn = self._get_conn()\n        rows = conn.execute(\"SELECT key, file_path FROM cache\").fetchall()\n\n        invalid_keys = [key for key, fp in rows if not Path(fp).exists()]\n\n        if not invalid_keys:\n            return\n\n        placeholders = \",\".join(\"?\" * len(invalid_keys))\n        conn.execute(\n            f\"DELETE FROM cache WHERE key IN ({placeholders})\",\n            invalid_keys,\n        )\n        conn.commit()\n        logger.debug(f\"Removed {len(invalid_keys)} invalid cache entries\")\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/image_cache.html#client.ayon_ui_qt.image_cache.ImageCache.get","title":"<code>get(key, file_closure)</code>","text":"<p>Return the cached file path for key, caching it if necessary.</p> <p>Cache hits are served via a fast path that requires no application- level locking; SQLite WAL mode allows concurrent reads across threads and processes.</p> <p>On a cache miss, a per-key lock is acquired so that only one thread calls file_closure for a given key at a time.  After acquiring the lock the database is re-checked: if another thread already populated the entry the result is returned immediately without calling the closure again.</p> <p>file_closure is called outside any database transaction, so a slow I/O operation (e.g. a network download) does not block threads that are requesting different keys.</p> <p>Parameters:</p> Name Type Description Default <code>key</code> <code>str</code> <p>Unique identifier for the cached file.</p> required <code>file_closure</code> <code>Callable</code> <p>Callable returning the path to the source file.           Called only on a cache miss.</p> required <p>Returns:</p> Type Description <code>str</code> <p>Absolute path to the cached file as a string.</p> <p>Raises:</p> Type Description <code>ValueError</code> <p>If key is empty or file_closure returns a path         that does not exist.</p> <code>IOError</code> <p>If the file cannot be copied into the cache.</p> Source code in <code>client/ayon_ui_qt/image_cache.py</code> <pre><code>def get(self, key: str, file_closure: Callable) -&gt; str:\n    \"\"\"Return the cached file path for *key*, caching it if necessary.\n\n    Cache hits are served via a fast path that requires no application-\n    level locking; SQLite WAL mode allows concurrent reads across threads\n    and processes.\n\n    On a cache miss, a per-key lock is acquired so that only one thread\n    calls *file_closure* for a given key at a time.  After acquiring the\n    lock the database is re-checked: if another thread already populated\n    the entry the result is returned immediately without calling the\n    closure again.\n\n    *file_closure* is called **outside** any database transaction, so a\n    slow I/O operation (e.g. a network download) does not block threads\n    that are requesting different keys.\n\n    Args:\n        key: Unique identifier for the cached file.\n        file_closure: Callable returning the path to the source file.\n                      Called only on a cache miss.\n\n    Returns:\n        Absolute path to the cached file as a string.\n\n    Raises:\n        ValueError: If *key* is empty or *file_closure* returns a path\n                    that does not exist.\n        IOError: If the file cannot be copied into the cache.\n    \"\"\"\n    if not key:\n        raise ValueError(\"Cache key cannot be empty\")\n\n    # ------------------------------------------------------------------\n    # ------------------------------------------------------------------\n    # Fast path: pure SELECT \u2014 concurrent reads across threads/processes\n    # proceed without blocking each other in WAL mode.  _touch is a\n    # separate best-effort write; LRU accuracy does not need to be exact.\n    # ------------------------------------------------------------------\n    cached_path = self._lookup(key)\n    if cached_path is not None:\n        self._touch(key)\n        logger.debug(f\"Cache hit for key '{key}'\")\n        return str(cached_path)\n\n    # ------------------------------------------------------------------\n    # Slow path: acquire the per-key lock, then double-check.\n    # Only threads requesting the same key are serialised here; threads\n    # requesting different keys proceed fully in parallel.\n    # ------------------------------------------------------------------\n    with self._get_key_lock(key):\n        # Double-check: another thread may have populated the entry\n        # while we were waiting for the key lock.\n        cached_path = self._lookup(key)\n        if cached_path is not None:\n            self._touch(key)\n            logger.debug(f\"Cache hit for key '{key}' (after key lock)\")\n            return str(cached_path)\n\n        # True miss: call the closure outside any database transaction.\n        logger.debug(f\"Cache miss for key '{key}', calling file_closure\")\n        source_path = Path(file_closure())\n\n        if not source_path.exists():\n            raise ValueError(\n                f\"Loader returned non-existent file: {source_path}\"\n            )\n\n        cache_filename = self._generate_cache_filename(key, source_path)\n        cached_path = self.cache_path / cache_filename\n\n        self._atomic_copy(source_path, cached_path)\n\n        conn = self._get_conn()\n        file_size = cached_path.stat().st_size\n        conn.execute(\n            \"INSERT OR REPLACE INTO cache \"\n            \"(key, file_path, size_bytes, access_count, last_accessed) \"\n            \"VALUES (?, ?, ?, 1, ?)\",\n            (key, str(cached_path), file_size, time.time()),\n        )\n        conn.commit()\n\n    # Eviction runs outside the per-key lock: it can be slow (file I/O +\n    # bulk DB DELETE) and must not block other threads querying this key.\n    self._evict_if_needed()\n\n    logger.debug(f\"Cached file for key '{key}': {cached_path}\")\n    return str(cached_path)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/image_cache.html#client.ayon_ui_qt.image_cache.ImageCache.get_instance","title":"<code>get_instance(cache_path=None, max_size_in_MB=500)</code>  <code>classmethod</code>","text":"<p>Return the singleton cache instance, creating it if needed.</p> <code>cache_path</code> and <code>max_size_in_MB</code> are only used on the first <p>call. Subsequent calls return the same instance regardless of the arguments.</p> <p>Parameters:</p> Name Type Description Default <code>cache_path</code> <code>str | Path | None</code> <p>Directory path for storing cached files.</p> <code>None</code> <code>max_size_in_MB</code> <code>int</code> <p>Maximum cache size in megabytes.</p> <code>500</code> <p>Returns:</p> Type Description <code>ImageCache</code> <p>The singleton ImageCache instance.</p> <p>Raises:</p> Type Description <code>ValueError</code> <p>If max_size_in_MB is not positive.</p> Source code in <code>client/ayon_ui_qt/image_cache.py</code> <pre><code>@classmethod\ndef get_instance(\n    cls,\n    cache_path: str | Path | None = None,\n    max_size_in_MB: int = 500,\n) -&gt; ImageCache:\n    \"\"\"Return the singleton cache instance, creating it if needed.\n\n    NOTE: `cache_path` and `max_size_in_MB` are only used on the first\n          call. Subsequent calls return the same instance regardless of\n          the arguments.\n\n    Args:\n        cache_path: Directory path for storing cached files.\n        max_size_in_MB: Maximum cache size in megabytes.\n\n    Returns:\n        The singleton ImageCache instance.\n\n    Raises:\n        ValueError: If max_size_in_MB is not positive.\n    \"\"\"\n    with cls._lock:\n        if cls._instance is not None:\n            return cls._instance\n        if max_size_in_MB &lt;= 0:\n            raise ValueError(\"max_size_in_MB must be positive\")\n        instance = object.__new__(cls)\n        instance._initialize(cache_path, max_size_in_MB)\n        cls._instance = instance\n        return cls._instance\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/image_cache.html#client.ayon_ui_qt.image_cache.ImageCache.get_path","title":"<code>get_path(key)</code>","text":"<p>Return the cached file path for key if it exists, else None.</p> <p>Updates access metadata when the entry is found.</p> <p>Parameters:</p> Name Type Description Default <code>key</code> <code>str</code> <p>Cache key to look up.</p> required <p>Returns:</p> Type Description <code>str | None</code> <p>Absolute path string to the cached file, or None.</p> Source code in <code>client/ayon_ui_qt/image_cache.py</code> <pre><code>def get_path(self, key: str) -&gt; str | None:\n    \"\"\"Return the cached file path for *key* if it exists, else None.\n\n    Updates access metadata when the entry is found.\n\n    Args:\n        key: Cache key to look up.\n\n    Returns:\n        Absolute path string to the cached file, or None.\n    \"\"\"\n    cached_path = self._lookup(key)\n    if cached_path is None:\n        return None\n    self._touch(key)\n    return str(cached_path)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/image_cache.html#client.ayon_ui_qt.image_cache.ImageCache.has","title":"<code>has(key)</code>","text":"<p>Return True if key is cached and its file exists on disk.</p> <p>Parameters:</p> Name Type Description Default <code>key</code> <code>str</code> <p>Cache key to check.</p> required <p>Returns:</p> Type Description <code>bool</code> <p>True if the key is present and the file exists, else False.</p> Source code in <code>client/ayon_ui_qt/image_cache.py</code> <pre><code>def has(self, key: str) -&gt; bool:\n    \"\"\"Return True if *key* is cached and its file exists on disk.\n\n    Args:\n        key: Cache key to check.\n\n    Returns:\n        True if the key is present and the file exists, else False.\n    \"\"\"\n    return self._lookup(key) is not None\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/image_cache.html#client.ayon_ui_qt.image_cache.ImageCache.set_path","title":"<code>set_path(key, file_path)</code>","text":"<p>Manually set a cache entry for a given key and file path.</p> Source code in <code>client/ayon_ui_qt/image_cache.py</code> <pre><code>def set_path(self, key: str, file_path: str) -&gt; Path:\n    \"\"\"Manually set a cache entry for a given key and file path.\"\"\"\n    with self._access_lock:\n        source_path = Path(file_path)\n        if not source_path.exists():\n            raise ValueError(\n                f\"Provided file does not exist: {source_path}\"\n            )\n\n        cache_filename = self._generate_cache_filename(key, source_path)\n        cached_path = self.cache_path / cache_filename\n\n        try:\n            with open(source_path, \"rb\") as src:\n                with open(cached_path, \"wb\") as dst:\n                    dst.write(src.read())\n        except IOError as e:\n            raise IOError(f\"Failed to set cache file: {e}\") from e\n\n        file_size = cached_path.stat().st_size\n        self._metadata[key] = {\n            \"file_path\": str(cached_path),\n            \"size_bytes\": file_size,\n            \"access_count\": 0,\n            \"last_accessed\": time.time(),\n        }\n        self._evict_if_needed()\n        return cached_path\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/image_cache.html#client.ayon_ui_qt.image_cache.make_activity_cache_key","title":"<code>make_activity_cache_key(project_name, file_id, is_thumbnail=False)</code>","text":"<p>Build the ImageCache key for an activity-attached file.</p> <p>Both the producer (download enqueue) and the consumer (UI refresh) must use this function so that they always agree on the key, and so that entries from different projects never collide.</p> <p>Parameters:</p> Name Type Description Default <code>project_name</code> <code>str</code> <p>AYON project name that owns the file.</p> required <code>file_id</code> <code>str</code> <p>The AYON file identifier.</p> required <code>is_thumbnail</code> <code>bool</code> <p>Whether the key is for the thumbnail variant.</p> <code>False</code> <p>Returns:</p> Type Description <code>str</code> <p>Cache key string in the form</p> <code>str</code> <p><code>act_&lt;project_name&gt;_&lt;file_id&gt;</code> or</p> <code>str</code> <p><code>act_thumb_&lt;project_name&gt;_&lt;file_id&gt;</code>.</p> Source code in <code>client/ayon_ui_qt/image_cache.py</code> <pre><code>def make_activity_cache_key(\n    project_name: str,\n    file_id: str,\n    is_thumbnail: bool = False,\n) -&gt; str:\n    \"\"\"Build the ImageCache key for an activity-attached file.\n\n    Both the producer (download enqueue) and the consumer (UI refresh)\n    must use this function so that they always agree on the key, and so\n    that entries from different projects never collide.\n\n    Args:\n        project_name: AYON project name that owns the file.\n        file_id: The AYON file identifier.\n        is_thumbnail: Whether the key is for the thumbnail variant.\n\n    Returns:\n        Cache key string in the form\n        ``act_&lt;project_name&gt;_&lt;file_id&gt;`` or\n        ``act_thumb_&lt;project_name&gt;_&lt;file_id&gt;``.\n    \"\"\"\n    prefix = \"thumb_\" if is_thumbnail else \"\"\n    return f\"act_{prefix}{project_name}_{file_id}\"\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html","title":"style","text":""},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.AYONStyle","title":"<code>AYONStyle</code>","text":"<p>               Bases: <code>QCommonStyle</code></p> <p>AYON QStyle implementation that replaces QSS styling with native Qt painting. Supports widget variants: surface, tonal, filled, tertiary, text, nav, etc.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>class AYONStyle(QCommonStyle):\n    \"\"\"\n    AYON QStyle implementation that replaces QSS styling with native Qt painting.\n    Supports widget variants: surface, tonal, filled, tertiary, text, nav, etc.\n    \"\"\"\n\n    def __init__(self) -&gt; None:\n        super().__init__()\n        self.model = StyleData()\n        self._in_widget_key = False\n        self.drawers = {}\n        self.sizers = {}\n        self.metrics = {}\n        self.base_classes = {}\n        self.drawer_objs = [\n            TooltipDrawer(self),\n            LabelDrawer(self),  # first because QLabel inherits from QFrame.\n            LineEditDrawer(self),\n            ButtonDrawer(self),\n            CheckboxDrawer(self),\n            ComboBoxDrawer(self),\n            ScrollBarDrawer(self),\n            FrameDrawer(self),\n            TreeViewDrawer(self),\n            TableHeaderDrawer(self),\n            ItemViewItemDrawer(self),\n        ]\n        for obj in self.drawer_objs:\n            self.base_classes.update(obj.base_class)\n            if hasattr(obj, \"register_drawers\"):\n                self.drawers.update(obj.register_drawers())\n            if hasattr(obj, \"register_sizers\"):\n                self.sizers.update(obj.register_sizers())\n            if hasattr(obj, \"register_metrics\"):\n                self.metrics.update(obj.register_metrics())\n\n        # Sort base_classes: most-specific (deepest MRO) first\n        self.base_classes = dict(\n            sorted(\n                self.base_classes.items(),\n                key=lambda kv: len(kv[1].__mro__),\n                reverse=True,\n            )\n        )\n\n    def widget_key(self, w: QWidget | None) -&gt; str:\n        if self._in_widget_key or w is None or not isValid(w):\n            return \"\"\n\n        if w:\n            # Handle item view widgets - check parent for delegate and exclude\n            # ComboBoxItemDelegate\n            if hasattr(w, \"itemDelegate\") and not isinstance(\n                w, (QComboBox, QHeaderView)\n            ):\n                # Calling itemDelegate() is not a simple getter - it can\n                # trigger Qt's internal operations that call back into the\n                # custom style methods (subElementRect, drawPrimitive,\n                # pixelMetric, etc.), each of which calls widget_key() again,\n                # creating infinite recursion.\n                self._in_widget_key = True\n                try:\n                    delegate = w.itemDelegate()\n                    cbd = delegate and isinstance(\n                        delegate, ComboBoxItemDelegate\n                    )\n                    tvd = delegate and isinstance(\n                        delegate, (TreeViewItemDelegate, TableItemDelegate)\n                    )\n                    if not cbd and not tvd:\n                        return \"QStyledItemDelegate\"\n                finally:\n                    self._in_widget_key = False\n            for name, wtype in self.base_classes.items():\n                if issubclass(type(w), wtype):\n                    if w.objectName() == \"qtooltip_label\":\n                        return \"QToolTip\"\n                    if isinstance(w, QLabel):\n                        p = w.parent()\n                        # NOTE: Qt does not use QToolTip but a QLabel (a private\n                        # QLabelTip class) !!\n                        # if the parent is a widget and it doesn't have a\n                        # layout, it could be a tooltip.\n                        # Sometimes, objectName() == \"qtooltip_label\" but the\n                        # object name is set when the rect requests are made.\n                        if p and isinstance(p, QWidget) and not p.layout():\n                            return \"QToolTip\"\n                    return name\n        return \"\"\n\n    def polish(self, widget) -&gt; None:\n        \"\"\"Polish widgets to enable hover tracking and custom palette.\"\"\"\n        if isinstance(widget, QWidget):\n            super().polish(widget)\n            # TODO(plp): move to QStyle:polishPalette(QPalette)\n            widget.setPalette(self.model.base_palette)\n            widget.setFont(self.model.base_font)\n\n            # Enable mouse tracking for buttons to receive hover events\n            widget.setAttribute(Qt.WidgetAttribute.WA_Hover, True)\n            widget.setMouseTracking(True)\n\n            if isinstance(widget, QComboBox):\n                widget.setMinimumContentsLength(1)\n                widget.setItemDelegate(\n                    ComboBoxItemDelegate(parent=widget, style_model=self.model)\n                )\n                widget.setSizeAdjustPolicy(\n                    QComboBox.SizeAdjustPolicy.AdjustToContents\n                )\n            elif isinstance(widget, QLabel):\n                # rounded corner no background.\n                widget.setAttribute(\n                    Qt.WidgetAttribute.WA_TranslucentBackground, True\n                )\n\n        # elif isinstance(widget, QPalette):\n        #     print(\"YES: QPalette\")\n\n        elif isinstance(widget, QApplication):\n            super().polish(widget)\n        else:\n            super().polish(widget)\n\n    def drawControl(\n        self,\n        element: QStyle.ControlElement,\n        option: QStyleOption,\n        painter: QPainter,\n        w: QWidget | None = None,\n    ) -&gt; None:\n        \"\"\"Draw control elements (buttons, labels, etc.).\"\"\"\n        key = enum_to_str(QStyle.ControlElement, element, self.widget_key(w))\n\n        if type(w).__name__ in W_T:\n            log.info(\"  &gt;&gt;  drawControl %s %s\", type(w), key)\n\n        try:\n            draw_ce_calls = self.drawers[key]\n        except KeyError:\n            # no custom drawer fallback\n            super().drawControl(element, option, painter, w)\n            return\n        else:\n            if isinstance(draw_ce_calls, list):\n                for draw_ce in draw_ce_calls:\n                    draw_ce(option, painter, w)\n            elif callable(draw_ce_calls):\n                draw_ce_calls(option, painter, w)\n            return\n\n    def drawComplexControl(\n        self,\n        cc: QStyle.ComplexControl,\n        opt: QtWidgets.QStyleOptionComplex,\n        p: QPainter,\n        w: QWidget | None = None,\n    ) -&gt; None:\n        key = enum_to_str(QStyle.ComplexControl, cc, self.widget_key(w))\n        if type(w).__name__ in W_T:\n            log.info(\"  &gt;&gt;  drawComplexControl %s %s\", type(w), key)\n\n        try:\n            draw_cc = self.drawers[key]\n        except KeyError:\n            # no custom drawer fallback\n            return super().drawComplexControl(cc, opt, p, w)\n\n        draw_cc(opt, p, w)\n\n    def drawPrimitive(\n        self,\n        element: QStyle.PrimitiveElement,\n        option: QStyleOption,\n        painter: QPainter,\n        w: QWidget | None = None,\n    ) -&gt; None:\n        \"\"\"Draw primitive elements.\"\"\"\n\n        key = enum_to_str(QStyle.PrimitiveElement, element, self.widget_key(w))\n        if type(w).__name__ in W_T:\n            log.info(\"  &gt;&gt;  drawPrimitive %s %s\", type(w), key)\n\n        try:\n            draw_prim = self.drawers[key]\n        except KeyError:\n            # Fall back to parent implementation\n            # print(f\"no match for {k}\")\n            super().drawPrimitive(element, option, painter, w)\n            return\n\n        draw_prim(option, painter, w)\n\n    def subElementRect(\n        self,\n        element: QStyle.SubElement,\n        option: QStyleOption,\n        widget: QWidget | None = None,\n    ) -&gt; QRect:\n        \"\"\"Calculate rectangles for sub-elements.\"\"\"\n        key = enum_to_str(QStyle.SubElement, element, self.widget_key(widget))\n\n        if isinstance(widget, QLabel):\n            log.debug(\"%s %s\", type(widget).__name__, key)\n\n        try:\n            sizer = self.sizers[key]\n        except KeyError:\n            # Fall back to parent implementation\n            # Catch RuntimeError in case widget's C++ object was already deleted\n            try:\n                if widget is not None:\n                    return super().subElementRect(element, option, widget)\n                else:\n                    return super().subElementRect(element, option)\n            except RuntimeError:\n                # Widget was deleted, call without it\n                return super().subElementRect(element, option)\n\n        return sizer(element, option, widget)\n\n    def subControlRect(\n        self,\n        cc: QStyle.ComplexControl,\n        opt: QtWidgets.QStyleOptionComplex,\n        sc: QStyle.SubControl,\n        w: QWidget | None = None,\n    ) -&gt; QRect:\n        key = enum_to_str(QStyle.ComplexControl, cc, self.widget_key(w))\n\n        if isinstance(w, QLabel):\n            log.debug(\"%s %s\", type(w).__name__, key)\n\n        try:\n            sizer = self.sizers[key]\n        except KeyError:\n            # Fall back to parent implementation\n            return super().subControlRect(cc, opt, sc, w)\n\n        try:\n            return sizer(cc, opt, sc, w)\n        except ValueError:\n            return super().subControlRect(cc, opt, sc, w)\n\n    def pixelMetric(\n        self,\n        metric: QStyle.PixelMetric,\n        opt: QStyleOption | None = None,\n        widget: QWidget | None = None,\n    ) -&gt; int:\n        \"\"\"Return pixel measurements for various style metrics.\"\"\"\n        # print(f\"PM: {metric}\")\n        key = enum_to_str(QStyle.PixelMetric, metric, self.widget_key(widget))\n\n        if isinstance(widget, QLabel):\n            log.debug(\"%s %s\", type(widget), key)\n\n        try:\n            metric_func = self.metrics[key]\n        except KeyError:\n            # Fall back to parent implementation\n            return super().pixelMetric(metric, opt, widget)\n\n        return metric_func(metric, opt, widget)\n\n    def styleHint(\n        self,\n        hint: QStyle.StyleHint,\n        opt: QStyleOption | None = None,\n        w: QWidget | None = None,\n        shret: QtWidgets.QStyleHintReturn | None = None,\n    ) -&gt; int:\n        \"\"\"Return style hints for behavior configuration.\"\"\"\n\n        if hint == QStyle.StyleHint.SH_Button_FocusPolicy:\n            return Qt.FocusPolicy.StrongFocus\n        elif hint == QStyle.StyleHint.SH_RequestSoftwareInputPanel:\n            return 0\n        elif hint == QStyle.StyleHint.SH_ComboBox_PopupFrameStyle:\n            return QFrame.Shape.NoFrame\n\n        # Fall back to parent implementation\n        return super().styleHint(hint, opt, w, shret)\n\n    def sizeFromContents(\n        self,\n        contents_type: QStyle.ContentsType,\n        option: QStyleOption | None,\n        contents_size: QtCore.QSize,\n        widget: QWidget | None = None,\n    ) -&gt; QtCore.QSize:\n        \"\"\"Calculate minimum size requirements for widgets based on their content.\"\"\"\n        # print(f\"CT: {contents_type}\")\n        key = enum_to_str(\n            QStyle.ContentsType, contents_type, self.widget_key(widget)\n        )\n\n        if isinstance(widget, QLabel):\n            log.debug(\"%s\", widget)\n\n        try:\n            sizer = self.sizers[key]\n        except KeyError:\n            if option:\n                return super().sizeFromContents(\n                    contents_type, option, contents_size, widget\n                )\n            else:\n                # Create a default size if no option is provided\n                return QtCore.QSize(100, 32)  # reasonable default\n        else:\n            return sizer(contents_type, option, contents_size, widget)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.AYONStyle.drawControl","title":"<code>drawControl(element, option, painter, w=None)</code>","text":"<p>Draw control elements (buttons, labels, etc.).</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def drawControl(\n    self,\n    element: QStyle.ControlElement,\n    option: QStyleOption,\n    painter: QPainter,\n    w: QWidget | None = None,\n) -&gt; None:\n    \"\"\"Draw control elements (buttons, labels, etc.).\"\"\"\n    key = enum_to_str(QStyle.ControlElement, element, self.widget_key(w))\n\n    if type(w).__name__ in W_T:\n        log.info(\"  &gt;&gt;  drawControl %s %s\", type(w), key)\n\n    try:\n        draw_ce_calls = self.drawers[key]\n    except KeyError:\n        # no custom drawer fallback\n        super().drawControl(element, option, painter, w)\n        return\n    else:\n        if isinstance(draw_ce_calls, list):\n            for draw_ce in draw_ce_calls:\n                draw_ce(option, painter, w)\n        elif callable(draw_ce_calls):\n            draw_ce_calls(option, painter, w)\n        return\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.AYONStyle.drawPrimitive","title":"<code>drawPrimitive(element, option, painter, w=None)</code>","text":"<p>Draw primitive elements.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def drawPrimitive(\n    self,\n    element: QStyle.PrimitiveElement,\n    option: QStyleOption,\n    painter: QPainter,\n    w: QWidget | None = None,\n) -&gt; None:\n    \"\"\"Draw primitive elements.\"\"\"\n\n    key = enum_to_str(QStyle.PrimitiveElement, element, self.widget_key(w))\n    if type(w).__name__ in W_T:\n        log.info(\"  &gt;&gt;  drawPrimitive %s %s\", type(w), key)\n\n    try:\n        draw_prim = self.drawers[key]\n    except KeyError:\n        # Fall back to parent implementation\n        # print(f\"no match for {k}\")\n        super().drawPrimitive(element, option, painter, w)\n        return\n\n    draw_prim(option, painter, w)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.AYONStyle.pixelMetric","title":"<code>pixelMetric(metric, opt=None, widget=None)</code>","text":"<p>Return pixel measurements for various style metrics.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def pixelMetric(\n    self,\n    metric: QStyle.PixelMetric,\n    opt: QStyleOption | None = None,\n    widget: QWidget | None = None,\n) -&gt; int:\n    \"\"\"Return pixel measurements for various style metrics.\"\"\"\n    # print(f\"PM: {metric}\")\n    key = enum_to_str(QStyle.PixelMetric, metric, self.widget_key(widget))\n\n    if isinstance(widget, QLabel):\n        log.debug(\"%s %s\", type(widget), key)\n\n    try:\n        metric_func = self.metrics[key]\n    except KeyError:\n        # Fall back to parent implementation\n        return super().pixelMetric(metric, opt, widget)\n\n    return metric_func(metric, opt, widget)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.AYONStyle.polish","title":"<code>polish(widget)</code>","text":"<p>Polish widgets to enable hover tracking and custom palette.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def polish(self, widget) -&gt; None:\n    \"\"\"Polish widgets to enable hover tracking and custom palette.\"\"\"\n    if isinstance(widget, QWidget):\n        super().polish(widget)\n        # TODO(plp): move to QStyle:polishPalette(QPalette)\n        widget.setPalette(self.model.base_palette)\n        widget.setFont(self.model.base_font)\n\n        # Enable mouse tracking for buttons to receive hover events\n        widget.setAttribute(Qt.WidgetAttribute.WA_Hover, True)\n        widget.setMouseTracking(True)\n\n        if isinstance(widget, QComboBox):\n            widget.setMinimumContentsLength(1)\n            widget.setItemDelegate(\n                ComboBoxItemDelegate(parent=widget, style_model=self.model)\n            )\n            widget.setSizeAdjustPolicy(\n                QComboBox.SizeAdjustPolicy.AdjustToContents\n            )\n        elif isinstance(widget, QLabel):\n            # rounded corner no background.\n            widget.setAttribute(\n                Qt.WidgetAttribute.WA_TranslucentBackground, True\n            )\n\n    # elif isinstance(widget, QPalette):\n    #     print(\"YES: QPalette\")\n\n    elif isinstance(widget, QApplication):\n        super().polish(widget)\n    else:\n        super().polish(widget)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.AYONStyle.sizeFromContents","title":"<code>sizeFromContents(contents_type, option, contents_size, widget=None)</code>","text":"<p>Calculate minimum size requirements for widgets based on their content.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def sizeFromContents(\n    self,\n    contents_type: QStyle.ContentsType,\n    option: QStyleOption | None,\n    contents_size: QtCore.QSize,\n    widget: QWidget | None = None,\n) -&gt; QtCore.QSize:\n    \"\"\"Calculate minimum size requirements for widgets based on their content.\"\"\"\n    # print(f\"CT: {contents_type}\")\n    key = enum_to_str(\n        QStyle.ContentsType, contents_type, self.widget_key(widget)\n    )\n\n    if isinstance(widget, QLabel):\n        log.debug(\"%s\", widget)\n\n    try:\n        sizer = self.sizers[key]\n    except KeyError:\n        if option:\n            return super().sizeFromContents(\n                contents_type, option, contents_size, widget\n            )\n        else:\n            # Create a default size if no option is provided\n            return QtCore.QSize(100, 32)  # reasonable default\n    else:\n        return sizer(contents_type, option, contents_size, widget)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.AYONStyle.styleHint","title":"<code>styleHint(hint, opt=None, w=None, shret=None)</code>","text":"<p>Return style hints for behavior configuration.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def styleHint(\n    self,\n    hint: QStyle.StyleHint,\n    opt: QStyleOption | None = None,\n    w: QWidget | None = None,\n    shret: QtWidgets.QStyleHintReturn | None = None,\n) -&gt; int:\n    \"\"\"Return style hints for behavior configuration.\"\"\"\n\n    if hint == QStyle.StyleHint.SH_Button_FocusPolicy:\n        return Qt.FocusPolicy.StrongFocus\n    elif hint == QStyle.StyleHint.SH_RequestSoftwareInputPanel:\n        return 0\n    elif hint == QStyle.StyleHint.SH_ComboBox_PopupFrameStyle:\n        return QFrame.Shape.NoFrame\n\n    # Fall back to parent implementation\n    return super().styleHint(hint, opt, w, shret)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.AYONStyle.subElementRect","title":"<code>subElementRect(element, option, widget=None)</code>","text":"<p>Calculate rectangles for sub-elements.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def subElementRect(\n    self,\n    element: QStyle.SubElement,\n    option: QStyleOption,\n    widget: QWidget | None = None,\n) -&gt; QRect:\n    \"\"\"Calculate rectangles for sub-elements.\"\"\"\n    key = enum_to_str(QStyle.SubElement, element, self.widget_key(widget))\n\n    if isinstance(widget, QLabel):\n        log.debug(\"%s %s\", type(widget).__name__, key)\n\n    try:\n        sizer = self.sizers[key]\n    except KeyError:\n        # Fall back to parent implementation\n        # Catch RuntimeError in case widget's C++ object was already deleted\n        try:\n            if widget is not None:\n                return super().subElementRect(element, option, widget)\n            else:\n                return super().subElementRect(element, option)\n        except RuntimeError:\n            # Widget was deleted, call without it\n            return super().subElementRect(element, option)\n\n    return sizer(element, option, widget)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ButtonDrawer","title":"<code>ButtonDrawer</code>","text":"Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>class ButtonDrawer:\n    def __init__(self, style_inst: AYONStyle) -&gt; None:\n        self.style_inst = style_inst\n        self.model = style_inst.model\n\n    @property\n    def base_class(self):\n        return {\"QPushButton\": QPushButton}\n\n    def register_drawers(self):\n        return {\n            enum_to_str(\n                QStyle.ControlElement,\n                QStyle.ControlElement.CE_PushButton,\n                \"QPushButton\",\n            ): [\n                partial(\n                    self.style_inst.drawControl,\n                    QStyle.ControlElement.CE_PushButtonBevel,\n                ),\n                partial(\n                    self.style_inst.drawControl,\n                    QStyle.ControlElement.CE_PushButtonLabel,\n                ),\n            ],\n            enum_to_str(\n                QStyle.ControlElement,\n                QStyle.ControlElement.CE_PushButtonBevel,\n                \"QPushButton\",\n            ): self.draw_push_button_bevel,\n            enum_to_str(\n                QStyle.ControlElement,\n                QStyle.ControlElement.CE_PushButtonLabel,\n                \"QPushButton\",\n            ): self.draw_push_button_label,\n        }\n\n    def register_sizers(self):\n        return {\n            enum_to_str(\n                QStyle.ContentsType,\n                QStyle.ContentsType.CT_PushButton,\n                \"QPushButton\",\n            ): self.calculate_push_button_size,\n            enum_to_str(\n                QStyle.SubElement,\n                QStyle.SubElement.SE_PushButtonContents,\n                \"QPushButton\",\n            ): self.sub_element_rect,\n            enum_to_str(\n                QStyle.SubElement,\n                QStyle.SubElement.SE_PushButtonFocusRect,\n                \"QPushButton\",\n            ): self.sub_element_rect,\n        }\n\n    def register_metrics(self):\n        return {\n            enum_to_str(\n                QStyle.PixelMetric,\n                QStyle.PixelMetric.PM_ButtonMargin,\n                \"QPushButton\",\n            ): self.get_metric,\n            enum_to_str(\n                QStyle.PixelMetric,\n                QStyle.PixelMetric.PM_DefaultFrameWidth,\n                \"QPushButton\",\n            ): self.get_metric,\n            enum_to_str(\n                QStyle.PixelMetric,\n                QStyle.PixelMetric.PM_ButtonDefaultIndicator,\n                \"QPushButton\",\n            ): self.get_metric,\n            enum_to_str(\n                QStyle.PixelMetric,\n                QStyle.PixelMetric.PM_FocusFrameVMargin,\n                \"QPushButton\",\n            ): self.get_metric,\n            enum_to_str(\n                QStyle.PixelMetric,\n                QStyle.PixelMetric.PM_FocusFrameHMargin,\n                \"QPushButton\",\n            ): self.get_metric,\n        }\n\n    def get_metric(\n        self,\n        metric: QStyle.PixelMetric,\n        opt: QStyleOption | None = None,\n        widget: QWidget | None = None,\n    ):\n        if metric == QStyle.PixelMetric.PM_ButtonMargin:\n            return 6\n        elif metric == QStyle.PixelMetric.PM_DefaultFrameWidth:\n            return 0\n        elif metric == QStyle.PixelMetric.PM_ButtonDefaultIndicator:\n            return 0\n        elif metric == QStyle.PixelMetric.PM_FocusFrameVMargin:\n            return 2\n        elif metric == QStyle.PixelMetric.PM_FocusFrameHMargin:\n            return 2\n\n    def get_button_variant(self, widget: QWidget) -&gt; str:\n        \"\"\"Extract button variant from widget properties.\"\"\"\n        if widget is None:\n            return \"surface\"\n        return getattr(widget, \"_variant_str\", \"surface\")\n\n    def get_button_has_icon(self, widget: QWidget) -&gt; bool:\n        \"\"\"Check if button has an icon.\"\"\"\n        if widget is None:\n            return False\n\n        # Method 1: Try has_icon property\n        if hasattr(widget, \"has_icon\"):\n            return widget.has_icon  # type: ignore\n\n        # Method 2: Try Qt property\n        has_icon_prop = widget.property(\"has_icon\")\n        if has_icon_prop is not None:\n            return bool(has_icon_prop)\n\n        # Method 3: Check the actual icon\n        return bool(widget.icon() and not widget.icon().isNull())  # type: ignore\n\n    def get_button_style(\n        self, widget: QWidget, state: QStyle.StateFlag\n    ) -&gt; tuple[dict, str]:\n        \"\"\"Get the appropriate style dictionary for the widget's variant and\n        state.\"\"\"\n        variant = self.get_button_variant(widget)\n\n        wstate = \"base\"\n        if not (state &amp; QStyle.StateFlag.State_Enabled):\n            wstate = \"disabled\"\n        elif state &amp; QStyle.StateFlag.State_Sunken:\n            wstate = \"pressed\"\n        elif state &amp; QStyle.StateFlag.State_MouseOver and not (\n            state &amp; QStyle.StateFlag.State_On\n        ):\n            wstate = \"hover\"\n        elif state &amp; QStyle.StateFlag.State_On:\n            wstate = \"checked\"\n\n        style = self.model.get_style(\"QPushButton\", variant, wstate)\n\n        return style, wstate\n\n    def draw_push_button_bevel(\n        self,\n        option: QStyleOption,\n        painter: QPainter,\n        widget: QWidget | None,\n    ) -&gt; None:\n        \"\"\"Draw the button background and frame with hover detection.\"\"\"\n        if not isinstance(option, QStyleOptionButton) or widget is None:\n            return\n\n        style, _ = self.get_button_style(widget, option.state)\n        rect = option.rect\n\n        painter.save()\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n        # Draw button background with hover awareness\n        bg_color = style[\"background-color\"]\n        painter.setOpacity(style.get(\"opacity\", 1.0))\n\n        painter.setBrush(QBrush(bg_color))\n        painter.setPen(Qt.PenStyle.NoPen)\n        border_radius = style.get(\"border-radius\", 0)\n\n        draw_icon_as_background = style.get(\"icon-as-background\", False)\n        clip_icon_to_radius = style.get(\"clip-icon-to-radius\", False)\n\n        if draw_icon_as_background:\n            # draw the icon clipped by the same rounded rect\n            painter.save()\n            if clip_icon_to_radius:\n                clip_path = QPainterPath()\n                clip_path.addRoundedRect(rect, border_radius, border_radius)\n                painter.setClipPath(clip_path)\n\n            mode = QtGui.QIcon.Mode.Normal\n            painter.drawRoundedRect(rect, border_radius, border_radius)\n            option.icon.paint(\n                painter,\n                rect,\n                Qt.AlignmentFlag.AlignCenter,\n                mode,\n            )\n\n            if clip_icon_to_radius:\n                painter.setClipping(False)\n\n            pen = QPen(QColor(style.get(\"border-color\")))\n            pen.setWidth(int(style.get(\"border-width\", 0)))\n            painter.setPen(pen)\n            painter.setBrush(Qt.BrushStyle.NoBrush)\n            painter.drawRoundedRect(rect, border_radius, border_radius)\n            painter.restore()\n        else:\n            painter.drawRoundedRect(rect, border_radius, border_radius)\n\n        # Draw focus outline if needed\n        if (\n            option.state &amp; QStyle.StateFlag.State_HasFocus\n            and option.state  # type: ignore\n            &amp; QStyle.StateFlag.State_KeyboardFocusChange\n        ):\n            focus_color = style[\"focus-outline-color\"]\n            pen = QPen(\n                QColor(focus_color), style.get(\"focus-outline-width\", 0)\n            )\n            painter.setPen(pen)\n            painter.setBrush(Qt.BrushStyle.NoBrush)\n            focus_rect = rect.adjusted(1, 1, -1, -1)\n            painter.drawRoundedRect(\n                focus_rect, border_radius + 1, border_radius + 1\n            )\n\n        painter.restore()\n\n    def draw_push_button_label(\n        self,\n        option: QStyleOption,\n        painter: QPainter,\n        widget: QWidget | None,\n    ) -&gt; None:\n        \"\"\"Draw the button text and icon.\"\"\"\n        if not isinstance(option, QStyleOptionButton) or widget is None:\n            return\n\n        style, wstate = self.get_button_style(widget, option.state)  # type: ignore\n        variant = self.get_button_variant(widget)\n\n        # Set up text color\n        text_color = self.model.get_color(\"color\", style, widget)\n        if not (option.state &amp; QStyle.StateFlag.State_Enabled):  # type: ignore\n            # Apply some opacity to disabled text\n            text_color.setAlpha(int(255 * 0.5))\n\n        painter.save()\n        painter.setPen(text_color)\n\n        # Set up font\n        painter.setFont(_style_font(style, widget))\n\n        # Get content rectangle\n        content_rect = self.style_inst.subElementRect(\n            QStyle.SubElement.SE_PushButtonContents, option, widget\n        )\n        # _debug_rect(painter, \"#ff5555\", content_rect)\n\n        # Optional per-widget alignment override (None \u2192 default centered layout)\n        label_alignment = getattr(widget, \"_label_alignment\", None)\n\n        # Draw icon if present\n        if option.icon:  # type: ignore\n            # icon_color = QColor(getattr(widget, \"_icon_color\", text_color))\n            if option.text and not style.get(\"ignore-text\", False):  # type: ignore\n                icon_size = option.iconSize  # type: ignore\n                icon_w = icon_size.width()\n                icon_h = icon_size.height()\n                _gap = 4\n\n                # Draw icon with text color inheritance\n                mode = QtGui.QIcon.Mode.Normal\n                if not (\n                    option.state &amp; QStyle.StateFlag.State_Enabled  # type: ignore\n                ):\n                    mode = QtGui.QIcon.Mode.Disabled\n                elif option.state &amp; QStyle.StateFlag.State_Sunken:  # type: ignore\n                    mode = QtGui.QIcon.Mode.Active\n\n                if label_alignment is not None:\n                    # Group layout: icon + text move together as a unit\n                    h_align = (\n                        label_alignment &amp; Qt.AlignmentFlag.AlignHorizontal_Mask\n                    )\n                    text_w = painter.fontMetrics().horizontalAdvance(\n                        option.text  # type: ignore\n                    )\n                    group_w = icon_w + _gap + text_w\n                    if h_align == Qt.AlignmentFlag.AlignLeft:\n                        group_x = content_rect.left()\n                    elif h_align == Qt.AlignmentFlag.AlignRight:\n                        group_x = content_rect.right() - group_w\n                    else:\n                        group_x = (\n                            content_rect.left()\n                            + (content_rect.width() - group_w) // 2\n                        )\n                    icon_rect = QRect(\n                        group_x,\n                        content_rect.center().y() - icon_h // 2,\n                        icon_w,\n                        icon_h,\n                    )\n                    text_rect = QRect(\n                        icon_rect.right() + _gap,\n                        content_rect.top(),\n                        text_w,\n                        content_rect.height(),\n                    )\n                    option.icon.paint(  # type: ignore\n                        painter,\n                        icon_rect,\n                        Qt.AlignmentFlag.AlignCenter,\n                        mode,\n                    )\n                    painter.drawText(\n                        text_rect,\n                        Qt.AlignmentFlag.AlignLeft\n                        | Qt.AlignmentFlag.AlignVCenter,\n                        option.text,  # type: ignore\n                    )\n                else:\n                    # Icon + text: place icon on the left (default centered layout)\n                    icon_rect = QRect(content_rect)\n                    icon_rect.setSize(icon_size)\n                    icon_rect.moveCenter(\n                        QtCore.QPoint(\n                            content_rect.left() + style[\"icon-padding\"][0],\n                            content_rect.center().y(),\n                        )\n                    )\n                    option.icon.paint(  # type: ignore\n                        painter,\n                        icon_rect,\n                        Qt.AlignmentFlag.AlignCenter,\n                        mode,\n                    )\n                    # Adjust text rectangle\n                    text_rect = QRect(content_rect)\n                    text_rect.setLeft(icon_rect.right() + _gap)\n                    # Draw text\n                    painter.drawText(\n                        text_rect,\n                        Qt.AlignmentFlag.AlignCenter,\n                        option.text,  # type: ignore\n                    )\n            elif variant != \"thumbnail\":\n                # Icon only\n                mode = QtGui.QIcon.Mode.Normal\n                if not (\n                    option.state &amp; QStyle.StateFlag.State_Enabled  # type: ignore\n                ):\n                    mode = QtGui.QIcon.Mode.Disabled\n                elif option.state &amp; QStyle.StateFlag.State_Sunken:  # type: ignore\n                    mode = QtGui.QIcon.Mode.Active\n\n                checkable = widget.isCheckable() if widget else False\n                # checked = widget.isChecked() if widget else False\n\n                icon_state = (\n                    (\n                        QtGui.QIcon.State.On\n                        if wstate == \"hover\"\n                        else QtGui.QIcon.State.Off\n                    )\n                    if not checkable\n                    else (\n                        QtGui.QIcon.State.On\n                        if option.state &amp; QStyle.StateFlag.State_On\n                        else QtGui.QIcon.State.Off\n                    )\n                )\n\n                _icon_align = (\n                    (label_alignment &amp; Qt.AlignmentFlag.AlignHorizontal_Mask)\n                    | Qt.AlignmentFlag.AlignVCenter\n                    if label_alignment is not None\n                    else Qt.AlignmentFlag.AlignCenter\n                )\n                option.icon.paint(  # type: ignore\n                    painter,\n                    content_rect,\n                    _icon_align,\n                    mode,\n                    icon_state,\n                )\n        else:\n            # Text only\n            if option.text and not style.get(\"ignore-text\", False):  # type: ignore\n                _text_align = (\n                    (label_alignment &amp; Qt.AlignmentFlag.AlignHorizontal_Mask)\n                    | Qt.AlignmentFlag.AlignVCenter\n                    if label_alignment is not None\n                    else Qt.AlignmentFlag.AlignCenter\n                )\n                painter.drawText(\n                    content_rect,\n                    _text_align,\n                    option.text,  # type: ignore\n                )\n\n        painter.restore()\n\n    def calculate_push_button_size(\n        self,\n        contents_type: QStyle.ContentsType,\n        option: QStyleOption | None,\n        contents_size: QtCore.QSize,\n        widget: QWidget | None,\n    ) -&gt; QtCore.QSize:\n        \"\"\"Calculate minimum size for push buttons with text, icons,\n        and proper padding.\"\"\"\n\n        if not isinstance(option, QStyleOptionButton):\n            # Fallback to parent if we don't have proper option data\n            if option is not None:\n                return super(AYONStyle, self.style_inst).sizeFromContents(\n                    contents_type,\n                    option,\n                    contents_size,\n                    widget,\n                )\n            else:\n                # Return reasonable default for button if no option\n                return QtCore.QSize(100, 30)\n\n        # Set up font for text measurement\n        style, _ = self.get_button_style(widget, option.state)  # type: ignore\n        font = _style_font(style, widget)\n\n        # Create font metrics for accurate text measurement\n        font_metrics = QtGui.QFontMetrics(font)\n\n        # Determine if button has icon\n        has_icon = (\n            self.get_button_has_icon(widget)\n            if widget\n            else not option.icon.isNull()  # type: ignore\n        )\n        has_icon = not option.icon.isNull()\n\n        # Determine appropriate padding\n        if has_icon and not option.text:  # type: ignore\n            # Icon-only button\n            padding = style[\"icon-padding\"]\n        else:\n            # Text button or icon+text button\n            padding = style[\"text-padding\"]\n\n        # Calculate text dimensions\n        text_width = 0\n        text_height = 0\n        if option.text and not style.get(\"ignore-text\", False):  # type: ignore\n            text_rect = font_metrics.boundingRect(option.text)  # type: ignore\n            text_width = text_rect.width()\n            text_height = text_rect.height()\n\n        # Calculate icon dimensions\n        icon_width = 0\n        icon_height = 0\n        if has_icon:\n            icon_size = option.iconSize  # type: ignore\n            icon_width = icon_size.width()\n            icon_height = icon_size.height()\n\n        # Calculate content dimensions\n        content_width = 0\n        content_height = 0\n\n        if has_icon and option.text:  # type: ignore\n            # Icon + text: icon on left, 4px spacing, then text\n            content_width = icon_width + 4 + text_width\n            content_height = max(icon_height, text_height)\n        elif has_icon:\n            # Icon only\n            content_width = icon_width\n            content_height = icon_height\n        elif option.text:  # type: ignore\n            # Text only\n            content_width = text_width\n            content_height = text_height\n\n        # Add padding (vertical, horizontal)\n        total_width = content_width + (\n            2 * padding[1]\n        )  # horizontal padding on both sides\n        total_height = content_height + (\n            2 * padding[0]\n        )  # vertical padding on top and bottom\n\n        # Ensure minimum button size (reasonable minimums)\n        min_width = 16\n        min_height = 16\n\n        total_width = max(total_width, min_width)\n        total_height = max(total_height, min_height)\n\n        return QtCore.QSize(total_width, total_height)\n\n    def sub_element_rect(\n        self,\n        element: QStyle.SubElement,\n        option: QStyleOption,\n        widget: QWidget,\n    ):\n        if element == QStyle.SubElement.SE_PushButtonContents:\n            style = self.model.get_style(\n                \"QPushButton\", self.get_button_variant(widget)\n            )\n            if option.icon:\n                padding = (\n                    style[\"icon-padding\"]\n                    if not widget.text()  # type: ignore\n                    else style[\"text-padding\"]\n                )\n            else:\n                padding = style[\"text-padding\"]\n\n            return option.rect.adjusted(  # type: ignore\n                padding[1], padding[0], -padding[1], -padding[0]\n            )\n\n        elif element == QStyle.SubElement.SE_PushButtonFocusRect:\n            return option.rect.adjusted(-2, -2, 2, 2)  # type: ignore\n\n        raise ValueError(f\"Nothing returned ! -&gt; {element}\")\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ButtonDrawer.calculate_push_button_size","title":"<code>calculate_push_button_size(contents_type, option, contents_size, widget)</code>","text":"<p>Calculate minimum size for push buttons with text, icons, and proper padding.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def calculate_push_button_size(\n    self,\n    contents_type: QStyle.ContentsType,\n    option: QStyleOption | None,\n    contents_size: QtCore.QSize,\n    widget: QWidget | None,\n) -&gt; QtCore.QSize:\n    \"\"\"Calculate minimum size for push buttons with text, icons,\n    and proper padding.\"\"\"\n\n    if not isinstance(option, QStyleOptionButton):\n        # Fallback to parent if we don't have proper option data\n        if option is not None:\n            return super(AYONStyle, self.style_inst).sizeFromContents(\n                contents_type,\n                option,\n                contents_size,\n                widget,\n            )\n        else:\n            # Return reasonable default for button if no option\n            return QtCore.QSize(100, 30)\n\n    # Set up font for text measurement\n    style, _ = self.get_button_style(widget, option.state)  # type: ignore\n    font = _style_font(style, widget)\n\n    # Create font metrics for accurate text measurement\n    font_metrics = QtGui.QFontMetrics(font)\n\n    # Determine if button has icon\n    has_icon = (\n        self.get_button_has_icon(widget)\n        if widget\n        else not option.icon.isNull()  # type: ignore\n    )\n    has_icon = not option.icon.isNull()\n\n    # Determine appropriate padding\n    if has_icon and not option.text:  # type: ignore\n        # Icon-only button\n        padding = style[\"icon-padding\"]\n    else:\n        # Text button or icon+text button\n        padding = style[\"text-padding\"]\n\n    # Calculate text dimensions\n    text_width = 0\n    text_height = 0\n    if option.text and not style.get(\"ignore-text\", False):  # type: ignore\n        text_rect = font_metrics.boundingRect(option.text)  # type: ignore\n        text_width = text_rect.width()\n        text_height = text_rect.height()\n\n    # Calculate icon dimensions\n    icon_width = 0\n    icon_height = 0\n    if has_icon:\n        icon_size = option.iconSize  # type: ignore\n        icon_width = icon_size.width()\n        icon_height = icon_size.height()\n\n    # Calculate content dimensions\n    content_width = 0\n    content_height = 0\n\n    if has_icon and option.text:  # type: ignore\n        # Icon + text: icon on left, 4px spacing, then text\n        content_width = icon_width + 4 + text_width\n        content_height = max(icon_height, text_height)\n    elif has_icon:\n        # Icon only\n        content_width = icon_width\n        content_height = icon_height\n    elif option.text:  # type: ignore\n        # Text only\n        content_width = text_width\n        content_height = text_height\n\n    # Add padding (vertical, horizontal)\n    total_width = content_width + (\n        2 * padding[1]\n    )  # horizontal padding on both sides\n    total_height = content_height + (\n        2 * padding[0]\n    )  # vertical padding on top and bottom\n\n    # Ensure minimum button size (reasonable minimums)\n    min_width = 16\n    min_height = 16\n\n    total_width = max(total_width, min_width)\n    total_height = max(total_height, min_height)\n\n    return QtCore.QSize(total_width, total_height)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ButtonDrawer.draw_push_button_bevel","title":"<code>draw_push_button_bevel(option, painter, widget)</code>","text":"<p>Draw the button background and frame with hover detection.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def draw_push_button_bevel(\n    self,\n    option: QStyleOption,\n    painter: QPainter,\n    widget: QWidget | None,\n) -&gt; None:\n    \"\"\"Draw the button background and frame with hover detection.\"\"\"\n    if not isinstance(option, QStyleOptionButton) or widget is None:\n        return\n\n    style, _ = self.get_button_style(widget, option.state)\n    rect = option.rect\n\n    painter.save()\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n    # Draw button background with hover awareness\n    bg_color = style[\"background-color\"]\n    painter.setOpacity(style.get(\"opacity\", 1.0))\n\n    painter.setBrush(QBrush(bg_color))\n    painter.setPen(Qt.PenStyle.NoPen)\n    border_radius = style.get(\"border-radius\", 0)\n\n    draw_icon_as_background = style.get(\"icon-as-background\", False)\n    clip_icon_to_radius = style.get(\"clip-icon-to-radius\", False)\n\n    if draw_icon_as_background:\n        # draw the icon clipped by the same rounded rect\n        painter.save()\n        if clip_icon_to_radius:\n            clip_path = QPainterPath()\n            clip_path.addRoundedRect(rect, border_radius, border_radius)\n            painter.setClipPath(clip_path)\n\n        mode = QtGui.QIcon.Mode.Normal\n        painter.drawRoundedRect(rect, border_radius, border_radius)\n        option.icon.paint(\n            painter,\n            rect,\n            Qt.AlignmentFlag.AlignCenter,\n            mode,\n        )\n\n        if clip_icon_to_radius:\n            painter.setClipping(False)\n\n        pen = QPen(QColor(style.get(\"border-color\")))\n        pen.setWidth(int(style.get(\"border-width\", 0)))\n        painter.setPen(pen)\n        painter.setBrush(Qt.BrushStyle.NoBrush)\n        painter.drawRoundedRect(rect, border_radius, border_radius)\n        painter.restore()\n    else:\n        painter.drawRoundedRect(rect, border_radius, border_radius)\n\n    # Draw focus outline if needed\n    if (\n        option.state &amp; QStyle.StateFlag.State_HasFocus\n        and option.state  # type: ignore\n        &amp; QStyle.StateFlag.State_KeyboardFocusChange\n    ):\n        focus_color = style[\"focus-outline-color\"]\n        pen = QPen(\n            QColor(focus_color), style.get(\"focus-outline-width\", 0)\n        )\n        painter.setPen(pen)\n        painter.setBrush(Qt.BrushStyle.NoBrush)\n        focus_rect = rect.adjusted(1, 1, -1, -1)\n        painter.drawRoundedRect(\n            focus_rect, border_radius + 1, border_radius + 1\n        )\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ButtonDrawer.draw_push_button_label","title":"<code>draw_push_button_label(option, painter, widget)</code>","text":"<p>Draw the button text and icon.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def draw_push_button_label(\n    self,\n    option: QStyleOption,\n    painter: QPainter,\n    widget: QWidget | None,\n) -&gt; None:\n    \"\"\"Draw the button text and icon.\"\"\"\n    if not isinstance(option, QStyleOptionButton) or widget is None:\n        return\n\n    style, wstate = self.get_button_style(widget, option.state)  # type: ignore\n    variant = self.get_button_variant(widget)\n\n    # Set up text color\n    text_color = self.model.get_color(\"color\", style, widget)\n    if not (option.state &amp; QStyle.StateFlag.State_Enabled):  # type: ignore\n        # Apply some opacity to disabled text\n        text_color.setAlpha(int(255 * 0.5))\n\n    painter.save()\n    painter.setPen(text_color)\n\n    # Set up font\n    painter.setFont(_style_font(style, widget))\n\n    # Get content rectangle\n    content_rect = self.style_inst.subElementRect(\n        QStyle.SubElement.SE_PushButtonContents, option, widget\n    )\n    # _debug_rect(painter, \"#ff5555\", content_rect)\n\n    # Optional per-widget alignment override (None \u2192 default centered layout)\n    label_alignment = getattr(widget, \"_label_alignment\", None)\n\n    # Draw icon if present\n    if option.icon:  # type: ignore\n        # icon_color = QColor(getattr(widget, \"_icon_color\", text_color))\n        if option.text and not style.get(\"ignore-text\", False):  # type: ignore\n            icon_size = option.iconSize  # type: ignore\n            icon_w = icon_size.width()\n            icon_h = icon_size.height()\n            _gap = 4\n\n            # Draw icon with text color inheritance\n            mode = QtGui.QIcon.Mode.Normal\n            if not (\n                option.state &amp; QStyle.StateFlag.State_Enabled  # type: ignore\n            ):\n                mode = QtGui.QIcon.Mode.Disabled\n            elif option.state &amp; QStyle.StateFlag.State_Sunken:  # type: ignore\n                mode = QtGui.QIcon.Mode.Active\n\n            if label_alignment is not None:\n                # Group layout: icon + text move together as a unit\n                h_align = (\n                    label_alignment &amp; Qt.AlignmentFlag.AlignHorizontal_Mask\n                )\n                text_w = painter.fontMetrics().horizontalAdvance(\n                    option.text  # type: ignore\n                )\n                group_w = icon_w + _gap + text_w\n                if h_align == Qt.AlignmentFlag.AlignLeft:\n                    group_x = content_rect.left()\n                elif h_align == Qt.AlignmentFlag.AlignRight:\n                    group_x = content_rect.right() - group_w\n                else:\n                    group_x = (\n                        content_rect.left()\n                        + (content_rect.width() - group_w) // 2\n                    )\n                icon_rect = QRect(\n                    group_x,\n                    content_rect.center().y() - icon_h // 2,\n                    icon_w,\n                    icon_h,\n                )\n                text_rect = QRect(\n                    icon_rect.right() + _gap,\n                    content_rect.top(),\n                    text_w,\n                    content_rect.height(),\n                )\n                option.icon.paint(  # type: ignore\n                    painter,\n                    icon_rect,\n                    Qt.AlignmentFlag.AlignCenter,\n                    mode,\n                )\n                painter.drawText(\n                    text_rect,\n                    Qt.AlignmentFlag.AlignLeft\n                    | Qt.AlignmentFlag.AlignVCenter,\n                    option.text,  # type: ignore\n                )\n            else:\n                # Icon + text: place icon on the left (default centered layout)\n                icon_rect = QRect(content_rect)\n                icon_rect.setSize(icon_size)\n                icon_rect.moveCenter(\n                    QtCore.QPoint(\n                        content_rect.left() + style[\"icon-padding\"][0],\n                        content_rect.center().y(),\n                    )\n                )\n                option.icon.paint(  # type: ignore\n                    painter,\n                    icon_rect,\n                    Qt.AlignmentFlag.AlignCenter,\n                    mode,\n                )\n                # Adjust text rectangle\n                text_rect = QRect(content_rect)\n                text_rect.setLeft(icon_rect.right() + _gap)\n                # Draw text\n                painter.drawText(\n                    text_rect,\n                    Qt.AlignmentFlag.AlignCenter,\n                    option.text,  # type: ignore\n                )\n        elif variant != \"thumbnail\":\n            # Icon only\n            mode = QtGui.QIcon.Mode.Normal\n            if not (\n                option.state &amp; QStyle.StateFlag.State_Enabled  # type: ignore\n            ):\n                mode = QtGui.QIcon.Mode.Disabled\n            elif option.state &amp; QStyle.StateFlag.State_Sunken:  # type: ignore\n                mode = QtGui.QIcon.Mode.Active\n\n            checkable = widget.isCheckable() if widget else False\n            # checked = widget.isChecked() if widget else False\n\n            icon_state = (\n                (\n                    QtGui.QIcon.State.On\n                    if wstate == \"hover\"\n                    else QtGui.QIcon.State.Off\n                )\n                if not checkable\n                else (\n                    QtGui.QIcon.State.On\n                    if option.state &amp; QStyle.StateFlag.State_On\n                    else QtGui.QIcon.State.Off\n                )\n            )\n\n            _icon_align = (\n                (label_alignment &amp; Qt.AlignmentFlag.AlignHorizontal_Mask)\n                | Qt.AlignmentFlag.AlignVCenter\n                if label_alignment is not None\n                else Qt.AlignmentFlag.AlignCenter\n            )\n            option.icon.paint(  # type: ignore\n                painter,\n                content_rect,\n                _icon_align,\n                mode,\n                icon_state,\n            )\n    else:\n        # Text only\n        if option.text and not style.get(\"ignore-text\", False):  # type: ignore\n            _text_align = (\n                (label_alignment &amp; Qt.AlignmentFlag.AlignHorizontal_Mask)\n                | Qt.AlignmentFlag.AlignVCenter\n                if label_alignment is not None\n                else Qt.AlignmentFlag.AlignCenter\n            )\n            painter.drawText(\n                content_rect,\n                _text_align,\n                option.text,  # type: ignore\n            )\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ButtonDrawer.get_button_has_icon","title":"<code>get_button_has_icon(widget)</code>","text":"<p>Check if button has an icon.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_button_has_icon(self, widget: QWidget) -&gt; bool:\n    \"\"\"Check if button has an icon.\"\"\"\n    if widget is None:\n        return False\n\n    # Method 1: Try has_icon property\n    if hasattr(widget, \"has_icon\"):\n        return widget.has_icon  # type: ignore\n\n    # Method 2: Try Qt property\n    has_icon_prop = widget.property(\"has_icon\")\n    if has_icon_prop is not None:\n        return bool(has_icon_prop)\n\n    # Method 3: Check the actual icon\n    return bool(widget.icon() and not widget.icon().isNull())  # type: ignore\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ButtonDrawer.get_button_style","title":"<code>get_button_style(widget, state)</code>","text":"<p>Get the appropriate style dictionary for the widget's variant and state.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_button_style(\n    self, widget: QWidget, state: QStyle.StateFlag\n) -&gt; tuple[dict, str]:\n    \"\"\"Get the appropriate style dictionary for the widget's variant and\n    state.\"\"\"\n    variant = self.get_button_variant(widget)\n\n    wstate = \"base\"\n    if not (state &amp; QStyle.StateFlag.State_Enabled):\n        wstate = \"disabled\"\n    elif state &amp; QStyle.StateFlag.State_Sunken:\n        wstate = \"pressed\"\n    elif state &amp; QStyle.StateFlag.State_MouseOver and not (\n        state &amp; QStyle.StateFlag.State_On\n    ):\n        wstate = \"hover\"\n    elif state &amp; QStyle.StateFlag.State_On:\n        wstate = \"checked\"\n\n    style = self.model.get_style(\"QPushButton\", variant, wstate)\n\n    return style, wstate\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ButtonDrawer.get_button_variant","title":"<code>get_button_variant(widget)</code>","text":"<p>Extract button variant from widget properties.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_button_variant(self, widget: QWidget) -&gt; str:\n    \"\"\"Extract button variant from widget properties.\"\"\"\n    if widget is None:\n        return \"surface\"\n    return getattr(widget, \"_variant_str\", \"surface\")\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ComboBoxItemDelegate","title":"<code>ComboBoxItemDelegate</code>","text":"<p>               Bases: <code>QStyledItemDelegate</code></p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>class ComboBoxItemDelegate(QtWidgets.QStyledItemDelegate):\n    def __init__(\n        self,\n        parent=None,\n        padding: int = 4,\n        icon_size: int = 16,\n        style_model: StyleData | None = None,\n    ) -&gt; None:\n        super().__init__(parent)\n        self._padding = padding\n        self._icon_size = icon_size\n        self._icon_text_spacing = 8\n        self._style_model = style_model\n        self._icon_cache: dict[str, QIcon] = {}\n\n    def sizeHint(\n        self, option: QtWidgets.QStyleOptionViewItem, index\n    ) -&gt; QtCore.QSize:\n        \"\"\"Calculate size hint including padding.\"\"\"\n\n        # Calculate text dimensions\n        font_metrics = option.fontMetrics\n        text_size = font_metrics.size(0, option.text)\n\n        # Calculate content dimensions\n        content_width = text_size.width()\n        content_height = max(text_size.height(), self._icon_size)\n\n        # Add icon space if present\n        if option.icon:\n            content_width += self._icon_size + self._icon_text_spacing\n\n        # Add padding to get total size\n        total_width = content_width + self._padding + self._padding\n        total_height = content_height + self._padding + self._padding\n\n        # Ensure minimum height\n        total_height = max(total_height, 32)\n\n        return QtCore.QSize(total_width, total_height)\n\n    def _get_icon(\n        self, fg: QColor, bg: QColor, icon_name: str, invert: bool = True\n    ) -&gt; QIcon:\n        \"\"\"Get icon from cache or create new one.\"\"\"\n        key = f\"{icon_name}-{fg.name()}-{bg.name()}-{invert}\"\n        if key not in self._icon_cache:\n            self._icon_cache[key] = get_icon(\n                icon_name,\n                bg if invert else fg,\n            )\n        return self._icon_cache[key]\n\n    def paint(\n        self,\n        painter: QPainter,\n        option: QStyleOptionViewItem,\n        index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n    ) -&gt; None:\n        \"\"\"Paint combo-box items directly, bypassing QStyle.\n\n        This avoids QStyleSheetStyle intercepting drawPrimitive /\n        drawControl calls when an app-level QSS is active.\n        \"\"\"\n        painter.save()\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n        # Build a copy of the option with text/palette configured\n        opt = QStyleOptionViewItem(option)\n        self.initStyleOption(opt, index)\n\n        # --- debug ---------------------------------------------\n        # m = f\"&gt;&gt; {opt.text!r} -&gt; \"\n        # for flag in QStyle.StateFlag:\n        #     if opt.state &amp; flag:\n        #         m += f\"{flag.name}, \"\n        # print(m)\n        # -------------------------------------------------------\n\n        # --- resolve colours -----------------------------------\n        fg_data = index.data(Qt.ItemDataRole.ForegroundRole)\n        bg_data = index.data(Qt.ItemDataRole.BackgroundRole)\n\n        cb = self.parent()\n\n        # Menu background from the AYON style JSON\n        if self._style_model:\n            cb_style = self._style_model.get_style(\"QComboBox\")\n            menu_bg = QColor(cb_style.get(\"menu-background-color\", \"#1c2026\"))\n        else:\n            menu_bg = opt.palette.color(\n                QPalette.ColorGroup.Active,\n                QPalette.ColorRole.Window,\n            )\n\n        highlight_color = opt.palette.color(\n            QPalette.ColorGroup.Active, QPalette.ColorRole.Dark\n        )\n\n        state = opt.state\n        is_selected = bool(state &amp; QStyle.StateFlag.State_Selected)\n        is_hovered = (\n            bool(state &amp; QStyle.StateFlag.State_MouseOver) and not is_selected\n        )\n\n        if fg_data and bg_data:\n            fg = fg_data.color()\n            bg = bg_data.color()\n\n            if is_hovered:\n                bg_color = highlight_color\n                text_color = fg\n            elif is_selected:\n                bg_color = fg\n                text_color = bg\n                # Regenerate icon with the swapped text_color\n                icon_name = (\n                    index.data(cb.model().IconNameRole)\n                    if hasattr(cb.model(), \"IconNameRole\")\n                    else None\n                )\n                if icon_name:\n                    opt.icon = self._get_icon(\n                        text_color, bg_color, icon_name, False\n                    )\n            else:\n                bg_color = menu_bg\n                text_color = fg\n        else:\n            # Fallback for items without FG/BG data\n            if is_hovered or is_selected:\n                bg_color = highlight_color\n                text_color = opt.palette.color(\n                    QPalette.ColorRole.HighlightedText\n                )\n            else:\n                bg_color = menu_bg\n                text_color = opt.palette.color(QPalette.ColorRole.Text)\n\n        # --- draw background -----------------------------------\n        painter.setBrush(QBrush(bg_color))\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.drawRect(opt.rect)\n\n        # --- draw icon -----------------------------------------\n        content_left = opt.rect.left() + self._padding\n        if not opt.icon.isNull():\n            icon_rect = QRect(\n                content_left,\n                opt.rect.center().y() - self._icon_size // 2,\n                self._icon_size,\n                self._icon_size,\n            )\n            mode = (\n                QIcon.Mode.Normal\n                if opt.state &amp; QStyle.StateFlag.State_Enabled\n                else QIcon.Mode.Disabled\n            )\n            state = (\n                QIcon.State.On\n                if (is_hovered or is_selected)\n                else QIcon.State.Off\n            )\n            opt.icon.paint(\n                painter,\n                icon_rect,\n                Qt.AlignmentFlag.AlignCenter,\n                mode,\n                state,\n            )\n            content_left = icon_rect.right() + self._icon_text_spacing\n\n        # --- draw text -----------------------------------------\n        if opt.text:\n            text_rect = QRect(opt.rect)\n            text_rect.setLeft(content_left)\n            text_rect.setRight(text_rect.right() - self._padding)\n            painter.setPen(text_color)\n            painter.setFont(opt.font)\n            painter.drawText(\n                text_rect,\n                Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n                opt.text,\n            )\n\n        painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ComboBoxItemDelegate.paint","title":"<code>paint(painter, option, index)</code>","text":"<p>Paint combo-box items directly, bypassing QStyle.</p> <p>This avoids QStyleSheetStyle intercepting drawPrimitive / drawControl calls when an app-level QSS is active.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def paint(\n    self,\n    painter: QPainter,\n    option: QStyleOptionViewItem,\n    index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n) -&gt; None:\n    \"\"\"Paint combo-box items directly, bypassing QStyle.\n\n    This avoids QStyleSheetStyle intercepting drawPrimitive /\n    drawControl calls when an app-level QSS is active.\n    \"\"\"\n    painter.save()\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n    # Build a copy of the option with text/palette configured\n    opt = QStyleOptionViewItem(option)\n    self.initStyleOption(opt, index)\n\n    # --- debug ---------------------------------------------\n    # m = f\"&gt;&gt; {opt.text!r} -&gt; \"\n    # for flag in QStyle.StateFlag:\n    #     if opt.state &amp; flag:\n    #         m += f\"{flag.name}, \"\n    # print(m)\n    # -------------------------------------------------------\n\n    # --- resolve colours -----------------------------------\n    fg_data = index.data(Qt.ItemDataRole.ForegroundRole)\n    bg_data = index.data(Qt.ItemDataRole.BackgroundRole)\n\n    cb = self.parent()\n\n    # Menu background from the AYON style JSON\n    if self._style_model:\n        cb_style = self._style_model.get_style(\"QComboBox\")\n        menu_bg = QColor(cb_style.get(\"menu-background-color\", \"#1c2026\"))\n    else:\n        menu_bg = opt.palette.color(\n            QPalette.ColorGroup.Active,\n            QPalette.ColorRole.Window,\n        )\n\n    highlight_color = opt.palette.color(\n        QPalette.ColorGroup.Active, QPalette.ColorRole.Dark\n    )\n\n    state = opt.state\n    is_selected = bool(state &amp; QStyle.StateFlag.State_Selected)\n    is_hovered = (\n        bool(state &amp; QStyle.StateFlag.State_MouseOver) and not is_selected\n    )\n\n    if fg_data and bg_data:\n        fg = fg_data.color()\n        bg = bg_data.color()\n\n        if is_hovered:\n            bg_color = highlight_color\n            text_color = fg\n        elif is_selected:\n            bg_color = fg\n            text_color = bg\n            # Regenerate icon with the swapped text_color\n            icon_name = (\n                index.data(cb.model().IconNameRole)\n                if hasattr(cb.model(), \"IconNameRole\")\n                else None\n            )\n            if icon_name:\n                opt.icon = self._get_icon(\n                    text_color, bg_color, icon_name, False\n                )\n        else:\n            bg_color = menu_bg\n            text_color = fg\n    else:\n        # Fallback for items without FG/BG data\n        if is_hovered or is_selected:\n            bg_color = highlight_color\n            text_color = opt.palette.color(\n                QPalette.ColorRole.HighlightedText\n            )\n        else:\n            bg_color = menu_bg\n            text_color = opt.palette.color(QPalette.ColorRole.Text)\n\n    # --- draw background -----------------------------------\n    painter.setBrush(QBrush(bg_color))\n    painter.setPen(Qt.PenStyle.NoPen)\n    painter.drawRect(opt.rect)\n\n    # --- draw icon -----------------------------------------\n    content_left = opt.rect.left() + self._padding\n    if not opt.icon.isNull():\n        icon_rect = QRect(\n            content_left,\n            opt.rect.center().y() - self._icon_size // 2,\n            self._icon_size,\n            self._icon_size,\n        )\n        mode = (\n            QIcon.Mode.Normal\n            if opt.state &amp; QStyle.StateFlag.State_Enabled\n            else QIcon.Mode.Disabled\n        )\n        state = (\n            QIcon.State.On\n            if (is_hovered or is_selected)\n            else QIcon.State.Off\n        )\n        opt.icon.paint(\n            painter,\n            icon_rect,\n            Qt.AlignmentFlag.AlignCenter,\n            mode,\n            state,\n        )\n        content_left = icon_rect.right() + self._icon_text_spacing\n\n    # --- draw text -----------------------------------------\n    if opt.text:\n        text_rect = QRect(opt.rect)\n        text_rect.setLeft(content_left)\n        text_rect.setRight(text_rect.right() - self._padding)\n        painter.setPen(text_color)\n        painter.setFont(opt.font)\n        painter.drawText(\n            text_rect,\n            Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n            opt.text,\n        )\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ComboBoxItemDelegate.sizeHint","title":"<code>sizeHint(option, index)</code>","text":"<p>Calculate size hint including padding.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def sizeHint(\n    self, option: QtWidgets.QStyleOptionViewItem, index\n) -&gt; QtCore.QSize:\n    \"\"\"Calculate size hint including padding.\"\"\"\n\n    # Calculate text dimensions\n    font_metrics = option.fontMetrics\n    text_size = font_metrics.size(0, option.text)\n\n    # Calculate content dimensions\n    content_width = text_size.width()\n    content_height = max(text_size.height(), self._icon_size)\n\n    # Add icon space if present\n    if option.icon:\n        content_width += self._icon_size + self._icon_text_spacing\n\n    # Add padding to get total size\n    total_width = content_width + self._padding + self._padding\n    total_height = content_height + self._padding + self._padding\n\n    # Ensure minimum height\n    total_height = max(total_height, 32)\n\n    return QtCore.QSize(total_width, total_height)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ItemViewItemDrawer","title":"<code>ItemViewItemDrawer</code>","text":"<p>Drawer for item view items using QStyledItemDelegate.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>class ItemViewItemDrawer:\n    \"\"\"Drawer for item view items using QStyledItemDelegate.\"\"\"\n\n    def __init__(self, style_inst: AYONStyle) -&gt; None:\n        self.style_inst = style_inst\n        self.model = style_inst.model\n\n    @property\n    def base_class(self):\n        return {\"QStyledItemDelegate\": QStyledItemDelegate}\n\n    def register_drawers(self):\n        return {\n            enum_to_str(\n                QStyle.ControlElement,\n                QStyle.ControlElement.CE_ItemViewItem,\n                \"QStyledItemDelegate\",\n            ): self.draw_item_view_item,\n        }\n\n    def get_item_view_variant(self, widget: QWidget | None) -&gt; str:\n        \"\"\"Extract item view variant from widget properties.\"\"\"\n        if widget is None:\n            return \"default\"\n        if hasattr(widget, \"itemDelegate\"):\n            delegate = widget.itemDelegate()\n            if hasattr(delegate, \"_variant_str\"):\n                return delegate._variant_str\n        return \"default\"\n\n    def get_item_view_style(\n        self,\n        widget: QWidget | None,\n        option: QStyleOptionViewItem,\n    ) -&gt; tuple[dict, str]:\n        \"\"\"Get the appropriate style dictionary for the widget's variant\n        and state.\n\n        Args:\n            widget: The parent widget containing the item view.\n            option: The style option containing state flags.\n\n        Returns:\n            A tuple of (style dictionary, state string).\n        \"\"\"\n        variant = self.get_item_view_variant(widget)\n\n        wstate = \"base\"\n        is_checked = option.checkState == Qt.CheckState.Checked\n        is_hovered = bool(option.state &amp; QStyle.StateFlag.State_MouseOver)\n\n        if is_checked:\n            wstate = \"checked\"\n        elif is_hovered:\n            wstate = \"hover\"\n\n        style = self.model.get_style(\"QStyledItemDelegate\", variant, wstate)\n\n        return style, wstate\n\n    def draw_item_view_item(\n        self,\n        option: QStyleOption,\n        painter: QPainter,\n        widget: QWidget | None,\n    ) -&gt; None:\n        \"\"\"Paint a filter item with checkbox indicator.\n\n        Hover and checked states are handled independently:\n        - Background color comes from hover state when hovered\n        - Checkbox background and text color come from checked state\n        \"\"\"\n        painter.save()\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n        # For QStyleOptionViewItem, we need to check different properties\n        if not isinstance(option, QStyleOptionViewItem):\n            painter.restore()\n            return\n\n        # Determine hover and checked states independently\n        is_checked = option.checkState == Qt.CheckState.Checked\n        is_hovered = bool(option.state &amp; QStyle.StateFlag.State_MouseOver)\n        text = option.text\n\n        # Get variant for style lookups\n        variant = self.get_item_view_variant(widget)\n\n        # Get all necessary styles in a single call\n        styles = self.model.get_styles(\n            \"QStyledItemDelegate\", variant, [\"base\", \"hover\", \"checked\"]\n        )\n        base_style = styles[\"base\"]\n        hover_style = styles[\"hover\"]\n        checked_style = styles[\"checked\"]\n\n        # Constants from base style data\n        checkbox_size = base_style.get(\"checkbox-size\", 16)\n        checkbox_margin = base_style.get(\"checkbox-margin\", 8)\n        text_padding = base_style.get(\"text-padding\", 12)\n        border_radius = base_style.get(\"border-radius\", 2)\n\n        # Background: use hover style if hovered, regardless of checked state\n        if is_hovered:\n            bg_color = QColor(\n                hover_style.get(\n                    \"background-color\",\n                    base_style.get(\"background-color\", \"transparent\"),\n                )\n            )\n        else:\n            bg_color = QColor(\n                base_style.get(\"background-color\", \"transparent\")\n            )\n\n        # Text color: use checked style if checked, else base\n        if is_checked:\n            text_color = QColor(\n                checked_style.get(\"color\", base_style.get(\"color\", \"#8b9198\"))\n            )\n        else:\n            text_color = QColor(base_style.get(\"color\", \"#8b9198\"))\n\n        # Checkbox background: use checked style if checked, else base\n        if is_checked:\n            checkbox_bg_color = QColor(\n                checked_style.get(\n                    \"checkbox-background-color\",\n                    base_style.get(\"checkbox-background-color\", \"#424a57\"),\n                )\n            )\n        else:\n            checkbox_bg_color = QColor(\n                base_style.get(\"checkbox-background-color\", \"#424a57\")\n            )\n\n        # Draw background if hovered (transparent check not needed for hover)\n        if is_hovered:\n            painter.setBrush(QBrush(bg_color))\n            painter.setPen(Qt.PenStyle.NoPen)\n            painter.drawRect(option.rect)\n\n        # Calculate checkbox rect - positioned on right side\n        cb_rect = QRect(\n            option.rect.right() - checkbox_size - checkbox_margin,\n            option.rect.center().y() - checkbox_size // 2,\n            checkbox_size,\n            checkbox_size,\n        )\n\n        # Draw checkbox background\n        painter.setBrush(QBrush(checkbox_bg_color))\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.drawRoundedRect(cb_rect, border_radius, border_radius)\n\n        # Draw X mark if checked\n        if is_checked:\n            icon = get_icon(\"close\", color=\"#000000\")\n            icon_rect = cb_rect.adjusted(2, 2, -2, -2)\n            icon.paint(painter, icon_rect)\n\n        # Draw text\n        painter.setPen(QPen(text_color))\n        text_rect = option.rect.adjusted(\n            text_padding,\n            0,\n            -(checkbox_size + checkbox_margin * 2),\n            0,\n        )\n        painter.drawText(\n            text_rect,\n            Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n            text,\n        )\n\n        painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ItemViewItemDrawer.draw_item_view_item","title":"<code>draw_item_view_item(option, painter, widget)</code>","text":"<p>Paint a filter item with checkbox indicator.</p> <p>Hover and checked states are handled independently: - Background color comes from hover state when hovered - Checkbox background and text color come from checked state</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def draw_item_view_item(\n    self,\n    option: QStyleOption,\n    painter: QPainter,\n    widget: QWidget | None,\n) -&gt; None:\n    \"\"\"Paint a filter item with checkbox indicator.\n\n    Hover and checked states are handled independently:\n    - Background color comes from hover state when hovered\n    - Checkbox background and text color come from checked state\n    \"\"\"\n    painter.save()\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n    # For QStyleOptionViewItem, we need to check different properties\n    if not isinstance(option, QStyleOptionViewItem):\n        painter.restore()\n        return\n\n    # Determine hover and checked states independently\n    is_checked = option.checkState == Qt.CheckState.Checked\n    is_hovered = bool(option.state &amp; QStyle.StateFlag.State_MouseOver)\n    text = option.text\n\n    # Get variant for style lookups\n    variant = self.get_item_view_variant(widget)\n\n    # Get all necessary styles in a single call\n    styles = self.model.get_styles(\n        \"QStyledItemDelegate\", variant, [\"base\", \"hover\", \"checked\"]\n    )\n    base_style = styles[\"base\"]\n    hover_style = styles[\"hover\"]\n    checked_style = styles[\"checked\"]\n\n    # Constants from base style data\n    checkbox_size = base_style.get(\"checkbox-size\", 16)\n    checkbox_margin = base_style.get(\"checkbox-margin\", 8)\n    text_padding = base_style.get(\"text-padding\", 12)\n    border_radius = base_style.get(\"border-radius\", 2)\n\n    # Background: use hover style if hovered, regardless of checked state\n    if is_hovered:\n        bg_color = QColor(\n            hover_style.get(\n                \"background-color\",\n                base_style.get(\"background-color\", \"transparent\"),\n            )\n        )\n    else:\n        bg_color = QColor(\n            base_style.get(\"background-color\", \"transparent\")\n        )\n\n    # Text color: use checked style if checked, else base\n    if is_checked:\n        text_color = QColor(\n            checked_style.get(\"color\", base_style.get(\"color\", \"#8b9198\"))\n        )\n    else:\n        text_color = QColor(base_style.get(\"color\", \"#8b9198\"))\n\n    # Checkbox background: use checked style if checked, else base\n    if is_checked:\n        checkbox_bg_color = QColor(\n            checked_style.get(\n                \"checkbox-background-color\",\n                base_style.get(\"checkbox-background-color\", \"#424a57\"),\n            )\n        )\n    else:\n        checkbox_bg_color = QColor(\n            base_style.get(\"checkbox-background-color\", \"#424a57\")\n        )\n\n    # Draw background if hovered (transparent check not needed for hover)\n    if is_hovered:\n        painter.setBrush(QBrush(bg_color))\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.drawRect(option.rect)\n\n    # Calculate checkbox rect - positioned on right side\n    cb_rect = QRect(\n        option.rect.right() - checkbox_size - checkbox_margin,\n        option.rect.center().y() - checkbox_size // 2,\n        checkbox_size,\n        checkbox_size,\n    )\n\n    # Draw checkbox background\n    painter.setBrush(QBrush(checkbox_bg_color))\n    painter.setPen(Qt.PenStyle.NoPen)\n    painter.drawRoundedRect(cb_rect, border_radius, border_radius)\n\n    # Draw X mark if checked\n    if is_checked:\n        icon = get_icon(\"close\", color=\"#000000\")\n        icon_rect = cb_rect.adjusted(2, 2, -2, -2)\n        icon.paint(painter, icon_rect)\n\n    # Draw text\n    painter.setPen(QPen(text_color))\n    text_rect = option.rect.adjusted(\n        text_padding,\n        0,\n        -(checkbox_size + checkbox_margin * 2),\n        0,\n    )\n    painter.drawText(\n        text_rect,\n        Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n        text,\n    )\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ItemViewItemDrawer.get_item_view_style","title":"<code>get_item_view_style(widget, option)</code>","text":"<p>Get the appropriate style dictionary for the widget's variant and state.</p> <p>Parameters:</p> Name Type Description Default <code>widget</code> <code>QWidget | None</code> <p>The parent widget containing the item view.</p> required <code>option</code> <code>QStyleOptionViewItem</code> <p>The style option containing state flags.</p> required <p>Returns:</p> Type Description <code>tuple[dict, str]</code> <p>A tuple of (style dictionary, state string).</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_item_view_style(\n    self,\n    widget: QWidget | None,\n    option: QStyleOptionViewItem,\n) -&gt; tuple[dict, str]:\n    \"\"\"Get the appropriate style dictionary for the widget's variant\n    and state.\n\n    Args:\n        widget: The parent widget containing the item view.\n        option: The style option containing state flags.\n\n    Returns:\n        A tuple of (style dictionary, state string).\n    \"\"\"\n    variant = self.get_item_view_variant(widget)\n\n    wstate = \"base\"\n    is_checked = option.checkState == Qt.CheckState.Checked\n    is_hovered = bool(option.state &amp; QStyle.StateFlag.State_MouseOver)\n\n    if is_checked:\n        wstate = \"checked\"\n    elif is_hovered:\n        wstate = \"hover\"\n\n    style = self.model.get_style(\"QStyledItemDelegate\", variant, wstate)\n\n    return style, wstate\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ItemViewItemDrawer.get_item_view_variant","title":"<code>get_item_view_variant(widget)</code>","text":"<p>Extract item view variant from widget properties.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_item_view_variant(self, widget: QWidget | None) -&gt; str:\n    \"\"\"Extract item view variant from widget properties.\"\"\"\n    if widget is None:\n        return \"default\"\n    if hasattr(widget, \"itemDelegate\"):\n        delegate = widget.itemDelegate()\n        if hasattr(delegate, \"_variant_str\"):\n            return delegate._variant_str\n    return \"default\"\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.LineEditDrawer","title":"<code>LineEditDrawer</code>","text":"<p>AYONStyle drawer for QLineEdit.</p> <p>Registers a no-op for PE_PanelLineEdit when the widget is an AYLineEdit instance (which paints itself fully in its own paintEvent), and falls back to the base QCommonStyle implementation for all other QLineEdit widgets.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>class LineEditDrawer:\n    \"\"\"AYONStyle drawer for QLineEdit.\n\n    Registers a no-op for PE_PanelLineEdit when the widget is an AYLineEdit\n    instance (which paints itself fully in its own paintEvent), and falls back\n    to the base QCommonStyle implementation for all other QLineEdit widgets.\n    \"\"\"\n\n    def __init__(self, style_inst: AYONStyle) -&gt; None:\n        self.style_inst = style_inst\n\n    @property\n    def base_class(self):\n        return {\"QLineEdit\": QLineEdit}\n\n    def register_drawers(self):\n        return {\n            enum_to_str(\n                QStyle.PrimitiveElement,\n                QStyle.PrimitiveElement.PE_PanelLineEdit,\n                \"QLineEdit\",\n            ): self.draw_panel,\n        }\n\n    def draw_panel(\n        self,\n        option: QStyleOption,\n        painter: QPainter,\n        widget: QWidget | None,\n    ) -&gt; None:\n        # AYLineEdit paints its own background \u2014 skip Qt's default frame.\n        if type(widget).__name__ == \"AYLineEdit\":\n            return\n        super(AYONStyle, self.style_inst).drawPrimitive(\n            QStyle.PrimitiveElement.PE_PanelLineEdit, option, painter, widget\n        )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ScrollBarDrawer","title":"<code>ScrollBarDrawer</code>","text":"Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>class ScrollBarDrawer:\n    def __init__(self, style_inst: AYONStyle) -&gt; None:\n        self.style_inst = style_inst\n        self.model = style_inst.model\n        self._style = self.model.get_style(\"QScrollBar\")\n        self._cache = {}\n\n    @property\n    def base_class(self):\n        return {\"QScrollBar\": QtWidgets.QScrollBar}\n\n    def register_drawers(self):\n        return {\n            enum_to_str(\n                QStyle.ControlElement,\n                QStyle.ControlElement.CE_ScrollBarSlider,\n                \"QScrollBar\",\n            ): self.draw_scrollbar_slider,\n            enum_to_str(\n                QStyle.ControlElement,\n                QStyle.ControlElement.CE_ScrollBarAddPage,\n                \"QScrollBar\",\n            ): self.draw_scrollbar_page,\n            enum_to_str(\n                QStyle.ControlElement,\n                QStyle.ControlElement.CE_ScrollBarSubPage,\n                \"QScrollBar\",\n            ): self.draw_scrollbar_page,\n        }\n\n    def register_sizers(self):\n        return {\n            enum_to_str(\n                QStyle.ComplexControl,\n                QStyle.ComplexControl.CC_ScrollBar,\n                \"QScrollBar\",\n            ): self.get_size,\n        }\n\n    def register_metrics(self):\n        return {\n            enum_to_str(\n                QStyle.PixelMetric,\n                QStyle.PixelMetric.PM_ScrollBarExtent,\n                \"QScrollBar\",\n            ): self.get_metric,\n            enum_to_str(\n                QStyle.PixelMetric,\n                QStyle.PixelMetric.PM_ScrollBarSliderMin,\n                \"QScrollBar\",\n            ): self.get_metric,\n        }\n\n    def get_size(\n        self,\n        cc: QStyle.ComplexControl,\n        opt: QStyleOptionComplex,\n        sc: QStyle.SubControl,\n        w: QWidget | None = None,\n    ) -&gt; QRect | None:\n        if not w:\n            raise ValueError\n\n        if not isinstance(self.style_inst, AYONStyle):\n            raise ValueError\n\n        sup = super(AYONStyle, self.style_inst)  # type: ignore\n        try:\n            als = self._cache[\"add_line_size\"]\n        except KeyError:\n            als = self._cache[\"add_line_size\"] = sup.subControlRect(\n                cc, opt, QStyle.SubControl.SC_ScrollBarAddLine, w\n            ).size()\n        try:\n            sls = self._cache[\"sub_line_size\"]\n        except KeyError:\n            sls = self._cache[\"sub_line_size\"] = sup.subControlRect(\n                cc, opt, QStyle.SubControl.SC_ScrollBarAddLine, w\n            ).size()\n\n        if (\n            sc == QStyle.SubControl.SC_ScrollBarSlider\n            or sc == QStyle.SubControl.SC_ScrollBarGroove\n        ) and isinstance(opt, QStyleOptionSlider):\n            rect = sup.subControlRect(cc, opt, sc, w)\n            if opt.orientation == Qt.Orientation.Vertical:\n                rect.adjust(0, -sls.height(), 0, als.height())\n            else:\n                rect.adjust(-sls.width(), 0, als.width(), 0)\n            return rect\n\n        elif sc == QStyle.SubControl.SC_ScrollBarAddPage and isinstance(\n            opt, QStyleOptionSlider\n        ):\n            rect = sup.subControlRect(cc, opt, sc, w)\n            if opt.orientation == Qt.Orientation.Vertical:\n                rect.adjust(0, 0, 0, als.height())\n            else:\n                rect.adjust(0, 0, als.width(), 0)\n            return rect\n\n        elif sc == QStyle.SubControl.SC_ScrollBarSubPage and isinstance(\n            opt, QStyleOptionSlider\n        ):\n            rect = sup.subControlRect(cc, opt, sc, w)\n            if opt.orientation == Qt.Orientation.Vertical:\n                rect.adjust(0, -sls.height(), 0, 0)\n            else:\n                rect.adjust(-sls.width(), 0, 0, 0)\n            return rect\n\n        raise ValueError\n\n    def get_metric(\n        self,\n        metric: QStyle.PixelMetric,\n        opt: QStyleOption | None = None,\n        widget: QWidget | None = None,\n    ) -&gt; int:\n        if metric == QStyle.PixelMetric.PM_ScrollBarExtent:\n            # Width of a vertical scroll bar and the height of a horizontal\n            # scroll bar.\n            return int(self._style[\"width\"])\n        elif metric == QStyle.PixelMetric.PM_ScrollBarSliderMin:\n            # The minimum height of a vertical scroll bar's slider and the\n            # minimum width of a horizontal scroll bar's slider.\n            return int(self._style[\"min-length\"])\n        return 0\n\n    def draw_scrollbar_slider(\n        self,\n        option: QStyleOptionComplex,\n        painter: QPainter,\n        widget: QWidget | None = None,\n    ) -&gt; None:\n        \"\"\"Draw the scrollbar slider/thumb.\"\"\"\n        style = self.model.get_style(\"QScrollBar\")\n        painter.save()\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n        # Draw slider background\n        painter.setBrush(QBrush(QColor(style.get(\"slider-color\"))))\n        pen = QPen(QColor(style.get(\"background-color\")))\n        pen.setWidth(style.get(\"border-width\"))\n        painter.setPen(pen)\n        radius = style.get(\"border-radius\")\n        painter.drawRoundedRect(option.rect, radius, radius)\n\n        painter.restore()\n\n    def draw_scrollbar_page(\n        self,\n        option: QStyleOptionComplex,\n        painter: QPainter,\n        widget: QWidget | None = None,\n    ) -&gt; None:\n        \"\"\"Draw scrollbar page buttons.\"\"\"\n        style = self.model.get_style(\"QScrollBar\")\n        painter.save()\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n        # Draw slider background\n        painter.setBrush(QBrush(QColor(style.get(\"background-color\"))))\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.drawRect(option.rect)\n\n        painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ScrollBarDrawer.draw_scrollbar_page","title":"<code>draw_scrollbar_page(option, painter, widget=None)</code>","text":"<p>Draw scrollbar page buttons.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def draw_scrollbar_page(\n    self,\n    option: QStyleOptionComplex,\n    painter: QPainter,\n    widget: QWidget | None = None,\n) -&gt; None:\n    \"\"\"Draw scrollbar page buttons.\"\"\"\n    style = self.model.get_style(\"QScrollBar\")\n    painter.save()\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n    # Draw slider background\n    painter.setBrush(QBrush(QColor(style.get(\"background-color\"))))\n    painter.setPen(Qt.PenStyle.NoPen)\n    painter.drawRect(option.rect)\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.ScrollBarDrawer.draw_scrollbar_slider","title":"<code>draw_scrollbar_slider(option, painter, widget=None)</code>","text":"<p>Draw the scrollbar slider/thumb.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def draw_scrollbar_slider(\n    self,\n    option: QStyleOptionComplex,\n    painter: QPainter,\n    widget: QWidget | None = None,\n) -&gt; None:\n    \"\"\"Draw the scrollbar slider/thumb.\"\"\"\n    style = self.model.get_style(\"QScrollBar\")\n    painter.save()\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n    # Draw slider background\n    painter.setBrush(QBrush(QColor(style.get(\"slider-color\"))))\n    pen = QPen(QColor(style.get(\"background-color\")))\n    pen.setWidth(style.get(\"border-width\"))\n    painter.setPen(pen)\n    radius = style.get(\"border-radius\")\n    painter.drawRoundedRect(option.rect, radius, radius)\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.StyleData","title":"<code>StyleData</code>","text":"Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>class StyleData:\n    def __init__(self) -&gt; None:\n        fpath = Path(__file__).parent / \"ayon_style.json\"\n        with open(fpath, \"r\") as fh:\n            self.data = json.load(fh)\n        # Palette values can reference each other\n        self._palette = self.data.get(\"palette\", {})\n        for k, v in self._palette.items():\n            if v.startswith(\"hsl(\"):\n                self._palette[k] = hsl_to_html_color(v)\n        for k, v in self._palette.items():\n            self._palette[k] = self._palette.get(v, v)\n        for k, v in self._palette.items():\n            if v in self._palette:\n                raise ValueError(f\"Unresolved palette value in {k}\")\n        # cache\n        self._cache = {}\n        self.last_key = \"\"\n        # base palette\n        self.base_palette = self._build_palette()\n        self._base_font = None\n\n    @property\n    def base_font(self):\n        # delayed to make sure QApplication is initialized\n        if self._base_font is None:\n            self._base_font = _style_font(\n                self.data.get(\"global\", {}), QWidget()\n            )\n        return self._base_font\n\n    def _build_palette(self):\n        bp = {\n            QPalette.ColorRole.Window: \"qt-active-window\",\n            QPalette.ColorRole.WindowText: \"qt-active-window-text\",\n            QPalette.ColorRole.Base: \"qt-active-base\",\n            QPalette.ColorRole.Text: \"qt-active-text\",\n            QPalette.ColorRole.Link: \"qt-active-link\",\n            QPalette.ColorRole.Button: \"qt-active-button\",\n            QPalette.ColorRole.ButtonText: \"qt-active-button-text\",\n            QPalette.ColorRole.PlaceholderText: \"qt-active-placeholder-text\",\n            QPalette.ColorRole.Highlight: \"qt-active-highlight\",\n            QPalette.ColorRole.HighlightedText: \"qt-active-highlight-text\",\n            QPalette.ColorRole.Light: \"qt-active-light\",\n            QPalette.ColorRole.Midlight: \"qt-active-midlight\",\n            QPalette.ColorRole.Dark: \"qt-active-dark\",\n            QPalette.ColorRole.Mid: \"qt-active-mid\",\n            QPalette.ColorRole.Shadow: \"qt-active-shadow\",\n        }\n        p = QPalette()\n        for role, color_name in bp.items():\n            p.setColor(\n                QPalette.ColorGroup.Active,\n                role,\n                QColor(self._palette.get(color_name, \"#ff0000\")),\n            )\n        return p\n\n    def dump_cache_stats(self):\n        print(f\"[StyleData] cached {len(self._cache)} styles.\")\n        print(f\"[StyleData]   &gt;&gt; {list(self._cache.keys())}\")\n\n    def widget_variants(self, widget):\n        return list(self.data[\"widgets\"][widget][\"variants\"].keys())\n\n    def widget_data(self, widget):\n        return self.data[\"widgets\"].get(widget, {})\n\n    def widget_list(self) -&gt; list[str]:\n        return list(self.data[\"widgets\"].keys())\n\n    def default_variant(self, widget_data):\n        return widget_data.get(\n            \"default-variant\", next(iter(widget_data.get(\"variants\", {})))\n        )\n\n    def validate_variant(self, widget_data, variant):\n        if variant not in widget_data.get(\"variants\", {}):\n            return self.default_variant(widget_data)\n        return variant\n\n    def palette(self):\n        return self._palette\n\n    def get_style(\n        self,\n        widget_cls: str,\n        variant=None,\n        state=\"base\",\n    ):\n        \"\"\"Returns a style for a widget, variant and state.\"\"\"\n        try:\n            return self._cache[f\"{widget_cls}-{variant}-{state}\"]\n        except KeyError:\n            pass\n\n        data = self.widget_data(widget_cls)\n        vrt = self.validate_variant(data, variant)\n        dvrt = self.default_variant(data)\n        pal = self._palette\n        d = copy.copy(self.data[\"global\"])\n        d.update(copy.deepcopy(data.get(\"variants\", {}).get(dvrt, {})))\n        d.update(copy.deepcopy(data.get(\"variants\", {}).get(vrt, {})))\n\n        if state == \"all\":\n            for key, val in d.items():\n                if isinstance(val, dict):\n                    d[key] = {kk: pal.get(vv, vv) for kk, vv in val.items()}\n                elif not isinstance(val, list):\n                    d[key] = pal.get(val, val)\n        else:\n            # Override palette variables with the current state's values and remove\n            # all states. That way, we can directly use \"background-color\" without\n            # checking the widget's state.\n            state_dict = {}\n            for key, val in list(d.items()):\n                if isinstance(val, dict):\n                    if key == state:\n                        state_dict = {\n                            kk: pal.get(vv, vv) for kk, vv in val.items()\n                        }\n                    d.pop(key)\n                elif not isinstance(val, list):\n                    d[key] = pal.get(val, val)\n            # apply current state overrides last to ensure they take precedence\n            # over the base variant\n            d.update(state_dict)\n\n        # cache result\n        self.last_key = f\"{widget_cls}-{variant}-{state}\"\n        self._cache[self.last_key] = d\n        return d\n\n    def get_styles(\n        self,\n        widget_cls: str,\n        variant: str | None = None,\n        states: list[str] | None = None,\n    ) -&gt; dict[str, dict]:\n        \"\"\"Returns styles for a widget, variant and multiple states at once.\n\n        This is more efficient than calling get_style() multiple times\n        when you need styles for several states of the same widget/variant.\n\n        Args:\n            widget_cls: The widget class name (e.g., \"QStyledItemDelegate\").\n            variant: The variant name (e.g., \"default\"). Defaults to None.\n            states: List of states to retrieve (e.g., [\"base\", \"hover\",\n                \"checked\"]). Defaults to [\"base\"].\n\n        Returns:\n            A dictionary mapping state names to their style dictionaries.\n        \"\"\"\n        if states is None:\n            states = [\"base\"]\n\n        cache_key = f\"{widget_cls}-{variant}-{'|'.join(states)}\"\n        try:\n            return self._cache[cache_key]\n        except KeyError:\n            pass\n\n        d = {\n            state: self.get_style(widget_cls, variant, state)\n            for state in states\n        }\n        self._cache[cache_key] = d\n        return d\n\n    def current_style(self):\n        return self._cache[self.last_key]\n\n    def get_color(self, color_name: str, style: dict, w: QWidget) -&gt; QColor:\n        \"\"\"Process color definitions referencing a widget attribute/property\n        using the @ syntax.\n\n        Args:\n            color_name: The color name to retrieve.\n            style: The style dictionary.\n            w: The widget to get the color from.\n        Returns:\n            The color.\n        \"\"\"\n        color = style[color_name]\n        if isinstance(color, str) and color.startswith(\"@\"):\n            color = getattr(\n                w,\n                color[1:],\n                w.palette().color(QPalette.ColorRole.ButtonText),\n            )\n        return QColor(color)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.StyleData.get_color","title":"<code>get_color(color_name, style, w)</code>","text":"<p>Process color definitions referencing a widget attribute/property using the @ syntax.</p> <p>Parameters:</p> Name Type Description Default <code>color_name</code> <code>str</code> <p>The color name to retrieve.</p> required <code>style</code> <code>dict</code> <p>The style dictionary.</p> required <code>w</code> <code>QWidget</code> <p>The widget to get the color from.</p> required <p>Returns:     The color.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_color(self, color_name: str, style: dict, w: QWidget) -&gt; QColor:\n    \"\"\"Process color definitions referencing a widget attribute/property\n    using the @ syntax.\n\n    Args:\n        color_name: The color name to retrieve.\n        style: The style dictionary.\n        w: The widget to get the color from.\n    Returns:\n        The color.\n    \"\"\"\n    color = style[color_name]\n    if isinstance(color, str) and color.startswith(\"@\"):\n        color = getattr(\n            w,\n            color[1:],\n            w.palette().color(QPalette.ColorRole.ButtonText),\n        )\n    return QColor(color)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.StyleData.get_style","title":"<code>get_style(widget_cls, variant=None, state='base')</code>","text":"<p>Returns a style for a widget, variant and state.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_style(\n    self,\n    widget_cls: str,\n    variant=None,\n    state=\"base\",\n):\n    \"\"\"Returns a style for a widget, variant and state.\"\"\"\n    try:\n        return self._cache[f\"{widget_cls}-{variant}-{state}\"]\n    except KeyError:\n        pass\n\n    data = self.widget_data(widget_cls)\n    vrt = self.validate_variant(data, variant)\n    dvrt = self.default_variant(data)\n    pal = self._palette\n    d = copy.copy(self.data[\"global\"])\n    d.update(copy.deepcopy(data.get(\"variants\", {}).get(dvrt, {})))\n    d.update(copy.deepcopy(data.get(\"variants\", {}).get(vrt, {})))\n\n    if state == \"all\":\n        for key, val in d.items():\n            if isinstance(val, dict):\n                d[key] = {kk: pal.get(vv, vv) for kk, vv in val.items()}\n            elif not isinstance(val, list):\n                d[key] = pal.get(val, val)\n    else:\n        # Override palette variables with the current state's values and remove\n        # all states. That way, we can directly use \"background-color\" without\n        # checking the widget's state.\n        state_dict = {}\n        for key, val in list(d.items()):\n            if isinstance(val, dict):\n                if key == state:\n                    state_dict = {\n                        kk: pal.get(vv, vv) for kk, vv in val.items()\n                    }\n                d.pop(key)\n            elif not isinstance(val, list):\n                d[key] = pal.get(val, val)\n        # apply current state overrides last to ensure they take precedence\n        # over the base variant\n        d.update(state_dict)\n\n    # cache result\n    self.last_key = f\"{widget_cls}-{variant}-{state}\"\n    self._cache[self.last_key] = d\n    return d\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.StyleData.get_styles","title":"<code>get_styles(widget_cls, variant=None, states=None)</code>","text":"<p>Returns styles for a widget, variant and multiple states at once.</p> <p>This is more efficient than calling get_style() multiple times when you need styles for several states of the same widget/variant.</p> <p>Parameters:</p> Name Type Description Default <code>widget_cls</code> <code>str</code> <p>The widget class name (e.g., \"QStyledItemDelegate\").</p> required <code>variant</code> <code>str | None</code> <p>The variant name (e.g., \"default\"). Defaults to None.</p> <code>None</code> <code>states</code> <code>list[str] | None</code> <p>List of states to retrieve (e.g., [\"base\", \"hover\", \"checked\"]). Defaults to [\"base\"].</p> <code>None</code> <p>Returns:</p> Type Description <code>dict[str, dict]</code> <p>A dictionary mapping state names to their style dictionaries.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_styles(\n    self,\n    widget_cls: str,\n    variant: str | None = None,\n    states: list[str] | None = None,\n) -&gt; dict[str, dict]:\n    \"\"\"Returns styles for a widget, variant and multiple states at once.\n\n    This is more efficient than calling get_style() multiple times\n    when you need styles for several states of the same widget/variant.\n\n    Args:\n        widget_cls: The widget class name (e.g., \"QStyledItemDelegate\").\n        variant: The variant name (e.g., \"default\"). Defaults to None.\n        states: List of states to retrieve (e.g., [\"base\", \"hover\",\n            \"checked\"]). Defaults to [\"base\"].\n\n    Returns:\n        A dictionary mapping state names to their style dictionaries.\n    \"\"\"\n    if states is None:\n        states = [\"base\"]\n\n    cache_key = f\"{widget_cls}-{variant}-{'|'.join(states)}\"\n    try:\n        return self._cache[cache_key]\n    except KeyError:\n        pass\n\n    d = {\n        state: self.get_style(widget_cls, variant, state)\n        for state in states\n    }\n    self._cache[cache_key] = d\n    return d\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TableHeaderDrawer","title":"<code>TableHeaderDrawer</code>","text":"<p>AYONStyle drawer for QHeaderView used by AYTableView.</p> <p>Handles painting of header sections and labels using colours from the AYTableView style data in ayon_style.json.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>class TableHeaderDrawer:\n    \"\"\"AYONStyle drawer for QHeaderView used by AYTableView.\n\n    Handles painting of header sections and labels using colours\n    from the AYTableView style data in ayon_style.json.\n    \"\"\"\n\n    def __init__(self, style_inst: AYONStyle) -&gt; None:\n        self.style_inst = style_inst\n        self.model = style_inst.model\n        self._icon_cache: dict[str, QIcon] = {}\n\n    @property\n    def base_class(self):\n        return {\"QHeaderView\": QtWidgets.QHeaderView}\n\n    def register_drawers(self) -&gt; dict:\n        return {\n            enum_to_str(\n                QStyle.ControlElement,\n                QStyle.ControlElement.CE_Header,\n                \"QHeaderView\",\n            ): [\n                partial(\n                    self.style_inst.drawControl,\n                    QStyle.ControlElement.CE_HeaderSection,\n                ),\n                partial(\n                    self.style_inst.drawControl,\n                    QStyle.ControlElement.CE_HeaderLabel,\n                ),\n            ],\n            enum_to_str(\n                QStyle.ControlElement,\n                QStyle.ControlElement.CE_HeaderSection,\n                \"QHeaderView\",\n            ): self.draw_header_section,\n            enum_to_str(\n                QStyle.ControlElement,\n                QStyle.ControlElement.CE_HeaderLabel,\n                \"QHeaderView\",\n            ): self.draw_header_label,\n        }\n\n    def register_metrics(self) -&gt; dict:\n        \"\"\"Register pixel metrics for QHeaderView.\"\"\"\n        return {\n            enum_to_str(\n                QStyle.PixelMetric,\n                QStyle.PixelMetric.PM_HeaderMargin,\n                \"QHeaderView\",\n            ): self.get_metric,\n        }\n\n    def get_metric(\n        self,\n        metric: QStyle.PixelMetric,\n        opt: QStyleOption | None = None,\n        widget: QWidget | None = None,\n    ) -&gt; int:\n        \"\"\"Return header margin from style data.\"\"\"\n        if metric == QStyle.PixelMetric.PM_HeaderMargin:\n            return 4\n        return 0\n\n    def _get_table_style(self, widget: QWidget | None) -&gt; dict:\n        \"\"\"Resolve the AYTableView style for the header's parent table.\"\"\"\n        variant = \"default\"\n        if widget is not None:\n            # QHeaderView's parent is the QTreeView/AYTableView\n            table = widget.parent()\n            if table is not None:\n                variant = getattr(table, \"_variant_str\", \"default\")\n        return self.model.get_style(\"AYTableView\", variant)\n\n    def draw_header_section(\n        self,\n        option: QStyleOption,\n        painter: QPainter,\n        widget: QWidget | None = None,\n    ) -&gt; None:\n        \"\"\"Draw the header section background and bottom border.\"\"\"\n        style = self._get_table_style(widget)\n\n        painter.save()\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing, False)\n\n        # Background\n        bg_color = QColor(style.get(\"header-background-color\", \"#272d35\"))\n        painter.setBrush(QBrush(bg_color))\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.drawRect(option.rect)\n\n        # Bottom border\n        border_color = QColor(style.get(\"header-border-color\", \"#41474d\"))\n        pen = QPen(border_color)\n        pen.setWidth(1)\n        painter.setPen(pen)\n        bottom = option.rect.bottom()\n        painter.drawLine(\n            option.rect.left(),\n            bottom,\n            option.rect.right(),\n            bottom,\n        )\n\n        painter.restore()\n\n    def draw_header_label(\n        self,\n        option: QStyleOption,\n        painter: QPainter,\n        widget: QWidget | None = None,\n    ) -&gt; None:\n        \"\"\"Draw the header label text and sort indicator.\"\"\"\n        style = self._get_table_style(widget)\n        padding = style.get(\"header-padding\", [4, 8])\n\n        painter.save()\n\n        # Text\n        text_color = QColor(style.get(\"header-color\", \"#c1c7ce\"))\n        painter.setPen(text_color)\n\n        font = painter.font()\n        font.setWeight(QtGui.QFont.Weight.DemiBold)\n        painter.setFont(font)\n\n        text_rect = option.rect.adjusted(\n            padding[1], padding[0], -padding[1], -padding[0]\n        )\n\n        text = \"\"\n        if hasattr(option, \"text\"):\n            text = option.text or \"\"\n\n        # Check for sort indicator\n        sort_indicator = getattr(option, \"sortIndicator\", None)\n        indicator_space = 0\n        if sort_indicator and sort_indicator != 0:\n            indicator_space = 16\n\n        if text:\n            draw_rect = QRect(text_rect)\n            if indicator_space:\n                draw_rect.setRight(draw_rect.right() - indicator_space)\n            painter.drawText(\n                draw_rect,\n                Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n                text,\n            )\n\n        # Sort indicator arrow\n        if sort_indicator and sort_indicator != 0:\n            indicator_color = QColor(\n                style.get(\n                    \"header-sort-indicator-color\",\n                    \"#8fceff\",\n                )\n            )\n            # sortIndicator: 1 = Down, 2 = Up (in QStyleOptionHeader)\n            icon_name = (\n                \"arrow_downward\" if sort_indicator == 1 else \"arrow_upward\"\n            )\n            cache_key = f\"{icon_name}-{indicator_color.name()}\"\n            if cache_key not in self._icon_cache:\n                self._icon_cache[cache_key] = get_icon(\n                    icon_name, color=indicator_color\n                )\n            icon = self._icon_cache[cache_key]\n            icon_rect = QRect(\n                text_rect.right() - 14,\n                text_rect.center().y() - 7,\n                14,\n                14,\n            )\n            icon.paint(painter, icon_rect)\n\n        painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TableHeaderDrawer.draw_header_label","title":"<code>draw_header_label(option, painter, widget=None)</code>","text":"<p>Draw the header label text and sort indicator.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def draw_header_label(\n    self,\n    option: QStyleOption,\n    painter: QPainter,\n    widget: QWidget | None = None,\n) -&gt; None:\n    \"\"\"Draw the header label text and sort indicator.\"\"\"\n    style = self._get_table_style(widget)\n    padding = style.get(\"header-padding\", [4, 8])\n\n    painter.save()\n\n    # Text\n    text_color = QColor(style.get(\"header-color\", \"#c1c7ce\"))\n    painter.setPen(text_color)\n\n    font = painter.font()\n    font.setWeight(QtGui.QFont.Weight.DemiBold)\n    painter.setFont(font)\n\n    text_rect = option.rect.adjusted(\n        padding[1], padding[0], -padding[1], -padding[0]\n    )\n\n    text = \"\"\n    if hasattr(option, \"text\"):\n        text = option.text or \"\"\n\n    # Check for sort indicator\n    sort_indicator = getattr(option, \"sortIndicator\", None)\n    indicator_space = 0\n    if sort_indicator and sort_indicator != 0:\n        indicator_space = 16\n\n    if text:\n        draw_rect = QRect(text_rect)\n        if indicator_space:\n            draw_rect.setRight(draw_rect.right() - indicator_space)\n        painter.drawText(\n            draw_rect,\n            Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n            text,\n        )\n\n    # Sort indicator arrow\n    if sort_indicator and sort_indicator != 0:\n        indicator_color = QColor(\n            style.get(\n                \"header-sort-indicator-color\",\n                \"#8fceff\",\n            )\n        )\n        # sortIndicator: 1 = Down, 2 = Up (in QStyleOptionHeader)\n        icon_name = (\n            \"arrow_downward\" if sort_indicator == 1 else \"arrow_upward\"\n        )\n        cache_key = f\"{icon_name}-{indicator_color.name()}\"\n        if cache_key not in self._icon_cache:\n            self._icon_cache[cache_key] = get_icon(\n                icon_name, color=indicator_color\n            )\n        icon = self._icon_cache[cache_key]\n        icon_rect = QRect(\n            text_rect.right() - 14,\n            text_rect.center().y() - 7,\n            14,\n            14,\n        )\n        icon.paint(painter, icon_rect)\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TableHeaderDrawer.draw_header_section","title":"<code>draw_header_section(option, painter, widget=None)</code>","text":"<p>Draw the header section background and bottom border.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def draw_header_section(\n    self,\n    option: QStyleOption,\n    painter: QPainter,\n    widget: QWidget | None = None,\n) -&gt; None:\n    \"\"\"Draw the header section background and bottom border.\"\"\"\n    style = self._get_table_style(widget)\n\n    painter.save()\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing, False)\n\n    # Background\n    bg_color = QColor(style.get(\"header-background-color\", \"#272d35\"))\n    painter.setBrush(QBrush(bg_color))\n    painter.setPen(Qt.PenStyle.NoPen)\n    painter.drawRect(option.rect)\n\n    # Bottom border\n    border_color = QColor(style.get(\"header-border-color\", \"#41474d\"))\n    pen = QPen(border_color)\n    pen.setWidth(1)\n    painter.setPen(pen)\n    bottom = option.rect.bottom()\n    painter.drawLine(\n        option.rect.left(),\n        bottom,\n        option.rect.right(),\n        bottom,\n    )\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TableHeaderDrawer.get_metric","title":"<code>get_metric(metric, opt=None, widget=None)</code>","text":"<p>Return header margin from style data.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_metric(\n    self,\n    metric: QStyle.PixelMetric,\n    opt: QStyleOption | None = None,\n    widget: QWidget | None = None,\n) -&gt; int:\n    \"\"\"Return header margin from style data.\"\"\"\n    if metric == QStyle.PixelMetric.PM_HeaderMargin:\n        return 4\n    return 0\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TableHeaderDrawer.register_metrics","title":"<code>register_metrics()</code>","text":"<p>Register pixel metrics for QHeaderView.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def register_metrics(self) -&gt; dict:\n    \"\"\"Register pixel metrics for QHeaderView.\"\"\"\n    return {\n        enum_to_str(\n            QStyle.PixelMetric,\n            QStyle.PixelMetric.PM_HeaderMargin,\n            \"QHeaderView\",\n        ): self.get_metric,\n    }\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TableItemDelegate","title":"<code>TableItemDelegate</code>","text":"<p>               Bases: <code>QStyledItemDelegate</code></p> <p>Item delegate for AYTableView that paints cells directly, bypassing QSS.</p> <p>Reads style data from the AYTableView style entry to draw cell backgrounds (hover, selected) and text/icons.</p> <p>Columns that carry a <code>widget_factory</code> on their :class:<code>TableColumn</code> definition get a persistent editor via :meth:<code>createEditor</code>.  Qt calls :meth:<code>setEditorData</code> both when the editor is first opened and automatically whenever the model emits <code>dataChanged</code> for that index, so server-push updates reach live widgets without extra wiring. User edits are written back via :meth:<code>setModelData</code>.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QWidget | None</code> <p>The parent widget (expected to be an AYTableView instance).</p> <code>None</code> <code>style_model</code> <code>StyleData | None</code> <p>StyleData instance providing colour/dimension data.</p> <code>None</code> <code>variant</code> <code>str</code> <p>The variant string used to look up the correct style.</p> <code>'default'</code> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>class TableItemDelegate(QtWidgets.QStyledItemDelegate):\n    \"\"\"Item delegate for AYTableView that paints cells directly, bypassing QSS.\n\n    Reads style data from the AYTableView style entry to draw cell\n    backgrounds (hover, selected) and text/icons.\n\n    Columns that carry a ``widget_factory`` on their :class:`TableColumn`\n    definition get a persistent editor via :meth:`createEditor`.  Qt calls\n    :meth:`setEditorData` both when the editor is first opened and\n    automatically whenever the model emits ``dataChanged`` for that index,\n    so server-push updates reach live widgets without extra wiring.\n    User edits are written back via :meth:`setModelData`.\n\n    Args:\n        parent: The parent widget (expected to be an AYTableView instance).\n        style_model: StyleData instance providing colour/dimension data.\n        variant: The variant string used to look up the correct style.\n    \"\"\"\n\n    def __init__(\n        self,\n        parent: QWidget | None = None,\n        style_model: StyleData | None = None,\n        variant: str = \"default\",\n    ) -&gt; None:\n        super().__init__(parent)\n        self._style_model = style_model\n        self._variant_str = variant\n\n    def _table_styles(self) -&gt; dict[str, dict]:\n        \"\"\"Return base, hover and selected style dicts at once.\"\"\"\n        if self._style_model is None:\n            return {\"base\": {}, \"hover\": {}, \"selected\": {}}\n        return self._style_model.get_styles(\n            \"AYTableView\",\n            self._variant_str,\n            [\"base\", \"hover\", \"selected\"],\n        )\n\n    def sizeHint(\n        self,\n        option: QtWidgets.QStyleOptionViewItem,\n        index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n    ) -&gt; QtCore.QSize:\n        \"\"\"Return a fixed row height from the style data.\"\"\"\n        if self._style_model:\n            style = self._style_model.get_style(\n                \"AYTableView\", self._variant_str\n            )\n            h = int(style.get(\"item-height\", 32))\n        else:\n            h = 32\n        return QtCore.QSize(option.rect.width(), h)\n\n    def createEditor(\n        self,\n        parent: QWidget,\n        option: QStyleOptionViewItem,\n        index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n    ) -&gt; QWidget | None:\n        \"\"\"Return a widget for widget-factory columns; None otherwise.\n\n        The returned widget is kept open permanently by the view via\n        ``openPersistentEditor``.  Qt calls :meth:`setEditorData` once\n        here and again automatically on every ``dataChanged`` emission\n        for this index, so server-push updates reach the widget for free.\n\n        Args:\n            parent: Parent widget (viewport).\n            option: Style option for the cell.\n            index: Model index identifying the cell.\n\n        Returns:\n            A QWidget created by the column's ``widget_factory``, or\n            ``None`` if the column has no factory.\n        \"\"\"\n        from .components.table_model import PaginatedTableModel\n\n        src_model = index.model()\n        if hasattr(src_model, \"sourceModel\"):\n            src_model = src_model.sourceModel()\n        if not isinstance(src_model, PaginatedTableModel):\n            return None\n        col = index.column()\n        cols = src_model.columns\n        if col &lt; 0 or col &gt;= len(cols):\n            return None\n        factory = cols[col].widget_factory\n        if factory is None:\n            return None\n        return factory(index, parent)  # type: ignore[return-value]\n\n    def setEditorData(\n        self,\n        editor: QWidget,\n        index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n    ) -&gt; None:\n        \"\"\"Push current model data into *editor* when the model changes.\n\n        Called by Qt when the persistent editor is first opened and\n        automatically whenever the model emits ``dataChanged`` for this\n        index \u2014 server-push updates propagate to live widgets for free.\n\n        This default implementation is a no-op suited to action widgets\n        (e.g. buttons) that do not reflect model data.  Override or\n        replace this method for data-reflecting widgets: read\n        ``index.data(Qt.DisplayRole)`` (or a custom role) and push the\n        value into *editor*.\n\n        Args:\n            editor: The persistent editor widget.\n            index: Model index whose data changed.\n        \"\"\"\n\n    def setModelData(\n        self,\n        editor: QWidget,\n        model: QtCore.QAbstractItemModel,\n        index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n    ) -&gt; None:\n        \"\"\"Write committed user input from *editor* back to *model*.\n\n        Called by Qt when the user commits an edit (e.g. presses Enter\n        or the editor loses focus).\n\n        This default implementation is a no-op suited to action widgets\n        that do not write back to the model.  For interactive widget\n        columns, read the current value from *editor* and call\n        ``model.setData(index, value, Qt.EditRole)`` to propagate the\n        change upstream (e.g. to the server).\n\n        Args:\n            editor: The persistent editor widget.\n            model: The data model.\n            index: Model index to write to.\n        \"\"\"\n\n    def paint(\n        self,\n        painter: QPainter,\n        option: QStyleOptionViewItem,\n        index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n    ) -&gt; None:\n        \"\"\"Paint a table cell directly, bypassing QStyle.\"\"\"\n        # Skip painting for cells covered by a persistent editor widget.\n        from .components.table_model import PaginatedTableModel\n\n        src_model = index.model()\n        if hasattr(src_model, \"sourceModel\"):\n            src_model = src_model.sourceModel()\n        if isinstance(src_model, PaginatedTableModel):\n            col = index.column()\n            cols = src_model.columns\n            if 0 &lt;= col &lt; len(cols) and cols[col].widget_factory is not None:\n                return\n\n        painter.save()\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n        opt = QStyleOptionViewItem(option)\n        self.initStyleOption(opt, index)\n\n        state = opt.state\n        is_selected = bool(state &amp; QStyle.StateFlag.State_Selected)\n        is_hovered = bool(state &amp; QStyle.StateFlag.State_MouseOver)\n        # State_MouseOver is only set for the cell directly under the cursor.\n        # When hovering the branch-indicator column, other cells in the same\n        # row don't receive it.  Fall back to a y-coordinate check so the\n        # entire row highlights consistently.\n        if not is_hovered and not is_selected:\n            _view = self.parent()\n            if type(_view).__name__ == \"AYTableView\" and hasattr(\n                _view, \"viewport\"\n            ):\n                _cursor = _view.viewport().mapFromGlobal(QtGui.QCursor.pos())\n                is_hovered = opt.rect.top() &lt;= _cursor.y() &lt; opt.rect.bottom()\n        is_item = not bool(state &amp; QStyle.StateFlag.State_Children)\n\n        styles = self._table_styles()\n        base_style = styles[\"base\"]\n        hover_style = styles[\"hover\"]\n        selected_style = styles[\"selected\"]\n\n        item_padding = base_style.get(\"item-padding\", [4, 8])\n        icon_text_spacing = int(base_style.get(\"icon-text-spacing\", 6))\n\n        # --- background ---\n        if is_selected:\n            bg_color = QColor(\n                selected_style.get(\n                    \"background-color\",\n                    base_style.get(\"background-color\", \"transparent\"),\n                )\n            )\n        elif is_hovered:\n            bg_color = QColor(\n                hover_style.get(\n                    \"background-color\",\n                    base_style.get(\"background-color\", \"transparent\"),\n                )\n            )\n        else:\n            bg_color = QColor(\n                base_style.get(\n                    \"background-color-item\" if is_item else \"background-color\",\n                    \"transparent\",\n                )\n            )\n\n        painter.setBrush(QBrush(bg_color))\n\n        pen_width = base_style.get(\"border-width\", 0)\n        if pen_width &gt; 0:\n            pen_color = QColor(base_style.get(\"border-color\", \"#000000\"))\n            pen = QPen(pen_color)\n            pen.setWidth(pen_width)\n            painter.setPen(pen)\n        else:\n            painter.setPen(Qt.PenStyle.NoPen)\n        column = index.column()\n        if column == 1:\n            painter.fillRect(opt.rect, bg_color)\n            painter.drawPolyline(\n                [\n                    opt.rect.topLeft(),\n                    opt.rect.topRight(),\n                    opt.rect.bottomRight(),\n                    opt.rect.bottomLeft(),\n                ]\n            )\n        else:\n            painter.drawRect(opt.rect)\n\n        # --- text colour ---\n        index_color = index.data(role=Qt.ItemDataRole.ForegroundRole)\n        if is_selected:\n            text_color = (\n                index_color.color()\n                if index_color\n                else QColor(base_style.get(\"color\", \"#f4f5f5\"))\n            )\n        else:\n            text_color = (\n                index_color.color()\n                if index_color\n                else QColor(base_style.get(\"color\", \"#f4f5f5\"))\n            )\n\n        # disabled dimming\n        if not (state &amp; QStyle.StateFlag.State_Enabled):\n            text_color.setAlpha(\n                int(\n                    text_color.alpha()\n                    * base_style.get(\"disabled-opacity\", 0.5)\n                )\n            )\n\n        # --- icon + text layout ---\n        content_rect = QRect(opt.rect).adjusted(\n            item_padding[1],\n            item_padding[0],\n            -item_padding[1],\n            -item_padding[0],\n        )\n        content_left = content_rect.left()\n\n        if not opt.icon.isNull():\n            icon_size = opt.decorationSize\n            icon_rect = QRect(\n                content_left,\n                opt.rect.center().y() - icon_size.height() // 2,\n                icon_size.width(),\n                icon_size.height(),\n            )\n            mode = (\n                QIcon.Mode.Normal\n                if state &amp; QStyle.StateFlag.State_Enabled\n                else QIcon.Mode.Disabled\n            )\n            opt.icon.paint(\n                painter,\n                icon_rect,\n                Qt.AlignmentFlag.AlignCenter,\n                mode,\n            )\n            content_left = icon_rect.right() + icon_text_spacing\n\n        if opt.text:\n            text_rect = QRect(opt.rect)\n            text_rect.setLeft(content_left)\n            text_rect.setRight(content_rect.right())\n            painter.setPen(text_color)\n            painter.setFont(opt.font)\n            painter.drawText(\n                text_rect,\n                Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n                opt.text,\n            )\n\n        painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TableItemDelegate.createEditor","title":"<code>createEditor(parent, option, index)</code>","text":"<p>Return a widget for widget-factory columns; None otherwise.</p> <p>The returned widget is kept open permanently by the view via <code>openPersistentEditor</code>.  Qt calls :meth:<code>setEditorData</code> once here and again automatically on every <code>dataChanged</code> emission for this index, so server-push updates reach the widget for free.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QWidget</code> <p>Parent widget (viewport).</p> required <code>option</code> <code>QStyleOptionViewItem</code> <p>Style option for the cell.</p> required <code>index</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Model index identifying the cell.</p> required <p>Returns:</p> Type Description <code>QWidget | None</code> <p>A QWidget created by the column's <code>widget_factory</code>, or</p> <code>QWidget | None</code> <p><code>None</code> if the column has no factory.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def createEditor(\n    self,\n    parent: QWidget,\n    option: QStyleOptionViewItem,\n    index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n) -&gt; QWidget | None:\n    \"\"\"Return a widget for widget-factory columns; None otherwise.\n\n    The returned widget is kept open permanently by the view via\n    ``openPersistentEditor``.  Qt calls :meth:`setEditorData` once\n    here and again automatically on every ``dataChanged`` emission\n    for this index, so server-push updates reach the widget for free.\n\n    Args:\n        parent: Parent widget (viewport).\n        option: Style option for the cell.\n        index: Model index identifying the cell.\n\n    Returns:\n        A QWidget created by the column's ``widget_factory``, or\n        ``None`` if the column has no factory.\n    \"\"\"\n    from .components.table_model import PaginatedTableModel\n\n    src_model = index.model()\n    if hasattr(src_model, \"sourceModel\"):\n        src_model = src_model.sourceModel()\n    if not isinstance(src_model, PaginatedTableModel):\n        return None\n    col = index.column()\n    cols = src_model.columns\n    if col &lt; 0 or col &gt;= len(cols):\n        return None\n    factory = cols[col].widget_factory\n    if factory is None:\n        return None\n    return factory(index, parent)  # type: ignore[return-value]\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TableItemDelegate.paint","title":"<code>paint(painter, option, index)</code>","text":"<p>Paint a table cell directly, bypassing QStyle.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def paint(\n    self,\n    painter: QPainter,\n    option: QStyleOptionViewItem,\n    index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n) -&gt; None:\n    \"\"\"Paint a table cell directly, bypassing QStyle.\"\"\"\n    # Skip painting for cells covered by a persistent editor widget.\n    from .components.table_model import PaginatedTableModel\n\n    src_model = index.model()\n    if hasattr(src_model, \"sourceModel\"):\n        src_model = src_model.sourceModel()\n    if isinstance(src_model, PaginatedTableModel):\n        col = index.column()\n        cols = src_model.columns\n        if 0 &lt;= col &lt; len(cols) and cols[col].widget_factory is not None:\n            return\n\n    painter.save()\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n    opt = QStyleOptionViewItem(option)\n    self.initStyleOption(opt, index)\n\n    state = opt.state\n    is_selected = bool(state &amp; QStyle.StateFlag.State_Selected)\n    is_hovered = bool(state &amp; QStyle.StateFlag.State_MouseOver)\n    # State_MouseOver is only set for the cell directly under the cursor.\n    # When hovering the branch-indicator column, other cells in the same\n    # row don't receive it.  Fall back to a y-coordinate check so the\n    # entire row highlights consistently.\n    if not is_hovered and not is_selected:\n        _view = self.parent()\n        if type(_view).__name__ == \"AYTableView\" and hasattr(\n            _view, \"viewport\"\n        ):\n            _cursor = _view.viewport().mapFromGlobal(QtGui.QCursor.pos())\n            is_hovered = opt.rect.top() &lt;= _cursor.y() &lt; opt.rect.bottom()\n    is_item = not bool(state &amp; QStyle.StateFlag.State_Children)\n\n    styles = self._table_styles()\n    base_style = styles[\"base\"]\n    hover_style = styles[\"hover\"]\n    selected_style = styles[\"selected\"]\n\n    item_padding = base_style.get(\"item-padding\", [4, 8])\n    icon_text_spacing = int(base_style.get(\"icon-text-spacing\", 6))\n\n    # --- background ---\n    if is_selected:\n        bg_color = QColor(\n            selected_style.get(\n                \"background-color\",\n                base_style.get(\"background-color\", \"transparent\"),\n            )\n        )\n    elif is_hovered:\n        bg_color = QColor(\n            hover_style.get(\n                \"background-color\",\n                base_style.get(\"background-color\", \"transparent\"),\n            )\n        )\n    else:\n        bg_color = QColor(\n            base_style.get(\n                \"background-color-item\" if is_item else \"background-color\",\n                \"transparent\",\n            )\n        )\n\n    painter.setBrush(QBrush(bg_color))\n\n    pen_width = base_style.get(\"border-width\", 0)\n    if pen_width &gt; 0:\n        pen_color = QColor(base_style.get(\"border-color\", \"#000000\"))\n        pen = QPen(pen_color)\n        pen.setWidth(pen_width)\n        painter.setPen(pen)\n    else:\n        painter.setPen(Qt.PenStyle.NoPen)\n    column = index.column()\n    if column == 1:\n        painter.fillRect(opt.rect, bg_color)\n        painter.drawPolyline(\n            [\n                opt.rect.topLeft(),\n                opt.rect.topRight(),\n                opt.rect.bottomRight(),\n                opt.rect.bottomLeft(),\n            ]\n        )\n    else:\n        painter.drawRect(opt.rect)\n\n    # --- text colour ---\n    index_color = index.data(role=Qt.ItemDataRole.ForegroundRole)\n    if is_selected:\n        text_color = (\n            index_color.color()\n            if index_color\n            else QColor(base_style.get(\"color\", \"#f4f5f5\"))\n        )\n    else:\n        text_color = (\n            index_color.color()\n            if index_color\n            else QColor(base_style.get(\"color\", \"#f4f5f5\"))\n        )\n\n    # disabled dimming\n    if not (state &amp; QStyle.StateFlag.State_Enabled):\n        text_color.setAlpha(\n            int(\n                text_color.alpha()\n                * base_style.get(\"disabled-opacity\", 0.5)\n            )\n        )\n\n    # --- icon + text layout ---\n    content_rect = QRect(opt.rect).adjusted(\n        item_padding[1],\n        item_padding[0],\n        -item_padding[1],\n        -item_padding[0],\n    )\n    content_left = content_rect.left()\n\n    if not opt.icon.isNull():\n        icon_size = opt.decorationSize\n        icon_rect = QRect(\n            content_left,\n            opt.rect.center().y() - icon_size.height() // 2,\n            icon_size.width(),\n            icon_size.height(),\n        )\n        mode = (\n            QIcon.Mode.Normal\n            if state &amp; QStyle.StateFlag.State_Enabled\n            else QIcon.Mode.Disabled\n        )\n        opt.icon.paint(\n            painter,\n            icon_rect,\n            Qt.AlignmentFlag.AlignCenter,\n            mode,\n        )\n        content_left = icon_rect.right() + icon_text_spacing\n\n    if opt.text:\n        text_rect = QRect(opt.rect)\n        text_rect.setLeft(content_left)\n        text_rect.setRight(content_rect.right())\n        painter.setPen(text_color)\n        painter.setFont(opt.font)\n        painter.drawText(\n            text_rect,\n            Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n            opt.text,\n        )\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TableItemDelegate.setEditorData","title":"<code>setEditorData(editor, index)</code>","text":"<p>Push current model data into editor when the model changes.</p> <p>Called by Qt when the persistent editor is first opened and automatically whenever the model emits <code>dataChanged</code> for this index \u2014 server-push updates propagate to live widgets for free.</p> <p>This default implementation is a no-op suited to action widgets (e.g. buttons) that do not reflect model data.  Override or replace this method for data-reflecting widgets: read <code>index.data(Qt.DisplayRole)</code> (or a custom role) and push the value into editor.</p> <p>Parameters:</p> Name Type Description Default <code>editor</code> <code>QWidget</code> <p>The persistent editor widget.</p> required <code>index</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Model index whose data changed.</p> required Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def setEditorData(\n    self,\n    editor: QWidget,\n    index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n) -&gt; None:\n    \"\"\"Push current model data into *editor* when the model changes.\n\n    Called by Qt when the persistent editor is first opened and\n    automatically whenever the model emits ``dataChanged`` for this\n    index \u2014 server-push updates propagate to live widgets for free.\n\n    This default implementation is a no-op suited to action widgets\n    (e.g. buttons) that do not reflect model data.  Override or\n    replace this method for data-reflecting widgets: read\n    ``index.data(Qt.DisplayRole)`` (or a custom role) and push the\n    value into *editor*.\n\n    Args:\n        editor: The persistent editor widget.\n        index: Model index whose data changed.\n    \"\"\"\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TableItemDelegate.setModelData","title":"<code>setModelData(editor, model, index)</code>","text":"<p>Write committed user input from editor back to model.</p> <p>Called by Qt when the user commits an edit (e.g. presses Enter or the editor loses focus).</p> <p>This default implementation is a no-op suited to action widgets that do not write back to the model.  For interactive widget columns, read the current value from editor and call <code>model.setData(index, value, Qt.EditRole)</code> to propagate the change upstream (e.g. to the server).</p> <p>Parameters:</p> Name Type Description Default <code>editor</code> <code>QWidget</code> <p>The persistent editor widget.</p> required <code>model</code> <code>QAbstractItemModel</code> <p>The data model.</p> required <code>index</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Model index to write to.</p> required Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def setModelData(\n    self,\n    editor: QWidget,\n    model: QtCore.QAbstractItemModel,\n    index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n) -&gt; None:\n    \"\"\"Write committed user input from *editor* back to *model*.\n\n    Called by Qt when the user commits an edit (e.g. presses Enter\n    or the editor loses focus).\n\n    This default implementation is a no-op suited to action widgets\n    that do not write back to the model.  For interactive widget\n    columns, read the current value from *editor* and call\n    ``model.setData(index, value, Qt.EditRole)`` to propagate the\n    change upstream (e.g. to the server).\n\n    Args:\n        editor: The persistent editor widget.\n        model: The data model.\n        index: Model index to write to.\n    \"\"\"\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TableItemDelegate.sizeHint","title":"<code>sizeHint(option, index)</code>","text":"<p>Return a fixed row height from the style data.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def sizeHint(\n    self,\n    option: QtWidgets.QStyleOptionViewItem,\n    index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n) -&gt; QtCore.QSize:\n    \"\"\"Return a fixed row height from the style data.\"\"\"\n    if self._style_model:\n        style = self._style_model.get_style(\n            \"AYTableView\", self._variant_str\n        )\n        h = int(style.get(\"item-height\", 32))\n    else:\n        h = 32\n    return QtCore.QSize(option.rect.width(), h)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TreeViewDrawer","title":"<code>TreeViewDrawer</code>","text":"<p>AYONStyle drawer for QTreeView.</p> <p>Handles branch expand/collapse indicators and the indentation metric using colours from the QTreeView style data in ayon_style.json.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>class TreeViewDrawer:\n    \"\"\"AYONStyle drawer for QTreeView.\n\n    Handles branch expand/collapse indicators and the indentation metric\n    using colours from the QTreeView style data in ayon_style.json.\n    \"\"\"\n\n    def __init__(self, style_inst: AYONStyle) -&gt; None:\n        self.style_inst = style_inst\n        self.model = style_inst.model\n        self._icon_cache = {}\n\n    @property\n    def base_class(self):\n        return {\"QTreeView\": QTreeView}\n\n    def register_drawers(self) -&gt; dict:\n        \"\"\"Register drawing functions for QTreeView primitives.\"\"\"\n        return {\n            enum_to_str(\n                QStyle.PrimitiveElement,\n                QStyle.PrimitiveElement.PE_IndicatorBranch,\n                \"QTreeView\",\n            ): self.draw_branch_indicator,\n        }\n\n    def register_metrics(self) -&gt; dict:\n        \"\"\"Register pixel metric functions for QTreeView.\"\"\"\n        return {\n            enum_to_str(\n                QStyle.PixelMetric,\n                QStyle.PixelMetric.PM_TreeViewIndentation,\n                \"QTreeView\",\n            ): self.get_metric,\n        }\n\n    def get_metric(\n        self,\n        metric: QStyle.PixelMetric,\n        opt: QStyleOption | None = None,\n        widget: QWidget | None = None,\n    ) -&gt; int:\n        \"\"\"Return indent width from style data.\n\n        Args:\n            metric: The pixel metric being queried.\n            opt: Optional style option.\n            widget: The target widget.\n\n        Returns:\n            The indent size in pixels.\n        \"\"\"\n        if metric == QStyle.PixelMetric.PM_TreeViewIndentation:\n            variant = getattr(widget, \"_variant_str\", \"default\")\n            style = self.model.get_style(\"QTreeView\", variant)\n            return int(style.get(\"indent\", 20))\n        return 0\n\n    def _draw_cell_border(\n        self,\n        painter: QPainter,\n        rect: \"QRect\",\n        style: dict,\n    ) -&gt; None:\n        \"\"\"Draw top and bottom border lines for an AYTableView cell.\"\"\"\n        painter.setPen(\n            QPen(\n                QColor(style.get(\"border-color\")), style.get(\"border-width\", 1)\n            )\n        )\n        painter.setBrush(Qt.BrushStyle.NoBrush)\n        painter.drawLines(\n            [\n                rect.topLeft(),\n                rect.topRight(),\n                rect.bottomLeft(),\n                rect.bottomRight(),\n            ]\n        )\n\n    def draw_branch_indicator(\n        self,\n        option: QStyleOption,\n        painter: QPainter,\n        widget: QWidget | None = None,\n    ) -&gt; None:\n        \"\"\"Draw expand / collapse arrows for tree branch items.\n\n        Args:\n            option: The primitive element style option.\n            painter: The QPainter to draw on.\n            widget: The QTreeView widget (may be the viewport).\n        \"\"\"\n        has_children = bool(option.state &amp; QStyle.StateFlag.State_Children)\n\n        # Resolve to the actual QTreeView \u2014 widget may be the viewport.\n        tv = widget\n        if tv is not None and not isinstance(tv, QTreeView):\n            tv = tv.parent() if tv.parent() else tv\n\n        is_table = type(tv).__name__ == \"AYTableView\"\n        is_selected = bool(option.state &amp; QStyle.StateFlag.State_Selected)\n\n        # State_MouseOver is only set when the cursor is directly over the\n        # branch rect \u2014 not when hovering another column in the same row.\n        # Query the actual cursor position for true row-level hover.\n        # Compare by y-coordinate rather than index.row() to avoid false\n        # matches between rows at the same row number under different parents\n        # (e.g. row 2 under root vs row 2 under an expanded child).\n        is_hovered = False\n        if not is_selected and is_table and isinstance(tv, QTreeView):\n            vp = tv.viewport()\n            cursor_vp = vp.mapFromGlobal(QtGui.QCursor.pos())\n            is_hovered = (\n                option.rect.top() &lt;= cursor_vp.y() &lt; option.rect.bottom()\n            )\n\n        if not has_children:\n            if is_table:\n                if is_selected:\n                    state_name = \"selected\"\n                elif is_hovered:\n                    state_name = \"hover\"\n                else:\n                    state_name = \"base\"\n                style = self.model.get_style(\"AYTableView\", state=state_name)\n                painter.save()\n                painter.fillRect(\n                    option.rect,\n                    QColor(style.get(\"background-color\", \"transparent\")),\n                )\n                self._draw_cell_border(painter, option.rect, style)\n                painter.restore()\n            return\n\n        is_open = bool(option.state &amp; QStyle.StateFlag.State_Open)\n\n        variant = getattr(tv, \"_variant_str\", \"default\")\n        style = self.model.get_style(\"QTreeView\", variant)\n        color = QColor(style.get(\"branch-indicator-color\", \"#8b9198\"))\n        icon_name = style.get(\n            \"expanded-icon-name\" if is_open else \"expand-icon-name\"\n        )\n\n        painter.save()\n\n        if is_table:\n            if is_selected:\n                state_name = \"selected\"\n            elif is_hovered:\n                state_name = \"hover\"\n            else:\n                state_name = \"base\"\n            tbl_style = self.model.get_style(\"AYTableView\", state=state_name)\n            painter.fillRect(\n                option.rect,\n                QColor(tbl_style.get(\"background-color\", \"transparent\")),\n            )\n            self._draw_cell_border(painter, option.rect, tbl_style)\n\n        if icon_name:\n            key = f\"{icon_name}-{color.name()}\"\n            if key not in self._icon_cache:\n                self._icon_cache[key] = get_icon(icon_name, color=color)\n            icon = self._icon_cache[key]\n            rect = option.rect\n            if style.get(\"expand-icon-size\"):\n                center = rect.center()\n                rect.setSize(QSize(16, 16))\n                rect.moveCenter(center)\n            icon.paint(painter, rect)\n\n        else:\n            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)\n            painter.setPen(Qt.PenStyle.NoPen)\n            painter.setBrush(QBrush(color))\n\n            rect = option.rect\n            cx, cy = rect.center().x(), rect.center().y()\n            size = max(4, min(rect.width(), rect.height()) // 3)\n\n            path = QPainterPath()\n            if is_open:\n                # Downward-pointing triangle\n                path.moveTo(cx - size, cy - size // 2)\n                path.lineTo(cx + size, cy - size // 2)\n                path.lineTo(cx, cy + size // 2)\n            else:\n                # Right-pointing triangle\n                path.moveTo(cx - size // 2, cy - size)\n                path.lineTo(cx - size // 2, cy + size)\n                path.lineTo(cx + size // 2, cy)\n            path.closeSubpath()\n            painter.drawPath(path)\n\n        painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TreeViewDrawer.draw_branch_indicator","title":"<code>draw_branch_indicator(option, painter, widget=None)</code>","text":"<p>Draw expand / collapse arrows for tree branch items.</p> <p>Parameters:</p> Name Type Description Default <code>option</code> <code>QStyleOption</code> <p>The primitive element style option.</p> required <code>painter</code> <code>QPainter</code> <p>The QPainter to draw on.</p> required <code>widget</code> <code>QWidget | None</code> <p>The QTreeView widget (may be the viewport).</p> <code>None</code> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def draw_branch_indicator(\n    self,\n    option: QStyleOption,\n    painter: QPainter,\n    widget: QWidget | None = None,\n) -&gt; None:\n    \"\"\"Draw expand / collapse arrows for tree branch items.\n\n    Args:\n        option: The primitive element style option.\n        painter: The QPainter to draw on.\n        widget: The QTreeView widget (may be the viewport).\n    \"\"\"\n    has_children = bool(option.state &amp; QStyle.StateFlag.State_Children)\n\n    # Resolve to the actual QTreeView \u2014 widget may be the viewport.\n    tv = widget\n    if tv is not None and not isinstance(tv, QTreeView):\n        tv = tv.parent() if tv.parent() else tv\n\n    is_table = type(tv).__name__ == \"AYTableView\"\n    is_selected = bool(option.state &amp; QStyle.StateFlag.State_Selected)\n\n    # State_MouseOver is only set when the cursor is directly over the\n    # branch rect \u2014 not when hovering another column in the same row.\n    # Query the actual cursor position for true row-level hover.\n    # Compare by y-coordinate rather than index.row() to avoid false\n    # matches between rows at the same row number under different parents\n    # (e.g. row 2 under root vs row 2 under an expanded child).\n    is_hovered = False\n    if not is_selected and is_table and isinstance(tv, QTreeView):\n        vp = tv.viewport()\n        cursor_vp = vp.mapFromGlobal(QtGui.QCursor.pos())\n        is_hovered = (\n            option.rect.top() &lt;= cursor_vp.y() &lt; option.rect.bottom()\n        )\n\n    if not has_children:\n        if is_table:\n            if is_selected:\n                state_name = \"selected\"\n            elif is_hovered:\n                state_name = \"hover\"\n            else:\n                state_name = \"base\"\n            style = self.model.get_style(\"AYTableView\", state=state_name)\n            painter.save()\n            painter.fillRect(\n                option.rect,\n                QColor(style.get(\"background-color\", \"transparent\")),\n            )\n            self._draw_cell_border(painter, option.rect, style)\n            painter.restore()\n        return\n\n    is_open = bool(option.state &amp; QStyle.StateFlag.State_Open)\n\n    variant = getattr(tv, \"_variant_str\", \"default\")\n    style = self.model.get_style(\"QTreeView\", variant)\n    color = QColor(style.get(\"branch-indicator-color\", \"#8b9198\"))\n    icon_name = style.get(\n        \"expanded-icon-name\" if is_open else \"expand-icon-name\"\n    )\n\n    painter.save()\n\n    if is_table:\n        if is_selected:\n            state_name = \"selected\"\n        elif is_hovered:\n            state_name = \"hover\"\n        else:\n            state_name = \"base\"\n        tbl_style = self.model.get_style(\"AYTableView\", state=state_name)\n        painter.fillRect(\n            option.rect,\n            QColor(tbl_style.get(\"background-color\", \"transparent\")),\n        )\n        self._draw_cell_border(painter, option.rect, tbl_style)\n\n    if icon_name:\n        key = f\"{icon_name}-{color.name()}\"\n        if key not in self._icon_cache:\n            self._icon_cache[key] = get_icon(icon_name, color=color)\n        icon = self._icon_cache[key]\n        rect = option.rect\n        if style.get(\"expand-icon-size\"):\n            center = rect.center()\n            rect.setSize(QSize(16, 16))\n            rect.moveCenter(center)\n        icon.paint(painter, rect)\n\n    else:\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.setBrush(QBrush(color))\n\n        rect = option.rect\n        cx, cy = rect.center().x(), rect.center().y()\n        size = max(4, min(rect.width(), rect.height()) // 3)\n\n        path = QPainterPath()\n        if is_open:\n            # Downward-pointing triangle\n            path.moveTo(cx - size, cy - size // 2)\n            path.lineTo(cx + size, cy - size // 2)\n            path.lineTo(cx, cy + size // 2)\n        else:\n            # Right-pointing triangle\n            path.moveTo(cx - size // 2, cy - size)\n            path.lineTo(cx - size // 2, cy + size)\n            path.lineTo(cx + size // 2, cy)\n        path.closeSubpath()\n        painter.drawPath(path)\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TreeViewDrawer.get_metric","title":"<code>get_metric(metric, opt=None, widget=None)</code>","text":"<p>Return indent width from style data.</p> <p>Parameters:</p> Name Type Description Default <code>metric</code> <code>PixelMetric</code> <p>The pixel metric being queried.</p> required <code>opt</code> <code>QStyleOption | None</code> <p>Optional style option.</p> <code>None</code> <code>widget</code> <code>QWidget | None</code> <p>The target widget.</p> <code>None</code> <p>Returns:</p> Type Description <code>int</code> <p>The indent size in pixels.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_metric(\n    self,\n    metric: QStyle.PixelMetric,\n    opt: QStyleOption | None = None,\n    widget: QWidget | None = None,\n) -&gt; int:\n    \"\"\"Return indent width from style data.\n\n    Args:\n        metric: The pixel metric being queried.\n        opt: Optional style option.\n        widget: The target widget.\n\n    Returns:\n        The indent size in pixels.\n    \"\"\"\n    if metric == QStyle.PixelMetric.PM_TreeViewIndentation:\n        variant = getattr(widget, \"_variant_str\", \"default\")\n        style = self.model.get_style(\"QTreeView\", variant)\n        return int(style.get(\"indent\", 20))\n    return 0\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TreeViewDrawer.register_drawers","title":"<code>register_drawers()</code>","text":"<p>Register drawing functions for QTreeView primitives.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def register_drawers(self) -&gt; dict:\n    \"\"\"Register drawing functions for QTreeView primitives.\"\"\"\n    return {\n        enum_to_str(\n            QStyle.PrimitiveElement,\n            QStyle.PrimitiveElement.PE_IndicatorBranch,\n            \"QTreeView\",\n        ): self.draw_branch_indicator,\n    }\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TreeViewDrawer.register_metrics","title":"<code>register_metrics()</code>","text":"<p>Register pixel metric functions for QTreeView.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def register_metrics(self) -&gt; dict:\n    \"\"\"Register pixel metric functions for QTreeView.\"\"\"\n    return {\n        enum_to_str(\n            QStyle.PixelMetric,\n            QStyle.PixelMetric.PM_TreeViewIndentation,\n            \"QTreeView\",\n        ): self.get_metric,\n    }\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TreeViewItemDelegate","title":"<code>TreeViewItemDelegate</code>","text":"<p>               Bases: <code>QStyledItemDelegate</code></p> <p>Item delegate for AYTreeView that paints directly, bypassing QSS.</p> <p>Reads style data from the QTreeView style entry to draw item backgrounds (hover, selected) and text/icons.  The paint() method uses raw QPainter calls so that a parent-level QStyleSheet cannot intercept and override the colours.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QWidget | None</code> <p>The parent widget (expected to be an AYTreeView instance).</p> <code>None</code> <code>style_model</code> <code>StyleData | None</code> <p>StyleData instance providing colour/dimension data.</p> <code>None</code> <code>variant</code> <code>str</code> <p>The variant string used to look up the correct style.</p> <code>'default'</code> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>class TreeViewItemDelegate(QtWidgets.QStyledItemDelegate):\n    \"\"\"Item delegate for AYTreeView that paints directly, bypassing QSS.\n\n    Reads style data from the QTreeView style entry to draw item\n    backgrounds (hover, selected) and text/icons.  The paint() method\n    uses raw QPainter calls so that a parent-level QStyleSheet cannot\n    intercept and override the colours.\n\n    Args:\n        parent: The parent widget (expected to be an AYTreeView instance).\n        style_model: StyleData instance providing colour/dimension data.\n        variant: The variant string used to look up the correct style.\n    \"\"\"\n\n    def __init__(\n        self,\n        parent: QWidget | None = None,\n        style_model: StyleData | None = None,\n        variant: str = \"default\",\n    ) -&gt; None:\n        super().__init__(parent)\n        self._style_model = style_model\n        self._variant_str = variant\n        self._icon_cache: dict[str, QIcon] = {}\n\n    def _tv_styles(self) -&gt; dict[str, dict]:\n        \"\"\"Return *base*, *hover* and *selected* style dicts at once.\"\"\"\n        if self._style_model is None:\n            return {\"base\": {}, \"hover\": {}, \"selected\": {}}\n        return self._style_model.get_styles(\n            \"QTreeView\",\n            self._variant_str,\n            [\"base\", \"hover\", \"selected\"],\n        )\n\n    def sizeHint(\n        self,\n        option: QtWidgets.QStyleOptionViewItem,\n        index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n    ) -&gt; QtCore.QSize:\n        \"\"\"Return a fixed row height from the style data.\n\n        Args:\n            option: The style option for the item.\n            index: The model index of the item.\n\n        Returns:\n            The size hint for the item.\n        \"\"\"\n        if self._style_model:\n            style = self._style_model.get_style(\"QTreeView\", self._variant_str)\n            h = int(style.get(\"item-height\", 28))\n        else:\n            h = 28\n        return QtCore.QSize(option.rect.width(), h)\n\n    def paint(\n        self,\n        painter: QPainter,\n        option: QStyleOptionViewItem,\n        index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n    ) -&gt; None:\n        \"\"\"Paint a tree-view item directly, bypassing QStyle completely.\n\n        Args:\n            painter: The QPainter to use.\n            option: The style option for the item.\n            index: The model index of the item.\n        \"\"\"\n        painter.save()\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n        opt = QStyleOptionViewItem(option)\n        self.initStyleOption(opt, index)\n\n        state = opt.state\n        is_selected = bool(state &amp; QStyle.StateFlag.State_Selected)\n        is_hovered = bool(state &amp; QStyle.StateFlag.State_MouseOver)\n\n        styles = self._tv_styles()\n        base_style = styles[\"base\"]\n        hover_style = styles[\"hover\"]\n        selected_style = styles[\"selected\"]\n\n        item_padding = base_style.get(\"item-padding\", [4, 8])\n        icon_text_spacing = int(base_style.get(\"icon-text-spacing\", 6))\n\n        # --- background ------------------------------------------------\n        if is_selected:\n            bg_color = QColor(\n                selected_style.get(\n                    \"background-color\",\n                    base_style.get(\"background-color\", \"transparent\"),\n                )\n            )\n        elif is_hovered:\n            bg_color = QColor(\n                hover_style.get(\n                    \"background-color\",\n                    base_style.get(\"background-color\", \"transparent\"),\n                )\n            )\n        else:\n            bg_color = QColor(\n                base_style.get(\"background-color\", \"transparent\")\n            )\n\n        painter.setBrush(QBrush(bg_color))\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.drawRect(opt.rect)\n\n        # --- text colour -----------------------------------------------\n        if is_selected:\n            text_color = QColor(\n                selected_style.get(\n                    \"color\",\n                    base_style.get(\"color\", \"#f4f5f5\"),\n                )\n            )\n        else:\n            text_color = QColor(base_style.get(\"color\", \"#f4f5f5\"))\n\n        # disabled dimming\n        if not (state &amp; QStyle.StateFlag.State_Enabled):\n            text_color.setAlpha(\n                int(\n                    text_color.alpha()\n                    * base_style.get(\"disabled-opacity\", 0.5)\n                )\n            )\n\n        # --- icon + text layout ----------------------------------------\n        content_rect = QRect(opt.rect).adjusted(\n            item_padding[1],\n            item_padding[0],\n            -item_padding[1],\n            -item_padding[0],\n        )\n        content_left = content_rect.left()\n\n        if not opt.icon.isNull():\n            icon_size = opt.decorationSize\n            icon_rect = QRect(\n                content_left,\n                opt.rect.center().y() - icon_size.height() // 2,\n                icon_size.width(),\n                icon_size.height(),\n            )\n            mode = (\n                QIcon.Mode.Normal\n                if state &amp; QStyle.StateFlag.State_Enabled\n                else QIcon.Mode.Disabled\n            )\n            opt.icon.paint(\n                painter,\n                icon_rect,\n                Qt.AlignmentFlag.AlignCenter,\n                mode,\n            )\n            content_left = icon_rect.right() + icon_text_spacing\n\n        if opt.text:\n            text_rect = QRect(opt.rect)\n            text_rect.setLeft(content_left)\n            text_rect.setRight(content_rect.right())\n            painter.setPen(text_color)\n            painter.setFont(opt.font)\n            painter.drawText(\n                text_rect,\n                Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n                opt.text,\n            )\n\n        painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TreeViewItemDelegate.paint","title":"<code>paint(painter, option, index)</code>","text":"<p>Paint a tree-view item directly, bypassing QStyle completely.</p> <p>Parameters:</p> Name Type Description Default <code>painter</code> <code>QPainter</code> <p>The QPainter to use.</p> required <code>option</code> <code>QStyleOptionViewItem</code> <p>The style option for the item.</p> required <code>index</code> <code>QModelIndex | QPersistentModelIndex</code> <p>The model index of the item.</p> required Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def paint(\n    self,\n    painter: QPainter,\n    option: QStyleOptionViewItem,\n    index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n) -&gt; None:\n    \"\"\"Paint a tree-view item directly, bypassing QStyle completely.\n\n    Args:\n        painter: The QPainter to use.\n        option: The style option for the item.\n        index: The model index of the item.\n    \"\"\"\n    painter.save()\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n    opt = QStyleOptionViewItem(option)\n    self.initStyleOption(opt, index)\n\n    state = opt.state\n    is_selected = bool(state &amp; QStyle.StateFlag.State_Selected)\n    is_hovered = bool(state &amp; QStyle.StateFlag.State_MouseOver)\n\n    styles = self._tv_styles()\n    base_style = styles[\"base\"]\n    hover_style = styles[\"hover\"]\n    selected_style = styles[\"selected\"]\n\n    item_padding = base_style.get(\"item-padding\", [4, 8])\n    icon_text_spacing = int(base_style.get(\"icon-text-spacing\", 6))\n\n    # --- background ------------------------------------------------\n    if is_selected:\n        bg_color = QColor(\n            selected_style.get(\n                \"background-color\",\n                base_style.get(\"background-color\", \"transparent\"),\n            )\n        )\n    elif is_hovered:\n        bg_color = QColor(\n            hover_style.get(\n                \"background-color\",\n                base_style.get(\"background-color\", \"transparent\"),\n            )\n        )\n    else:\n        bg_color = QColor(\n            base_style.get(\"background-color\", \"transparent\")\n        )\n\n    painter.setBrush(QBrush(bg_color))\n    painter.setPen(Qt.PenStyle.NoPen)\n    painter.drawRect(opt.rect)\n\n    # --- text colour -----------------------------------------------\n    if is_selected:\n        text_color = QColor(\n            selected_style.get(\n                \"color\",\n                base_style.get(\"color\", \"#f4f5f5\"),\n            )\n        )\n    else:\n        text_color = QColor(base_style.get(\"color\", \"#f4f5f5\"))\n\n    # disabled dimming\n    if not (state &amp; QStyle.StateFlag.State_Enabled):\n        text_color.setAlpha(\n            int(\n                text_color.alpha()\n                * base_style.get(\"disabled-opacity\", 0.5)\n            )\n        )\n\n    # --- icon + text layout ----------------------------------------\n    content_rect = QRect(opt.rect).adjusted(\n        item_padding[1],\n        item_padding[0],\n        -item_padding[1],\n        -item_padding[0],\n    )\n    content_left = content_rect.left()\n\n    if not opt.icon.isNull():\n        icon_size = opt.decorationSize\n        icon_rect = QRect(\n            content_left,\n            opt.rect.center().y() - icon_size.height() // 2,\n            icon_size.width(),\n            icon_size.height(),\n        )\n        mode = (\n            QIcon.Mode.Normal\n            if state &amp; QStyle.StateFlag.State_Enabled\n            else QIcon.Mode.Disabled\n        )\n        opt.icon.paint(\n            painter,\n            icon_rect,\n            Qt.AlignmentFlag.AlignCenter,\n            mode,\n        )\n        content_left = icon_rect.right() + icon_text_spacing\n\n    if opt.text:\n        text_rect = QRect(opt.rect)\n        text_rect.setLeft(content_left)\n        text_rect.setRight(content_rect.right())\n        painter.setPen(text_color)\n        painter.setFont(opt.font)\n        painter.drawText(\n            text_rect,\n            Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n            opt.text,\n        )\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.TreeViewItemDelegate.sizeHint","title":"<code>sizeHint(option, index)</code>","text":"<p>Return a fixed row height from the style data.</p> <p>Parameters:</p> Name Type Description Default <code>option</code> <code>QStyleOptionViewItem</code> <p>The style option for the item.</p> required <code>index</code> <code>QModelIndex | QPersistentModelIndex</code> <p>The model index of the item.</p> required <p>Returns:</p> Type Description <code>QSize</code> <p>The size hint for the item.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def sizeHint(\n    self,\n    option: QtWidgets.QStyleOptionViewItem,\n    index: QtCore.QModelIndex | QtCore.QPersistentModelIndex,\n) -&gt; QtCore.QSize:\n    \"\"\"Return a fixed row height from the style data.\n\n    Args:\n        option: The style option for the item.\n        index: The model index of the item.\n\n    Returns:\n        The size hint for the item.\n    \"\"\"\n    if self._style_model:\n        style = self._style_model.get_style(\"QTreeView\", self._variant_str)\n        h = int(style.get(\"item-height\", 28))\n    else:\n        h = 28\n    return QtCore.QSize(option.rect.width(), h)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.enum_to_str","title":"<code>enum_to_str(enum, enum_value, widget)</code>","text":"<p>Convert enum value to string representation.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def enum_to_str(enum, enum_value: int, widget: str) -&gt; str:\n    \"\"\"Convert enum value to string representation.\"\"\"\n    cachekey = f\"{enum.__name__}_{enum_value}_{widget}\"\n    try:\n        return enum_to_str._cache[cachekey]  # type: ignore\n    except AttributeError:\n        enum_to_str._cache = {}  # type: ignore\n    except KeyError:\n        pass\n\n    try:\n        enum_to_str._cache[cachekey] = enum.valueToKey(enum_value)  # type: ignore\n    except AttributeError:\n        meta_object = QStyle.staticMetaObject  # type: ignore\n        enum_index = meta_object.indexOfEnumerator(enum.__name__)\n        meta_enum = meta_object.enumerator(enum_index)\n        enum_to_str._cache[cachekey] = (  # type: ignore\n            f\"{meta_enum.valueToKey(enum_value)}-{widget}\"  # type: ignore\n        )\n        # print(f'{cachekey}: {enum_to_str._cache[cachekey]}')\n\n    return enum_to_str._cache[cachekey]  # type: ignore\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.get_ayon_style","title":"<code>get_ayon_style()</code>","text":"<p>Get the singleton AYONStyle instance.</p> <p>Returns:</p> Type Description <code>AYONStyle</code> <p>The singleton AYONStyle instance.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_ayon_style() -&gt; AYONStyle:\n    \"\"\"Get the singleton AYONStyle instance.\n\n    Returns:\n        The singleton AYONStyle instance.\n    \"\"\"\n    global _ayon_style_instance\n    if _ayon_style_instance is None:\n        _ayon_style_instance = AYONStyle()\n    return _ayon_style_instance\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.get_ayon_style_data","title":"<code>get_ayon_style_data(widget_cls, variant=None)</code>","text":"<p>Get the AYON style data.</p> <p>Returns:</p> Type Description <code>dict</code> <p>The AYON style data.</p> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def get_ayon_style_data(widget_cls: str, variant: str | None = None) -&gt; dict:\n    \"\"\"Get the AYON style data.\n\n    Returns:\n        The AYON style data.\n    \"\"\"\n    return get_ayon_style().model.get_style(\n        widget_cls, variant=variant, state=\"all\"\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/style.html#client.ayon_ui_qt.style.style_widget_and_siblings","title":"<code>style_widget_and_siblings(widget, fix_app=False)</code>","text":"<p>Apply AYON style to a widget and its siblings recursively.</p> <p>Removes any existing stylesheets and applies the AYON QStyle to the given widget and all its sibling widgets (widgets that share the same parent), including all their nested children even if they are in QLayouts.</p> <p>Parameters:</p> Name Type Description Default <code>widget</code> <code>QWidget</code> <p>The widget whose siblings (and itself) will be styled.</p> required <code>fix_app</code> <code>bool</code> <p>Whether to temporarily remove and restore app stylesheet.</p> <code>False</code> Source code in <code>client/ayon_ui_qt/style.py</code> <pre><code>def style_widget_and_siblings(widget: QWidget, fix_app: bool = False) -&gt; None:\n    \"\"\"Apply AYON style to a widget and its siblings recursively.\n\n    Removes any existing stylesheets and applies the AYON QStyle\n    to the given widget and all its sibling widgets (widgets that\n    share the same parent), including all their nested children\n    even if they are in QLayouts.\n\n    Args:\n        widget: The widget whose siblings (and itself) will be styled.\n        fix_app: Whether to temporarily remove and restore app stylesheet.\n    \"\"\"\n\n    def _collect_widgets(w: QWidget, seen: set[int]) -&gt; None:\n        \"\"\"Recursively collect all widgets including those in layouts.\"\"\"\n        if id(w) in seen:\n            return\n\n        seen.add(id(w))\n        widgets_to_style.append(w)\n\n        # Collect direct widget children\n        for child in w.children():\n            if isinstance(child, QWidget):\n                _collect_widgets(child, seen)\n\n        # Collect widgets from layouts\n        if (layout := w.layout()) is not None:\n            for i in range(layout.count()):\n                if (item := layout.itemAt(i)) and (\n                    item_widget := item.widget()\n                ):\n                    _collect_widgets(item_widget, seen)\n\n    # Determine root widgets: siblings if parent exists, otherwise just widget\n    root_widgets = [widget]\n\n    # Collect all widgets recursively\n    seen_widgets: set[int] = set()\n    widgets_to_style: list[QWidget] = []\n    for w in root_widgets:\n        _collect_widgets(w, seen_widgets)\n\n    qss = None\n    app = QApplication.instance()\n    if fix_app and app and isinstance(app, QApplication):\n        qss = copy.copy(app.property(\"styleSheet\"))\n\n    if fix_app and qss and isinstance(app, QApplication):\n        app.setStyleSheet(\"\")\n\n    widget.setAttribute(Qt.WidgetAttribute.WA_WindowPropagation, False)\n\n    # Apply style to all collected widgets\n    style = get_ayon_style()\n    for w in widgets_to_style:\n        w.style().unpolish(w)\n        w.setStyle(style)\n\n    if fix_app and qss and isinstance(app, QApplication):\n        app.setStyleSheet(qss)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/tester.html","title":"tester","text":""},{"location":"autoapi/client/ayon_ui_qt/tester.html#client.ayon_ui_qt.tester.test","title":"<code>test(test_widget, style=Style.AyonStyleOverCSS)</code>","text":"<p>Main function to run the Qt test.</p> Source code in <code>client/ayon_ui_qt/tester.py</code> <pre><code>def test(test_widget, style: Style = Style.AyonStyleOverCSS):\n    \"\"\"Main function to run the Qt test.\"\"\"\n    app = QtWidgets.QApplication(sys.argv)\n\n    if style == Style.CSS:\n        # Set old RV dark theme for the application\n        app.setStyleSheet(load_rv_stylesheet())\n    elif style == Style.AyonStyle:\n        app.setStyle(get_ayon_style())\n    elif style == Style.AyonStyleOverCSS:\n        app.setStyleSheet(load_rv_stylesheet())\n\n    # Create and show the test widget\n    widget = test_widget()\n\n    if style == Style.AyonStyleOverCSS:\n        widget.setStyle(get_ayon_style())\n\n    widget.show()\n\n    print(\"Qt widget test started. Close the window to exit.\")\n    return app.exec()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/utils.html","title":"utils","text":""},{"location":"autoapi/client/ayon_ui_qt/utils.html#client.ayon_ui_qt.utils.clear_layout","title":"<code>clear_layout(layout)</code>","text":"<p>Recursively deletes child QWidgets in the initial QLayout and in sub-layouts.</p> <p>This function handles all types of QLayout subclasses (QVBoxLayout, QHBoxLayout, QGridLayout, etc.) and safely deletes all child widgets while maintaining the integrity of the parent layout structure.</p> <p>Parameters:</p> Name Type Description Default <code>layout</code> <p>QLayout instance to clear</p> required Source code in <code>client/ayon_ui_qt/utils.py</code> <pre><code>def clear_layout(layout):\n    \"\"\"Recursively deletes child QWidgets in the initial QLayout and in sub-layouts.\n\n    This function handles all types of QLayout subclasses (QVBoxLayout, QHBoxLayout,\n    QGridLayout, etc.) and safely deletes all child widgets while maintaining the\n    integrity of the parent layout structure.\n\n    Args:\n        layout: QLayout instance to clear\n    \"\"\"\n    if layout is None:\n        return\n\n    # print(f\"layout = {layout}\")\n\n    # Work backwards through the layout to avoid index issues when removing items\n    for i in reversed(range(layout.count())):\n        item = layout.takeAt(i)\n        if item is None:\n            continue\n\n        widget = item.widget()\n        sub_layout = item.layout()\n\n        if widget:\n            # Recursively clear any layouts this widget might have\n            # (in case it's a container widget with its own layouts)\n            if hasattr(widget, \"layout\") and widget.layout():\n                clear_layout(widget.layout())\n            # Delete the widget\n            widget.setParent(None)\n            widget.deleteLater()\n        elif sub_layout:\n            # Recursively clear the sub-layout\n            clear_layout(sub_layout)\n            # Delete the layout\n            sub_layout.deleteLater()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/utils.html#client.ayon_ui_qt.utils.process_activity_data","title":"<code>process_activity_data(activity_data, project_data)</code>","text":"<p>Preprocesses payload data to extract and parse comment activities.</p> <p>This function processes the input data to extract activities, specifically focusing on comment activities. It parses these activities using the AYComment class and returns a list of parsed comment objects.</p> <p>Parameters:</p> Name Type Description Default <code>activity_data</code> <code>dict</code> <p>The input data containing project activities in a specific structure. Expected to have a nested structure with 'project' -&gt; 'activities'.</p> required <p>Returns:</p> Name Type Description <code>list</code> <code>list[CommentModel | VersionPublishModel | StatusChangeModel]</code> <p>A list of parsed comment objects. Returns an empty list if no activities are found or if there's an error during processing.</p> Source code in <code>client/ayon_ui_qt/utils.py</code> <pre><code>def process_activity_data(\n    activity_data: dict, project_data: ProjectData\n) -&gt; list[CommentModel | VersionPublishModel | StatusChangeModel]:\n    \"\"\"Preprocesses payload data to extract and parse comment activities.\n\n    This function processes the input data to extract activities, specifically\n    focusing on comment activities. It parses these activities using the\n    AYComment class and returns a list of parsed comment objects.\n\n    Args:\n        activity_data (dict): The input data containing project activities in\n            a specific structure. Expected to have a nested structure with\n            'project' -&gt; 'activities'.\n        project_data (ProjectData)\n\n    Returns:\n        list: A list of parsed comment objects. Returns an empty list if\n            no activities are found or if there's an error during processing.\n    \"\"\"\n    try:\n        activities: list[dict] = activity_data[\"project\"][\"activities\"]\n    except KeyError as err:\n        logger.error(f\"Could not extract activities: {err}\")\n        return []\n\n    users = {d.short_name: d for d in project_data.users}\n    category_colors = {c.name: c.color for c in project_data.comment_category}\n\n    ui_data = []\n    nothing = \"n/a\"\n    for act in activities:\n        act_data = act.get(\"activityData\", {})\n        if isinstance(act_data, str):\n            act_data = json.loads(act_data)\n            act[\"activityData\"] = act_data\n\n        activity_type = act.get(\"activityType\", \"\")\n        activity_id = act[\"activityId\"]\n\n        user_name = act.get(\"author\", {}).get(\"name\", nothing)\n        user_full_name = user_name\n        user = users.get(user_name)\n        if user:\n            user_full_name = user.full_name\n\n        date = act.get(\"updatedAt\", nothing)\n\n        if activity_type == \"comment\":\n            annotation_models, ranges = _parse_annotations(act_data, nothing)\n            file_models = _parse_files(act, ranges, nothing)\n            category = act_data.get(\"category\", \"\")\n            ui_data.append(\n                CommentModel(\n                    activity_id=activity_id,\n                    user_full_name=user_full_name,\n                    user_name=user_name,\n                    comment=act.get(\"body\", nothing),\n                    comment_date=date,\n                    category=category,\n                    category_color=category_colors.get(category, \"\"),\n                    files=file_models,\n                    annotations=annotation_models,\n                )\n            )\n        elif activity_type == \"version.publish\":\n            ui_data.append(\n                VersionPublishModel(\n                    activity_id=activity_id,\n                    user_full_name=user_full_name,\n                    user_name=user_name,\n                    version=str(\n                        act_data.get(\"origin\", {}).get(\"name\", nothing)\n                    ),\n                    product=str(\n                        act_data.get(\"context\", {}).get(\"productName\", nothing)\n                    ),\n                    date=date,\n                )\n            )\n        elif activity_type == \"status.change\":\n            version = act_data.get(\"origin\", {}).get(\"name\", nothing)\n            parents: list[dict] = act_data.get(\"parents\", {})\n            product = next(\n                (p[\"name\"] for p in parents if p[\"type\"] == \"product\"),\n                nothing,\n            )\n            ui_data.append(\n                StatusChangeModel(\n                    activity_id=activity_id,\n                    user_full_name=user_full_name,\n                    user_name=user_name,\n                    product=product,\n                    version=version,\n                    old_status=str(act_data.get(\"oldValue\", nothing)),\n                    new_status=str(act_data.get(\"newValue\", nothing)),\n                    date=date,\n                )\n            )\n\n    return ui_data\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/variants.html","title":"variants","text":""},{"location":"autoapi/client/ayon_ui_qt/variants.html#client.ayon_ui_qt.variants.check_variants_sync","title":"<code>check_variants_sync()</code>","text":"<p>Check if the variants.py file is in sync with the style data.</p> Source code in <code>client/ayon_ui_qt/variants.py</code> <pre><code>def check_variants_sync():\n    \"\"\"Check if the variants.py file is in sync with the style data.\"\"\"\n    from .style import get_ayon_style\n\n    # Runtime sync assertion at import\n    style_data = get_ayon_style().model\n    enum_desync = False\n    report = \"\"\n\n    for widget in style_data.widget_list():\n        json_variants = style_data.widget_variants(widget)\n        if not json_variants:\n            continue\n\n        enum_name = f\"{widget}Variants\"\n\n        # check if the enum exists for that widget class\n        if enum_name not in globals():\n            report += f\"    Missing enum for {widget}\\n\"\n            enum_desync = True\n            continue\n\n        # check if the enum values match the style data\n        enum = globals()[enum_name]\n        if set(json_variants) != {v.value for v in enum}:\n            report += (\n                f\"    Desync for {widget}: {json_variants} != {enum}\\n\"\n            )\n            enum_desync = True\n\n    # print the report\n    print(\"-\" * 80)\n    if enum_desync:\n        update_variants_file(style_data)\n        print(\"Variants are not in sync with the style data.\\n\")\n        print(f\"VARIANTS ANALYSIS {'_' * 62}\\n\" + report)\n    else:\n        print(\"Variants are in sync with the style data.\")\n    print(\"-\" * 80)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/variants.html#client.ayon_ui_qt.variants.update_variants_file","title":"<code>update_variants_file(style_data)</code>","text":"<p>Update the variants.py file with the current style data.</p> Source code in <code>client/ayon_ui_qt/variants.py</code> <pre><code>def update_variants_file(style_data):\n    \"\"\"Update the variants.py file with the current style data.\"\"\"\n    import os\n    import inspect\n    import re\n\n    # get the path of the current file\n    current_file = inspect.getfile(inspect.currentframe())\n    current_dir = os.path.dirname(current_file)\n\n    # load the current variants.py file\n    with open(os.path.join(current_dir, \"variants.py\"), \"r\") as f:\n        current = f.read()\n\n    # get the start and end of the variants definitions\n    start = current.find(\"# VARIANTS DEFINITIONS\")\n    end = current.find(\"# END OF VARIANTs DEFINITIONS\")\n    if start == -1 or end == -1:\n        raise RuntimeError(\n            \"Could not find variants definitions in variants.py\"\n        )\n    # adjust start to the end of the line\n    start = current.find(\"\\n\", start) + 1\n\n    # get the part before and after the variants definitions\n    before = current[:start]\n    after = current[end:]\n\n    # generate all variants enums from style data\n    defs = []\n    for widget in style_data.widget_list():\n        json_variants = style_data.widget_variants(widget)\n        if not json_variants:\n            continue\n\n        defs.append(f\"class {widget}Variants(Enum):\\n\")\n        for variant in json_variants:\n            # remove spaces and special characters\n            field_name = re.sub(r\"[^a-zA-Z0-9]\", \"_\", variant).title()\n            # avoid empty strings\n            if variant == \"\":\n                field_name = \"Default\"\n            defs.append(f'    {field_name} = \"{variant}\"\\n')\n        defs.append(\"\\n\\n\")\n\n    new = before + \"\\n\\n\" + \"\".join(defs) + after\n    # print(\"-\" * 80 + \"\\n\" + new + \"\\n\" + \"-\" * 80 + \"\\n\")\n\n    # write the new variants.py file\n    with open(os.path.join(current_dir, \"variants.py\"), \"w\") as f:\n        f.write(new)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/version.html","title":"version","text":"<p>Package declaring AYON addon 'ui_qt' version.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/index.html","title":"components","text":"<p>AYON UI Qt components package.</p> <p>This package provides reusable Qt widgets styled according to the AYON design system.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/buttons.html","title":"buttons","text":""},{"location":"autoapi/client/ayon_ui_qt/components/buttons.html#client.ayon_ui_qt.components.buttons.AYButtonMenu","title":"<code>AYButtonMenu</code>","text":"<p>               Bases: <code>AYButton</code></p> <p>A push button that shows a floating dropdown panel when clicked.</p> <p>When clicked, the button displays a <code>QFrame</code> popup positioned directly below it (or above when screen space is insufficient). The popup contents are provided by a caller-supplied <code>populate_callback</code> which receives the dropdown <code>QFrame</code> container.</p> <p>Clicking the button again or clicking outside the popup closes the dropdown.</p> <p>Example::</p> <pre><code>def populate(container: QtWidgets.QFrame) -&gt; None:\n    btn = QPushButton(\"Option A\", container)\n    container.layout().addWidget(btn)\n\nmenu_btn = AYButtonMenu(\"Options\", populate_callback=populate)\n</code></pre> Signals <p>menu_opened: Emitted when the dropdown is shown. menu_closed: Emitted when the dropdown is hidden.</p> Source code in <code>client/ayon_ui_qt/components/buttons.py</code> <pre><code>class AYButtonMenu(AYButton):\n    \"\"\"A push button that shows a floating dropdown panel when clicked.\n\n    When clicked, the button displays a ``QFrame`` popup positioned\n    directly below it (or above when screen space is insufficient). The\n    popup contents are provided by a caller-supplied\n    ``populate_callback`` which receives the dropdown ``QFrame``\n    container.\n\n    Clicking the button again or clicking outside the popup closes the\n    dropdown.\n\n    Example::\n\n        def populate(container: QtWidgets.QFrame) -&gt; None:\n            btn = QPushButton(\"Option A\", container)\n            container.layout().addWidget(btn)\n\n        menu_btn = AYButtonMenu(\"Options\", populate_callback=populate)\n\n    Signals:\n        menu_opened: Emitted when the dropdown is shown.\n        menu_closed: Emitted when the dropdown is hidden.\n    \"\"\"\n\n    menu_opened = QtCore.Signal()\n    menu_closed = QtCore.Signal()\n\n    def __init__(\n        self,\n        *args,\n        populate_callback: Callable[[AYContainer], None],\n        **kwargs,\n    ) -&gt; None:\n        \"\"\"Initialize the AYButtonMenu.\n\n        Args:\n            *args: Positional arguments forwarded to ``AYButton``.\n            populate_callback: A callable that receives the dropdown\n                ``QFrame`` container and is responsible for adding\n                child widgets to it.\n            **kwargs: Keyword arguments forwarded to ``AYButton``.\n        \"\"\"\n        super().__init__(*args, **kwargs)\n\n        self._populate_callback = populate_callback\n        self._menu_open: bool = False\n\n        self._dropdown = _ButtonMenuDropdown(self)\n        self._populate_callback(self._dropdown)\n        self._dropdown.popup_closed.connect(self._on_popup_closed)\n\n        self.clicked.connect(self._on_button_clicked)\n\n    # --- Event handlers ---\n\n    def _on_button_clicked(self) -&gt; None:\n        \"\"\"Toggle the dropdown popup visibility.\"\"\"\n        if self._menu_open:\n            self._dropdown.close()\n        else:\n            self._menu_open = True\n            self.menu_opened.emit()\n            self._dropdown.show_below(self)\n\n    def _on_popup_closed(self) -&gt; None:\n        \"\"\"Update state when the popup signals it has closed.\"\"\"\n        self._menu_open = False\n        self.menu_closed.emit()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/buttons.html#client.ayon_ui_qt.components.buttons.AYButtonMenu.__init__","title":"<code>__init__(*args, populate_callback, **kwargs)</code>","text":"<p>Initialize the AYButtonMenu.</p> <p>Parameters:</p> Name Type Description Default <code>*args</code> <p>Positional arguments forwarded to <code>AYButton</code>.</p> <code>()</code> <code>populate_callback</code> <code>Callable[[AYContainer], None]</code> <p>A callable that receives the dropdown <code>QFrame</code> container and is responsible for adding child widgets to it.</p> required <code>**kwargs</code> <p>Keyword arguments forwarded to <code>AYButton</code>.</p> <code>{}</code> Source code in <code>client/ayon_ui_qt/components/buttons.py</code> <pre><code>def __init__(\n    self,\n    *args,\n    populate_callback: Callable[[AYContainer], None],\n    **kwargs,\n) -&gt; None:\n    \"\"\"Initialize the AYButtonMenu.\n\n    Args:\n        *args: Positional arguments forwarded to ``AYButton``.\n        populate_callback: A callable that receives the dropdown\n            ``QFrame`` container and is responsible for adding\n            child widgets to it.\n        **kwargs: Keyword arguments forwarded to ``AYButton``.\n    \"\"\"\n    super().__init__(*args, **kwargs)\n\n    self._populate_callback = populate_callback\n    self._menu_open: bool = False\n\n    self._dropdown = _ButtonMenuDropdown(self)\n    self._populate_callback(self._dropdown)\n    self._dropdown.popup_closed.connect(self._on_popup_closed)\n\n    self.clicked.connect(self._on_button_clicked)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/check_box.html","title":"check_box","text":"<p>checkbox</p>"},{"location":"autoapi/client/ayon_ui_qt/components/check_box.html#client.ayon_ui_qt.components.check_box.AYCheckBox","title":"<code>AYCheckBox</code>","text":"<p>               Bases: <code>QCheckBox</code></p> <p>AYON styled checkbox widget.</p> <p>Overrides Qt's stylesheet painting with AYONStyle custom rendering.</p> <p>Parameters:</p> Name Type Description Default <code>*args</code> <p>Positional arguments passed to QCheckBox.</p> <code>()</code> <code>**kwargs</code> <p>Keyword arguments passed to QCheckBox.</p> <code>{}</code> Source code in <code>client/ayon_ui_qt/components/check_box.py</code> <pre><code>class AYCheckBox(QCheckBox):\n    \"\"\"AYON styled checkbox widget.\n\n    Overrides Qt's stylesheet painting with AYONStyle custom rendering.\n\n    Args:\n        *args: Positional arguments passed to QCheckBox.\n        **kwargs: Keyword arguments passed to QCheckBox.\n    \"\"\"\n\n    Variants = QCheckBoxVariants\n\n    def __init__(\n        self,\n        *args,\n        variant: Variants = Variants.Default,\n        **kwargs,\n    ):\n        super().__init__(*args, **kwargs)\n        self._variant_str = variant.value\n        self._style_dict = None\n        self.setStyle(get_ayon_style())\n\n        if variant == AYCheckBox.Variants.Button:\n            self.setFixedSize(self.sizeHint())\n\n    @property\n    def style_dict(self):\n        if self._style_dict is None:\n            self._style_dict = get_ayon_style().model.get_style(\n                \"QCheckBox\", variant=self._variant_str\n            )\n        return self._style_dict\n\n    def paintEvent(self, arg__1: QPaintEvent) -&gt; None:\n        p = QPainter(self)\n        option = QStyleOptionButton()\n        self.initStyleOption(option)\n        _style = get_ayon_style()\n\n        _expanding = self.sizePolicy().horizontalPolicy() in (\n            QSizePolicy.Policy.Expanding,\n            QSizePolicy.Policy.MinimumExpanding,\n        )\n        if _expanding:\n            ind_w = _style.pixelMetric(\n                QStyle.PixelMetric.PM_IndicatorWidth, option, self\n            )\n            ind_h = _style.pixelMetric(\n                QStyle.PixelMetric.PM_IndicatorHeight, option, self\n            )\n            spacing = _style.pixelMetric(\n                QStyle.PixelMetric.PM_CheckBoxLabelSpacing, option, self\n            )\n            cy = self.height() // 2\n\n            ind_opt = QStyleOptionButton(option)\n            ind_opt.rect = QRect(0, cy - ind_h // 2, ind_w, ind_h)\n            _style.drawPrimitive(\n                QStyle.PrimitiveElement.PE_IndicatorCheckBox, ind_opt, p, self\n            )\n\n            label_opt = QStyleOptionButton(option)\n            label_opt.rect = QRect(\n                ind_w + spacing,\n                0,\n                self.width() - ind_w - spacing,\n                self.height(),\n            )\n            _style.drawControl(\n                QStyle.ControlElement.CE_CheckBoxLabel, label_opt, p, self\n            )\n        else:\n            _style.drawControl(\n                QStyle.ControlElement.CE_CheckBox, option, p, self\n            )\n\n    def sizeHint(self) -&gt; QSize:\n        size = super().sizeHint()\n\n        if self._variant_str == AYCheckBox.Variants.Button.value:\n            h_pad, v_pad = self.style_dict.get(\"padding\", [6, 6])\n            size.setWidth(size.width() + h_pad * 2)\n            size.setHeight(size.height() + v_pad * 2)\n\n        return size\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html","title":"checkbox_handler","text":"<p>Checkbox handler for markdown checkboxes in QTextEdit.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler","title":"<code>CheckboxHandler</code>","text":"<p>               Bases: <code>QObject</code></p> <p>Handles checkbox parsing, rendering, and state management.</p> <p>This class manages: - Parsing markdown to extract checkbox items - Registering custom text objects for checkbox rendering - Tracking checkbox state and positions - Converting back to markdown format</p> Signals <p>checklist_changed: Emitted when any checkbox state changes.</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>class CheckboxHandler(QObject):\n    \"\"\"Handles checkbox parsing, rendering, and state management.\n\n    This class manages:\n    - Parsing markdown to extract checkbox items\n    - Registering custom text objects for checkbox rendering\n    - Tracking checkbox state and positions\n    - Converting back to markdown format\n\n    Signals:\n        checklist_changed: Emitted when any checkbox state changes.\n    \"\"\"\n\n    checklist_changed = Signal()\n\n    # GitHub-flavored markdown checkbox patterns\n    # Matches: - [ ] text, - [x] text, * [ ] text, * [X] text, + [ ] text\n    CHECKBOX_PATTERN = re.compile(\n        r\"^(\\s*[-*+]\\s+)\\[([xX ])\\]\\s*(.*)$\", re.MULTILINE\n    )\n\n    def __init__(self, text_edit: QTextEdit, parent: QObject | None = None):\n        \"\"\"Initialize the checkbox handler.\n\n        Args:\n            text_edit: The QTextEdit widget to manage checkboxes for.\n            parent: Optional parent QObject.\n        \"\"\"\n        super().__init__(parent)\n        self._text_edit = text_edit\n        self._checkboxes: List[CheckboxItem] = []\n        self._checkbox_object: CheckboxTextObject | None = None\n        self._original_markdown: str = \"\"\n        self._register_handler()\n\n    def _register_handler(self) -&gt; None:\n        \"\"\"Register the custom checkbox text object with the document.\"\"\"\n        self._checkbox_object = CheckboxTextObject(self)\n        doc = self._text_edit.document()\n        doc_layout = doc.documentLayout()\n        doc_layout.registerHandler(CHECKBOX_FORMAT_TYPE, self._checkbox_object)\n\n    def parse_and_render(self, markdown: str) -&gt; None:\n        \"\"\"Parse markdown and render checkboxes in the document.\n\n        Extracts checkbox items from markdown, stores their state,\n        and renders them as custom text objects with icons.\n\n        Args:\n            markdown: The markdown string containing checkboxes.\n        \"\"\"\n        self._original_markdown = markdown\n        self._checkboxes.clear()\n\n        # Find all checkbox patterns\n        lines = markdown.split(\"\\n\")\n        processed_lines: List[str] = []\n        checkbox_index = 0\n\n        for line_num, line in enumerate(lines):\n            match = self.CHECKBOX_PATTERN.match(line)\n            if match:\n                prefix = match.group(1)\n                checked_char = match.group(2)\n                text = match.group(3)\n                is_checked = checked_char.lower() == \"x\"\n\n                # Store checkbox info (doc_position filled after insertion)\n                self._checkboxes.append(\n                    CheckboxItem(\n                        index=checkbox_index,\n                        checked=is_checked,\n                        text=text,\n                        line_number=line_num,\n                        prefix=prefix,\n                    )\n                )\n\n                # Replace checkbox syntax with placeholder\n                # We'll insert the actual object after setting plain text\n                processed_lines.append(f\"{prefix}\\ufffc {text}\")\n                checkbox_index += 1\n            else:\n                processed_lines.append(line)\n\n        # Set the processed text\n        processed_text = \"\\n\".join(processed_lines)\n        self._text_edit.setMarkdown(processed_text)\n        self._remove_list_bullets()\n\n        # Now insert checkbox objects at placeholder positions\n        self._insert_checkbox_objects()\n\n    def _remove_list_bullets(self) -&gt; None:\n        \"\"\"Remove bullet markers from list blocks containing checkboxes and\n        correct the indentation to match front-end.\"\"\"\n        doc = self._text_edit.document()\n        processed_lists: set[int] = set()\n\n        block = doc.begin()\n        while block.isValid():\n            text_list = block.textList()\n            if text_list and id(text_list) not in processed_lists:\n                list_key = text_list.item(0).position()\n                if \"\\ufffc\" in block.text():\n                    fmt = text_list.format()\n                    fmt.setStyle(QTextListFormat.Style.ListStyleUndefined)\n                    fmt.setIndent(0)\n                    text_list.setFormat(fmt)\n                    processed_lists.add(list_key)\n            block = block.next()\n\n    def _insert_checkbox_objects(self) -&gt; None:\n        \"\"\"Insert checkbox custom objects at placeholder positions.\"\"\"\n        doc = self._text_edit.document()\n        doc.blockSignals(True)\n\n        cursor = QTextCursor(doc)\n        cursor.beginEditBlock()\n\n        # Find all placeholder characters and replace with checkbox objects\n        text = doc.toPlainText()\n        offset = 0\n\n        for i, cb in enumerate(self._checkboxes):\n            # Find the placeholder character (OBJECT REPLACEMENT CHARACTER)\n            pos = text.find(\"\\ufffc\", offset)\n            if pos == -1:\n                log.warning(\"Could not find placeholder for checkbox %d\", i)\n                continue\n\n            # Create format for the checkbox\n            fmt = QTextCharFormat()\n            fmt.setObjectType(CHECKBOX_FORMAT_TYPE)\n            fmt.setProperty(CHECKBOX_CHECKED_PROP, cb.checked)\n            fmt.setProperty(CHECKBOX_INDEX_PROP, cb.index)\n            fmt.setVerticalAlignment(\n                QTextCharFormat.VerticalAlignment.AlignBaseline\n            )\n\n            # Select and replace the placeholder\n            cursor.setPosition(pos)\n            cursor.setPosition(pos + 1, QTextCursor.MoveMode.KeepAnchor)\n            cursor.insertText(\"\\ufffc\", fmt)\n\n            # Store the document position for fast hit-testing\n            cb.doc_position = pos\n\n            offset = pos + 1\n\n        cursor.endEditBlock()\n        doc.blockSignals(False)\n\n    def get_checkbox_at_position(self, pos: int) -&gt; int | None:\n        \"\"\"Get the checkbox index at the given document position.\n\n        Args:\n            pos: Position in the document (one past the \\\\ufffc char).\n\n        Returns:\n            Checkbox index if found, None otherwise.\n        \"\"\"\n        doc = self._text_edit.document()\n        cursor = QTextCursor(doc)\n        cursor.setPosition(pos)\n        fmt = cursor.charFormat()\n        fmt_type = fmt.objectType()\n\n        if fmt_type == CHECKBOX_FORMAT_TYPE:\n            return fmt.property(CHECKBOX_INDEX_PROP)\n        return None\n\n    def find_checkbox_at_click(\n        self, click_pos: \"QPoint\", content_offset: \"QPoint | None\" = None\n    ) -&gt; Optional[Tuple[bool, Optional[int]]]:\n        \"\"\"Find the checkbox hit by a viewport click using stored positions.\n\n        Uses the cached ``doc_position`` on each :class:`CheckboxItem`\n        instead of scanning the full document text, making hit-testing O(n)\n        in the number of checkboxes rather than O(len(document)).\n\n        Args:\n            click_pos: Click position in viewport coordinates.\n            content_offset: Optional scroll offset (x, y) as a QPoint.\n                Defaults to (0, 0) when not provided.\n\n        Returns:\n            ``(True, doc_position + 1)`` when the click lands on a checkbox,\n            ``(False, None)`` otherwise.\n        \"\"\"\n        if not self._checkboxes:\n            return False, None\n\n        doc = self._text_edit.document()\n        ox = content_offset.x() if content_offset else 0\n        oy = content_offset.y() if content_offset else 0\n\n        for cb in self._checkboxes:\n            pos = cb.doc_position\n            if pos &lt; 0:\n                continue\n\n            cursor = QTextCursor(doc)\n            cursor.setPosition(pos)\n            block = cursor.block()\n            block_layout = block.layout()\n\n            if not block_layout:\n                continue\n\n            rel_pos = pos - block.position()\n            line = block_layout.lineForTextPosition(rel_pos)\n            if not line.isValid():\n                continue\n\n            x1 = line.cursorToX(rel_pos)[0]  # type: ignore[index]\n            x2 = line.cursorToX(rel_pos + 1)[0]  # type: ignore[index]\n            y = line.y() + block_layout.position().y()\n            h = line.height()\n\n            rect = QRectF(x1 + ox, y + oy, x2 - x1, h)\n            if rect.contains(QPointF(click_pos)):\n                return True, pos + 1\n\n        return False, None\n\n    def toggle_checkbox(self, index: int) -&gt; bool:\n        \"\"\"Toggle a checkbox by its index.\n\n        Args:\n            index: The index of the checkbox to toggle.\n\n        Returns:\n            True if the checkbox was toggled, False otherwise.\n        \"\"\"\n        if not 0 &lt;= index &lt; len(self._checkboxes):\n            return False\n\n        # Toggle the state\n        self._checkboxes[index].checked = not self._checkboxes[index].checked\n\n        # Update the document\n        self._update_checkbox_in_document(index)\n\n        # Emit signal\n        self.checklist_changed.emit()\n        return True\n\n    def _update_checkbox_in_document(self, index: int) -&gt; None:\n        \"\"\"Update a single checkbox display in the document.\n\n        Args:\n            index: The index of the checkbox to update.\n        \"\"\"\n        doc = self._text_edit.document()\n        cb = self._checkboxes[index]\n\n        # Block signals to prevent triggering format_comment_on_change\n        # which would clear all formatting including checkboxes\n        doc.blockSignals(True)\n\n        try:\n            pos = cb.doc_position\n            if pos &lt; 0:\n                # Fall back to scanning if position is unknown\n                text = doc.toPlainText()\n                count = 0\n                for i, char in enumerate(text):\n                    if char == \"\\ufffc\":\n                        if count == index:\n                            pos = i\n                            break\n                        count += 1\n\n            if pos &lt; 0:\n                log.warning(\n                    \"Cannot find document position for checkbox %d\", index\n                )\n                return\n\n            cursor = QTextCursor(doc)\n            cursor.setPosition(pos)\n            cursor.setPosition(pos + 1, QTextCursor.MoveMode.KeepAnchor)\n\n            fmt = QTextCharFormat()\n            fmt.setObjectType(CHECKBOX_FORMAT_TYPE)\n            fmt.setProperty(CHECKBOX_CHECKED_PROP, cb.checked)\n            fmt.setProperty(CHECKBOX_INDEX_PROP, cb.index)\n            fmt.setVerticalAlignment(\n                QTextCharFormat.VerticalAlignment.AlignBaseline\n            )\n\n            cursor.setCharFormat(fmt)\n        finally:\n            doc.blockSignals(False)\n\n    def add_checkbox(\n        self,\n        checked: bool = False,\n        prefix: str = \"- \",\n        doc_position: int = -1,\n    ) -&gt; CheckboxItem:\n        \"\"\"Append a new checkbox to the tracked list.\n\n        This is the public API for adding a checkbox programmatically\n        (e.g. when the user presses Enter on a checkbox line or clicks\n        the checklist toolbar button).  The caller is responsible for\n        inserting the actual ``\\\\ufffc`` character into the document and\n        then updating :attr:`CheckboxItem.doc_position`.\n\n        Args:\n            checked: Initial checked state.\n            prefix: Markdown list prefix (e.g. ``\"- \"``).\n            doc_position: Document character position of the ``\\\\ufffc``\n                object, or ``-1`` if not yet known.\n\n        Returns:\n            The newly created :class:`CheckboxItem`.\n        \"\"\"\n        new_index = len(self._checkboxes)\n        item = CheckboxItem(\n            index=new_index,\n            checked=checked,\n            text=\"\",\n            line_number=-1,\n            prefix=prefix,\n            doc_position=doc_position,\n        )\n        self._checkboxes.append(item)\n        return item\n\n    def remove_checkbox(self, index: int) -&gt; None:\n        \"\"\"Remove a checkbox from the tracked list.\n\n        Re-indexes the Python list **and** patches the stale\n        ``CHECKBOX_INDEX_PROP`` values stored in the live\n        ``QTextDocument`` so that subsequent hit-tests via\n        :meth:`get_checkbox_at_position` return correct indices.\n\n        Args:\n            index: The index of the checkbox to remove.\n        \"\"\"\n        if not 0 &lt;= index &lt; len(self._checkboxes):\n            return\n\n        self._checkboxes.pop(index)\n\n        # Re-index the Python list and sync each affected document char format.\n        doc = self._text_edit.document()\n        doc.blockSignals(True)\n        cursor = QTextCursor(doc)\n        cursor.beginEditBlock()\n        try:\n            for i, cb in enumerate(self._checkboxes[index:], start=index):\n                cb.index = i\n                pos = cb.doc_position\n                if pos &lt; 0:\n                    continue\n                cursor.setPosition(pos)\n                cursor.setPosition(pos + 1, QTextCursor.MoveMode.KeepAnchor)\n                fmt = QTextCharFormat()\n                fmt.setObjectType(CHECKBOX_FORMAT_TYPE)\n                fmt.setProperty(CHECKBOX_CHECKED_PROP, cb.checked)\n                fmt.setProperty(CHECKBOX_INDEX_PROP, cb.index)\n                fmt.setVerticalAlignment(\n                    QTextCharFormat.VerticalAlignment.AlignBaseline\n                )\n                cursor.setCharFormat(fmt)\n        except Exception:\n            log.warning(\n                \"Failed to re-index checkboxes in document\", exc_info=True\n            )\n        finally:\n            cursor.endEditBlock()\n            doc.blockSignals(False)\n\n    def remove_last_checkbox(self) -&gt; bool:\n        \"\"\"Remove the last checkbox from the tracked list.\n\n        Used when the user presses Enter on an empty checkbox line to\n        terminate the list.\n\n        Returns:\n            True if a checkbox was removed, False if the list was empty.\n        \"\"\"\n        if not self._checkboxes:\n            return False\n        self._checkboxes.pop()\n        return True\n\n    def to_markdown(self) -&gt; str:\n        \"\"\"Reconstruct markdown with current checkbox states.\n\n        Returns:\n            GitHub-flavored markdown string with checkbox syntax.\n        \"\"\"\n        if not self._checkboxes:\n            return self._text_edit.toMarkdown(MD_DIALECT)\n\n        # Get current text and replace placeholders with checkbox syntax\n        # we use toMarkdown() to make sure the other formatted items have\n        # already been dealt with.\n        text = self._text_edit.toMarkdown(MD_DIALECT)\n        lines = text.split(\"\\n\")\n        result_lines: List[str] = []\n\n        checkbox_iter = iter(self._checkboxes)\n        current_cb = next(checkbox_iter, None)\n\n        for line in lines:\n            if \"\\ufffc\" in line and current_cb:\n                # Replace \"  \\ufffc \" with prefix + checkbox syntax\n                checked_char = \"x\" if current_cb.checked else \" \"\n                # Remove the spaces before \\ufffc and add the proper prefix\n                line = _PH_RE.sub(\n                    f\"{current_cb.prefix}[{checked_char}] \", line, count=1\n                )\n                current_cb = next(checkbox_iter, None)\n            result_lines.append(line)\n\n        return \"\\n\".join(result_lines)\n\n    @property\n    def checkboxes(self) -&gt; List[CheckboxItem]:\n        \"\"\"Get the list of checkbox items.\n\n        Returns:\n            List of CheckboxItem objects.\n        \"\"\"\n        return self._checkboxes.copy()\n\n    def has_checkboxes(self) -&gt; bool:\n        \"\"\"Check if the document contains any checkboxes.\n\n        Returns:\n            True if there are checkboxes, False otherwise.\n        \"\"\"\n        return bool(self._checkboxes)\n\n    @staticmethod\n    def contains_checkboxes(markdown: str) -&gt; bool:\n        \"\"\"Check if markdown text contains checkbox syntax.\n\n        Args:\n            markdown: The markdown string to check.\n\n        Returns:\n            True if checkbox syntax is found, False otherwise.\n        \"\"\"\n        return bool(CheckboxHandler.CHECKBOX_PATTERN.search(markdown))\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.checkboxes","title":"<code>checkboxes</code>  <code>property</code>","text":"<p>Get the list of checkbox items.</p> <p>Returns:</p> Type Description <code>List[CheckboxItem]</code> <p>List of CheckboxItem objects.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.__init__","title":"<code>__init__(text_edit, parent=None)</code>","text":"<p>Initialize the checkbox handler.</p> <p>Parameters:</p> Name Type Description Default <code>text_edit</code> <code>QTextEdit</code> <p>The QTextEdit widget to manage checkboxes for.</p> required <code>parent</code> <code>QObject | None</code> <p>Optional parent QObject.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def __init__(self, text_edit: QTextEdit, parent: QObject | None = None):\n    \"\"\"Initialize the checkbox handler.\n\n    Args:\n        text_edit: The QTextEdit widget to manage checkboxes for.\n        parent: Optional parent QObject.\n    \"\"\"\n    super().__init__(parent)\n    self._text_edit = text_edit\n    self._checkboxes: List[CheckboxItem] = []\n    self._checkbox_object: CheckboxTextObject | None = None\n    self._original_markdown: str = \"\"\n    self._register_handler()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.add_checkbox","title":"<code>add_checkbox(checked=False, prefix='- ', doc_position=-1)</code>","text":"<p>Append a new checkbox to the tracked list.</p> <p>This is the public API for adding a checkbox programmatically (e.g. when the user presses Enter on a checkbox line or clicks the checklist toolbar button).  The caller is responsible for inserting the actual <code>\\ufffc</code> character into the document and then updating :attr:<code>CheckboxItem.doc_position</code>.</p> <p>Parameters:</p> Name Type Description Default <code>checked</code> <code>bool</code> <p>Initial checked state.</p> <code>False</code> <code>prefix</code> <code>str</code> <p>Markdown list prefix (e.g. <code>\"- \"</code>).</p> <code>'- '</code> <code>doc_position</code> <code>int</code> <p>Document character position of the <code>\\ufffc</code> object, or <code>-1</code> if not yet known.</p> <code>-1</code> <p>Returns:</p> Type Description <code>CheckboxItem</code> <p>The newly created :class:<code>CheckboxItem</code>.</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def add_checkbox(\n    self,\n    checked: bool = False,\n    prefix: str = \"- \",\n    doc_position: int = -1,\n) -&gt; CheckboxItem:\n    \"\"\"Append a new checkbox to the tracked list.\n\n    This is the public API for adding a checkbox programmatically\n    (e.g. when the user presses Enter on a checkbox line or clicks\n    the checklist toolbar button).  The caller is responsible for\n    inserting the actual ``\\\\ufffc`` character into the document and\n    then updating :attr:`CheckboxItem.doc_position`.\n\n    Args:\n        checked: Initial checked state.\n        prefix: Markdown list prefix (e.g. ``\"- \"``).\n        doc_position: Document character position of the ``\\\\ufffc``\n            object, or ``-1`` if not yet known.\n\n    Returns:\n        The newly created :class:`CheckboxItem`.\n    \"\"\"\n    new_index = len(self._checkboxes)\n    item = CheckboxItem(\n        index=new_index,\n        checked=checked,\n        text=\"\",\n        line_number=-1,\n        prefix=prefix,\n        doc_position=doc_position,\n    )\n    self._checkboxes.append(item)\n    return item\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.contains_checkboxes","title":"<code>contains_checkboxes(markdown)</code>  <code>staticmethod</code>","text":"<p>Check if markdown text contains checkbox syntax.</p> <p>Parameters:</p> Name Type Description Default <code>markdown</code> <code>str</code> <p>The markdown string to check.</p> required <p>Returns:</p> Type Description <code>bool</code> <p>True if checkbox syntax is found, False otherwise.</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>@staticmethod\ndef contains_checkboxes(markdown: str) -&gt; bool:\n    \"\"\"Check if markdown text contains checkbox syntax.\n\n    Args:\n        markdown: The markdown string to check.\n\n    Returns:\n        True if checkbox syntax is found, False otherwise.\n    \"\"\"\n    return bool(CheckboxHandler.CHECKBOX_PATTERN.search(markdown))\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.find_checkbox_at_click","title":"<code>find_checkbox_at_click(click_pos, content_offset=None)</code>","text":"<p>Find the checkbox hit by a viewport click using stored positions.</p> <p>Uses the cached <code>doc_position</code> on each :class:<code>CheckboxItem</code> instead of scanning the full document text, making hit-testing O(n) in the number of checkboxes rather than O(len(document)).</p> <p>Parameters:</p> Name Type Description Default <code>click_pos</code> <code>'QPoint'</code> <p>Click position in viewport coordinates.</p> required <code>content_offset</code> <code>'QPoint | None'</code> <p>Optional scroll offset (x, y) as a QPoint. Defaults to (0, 0) when not provided.</p> <code>None</code> <p>Returns:</p> Type Description <code>Optional[Tuple[bool, Optional[int]]]</code> <p><code>(True, doc_position + 1)</code> when the click lands on a checkbox,</p> <code>Optional[Tuple[bool, Optional[int]]]</code> <p><code>(False, None)</code> otherwise.</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def find_checkbox_at_click(\n    self, click_pos: \"QPoint\", content_offset: \"QPoint | None\" = None\n) -&gt; Optional[Tuple[bool, Optional[int]]]:\n    \"\"\"Find the checkbox hit by a viewport click using stored positions.\n\n    Uses the cached ``doc_position`` on each :class:`CheckboxItem`\n    instead of scanning the full document text, making hit-testing O(n)\n    in the number of checkboxes rather than O(len(document)).\n\n    Args:\n        click_pos: Click position in viewport coordinates.\n        content_offset: Optional scroll offset (x, y) as a QPoint.\n            Defaults to (0, 0) when not provided.\n\n    Returns:\n        ``(True, doc_position + 1)`` when the click lands on a checkbox,\n        ``(False, None)`` otherwise.\n    \"\"\"\n    if not self._checkboxes:\n        return False, None\n\n    doc = self._text_edit.document()\n    ox = content_offset.x() if content_offset else 0\n    oy = content_offset.y() if content_offset else 0\n\n    for cb in self._checkboxes:\n        pos = cb.doc_position\n        if pos &lt; 0:\n            continue\n\n        cursor = QTextCursor(doc)\n        cursor.setPosition(pos)\n        block = cursor.block()\n        block_layout = block.layout()\n\n        if not block_layout:\n            continue\n\n        rel_pos = pos - block.position()\n        line = block_layout.lineForTextPosition(rel_pos)\n        if not line.isValid():\n            continue\n\n        x1 = line.cursorToX(rel_pos)[0]  # type: ignore[index]\n        x2 = line.cursorToX(rel_pos + 1)[0]  # type: ignore[index]\n        y = line.y() + block_layout.position().y()\n        h = line.height()\n\n        rect = QRectF(x1 + ox, y + oy, x2 - x1, h)\n        if rect.contains(QPointF(click_pos)):\n            return True, pos + 1\n\n    return False, None\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.get_checkbox_at_position","title":"<code>get_checkbox_at_position(pos)</code>","text":"<p>Get the checkbox index at the given document position.</p> <p>Parameters:</p> Name Type Description Default <code>pos</code> <code>int</code> <p>Position in the document (one past the \\ufffc char).</p> required <p>Returns:</p> Type Description <code>int | None</code> <p>Checkbox index if found, None otherwise.</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def get_checkbox_at_position(self, pos: int) -&gt; int | None:\n    \"\"\"Get the checkbox index at the given document position.\n\n    Args:\n        pos: Position in the document (one past the \\\\ufffc char).\n\n    Returns:\n        Checkbox index if found, None otherwise.\n    \"\"\"\n    doc = self._text_edit.document()\n    cursor = QTextCursor(doc)\n    cursor.setPosition(pos)\n    fmt = cursor.charFormat()\n    fmt_type = fmt.objectType()\n\n    if fmt_type == CHECKBOX_FORMAT_TYPE:\n        return fmt.property(CHECKBOX_INDEX_PROP)\n    return None\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.has_checkboxes","title":"<code>has_checkboxes()</code>","text":"<p>Check if the document contains any checkboxes.</p> <p>Returns:</p> Type Description <code>bool</code> <p>True if there are checkboxes, False otherwise.</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def has_checkboxes(self) -&gt; bool:\n    \"\"\"Check if the document contains any checkboxes.\n\n    Returns:\n        True if there are checkboxes, False otherwise.\n    \"\"\"\n    return bool(self._checkboxes)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.parse_and_render","title":"<code>parse_and_render(markdown)</code>","text":"<p>Parse markdown and render checkboxes in the document.</p> <p>Extracts checkbox items from markdown, stores their state, and renders them as custom text objects with icons.</p> <p>Parameters:</p> Name Type Description Default <code>markdown</code> <code>str</code> <p>The markdown string containing checkboxes.</p> required Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def parse_and_render(self, markdown: str) -&gt; None:\n    \"\"\"Parse markdown and render checkboxes in the document.\n\n    Extracts checkbox items from markdown, stores their state,\n    and renders them as custom text objects with icons.\n\n    Args:\n        markdown: The markdown string containing checkboxes.\n    \"\"\"\n    self._original_markdown = markdown\n    self._checkboxes.clear()\n\n    # Find all checkbox patterns\n    lines = markdown.split(\"\\n\")\n    processed_lines: List[str] = []\n    checkbox_index = 0\n\n    for line_num, line in enumerate(lines):\n        match = self.CHECKBOX_PATTERN.match(line)\n        if match:\n            prefix = match.group(1)\n            checked_char = match.group(2)\n            text = match.group(3)\n            is_checked = checked_char.lower() == \"x\"\n\n            # Store checkbox info (doc_position filled after insertion)\n            self._checkboxes.append(\n                CheckboxItem(\n                    index=checkbox_index,\n                    checked=is_checked,\n                    text=text,\n                    line_number=line_num,\n                    prefix=prefix,\n                )\n            )\n\n            # Replace checkbox syntax with placeholder\n            # We'll insert the actual object after setting plain text\n            processed_lines.append(f\"{prefix}\\ufffc {text}\")\n            checkbox_index += 1\n        else:\n            processed_lines.append(line)\n\n    # Set the processed text\n    processed_text = \"\\n\".join(processed_lines)\n    self._text_edit.setMarkdown(processed_text)\n    self._remove_list_bullets()\n\n    # Now insert checkbox objects at placeholder positions\n    self._insert_checkbox_objects()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.remove_checkbox","title":"<code>remove_checkbox(index)</code>","text":"<p>Remove a checkbox from the tracked list.</p> <p>Re-indexes the Python list and patches the stale <code>CHECKBOX_INDEX_PROP</code> values stored in the live <code>QTextDocument</code> so that subsequent hit-tests via :meth:<code>get_checkbox_at_position</code> return correct indices.</p> <p>Parameters:</p> Name Type Description Default <code>index</code> <code>int</code> <p>The index of the checkbox to remove.</p> required Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def remove_checkbox(self, index: int) -&gt; None:\n    \"\"\"Remove a checkbox from the tracked list.\n\n    Re-indexes the Python list **and** patches the stale\n    ``CHECKBOX_INDEX_PROP`` values stored in the live\n    ``QTextDocument`` so that subsequent hit-tests via\n    :meth:`get_checkbox_at_position` return correct indices.\n\n    Args:\n        index: The index of the checkbox to remove.\n    \"\"\"\n    if not 0 &lt;= index &lt; len(self._checkboxes):\n        return\n\n    self._checkboxes.pop(index)\n\n    # Re-index the Python list and sync each affected document char format.\n    doc = self._text_edit.document()\n    doc.blockSignals(True)\n    cursor = QTextCursor(doc)\n    cursor.beginEditBlock()\n    try:\n        for i, cb in enumerate(self._checkboxes[index:], start=index):\n            cb.index = i\n            pos = cb.doc_position\n            if pos &lt; 0:\n                continue\n            cursor.setPosition(pos)\n            cursor.setPosition(pos + 1, QTextCursor.MoveMode.KeepAnchor)\n            fmt = QTextCharFormat()\n            fmt.setObjectType(CHECKBOX_FORMAT_TYPE)\n            fmt.setProperty(CHECKBOX_CHECKED_PROP, cb.checked)\n            fmt.setProperty(CHECKBOX_INDEX_PROP, cb.index)\n            fmt.setVerticalAlignment(\n                QTextCharFormat.VerticalAlignment.AlignBaseline\n            )\n            cursor.setCharFormat(fmt)\n    except Exception:\n        log.warning(\n            \"Failed to re-index checkboxes in document\", exc_info=True\n        )\n    finally:\n        cursor.endEditBlock()\n        doc.blockSignals(False)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.remove_last_checkbox","title":"<code>remove_last_checkbox()</code>","text":"<p>Remove the last checkbox from the tracked list.</p> <p>Used when the user presses Enter on an empty checkbox line to terminate the list.</p> <p>Returns:</p> Type Description <code>bool</code> <p>True if a checkbox was removed, False if the list was empty.</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def remove_last_checkbox(self) -&gt; bool:\n    \"\"\"Remove the last checkbox from the tracked list.\n\n    Used when the user presses Enter on an empty checkbox line to\n    terminate the list.\n\n    Returns:\n        True if a checkbox was removed, False if the list was empty.\n    \"\"\"\n    if not self._checkboxes:\n        return False\n    self._checkboxes.pop()\n    return True\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.to_markdown","title":"<code>to_markdown()</code>","text":"<p>Reconstruct markdown with current checkbox states.</p> <p>Returns:</p> Type Description <code>str</code> <p>GitHub-flavored markdown string with checkbox syntax.</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def to_markdown(self) -&gt; str:\n    \"\"\"Reconstruct markdown with current checkbox states.\n\n    Returns:\n        GitHub-flavored markdown string with checkbox syntax.\n    \"\"\"\n    if not self._checkboxes:\n        return self._text_edit.toMarkdown(MD_DIALECT)\n\n    # Get current text and replace placeholders with checkbox syntax\n    # we use toMarkdown() to make sure the other formatted items have\n    # already been dealt with.\n    text = self._text_edit.toMarkdown(MD_DIALECT)\n    lines = text.split(\"\\n\")\n    result_lines: List[str] = []\n\n    checkbox_iter = iter(self._checkboxes)\n    current_cb = next(checkbox_iter, None)\n\n    for line in lines:\n        if \"\\ufffc\" in line and current_cb:\n            # Replace \"  \\ufffc \" with prefix + checkbox syntax\n            checked_char = \"x\" if current_cb.checked else \" \"\n            # Remove the spaces before \\ufffc and add the proper prefix\n            line = _PH_RE.sub(\n                f\"{current_cb.prefix}[{checked_char}] \", line, count=1\n            )\n            current_cb = next(checkbox_iter, None)\n        result_lines.append(line)\n\n    return \"\\n\".join(result_lines)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxHandler.toggle_checkbox","title":"<code>toggle_checkbox(index)</code>","text":"<p>Toggle a checkbox by its index.</p> <p>Parameters:</p> Name Type Description Default <code>index</code> <code>int</code> <p>The index of the checkbox to toggle.</p> required <p>Returns:</p> Type Description <code>bool</code> <p>True if the checkbox was toggled, False otherwise.</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def toggle_checkbox(self, index: int) -&gt; bool:\n    \"\"\"Toggle a checkbox by its index.\n\n    Args:\n        index: The index of the checkbox to toggle.\n\n    Returns:\n        True if the checkbox was toggled, False otherwise.\n    \"\"\"\n    if not 0 &lt;= index &lt; len(self._checkboxes):\n        return False\n\n    # Toggle the state\n    self._checkboxes[index].checked = not self._checkboxes[index].checked\n\n    # Update the document\n    self._update_checkbox_in_document(index)\n\n    # Emit signal\n    self.checklist_changed.emit()\n    return True\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxItem","title":"<code>CheckboxItem</code>  <code>dataclass</code>","text":"<p>Represents a checkbox item in the document.</p> <p>Attributes:</p> Name Type Description <code>index</code> <code>int</code> <p>Unique index of the checkbox.</p> <code>checked</code> <code>bool</code> <p>Whether the checkbox is checked.</p> <code>text</code> <code>str</code> <p>Text following the checkbox.</p> <code>line_number</code> <code>int</code> <p>Line number in the original markdown.</p> <code>prefix</code> <code>str</code> <p>Characters before the checkbox (e.g., \"- \", \"* \").</p> <code>doc_position</code> <code>int</code> <p>Character position of the \\ufffc object in the document, or -1 if not yet placed.</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>@dataclass\nclass CheckboxItem:\n    \"\"\"Represents a checkbox item in the document.\n\n    Attributes:\n        index: Unique index of the checkbox.\n        checked: Whether the checkbox is checked.\n        text: Text following the checkbox.\n        line_number: Line number in the original markdown.\n        prefix: Characters before the checkbox (e.g., \"- \", \"* \").\n        doc_position: Character position of the \\\\ufffc object in the\n            document, or -1 if not yet placed.\n    \"\"\"\n\n    index: int\n    checked: bool\n    text: str\n    line_number: int\n    prefix: str = \"- \"\n    doc_position: int = field(default=-1)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxTextObject","title":"<code>CheckboxTextObject</code>","text":"<p>               Bases: <code>QPyTextObject</code></p> <p>Custom text object for rendering checkbox icons in QTextDocument.</p> <p>Uses Material icons to render checkboxes: - Unchecked: white radio_button_unchecked - Checked: green check_circle</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>class CheckboxTextObject(QPyTextObject):\n    \"\"\"Custom text object for rendering checkbox icons in QTextDocument.\n\n    Uses Material icons to render checkboxes:\n    - Unchecked: white radio_button_unchecked\n    - Checked: green check_circle\n    \"\"\"\n\n    def __init__(self, parent: QObject | None = None):\n        super().__init__(parent)\n        self._icon_cache: dict[bool, QPixmap] = {}\n\n    def intrinsicSize(\n        self,\n        doc: QTextDocument,\n        posInDocument: int,\n        format: QTextFormat,\n    ) -&gt; QSizeF:\n        \"\"\"Return the size of the checkbox icon.\n\n        Args:\n            doc: The document containing the object.\n            posInDocument: Position in the document.\n            format: The text format of the object.\n\n        Returns:\n            Size of the checkbox icon based on font size.\n        \"\"\"\n        font = doc.defaultFont()\n        size = max(font.pointSize() * 1.4, 14)\n        return QSizeF(size, size)\n\n    def drawObject(\n        self,\n        painter: QPainter,\n        rect: Union[QRectF, QRect],\n        doc: QTextDocument,\n        posInDocument: int,\n        format: QTextFormat,\n    ) -&gt; None:\n        \"\"\"Draw the checkbox icon.\n\n        Args:\n            painter: The painter to draw with.\n            rect: The rectangle to draw in.\n            doc: The document containing the object.\n            posInDocument: Position in the document.\n            format: The text format containing checkbox state.\n        \"\"\"\n        is_checked = format.property(CHECKBOX_CHECKED_PROP)\n\n        if is_checked:\n            icon = get_icon(CHECKED_ICON, color=CHECKED_COLOR)\n        else:\n            icon = get_icon(UNCHECKED_ICON, color=UNCHECKED_COLOR)\n\n        size = int(min(rect.width(), rect.height()))\n        pixmap = icon.pixmap(size, size)\n\n        # Vertically center the icon relative to text ascent\n        font_metrics = QFontMetrics(doc.defaultFont())\n        ascent = font_metrics.ascent()\n        y_offset = (ascent - size) // 3\n        draw_point = rect.topLeft().toPoint() + QPoint(0, -y_offset)\n\n        painter.drawPixmap(draw_point, pixmap)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxTextObject.drawObject","title":"<code>drawObject(painter, rect, doc, posInDocument, format)</code>","text":"<p>Draw the checkbox icon.</p> <p>Parameters:</p> Name Type Description Default <code>painter</code> <code>QPainter</code> <p>The painter to draw with.</p> required <code>rect</code> <code>Union[QRectF, QRect]</code> <p>The rectangle to draw in.</p> required <code>doc</code> <code>QTextDocument</code> <p>The document containing the object.</p> required <code>posInDocument</code> <code>int</code> <p>Position in the document.</p> required <code>format</code> <code>QTextFormat</code> <p>The text format containing checkbox state.</p> required Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def drawObject(\n    self,\n    painter: QPainter,\n    rect: Union[QRectF, QRect],\n    doc: QTextDocument,\n    posInDocument: int,\n    format: QTextFormat,\n) -&gt; None:\n    \"\"\"Draw the checkbox icon.\n\n    Args:\n        painter: The painter to draw with.\n        rect: The rectangle to draw in.\n        doc: The document containing the object.\n        posInDocument: Position in the document.\n        format: The text format containing checkbox state.\n    \"\"\"\n    is_checked = format.property(CHECKBOX_CHECKED_PROP)\n\n    if is_checked:\n        icon = get_icon(CHECKED_ICON, color=CHECKED_COLOR)\n    else:\n        icon = get_icon(UNCHECKED_ICON, color=UNCHECKED_COLOR)\n\n    size = int(min(rect.width(), rect.height()))\n    pixmap = icon.pixmap(size, size)\n\n    # Vertically center the icon relative to text ascent\n    font_metrics = QFontMetrics(doc.defaultFont())\n    ascent = font_metrics.ascent()\n    y_offset = (ascent - size) // 3\n    draw_point = rect.topLeft().toPoint() + QPoint(0, -y_offset)\n\n    painter.drawPixmap(draw_point, pixmap)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/checkbox_handler.html#client.ayon_ui_qt.components.checkbox_handler.CheckboxTextObject.intrinsicSize","title":"<code>intrinsicSize(doc, posInDocument, format)</code>","text":"<p>Return the size of the checkbox icon.</p> <p>Parameters:</p> Name Type Description Default <code>doc</code> <code>QTextDocument</code> <p>The document containing the object.</p> required <code>posInDocument</code> <code>int</code> <p>Position in the document.</p> required <code>format</code> <code>QTextFormat</code> <p>The text format of the object.</p> required <p>Returns:</p> Type Description <code>QSizeF</code> <p>Size of the checkbox icon based on font size.</p> Source code in <code>client/ayon_ui_qt/components/checkbox_handler.py</code> <pre><code>def intrinsicSize(\n    self,\n    doc: QTextDocument,\n    posInDocument: int,\n    format: QTextFormat,\n) -&gt; QSizeF:\n    \"\"\"Return the size of the checkbox icon.\n\n    Args:\n        doc: The document containing the object.\n        posInDocument: Position in the document.\n        format: The text format of the object.\n\n    Returns:\n        Size of the checkbox icon based on font size.\n    \"\"\"\n    font = doc.defaultFont()\n    size = max(font.pointSize() * 1.4, 14)\n    return QSizeF(size, size)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html","title":"combo_box","text":"<p>Combo-box components for the AYON UI Qt library.</p> <p>This module provides :class:<code>AYComboBox</code>, a styled :class:<code>QComboBox</code> subclass that supports per-item coloured icons, a short-text display mode, and an icon-only display mode via :class:<code>~ayon_ui_qt.data_models.MenuSize</code>.</p> <p>It also exposes :class:<code>AYComboBoxModel</code>, the default :class:<code>QStandardItemModel</code> subclass that adds two extra item-data roles:</p> <ul> <li><code>ShortTextRole</code> - an abbreviated label shown when the combo-box is in   :attr:<code>~ayon_ui_qt.data_models.MenuSize.Short</code> mode.</li> <li><code>IconNameRole</code> - the Material Symbol icon name used to regenerate icons   when the inverted colour mode is toggled.</li> </ul> <p>A drop-in sample dataset :data:<code>ALL_STATUSES</code> is included for quick prototyping and automated tests.</p> <p>Typical usage::</p> <pre><code>from ayon_ui_qt.components.combo_box import AYComboBox, ALL_STATUSES\n\ncombo = AYComboBox(parent=my_widget, items=ALL_STATUSES)\ncombo.set_size(\"short\")   # or MenuSize.Short\ncombo.set_inverted(True)\n</code></pre> <p>Custom model usage (must expose <code>ShortTextRole</code> and <code>IconNameRole</code>)::</p> <pre><code>model = MyCustomModel(parent=combo)\ncombo.setModel(model)\n</code></pre> Note <p>When a custom model that does not expose <code>ShortTextRole</code> / <code>IconNameRole</code> is set via :meth:<code>AYComboBox.setModel</code>, the widget falls back to displaying <code>\"&lt; INCOMPATIBLE MODEL &gt;\"</code> in short mode and raises :exc:<code>RuntimeError</code> when :meth:<code>AYComboBox.add_item</code> or :meth:<code>AYComboBox.update_items</code> is called.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html#client.ayon_ui_qt.components.combo_box.ALL_STATUSES","title":"<code>ALL_STATUSES = [{'text': 'Not ready', 'short_text': 'NRD', 'icon': 'fiber_new', 'color': '#434a56'}, {'text': 'Ready to start', 'short_text': 'RDY', 'icon': 'timer', 'color': '#bababa'}, {'text': 'In progress', 'short_text': 'PRG', 'icon': 'play_arrow', 'color': '#3498db'}, {'text': 'Pending review', 'short_text': 'RVW', 'icon': 'visibility', 'color': '#ff9b0a'}, {'text': 'Approved', 'short_text': 'APP', 'icon': 'task_alt', 'color': '#00f0b4'}, {'text': 'On hold', 'short_text': 'HLD', 'icon': 'back_hand', 'color': '#fa6e46'}, {'text': 'Omitted', 'short_text': 'OMT', 'icon': 'block', 'color': '#cb1a1a'}]</code>  <code>module-attribute</code>","text":"<p>Sample status definitions for prototyping and tests.</p> <p>Each entry is a :class:<code>dict</code> with the following keys:</p> <ul> <li><code>\"text\"</code>       - Full display label shown in   :attr:<code>~ayon_ui_qt.data_models.MenuSize.Full</code> mode.</li> <li><code>\"short_text\"</code> - Abbreviated label (\u2264 3 chars) shown in   :attr:<code>~ayon_ui_qt.data_models.MenuSize.Short</code> mode.</li> <li><code>\"icon\"</code>       - Material Symbol icon name passed to <code>get_icon()</code>.</li> <li><code>\"color\"</code>      - Hex colour string used as the item foreground.</li> </ul>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html#client.ayon_ui_qt.components.combo_box.AYComboBox","title":"<code>AYComboBox</code>","text":"<p>               Bases: <code>QComboBox</code></p> <p>AYON-styled combo-box with icon, short-text, and inverted-colour support.</p> <p>:class:<code>AYComboBox</code> wraps :class:<code>QComboBox</code> and adds:</p> <ul> <li> <p>Three display modes controlled by   :class:<code>~ayon_ui_qt.data_models.MenuSize</code>:</p> </li> <li> <p><code>Full</code>  - shows the full item label (default).</p> </li> <li><code>Short</code> - shows the abbreviated <code>ShortTextRole</code> label.</li> <li> <p><code>Icon</code>  - hides the text and shows only the item icon.</p> </li> <li> <p>Inverted colour mode - swaps the icon foreground/background colours   so the icon appears on a coloured pill rather than a neutral background.</p> </li> <li>Placeholder text support for an empty selection state.</li> <li>Custom model support: any model that exposes <code>ShortTextRole</code> and   <code>IconNameRole</code> attributes is accepted. Models without those attributes   are flagged as incompatible; :meth:<code>add_item</code> and :meth:<code>update_items</code>   will raise :exc:<code>RuntimeError</code> when such a model is active.</li> </ul> <p>The default model is :class:<code>AYComboBoxModel</code>.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>Optional[QWidget]</code> <p>Optional parent widget.</p> <code>None</code> <code>items</code> <code>List[dict] | None</code> <p>Initial list of item dictionaries.  Each dict may contain:</p> <ul> <li><code>\"text\"</code> (required) - Display label.</li> <li><code>\"color\"</code>      - Hex foreground colour (default <code>\"#ffffff\"</code>).</li> <li><code>\"icon\"</code>       - Material Symbol icon name.</li> <li><code>\"short_text\"</code> - Abbreviated label for short mode   (default <code>\"&lt; UNDEFINED &gt;\"</code>).</li> </ul> <code>None</code> <code>size</code> <code>MenuSize | str</code> <p>Initial display mode.  Accepts a :class:<code>~ayon_ui_qt.data_models.MenuSize</code> value or its string equivalent (<code>\"full\"</code>, <code>\"short\"</code>, <code>\"icon\"</code>).</p> <code>Full</code> <code>height</code> <code>int</code> <p>Fixed maximum height in pixels (default <code>30</code>).</p> <code>30</code> <code>placeholder</code> <code>Optional[str]</code> <p>Placeholder string shown when no item is selected.</p> <code>None</code> <code>inverted</code> <code>bool</code> <p>When <code>True</code> the icon foreground and background colours are swapped (default <code>False</code>).</p> <code>False</code> <code>icon_size</code> <code>int</code> <p>Icon size in pixels (default <code>20</code>).</p> <code>20</code> <code>**kwargs</code> <p>Additional keyword arguments forwarded to :class:<code>QComboBox</code>.</p> <code>{}</code> Example <p>Basic usage with the built-in status list::</p> <pre><code>combo = AYComboBox(\n    parent=my_widget,\n    items=ALL_STATUSES,\n    size=MenuSize.Short,\n    placeholder=\"Select status\u2026\",\n)\ncombo.currentTextChanged.connect(on_status_changed)\n</code></pre> <p>Switching modes at runtime::</p> <pre><code>combo.set_size(\"icon\")\ncombo.set_inverted(True)\n</code></pre> Source code in <code>client/ayon_ui_qt/components/combo_box.py</code> <pre><code>class AYComboBox(QtWidgets.QComboBox):\n    \"\"\"AYON-styled combo-box with icon, short-text, and inverted-colour support.\n\n    :class:`AYComboBox` wraps :class:`QComboBox` and adds:\n\n    - **Three display modes** controlled by\n      :class:`~ayon_ui_qt.data_models.MenuSize`:\n\n      - ``Full``  - shows the full item label (default).\n      - ``Short`` - shows the abbreviated ``ShortTextRole`` label.\n      - ``Icon``  - hides the text and shows only the item icon.\n\n    - **Inverted colour mode** - swaps the icon foreground/background colours\n      so the icon appears on a coloured pill rather than a neutral background.\n    - **Placeholder text** support for an empty selection state.\n    - **Custom model** support: any model that exposes ``ShortTextRole`` and\n      ``IconNameRole`` attributes is accepted. Models without those attributes\n      are flagged as incompatible; :meth:`add_item` and :meth:`update_items`\n      will raise :exc:`RuntimeError` when such a model is active.\n\n    The default model is :class:`AYComboBoxModel`.\n\n    Args:\n        parent: Optional parent widget.\n        items: Initial list of item dictionaries.  Each dict may contain:\n\n            - ``\"text\"``       *(required)* - Display label.\n            - ``\"color\"``      - Hex foreground colour (default ``\"#ffffff\"``).\n            - ``\"icon\"``       - Material Symbol icon name.\n            - ``\"short_text\"`` - Abbreviated label for short mode\n              (default ``\"&lt; UNDEFINED &gt;\"``).\n\n        size: Initial display mode.  Accepts a\n            :class:`~ayon_ui_qt.data_models.MenuSize` value or its string\n            equivalent (``\"full\"``, ``\"short\"``, ``\"icon\"``).\n        height: Fixed maximum height in pixels (default ``30``).\n        placeholder: Placeholder string shown when no item is selected.\n        inverted: When ``True`` the icon foreground and background colours are\n            swapped (default ``False``).\n        icon_size: Icon size in pixels (default ``20``).\n        **kwargs: Additional keyword arguments forwarded to\n            :class:`QComboBox`.\n\n    Example:\n        Basic usage with the built-in status list::\n\n            combo = AYComboBox(\n                parent=my_widget,\n                items=ALL_STATUSES,\n                size=MenuSize.Short,\n                placeholder=\"Select status\u2026\",\n            )\n            combo.currentTextChanged.connect(on_status_changed)\n\n        Switching modes at runtime::\n\n            combo.set_size(\"icon\")\n            combo.set_inverted(True)\n    \"\"\"\n\n    Variants = QComboBoxVariants\n\n    def __init__(\n        self,\n        parent: Optional[QtWidgets.QWidget] = None,\n        items: List[dict] | None = None,\n        size: MenuSize | str = MenuSize.Full,\n        height: int = 30,\n        placeholder: Optional[str] = None,\n        inverted: bool = False,\n        icon_size: int = 20,\n        variant: Variants = Variants.Default,\n        **kwargs,\n    ) -&gt; None:\n        self._uses_incompatible_model = False\n        super().__init__(parent, **kwargs)\n        self._variant_str = variant.value\n        from ..style import get_ayon_style\n\n        self.setStyle(get_ayon_style())\n        self.setMouseTracking(True)\n        self.setMaximumHeight(height)\n\n        # Initialize properties\n        self._size: MenuSize = (\n            size if isinstance(size, MenuSize) else MenuSize(size)\n        )\n        self._height: int = height\n        self._inverted: bool = inverted\n        self._icon_size: int = icon_size\n        self._inverted_icons: dict[str, QIcon] = {}\n\n        if placeholder:\n            self.setPlaceholderText(placeholder)\n\n        # setup model\n        model = AYComboBoxModel(self)\n        self.setModel(model)\n\n        self.update_items(items)\n\n    def _assert_compatible_model(self) -&gt; None:\n        \"\"\"Raise :exc:`RuntimeError` when an incompatible model is active.\n\n        Called by :meth:`add_item` and :meth:`update_items` to guard against\n        direct item mutations when a custom model that does not expose\n        ``ShortTextRole`` / ``IconNameRole`` has been set via\n        :meth:`setModel`.\n        \"\"\"\n        if self._uses_incompatible_model:\n            raise RuntimeError(\n                \"Cannot modify items directly when a custom \"\n                \"model is in use. Modify the model instead.\"\n            )\n\n    def setModel(self, model: QtCore.QAbstractItemModel) -&gt; None:\n        \"\"\"Set the item model and detect compatibility with AYComboBox roles.\n\n        If *model* is not an :class:`AYComboBoxModel` instance **and** it\n        does not expose both ``ShortTextRole`` and ``IconNameRole``\n        attributes, it is marked as *incompatible*.  In that state:\n\n        - :meth:`add_item` and :meth:`update_items` will raise\n          :exc:`RuntimeError`.\n        - Short mode falls back to ``\"&lt; INCOMPATIBLE MODEL &gt;\"`` as the\n          displayed text.\n\n        Args:\n            model: The new item model to attach to the combo-box.\n        \"\"\"\n        mtype = type(model)\n        self._uses_incompatible_model = mtype is not AYComboBoxModel and (\n            not hasattr(model, \"IconNameRole\")\n            or not hasattr(model, \"ShortTextRole\")\n        )\n        super().setModel(model)\n\n    def _make_icon(\n        self,\n        fg_color: QColor,\n        bg_color: QColor,\n        icon_name: str | None,\n        inverted: bool = False,\n    ) -&gt; QIcon | None:\n        \"\"\"Assign a Material Symbol icon to *data_item*.\n\n        Reads the item's background and foreground colours and passes them\n        to ``get_icon()``.  When *inverted* mode is active the icon's normal\n        colour uses the **background** colour so the icon appears on a\n        coloured pill; otherwise it uses the foreground colour.\n\n        Does nothing when *icon_name* is ``None`` or an empty string.\n\n        Args:\n            fg_color: Icon color.\n            bg_color: Background color.\n            icon_name: A Material Symbol identifier (e.g. ``\"play_arrow\"``),\n                or ``None`` / ``\"\"`` to skip icon assignment.\n            inverted: When ``True``, the icon's normal colour is taken from\n                the item's **background** colour so it renders as a coloured\n                icon on a neutral background.  Defaults to ``False``.\n        \"\"\"\n        icon = None\n        if icon_name:\n            icon = get_icon(\n                icon_name,\n                color=bg_color if inverted else fg_color,\n                # TODO: add fill support to get_icon and pass self._icon_fill here\n            )\n        return icon\n\n    def _get_inverted_icon(self, default: QIcon) -&gt; QIcon:\n        \"\"\"Return the inverted-colour icon for the currently selected item.\n\n        Looks up the ``IconNameRole`` of the current item and returns a\n        cached inverted icon.  If the icon has not been generated yet it is\n        created via :meth:`_make_icon` with ``inverted=True`` and stored in\n        :attr:`_inverted_icons` for future calls.\n\n        Args:\n            default: Fallback icon returned when the current item has no\n                ``IconNameRole`` value.\n\n        Returns:\n            A :class:`QIcon` rendered with inverted colours, or *default*\n            when no icon name is available.\n        \"\"\"\n        idx = self.currentIndex()\n        if idx &lt; 0:\n            return default\n\n        icon_name = self.currentData(self.model().IconNameRole)\n        if not icon_name:\n            return default\n\n        fg = self.currentData(QtCore.Qt.ItemDataRole.ForegroundRole).color()\n        bg = self.currentData(QtCore.Qt.ItemDataRole.BackgroundRole).color()\n        key = f\"{icon_name}:{fg.name()}:{bg.name()}\"\n\n        if key not in self._inverted_icons:\n            self._inverted_icons[key] = (\n                self._make_icon(fg, bg, icon_name, inverted=True) or default\n            )\n\n        return self._inverted_icons[key]\n\n    def add_item(self, item: dict[str, str]):\n        \"\"\"Append a single item to the combo-box model.\n\n        Constructs a :class:`QStandardItem` from *item*, sets its foreground\n        colour, background colour (from the current palette), icon, short\n        text, and icon name, then appends it to the model.\n\n        Raises:\n            RuntimeError: If a custom incompatible model is currently set\n                (see :meth:`setModel`).\n\n        Args:\n            item: A dict with the following keys:\n\n                - ``\"text\"``       *(required)* - Display label.\n                - ``\"color\"``      - Hex foreground colour\n                  (default ``\"#ffffff\"``).\n                - ``\"icon\"``       - Material Symbol icon name.\n                - ``\"short_text\"`` - Abbreviated label stored in\n                  ``ShortTextRole`` (default ``\"&lt; UNDEFINED &gt;\"``).\n        \"\"\"\n        self._assert_compatible_model()\n\n        bg_color = self.palette().color(\n            QPalette.ColorGroup.Active, QPalette.ColorRole.Window\n        )\n        fg_color = QColor(item.get(\"color\", \"#ffffff\"))\n\n        text = item.get(\"text\")\n        if not text:\n            raise ValueError(\n                f\"Item dict must contain a non-empty 'text' key; got: {item!r}\"\n            )\n\n        data_item = QStandardItem(text)\n        data_item.setData(\n            QBrush(fg_color),\n            QtCore.Qt.ItemDataRole.ForegroundRole,\n        )\n        data_item.setData(\n            QBrush(bg_color), QtCore.Qt.ItemDataRole.BackgroundRole\n        )\n        icon = self._make_icon(fg_color, bg_color, item.get(\"icon\"))\n        if icon:\n            data_item.setIcon(icon)\n        data_item.setData(\n            item.get(\"short_text\", \"&lt; UNDEFINED &gt;\"),\n            self.model().ShortTextRole,\n        )  # type: ignore\n        data_item.setData(item.get(\"icon\"), self.model().IconNameRole)  # type: ignore\n        self.model().appendRow(data_item)  # type: ignore\n\n    def update_items(self, item_list: list[dict] | None = None):\n        \"\"\"Replace all items in the model with the provided list.\n\n        Clears the model and calls :meth:`add_item` for every entry in\n        *item_list*.  If *item_list* is ``None`` or empty the model is left\n        unchanged.\n\n        Raises:\n            RuntimeError: If a custom incompatible model is currently set\n                (see :meth:`setModel`).\n\n        Args:\n            item_list: List of item dicts as accepted by :meth:`add_item`.\n                Pass ``None`` or an empty list to keep the current items.\n        \"\"\"\n        if item_list:\n            self._assert_compatible_model()\n            self.model().clear()  # type: ignore\n            for item in item_list:\n                self.add_item(item)\n\n    def set_inverted(self, state: bool):\n        \"\"\"Toggle the inverted colour mode and schedule a repaint.\n\n        In *inverted* mode the icon's normal colour is drawn using the item's\n        **background** colour instead of its foreground colour, producing a\n        coloured icon on a neutral background.\n\n        Inverted icons are generated lazily on first paint via\n        :meth:`_get_inverted_icon` and cached in :attr:`_inverted_icons`.\n        Calling this method triggers a repaint so the change is visible\n        immediately.\n\n        Args:\n            state: ``True`` to enable inverted mode, ``False`` to disable.\n        \"\"\"\n        self._inverted = state\n        self.update()\n\n    def set_size(self, size: MenuSize | str):\n        \"\"\"Change the display mode and repaint the widget.\n\n        Args:\n            size: New display mode.  Accepts a\n                :class:`~ayon_ui_qt.data_models.MenuSize` value or its\n                lowercase string equivalent (``\"full\"``, ``\"short\"``,\n                ``\"icon\"``).\n        \"\"\"\n        self._size = (\n            size if isinstance(size, MenuSize) else MenuSize(size.lower())\n        )\n        self.update()\n\n    def sizeHint(self) -&gt; QtCore.QSize:\n        \"\"\"Return the preferred size for the combo-box.\n\n        Delegates to the AYON style's\n        :meth:`QStyle.sizeFromContents` so that the hint respects the\n        custom theme's metrics rather than the system default.\n\n        Returns:\n            The preferred :class:`QSize` for this widget.\n        \"\"\"\n        from ..style import get_ayon_style\n\n        option = QtWidgets.QStyleOptionComboBox()\n        self.initStyleOption(option)\n        return get_ayon_style().sizeFromContents(\n            QtWidgets.QStyle.ContentsType.CT_ComboBox,\n            option,\n            self.rect().size(),\n            self,\n        )\n\n    def _resolve_current_text(self, idx: int) -&gt; str | None:\n        \"\"\"Return the display text for the current item.\n\n        Args:\n            idx: The current combo-box index.\n\n        Returns:\n            The text to display, or ``None`` when the option should be left\n            unchanged (e.g. no item is selected and no placeholder applies).\n        \"\"\"\n        if idx &lt; 0:\n            return None\n\n        if self._size == MenuSize.Full:\n            return self.currentData(QtCore.Qt.ItemDataRole.DisplayRole)\n        if self._size == MenuSize.Short:\n            return (\n                self.currentData(self.model().ShortTextRole)\n                if hasattr(self.model(), \"ShortTextRole\")\n                else \"&lt; INCOMPATIBLE MODEL &gt;\"\n            )\n        return \"\"  # MenuSize.Icon\n\n    def paintEvent(self, arg__1: QPaintEvent) -&gt; None:\n        \"\"\"Render the combo-box using the AYON custom style.\n\n        Overrides the default :meth:`QComboBox.paintEvent` to:\n\n        1. Draw the combo-box frame/control via the AYON style.\n        2. Substitute placeholder text (rendered in ``placeholderText``\n           palette colour) when no item is selected.\n        3. Render the label according to the current\n           :class:`~ayon_ui_qt.data_models.MenuSize` mode:\n\n           - ``Full``  \u2192 item's full text.\n           - ``Short`` \u2192 item's ``ShortTextRole`` value, or\n             ``\"&lt; INCOMPATIBLE MODEL &gt;\"`` if the role is unavailable.\n           - ``Icon``  \u2192 empty string (icon only).\n\n        Args:\n            arg__1: The paint event delivered by Qt.\n        \"\"\"\n        from ..style import get_ayon_style\n\n        p = QPainter(self)\n        option = QtWidgets.QStyleOptionComboBox()\n        self.initStyleOption(option)\n\n        if self._inverted:\n            option.currentIcon = self._get_inverted_icon(option.currentIcon)\n\n        _style = get_ayon_style()\n        _style.drawComplexControl(\n            QtWidgets.QStyle.ComplexControl.CC_ComboBox, option, p, self\n        )\n\n        idx = self.currentIndex()\n\n        if idx &lt; 0 and self.placeholderText():\n            option.palette.setBrush(  # type: ignore\n                QPalette.ColorRole.ButtonText,\n                option.palette.placeholderText(),  # type: ignore\n            )\n            option.currentText = self.placeholderText()  # type: ignore\n\n        text = self._resolve_current_text(idx)\n        if text is not None:\n            option.currentText = text  # type: ignore\n\n        _style.drawControl(\n            QtWidgets.QStyle.ControlElement.CE_ComboBoxLabel,\n            option,\n            p,\n            self,\n        )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html#client.ayon_ui_qt.components.combo_box.AYComboBox.add_item","title":"<code>add_item(item)</code>","text":"<p>Append a single item to the combo-box model.</p> <p>Constructs a :class:<code>QStandardItem</code> from item, sets its foreground colour, background colour (from the current palette), icon, short text, and icon name, then appends it to the model.</p> <p>Raises:</p> Type Description <code>RuntimeError</code> <p>If a custom incompatible model is currently set (see :meth:<code>setModel</code>).</p> <p>Parameters:</p> Name Type Description Default <code>item</code> <code>dict[str, str]</code> <p>A dict with the following keys:</p> <ul> <li><code>\"text\"</code> (required) - Display label.</li> <li><code>\"color\"</code>      - Hex foreground colour   (default <code>\"#ffffff\"</code>).</li> <li><code>\"icon\"</code>       - Material Symbol icon name.</li> <li><code>\"short_text\"</code> - Abbreviated label stored in   <code>ShortTextRole</code> (default <code>\"&lt; UNDEFINED &gt;\"</code>).</li> </ul> required Source code in <code>client/ayon_ui_qt/components/combo_box.py</code> <pre><code>def add_item(self, item: dict[str, str]):\n    \"\"\"Append a single item to the combo-box model.\n\n    Constructs a :class:`QStandardItem` from *item*, sets its foreground\n    colour, background colour (from the current palette), icon, short\n    text, and icon name, then appends it to the model.\n\n    Raises:\n        RuntimeError: If a custom incompatible model is currently set\n            (see :meth:`setModel`).\n\n    Args:\n        item: A dict with the following keys:\n\n            - ``\"text\"``       *(required)* - Display label.\n            - ``\"color\"``      - Hex foreground colour\n              (default ``\"#ffffff\"``).\n            - ``\"icon\"``       - Material Symbol icon name.\n            - ``\"short_text\"`` - Abbreviated label stored in\n              ``ShortTextRole`` (default ``\"&lt; UNDEFINED &gt;\"``).\n    \"\"\"\n    self._assert_compatible_model()\n\n    bg_color = self.palette().color(\n        QPalette.ColorGroup.Active, QPalette.ColorRole.Window\n    )\n    fg_color = QColor(item.get(\"color\", \"#ffffff\"))\n\n    text = item.get(\"text\")\n    if not text:\n        raise ValueError(\n            f\"Item dict must contain a non-empty 'text' key; got: {item!r}\"\n        )\n\n    data_item = QStandardItem(text)\n    data_item.setData(\n        QBrush(fg_color),\n        QtCore.Qt.ItemDataRole.ForegroundRole,\n    )\n    data_item.setData(\n        QBrush(bg_color), QtCore.Qt.ItemDataRole.BackgroundRole\n    )\n    icon = self._make_icon(fg_color, bg_color, item.get(\"icon\"))\n    if icon:\n        data_item.setIcon(icon)\n    data_item.setData(\n        item.get(\"short_text\", \"&lt; UNDEFINED &gt;\"),\n        self.model().ShortTextRole,\n    )  # type: ignore\n    data_item.setData(item.get(\"icon\"), self.model().IconNameRole)  # type: ignore\n    self.model().appendRow(data_item)  # type: ignore\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html#client.ayon_ui_qt.components.combo_box.AYComboBox.paintEvent","title":"<code>paintEvent(arg__1)</code>","text":"<p>Render the combo-box using the AYON custom style.</p> <p>Overrides the default :meth:<code>QComboBox.paintEvent</code> to:</p> <ol> <li>Draw the combo-box frame/control via the AYON style.</li> <li>Substitute placeholder text (rendered in <code>placeholderText</code>    palette colour) when no item is selected.</li> <li> <p>Render the label according to the current    :class:<code>~ayon_ui_qt.data_models.MenuSize</code> mode:</p> </li> <li> <p><code>Full</code>  \u2192 item's full text.</p> </li> <li><code>Short</code> \u2192 item's <code>ShortTextRole</code> value, or      <code>\"&lt; INCOMPATIBLE MODEL &gt;\"</code> if the role is unavailable.</li> <li><code>Icon</code>  \u2192 empty string (icon only).</li> </ol> <p>Parameters:</p> Name Type Description Default <code>arg__1</code> <code>QPaintEvent</code> <p>The paint event delivered by Qt.</p> required Source code in <code>client/ayon_ui_qt/components/combo_box.py</code> <pre><code>def paintEvent(self, arg__1: QPaintEvent) -&gt; None:\n    \"\"\"Render the combo-box using the AYON custom style.\n\n    Overrides the default :meth:`QComboBox.paintEvent` to:\n\n    1. Draw the combo-box frame/control via the AYON style.\n    2. Substitute placeholder text (rendered in ``placeholderText``\n       palette colour) when no item is selected.\n    3. Render the label according to the current\n       :class:`~ayon_ui_qt.data_models.MenuSize` mode:\n\n       - ``Full``  \u2192 item's full text.\n       - ``Short`` \u2192 item's ``ShortTextRole`` value, or\n         ``\"&lt; INCOMPATIBLE MODEL &gt;\"`` if the role is unavailable.\n       - ``Icon``  \u2192 empty string (icon only).\n\n    Args:\n        arg__1: The paint event delivered by Qt.\n    \"\"\"\n    from ..style import get_ayon_style\n\n    p = QPainter(self)\n    option = QtWidgets.QStyleOptionComboBox()\n    self.initStyleOption(option)\n\n    if self._inverted:\n        option.currentIcon = self._get_inverted_icon(option.currentIcon)\n\n    _style = get_ayon_style()\n    _style.drawComplexControl(\n        QtWidgets.QStyle.ComplexControl.CC_ComboBox, option, p, self\n    )\n\n    idx = self.currentIndex()\n\n    if idx &lt; 0 and self.placeholderText():\n        option.palette.setBrush(  # type: ignore\n            QPalette.ColorRole.ButtonText,\n            option.palette.placeholderText(),  # type: ignore\n        )\n        option.currentText = self.placeholderText()  # type: ignore\n\n    text = self._resolve_current_text(idx)\n    if text is not None:\n        option.currentText = text  # type: ignore\n\n    _style.drawControl(\n        QtWidgets.QStyle.ControlElement.CE_ComboBoxLabel,\n        option,\n        p,\n        self,\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html#client.ayon_ui_qt.components.combo_box.AYComboBox.setModel","title":"<code>setModel(model)</code>","text":"<p>Set the item model and detect compatibility with AYComboBox roles.</p> <p>If model is not an :class:<code>AYComboBoxModel</code> instance and it does not expose both <code>ShortTextRole</code> and <code>IconNameRole</code> attributes, it is marked as incompatible.  In that state:</p> <ul> <li>:meth:<code>add_item</code> and :meth:<code>update_items</code> will raise   :exc:<code>RuntimeError</code>.</li> <li>Short mode falls back to <code>\"&lt; INCOMPATIBLE MODEL &gt;\"</code> as the   displayed text.</li> </ul> <p>Parameters:</p> Name Type Description Default <code>model</code> <code>QAbstractItemModel</code> <p>The new item model to attach to the combo-box.</p> required Source code in <code>client/ayon_ui_qt/components/combo_box.py</code> <pre><code>def setModel(self, model: QtCore.QAbstractItemModel) -&gt; None:\n    \"\"\"Set the item model and detect compatibility with AYComboBox roles.\n\n    If *model* is not an :class:`AYComboBoxModel` instance **and** it\n    does not expose both ``ShortTextRole`` and ``IconNameRole``\n    attributes, it is marked as *incompatible*.  In that state:\n\n    - :meth:`add_item` and :meth:`update_items` will raise\n      :exc:`RuntimeError`.\n    - Short mode falls back to ``\"&lt; INCOMPATIBLE MODEL &gt;\"`` as the\n      displayed text.\n\n    Args:\n        model: The new item model to attach to the combo-box.\n    \"\"\"\n    mtype = type(model)\n    self._uses_incompatible_model = mtype is not AYComboBoxModel and (\n        not hasattr(model, \"IconNameRole\")\n        or not hasattr(model, \"ShortTextRole\")\n    )\n    super().setModel(model)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html#client.ayon_ui_qt.components.combo_box.AYComboBox.set_inverted","title":"<code>set_inverted(state)</code>","text":"<p>Toggle the inverted colour mode and schedule a repaint.</p> <p>In inverted mode the icon's normal colour is drawn using the item's background colour instead of its foreground colour, producing a coloured icon on a neutral background.</p> <p>Inverted icons are generated lazily on first paint via :meth:<code>_get_inverted_icon</code> and cached in :attr:<code>_inverted_icons</code>. Calling this method triggers a repaint so the change is visible immediately.</p> <p>Parameters:</p> Name Type Description Default <code>state</code> <code>bool</code> <p><code>True</code> to enable inverted mode, <code>False</code> to disable.</p> required Source code in <code>client/ayon_ui_qt/components/combo_box.py</code> <pre><code>def set_inverted(self, state: bool):\n    \"\"\"Toggle the inverted colour mode and schedule a repaint.\n\n    In *inverted* mode the icon's normal colour is drawn using the item's\n    **background** colour instead of its foreground colour, producing a\n    coloured icon on a neutral background.\n\n    Inverted icons are generated lazily on first paint via\n    :meth:`_get_inverted_icon` and cached in :attr:`_inverted_icons`.\n    Calling this method triggers a repaint so the change is visible\n    immediately.\n\n    Args:\n        state: ``True`` to enable inverted mode, ``False`` to disable.\n    \"\"\"\n    self._inverted = state\n    self.update()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html#client.ayon_ui_qt.components.combo_box.AYComboBox.set_size","title":"<code>set_size(size)</code>","text":"<p>Change the display mode and repaint the widget.</p> <p>Parameters:</p> Name Type Description Default <code>size</code> <code>MenuSize | str</code> <p>New display mode.  Accepts a :class:<code>~ayon_ui_qt.data_models.MenuSize</code> value or its lowercase string equivalent (<code>\"full\"</code>, <code>\"short\"</code>, <code>\"icon\"</code>).</p> required Source code in <code>client/ayon_ui_qt/components/combo_box.py</code> <pre><code>def set_size(self, size: MenuSize | str):\n    \"\"\"Change the display mode and repaint the widget.\n\n    Args:\n        size: New display mode.  Accepts a\n            :class:`~ayon_ui_qt.data_models.MenuSize` value or its\n            lowercase string equivalent (``\"full\"``, ``\"short\"``,\n            ``\"icon\"``).\n    \"\"\"\n    self._size = (\n        size if isinstance(size, MenuSize) else MenuSize(size.lower())\n    )\n    self.update()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html#client.ayon_ui_qt.components.combo_box.AYComboBox.sizeHint","title":"<code>sizeHint()</code>","text":"<p>Return the preferred size for the combo-box.</p> <p>Delegates to the AYON style's :meth:<code>QStyle.sizeFromContents</code> so that the hint respects the custom theme's metrics rather than the system default.</p> <p>Returns:</p> Type Description <code>QSize</code> <p>The preferred :class:<code>QSize</code> for this widget.</p> Source code in <code>client/ayon_ui_qt/components/combo_box.py</code> <pre><code>def sizeHint(self) -&gt; QtCore.QSize:\n    \"\"\"Return the preferred size for the combo-box.\n\n    Delegates to the AYON style's\n    :meth:`QStyle.sizeFromContents` so that the hint respects the\n    custom theme's metrics rather than the system default.\n\n    Returns:\n        The preferred :class:`QSize` for this widget.\n    \"\"\"\n    from ..style import get_ayon_style\n\n    option = QtWidgets.QStyleOptionComboBox()\n    self.initStyleOption(option)\n    return get_ayon_style().sizeFromContents(\n        QtWidgets.QStyle.ContentsType.CT_ComboBox,\n        option,\n        self.rect().size(),\n        self,\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html#client.ayon_ui_qt.components.combo_box.AYComboBox.update_items","title":"<code>update_items(item_list=None)</code>","text":"<p>Replace all items in the model with the provided list.</p> <p>Clears the model and calls :meth:<code>add_item</code> for every entry in item_list.  If item_list is <code>None</code> or empty the model is left unchanged.</p> <p>Raises:</p> Type Description <code>RuntimeError</code> <p>If a custom incompatible model is currently set (see :meth:<code>setModel</code>).</p> <p>Parameters:</p> Name Type Description Default <code>item_list</code> <code>list[dict] | None</code> <p>List of item dicts as accepted by :meth:<code>add_item</code>. Pass <code>None</code> or an empty list to keep the current items.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/combo_box.py</code> <pre><code>def update_items(self, item_list: list[dict] | None = None):\n    \"\"\"Replace all items in the model with the provided list.\n\n    Clears the model and calls :meth:`add_item` for every entry in\n    *item_list*.  If *item_list* is ``None`` or empty the model is left\n    unchanged.\n\n    Raises:\n        RuntimeError: If a custom incompatible model is currently set\n            (see :meth:`setModel`).\n\n    Args:\n        item_list: List of item dicts as accepted by :meth:`add_item`.\n            Pass ``None`` or an empty list to keep the current items.\n    \"\"\"\n    if item_list:\n        self._assert_compatible_model()\n        self.model().clear()  # type: ignore\n        for item in item_list:\n            self.add_item(item)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html#client.ayon_ui_qt.components.combo_box.AYComboBoxModel","title":"<code>AYComboBoxModel</code>","text":"<p>               Bases: <code>QStandardItemModel</code></p> <p>Default item model for :class:<code>AYComboBox</code>.</p> <p>Extends :class:<code>QStandardItemModel</code> with two additional item-data roles required by :class:<code>AYComboBox</code> for short-text and icon-regeneration support.</p> <p>Attributes:</p> Name Type Description <code>ShortTextRole</code> <p>Custom data role (<code>UserRole + 1</code>) that stores the abbreviated label displayed in :attr:<code>~ayon_ui_qt.data_models.MenuSize.Short</code> mode.</p> <code>IconNameRole</code> <p>Custom data role (<code>UserRole + 2</code>) that stores the Material Symbol icon name so icons can be regenerated when the inverted colour mode changes.</p> Source code in <code>client/ayon_ui_qt/components/combo_box.py</code> <pre><code>class AYComboBoxModel(QStandardItemModel):\n    \"\"\"Default item model for :class:`AYComboBox`.\n\n    Extends :class:`QStandardItemModel` with two additional item-data roles\n    required by :class:`AYComboBox` for short-text and icon-regeneration\n    support.\n\n    Attributes:\n        ShortTextRole: Custom data role (``UserRole + 1``) that stores the\n            abbreviated label displayed in\n            :attr:`~ayon_ui_qt.data_models.MenuSize.Short` mode.\n        IconNameRole: Custom data role (``UserRole + 2``) that stores the\n            Material Symbol icon name so icons can be regenerated when the\n            *inverted* colour mode changes.\n    \"\"\"\n\n    ShortTextRole = QtCore.Qt.ItemDataRole.UserRole + 1\n    IconNameRole = QtCore.Qt.ItemDataRole.UserRole + 2\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/combo_box.html#client.ayon_ui_qt.components.combo_box.txt_color","title":"<code>txt_color(bg_color)</code>","text":"<p>Return a legible foreground colour for the given background colour.</p> <p>Uses the HSV value (brightness) component to decide between a light and a dark foreground:</p> <ul> <li>Backgrounds with <code>value &lt; 0.9</code> are considered dark \u2192 returns   <code>QColor(\"#eee\")</code> (near-white).</li> <li>Backgrounds with <code>value &gt;= 0.9</code> are considered light \u2192 returns   <code>QColor(\"#222\")</code> (near-black).</li> </ul> <p>Parameters:</p> Name Type Description Default <code>bg_color</code> <code>str | QColor</code> <p>Background colour as a CSS hex string (e.g. <code>\"#3498db\"</code>) or a :class:<code>QColor</code> instance.</p> required <p>Returns:</p> Name Type Description <code>A</code> <code>QColor</code> <p>class:<code>QColor</code> suitable for text rendered on bg_color.</p> Source code in <code>client/ayon_ui_qt/components/combo_box.py</code> <pre><code>def txt_color(bg_color: str | QColor) -&gt; QColor:\n    \"\"\"Return a legible foreground colour for the given background colour.\n\n    Uses the HSV *value* (brightness) component to decide between a light\n    and a dark foreground:\n\n    - Backgrounds with ``value &lt; 0.9`` are considered dark \u2192 returns\n      ``QColor(\"#eee\")`` (near-white).\n    - Backgrounds with ``value &gt;= 0.9`` are considered light \u2192 returns\n      ``QColor(\"#222\")`` (near-black).\n\n    Args:\n        bg_color: Background colour as a CSS hex string (e.g. ``\"#3498db\"``)\n            or a :class:`QColor` instance.\n\n    Returns:\n        A :class:`QColor` suitable for text rendered on *bg_color*.\n    \"\"\"\n    value = QColor(bg_color).valueF()\n    return QColor(\"#eee\") if value &lt; 0.9 else QColor(\"#222\")\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html","title":"comment","text":""},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYComment","title":"<code>AYComment</code>","text":"<p>               Bases: <code>AYContainer</code></p> <p>Enhanced comment widget that displays images from CommentModel.files.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>class AYComment(AYContainer):\n    \"\"\"Enhanced comment widget that displays images from CommentModel.files.\"\"\"\n\n    comment_deleted = Signal(object)\n    comment_edited = Signal(object)\n\n    def __init__(\n        self,\n        *args,\n        data: CommentModel | None = None,\n        user_list: list[User] | None = None,\n        **kwargs,\n    ):\n        self._data = data if data else CommentModel()\n        self._user_list: list[User] = user_list or []\n        self._bg_color = None\n        self._image_widgets = {}\n        self._attachments_built = False\n\n        super().__init__(\n            *args,\n            layout=AYContainer.Layout.VBox,\n            variant=AYContainer.Variants.Low,\n            bg_tint=\"\",  # keep neutral\n            margin=0,\n            layout_spacing=0,\n            layout_margin=1,\n            **kwargs,\n        )\n\n        self._build()\n\n        # configure\n        if self._data:\n            self.update_comment()\n\n        self.text_field.checklist_changed.connect(self._on_checklist_changed)\n\n    def update_comment(self, data: CommentModel | None = None):\n        prev_data = self._data\n        if data:\n            self._data = data\n        self.text_field.set_markdown(self._data.comment)\n        self.date.setText(self._data.short_date)\n        self.set_comment_category()\n        if not self._attachments_built or prev_data.files != self._data.files:\n            self.images_container.clear()\n            self._build_image_attachments()\n\n    def _build_top_bar(self):\n        self.user_icon = AYUserImage(\n            parent=self,\n            size=20,\n            src=self._data.user_src,\n            name=self._data.user_name,\n            full_name=self._data.user_full_name,\n            outline=False,\n        )\n        self.user_name = AYLabel(self._data.user_full_name, bold=True)\n        self.date = AYLabel(self._data.short_date, dim=True, rel_text_size=-2)\n        cntr = AYContainer(\n            layout=AYContainer.Layout.HBox,\n            variant=AYContainer.Variants.Low,\n            margin=0,\n            layout_spacing=8,\n        )\n        cntr.setContentsMargins(0, 0, 0, 4)\n        cntr.add_widget(self.user_icon)\n        cntr.add_widget(self.user_name)\n        cntr.addStretch()\n        cntr.add_widget(self.date)\n        return cntr\n\n    def _build_editor_toolbar(self):\n        lyt = AYHBoxLayout()\n        self.reaction = AYButton(\n            variant=AYButton.Variants.Nav_Small,\n            icon=\"add_reaction\",\n            icon_color=\"#888\",\n            tooltip=\"Not Implemented Yet !\",\n            parent=self,\n        )\n        self.cancel_edit = AYButton(\n            \"Cancel\", variant=AYButton.Variants.Nav, parent=self\n        )\n        self.save_edit = AYButton(\n            \"Save\", variant=AYButton.Variants.Filled, parent=self\n        )\n        lyt.addWidget(self.reaction)\n        lyt.addStretch(10)\n        lyt.addWidget(self.cancel_edit)\n        lyt.addWidget(self.save_edit)\n\n        self.cancel_edit.clicked.connect(self._cancel_edit)\n        self.cancel_edit.setVisible(False)\n        self.save_edit.clicked.connect(self._save_edit)\n        self.save_edit.setVisible(False)\n        return lyt\n\n    def _build_edit_buttons(self):\n        self.edit_frame = AYContainer(\n            layout=AYContainer.Layout.HBox,\n            bg_tint=self._data.category_color,\n            parent=self.top_line,\n        )\n        bsize = 22\n        self.del_button = AYButton(\n            variant=AYButton.Variants.Nav_Small, icon=\"delete\", parent=self\n        )\n        self.del_button.setFixedSize(bsize, bsize)\n        self.edit_button = AYButton(\n            variant=AYButton.Variants.Nav_Small,\n            icon=\"edit_square\",\n            parent=self,\n        )\n        self.edit_button.setFixedSize(bsize, bsize)\n        self.edit_frame.add_widget(self.del_button)\n        self.edit_frame.add_widget(self.edit_button)\n        self.top_line.addStretch(100)\n        self.top_line.add_widget(self.edit_frame)\n        self.edit_frame.setVisible(False)\n        self.del_button.clicked.connect(self._confirm_delete)\n        self.edit_button.clicked.connect(self._edit_comment)\n\n    def _build(self):\n        self.add_widget(self._build_top_bar())\n        self.text_field = AYCommentField(\n            self,\n            text=self._data.comment,\n            read_only=True,\n            user_list=self._user_list,\n            model=self._data,\n            variant=AYCommentField.Variants.High,\n        )\n\n        editor_lyt = AYContainer(\n            layout=AYContainer.Layout.VBox,\n            variant=AYContainer.Variants.High,\n            bg_tint=self._data.category_color,\n            layout_margin=4,\n        )\n        self.top_line = AYContainer(\n            layout=AYContainer.Layout.HBox,\n            variant=AYContainer.Variants.High,\n            bg_tint=self._data.category_color,\n        )\n        self.images_container = AYContainer(\n            layout=AYContainer.Layout.Flow,\n            variant=AYContainer.Variants.High,\n            bg_tint=self._data.category_color,\n            layout_spacing=4,\n            layout_margin=0,\n        )\n        self.images_container.setContentsMargins(0, 0, 0, 0)\n        self.top_line.setFixedHeight(20)\n        editor_lyt.add_widget(self.top_line, stretch=0)\n        editor_lyt.add_widget(self.images_container, stretch=0)\n        editor_lyt.add_widget(self.text_field, stretch=10)\n\n        editor_lyt.add_layout(self._build_editor_toolbar(), stretch=0)\n        self.add_widget(editor_lyt)\n        self._build_edit_buttons()\n\n    def _build_image_attachments(self):\n        \"\"\"Build and display image attachments as separate clickable widgets.\n\n        Supports gallery view: when multiple images are present, clicking\n        any thumbnail opens a GalleryDialog for navigating through all images.\n        \"\"\"\n        if (\n            not self._data\n            or not hasattr(self._data, \"files\")\n            or not self._data.files\n        ):\n            return\n\n        # First pass: collect all valid images for gallery view\n        valid_files = []\n        for file_model in self._data.files:\n            # Check if this file is marked as transparent in annotations\n            is_transparent = False\n            if hasattr(self._data, \"annotations\"):\n                for annotation in self._data.annotations:\n                    if file_model.id == annotation.transparent:\n                        is_transparent = True\n                        break\n\n            if is_transparent:\n                continue\n            # Check if file has local_path\n            if not hasattr(file_model, \"local_path\"):\n                continue\n\n            # Guard against empty path: Path(\"\") resolves to Path(\".\")\n            # which always exists (current directory), leading to errors when\n            # trying to cache it as an image.\n            local_path = file_model.local_path\n            if not local_path or not Path(local_path).exists():\n                # Register as None so refresh_image can create the widget\n                # once the background download completes.\n                self._image_widgets.setdefault(file_model.id, None)\n\n            valid_files.append(file_model)\n\n        # Build gallery images list for navigation\n        gallery_images = [\n            (\n                f.local_path,\n                f\"Frame {f.start_frame + f.frame - 1 if f.frame &gt; 0 else -1}\",\n            )\n            for f in valid_files\n        ]\n\n        # Second pass: create widgets with gallery support\n        for idx, file_model in enumerate(valid_files):\n            max_image_width = 100\n            max_image_height = 47\n\n            # coerce any invalid thumb path to None.\n            thumb_path = getattr(file_model, \"thumb_local_path\", None) or None\n\n            # frame sequences start at 1, so we need to subtract 1 to get the\n            # actual frame number.\n            # if frame is 0 or negative, we treat it as n/a. This happens when\n            # attaching a screenshot or external file.\n            frame = (\n                file_model.start_frame + file_model.frame - 1\n                if file_model.frame &gt; 0\n                else -1\n            )\n\n            # Create image widget with gallery support\n            image_widget = AYImageAttachment(\n                parent=self,\n                image_path=local_path,\n                thumb_path=thumb_path,\n                max_width=max_image_width,\n                max_height=max_image_height,\n                frame=frame,\n                gallery_images=gallery_images,\n                gallery_index=idx,\n            )\n\n            self.images_container.add_widget(image_widget)\n            self._image_widgets[file_model.id] = image_widget\n\n        # mark as built to avoid rebuilding on every update\n        self._attachments_built = True\n\n    def _edit_comment(self):\n        \"\"\"Make the field editable, hide the edit/del buttons and show\n        Save/Cancel.\"\"\"\n        self._show_edit_buttons(False)\n        self.text_field.setReadOnly(False)\n        self.cancel_edit.setVisible(True)\n        self.save_edit.setVisible(True)\n\n    def _cancel_edit(self):\n        \"\"\"Make the field read-only and restore text.\"\"\"\n        self.text_field.setReadOnly(True)\n        self.cancel_edit.setVisible(False)\n        self.save_edit.setVisible(False)\n        self.text_field.set_markdown(self._data.comment)\n        self._show_edit_buttons(True)\n\n    def _save_edit(self):\n        self.text_field.setReadOnly(True)\n        self.cancel_edit.setVisible(False)\n        self.save_edit.setVisible(False)\n        self._show_edit_buttons(True)\n        self._data.comment = self.text_field.as_markdown()\n        self.comment_edited.emit(self._data)\n\n    def _confirm_delete(self):\n        mb = QMessageBox(\n            text=\"Are you sure you want to delete this comment?\",\n            standardButtons=QMessageBox.StandardButton.Cancel\n            | QMessageBox.StandardButton.Yes,  # type: ignore\n            parent=self,\n        )\n        if mb.exec() == QMessageBox.StandardButton.Yes:\n            self.comment_deleted.emit(self._data)\n\n    def _show_edit_buttons(self, state):\n        \"\"\"show / hide edit buttons and position them.\"\"\"\n        if not self.text_field.isReadOnly():\n            return\n        self.edit_frame.setVisible(state)\n        if state:\n            fr = self.edit_frame.rect()\n            vr = self.text_field.visibleRegion().boundingRect()\n            self.edit_frame.move((vr.width() + vr.x()) - fr.width(), 0)\n\n    def set_comment_category(self):\n        if not self._data.category:\n            return\n        cat = AYLabel(\n            self._data.category,\n            icon_color=self._data.category_color,\n            variant=AYLabel.Variants.Badge,\n            rel_text_size=-2,\n        )\n        self.top_line.insert_widget(0, cat)\n\n    def enterEvent(self, event: QEnterEvent) -&gt; None:\n        self._show_edit_buttons(True)\n        return super().enterEvent(event)\n\n    def leaveEvent(self, event: QEvent) -&gt; None:\n        self._show_edit_buttons(False)\n        return super().leaveEvent(event)\n\n    def update_params(self, model: CommentModel):\n        if self._data:\n            self.user_icon.update_params(\n                self._data.user_src, self._data.user_full_name\n            )\n            self.user_name.setText(self._data.user_name)\n            self.date.setText(self._data.short_date)\n\n    def refresh_image(\n        self,\n        file_id: str,\n        filepath: str | None,\n        project_name: str,\n    ) -&gt; None:\n        \"\"\"Refresh image attachment widget once a file download completes.\n\n        Called by the activity stream when a background download finishes.\n        If the widget hasn't been created yet (path was unavailable at build\n        time), creates and adds it now.\n\n        Args:\n            file_id: The AYON file identifier.\n            filepath: Unused - paths are resolved from ImageCache.\n            project_name: AYON project name that owns the file, used to\n                build the cache key via\n                :func:`ayon_ui_qt.image_cache.make_activity_cache_key`.\n        \"\"\"\n        ic = ImageCache.get_instance()\n        image_attachment = self._image_widgets.get(file_id)\n\n        if image_attachment is None and file_id in self._image_widgets:\n            # Widget placeholder registered but not yet created - build it\n            # now that the download has completed.\n            image_path = (\n                ic.get_path(\n                    make_activity_cache_key(project_name, file_id),\n                )\n                or \"\"\n            )\n            thumb_path = ic.get_path(\n                make_activity_cache_key(\n                    project_name, file_id, is_thumbnail=True\n                )\n            )\n            if not image_path:\n                return  # Full-size not ready yet; thumbnail alone is enough\n            image_attachment = AYImageAttachment(\n                parent=self,\n                image_path=image_path,\n                thumb_path=thumb_path,\n                max_width=100,\n                max_height=47,\n            )\n            self.images_container.add_widget(image_attachment)\n            self._image_widgets[file_id] = image_attachment\n            return\n\n        if isinstance(image_attachment, AYImageAttachment):\n            if not image_attachment._thumb_path:\n                image_attachment._thumb_path = (\n                    ic.get_path(\n                        make_activity_cache_key(\n                            project_name, file_id, is_thumbnail=True\n                        )\n                    )\n                    or \"\"\n                )\n            if not image_attachment._image_path:\n                image_attachment._image_path = (\n                    ic.get_path(\n                        make_activity_cache_key(project_name, file_id),\n                    )\n                    or \"\"\n                )\n            if image_attachment._thumb_path or image_attachment._image_path:\n                image_attachment._load_thumbnail()\n\n    def _on_checklist_changed(self):\n        md = self.text_field.as_markdown()\n        self._data.comment = md\n        self.comment_edited.emit(self._data)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYComment.refresh_image","title":"<code>refresh_image(file_id, filepath, project_name)</code>","text":"<p>Refresh image attachment widget once a file download completes.</p> <p>Called by the activity stream when a background download finishes. If the widget hasn't been created yet (path was unavailable at build time), creates and adds it now.</p> <p>Parameters:</p> Name Type Description Default <code>file_id</code> <code>str</code> <p>The AYON file identifier.</p> required <code>filepath</code> <code>str | None</code> <p>Unused - paths are resolved from ImageCache.</p> required <code>project_name</code> <code>str</code> <p>AYON project name that owns the file, used to build the cache key via :func:<code>ayon_ui_qt.image_cache.make_activity_cache_key</code>.</p> required Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def refresh_image(\n    self,\n    file_id: str,\n    filepath: str | None,\n    project_name: str,\n) -&gt; None:\n    \"\"\"Refresh image attachment widget once a file download completes.\n\n    Called by the activity stream when a background download finishes.\n    If the widget hasn't been created yet (path was unavailable at build\n    time), creates and adds it now.\n\n    Args:\n        file_id: The AYON file identifier.\n        filepath: Unused - paths are resolved from ImageCache.\n        project_name: AYON project name that owns the file, used to\n            build the cache key via\n            :func:`ayon_ui_qt.image_cache.make_activity_cache_key`.\n    \"\"\"\n    ic = ImageCache.get_instance()\n    image_attachment = self._image_widgets.get(file_id)\n\n    if image_attachment is None and file_id in self._image_widgets:\n        # Widget placeholder registered but not yet created - build it\n        # now that the download has completed.\n        image_path = (\n            ic.get_path(\n                make_activity_cache_key(project_name, file_id),\n            )\n            or \"\"\n        )\n        thumb_path = ic.get_path(\n            make_activity_cache_key(\n                project_name, file_id, is_thumbnail=True\n            )\n        )\n        if not image_path:\n            return  # Full-size not ready yet; thumbnail alone is enough\n        image_attachment = AYImageAttachment(\n            parent=self,\n            image_path=image_path,\n            thumb_path=thumb_path,\n            max_width=100,\n            max_height=47,\n        )\n        self.images_container.add_widget(image_attachment)\n        self._image_widgets[file_id] = image_attachment\n        return\n\n    if isinstance(image_attachment, AYImageAttachment):\n        if not image_attachment._thumb_path:\n            image_attachment._thumb_path = (\n                ic.get_path(\n                    make_activity_cache_key(\n                        project_name, file_id, is_thumbnail=True\n                    )\n                )\n                or \"\"\n            )\n        if not image_attachment._image_path:\n            image_attachment._image_path = (\n                ic.get_path(\n                    make_activity_cache_key(project_name, file_id),\n                )\n                or \"\"\n            )\n        if image_attachment._thumb_path or image_attachment._image_path:\n            image_attachment._load_thumbnail()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYCommentField","title":"<code>AYCommentField</code>","text":"<p>               Bases: <code>AYTextEdit</code></p> <p>Text field for comment display with markdown and checkbox support.</p> <p>Supports GitHub-flavored markdown checkboxes (- [ ] and - [x]) that render with Material icons and can be toggled even in read-only mode.</p> Signals <p>checklist_changed: Emitted when a checkbox state changes.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>class AYCommentField(AYTextEdit):\n    \"\"\"Text field for comment display with markdown and checkbox support.\n\n    Supports GitHub-flavored markdown checkboxes (- [ ] and - [x]) that\n    render with Material icons and can be toggled even in read-only mode.\n\n    Signals:\n        checklist_changed: Emitted when a checkbox state changes.\n    \"\"\"\n\n    Variants = QTextEditVariants\n    checklist_changed = Signal()\n\n    def __init__(\n        self,\n        *args,\n        text: str = \"\",\n        read_only: bool = False,\n        num_lines: int = 0,\n        user_list: list[User] | None = None,\n        model: CommentModel | None = None,\n        variant: Variants = Variants.Default,\n        **kwargs,\n    ) -&gt; None:\n        # remove our kwargs\n        self._num_lines = num_lines\n        self._read_only: bool = read_only\n        self._user_list: list[User] = user_list or []\n        self._data = model\n        self._bg_color = None\n        self._checkbox_handler: CheckboxHandler | None = None\n        # Guard flag: when True, format_comment_on_change is a no-op.\n        self._suppress_formatting: bool = False\n\n        super().__init__(*args, variant=variant, **kwargs)\n        self.setAutoFormatting(QTextEdit.AutoFormattingFlag.AutoAll)\n        self.setSizeAdjustPolicy(QTextEdit.SizeAdjustPolicy.AdjustToContents)\n        self.document().setIndentWidth(22)\n        # Enable mouse tracking on viewport to receive mouseMoveEvent\n        # self.setMouseTracking(True)\n        self.viewport().setMouseTracking(True)\n        self.set_markdown(text)\n\n        # configure\n        if self._read_only:\n            # Auto-size to content for read-only fields\n            self.document().contentsChanged.connect(\n                self._adjust_height_to_content\n            )\n            self._adjust_height_to_content()\n        elif num_lines:\n            height = int(self.fontMetrics().lineSpacing()) * num_lines + 8 + 8\n            self.setFixedHeight(height)\n\n        if not self._read_only:\n            self.setPlaceholderText(\n                \"Comment or mention with @user, @@version, @@@task...\"\n            )\n        self.setReadOnly(self._read_only)\n\n        # Setup user completer\n        setup_user_completer(\n            self,\n            self._on_completer_activated,\n            self._on_text_changed,\n        )\n\n        # Connect text changed signal to format mentions\n        self.document().contentsChanged.connect(self._on_contents_changed)\n\n    def _on_contents_changed(self) -&gt; None:\n        \"\"\"Forward contentsChanged to format_comment_on_change.\n\n        Skipped when ``_suppress_formatting`` is True so that checkbox\n        insertion code can mutate the document without triggering a\n        full re-format pass.\n        \"\"\"\n        if not self._suppress_formatting:\n            format_comment_on_change(self)\n            apply_code_block_backgrounds(self)\n\n    def get_bg_color(self, base_color: str):\n        if not self._bg_color:\n            self._bg_color = base_color\n            if self._data and self._data.category_color:\n                self._bg_color = color_blend(\n                    base_color, self._data.category_color, 0.1\n                )\n        return self._bg_color\n\n    def set_markdown(self, md: str) -&gt; None:\n        \"\"\"Set markdown content with checkbox and web markdown support.\n\n        Supports:\n        - GitHub-flavored markdown checkboxes (- [ ] and - [x])\n        - Web markdown syntax (text\\\\n----, **bold**, _italic_, [link](url))\n        - Standard QTextDocument markdown\n\n        Args:\n            md: Markdown text to display\n        \"\"\"\n        # Check for checkboxes first\n        if CheckboxHandler.contains_checkboxes(md):\n            self._setup_checkbox_handler()\n            # Handler is guaranteed to exist after _setup_checkbox_handler\n            assert self._checkbox_handler is not None\n            self._checkbox_handler.parse_and_render(md)\n            if self._read_only:\n                self._adjust_height_to_content()\n            return\n\n        self.document().setMarkdown(md, MD_DIALECT)\n        apply_code_block_backgrounds(self)\n\n        if self._read_only:\n            self._adjust_height_to_content()\n\n    def _setup_checkbox_handler(self) -&gt; None:\n        \"\"\"Initialize checkbox handler if not already done.\"\"\"\n        if self._checkbox_handler is None:\n            self._checkbox_handler = CheckboxHandler(self)\n            self._checkbox_handler.checklist_changed.connect(\n                self._on_checklist_changed\n            )\n\n    def _on_checklist_changed(self) -&gt; None:\n        \"\"\"Handle checkbox state changes.\"\"\"\n        self.checklist_changed.emit()\n        if self._read_only:\n            self._adjust_height_to_content()\n\n    def as_markdown(self) -&gt; str:\n        \"\"\"Get the content as GitHub-flavored markdown.\n\n        If the field contains checkboxes, returns the markdown with\n        checkbox syntax (- [ ] and - [x]) reflecting current state.\n\n        Returns:\n            Markdown string.\n        \"\"\"\n        if self._checkbox_handler and self._checkbox_handler.has_checkboxes():\n            return self._checkbox_handler.to_markdown()\n        return self.document().toMarkdown(MD_DIALECT)\n\n    def _on_text_changed(self) -&gt; None:\n        \"\"\"Handle text changes to show/hide completer.\"\"\"\n        on_completer_text_changed(self)\n\n    def _on_completer_activated(self, text: str) -&gt; None:\n        \"\"\"Handle completer selection.\"\"\"\n        on_completer_activated(self, text)\n\n    def _adjust_height_to_content(self) -&gt; None:\n        \"\"\"Adjust widget height to fit document content (read-only mode only).\"\"\"\n        if not self._read_only:\n            return\n\n        # Get document height\n        doc = self.document()\n        doc.setTextWidth(self.viewport().width())\n        doc_height = doc.size().height()\n\n        # Add frame margins (top + bottom)\n        frame_width = self.frameWidth()\n        margins = self.contentsMargins()\n        total_height = (\n            int(doc_height)\n            + frame_width * 2\n            + margins.top()\n            + margins.bottom()\n        )\n\n        self.setFixedHeight(total_height)\n\n    def resizeEvent(self, event) -&gt; None:\n        \"\"\"Recalculate height when width changes (affects text wrapping).\"\"\"\n        super().resizeEvent(event)\n        if self._read_only:\n            self._adjust_height_to_content()\n\n    def contentOffset(self) -&gt; QPointF:\n        \"\"\"Compute content offset (QPlainTextEdit compatibility).\n\n        Returns the offset from viewport coordinates to document coordinates.\n        This method provides compatibility with QPlainTextEdit for checkbox\n        hit-testing in _is_checkbox_at_cursor.\n\n        Returns:\n            QPointF offset where viewport origin corresponds to document coords.\n        \"\"\"\n        return QPointF(\n            -self.horizontalScrollBar().value(),\n            -self.verticalScrollBar().value(),\n        )\n\n    def _insert_checkbox_at_cursor(self, cursor: QTextCursor) -&gt; None:\n        \"\"\"Insert a new unchecked checkbox object at the cursor position.\n\n        Inserts the custom checkbox object character (``\\\\ufffc``), and a\n        trailing space, then records the document position on the\n        :class:`CheckboxItem` for fast hit-testing.\n        The checkbox handler must already be initialised via\n        :meth:`_setup_checkbox_handler`.\n\n        Args:\n            cursor: Cursor at the insertion point; advanced past the\n                inserted characters on return.\n        \"\"\"\n        assert self._checkbox_handler is not None\n        new_item = self._checkbox_handler.add_checkbox()\n        fmt = QTextCharFormat()\n        fmt.setObjectType(CHECKBOX_FORMAT_TYPE)\n        fmt.setProperty(CHECKBOX_CHECKED_PROP, False)\n        fmt.setProperty(CHECKBOX_INDEX_PROP, new_item.index)\n        fmt.setVerticalAlignment(\n            QTextCharFormat.VerticalAlignment.AlignBaseline\n        )\n        new_item.doc_position = cursor.position()\n        cursor.insertText(\"\\ufffc\", fmt)\n        cursor.insertText(\" \")\n\n    def keyPressEvent(self, event) -&gt; None:\n        \"\"\"Handle key press events for completer.\"\"\"\n        if on_completer_key_press(self, event):\n            event.accept()\n            return\n\n        # Auto-continue checkbox on Enter\n        if (\n            event.key() in {Qt.Key.Key_Return, Qt.Key.Key_Enter}\n            and self._checkbox_handler\n            and self._checkbox_handler.has_checkboxes()\n        ):\n            cursor = self.textCursor()\n            block_text = cursor.block().text()\n\n            if \"\\ufffc\" in block_text:\n                # Extract text after the checkbox object char\n                parts = block_text.split(\"\\ufffc\", 1)\n                after_checkbox = parts[1].strip() if len(parts) &gt; 1 else \"\"\n                position_in_block = cursor.positionInBlock()\n                token_pos_in_block = block_text.index(\"\\ufffc\")\n                token_pos = (\n                    cursor.position() - position_in_block + token_pos_in_block\n                )\n                cb_index = self._checkbox_handler.get_checkbox_at_position(\n                    token_pos\n                )\n\n                if not after_checkbox:\n                    self._suppress_formatting = True\n                    try:\n                        # Empty checkbox line \u2192 end the list\n                        # Remove the checkbox content from current block\n                        cursor.movePosition(\n                            QTextCursor.MoveOperation.StartOfBlock,\n                            QTextCursor.MoveMode.MoveAnchor,\n                        )\n                        cursor.movePosition(\n                            QTextCursor.MoveOperation.EndOfBlock,\n                            QTextCursor.MoveMode.KeepAnchor,\n                        )\n                        cursor.removeSelectedText()\n                        # Remove the last checkbox from handler\n                        if cb_index is not None:\n                            self._checkbox_handler.remove_checkbox(cb_index)\n                    finally:\n                        self._suppress_formatting = False\n                    # Insert a plain newline\n                    super().keyPressEvent(event)\n                    return\n\n                # Non-empty checkbox line \u2192 insert new checkbox\n                event.accept()\n                self._suppress_formatting = True\n\n                try:\n                    cursor.beginEditBlock()\n                    cursor.movePosition(QTextCursor.MoveOperation.EndOfBlock)\n                    cursor.insertBlock()\n                    self._insert_checkbox_at_cursor(cursor)\n                    cursor.endEditBlock()\n                except Exception as err:\n                    logger.debug(\"Error inserting checkbox: %s\", err)\n                finally:\n                    self._suppress_formatting = False\n                self.setTextCursor(cursor)\n                return\n\n        super().keyPressEvent(event)\n\n    def _is_checkbox_at_cursor(\n        self, click_pos: QPoint\n    ) -&gt; tuple[bool, int | None]:\n        \"\"\"Check if a click position hits a checkbox bounding rect.\n\n        Delegates to `CheckboxHandler.find_checkbox_at_click` which\n        uses stored document positions instead of scanning the full text.\n\n        Args:\n            click_pos: QPoint from event.pos(), viewport coords.\n\n        Returns:\n            Tuple of (is_checkbox, document_position_for_lookup).\n        \"\"\"\n        if not self._checkbox_handler:\n            return False, None\n\n        result = self._checkbox_handler.find_checkbox_at_click(\n            click_pos, self.contentOffset().toPoint()\n        )\n        if result is None:\n            return False, None\n        return result\n\n    def mouseDoubleClickEvent(self, event) -&gt; None:\n        \"\"\"Prevent text selection when double-clicking checkboxes.\"\"\"\n        is_cb, cb_pos = self._is_checkbox_at_cursor(event.pos())\n        if is_cb and cb_pos is not None:\n            event.accept()\n            return\n        super().mouseDoubleClickEvent(event)\n\n    def mousePressEvent(self, event) -&gt; None:\n        \"\"\"Handle mouse press events for checkboxes and links.\n\n        Checkboxes can be toggled even in read-only mode.\n        Links are opened only in read-only mode.\n        \"\"\"\n        # Get the character at the click position\n        cursor = self.cursorForPosition(event.pos())\n        char_format = cursor.charFormat()\n\n        # Check if clicked on a checkbox (works in both modes)\n        is_cb, cb_pos = self._is_checkbox_at_cursor(event.pos())\n        if is_cb and cb_pos is not None:\n            assert self._checkbox_handler is not None  # implied by is_cb==True\n            checkbox_idx = self._checkbox_handler.get_checkbox_at_position(\n                cb_pos\n            )\n            if checkbox_idx is not None:\n                self._checkbox_handler.toggle_checkbox(checkbox_idx)\n                self.viewport().update()\n                event.accept()\n                return\n\n        # Handle link clicks only in read-only mode (display comments)\n        if self.isReadOnly():\n            # Check if the clicked text is a link (has anchor href)\n            if char_format.isAnchor() and char_format.anchorHref():\n                url = char_format.anchorHref()\n                webbrowser.open(url)\n                event.accept()\n                return\n\n        super().mousePressEvent(event)\n\n    def mouseMoveEvent(self, event) -&gt; None:\n        \"\"\"Change cursor to arrow when hovering over checkboxes, hand for links.\"\"\"\n        cursor = self.cursorForPosition(event.pos())\n        char_format = cursor.charFormat()\n\n        # Show arrow cursor for checkboxes (in any mode)\n        if char_format.objectType() == CHECKBOX_FORMAT_TYPE:\n            self.viewport().setCursor(Qt.CursorShape.ArrowCursor)\n            super().mouseMoveEvent(event)\n            return\n\n        # Show hand cursor for links (only in read-only mode)\n        if self.isReadOnly():\n            if char_format.isAnchor() and char_format.anchorHref():\n                self.viewport().setCursor(Qt.CursorShape.PointingHandCursor)\n            else:\n                self.viewport().setCursor(Qt.CursorShape.ArrowCursor)\n        else:\n            self.viewport().setCursor(Qt.CursorShape.IBeamCursor)\n\n        super().mouseMoveEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYCommentField.as_markdown","title":"<code>as_markdown()</code>","text":"<p>Get the content as GitHub-flavored markdown.</p> <p>If the field contains checkboxes, returns the markdown with checkbox syntax (- [ ] and - [x]) reflecting current state.</p> <p>Returns:</p> Type Description <code>str</code> <p>Markdown string.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def as_markdown(self) -&gt; str:\n    \"\"\"Get the content as GitHub-flavored markdown.\n\n    If the field contains checkboxes, returns the markdown with\n    checkbox syntax (- [ ] and - [x]) reflecting current state.\n\n    Returns:\n        Markdown string.\n    \"\"\"\n    if self._checkbox_handler and self._checkbox_handler.has_checkboxes():\n        return self._checkbox_handler.to_markdown()\n    return self.document().toMarkdown(MD_DIALECT)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYCommentField.contentOffset","title":"<code>contentOffset()</code>","text":"<p>Compute content offset (QPlainTextEdit compatibility).</p> <p>Returns the offset from viewport coordinates to document coordinates. This method provides compatibility with QPlainTextEdit for checkbox hit-testing in _is_checkbox_at_cursor.</p> <p>Returns:</p> Type Description <code>QPointF</code> <p>QPointF offset where viewport origin corresponds to document coords.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def contentOffset(self) -&gt; QPointF:\n    \"\"\"Compute content offset (QPlainTextEdit compatibility).\n\n    Returns the offset from viewport coordinates to document coordinates.\n    This method provides compatibility with QPlainTextEdit for checkbox\n    hit-testing in _is_checkbox_at_cursor.\n\n    Returns:\n        QPointF offset where viewport origin corresponds to document coords.\n    \"\"\"\n    return QPointF(\n        -self.horizontalScrollBar().value(),\n        -self.verticalScrollBar().value(),\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYCommentField.keyPressEvent","title":"<code>keyPressEvent(event)</code>","text":"<p>Handle key press events for completer.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def keyPressEvent(self, event) -&gt; None:\n    \"\"\"Handle key press events for completer.\"\"\"\n    if on_completer_key_press(self, event):\n        event.accept()\n        return\n\n    # Auto-continue checkbox on Enter\n    if (\n        event.key() in {Qt.Key.Key_Return, Qt.Key.Key_Enter}\n        and self._checkbox_handler\n        and self._checkbox_handler.has_checkboxes()\n    ):\n        cursor = self.textCursor()\n        block_text = cursor.block().text()\n\n        if \"\\ufffc\" in block_text:\n            # Extract text after the checkbox object char\n            parts = block_text.split(\"\\ufffc\", 1)\n            after_checkbox = parts[1].strip() if len(parts) &gt; 1 else \"\"\n            position_in_block = cursor.positionInBlock()\n            token_pos_in_block = block_text.index(\"\\ufffc\")\n            token_pos = (\n                cursor.position() - position_in_block + token_pos_in_block\n            )\n            cb_index = self._checkbox_handler.get_checkbox_at_position(\n                token_pos\n            )\n\n            if not after_checkbox:\n                self._suppress_formatting = True\n                try:\n                    # Empty checkbox line \u2192 end the list\n                    # Remove the checkbox content from current block\n                    cursor.movePosition(\n                        QTextCursor.MoveOperation.StartOfBlock,\n                        QTextCursor.MoveMode.MoveAnchor,\n                    )\n                    cursor.movePosition(\n                        QTextCursor.MoveOperation.EndOfBlock,\n                        QTextCursor.MoveMode.KeepAnchor,\n                    )\n                    cursor.removeSelectedText()\n                    # Remove the last checkbox from handler\n                    if cb_index is not None:\n                        self._checkbox_handler.remove_checkbox(cb_index)\n                finally:\n                    self._suppress_formatting = False\n                # Insert a plain newline\n                super().keyPressEvent(event)\n                return\n\n            # Non-empty checkbox line \u2192 insert new checkbox\n            event.accept()\n            self._suppress_formatting = True\n\n            try:\n                cursor.beginEditBlock()\n                cursor.movePosition(QTextCursor.MoveOperation.EndOfBlock)\n                cursor.insertBlock()\n                self._insert_checkbox_at_cursor(cursor)\n                cursor.endEditBlock()\n            except Exception as err:\n                logger.debug(\"Error inserting checkbox: %s\", err)\n            finally:\n                self._suppress_formatting = False\n            self.setTextCursor(cursor)\n            return\n\n    super().keyPressEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYCommentField.mouseDoubleClickEvent","title":"<code>mouseDoubleClickEvent(event)</code>","text":"<p>Prevent text selection when double-clicking checkboxes.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def mouseDoubleClickEvent(self, event) -&gt; None:\n    \"\"\"Prevent text selection when double-clicking checkboxes.\"\"\"\n    is_cb, cb_pos = self._is_checkbox_at_cursor(event.pos())\n    if is_cb and cb_pos is not None:\n        event.accept()\n        return\n    super().mouseDoubleClickEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYCommentField.mouseMoveEvent","title":"<code>mouseMoveEvent(event)</code>","text":"<p>Change cursor to arrow when hovering over checkboxes, hand for links.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def mouseMoveEvent(self, event) -&gt; None:\n    \"\"\"Change cursor to arrow when hovering over checkboxes, hand for links.\"\"\"\n    cursor = self.cursorForPosition(event.pos())\n    char_format = cursor.charFormat()\n\n    # Show arrow cursor for checkboxes (in any mode)\n    if char_format.objectType() == CHECKBOX_FORMAT_TYPE:\n        self.viewport().setCursor(Qt.CursorShape.ArrowCursor)\n        super().mouseMoveEvent(event)\n        return\n\n    # Show hand cursor for links (only in read-only mode)\n    if self.isReadOnly():\n        if char_format.isAnchor() and char_format.anchorHref():\n            self.viewport().setCursor(Qt.CursorShape.PointingHandCursor)\n        else:\n            self.viewport().setCursor(Qt.CursorShape.ArrowCursor)\n    else:\n        self.viewport().setCursor(Qt.CursorShape.IBeamCursor)\n\n    super().mouseMoveEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYCommentField.mousePressEvent","title":"<code>mousePressEvent(event)</code>","text":"<p>Handle mouse press events for checkboxes and links.</p> <p>Checkboxes can be toggled even in read-only mode. Links are opened only in read-only mode.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def mousePressEvent(self, event) -&gt; None:\n    \"\"\"Handle mouse press events for checkboxes and links.\n\n    Checkboxes can be toggled even in read-only mode.\n    Links are opened only in read-only mode.\n    \"\"\"\n    # Get the character at the click position\n    cursor = self.cursorForPosition(event.pos())\n    char_format = cursor.charFormat()\n\n    # Check if clicked on a checkbox (works in both modes)\n    is_cb, cb_pos = self._is_checkbox_at_cursor(event.pos())\n    if is_cb and cb_pos is not None:\n        assert self._checkbox_handler is not None  # implied by is_cb==True\n        checkbox_idx = self._checkbox_handler.get_checkbox_at_position(\n            cb_pos\n        )\n        if checkbox_idx is not None:\n            self._checkbox_handler.toggle_checkbox(checkbox_idx)\n            self.viewport().update()\n            event.accept()\n            return\n\n    # Handle link clicks only in read-only mode (display comments)\n    if self.isReadOnly():\n        # Check if the clicked text is a link (has anchor href)\n        if char_format.isAnchor() and char_format.anchorHref():\n            url = char_format.anchorHref()\n            webbrowser.open(url)\n            event.accept()\n            return\n\n    super().mousePressEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYCommentField.resizeEvent","title":"<code>resizeEvent(event)</code>","text":"<p>Recalculate height when width changes (affects text wrapping).</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def resizeEvent(self, event) -&gt; None:\n    \"\"\"Recalculate height when width changes (affects text wrapping).\"\"\"\n    super().resizeEvent(event)\n    if self._read_only:\n        self._adjust_height_to_content()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYCommentField.set_markdown","title":"<code>set_markdown(md)</code>","text":"<p>Set markdown content with checkbox and web markdown support.</p> <p>Supports: - GitHub-flavored markdown checkboxes (- [ ] and - [x]) - Web markdown syntax (text\\n----, bold, italic, link) - Standard QTextDocument markdown</p> <p>Parameters:</p> Name Type Description Default <code>md</code> <code>str</code> <p>Markdown text to display</p> required Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def set_markdown(self, md: str) -&gt; None:\n    \"\"\"Set markdown content with checkbox and web markdown support.\n\n    Supports:\n    - GitHub-flavored markdown checkboxes (- [ ] and - [x])\n    - Web markdown syntax (text\\\\n----, **bold**, _italic_, [link](url))\n    - Standard QTextDocument markdown\n\n    Args:\n        md: Markdown text to display\n    \"\"\"\n    # Check for checkboxes first\n    if CheckboxHandler.contains_checkboxes(md):\n        self._setup_checkbox_handler()\n        # Handler is guaranteed to exist after _setup_checkbox_handler\n        assert self._checkbox_handler is not None\n        self._checkbox_handler.parse_and_render(md)\n        if self._read_only:\n            self._adjust_height_to_content()\n        return\n\n    self.document().setMarkdown(md, MD_DIALECT)\n    apply_code_block_backgrounds(self)\n\n    if self._read_only:\n        self._adjust_height_to_content()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYImageAttachment","title":"<code>AYImageAttachment</code>","text":"<p>               Bases: <code>QLabel</code></p> <p>Widget to display an image attachment with thumbnail and full-size preview.</p> <p>Supports gallery mode when multiple images are associated together. When gallery_images is set, clicking the thumbnail opens a GalleryDialog that allows navigating through all images.</p> <p>Attributes:</p> Name Type Description <code>gallery_images</code> <p>List of (image_path, filename) tuples for gallery mode.</p> <code>gallery_index</code> <p>Current image index within the gallery.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>class AYImageAttachment(QLabel):\n    \"\"\"Widget to display an image attachment with thumbnail and full-size preview.\n\n    Supports gallery mode when multiple images are associated together.\n    When gallery_images is set, clicking the thumbnail opens a GalleryDialog\n    that allows navigating through all images.\n\n    Attributes:\n        gallery_images: List of (image_path, filename) tuples for gallery mode.\n        gallery_index: Current image index within the gallery.\n    \"\"\"\n\n    no_img = None\n    cacher_tmp_dir: Path | None = None\n\n    def __init__(\n        self,\n        parent: QWidget | None = None,\n        image_path: str | None = None,\n        thumb_path: str | None = None,\n        max_width: int = 100,\n        max_height: int = 47,\n        frame: int = 0,\n        gallery_images: list | None = None,\n        gallery_index: int = 0,\n    ):\n        super().__init__(parent)\n        self._image_path = image_path\n        self._thumb_path = thumb_path or image_path\n        if (\n            self._thumb_path is not None\n            and not Path(self._thumb_path).exists()\n        ):\n            self._thumb_path = None\n        self._max_width = max_width\n        self._max_height = max_height\n        self._frame = frame\n        self._gallery_images = gallery_images or []\n        self._gallery_index = gallery_index\n\n        self.setScaledContents(False)\n        self.setAlignment(\n            Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignTop\n        )\n        self.setCursor(Qt.CursorShape.PointingHandCursor)\n\n        # Set tooltip\n        self.setToolTip(\"Click to view full size\")\n\n        self._hovered = False\n        self._label_height = 16\n\n        self.setFixedSize(\n            self._max_width, self._max_height + self._label_height\n        )\n\n        # Load and display thumbnail\n        self._load_thumbnail()\n        self._draw_icon = get_icon(\"draw\", color=\"#eeeeee\")\n\n    @property\n    def image_path(self) -&gt; str:\n        \"\"\"Get the path to the full-size image.\"\"\"\n        return self._image_path\n\n    @property\n    def frame(self) -&gt; int:\n        \"\"\"Get the frame number associated with the image.\"\"\"\n        return self._frame\n\n    def _load_thumbnail(self):\n        \"\"\"Load and display the thumbnail image.\"\"\"\n        if AYImageAttachment.no_img is None:\n            AYImageAttachment.no_img = get_icon(\"panorama\", color=\"#666666\")\n\n        if not self._thumb_path or not Path(self._thumb_path).exists():\n            self.setPixmap(AYImageAttachment.no_img.pixmap(32, 32))\n            return\n\n        thumb_path = Path(self._thumb_path)\n        cache_key = f\"{thumb_path.name}_{self._max_width}_{self._max_height}\"\n\n        def _thumbnail_cacher() -&gt; Path:\n            \"\"\"Cache the scaled-down thumbnail image.\"\"\"\n            pixmap = QPixmap(self._thumb_path or \"\")\n            if pixmap.isNull():\n                raise ValueError(\n                    f\"Cannot load image from path: {self._thumb_path!r}\"\n                )\n\n            # Scale pixmap to fit within max dimensions while maintaining\n            # aspect ratio.\n            scaled_pixmap = pixmap.scaled(\n                self._max_width,\n                self._max_height,\n                Qt.AspectRatioMode.KeepAspectRatio,\n                Qt.TransformationMode.SmoothTransformation,\n            )\n            tmp_dir = AYImageAttachment.get_cacher_tmp_dir()\n            tmp_file_path = tmp_dir / f\"{cache_key}.thumb.png\"\n            scaled_pixmap.save(str(tmp_file_path), quality=75)\n            return tmp_file_path\n\n        ic = ImageCache.get_instance()\n        pxm = QPixmap(ic.get(cache_key, _thumbnail_cacher))\n        self.setPixmap(pxm)\n        self.setFixedSize(pxm.width(), pxm.height() + self._label_height)\n\n    def enterEvent(self, event):\n        \"\"\"Dim the image slightly when mouse enters.\"\"\"\n        self._hovered = True\n        super().enterEvent(event)\n\n    def leaveEvent(self, event):\n        \"\"\"Restore full opacity when mouse leaves.\"\"\"\n        self._hovered = False\n        super().leaveEvent(event)\n\n    def paintEvent(self, arg__1: QPaintEvent) -&gt; None:\n        \"\"\"Draw a semi-transparent overlay with a fullscreen icon when hovered.\"\"\"\n        # draw image\n        super().paintEvent(arg__1)\n        # setup painter\n        painter = QPainter(self)\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n        painter.setPen(Qt.PenStyle.NoPen)\n\n        if self._hovered:\n            img_rect = self.rect().adjusted(0, 0, 0, -self._label_height)\n            painter.setBrush(QColor(0, 0, 0, 144))\n            painter.drawRect(img_rect)\n            icon = get_icon(\"open_in_full\", color=\"#eeeeee\")\n            painter.drawPixmap(\n                img_rect.center() - QPoint(12, 12), icon.pixmap(24, 24)\n            )\n\n        # draw label background\n        lrect = QRect(\n            0,\n            self.height() - self._label_height,\n            self.width(),\n            self._label_height,\n        )\n        painter.setBrush(QColor(\"#1c2026\"))\n        painter.drawRect(lrect)\n        # draw icon on the left side\n        painter.drawPixmap(\n            lrect.left() + 3, lrect.top() + 3, self._draw_icon.pixmap(10, 10)\n        )\n        # draw text on the right side\n        painter.setPen(QColor(\"#eeeeee\"))\n        font = painter.font()\n        font.setPointSize(10)\n        painter.setFont(font)\n        painter.drawText(\n            lrect.adjusted(16 + 4, 0, 0, 0),\n            Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,\n            str(self._frame if self._frame &gt; 0 else \"n/a\"),\n        )\n\n    def mousePressEvent(self, event):\n        \"\"\"Handle click to show full-size image.\"\"\"\n        if event.button() == Qt.MouseButton.LeftButton:\n            self._show_full_size()\n        super().mousePressEvent(event)\n\n    def _show_full_size(self):\n        \"\"\"Show full-size image in a dialog that respects aspect ratio.\n\n        Uses GalleryDialog for consistent UI regardless of whether there's\n        a single image or multiple images in the gallery.\n        \"\"\"\n\n        # Collect gallery images if not already done\n        if not self._gallery_images or any(\n            t[0] == \"\" for t in self._gallery_images\n        ):\n            self._gallery_images = self._image_collector()\n\n        # Build gallery images list - use gallery_images if set, otherwise just this image\n        if self._gallery_images:\n            images = self._gallery_images\n            current_index = self._gallery_index\n        else:\n            # Single image case - still use gallery dialog for consistency\n            if not self._image_path or not Path(self._image_path).exists():\n                QMessageBox.warning(\n                    self,\n                    \"Image Not Available\",\n                    \"The full-size image is not available.\",\n                )\n                return\n            images = [(self._image_path, f\"Frame {self._frame}\")]\n            current_index = 0\n\n        dialog = GalleryDialog(\n            images=images,\n            current_index=current_index,\n            parent=self,\n        )\n        dialog.exec()\n\n    def set_gallery_images(self, images: list, current_index: int = 0) -&gt; None:\n        \"\"\"Set the gallery images for navigation.\n\n        Args:\n            images: List of (image_path, filename) tuples.\n            current_index: Index of this image in the gallery.\n        \"\"\"\n        self._gallery_images = images\n        self._gallery_index = current_index\n\n    def _image_collector(self) -&gt; list[tuple[str, str]]:\n        \"\"\"Collect all images in the parent layout.\"\"\"\n        try:\n            parent_layout = self.parentWidget().layout()\n        except AttributeError:\n            logger.info(\n                \"Parent widget has no valid layout for image collector\"\n            )\n            return []  # invalid parent widget\n\n        assert isinstance(parent_layout, QLayout)\n        image_list = []\n        for i in range(parent_layout.count()):\n            try:\n                widget = parent_layout.itemAt(i).widget()\n            except AttributeError:\n                continue  # invalid layout item\n            if isinstance(widget, AYImageAttachment):\n                image_list.append((widget.image_path, f\"Frame {widget.frame}\"))\n\n        return image_list\n\n    @classmethod\n    def get_cacher_tmp_dir(cls) -&gt; Path:\n        if cls.cacher_tmp_dir is None:\n            cls.cacher_tmp_dir = Path(\n                tempfile.mkdtemp(\n                    prefix=\"ayon_review_desktop_thumbnail_cacher_\"\n                )\n            )\n        return cls.cacher_tmp_dir\n\n    @staticmethod\n    def cleanup_cacher_directory() -&gt; None:\n        if (\n            AYImageAttachment.cacher_tmp_dir\n            and AYImageAttachment.cacher_tmp_dir.exists()\n        ):\n            rmtree(AYImageAttachment.cacher_tmp_dir, ignore_errors=True)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYImageAttachment.frame","title":"<code>frame</code>  <code>property</code>","text":"<p>Get the frame number associated with the image.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYImageAttachment.image_path","title":"<code>image_path</code>  <code>property</code>","text":"<p>Get the path to the full-size image.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYImageAttachment.enterEvent","title":"<code>enterEvent(event)</code>","text":"<p>Dim the image slightly when mouse enters.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def enterEvent(self, event):\n    \"\"\"Dim the image slightly when mouse enters.\"\"\"\n    self._hovered = True\n    super().enterEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYImageAttachment.leaveEvent","title":"<code>leaveEvent(event)</code>","text":"<p>Restore full opacity when mouse leaves.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def leaveEvent(self, event):\n    \"\"\"Restore full opacity when mouse leaves.\"\"\"\n    self._hovered = False\n    super().leaveEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYImageAttachment.mousePressEvent","title":"<code>mousePressEvent(event)</code>","text":"<p>Handle click to show full-size image.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def mousePressEvent(self, event):\n    \"\"\"Handle click to show full-size image.\"\"\"\n    if event.button() == Qt.MouseButton.LeftButton:\n        self._show_full_size()\n    super().mousePressEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYImageAttachment.paintEvent","title":"<code>paintEvent(arg__1)</code>","text":"<p>Draw a semi-transparent overlay with a fullscreen icon when hovered.</p> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def paintEvent(self, arg__1: QPaintEvent) -&gt; None:\n    \"\"\"Draw a semi-transparent overlay with a fullscreen icon when hovered.\"\"\"\n    # draw image\n    super().paintEvent(arg__1)\n    # setup painter\n    painter = QPainter(self)\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n    painter.setPen(Qt.PenStyle.NoPen)\n\n    if self._hovered:\n        img_rect = self.rect().adjusted(0, 0, 0, -self._label_height)\n        painter.setBrush(QColor(0, 0, 0, 144))\n        painter.drawRect(img_rect)\n        icon = get_icon(\"open_in_full\", color=\"#eeeeee\")\n        painter.drawPixmap(\n            img_rect.center() - QPoint(12, 12), icon.pixmap(24, 24)\n        )\n\n    # draw label background\n    lrect = QRect(\n        0,\n        self.height() - self._label_height,\n        self.width(),\n        self._label_height,\n    )\n    painter.setBrush(QColor(\"#1c2026\"))\n    painter.drawRect(lrect)\n    # draw icon on the left side\n    painter.drawPixmap(\n        lrect.left() + 3, lrect.top() + 3, self._draw_icon.pixmap(10, 10)\n    )\n    # draw text on the right side\n    painter.setPen(QColor(\"#eeeeee\"))\n    font = painter.font()\n    font.setPointSize(10)\n    painter.setFont(font)\n    painter.drawText(\n        lrect.adjusted(16 + 4, 0, 0, 0),\n        Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,\n        str(self._frame if self._frame &gt; 0 else \"n/a\"),\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment.html#client.ayon_ui_qt.components.comment.AYImageAttachment.set_gallery_images","title":"<code>set_gallery_images(images, current_index=0)</code>","text":"<p>Set the gallery images for navigation.</p> <p>Parameters:</p> Name Type Description Default <code>images</code> <code>list</code> <p>List of (image_path, filename) tuples.</p> required <code>current_index</code> <code>int</code> <p>Index of this image in the gallery.</p> <code>0</code> Source code in <code>client/ayon_ui_qt/components/comment.py</code> <pre><code>def set_gallery_images(self, images: list, current_index: int = 0) -&gt; None:\n    \"\"\"Set the gallery images for navigation.\n\n    Args:\n        images: List of (image_path, filename) tuples.\n        current_index: Index of this image in the gallery.\n    \"\"\"\n    self._gallery_images = images\n    self._gallery_index = current_index\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html","title":"comment_completion","text":""},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.MentionHighlighter","title":"<code>MentionHighlighter</code>","text":"<p>               Bases: <code>QSyntaxHighlighter</code></p> <p>Syntax highlighter for @mentions, raw URLs, and code spans.</p> <p>Operates on block-local plain text so positions are always correct regardless of any rich-text formatting already present in the document (bold, italic, headings, code spans, etc.).</p> <p>Patterns highlighted:</p> <ul> <li>Fenced code blocks (<code>\\`\\`\\` ... \\`\\`\\</code>) spanning multiple lines \u2014   black background, white monospace text.  Block state <code>1</code> tracks   whether the current block is inside a fence.</li> <li>Qt-rendered code blocks (from <code>setMarkdown()</code>) \u2014 detected via   <code>nonBreakableLines</code> on the block format.</li> <li>Qt-rendered inline code spans (from <code>setMarkdown()</code>) \u2014 detected via   <code>fontFixedPitch</code> on individual text fragments.</li> <li>Inline code spans (<code>\\`code\\`</code>) in raw (un-rendered) text \u2014 same   style, detected by backtick regex.</li> <li><code>@@@word</code> \u2014 task mention</li> <li><code>@@word</code>  \u2014 version mention</li> <li><code>@word</code>   \u2014 user mention (only the first word if the full name is not   in the known user list; both words when it is)</li> <li><code>https?://\u2026</code> \u2014 raw URL</li> </ul> <p>Parameters:</p> Name Type Description Default <code>document</code> <p>The QTextDocument to attach to.</p> required <code>user_list</code> <code>list</code> <p>Live list of :class:<code>~..data_models.User</code> objects used to decide whether a two-word mention should be highlighted in full.</p> required Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>class MentionHighlighter(QSyntaxHighlighter):\n    \"\"\"Syntax highlighter for @mentions, raw URLs, and code spans.\n\n    Operates on block-local plain text so positions are always correct\n    regardless of any rich-text formatting already present in the document\n    (bold, italic, headings, code spans, etc.).\n\n    Patterns highlighted:\n\n    - Fenced code blocks (```\\\\`\\\\`\\\\` ... \\\\`\\\\`\\\\```) spanning multiple lines \u2014\n      black background, white monospace text.  Block state ``1`` tracks\n      whether the current block is inside a fence.\n    - Qt-rendered code blocks (from ``setMarkdown()``) \u2014 detected via\n      ``nonBreakableLines`` on the block format.\n    - Qt-rendered inline code spans (from ``setMarkdown()``) \u2014 detected via\n      ``fontFixedPitch`` on individual text fragments.\n    - Inline code spans (`` \\\\`code\\\\` ``) in raw (un-rendered) text \u2014 same\n      style, detected by backtick regex.\n    - ``@@@word`` \u2014 task mention\n    - ``@@word``  \u2014 version mention\n    - ``@word``   \u2014 user mention (only the first word if the full name is not\n      in the known user list; both words when it is)\n    - ``https?://\u2026`` \u2014 raw URL\n\n    Args:\n        document: The QTextDocument to attach to.\n        user_list: Live list of :class:`~..data_models.User` objects used to\n            decide whether a two-word mention should be highlighted in full.\n    \"\"\"\n\n    # Compiled patterns \u2014 order matters: longer prefixes first so that\n    # ``@@@`` is matched before ``@@`` and ``@@`` before ``@``.\n    _P_TASK = re.compile(r\"@@@\\w+( \\w+)?\")\n    _P_VERSION = re.compile(r\"@@(?!@)\\w+( \\w+)?\")\n    _P_USER = re.compile(r\"@(?!@)\\w+( \\w+)?\")\n    _P_RAW_LINK = re.compile(r\"https?://\\S+\")\n    # Inline code: single backtick pair on the same line.\n    _P_CODE_INLINE = re.compile(r\"`[^`\\n]+`\")\n\n    def __init__(self, document, user_list: list) -&gt; None:\n        super().__init__(document)\n        self._user_list = user_list\n        pal = get_ayon_style().model.base_palette\n        self._mention_fmt = QTextCharFormat()\n        self._mention_fmt.setForeground(pal.link())\n        self._code_fmt = QTextCharFormat()\n        self._code_fmt.setFontFixedPitch(True)\n        self._code_fmt.setFontFamilies(\n            [\"Courier New\", \"Menlo\", \"Monaco\", \"monospace\"]\n        )\n        self._code_fmt.setBackground(CODE_BG)\n        self._code_fmt.setForeground(CODE_FG)\n\n    def update_user_list(self, user_list: list) -&gt; None:\n        \"\"\"Replace the user list and trigger a full rehighlight.\n\n        Args:\n            user_list: Updated list of User objects.\n        \"\"\"\n        self._user_list = user_list\n        self.rehighlight()\n\n    def highlightBlock(self, text: str) -&gt; None:\n        \"\"\"Apply code, mention, and URL highlighting to a single block.\n\n        Two detection strategies are combined so that code is styled in both\n        *edit mode* (raw markdown typed by the user) and *display mode*\n        (rich text rendered via ``document().setMarkdown()``):\n\n        **Edit mode \u2014 raw fence markers:**\n        Uses block state ``1`` to track multi-line fenced code blocks. A line\n        starting with *```* opens or closes a fence; every line inside the\n        fence is styled with :attr:`_code_fmt`.  A line that both opens and\n        closes a fence on the same line (e.g. ``\\\\`\\\\`\\\\`code\\\\`\\\\`\\\\```) is\n        treated as a single-line code block with no state change.\n\n        **Display mode \u2014 Qt-rendered char formats:**\n        After ``setMarkdown()`` Qt strips the fence markers and stores rich\n        text character formats.  Fenced code blocks have\n        ``nonBreakableLines=True`` set on the block format (``fontFixedPitch``\n        stays ``False`` on the block-level char format).  Inline code spans\n        set ``fontFixedPitch=True`` on individual text *fragments* within a\n        paragraph.  Both are detected here and styled with :attr:`_code_fmt`.\n\n        Inline code spans from raw backtick syntax (`` \\\\`code\\\\` ``) are also\n        detected via :attr:`_P_CODE_INLINE` for live-typed backtick spans.\n\n        Code formatting is applied *after* mention/URL patterns so that it\n        takes precedence over any mention highlight inside a code span.\n\n        Called automatically by Qt whenever the block changes.\n\n        Args:\n            text: Plain text content of the current block.\n        \"\"\"\n        block = self.currentBlock()\n        in_fence = self.previousBlockState() == 1\n\n        # \u2500\u2500 Edit mode: raw fence markers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n        if in_fence:\n            # The entire line belongs to the open fenced block.\n            self.setFormat(0, len(text), self._code_fmt)\n            # A line starting with ``` closes the fence.\n            if text.startswith(\"```\"):\n                self.setCurrentBlockState(0)\n            else:\n                self.setCurrentBlockState(1)\n            return\n\n        if text.startswith(\"```\"):\n            self.setFormat(0, len(text), self._code_fmt)\n            rest = text[3:]\n            # Closing ``` on the same line \u2192 single-line block, no state.\n            if \"```\" in rest:\n                self.setCurrentBlockState(0)\n            else:\n                self.setCurrentBlockState(1)\n            return\n\n        self.setCurrentBlockState(0)\n\n        # \u2500\u2500 Display mode: Qt-rendered whole-block code \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n        # After setMarkdown(), Qt marks fenced code block lines with\n        # nonBreakableLines=True on the block format.  The char format\n        # carries fontFamilies=['monospace'] but fontFixedPitch stays False.\n        # Style the whole line and skip mention/URL patterns \u2014 they don't\n        # belong inside code.\n        if block.blockFormat().nonBreakableLines():\n            self.setFormat(0, len(text), self._code_fmt)\n            return\n\n        # \u2500\u2500 Mentions and URLs (applied before inline code) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n        users = {u.full_name for u in self._user_list}\n\n        # Task mentions (@@@)\n        for m in self._P_TASK.finditer(text):\n            self.setFormat(m.start(), m.end() - m.start(), self._mention_fmt)\n\n        # Version mentions (@@)\n        for m in self._P_VERSION.finditer(text):\n            self.setFormat(m.start(), m.end() - m.start(), self._mention_fmt)\n\n        # User mentions (@) \u2014 highlight only the first word unless the full\n        # two-word name is in the known user list.\n        for m in self._P_USER.finditer(text):\n            full_match = m.group(0)\n            mention_name = full_match[1:]  # strip leading @\n            if mention_name in users:\n                length = len(full_match)\n            else:\n                # Highlight only up to the first word (no trailing space+word)\n                length = len(full_match.split()[0])\n            self.setFormat(m.start(), length, self._mention_fmt)\n\n        # Raw URLs\n        for m in self._P_RAW_LINK.finditer(text):\n            self.setFormat(m.start(), m.end() - m.start(), self._mention_fmt)\n\n        # \u2500\u2500 Inline code (applied last, overrides mention formatting) \u2500\u2500\u2500\u2500\u2500\n\n        # Raw backtick syntax `code` \u2014 detected in plain text for live\n        # editing where backtick characters are still present:\n        for m in self._P_CODE_INLINE.finditer(text):\n            self.setFormat(m.start(), m.end() - m.start(), self._code_fmt)\n\n        # Qt-rendered inline code spans \u2014 after setMarkdown() the backticks\n        # are consumed and individual fragments carry fontFixedPitch=True:\n        it = block.begin()\n        while not it.atEnd():\n            fragment = it.fragment()\n            if fragment.isValid() and fragment.charFormat().fontFixedPitch():\n                frag_start = fragment.position() - block.position()\n                self.setFormat(frag_start, fragment.length(), self._code_fmt)\n            it += 1\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.MentionHighlighter.highlightBlock","title":"<code>highlightBlock(text)</code>","text":"<p>Apply code, mention, and URL highlighting to a single block.</p> <p>Two detection strategies are combined so that code is styled in both edit mode (raw markdown typed by the user) and display mode (rich text rendered via <code>document().setMarkdown()</code>):</p> <p>Edit mode \u2014 raw fence markers: Uses block state <code>1</code> to track multi-line fenced code blocks. A line starting with *<code>* opens or closes a fence; every line inside the fence is styled with :attr:`_code_fmt`.  A line that both opens and closes a fence on the same line (e.g. ``\\`\\`\\`code\\`\\`\\</code>) is treated as a single-line code block with no state change.</p> <p>Display mode \u2014 Qt-rendered char formats: After <code>setMarkdown()</code> Qt strips the fence markers and stores rich text character formats.  Fenced code blocks have <code>nonBreakableLines=True</code> set on the block format (<code>fontFixedPitch</code> stays <code>False</code> on the block-level char format).  Inline code spans set <code>fontFixedPitch=True</code> on individual text fragments within a paragraph.  Both are detected here and styled with :attr:<code>_code_fmt</code>.</p> <p>Inline code spans from raw backtick syntax (<code>\\`code\\`</code>) are also detected via :attr:<code>_P_CODE_INLINE</code> for live-typed backtick spans.</p> <p>Code formatting is applied after mention/URL patterns so that it takes precedence over any mention highlight inside a code span.</p> <p>Called automatically by Qt whenever the block changes.</p> <p>Parameters:</p> Name Type Description Default <code>text</code> <code>str</code> <p>Plain text content of the current block.</p> required Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>def highlightBlock(self, text: str) -&gt; None:\n    \"\"\"Apply code, mention, and URL highlighting to a single block.\n\n    Two detection strategies are combined so that code is styled in both\n    *edit mode* (raw markdown typed by the user) and *display mode*\n    (rich text rendered via ``document().setMarkdown()``):\n\n    **Edit mode \u2014 raw fence markers:**\n    Uses block state ``1`` to track multi-line fenced code blocks. A line\n    starting with *```* opens or closes a fence; every line inside the\n    fence is styled with :attr:`_code_fmt`.  A line that both opens and\n    closes a fence on the same line (e.g. ``\\\\`\\\\`\\\\`code\\\\`\\\\`\\\\```) is\n    treated as a single-line code block with no state change.\n\n    **Display mode \u2014 Qt-rendered char formats:**\n    After ``setMarkdown()`` Qt strips the fence markers and stores rich\n    text character formats.  Fenced code blocks have\n    ``nonBreakableLines=True`` set on the block format (``fontFixedPitch``\n    stays ``False`` on the block-level char format).  Inline code spans\n    set ``fontFixedPitch=True`` on individual text *fragments* within a\n    paragraph.  Both are detected here and styled with :attr:`_code_fmt`.\n\n    Inline code spans from raw backtick syntax (`` \\\\`code\\\\` ``) are also\n    detected via :attr:`_P_CODE_INLINE` for live-typed backtick spans.\n\n    Code formatting is applied *after* mention/URL patterns so that it\n    takes precedence over any mention highlight inside a code span.\n\n    Called automatically by Qt whenever the block changes.\n\n    Args:\n        text: Plain text content of the current block.\n    \"\"\"\n    block = self.currentBlock()\n    in_fence = self.previousBlockState() == 1\n\n    # \u2500\u2500 Edit mode: raw fence markers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    if in_fence:\n        # The entire line belongs to the open fenced block.\n        self.setFormat(0, len(text), self._code_fmt)\n        # A line starting with ``` closes the fence.\n        if text.startswith(\"```\"):\n            self.setCurrentBlockState(0)\n        else:\n            self.setCurrentBlockState(1)\n        return\n\n    if text.startswith(\"```\"):\n        self.setFormat(0, len(text), self._code_fmt)\n        rest = text[3:]\n        # Closing ``` on the same line \u2192 single-line block, no state.\n        if \"```\" in rest:\n            self.setCurrentBlockState(0)\n        else:\n            self.setCurrentBlockState(1)\n        return\n\n    self.setCurrentBlockState(0)\n\n    # \u2500\u2500 Display mode: Qt-rendered whole-block code \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    # After setMarkdown(), Qt marks fenced code block lines with\n    # nonBreakableLines=True on the block format.  The char format\n    # carries fontFamilies=['monospace'] but fontFixedPitch stays False.\n    # Style the whole line and skip mention/URL patterns \u2014 they don't\n    # belong inside code.\n    if block.blockFormat().nonBreakableLines():\n        self.setFormat(0, len(text), self._code_fmt)\n        return\n\n    # \u2500\u2500 Mentions and URLs (applied before inline code) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    users = {u.full_name for u in self._user_list}\n\n    # Task mentions (@@@)\n    for m in self._P_TASK.finditer(text):\n        self.setFormat(m.start(), m.end() - m.start(), self._mention_fmt)\n\n    # Version mentions (@@)\n    for m in self._P_VERSION.finditer(text):\n        self.setFormat(m.start(), m.end() - m.start(), self._mention_fmt)\n\n    # User mentions (@) \u2014 highlight only the first word unless the full\n    # two-word name is in the known user list.\n    for m in self._P_USER.finditer(text):\n        full_match = m.group(0)\n        mention_name = full_match[1:]  # strip leading @\n        if mention_name in users:\n            length = len(full_match)\n        else:\n            # Highlight only up to the first word (no trailing space+word)\n            length = len(full_match.split()[0])\n        self.setFormat(m.start(), length, self._mention_fmt)\n\n    # Raw URLs\n    for m in self._P_RAW_LINK.finditer(text):\n        self.setFormat(m.start(), m.end() - m.start(), self._mention_fmt)\n\n    # \u2500\u2500 Inline code (applied last, overrides mention formatting) \u2500\u2500\u2500\u2500\u2500\n\n    # Raw backtick syntax `code` \u2014 detected in plain text for live\n    # editing where backtick characters are still present:\n    for m in self._P_CODE_INLINE.finditer(text):\n        self.setFormat(m.start(), m.end() - m.start(), self._code_fmt)\n\n    # Qt-rendered inline code spans \u2014 after setMarkdown() the backticks\n    # are consumed and individual fragments carry fontFixedPitch=True:\n    it = block.begin()\n    while not it.atEnd():\n        fragment = it.fragment()\n        if fragment.isValid() and fragment.charFormat().fontFixedPitch():\n            frag_start = fragment.position() - block.position()\n            self.setFormat(frag_start, fragment.length(), self._code_fmt)\n        it += 1\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.MentionHighlighter.update_user_list","title":"<code>update_user_list(user_list)</code>","text":"<p>Replace the user list and trigger a full rehighlight.</p> <p>Parameters:</p> Name Type Description Default <code>user_list</code> <code>list</code> <p>Updated list of User objects.</p> required Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>def update_user_list(self, user_list: list) -&gt; None:\n    \"\"\"Replace the user list and trigger a full rehighlight.\n\n    Args:\n        user_list: Updated list of User objects.\n    \"\"\"\n    self._user_list = user_list\n    self.rehighlight()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.UserCompleterDelegate","title":"<code>UserCompleterDelegate</code>","text":"<p>               Bases: <code>QStyledItemDelegate</code></p> <p>Custom delegate to display user icon and full name in completer.</p> Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>class UserCompleterDelegate(QStyledItemDelegate):\n    \"\"\"Custom delegate to display user icon and full name in completer.\"\"\"\n\n    def __init__(self, parent=None):\n        super().__init__(parent)\n        self.icon_size = 20\n        self._user_pixmap = {}\n\n    def paint(\n        self,\n        painter: QPainter,\n        option: QStyleOptionViewItem,\n        index,\n    ) -&gt; None:\n        \"\"\"Paint user icon and full name.\"\"\"\n        user: User = index.data(Qt.ItemDataRole.UserRole)\n        if not user:\n            super().paint(painter, option, index)\n            return\n\n        # Draw background\n        if option.state &amp; QStyle.StateFlag.State_Selected:\n            painter.fillRect(option.rect, option.palette.light())\n        else:\n            painter.fillRect(option.rect, option.palette.midlight())\n\n        # Draw user icon\n        try:\n            icon_pixmap = self._user_pixmap[user.name]\n        except KeyError:\n            user_image = AYUserImage(\n                src=user.avatar_url,\n                full_name=user.full_name,\n                size=self.icon_size,\n                outline=False,\n            )\n            icon_pixmap = user_image.pixmap()\n            self._user_pixmap[user.name] = icon_pixmap\n\n        icon_x = option.rect.x() + 4\n        icon_y = option.rect.y() + (option.rect.height() - self.icon_size) // 2\n        painter.drawPixmap(icon_x, icon_y, icon_pixmap)\n\n        # Draw full name\n        text_x = icon_x + self.icon_size + 8\n        text_rect = option.rect.adjusted(text_x, 0, 0, 0)\n        painter.drawText(\n            text_rect,\n            Qt.AlignmentFlag.AlignVCenter,\n            user.full_name,\n        )\n\n    def sizeHint(\n        self,\n        option: QStyleOptionViewItem,\n        index,\n    ) -&gt; QSize:\n        \"\"\"Return size hint for completer items.\"\"\"\n        return QSize(option.rect.width(), self.icon_size + 8)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.UserCompleterDelegate.paint","title":"<code>paint(painter, option, index)</code>","text":"<p>Paint user icon and full name.</p> Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>def paint(\n    self,\n    painter: QPainter,\n    option: QStyleOptionViewItem,\n    index,\n) -&gt; None:\n    \"\"\"Paint user icon and full name.\"\"\"\n    user: User = index.data(Qt.ItemDataRole.UserRole)\n    if not user:\n        super().paint(painter, option, index)\n        return\n\n    # Draw background\n    if option.state &amp; QStyle.StateFlag.State_Selected:\n        painter.fillRect(option.rect, option.palette.light())\n    else:\n        painter.fillRect(option.rect, option.palette.midlight())\n\n    # Draw user icon\n    try:\n        icon_pixmap = self._user_pixmap[user.name]\n    except KeyError:\n        user_image = AYUserImage(\n            src=user.avatar_url,\n            full_name=user.full_name,\n            size=self.icon_size,\n            outline=False,\n        )\n        icon_pixmap = user_image.pixmap()\n        self._user_pixmap[user.name] = icon_pixmap\n\n    icon_x = option.rect.x() + 4\n    icon_y = option.rect.y() + (option.rect.height() - self.icon_size) // 2\n    painter.drawPixmap(icon_x, icon_y, icon_pixmap)\n\n    # Draw full name\n    text_x = icon_x + self.icon_size + 8\n    text_rect = option.rect.adjusted(text_x, 0, 0, 0)\n    painter.drawText(\n        text_rect,\n        Qt.AlignmentFlag.AlignVCenter,\n        user.full_name,\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.UserCompleterDelegate.sizeHint","title":"<code>sizeHint(option, index)</code>","text":"<p>Return size hint for completer items.</p> Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>def sizeHint(\n    self,\n    option: QStyleOptionViewItem,\n    index,\n) -&gt; QSize:\n    \"\"\"Return size hint for completer items.\"\"\"\n    return QSize(option.rect.width(), self.icon_size + 8)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.UserCompleterModel","title":"<code>UserCompleterModel</code>","text":"<p>               Bases: <code>QStandardItemModel</code></p> <p>Model for user completer.</p> Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>class UserCompleterModel(QStandardItemModel):\n    \"\"\"Model for user completer.\"\"\"\n\n    def __init__(self, users: list[User], parent=None):\n        super().__init__(parent)\n        self.users = users\n        self._populate()\n\n    def _populate(self) -&gt; None:\n        \"\"\"Populate model with users.\"\"\"\n        self.clear()\n        for user in self.users:\n            item = QStandardItem(user.full_name)\n            item.setData(user, Qt.ItemDataRole.UserRole)\n            self.appendRow(item)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.apply_code_block_backgrounds","title":"<code>apply_code_block_backgrounds(text_edit)</code>","text":"<p>Apply a full-width background colour to every fenced code block.</p> <p><code>QSyntaxHighlighter.setFormat()</code> only paints behind individual text characters, so the end of a short line keeps the regular widget background.  Setting <code>QTextBlockFormat.background</code> instead causes Qt's own layout engine to paint the background across the entire width of the block before any characters are drawn.</p> <p>This function is intentionally separate from :class:<code>MentionHighlighter</code> because Qt's documentation forbids modifying the document from inside <code>highlightBlock()</code>.</p> <p>Two detection strategies are combined so that code blocks are recognised in both scenarios:</p> <ul> <li>Display mode (after <code>document().setMarkdown()</code>): Qt marks   fenced code block lines with <code>nonBreakableLines=True</code> on the   block format.</li> <li>Edit mode (raw typing): Lines inside a <code>`\\</code>``\u2026`````` fence   are detected by tracking an open-fence flag while iterating from   the first block of the document.</li> </ul> <p>The function is guarded by the <code>_suppress_formatting</code> attribute on text_edit to prevent infinite recursion: writing block formats emits <code>contentsChanged</code>, which would otherwise re-enter this function.</p> <p>Parameters:</p> Name Type Description Default <code>text_edit</code> <code>QTextEdit</code> <p>The QTextEdit whose document should have fenced code block backgrounds applied.</p> required Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>def apply_code_block_backgrounds(text_edit: QTextEdit) -&gt; None:\n    \"\"\"Apply a full-width background colour to every fenced code block.\n\n    ``QSyntaxHighlighter.setFormat()`` only paints behind individual\n    text characters, so the end of a short line keeps the regular widget\n    background.  Setting ``QTextBlockFormat.background`` instead causes\n    Qt's own layout engine to paint the background across the *entire*\n    width of the block before any characters are drawn.\n\n    This function is intentionally separate from\n    :class:`MentionHighlighter` because Qt's documentation forbids\n    modifying the document from inside ``highlightBlock()``.\n\n    Two detection strategies are combined so that code blocks are\n    recognised in both scenarios:\n\n    - **Display mode** (after ``document().setMarkdown()``): Qt marks\n      fenced code block lines with ``nonBreakableLines=True`` on the\n      block format.\n    - **Edit mode** (raw typing): Lines inside a ``\\\\`\\\\`\\\\`\u2026\\\\`\\\\`\\\\```` fence\n      are detected by tracking an open-fence flag while iterating from\n      the first block of the document.\n\n    The function is guarded by the ``_suppress_formatting`` attribute on\n    *text_edit* to prevent infinite recursion: writing block formats\n    emits ``contentsChanged``, which would otherwise re-enter this\n    function.\n\n    Args:\n        text_edit: The QTextEdit whose document should have fenced code\n            block backgrounds applied.\n    \"\"\"\n    if getattr(text_edit, \"_suppress_formatting\", False):\n        return\n\n    doc = text_edit.document()\n    setattr(text_edit, \"_suppress_formatting\", True)\n\n    cursor = QTextCursor(doc)\n    cursor.beginEditBlock()\n\n    try:\n        in_fence = False\n        block = doc.begin()\n        while block.isValid():\n            text = block.text()\n            is_code = False\n\n            # Display mode: Qt-rendered fenced code block.\n            if block.blockFormat().nonBreakableLines():\n                is_code = True\n            else:\n                # Edit mode: raw ``` fence markers.\n                if in_fence:\n                    is_code = True\n                    if text.startswith(\"```\"):\n                        in_fence = False  # closing fence line \u2014 still code\n                elif text.startswith(\"```\"):\n                    is_code = True\n                    rest = text[3:]\n                    if \"```\" not in rest:\n                        in_fence = True  # opening fence\n                    # else: single-line ```\u2026``` \u2014 is_code=True, no state change\n\n            bg_brush = block.blockFormat().background()\n            has_code_bg = (\n                bg_brush.style() != Qt.BrushStyle.NoBrush\n                and bg_brush.color().rgb() == CODE_BG.rgb()\n            )\n\n            if is_code and not has_code_bg:\n                cursor.setPosition(block.position())\n                new_fmt = QTextBlockFormat()\n                new_fmt.setBackground(CODE_BG)\n                cursor.mergeBlockFormat(new_fmt)\n            elif not is_code and has_code_bg:\n                # Remove the previously applied code background.\n                cursor.setPosition(block.position())\n                restored = QTextBlockFormat(block.blockFormat())\n                restored.clearBackground()\n                cursor.setBlockFormat(restored)\n\n            block = block.next()\n    except Exception as e:\n        logging.info(f\"Error in apply_code_block_backgrounds: {e}\")\n    finally:\n        # Ensure we always end the edit block and reset the flag\n        cursor.endEditBlock()\n        setattr(text_edit, \"_suppress_formatting\", False)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.format_comment_on_change","title":"<code>format_comment_on_change(text_edit)</code>","text":"<p>Ensure a :class:<code>MentionHighlighter</code> is installed on text_edit.</p> <p>Idempotent: safe to call on every <code>contentsChanged</code> signal.  The highlighter is created once and attached to the document.  Subsequent calls only call :meth:<code>MentionHighlighter.update_user_list</code> when the <code>_user_list</code> reference on text_edit has been replaced (e.g. after a server refresh), which avoids triggering an unnecessary <code>rehighlight</code> \u2014 and the infinite-recursion that would follow \u2014 on every keystroke.</p> <p>Parameters:</p> Name Type Description Default <code>text_edit</code> <code>QTextEdit</code> <p>The QTextEdit whose document should have mention highlighting applied.</p> required Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>def format_comment_on_change(text_edit: QTextEdit) -&gt; None:\n    \"\"\"Ensure a :class:`MentionHighlighter` is installed on *text_edit*.\n\n    Idempotent: safe to call on every ``contentsChanged`` signal.  The\n    highlighter is created once and attached to the document.  Subsequent\n    calls only call :meth:`MentionHighlighter.update_user_list` when the\n    ``_user_list`` reference on *text_edit* has been replaced (e.g. after a\n    server refresh), which avoids triggering an unnecessary ``rehighlight``\n    \u2014 and the infinite-recursion that would follow \u2014 on every keystroke.\n\n    Args:\n        text_edit: The QTextEdit whose document should have mention\n            highlighting applied.\n    \"\"\"\n    highlighter: MentionHighlighter | None = getattr(\n        text_edit, \"_mention_highlighter\", None\n    )\n    user_list = getattr(text_edit, \"_user_list\", [])\n\n    if highlighter is None:\n        highlighter = MentionHighlighter(text_edit.document(), user_list)\n        text_edit._mention_highlighter = highlighter  # type: ignore[attr-defined]\n    elif highlighter._user_list is not user_list:\n        # The list object was replaced (e.g. after a user-list refresh).\n        # update_user_list() calls rehighlight() which is safe here because\n        # this branch is only reached when _suppress_formatting is False and\n        # the list identity has changed \u2014 not on every keystroke.\n        highlighter.update_user_list(user_list)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.on_completer_activated","title":"<code>on_completer_activated(text_edit, text)</code>","text":"<p>Handle completer selection.</p> <p>Parameters:</p> Name Type Description Default <code>text_edit</code> <code>QTextEdit</code> <p>The QTextEdit widget with completer.</p> required <code>text</code> <code>str</code> <p>The selected completion text (user full name).</p> required Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>def on_completer_activated(\n    text_edit: QTextEdit,\n    text: str,\n) -&gt; None:\n    \"\"\"Handle completer selection.\n\n    Args:\n        text_edit: The QTextEdit widget with completer.\n        text: The selected completion text (user full name).\n    \"\"\"\n    cursor = text_edit.textCursor()\n    block = cursor.block()\n    text_in_block = block.text()\n    pos_in_block = cursor.positionInBlock()\n\n    # Find the '@' position\n    at_pos = text_in_block.rfind(\"@\", 0, pos_in_block)\n    if at_pos == -1:\n        return\n\n    # Replace from '@' to cursor with '@' + full_name\n    cursor.setPosition(block.position() + at_pos)\n    cursor.setPosition(\n        block.position() + pos_in_block,\n        QTextCursor.MoveMode.KeepAnchor,\n    )\n    cursor.insertText(f\"@{text}\")\n    text_edit.setTextCursor(cursor)\n    popup = text_edit.completer.popup()\n    if popup:\n        popup.hide()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.on_completer_key_press","title":"<code>on_completer_key_press(text_edit, event)</code>","text":"<p>Handle key press events for completer.</p> <p>Parameters:</p> Name Type Description Default <code>text_edit</code> <code>QTextEdit</code> <p>The QTextEdit widget with completer.</p> required <code>event</code> <p>The key press event.</p> required <p>Returns:</p> Type Description <code>bool</code> <p>True if event was handled, False otherwise.</p> Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>def on_completer_key_press(\n    text_edit: QTextEdit,\n    event,\n) -&gt; bool:\n    \"\"\"Handle key press events for completer.\n\n    Args:\n        text_edit: The QTextEdit widget with completer.\n        event: The key press event.\n\n    Returns:\n        True if event was handled, False otherwise.\n    \"\"\"\n    if not hasattr(text_edit, \"completer\"):\n        return False\n\n    popup = text_edit.completer.popup()\n    if popup and popup.isVisible():\n        if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter):\n            # Get current completion from the selected index\n            current_index = popup.currentIndex()\n            if current_index.isValid():\n                completion = current_index.data()\n                if completion:\n                    text_edit.completer.activated.emit(completion)\n                    return True\n    return False\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.on_completer_text_changed","title":"<code>on_completer_text_changed(text_edit)</code>","text":"<p>Handle text changes to show/hide completer.</p> <p>Parameters:</p> Name Type Description Default <code>text_edit</code> <code>QTextEdit</code> <p>The QTextEdit widget with completer.</p> required Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>def on_completer_text_changed(\n    text_edit: QTextEdit,\n) -&gt; None:\n    \"\"\"Handle text changes to show/hide completer.\n\n    Args:\n        text_edit: The QTextEdit widget with completer.\n    \"\"\"\n    if not hasattr(text_edit, \"completer\") or text_edit.isReadOnly():\n        return\n\n    cursor = text_edit.textCursor()\n    block = cursor.block()\n    text = block.text()\n    pos_in_block = cursor.positionInBlock()\n\n    # Find the last '@' before cursor\n    at_pos = text.rfind(\"@\", 0, pos_in_block)\n    if at_pos == -1:\n        popup = text_edit.completer.popup()\n        if popup:\n            popup.hide()\n        return\n\n    # Get text after '@'\n    prefix = text[at_pos + 1 : pos_in_block]\n\n    # Show completer if '@' is followed by nothing or non-space characters\n    if not prefix or (prefix and not prefix[0].isspace()):\n        text_edit.completer.setCompletionPrefix(prefix)\n        show_completer_popup(text_edit, at_pos)\n        # Auto-select if only one item\n        popup = text_edit.completer.popup()\n        if popup:\n            popup_model = popup.model()\n            row_count = popup_model.rowCount() if popup_model else 0\n            if row_count == 1:\n                popup.setCurrentIndex(popup_model.index(0, 0))\n    else:\n        popup = text_edit.completer.popup()\n        if popup:\n            popup.hide()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.setup_user_completer","title":"<code>setup_user_completer(text_edit, on_completer_activated, on_text_changed)</code>","text":"<p>Setup user name completer for a QTextEdit widget.</p> <p>Parameters:</p> Name Type Description Default <code>text_edit</code> <code>QTextEdit</code> <p>The QTextEdit widget to attach completer to.</p> required <code>on_completer_activated</code> <p>Callback for completer activation.</p> required <code>on_text_changed</code> <p>Callback for text changes.</p> required Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>def setup_user_completer(\n    text_edit: QTextEdit,\n    on_completer_activated,\n    on_text_changed,\n) -&gt; None:\n    \"\"\"Setup user name completer for a QTextEdit widget.\n\n    Args:\n        text_edit: The QTextEdit widget to attach completer to.\n        on_completer_activated: Callback for completer activation.\n        on_text_changed: Callback for text changes.\n    \"\"\"\n    users = getattr(text_edit, \"_user_list\")\n    if not users:\n        users = [\n            User(\n                name=\"not available\",\n                short_name=\"not available\",\n                full_name=\"not available\",\n                email=\"\",\n                avatar_url=\"\",\n            )\n        ]\n    model = UserCompleterModel(users, text_edit)\n    text_edit.completer = QCompleter(model, text_edit)\n    text_edit.completer.setCompletionMode(\n        QCompleter.CompletionMode.PopupCompletion\n    )\n    text_edit.completer.setFilterMode(Qt.MatchFlag.MatchContains)\n    text_edit.completer.setMaxVisibleItems(4)\n    text_edit.completer.setCaseSensitivity(Qt.CaseSensitivity.CaseInsensitive)\n    text_edit.completer.setWidget(text_edit)\n\n    # Set custom delegate\n    popup = text_edit.completer.popup()\n    if popup:\n        delegate = UserCompleterDelegate(popup)\n        popup.setItemDelegate(delegate)\n        popup.setWindowFlag(Qt.WindowType.NoDropShadowWindowHint, True)\n\n    # Connect completer signals\n    text_edit.completer.activated.connect(on_completer_activated)\n    text_edit.textChanged.connect(on_text_changed)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/comment_completion.html#client.ayon_ui_qt.components.comment_completion.show_completer_popup","title":"<code>show_completer_popup(text_edit, at_pos)</code>","text":"<p>Show completer popup above the QTextEdit.</p> <p>Parameters:</p> Name Type Description Default <code>text_edit</code> <code>QTextEdit</code> <p>The QTextEdit widget with completer.</p> required <code>at_pos</code> <code>int</code> <p>Position of '@' character in the block.</p> required Source code in <code>client/ayon_ui_qt/components/comment_completion.py</code> <pre><code>def show_completer_popup(text_edit: QTextEdit, at_pos: int) -&gt; None:\n    \"\"\"Show completer popup above the QTextEdit.\n\n    Args:\n        text_edit: The QTextEdit widget with completer.\n        at_pos: Position of '@' character in the block.\n    \"\"\"\n    popup = text_edit.completer.popup()\n    if not popup:\n        return\n\n    # Get editor dimensions\n    editor_rect = text_edit.rect()\n    editor_width = editor_rect.width()\n\n    # Show popup to get its height\n    popup.show()\n\n    # Calculate height based on max visible items (4)\n    max_visible = text_edit.completer.maxVisibleItems()\n    item_height = popup.sizeHintForRow(0)\n    popup_height = item_height * max_visible\n\n    # Position popup above the QTextEdit with same width as editor\n    global_pos = text_edit.mapToGlobal(editor_rect.topLeft())\n    popup_x = global_pos.x()\n    popup_y = global_pos.y() - popup_height\n\n    popup.setGeometry(popup_x, popup_y, editor_width, popup_height)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/container.html","title":"container","text":""},{"location":"autoapi/client/ayon_ui_qt/components/entity_card.html","title":"entity_card","text":"<p>AYEntityCard \u2014 a card widget representing an AYON entity (task, version, product, etc.).</p> <p>Mirrors the EntityCard component from https://components.ayon.dev.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/entity_card.html#client.ayon_ui_qt.components.entity_card--layout","title":"Layout","text":"<p>\u250c\u2500\u2500\u2500 header row \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u2502  [project]  [path/breadcrumb]          [entity name bold] \u2502   \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u250c\u2500\u2500\u2500 card body (thumbnail + overlay) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u2502  [background image or icon placeholder]                    \u2502   \u2502                                                            \u2502   \u2502  \u2504 overlay top row \u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504  \u2502   \u2502  [title chip (icon + text)]              [play chip]       \u2502   \u2502                                                            \u2502   \u2502  \u2504 overlay bottom row \u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504\u2504  \u2502   \u2502  [users][priority] [versions]     [status icon + name]   \u2502   \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518</p>"},{"location":"autoapi/client/ayon_ui_qt/components/entity_card.html#client.ayon_ui_qt.components.entity_card.AYEntityCard","title":"<code>AYEntityCard</code>","text":"<p>               Bases: <code>AYContainer</code></p> <p>A card widget representing an AYON entity (task, version, product\u2026).</p>"},{"location":"autoapi/client/ayon_ui_qt/components/entity_card.html#client.ayon_ui_qt.components.entity_card.AYEntityCard--signals","title":"Signals","text":"<p>activated     Emitted when the card is clicked (or keyboard-activated). title_clicked     Emitted when the title chip inside the card is clicked.</p> Source code in <code>client/ayon_ui_qt/components/entity_card.py</code> <pre><code>class AYEntityCard(AYContainer):\n    \"\"\"A card widget representing an AYON entity (task, version, product\u2026).\n\n    Signals\n    -------\n    activated\n        Emitted when the card is clicked (or keyboard-activated).\n    title_clicked\n        Emitted when the title chip inside the card is clicked.\n    \"\"\"\n\n    activated = Signal()\n    title_clicked = Signal()\n\n    def __init__(\n        self,\n        *,\n        width: int = 200,\n        header: str = \"\",\n        path: str | list[str] = \"\",\n        project: str = \"\",\n        show_path: bool = False,\n        title: str = \"\",\n        title_icon: str = \"\",\n        title_color: str = \"\",\n        is_playable: bool = False,\n        users: list[dict[str, Any]] | None = None,\n        status: dict[str, Any] | None = None,\n        priority: dict[str, Any] | None = None,\n        hide_priority: bool = False,\n        version: str = \"\",\n        image_src: str | Path = \"\",\n        image_icon: str = \"image\",\n        is_active: bool = False,\n        is_loading: bool = False,\n        is_error: bool = False,\n        is_hover: bool = False,\n        is_dragging: bool = False,\n        is_draggable: bool = False,\n        parent: QWidget | None = None,\n    ) -&gt; None:\n        super().__init__(\n            parent,\n            layout=AYContainer.Layout.VBox,\n            variant=QFrameVariants.Entity_Card,\n            layout_margin=0,\n            layout_spacing=0,\n        )\n        self.set_width(width)\n\n        self.setStyle(get_ayon_style())\n        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)\n        self.setMouseTracking(True)\n\n        # ---- state ----\n        self._header = header\n        self._path = path\n        self._project = project\n        self._show_path = show_path\n        self._title = title\n        self._title_icon = title_icon\n        self._title_color = title_color\n        self._is_playable = is_playable\n        self._users = users\n        self._status = status\n        self._priority = priority\n        self._hide_priority = hide_priority\n        self._version = version\n        self._image_src = image_src\n        self._image_icon = image_icon\n        self._is_active = is_active\n        self._is_loading = is_loading\n        self._is_error = is_error\n        self._is_hover = is_hover\n        self._is_dragging = is_dragging\n        self._is_draggable = is_draggable\n        self._drag_start_pos: QPoint | None = None\n\n        # ---- build UI ----\n        self._header_widget = _CardHeader(self)\n        self.add_widget(self._header_widget)\n\n        # The card body container holds body + overlay stacked\n        self._body_container = QWidget(self)\n        self._body_container.setAttribute(\n            Qt.WidgetAttribute.WA_TranslucentBackground\n        )\n        self._body_container.setSizePolicy(\n            QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding\n        )\n        self.add_widget(self._body_container, 1)\n\n        self._card_body = _CardBody(parent=self._body_container, width=width)\n        self._overlay = _CardOverlay(parent=self._body_container)\n\n        # Lay body &amp; overlay in a stacked layout so overlay is on top\n        stacked = QStackedLayout(self._body_container)\n        stacked.setStackingMode(QStackedLayout.StackingMode.StackAll)\n        stacked.addWidget(self._card_body)\n        stacked.addWidget(self._overlay)\n        stacked.setCurrentWidget(self._overlay)\n\n        _body_sd = get_ayon_style_data(\"QFrame\", \"entity-card\")\n\n        # ---- init content ----\n        self._rebuild_header()\n        self._rebuild_thumbnail()\n        self._rebuild_overlay()\n        self._apply_body_state()\n\n        # ---- drag ----\n        if is_draggable:\n            self.setCursor(QCursor(Qt.CursorShape.OpenHandCursor))\n\n    def set_width(self, w: int) -&gt; None:\n        \"\"\"Set the card width and adjust height to maintain a 1.52:1 aspect\n        ratio (default thumbnail ratio from front-end).\"\"\"\n        self.setFixedSize(w, int(w / CARD_RATIO))\n\n    # ------------------------------------------------------------------\n    # Rebuild helpers\n    # ------------------------------------------------------------------\n\n    def _rebuild_header(self) -&gt; None:\n        self._header_widget.update_content(\n            self._project, self._path, self._header, self._show_path\n        )\n\n    def _rebuild_thumbnail(self) -&gt; None:\n        self._card_body.set_thumbnail(self._image_src)\n        self._card_body.set_image_icon(self._image_icon)\n\n    def _rebuild_overlay(self) -&gt; None:\n        self._overlay.set_title(\n            self._title,\n            self._title_icon,\n            self._title_color,\n            on_click=self.title_clicked,\n        )\n        self._overlay.set_playable(self._is_playable)\n        self._overlay.set_users(self._users)\n        self._overlay.set_priority(self._priority, hide=self._hide_priority)\n        self._overlay.set_version(self._version)\n        self._overlay.set_status(self._status)\n        self._overlay.set_loading(self._is_loading)\n\n    def _apply_body_state(self) -&gt; None:\n        self._card_body.set_is_active(self._is_active)\n        self._card_body.set_is_hover(self._is_hover)\n        self._card_body.set_is_dragging(self._is_dragging)\n        self._card_body.set_is_loading(self._is_loading)\n        self._card_body.set_is_error(self._is_error)\n\n    # ------------------------------------------------------------------\n    # Properties\n    # ------------------------------------------------------------------\n\n    @property\n    def header(self) -&gt; str:\n        return self._header\n\n    @header.setter\n    def header(self, value: str) -&gt; None:\n        self._header = value\n        self._rebuild_header()\n\n    @property\n    def path(self) -&gt; str | list[str]:\n        return self._path\n\n    @path.setter\n    def path(self, value: str | list[str]) -&gt; None:\n        self._path = value\n        self._rebuild_header()\n\n    @property\n    def project(self) -&gt; str:\n        return self._project\n\n    @project.setter\n    def project(self, value: str) -&gt; None:\n        self._project = value\n        self._rebuild_header()\n\n    @property\n    def show_path(self) -&gt; bool:\n        return self._show_path\n\n    @show_path.setter\n    def show_path(self, value: bool) -&gt; None:\n        self._show_path = value\n        self._rebuild_header()\n\n    @property\n    def title(self) -&gt; str:\n        return self._title\n\n    @title.setter\n    def title(self, value: str) -&gt; None:\n        self._title = value\n        self._rebuild_overlay()\n\n    @property\n    def title_icon(self) -&gt; str:\n        return self._title_icon\n\n    @title_icon.setter\n    def title_icon(self, value: str) -&gt; None:\n        self._title_icon = value\n        self._rebuild_overlay()\n\n    @property\n    def title_color(self) -&gt; str:\n        return self._title_color\n\n    @title_color.setter\n    def title_color(self, value: str) -&gt; None:\n        self._title_color = value\n        self._rebuild_overlay()\n\n    @property\n    def is_playable(self) -&gt; bool:\n        return self._is_playable\n\n    @is_playable.setter\n    def is_playable(self, value: bool) -&gt; None:\n        self._is_playable = value\n        self._rebuild_overlay()\n\n    @property\n    def users(self) -&gt; list[dict[str, Any]] | None:\n        return self._users\n\n    @users.setter\n    def users(self, value: list[dict[str, Any]] | None) -&gt; None:\n        self._users = value\n        self._rebuild_overlay()\n\n    @property\n    def status(self) -&gt; dict[str, Any] | None:\n        return self._status\n\n    @status.setter\n    def status(self, value: dict[str, Any] | None) -&gt; None:\n        self._status = value\n        self._rebuild_overlay()\n\n    @property\n    def priority(self) -&gt; dict[str, Any] | None:\n        return self._priority\n\n    @priority.setter\n    def priority(self, value: dict[str, Any] | None) -&gt; None:\n        self._priority = value\n        self._rebuild_overlay()\n\n    @property\n    def hide_priority(self) -&gt; bool:\n        return self._hide_priority\n\n    @hide_priority.setter\n    def hide_priority(self, value: bool) -&gt; None:\n        self._hide_priority = value\n        self._rebuild_overlay()\n\n    @property\n    def version(self) -&gt; str | None:\n        return self._version\n\n    @version.setter\n    def version(self, value: str | None) -&gt; None:\n        self._version = value\n        self._rebuild_overlay()\n\n    @property\n    def image_src(self) -&gt; str | Path:\n        return self._image_src\n\n    @image_src.setter\n    def image_src(self, value: str | Path) -&gt; None:\n        self._image_src = value\n        self._rebuild_thumbnail()\n\n    @property\n    def image_icon(self) -&gt; str:\n        return self._image_icon\n\n    @image_icon.setter\n    def image_icon(self, value: str) -&gt; None:\n        self._image_icon = value\n        self._rebuild_thumbnail()\n\n    @property\n    def is_active(self) -&gt; bool:\n        return self._is_active\n\n    @is_active.setter\n    def is_active(self, value: bool) -&gt; None:\n        self._is_active = value\n        self._apply_body_state()\n\n    @property\n    def is_loading(self) -&gt; bool:\n        return self._is_loading\n\n    @is_loading.setter\n    def is_loading(self, value: bool) -&gt; None:\n        self._is_loading = value\n        self._apply_body_state()\n        self._rebuild_overlay()\n\n    @property\n    def is_error(self) -&gt; bool:\n        return self._is_error\n\n    @is_error.setter\n    def is_error(self, value: bool) -&gt; None:\n        self._is_error = value\n        self._apply_body_state()\n\n    @property\n    def is_hover(self) -&gt; bool:\n        return self._is_hover\n\n    @is_hover.setter\n    def is_hover(self, value: bool) -&gt; None:\n        self._is_hover = value\n        self._apply_body_state()\n\n    @property\n    def is_dragging(self) -&gt; bool:\n        return self._is_dragging\n\n    @is_dragging.setter\n    def is_dragging(self, value: bool) -&gt; None:\n        self._is_dragging = value\n        self._apply_body_state()\n\n    @property\n    def is_draggable(self) -&gt; bool:\n        return self._is_draggable\n\n    @is_draggable.setter\n    def is_draggable(self, value: bool) -&gt; None:\n        self._is_draggable = value\n        if value:\n            self.setCursor(QCursor(Qt.CursorShape.OpenHandCursor))\n        else:\n            self.unsetCursor()\n\n    # ------------------------------------------------------------------\n    # Mouse / drag events\n    # ------------------------------------------------------------------\n\n    def enterEvent(self, event: QtGui.QEnterEvent) -&gt; None:\n        if self._is_draggable:\n            self.setCursor(QCursor(Qt.CursorShape.OpenHandCursor))\n        super().enterEvent(event)\n\n    def leaveEvent(self, event: QtCore.QEvent) -&gt; None:\n        if self._is_draggable:\n            self.setCursor(QCursor(Qt.CursorShape.OpenHandCursor))\n        super().leaveEvent(event)\n\n    def mousePressEvent(self, event: QtGui.QMouseEvent) -&gt; None:\n        if event.button() == Qt.MouseButton.LeftButton:\n            self._drag_start_pos = event.pos()\n        super().mousePressEvent(event)\n\n    def mouseMoveEvent(self, event: QtGui.QMouseEvent) -&gt; None:\n        if (\n            self._is_draggable\n            and self._drag_start_pos is not None\n            and event.buttons() &amp; Qt.MouseButton.LeftButton\n        ):\n            delta = (event.pos() - self._drag_start_pos).manhattanLength()\n            if delta &gt;= QApplication.startDragDistance():\n                self._start_drag()\n                self._drag_start_pos = None\n                return\n        super().mouseMoveEvent(event)\n\n    def mouseReleaseEvent(self, event: QtGui.QMouseEvent) -&gt; None:\n        if (\n            event.button() == Qt.MouseButton.LeftButton\n            and self._drag_start_pos is not None\n        ):\n            self.activated.emit()\n            self._drag_start_pos = None\n        super().mouseReleaseEvent(event)\n\n    def _start_drag(self) -&gt; None:\n        drag = QDrag(self)\n        mime = QMimeData()\n        mime.setText(self._header)\n        drag.setMimeData(mime)\n        # Create a semi-transparent drag thumbnail from the card body\n        pxm = self._card_body.grab()\n        semi = QPixmap(pxm.size())\n        semi.fill(Qt.GlobalColor.transparent)\n        painter = QPainter(semi)\n        painter.setOpacity(0.75)\n        painter.drawPixmap(0, 0, pxm)\n        painter.end()\n        drag.setPixmap(semi)\n        drag.setHotSpot(self._card_body.rect().center())\n        self.is_dragging = True\n        drag.exec(Qt.DropAction.CopyAction | Qt.DropAction.MoveAction)\n        self.is_dragging = False\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/entity_card.html#client.ayon_ui_qt.components.entity_card.AYEntityCard.set_width","title":"<code>set_width(w)</code>","text":"<p>Set the card width and adjust height to maintain a 1.52:1 aspect ratio (default thumbnail ratio from front-end).</p> Source code in <code>client/ayon_ui_qt/components/entity_card.py</code> <pre><code>def set_width(self, w: int) -&gt; None:\n    \"\"\"Set the card width and adjust height to maintain a 1.52:1 aspect\n    ratio (default thumbnail ratio from front-end).\"\"\"\n    self.setFixedSize(w, int(w / CARD_RATIO))\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/entity_path.html","title":"entity_path","text":""},{"location":"autoapi/client/ayon_ui_qt/components/entity_thumbnail.html","title":"entity_thumbnail","text":""},{"location":"autoapi/client/ayon_ui_qt/components/entity_thumbnail.html#client.ayon_ui_qt.components.entity_thumbnail.AYEntityThumbnail","title":"<code>AYEntityThumbnail</code>","text":"<p>               Bases: <code>QPushButton</code></p> Source code in <code>client/ayon_ui_qt/components/entity_thumbnail.py</code> <pre><code>class AYEntityThumbnail(QPushButton):\n    class Variants(Enum):\n        Thumbnail = QPushButtonVariants.Thumbnail.value\n        Entity_Card = QPushButtonVariants.Entity_Card.value\n\n    def __init__(\n        self,\n        src: Path | str = \"\",\n        file_cacher: Callable | None = None,\n        placeholder_icon: str = \"image\",\n        placeholder_scale: float = 0.333333,\n        size: tuple = (85, 48),\n        fade_duration: int = 0,\n        variant: Variants = Variants.Thumbnail,\n        **kwargs,\n    ):\n        \"\"\"A widget that displays a thumbnail image for an entity, with options\n        to customize the image source, caching behavior, and size.\"\"\"\n        self._file_cacher = file_cacher\n        self._size = size\n        self._variant_str: str = variant.value\n        icn_size = size[1] * placeholder_scale\n        self._placeholder_icon = QIcon(\n            get_icon(placeholder_icon, color=\"#10ffffff\").pixmap(\n                QSize(icn_size, icn_size),\n            )\n        )\n\n        super().__init__(QIcon(), \"\", **kwargs)\n        self.setStyle(get_ayon_style())\n\n        self._src: Path | str = \"\"\n        self._incoming_pixmap: QPixmap | None = None\n        self._opacity: float = 1.0\n        self._anim = QVariantAnimation(self)\n        self._anim.setStartValue(0.0)\n        self._anim.setEndValue(1.0)\n        self._anim.setDuration(fade_duration)\n        self._anim.setEasingCurve(QEasingCurve.Type.InOutQuad)\n        self._anim.valueChanged.connect(self._on_fade_tick)\n        self._anim.finished.connect(self._on_fade_done)\n        self._bg_color = QColor(\n            get_ayon_style()\n            .model.get_style(\"QPushButton\", variant=self._variant_str)\n            .get(\"background-color\", \"#000000\")\n        )\n\n        self.set_thumbnail(src)\n        self.setFixedSize(*self._size)\n\n    def set_fade_duration(self, duration: int) -&gt; None:\n        \"\"\"Set the duration of the fade animation when changing thumbnails.\"\"\"\n        self._anim.setDuration(duration)\n\n    def _resolve_src(self, src: Path | str) -&gt; Path | str:\n        \"\"\"Resolve a cache key or path to an existing file path.\"\"\"\n        if Path(src).exists():\n            return src\n        ic = ImageCache.get_instance()\n        if self._file_cacher:\n            return ic.get(str(src), partial(self._file_cacher, src))\n        if ic.has(str(src)):\n            return ic.get_path(str(src)) or \"\"\n        return src\n\n    def _on_fade_tick(self, value: float) -&gt; None:\n        self._opacity = value\n        self.update()\n\n    def _on_fade_done(self) -&gt; None:\n        pixmap = self._incoming_pixmap\n        if pixmap and not pixmap.isNull():\n            icon = QIcon()\n            icon.addPixmap(pixmap)\n            self.setIcon(icon)\n            self.setIconSize(QSize(*self._size))\n        else:\n            self.setIcon(QIcon())\n        self._incoming_pixmap = None\n        self._opacity = 1.0\n        self.update()\n\n    def set_thumbnail(self, name: Path | str) -&gt; None:\n        \"\"\"Set the thumbnail image for the button.\"\"\"\n        self._src = self._resolve_src(name)\n        self._anim.stop()\n        if self._src and Path(self._src).exists():\n            raw = QPixmap(str(self._src))\n            self._incoming_pixmap = raw.scaled(\n                QSize(*self._size),\n                Qt.AspectRatioMode.KeepAspectRatio,\n                Qt.TransformationMode.SmoothTransformation,\n            )\n            self._opacity = 0.0\n            self._anim.start()\n        else:\n            self._incoming_pixmap = None\n            self._opacity = 1.0\n            self.setIcon(self._placeholder_icon)\n\n    def paintEvent(self, arg__1: QPaintEvent) -&gt; None:\n        p = QPainter(self)\n        option = QStyleOptionButton()\n        self.initStyleOption(option)\n        # override rect set by stylesheet\n        size = QSize(*self._size)\n        self.setFixedSize(size)\n        option.rect = QRect(0, 0, size.width(), size.height())\n        # draw base (current icon)\n        get_ayon_style().drawControl(\n            QStyle.ControlElement.CE_PushButton, option, p, self\n        )\n        # overlay incoming pixmap with fade opacity\n        if self._incoming_pixmap and not self._incoming_pixmap.isNull():\n            x = (size.width() - self._incoming_pixmap.width()) // 2\n            y = (size.height() - self._incoming_pixmap.height()) // 2\n            p.save()\n            p.setClipRect(QRect(1, 1, size.width() - 2, size.height() - 2))\n            p.setOpacity(self._opacity)\n            p.fillRect(option.rect, self._bg_color)\n            p.drawPixmap(x, y, self._incoming_pixmap)\n            p.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/entity_thumbnail.html#client.ayon_ui_qt.components.entity_thumbnail.AYEntityThumbnail.__init__","title":"<code>__init__(src='', file_cacher=None, placeholder_icon='image', placeholder_scale=0.333333, size=(85, 48), fade_duration=0, variant=Variants.Thumbnail, **kwargs)</code>","text":"<p>A widget that displays a thumbnail image for an entity, with options to customize the image source, caching behavior, and size.</p> Source code in <code>client/ayon_ui_qt/components/entity_thumbnail.py</code> <pre><code>def __init__(\n    self,\n    src: Path | str = \"\",\n    file_cacher: Callable | None = None,\n    placeholder_icon: str = \"image\",\n    placeholder_scale: float = 0.333333,\n    size: tuple = (85, 48),\n    fade_duration: int = 0,\n    variant: Variants = Variants.Thumbnail,\n    **kwargs,\n):\n    \"\"\"A widget that displays a thumbnail image for an entity, with options\n    to customize the image source, caching behavior, and size.\"\"\"\n    self._file_cacher = file_cacher\n    self._size = size\n    self._variant_str: str = variant.value\n    icn_size = size[1] * placeholder_scale\n    self._placeholder_icon = QIcon(\n        get_icon(placeholder_icon, color=\"#10ffffff\").pixmap(\n            QSize(icn_size, icn_size),\n        )\n    )\n\n    super().__init__(QIcon(), \"\", **kwargs)\n    self.setStyle(get_ayon_style())\n\n    self._src: Path | str = \"\"\n    self._incoming_pixmap: QPixmap | None = None\n    self._opacity: float = 1.0\n    self._anim = QVariantAnimation(self)\n    self._anim.setStartValue(0.0)\n    self._anim.setEndValue(1.0)\n    self._anim.setDuration(fade_duration)\n    self._anim.setEasingCurve(QEasingCurve.Type.InOutQuad)\n    self._anim.valueChanged.connect(self._on_fade_tick)\n    self._anim.finished.connect(self._on_fade_done)\n    self._bg_color = QColor(\n        get_ayon_style()\n        .model.get_style(\"QPushButton\", variant=self._variant_str)\n        .get(\"background-color\", \"#000000\")\n    )\n\n    self.set_thumbnail(src)\n    self.setFixedSize(*self._size)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/entity_thumbnail.html#client.ayon_ui_qt.components.entity_thumbnail.AYEntityThumbnail.set_fade_duration","title":"<code>set_fade_duration(duration)</code>","text":"<p>Set the duration of the fade animation when changing thumbnails.</p> Source code in <code>client/ayon_ui_qt/components/entity_thumbnail.py</code> <pre><code>def set_fade_duration(self, duration: int) -&gt; None:\n    \"\"\"Set the duration of the fade animation when changing thumbnails.\"\"\"\n    self._anim.setDuration(duration)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/entity_thumbnail.html#client.ayon_ui_qt.components.entity_thumbnail.AYEntityThumbnail.set_thumbnail","title":"<code>set_thumbnail(name)</code>","text":"<p>Set the thumbnail image for the button.</p> Source code in <code>client/ayon_ui_qt/components/entity_thumbnail.py</code> <pre><code>def set_thumbnail(self, name: Path | str) -&gt; None:\n    \"\"\"Set the thumbnail image for the button.\"\"\"\n    self._src = self._resolve_src(name)\n    self._anim.stop()\n    if self._src and Path(self._src).exists():\n        raw = QPixmap(str(self._src))\n        self._incoming_pixmap = raw.scaled(\n            QSize(*self._size),\n            Qt.AspectRatioMode.KeepAspectRatio,\n            Qt.TransformationMode.SmoothTransformation,\n        )\n        self._opacity = 0.0\n        self._anim.start()\n    else:\n        self._incoming_pixmap = None\n        self._opacity = 1.0\n        self.setIcon(self._placeholder_icon)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html","title":"filter","text":"<p>AYFilter component for multi-select filtering with tags and dropdown.</p> <p>This module provides: - FilterItem: Data model for filter options - FilterCheckboxDelegate: Custom delegate for checkbox-style rendering - FilterDropdownPopup: Floating popup for filter selection - AYFilter: Main filter widget with tag bar and dropdown selection</p>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.AYFilter","title":"<code>AYFilter</code>","text":"<p>               Bases: <code>AYFrame</code></p> <p>Multi-select filter widget with tag display and dropdown selection.</p> <p>Displays selected filters as dismissible tags in a top bar, with a dropdown panel for selecting/deselecting filter options.</p> Signals <p>filter_changed: Emitted when selection changes. Passes list of                 selected FilterItem keys. filter_added: Emitted when a filter is selected. Passes the key. filter_removed: Emitted when a filter is deselected. Passes the key.</p> <p>Attributes:</p> Name Type Description <code>items</code> <p>List of FilterItem objects representing available filters.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>class AYFilter(AYFrame):\n    \"\"\"Multi-select filter widget with tag display and dropdown selection.\n\n    Displays selected filters as dismissible tags in a top bar, with a\n    dropdown panel for selecting/deselecting filter options.\n\n    Signals:\n        filter_changed: Emitted when selection changes. Passes list of\n                        selected FilterItem keys.\n        filter_added: Emitted when a filter is selected. Passes the key.\n        filter_removed: Emitted when a filter is deselected. Passes the key.\n\n    Attributes:\n        items: List of FilterItem objects representing available filters.\n    \"\"\"\n\n    filter_changed = Signal(list)  # List[str] of selected keys\n    filter_added = Signal(str)  # key of added filter\n    filter_removed = Signal(str)  # key of removed filter\n\n    Variants = QFrameVariants\n\n    def __init__(\n        self,\n        parent: QtWidgets.QWidget | None = None,\n        label: str = \"Sort by\",\n        items: List[FilterItem] | None = None,\n        default_color: str = \"#8fceff\",\n        variant: Variants = Variants.Low,\n    ) -&gt; None:\n        \"\"\"Initialize the filter widget.\n\n        Args:\n            parent: Optional parent widget.\n            label: Text displayed before the filter tags.\n            items: Initial list of filter items.\n            default_color: Default tag color when item has no color set.\n            variant: Frame variant for background styling.\n        \"\"\"\n        super().__init__(parent, variant=variant, margin=0)\n\n        self._label_text = label\n        self._items: List[FilterItem] = list(items) if items else []\n        self._default_color = default_color\n        self._tags: dict[str, AYTag] = {}\n        self._dropdown_visible = False\n\n        self._init_ui()\n        self._connect_signals()\n        self._sync_tags_from_items()\n\n    # --- UI Setup ---\n\n    def _init_ui(self) -&gt; None:\n        \"\"\"Build the widget layout.\"\"\"\n        main_layout = AYVBoxLayout(self, margin=0, spacing=0)\n\n        # Top bar\n        self._top_bar = AYContainer(\n            layout=AYContainer.Layout.HBox,\n            variant=AYContainer.Variants.Low,\n            layout_margin=4,\n            layout_spacing=4,\n        )\n        main_layout.addWidget(self._top_bar)\n\n        # Label\n        self._label = AYLabel(self._label_text)\n        self._label.setContentsMargins(10, 0, 5, 0)\n        self._top_bar.add_widget(self._label)\n\n        # Tags container\n        self._tags_container = AYContainer(\n            layout=AYContainer.Layout.HBox,\n            variant=AYContainer.Variants.Default,\n            layout_margin=0,\n            layout_spacing=4,\n        )\n        lyt = self._tags_container.layout()\n        if lyt:\n            lyt.setSizeConstraint(\n                QtWidgets.QLayout.SizeConstraint.SetFixedSize\n            )\n        self._top_bar.add_widget(self._tags_container)\n\n        # Spacer\n        self._top_bar.addStretch()\n\n        # Toggle button\n        self._toggle_btn = AYButton(\n            icon=\"keyboard_arrow_down\",\n            variant=AYButton.Variants.Nav_Small,\n            tooltip=\"Toggle filter options\",\n        )\n        self._toggle_btn.setContentsMargins(4, 4, 4, 10)\n        self._top_bar.add_widget(self._toggle_btn)\n\n        # Create floating dropdown popup (not added to layout)\n        self._dropdown_popup = FilterDropdownPopup()\n        self._dropdown_popup.populate(self._items)\n\n    def _connect_signals(self) -&gt; None:\n        \"\"\"Connect internal signals.\"\"\"\n        self._toggle_btn.clicked.connect(self._on_toggle_dropdown)\n        self._dropdown_popup.item_toggled.connect(self._on_popup_item_toggled)\n        self._dropdown_popup.popup_closed.connect(self._on_popup_closed)\n\n    # --- Public API ---\n\n    def add_filter(self, item: FilterItem) -&gt; None:\n        \"\"\"Add a new filter option.\n\n        Args:\n            item: The FilterItem to add.\n        \"\"\"\n        if item not in self._items:\n            self._items.append(item)\n            self._repopulate_popup()\n            if item.selected:\n                self._add_tag(item)\n\n    def remove_filter(self, key: str) -&gt; None:\n        \"\"\"Remove a filter option by key.\n\n        Args:\n            key: Unique identifier of the filter to remove.\n        \"\"\"\n        for i, item in enumerate(self._items):\n            if item.key == key:\n                self._items.pop(i)\n                self._remove_tag(key)\n                self._repopulate_popup()\n                break\n\n    def set_filter_selected(self, key: str, selected: bool) -&gt; None:\n        \"\"\"Set selection state of a filter.\n\n        Args:\n            key: Unique identifier of the filter.\n            selected: New selection state.\n        \"\"\"\n        for item in self._items:\n            if item.key == key:\n                if item.selected != selected:\n                    item.selected = selected\n                    self._update_popup_item_state(key, selected)\n                    if selected:\n                        self._add_tag(item)\n                        self.filter_added.emit(key)\n                    else:\n                        self._remove_tag(key)\n                        self.filter_removed.emit(key)\n                    self._emit_filter_changed()\n                break\n\n    def get_selected_keys(self) -&gt; List[str]:\n        \"\"\"Get list of selected filter keys.\n\n        Returns:\n            List of keys for currently selected filters.\n        \"\"\"\n        return [item.key for item in self._items if item.selected]\n\n    def get_selected_items(self) -&gt; List[FilterItem]:\n        \"\"\"Get list of selected filter items.\n\n        Returns:\n            List of FilterItem objects that are selected.\n        \"\"\"\n        return [item for item in self._items if item.selected]\n\n    def clear_selection(self) -&gt; None:\n        \"\"\"Deselect all filters.\"\"\"\n        for item in self._items:\n            if item.selected:\n                self.set_filter_selected(item.key, False)\n\n    def select_all(self) -&gt; None:\n        \"\"\"Select all filters.\"\"\"\n        for item in self._items:\n            if not item.selected:\n                self.set_filter_selected(item.key, True)\n\n    # --- Private Methods ---\n\n    def _repopulate_popup(self) -&gt; None:\n        \"\"\"Repopulate the popup with current filter items.\"\"\"\n        self._dropdown_popup.populate(self._items)\n\n    def _update_popup_item_state(self, key: str, selected: bool) -&gt; None:\n        \"\"\"Update checkbox state of a popup item.\n\n        Args:\n            key: Key of the item to update.\n            selected: New selection state.\n        \"\"\"\n        self._dropdown_popup.update_item_state(key, selected)\n\n    def _sync_tags_from_items(self) -&gt; None:\n        \"\"\"Synchronize tags with current filter item states.\"\"\"\n        for item in self._items:\n            if item.selected and item.key not in self._tags:\n                self._add_tag(item)\n            elif not item.selected and item.key in self._tags:\n                self._remove_tag(item.key)\n\n    def _add_tag(self, item: FilterItem) -&gt; None:\n        \"\"\"Create and add a tag widget for a filter item.\n\n        Args:\n            item: The FilterItem to create a tag for.\n        \"\"\"\n        if item.key in self._tags:\n            return\n\n        color = QColor(item.color or self._default_color)\n        tag = AYTag(item.key, color, label=item.label)\n        tag.tag_removed.connect(self._on_tag_removed)\n        tag.tag_expanded.connect(self._on_tag_expanded)\n\n        self._tags[item.key] = tag\n        self._tags_container.add_widget(tag)\n\n    def _remove_tag(self, key: str) -&gt; None:\n        \"\"\"Remove a tag widget.\n\n        Args:\n            key: Key of the tag to remove.\n        \"\"\"\n        if key not in self._tags:\n            return\n\n        tag = self._tags.pop(key)\n        tag.setParent(None)\n        tag.deleteLater()\n\n    def _emit_filter_changed(self) -&gt; None:\n        \"\"\"Emit filter_changed signal with current selection.\"\"\"\n        self.filter_changed.emit(self.get_selected_keys())\n\n    # --- Event Handlers ---\n\n    def _on_toggle_dropdown(self) -&gt; None:\n        \"\"\"Handle toggle button click.\"\"\"\n        if self._dropdown_visible:\n            # Close popup\n            self._dropdown_popup.close()\n        else:\n            # Show popup below the top bar\n            self._dropdown_visible = True\n            self._toggle_btn.set_icon(\"keyboard_arrow_up\")\n            self._dropdown_popup.show_below(self._top_bar)\n\n    def _on_popup_item_toggled(self, key: str, selected: bool) -&gt; None:\n        \"\"\"Handle popup item toggle.\n\n        Args:\n            key: Key of the toggled filter.\n            selected: New selection state.\n        \"\"\"\n        self.set_filter_selected(key, selected)\n\n    def _on_popup_closed(self) -&gt; None:\n        \"\"\"Handle popup close event.\"\"\"\n        self._dropdown_visible = False\n        self._toggle_btn.set_icon(\"keyboard_arrow_down\")\n\n    def _on_tag_removed(self, key: str) -&gt; None:\n        \"\"\"Handle tag X button click.\n\n        Args:\n            key: Key of the removed tag.\n        \"\"\"\n        self.set_filter_selected(key, False)\n\n    def _on_tag_expanded(self, key: str) -&gt; None:\n        \"\"\"Handle tag expand button click - toggle dropdown.\n\n        Args:\n            key: Key of the expanded tag.\n        \"\"\"\n        self._on_toggle_dropdown()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.AYFilter.__init__","title":"<code>__init__(parent=None, label='Sort by', items=None, default_color='#8fceff', variant=Variants.Low)</code>","text":"<p>Initialize the filter widget.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QWidget | None</code> <p>Optional parent widget.</p> <code>None</code> <code>label</code> <code>str</code> <p>Text displayed before the filter tags.</p> <code>'Sort by'</code> <code>items</code> <code>List[FilterItem] | None</code> <p>Initial list of filter items.</p> <code>None</code> <code>default_color</code> <code>str</code> <p>Default tag color when item has no color set.</p> <code>'#8fceff'</code> <code>variant</code> <code>Variants</code> <p>Frame variant for background styling.</p> <code>Low</code> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def __init__(\n    self,\n    parent: QtWidgets.QWidget | None = None,\n    label: str = \"Sort by\",\n    items: List[FilterItem] | None = None,\n    default_color: str = \"#8fceff\",\n    variant: Variants = Variants.Low,\n) -&gt; None:\n    \"\"\"Initialize the filter widget.\n\n    Args:\n        parent: Optional parent widget.\n        label: Text displayed before the filter tags.\n        items: Initial list of filter items.\n        default_color: Default tag color when item has no color set.\n        variant: Frame variant for background styling.\n    \"\"\"\n    super().__init__(parent, variant=variant, margin=0)\n\n    self._label_text = label\n    self._items: List[FilterItem] = list(items) if items else []\n    self._default_color = default_color\n    self._tags: dict[str, AYTag] = {}\n    self._dropdown_visible = False\n\n    self._init_ui()\n    self._connect_signals()\n    self._sync_tags_from_items()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.AYFilter.add_filter","title":"<code>add_filter(item)</code>","text":"<p>Add a new filter option.</p> <p>Parameters:</p> Name Type Description Default <code>item</code> <code>FilterItem</code> <p>The FilterItem to add.</p> required Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def add_filter(self, item: FilterItem) -&gt; None:\n    \"\"\"Add a new filter option.\n\n    Args:\n        item: The FilterItem to add.\n    \"\"\"\n    if item not in self._items:\n        self._items.append(item)\n        self._repopulate_popup()\n        if item.selected:\n            self._add_tag(item)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.AYFilter.clear_selection","title":"<code>clear_selection()</code>","text":"<p>Deselect all filters.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def clear_selection(self) -&gt; None:\n    \"\"\"Deselect all filters.\"\"\"\n    for item in self._items:\n        if item.selected:\n            self.set_filter_selected(item.key, False)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.AYFilter.get_selected_items","title":"<code>get_selected_items()</code>","text":"<p>Get list of selected filter items.</p> <p>Returns:</p> Type Description <code>List[FilterItem]</code> <p>List of FilterItem objects that are selected.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def get_selected_items(self) -&gt; List[FilterItem]:\n    \"\"\"Get list of selected filter items.\n\n    Returns:\n        List of FilterItem objects that are selected.\n    \"\"\"\n    return [item for item in self._items if item.selected]\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.AYFilter.get_selected_keys","title":"<code>get_selected_keys()</code>","text":"<p>Get list of selected filter keys.</p> <p>Returns:</p> Type Description <code>List[str]</code> <p>List of keys for currently selected filters.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def get_selected_keys(self) -&gt; List[str]:\n    \"\"\"Get list of selected filter keys.\n\n    Returns:\n        List of keys for currently selected filters.\n    \"\"\"\n    return [item.key for item in self._items if item.selected]\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.AYFilter.remove_filter","title":"<code>remove_filter(key)</code>","text":"<p>Remove a filter option by key.</p> <p>Parameters:</p> Name Type Description Default <code>key</code> <code>str</code> <p>Unique identifier of the filter to remove.</p> required Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def remove_filter(self, key: str) -&gt; None:\n    \"\"\"Remove a filter option by key.\n\n    Args:\n        key: Unique identifier of the filter to remove.\n    \"\"\"\n    for i, item in enumerate(self._items):\n        if item.key == key:\n            self._items.pop(i)\n            self._remove_tag(key)\n            self._repopulate_popup()\n            break\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.AYFilter.select_all","title":"<code>select_all()</code>","text":"<p>Select all filters.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def select_all(self) -&gt; None:\n    \"\"\"Select all filters.\"\"\"\n    for item in self._items:\n        if not item.selected:\n            self.set_filter_selected(item.key, True)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.AYFilter.set_filter_selected","title":"<code>set_filter_selected(key, selected)</code>","text":"<p>Set selection state of a filter.</p> <p>Parameters:</p> Name Type Description Default <code>key</code> <code>str</code> <p>Unique identifier of the filter.</p> required <code>selected</code> <code>bool</code> <p>New selection state.</p> required Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def set_filter_selected(self, key: str, selected: bool) -&gt; None:\n    \"\"\"Set selection state of a filter.\n\n    Args:\n        key: Unique identifier of the filter.\n        selected: New selection state.\n    \"\"\"\n    for item in self._items:\n        if item.key == key:\n            if item.selected != selected:\n                item.selected = selected\n                self._update_popup_item_state(key, selected)\n                if selected:\n                    self._add_tag(item)\n                    self.filter_added.emit(key)\n                else:\n                    self._remove_tag(key)\n                    self.filter_removed.emit(key)\n                self._emit_filter_changed()\n            break\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterCheckboxDelegate","title":"<code>FilterCheckboxDelegate</code>","text":"<p>               Bases: <code>QStyledItemDelegate</code></p> <p>Delegate for rendering filter items with checkbox indicators.</p> <p>Draws a small square checkbox indicator on the right side of each item. Checked items display an X icon inside the checkbox.</p> <p>Attributes:</p> Name Type Description <code>CHECKBOX_SIZE</code> <p>Size of the checkbox indicator in pixels.</p> <code>CHECKBOX_MARGIN</code> <p>Margin around the checkbox.</p> <code>TEXT_PADDING</code> <p>Padding for the text from the left edge.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>class FilterCheckboxDelegate(QtWidgets.QStyledItemDelegate):\n    \"\"\"Delegate for rendering filter items with checkbox indicators.\n\n    Draws a small square checkbox indicator on the right side of each item.\n    Checked items display an X icon inside the checkbox.\n\n    Attributes:\n        CHECKBOX_SIZE: Size of the checkbox indicator in pixels.\n        CHECKBOX_MARGIN: Margin around the checkbox.\n        TEXT_PADDING: Padding for the text from the left edge.\n    \"\"\"\n\n    CHECKBOX_SIZE = 16\n    CHECKBOX_MARGIN = 8\n    TEXT_PADDING = 12\n\n    Variants = QStyledItemDelegateVariants\n\n    def __init__(\n        self,\n        parent: QtWidgets.QWidget | None = None,\n        variant: Variants = Variants.Default,\n    ) -&gt; None:\n        \"\"\"Initialize the delegate.\n\n        Args:\n            parent: Optional parent widget.\n            variant: Style variant for the delegate.\n        \"\"\"\n        super().__init__(parent)\n        self._variant_str = variant.value\n\n    def paint(\n        self,\n        painter: QPainter,\n        option: QStyleOptionViewItem,\n        index: QModelIndex | QPersistentModelIndex,\n    ) -&gt; None:\n        \"\"\"Paint the filter item with checkbox indicator.\n\n        Args:\n            painter: QPainter instance for rendering.\n            option: Style options for the item.\n            index: Model index of the item.\n        \"\"\"\n        # Update option with model data for the drawer\n        option.text = index.data(Qt.ItemDataRole.DisplayRole) or \"\"\n        check_state = index.data(Qt.ItemDataRole.CheckStateRole)\n        option.checkState = (\n            Qt.CheckState.Checked\n            if check_state == Qt.CheckState.Checked\n            else Qt.CheckState.Unchecked\n        )\n\n        # Delegate painting to AYONStyle\n        parent = self.parent()\n        widget = parent if isinstance(parent, QtWidgets.QWidget) else None\n        get_ayon_style().drawControl(\n            QStyle.ControlElement.CE_ItemViewItem,\n            option,\n            painter,\n            widget,\n        )\n\n    def sizeHint(\n        self,\n        option: QStyleOptionViewItem,\n        index: QModelIndex | QPersistentModelIndex,\n    ) -&gt; QtCore.QSize:\n        \"\"\"Return size hint for the item.\n\n        Args:\n            option: Style options for the item.\n            index: Model index of the item.\n\n        Returns:\n            Recommended size for the item.\n        \"\"\"\n        base = super().sizeHint(option, index)\n        return QtCore.QSize(base.width(), max(base.height(), 36))\n\n    def editorEvent(\n        self,\n        event: QtCore.QEvent,\n        model: QtCore.QAbstractItemModel,\n        option: QStyleOptionViewItem,\n        index: QModelIndex | QPersistentModelIndex,\n    ) -&gt; bool:\n        \"\"\"Handle click events to toggle checkbox state.\n\n        Args:\n            event: The input event.\n            model: The data model.\n            option: Style options for the item.\n            index: Model index of the item.\n\n        Returns:\n            True if the event was handled.\n        \"\"\"\n        if event.type() == QtCore.QEvent.Type.MouseButtonRelease:\n            current = index.data(Qt.ItemDataRole.CheckStateRole)\n            new_state = (\n                Qt.CheckState.Unchecked\n                if current == Qt.CheckState.Checked\n                else Qt.CheckState.Checked\n            )\n            model.setData(index, new_state, Qt.ItemDataRole.CheckStateRole)\n            return True\n        return super().editorEvent(event, model, option, index)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterCheckboxDelegate.__init__","title":"<code>__init__(parent=None, variant=Variants.Default)</code>","text":"<p>Initialize the delegate.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QWidget | None</code> <p>Optional parent widget.</p> <code>None</code> <code>variant</code> <code>Variants</code> <p>Style variant for the delegate.</p> <code>Default</code> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def __init__(\n    self,\n    parent: QtWidgets.QWidget | None = None,\n    variant: Variants = Variants.Default,\n) -&gt; None:\n    \"\"\"Initialize the delegate.\n\n    Args:\n        parent: Optional parent widget.\n        variant: Style variant for the delegate.\n    \"\"\"\n    super().__init__(parent)\n    self._variant_str = variant.value\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterCheckboxDelegate.editorEvent","title":"<code>editorEvent(event, model, option, index)</code>","text":"<p>Handle click events to toggle checkbox state.</p> <p>Parameters:</p> Name Type Description Default <code>event</code> <code>QEvent</code> <p>The input event.</p> required <code>model</code> <code>QAbstractItemModel</code> <p>The data model.</p> required <code>option</code> <code>QStyleOptionViewItem</code> <p>Style options for the item.</p> required <code>index</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Model index of the item.</p> required <p>Returns:</p> Type Description <code>bool</code> <p>True if the event was handled.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def editorEvent(\n    self,\n    event: QtCore.QEvent,\n    model: QtCore.QAbstractItemModel,\n    option: QStyleOptionViewItem,\n    index: QModelIndex | QPersistentModelIndex,\n) -&gt; bool:\n    \"\"\"Handle click events to toggle checkbox state.\n\n    Args:\n        event: The input event.\n        model: The data model.\n        option: Style options for the item.\n        index: Model index of the item.\n\n    Returns:\n        True if the event was handled.\n    \"\"\"\n    if event.type() == QtCore.QEvent.Type.MouseButtonRelease:\n        current = index.data(Qt.ItemDataRole.CheckStateRole)\n        new_state = (\n            Qt.CheckState.Unchecked\n            if current == Qt.CheckState.Checked\n            else Qt.CheckState.Checked\n        )\n        model.setData(index, new_state, Qt.ItemDataRole.CheckStateRole)\n        return True\n    return super().editorEvent(event, model, option, index)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterCheckboxDelegate.paint","title":"<code>paint(painter, option, index)</code>","text":"<p>Paint the filter item with checkbox indicator.</p> <p>Parameters:</p> Name Type Description Default <code>painter</code> <code>QPainter</code> <p>QPainter instance for rendering.</p> required <code>option</code> <code>QStyleOptionViewItem</code> <p>Style options for the item.</p> required <code>index</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Model index of the item.</p> required Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def paint(\n    self,\n    painter: QPainter,\n    option: QStyleOptionViewItem,\n    index: QModelIndex | QPersistentModelIndex,\n) -&gt; None:\n    \"\"\"Paint the filter item with checkbox indicator.\n\n    Args:\n        painter: QPainter instance for rendering.\n        option: Style options for the item.\n        index: Model index of the item.\n    \"\"\"\n    # Update option with model data for the drawer\n    option.text = index.data(Qt.ItemDataRole.DisplayRole) or \"\"\n    check_state = index.data(Qt.ItemDataRole.CheckStateRole)\n    option.checkState = (\n        Qt.CheckState.Checked\n        if check_state == Qt.CheckState.Checked\n        else Qt.CheckState.Unchecked\n    )\n\n    # Delegate painting to AYONStyle\n    parent = self.parent()\n    widget = parent if isinstance(parent, QtWidgets.QWidget) else None\n    get_ayon_style().drawControl(\n        QStyle.ControlElement.CE_ItemViewItem,\n        option,\n        painter,\n        widget,\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterCheckboxDelegate.sizeHint","title":"<code>sizeHint(option, index)</code>","text":"<p>Return size hint for the item.</p> <p>Parameters:</p> Name Type Description Default <code>option</code> <code>QStyleOptionViewItem</code> <p>Style options for the item.</p> required <code>index</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Model index of the item.</p> required <p>Returns:</p> Type Description <code>QSize</code> <p>Recommended size for the item.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def sizeHint(\n    self,\n    option: QStyleOptionViewItem,\n    index: QModelIndex | QPersistentModelIndex,\n) -&gt; QtCore.QSize:\n    \"\"\"Return size hint for the item.\n\n    Args:\n        option: Style options for the item.\n        index: Model index of the item.\n\n    Returns:\n        Recommended size for the item.\n    \"\"\"\n    base = super().sizeHint(option, index)\n    return QtCore.QSize(base.width(), max(base.height(), 36))\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterDropdownPopup","title":"<code>FilterDropdownPopup</code>","text":"<p>               Bases: <code>AYFrame</code></p> <p>Floating popup widget for filter selection.</p> <p>This popup appears below the toggle button and contains a list of filter items with checkboxes. It closes when clicking outside, pressing Escape, or when explicitly closed.</p> Signals <p>item_toggled: Emitted when a filter item is toggled.               Passes (key: str, selected: bool). popup_closed: Emitted when the popup is closed.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>class FilterDropdownPopup(AYFrame):\n    \"\"\"Floating popup widget for filter selection.\n\n    This popup appears below the toggle button and contains a list of\n    filter items with checkboxes. It closes when clicking outside,\n    pressing Escape, or when explicitly closed.\n\n    Signals:\n        item_toggled: Emitted when a filter item is toggled.\n                      Passes (key: str, selected: bool).\n        popup_closed: Emitted when the popup is closed.\n    \"\"\"\n\n    item_toggled = Signal(str, bool)  # (key, selected)\n    popup_closed = Signal()\n\n    # Styling constants\n    POPUP_MIN_WIDTH = 180\n    POPUP_MAX_HEIGHT = 300\n\n    def __init__(\n        self,\n        parent: QtWidgets.QWidget | None = None,\n    ) -&gt; None:\n        \"\"\"Initialize the dropdown popup.\n\n        Args:\n            parent: Optional parent widget.\n        \"\"\"\n        super().__init__(parent, variant=AYFrame.Variants.Low)\n\n        # Set popup window flags\n        self.setWindowFlags(\n            Qt.WindowType.Popup\n            | Qt.WindowType.FramelessWindowHint\n            | Qt.WindowType.NoDropShadowWindowHint\n        )\n        self.setAttribute(Qt.WidgetAttribute.WA_WindowPropagation)\n\n        self._init_ui()\n\n    def _init_ui(self) -&gt; None:\n        \"\"\"Build the popup layout.\"\"\"\n        layout = AYVBoxLayout(self, margin=4, spacing=0)\n\n        # List widget for filter items\n        self._list_widget = QtWidgets.QListWidget(self)\n        self._list_widget.setSelectionMode(\n            QtWidgets.QAbstractItemView.SelectionMode.NoSelection\n        )\n        self._list_widget.setItemDelegate(\n            FilterCheckboxDelegate(self._list_widget)\n        )\n        self._list_widget.setMouseTracking(True)\n        self._list_widget.setHorizontalScrollBarPolicy(\n            Qt.ScrollBarPolicy.ScrollBarAlwaysOff\n        )\n        self._list_widget.setVerticalScrollBarPolicy(\n            Qt.ScrollBarPolicy.ScrollBarAsNeeded\n        )\n\n        self._list_widget.clicked.connect(self._on_item_clicked)\n\n        layout.addWidget(self._list_widget)\n\n        # Set size constraints\n        self.setMinimumWidth(self.POPUP_MIN_WIDTH)\n        self.setMaximumHeight(self.POPUP_MAX_HEIGHT)\n\n    def populate(self, items: List[FilterItem]) -&gt; None:\n        \"\"\"Populate the list with filter items.\n\n        Args:\n            items: List of FilterItem objects to display.\n        \"\"\"\n        self._list_widget.clear()\n        for item in items:\n            self._add_list_item(item)\n\n        # Adjust height based on content\n        self._adjust_size()\n\n    def _add_list_item(self, item: FilterItem) -&gt; None:\n        \"\"\"Add a filter item to the list widget.\n\n        Args:\n            item: The FilterItem to add to the list.\n        \"\"\"\n        list_item = QtWidgets.QListWidgetItem(item.label)\n        list_item.setData(QtCore.Qt.ItemDataRole.UserRole, item.key)\n        list_item.setData(\n            QtCore.Qt.ItemDataRole.CheckStateRole,\n            QtCore.Qt.CheckState.Checked\n            if item.selected\n            else QtCore.Qt.CheckState.Unchecked,\n        )\n        list_item.setFlags(\n            list_item.flags() | QtCore.Qt.ItemFlag.ItemIsUserCheckable\n        )\n        self._list_widget.addItem(list_item)\n\n    def _adjust_size(self) -&gt; None:\n        \"\"\"Adjust popup size based on content.\"\"\"\n        item_count = self._list_widget.count()\n        if item_count == 0:\n            return\n\n        # Calculate height based on items\n        row_height = 36  # From delegate sizeHint\n        content_height = item_count * row_height + 8  # 8 for margins\n        height = min(content_height, self.POPUP_MAX_HEIGHT)\n        self.setFixedHeight(height)\n\n    def update_item_state(self, key: str, selected: bool) -&gt; None:\n        \"\"\"Update the check state of a specific item.\n\n        Args:\n            key: Key of the item to update.\n            selected: New selection state.\n        \"\"\"\n        for i in range(self._list_widget.count()):\n            item = self._list_widget.item(i)\n            if item and item.data(QtCore.Qt.ItemDataRole.UserRole) == key:\n                item.setData(\n                    QtCore.Qt.ItemDataRole.CheckStateRole,\n                    QtCore.Qt.CheckState.Checked\n                    if selected\n                    else QtCore.Qt.CheckState.Unchecked,\n                )\n                break\n\n    def show_below(self, widget: QtWidgets.QWidget) -&gt; None:\n        \"\"\"Show the popup positioned below the given widget.\n\n        Args:\n            widget: Widget to position the popup below.\n        \"\"\"\n        # Get global position of the bottom-left of the widget\n        global_pos = widget.mapToGlobal(QtCore.QPoint(0, widget.height()))\n\n        # Ensure popup doesn't go off screen\n        screen = QtWidgets.QApplication.screenAt(global_pos)\n        if screen:\n            screen_geo = screen.availableGeometry()\n\n            # Adjust horizontal position if needed\n            if global_pos.x() + self.width() &gt; screen_geo.right():\n                global_pos.setX(screen_geo.right() - self.width())\n\n            # Show above if not enough space below\n            if global_pos.y() + self.height() &gt; screen_geo.bottom():\n                global_pos = widget.mapToGlobal(QtCore.QPoint(0, 0))\n                global_pos.setY(global_pos.y() - self.height())\n\n        self.move(global_pos)\n        self.show()\n\n    def _on_item_clicked(self, index: QtCore.QModelIndex) -&gt; None:\n        \"\"\"Handle list item click - emit toggle signal.\n\n        Args:\n            index: Model index of the clicked item.\n        \"\"\"\n        item = self._list_widget.item(index.row())\n        if not item:\n            return\n\n        key = item.data(QtCore.Qt.ItemDataRole.UserRole)\n        current_state = item.data(QtCore.Qt.ItemDataRole.CheckStateRole)\n        new_selected = current_state == QtCore.Qt.CheckState.Checked\n\n        self.item_toggled.emit(key, new_selected)\n\n    def keyPressEvent(self, event: QtGui.QKeyEvent) -&gt; None:\n        \"\"\"Handle key press events.\n\n        Args:\n            event: The key event.\n        \"\"\"\n        if event.key() == Qt.Key.Key_Escape:\n            self.close()\n        else:\n            super().keyPressEvent(event)\n\n    def closeEvent(self, event: QtGui.QCloseEvent) -&gt; None:\n        \"\"\"Handle close event.\n\n        Args:\n            event: The close event.\n        \"\"\"\n        self.popup_closed.emit()\n        super().closeEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterDropdownPopup.__init__","title":"<code>__init__(parent=None)</code>","text":"<p>Initialize the dropdown popup.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QWidget | None</code> <p>Optional parent widget.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def __init__(\n    self,\n    parent: QtWidgets.QWidget | None = None,\n) -&gt; None:\n    \"\"\"Initialize the dropdown popup.\n\n    Args:\n        parent: Optional parent widget.\n    \"\"\"\n    super().__init__(parent, variant=AYFrame.Variants.Low)\n\n    # Set popup window flags\n    self.setWindowFlags(\n        Qt.WindowType.Popup\n        | Qt.WindowType.FramelessWindowHint\n        | Qt.WindowType.NoDropShadowWindowHint\n    )\n    self.setAttribute(Qt.WidgetAttribute.WA_WindowPropagation)\n\n    self._init_ui()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterDropdownPopup.closeEvent","title":"<code>closeEvent(event)</code>","text":"<p>Handle close event.</p> <p>Parameters:</p> Name Type Description Default <code>event</code> <code>QCloseEvent</code> <p>The close event.</p> required Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def closeEvent(self, event: QtGui.QCloseEvent) -&gt; None:\n    \"\"\"Handle close event.\n\n    Args:\n        event: The close event.\n    \"\"\"\n    self.popup_closed.emit()\n    super().closeEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterDropdownPopup.keyPressEvent","title":"<code>keyPressEvent(event)</code>","text":"<p>Handle key press events.</p> <p>Parameters:</p> Name Type Description Default <code>event</code> <code>QKeyEvent</code> <p>The key event.</p> required Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def keyPressEvent(self, event: QtGui.QKeyEvent) -&gt; None:\n    \"\"\"Handle key press events.\n\n    Args:\n        event: The key event.\n    \"\"\"\n    if event.key() == Qt.Key.Key_Escape:\n        self.close()\n    else:\n        super().keyPressEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterDropdownPopup.populate","title":"<code>populate(items)</code>","text":"<p>Populate the list with filter items.</p> <p>Parameters:</p> Name Type Description Default <code>items</code> <code>List[FilterItem]</code> <p>List of FilterItem objects to display.</p> required Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def populate(self, items: List[FilterItem]) -&gt; None:\n    \"\"\"Populate the list with filter items.\n\n    Args:\n        items: List of FilterItem objects to display.\n    \"\"\"\n    self._list_widget.clear()\n    for item in items:\n        self._add_list_item(item)\n\n    # Adjust height based on content\n    self._adjust_size()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterDropdownPopup.show_below","title":"<code>show_below(widget)</code>","text":"<p>Show the popup positioned below the given widget.</p> <p>Parameters:</p> Name Type Description Default <code>widget</code> <code>QWidget</code> <p>Widget to position the popup below.</p> required Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def show_below(self, widget: QtWidgets.QWidget) -&gt; None:\n    \"\"\"Show the popup positioned below the given widget.\n\n    Args:\n        widget: Widget to position the popup below.\n    \"\"\"\n    # Get global position of the bottom-left of the widget\n    global_pos = widget.mapToGlobal(QtCore.QPoint(0, widget.height()))\n\n    # Ensure popup doesn't go off screen\n    screen = QtWidgets.QApplication.screenAt(global_pos)\n    if screen:\n        screen_geo = screen.availableGeometry()\n\n        # Adjust horizontal position if needed\n        if global_pos.x() + self.width() &gt; screen_geo.right():\n            global_pos.setX(screen_geo.right() - self.width())\n\n        # Show above if not enough space below\n        if global_pos.y() + self.height() &gt; screen_geo.bottom():\n            global_pos = widget.mapToGlobal(QtCore.QPoint(0, 0))\n            global_pos.setY(global_pos.y() - self.height())\n\n    self.move(global_pos)\n    self.show()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterDropdownPopup.update_item_state","title":"<code>update_item_state(key, selected)</code>","text":"<p>Update the check state of a specific item.</p> <p>Parameters:</p> Name Type Description Default <code>key</code> <code>str</code> <p>Key of the item to update.</p> required <code>selected</code> <code>bool</code> <p>New selection state.</p> required Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def update_item_state(self, key: str, selected: bool) -&gt; None:\n    \"\"\"Update the check state of a specific item.\n\n    Args:\n        key: Key of the item to update.\n        selected: New selection state.\n    \"\"\"\n    for i in range(self._list_widget.count()):\n        item = self._list_widget.item(i)\n        if item and item.data(QtCore.Qt.ItemDataRole.UserRole) == key:\n            item.setData(\n                QtCore.Qt.ItemDataRole.CheckStateRole,\n                QtCore.Qt.CheckState.Checked\n                if selected\n                else QtCore.Qt.CheckState.Unchecked,\n            )\n            break\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterItem","title":"<code>FilterItem</code>  <code>dataclass</code>","text":"<p>Data model for a single filter option.</p> <p>Attributes:</p> Name Type Description <code>key</code> <code>str</code> <p>Unique identifier for the filter.</p> <code>label</code> <code>str</code> <p>Display text shown in dropdown and tags.</p> <code>selected</code> <code>bool</code> <p>Current selection state.</p> <code>color</code> <code>str | None</code> <p>Optional background color for tag display.</p> <code>icon</code> <code>str | None</code> <p>Optional material icon name.</p> <code>enabled</code> <code>bool</code> <p>Whether the filter can be toggled.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>@dataclass\nclass FilterItem:\n    \"\"\"Data model for a single filter option.\n\n    Attributes:\n        key: Unique identifier for the filter.\n        label: Display text shown in dropdown and tags.\n        selected: Current selection state.\n        color: Optional background color for tag display.\n        icon: Optional material icon name.\n        enabled: Whether the filter can be toggled.\n    \"\"\"\n\n    key: str\n    label: str\n    selected: bool = False\n    color: str | None = field(default=None)\n    icon: str | None = field(default=None)\n    enabled: bool = True\n\n    def __hash__(self) -&gt; int:\n        \"\"\"Return hash based on key.\"\"\"\n        return hash(self.key)\n\n    def __eq__(self, other: object) -&gt; bool:\n        \"\"\"Compare equality based on key.\"\"\"\n        if isinstance(other, FilterItem):\n            return self.key == other.key\n        return False\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterItem.__eq__","title":"<code>__eq__(other)</code>","text":"<p>Compare equality based on key.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def __eq__(self, other: object) -&gt; bool:\n    \"\"\"Compare equality based on key.\"\"\"\n    if isinstance(other, FilterItem):\n        return self.key == other.key\n    return False\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/filter.html#client.ayon_ui_qt.components.filter.FilterItem.__hash__","title":"<code>__hash__()</code>","text":"<p>Return hash based on key.</p> Source code in <code>client/ayon_ui_qt/components/filter.py</code> <pre><code>def __hash__(self) -&gt; int:\n    \"\"\"Return hash based on key.\"\"\"\n    return hash(self.key)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/frame.html","title":"frame","text":""},{"location":"autoapi/client/ayon_ui_qt/components/gallery_dialog.html","title":"gallery_dialog","text":"<p>Gallery dialog for navigating through activity thumbnails/images.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/gallery_dialog.html#client.ayon_ui_qt.components.gallery_dialog.GalleryDialog","title":"<code>GalleryDialog</code>","text":"<p>               Bases: <code>QDialog</code></p> <p>Dialog for viewing and navigating through multiple images.</p> <p>This dialog provides a simple gallery view using standard Qt widgets, matching the official AYON style for image preview dialogs.</p> <p>Attributes:</p> Name Type Description <code>image_changed</code> <p>Signal emitted when the current image changes. Emits the current index.</p> Example <p>images = [ ...     (\"/path/to/image1.png\", \"image1.png\"), ...     (\"/path/to/image2.png\", \"image2.png\"), ... ] dialog = GalleryDialog(images, current_index=0) dialog.exec()</p> Source code in <code>client/ayon_ui_qt/components/gallery_dialog.py</code> <pre><code>class GalleryDialog(QDialog):\n    \"\"\"Dialog for viewing and navigating through multiple images.\n\n    This dialog provides a simple gallery view using standard Qt widgets,\n    matching the official AYON style for image preview dialogs.\n\n    Attributes:\n        image_changed: Signal emitted when the current image changes.\n            Emits the current index.\n\n    Example:\n        &gt;&gt;&gt; images = [\n        ...     (\"/path/to/image1.png\", \"image1.png\"),\n        ...     (\"/path/to/image2.png\", \"image2.png\"),\n        ... ]\n        &gt;&gt;&gt; dialog = GalleryDialog(images, current_index=0)\n        &gt;&gt;&gt; dialog.exec()\n    \"\"\"\n\n    image_changed = Signal(int)\n\n    def __init__(\n        self,\n        images: list[tuple[str, str]],\n        current_index: int = 0,\n        parent: QWidget | None = None,\n    ) -&gt; None:\n        \"\"\"Initialize the gallery dialog.\n\n        Args:\n            images: List of tuples (image_path, filename) for each image.\n            current_index: Index of the image to show initially.\n            parent: Parent widget.\n        \"\"\"\n        super().__init__(parent)\n        self.setWindowFlags(self.windowFlags() | Qt.WindowType.Tool)\n        self.setStyle(get_ayon_style())\n        self.images = images\n        self.current_index = current_index\n        # Track if dialog size has been set based on first image\n        self._dialog_size_set = False\n\n        self.setWindowTitle(\"Image Preview\")\n\n        # Set focus policy so dialog can receive keyboard events\n        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)\n\n        # Install event filter to intercept keyboard events from child widgets\n        self.installEventFilter(self)\n\n        self._setup_ui()\n        self._show_current_image()\n\n    def showEvent(self, event: QShowEvent) -&gt; None:\n        \"\"\"Handle dialog show event to set focus properly.\n\n        Args:\n            event: Show event.\n        \"\"\"\n        super().showEvent(event)\n        # Activate window and set focus to the dialog so keyboard events work immediately\n        self.activateWindow()\n        self.setFocus(Qt.FocusReason.OtherFocusReason)\n\n    def eventFilter(self, obj, event: QEvent) -&gt; bool:\n        \"\"\"Filter events to intercept keyboard navigation from any widget.\n\n        This ensures arrow key navigation works even if a child widget\n        somehow gains focus.\n\n        Args:\n            obj: Object that received the event.\n            event: Event to filter.\n\n        Returns:\n            True if the event was handled, False otherwise.\n        \"\"\"\n        if event.type() == QEvent.Type.KeyPress:\n            key = event.key()\n            if key == Qt.Key.Key_Left:\n                self._show_previous()\n                return True\n            elif key == Qt.Key.Key_Right:\n                self._show_next()\n                return True\n            elif key == Qt.Key.Key_Escape:\n                self.accept()\n                return True\n        return super().eventFilter(obj, event)\n\n    def _setup_ui(self) -&gt; None:\n        \"\"\"Set up the dialog UI components using standard Qt widgets.\"\"\"\n        dialog_lyt = AYVBoxLayout(self, margin=0, spacing=0)\n\n        self.top_lyt = AYContainer(\n            self,\n            layout=AYContainer.Layout.VBox,\n            variant=AYContainer.Variants.Low,\n            layout_margin=10,\n            layout_spacing=10,\n        )\n        # Prevent container from accepting focus\n        self.top_lyt.setFocusPolicy(Qt.FocusPolicy.NoFocus)\n        dialog_lyt.addWidget(self.top_lyt)\n\n        # Image display area\n        self.image_label = QLabel()\n        self.image_label.setAlignment(Qt.AlignmentFlag.AlignCenter)\n        self.image_label.setScaledContents(False)\n        # Prevent label from accepting focus\n        self.image_label.setFocusPolicy(Qt.FocusPolicy.NoFocus)\n        self.top_lyt.add_widget(self.image_label, stretch=1)\n\n        # Only show navigation controls if multiple images\n        if len(self.images) &gt; 1:\n            # Navigation controls\n            nav_widget = AYContainer(\n                layout=AYContainer.Layout.HBox,\n                variant=AYContainer.Variants.High,\n                layout_margin=0,\n                layout_spacing=10,\n            )\n            # Prevent container from accepting focus\n            nav_widget.setFocusPolicy(Qt.FocusPolicy.NoFocus)\n\n            # Previous button\n            self.prev_btn = AYButton(\n                \"\u25c0 Previous\", variant=AYButton.Variants.Nav\n            )\n            self.prev_btn.clicked.connect(self._show_previous)\n            # Prevent button from stealing focus\n            self.prev_btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)\n            self.prev_btn.installEventFilter(self)\n            nav_widget.add_widget(self.prev_btn)\n\n            # Info label (counter and filename)\n            self.info_label = AYLabel(variant=AYLabel.Variants.Default)\n            self.info_label.setAlignment(Qt.AlignmentFlag.AlignCenter)\n            # Prevent label from accepting focus\n            self.info_label.setFocusPolicy(Qt.FocusPolicy.NoFocus)\n            nav_widget.add_widget(self.info_label, stretch=1)\n\n            # Next button\n            self.next_btn = AYButton(\"Next \u25b6\", variant=AYButton.Variants.Nav)\n            self.next_btn.clicked.connect(self._show_next)\n            # Prevent button from stealing focus\n            self.next_btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)\n            self.next_btn.installEventFilter(self)\n            nav_widget.add_widget(self.next_btn)\n\n            self.top_lyt.add_widget(nav_widget)\n\n    def _show_current_image(self) -&gt; None:\n        \"\"\"Display the current image with proper scaling.\"\"\"\n        if not self.images or self.current_index &gt;= len(self.images):\n            return\n\n        image_path, filename = self.images[self.current_index]\n\n        # Load the full-size image\n        if not Path(image_path).exists():\n            self.image_label.setText(\"Image not found\")\n            return\n\n        original_pixmap = QPixmap(image_path)\n        if original_pixmap.isNull():\n            self.image_label.setText(\"Failed to load image\")\n            return\n\n        # Get screen dimensions for sizing\n        screen = self.screen() or QApplication.primaryScreen()\n        screen_size = screen.availableGeometry()\n        max_w = int(screen_size.width() * 0.8)\n        max_h = int(screen_size.height() * 0.8)\n\n        # Scale if too large for screen while maintaining aspect ratio\n        display_pixmap = original_pixmap\n        if original_pixmap.width() &gt; max_w or original_pixmap.height() &gt; max_h:\n            display_pixmap = original_pixmap.scaled(\n                max_w,\n                max_h,\n                Qt.AspectRatioMode.KeepAspectRatio,\n                Qt.TransformationMode.SmoothTransformation,\n            )\n\n        self.image_label.setPixmap(display_pixmap)\n\n        # Set dialog size once on first image, then keep it consistent\n        if not self._dialog_size_set:\n            _layout = self.top_lyt.layout()\n            if _layout:\n                self.resize(_layout.sizeHint())\n                self._dialog_size_set = True\n            else:\n                logger.warning(\"Failed to get layout to size the dialog\")\n\n        # Update navigation controls if multiple images\n        if len(self.images) &gt; 1:\n            # Update info label\n            display_name = Path(filename).stem if filename else \"Unknown\"\n            info_text = f\"{self.current_index + 1} / {len(self.images)} - {display_name}\"\n            self.info_label.setText(info_text)\n\n            # Update button states\n            self.prev_btn.setEnabled(self.current_index &gt; 0)\n            self.next_btn.setEnabled(self.current_index &lt; len(self.images) - 1)\n\n        # Emit signal\n        self.image_changed.emit(self.current_index)\n\n    def _show_previous(self) -&gt; None:\n        \"\"\"Show the previous image.\"\"\"\n        if self.current_index &gt; 0:\n            self.current_index -= 1\n            self._show_current_image()\n\n    def _show_next(self) -&gt; None:\n        \"\"\"Show the next image.\"\"\"\n        if self.current_index &lt; len(self.images) - 1:\n            self.current_index += 1\n            self._show_current_image()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/gallery_dialog.html#client.ayon_ui_qt.components.gallery_dialog.GalleryDialog.__init__","title":"<code>__init__(images, current_index=0, parent=None)</code>","text":"<p>Initialize the gallery dialog.</p> <p>Parameters:</p> Name Type Description Default <code>images</code> <code>list[tuple[str, str]]</code> <p>List of tuples (image_path, filename) for each image.</p> required <code>current_index</code> <code>int</code> <p>Index of the image to show initially.</p> <code>0</code> <code>parent</code> <code>QWidget | None</code> <p>Parent widget.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/gallery_dialog.py</code> <pre><code>def __init__(\n    self,\n    images: list[tuple[str, str]],\n    current_index: int = 0,\n    parent: QWidget | None = None,\n) -&gt; None:\n    \"\"\"Initialize the gallery dialog.\n\n    Args:\n        images: List of tuples (image_path, filename) for each image.\n        current_index: Index of the image to show initially.\n        parent: Parent widget.\n    \"\"\"\n    super().__init__(parent)\n    self.setWindowFlags(self.windowFlags() | Qt.WindowType.Tool)\n    self.setStyle(get_ayon_style())\n    self.images = images\n    self.current_index = current_index\n    # Track if dialog size has been set based on first image\n    self._dialog_size_set = False\n\n    self.setWindowTitle(\"Image Preview\")\n\n    # Set focus policy so dialog can receive keyboard events\n    self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)\n\n    # Install event filter to intercept keyboard events from child widgets\n    self.installEventFilter(self)\n\n    self._setup_ui()\n    self._show_current_image()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/gallery_dialog.html#client.ayon_ui_qt.components.gallery_dialog.GalleryDialog.eventFilter","title":"<code>eventFilter(obj, event)</code>","text":"<p>Filter events to intercept keyboard navigation from any widget.</p> <p>This ensures arrow key navigation works even if a child widget somehow gains focus.</p> <p>Parameters:</p> Name Type Description Default <code>obj</code> <p>Object that received the event.</p> required <code>event</code> <code>QEvent</code> <p>Event to filter.</p> required <p>Returns:</p> Type Description <code>bool</code> <p>True if the event was handled, False otherwise.</p> Source code in <code>client/ayon_ui_qt/components/gallery_dialog.py</code> <pre><code>def eventFilter(self, obj, event: QEvent) -&gt; bool:\n    \"\"\"Filter events to intercept keyboard navigation from any widget.\n\n    This ensures arrow key navigation works even if a child widget\n    somehow gains focus.\n\n    Args:\n        obj: Object that received the event.\n        event: Event to filter.\n\n    Returns:\n        True if the event was handled, False otherwise.\n    \"\"\"\n    if event.type() == QEvent.Type.KeyPress:\n        key = event.key()\n        if key == Qt.Key.Key_Left:\n            self._show_previous()\n            return True\n        elif key == Qt.Key.Key_Right:\n            self._show_next()\n            return True\n        elif key == Qt.Key.Key_Escape:\n            self.accept()\n            return True\n    return super().eventFilter(obj, event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/gallery_dialog.html#client.ayon_ui_qt.components.gallery_dialog.GalleryDialog.showEvent","title":"<code>showEvent(event)</code>","text":"<p>Handle dialog show event to set focus properly.</p> <p>Parameters:</p> Name Type Description Default <code>event</code> <code>QShowEvent</code> <p>Show event.</p> required Source code in <code>client/ayon_ui_qt/components/gallery_dialog.py</code> <pre><code>def showEvent(self, event: QShowEvent) -&gt; None:\n    \"\"\"Handle dialog show event to set focus properly.\n\n    Args:\n        event: Show event.\n    \"\"\"\n    super().showEvent(event)\n    # Activate window and set focus to the dialog so keyboard events work immediately\n    self.activateWindow()\n    self.setFocus(Qt.FocusReason.OtherFocusReason)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/label.html","title":"label","text":""},{"location":"autoapi/client/ayon_ui_qt/components/label.html#client.ayon_ui_qt.components.label.AYLabel","title":"<code>AYLabel</code>","text":"<p>               Bases: <code>QLabel</code></p> Source code in <code>client/ayon_ui_qt/components/label.py</code> <pre><code>class AYLabel(QtWidgets.QLabel):\n    Variants = QLabelVariants\n\n    def __init__(\n        self,\n        *args,\n        dim: bool = False,\n        icon: str = \"\",\n        icon_color: str = \"\",\n        icon_size: int = 20,\n        icon_text_spacing=6,\n        icon_fill=False,\n        text_color: str = \"\",\n        rel_text_size: int = 0,\n        bold: bool = False,\n        tool_tip=\"\",\n        variant: Variants = Variants.Default,\n        contrast_color: QColor | None = None,\n        elide_mode: Qt.TextElideMode = Qt.TextElideMode.ElideNone,\n        **kwargs,\n    ):\n        self._dim = dim\n        self._icon = icon\n        self._icon_color = icon_color\n        self._icon_size = icon_size\n        self._icon_fill = icon_fill\n        self._icon_text_spacing = icon_text_spacing\n        self._rel_text_size = rel_text_size\n        self._text_color = text_color\n        self._bold = bold\n        self._variant_str: str = variant.value\n        self._text_setup_done = False\n        self._style_palette = None\n        self._elide_mode = elide_mode\n        self._elided_text: str = \"\"\n        # reference bg color to compute contrast-adapted text color\n        self._contrast_color = (\n            contrast_color\n            if isinstance(contrast_color, QColor) and contrast_color.isValid()\n            else None\n        )\n        self._contrast_adapted = None\n\n        super().__init__(*args, **kwargs)\n        self._style = get_ayon_style()\n        self.setStyle(self._style)\n\n        # used to be in polish\n        self.setWindowFlag(Qt.WindowType.FramelessWindowHint, True)\n        self.setWindowFlag(Qt.WindowType.NoDropShadowWindowHint, True)\n\n        self._text = self.text()\n        self.setToolTip(tool_tip)\n\n        self.set_icon()\n\n    @property\n    def contrast_color(self) -&gt; QColor | None:\n        return self._contrast_color\n\n    def set_icon(self, icon: str | None = None, color: str = \"\") -&gt; None:\n        if icon is not None:\n            self._icon = icon\n        if color:\n            self._icon_color = color\n        if self._icon:\n            icon_color = (\n                self._icon_color\n                or self.palette().color(self.foregroundRole()).name()\n            )\n            icn: QIcon = get_icon(\n                self._icon,\n                color=icon_color,\n                fill=self._icon_fill,\n            )\n            self.setPixmap(icn.pixmap(QSize(self._icon_size, self._icon_size)))\n\n    def _ensure_font_setup(self) -&gt; None:\n        \"\"\"Initialize font configuration on first paint.\"\"\"\n        if self._text_setup_done:\n            return\n\n        self._text_setup_done = True\n        self._font = self.font()\n\n        if self._rel_text_size != 0:\n            self._font.setPointSize(\n                self._font.pointSize() + self._rel_text_size\n            )\n\n        weight = QFont.Weight.Bold if self._bold else QFont.Weight.Normal\n        self._font.setWeight(weight)\n        self.setFont(self._font)\n        self._font_metrics = QFontMetrics(self._font)\n        self._update_elided_text()\n\n    def _update_elided_text(self) -&gt; None:\n        \"\"\"Recompute the elided version of the stored text.\"\"\"\n        if (\n            self._elide_mode == Qt.TextElideMode.ElideNone\n            or not self._text_setup_done\n        ):\n            self._elided_text = self._text\n            return\n        available_w = self.contentsRect().width()\n        if self._icon:\n            spacing = self._icon_text_spacing\n            available_w -= self._icon_size + spacing\n        self._elided_text = self._font_metrics.elidedText(\n            self._text, self._elide_mode, max(0, available_w)\n        )\n\n    def _resolve_color(self) -&gt; QColor:\n        \"\"\"Get the effective foreground color (icon_color or palette).\"\"\"\n        if self._icon_color:\n            return QColor(self._icon_color)\n        return self.palette().color(self.foregroundRole())\n\n    def _to_qcolor(self, color: QColor | str | None) -&gt; QColor | None:\n        \"\"\"Convert a color value to QColor, handling None and strings.\"\"\"\n        if color is None:\n            return None\n        if isinstance(color, QColor):\n            return color\n        return QColor(color)\n\n    def _compute_contrast_text_color(\n        self,\n        bg_color: QColor | str | None,\n        fg_color: QColor,\n    ) -&gt; QColor:\n        \"\"\"Compute text color with sufficient contrast against background.\"\"\"\n        if not bg_color:\n            return fg_color\n        qbg = self._to_qcolor(bg_color)\n        return compute_color_for_contrast(\n            qbg.toTuple(),\n            fg_color.toTuple(),\n            min_contrast_ratio=7.0,\n        )\n\n    def _apply_palette(self) -&gt; None:\n        \"\"\"Configure palette based on dim/contrast settings.\"\"\"\n        # _style_palette is guaranteed to be set in paintEvent before this call\n        assert self._style_palette is not None\n\n        if self._dim:\n            p = QPalette(self._style_palette)\n            p.setColor(\n                QPalette.ColorGroup.Active,\n                self.foregroundRole(),\n                self._style_palette.color(\n                    QPalette.ColorGroup.Active,\n                    QPalette.ColorRole.PlaceholderText,\n                ),\n            )\n            self.setPalette(p)\n            return\n\n        if self._contrast_color:\n            txt_color = self._compute_contrast_text_color(\n                self._contrast_color,\n                self._style_palette.color(self.foregroundRole()),\n            )\n            p = QPalette(self._style_palette)\n            p.setColor(self.foregroundRole(), txt_color)\n            self.setPalette(p)\n        else:\n            self.setPalette(self._style_palette)\n\n    def _paint_filled(self, style_data: dict) -&gt; None:\n        \"\"\"Render a filled-background label driven by style data.\"\"\"\n        style = self._style\n\n        # Auto-size from text metrics\n        if style_data.get(\"auto-size\"):\n            padding = style_data.get(\"auto-size-padding\", [0, 0])\n            t_rect = self._font_metrics.boundingRect(self.text())\n            padx = int(self._font_metrics.averageCharWidth() * padding[0])\n            pady = int(self._font_metrics.height() * padding[1])\n            self.setFixedSize(\n                t_rect.width() + padx,\n                t_rect.height() + pady,\n            )\n\n        p = QPainter(self)\n        self.initPainter(p)\n        p.setFont(self._font)\n        p.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n        # Fill color from foreground\n        fill_color = self._resolve_color()\n        p.setBrush(QBrush(fill_color))\n        p.setPen(Qt.PenStyle.NoPen)\n\n        # Border radius: fraction of height or fixed\n        radius_frac = style_data.get(\"border-radius-fraction\")\n        if radius_frac is not None:\n            radius = self.rect().height() * radius_frac\n        else:\n            radius = style_data.get(\"border-radius\", 0)\n\n        p.drawRoundedRect(self.rect(), radius, radius)\n\n        # Text color with contrast computation\n        if style_data.get(\"contrast-text\"):\n            contrast_ref = self._contrast_color or self._icon_color\n            txt_color = self._compute_contrast_text_color(\n                contrast_ref,\n                self.palette().color(self.foregroundRole()),\n            )\n            p.setPen(QPen(QBrush(txt_color), 1.0))\n\n        style.drawItemText(\n            p,\n            self.rect(),\n            Qt.AlignmentFlag.AlignCenter,\n            self.palette(),\n            self.isEnabled(),\n            self.text(),\n            textRole=QPalette.ColorRole.NoRole,\n        )\n        p.end()\n\n    def _paint_icon_and_text(self, style_data: dict) -&gt; None:\n        \"\"\"Render label with both icon and text.\n\n        The icon and text are treated as a single group and positioned\n        within the widget rect according to the current alignment.\n\n        The spacing between icon and text is resolved from the\n        ``icon-text-spacing`` property in *style_data*, falling back to\n        the value supplied at construction time.\n\n        Args:\n            style_data: Variant style properties resolved from the style\n                JSON for the current ``QLabel`` variant.\n        \"\"\"\n        style = self._style\n        p = QPainter(self)\n        p.setFont(self._font)\n        p.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n        text_rect = self._font_metrics.boundingRect(self._elided_text)\n        text_rect.adjust(0, 0, 1, 0)  # +1 pixel for antialiasing\n\n        icon_w = self._icon_size\n        icon_h = self._icon_size\n        spacing = int(\n            style_data.get(\"icon-text-spacing\", self._icon_text_spacing)\n        )\n        group_w = icon_w + spacing + text_rect.width()\n        group_h = max(icon_h, text_rect.height())\n\n        # Position the group using the current alignment\n        widget_rect = self.contentsRect().normalized()\n        alignment = self.alignment()\n\n        if alignment &amp; Qt.AlignmentFlag.AlignLeft:\n            group_x = widget_rect.left()\n        elif alignment &amp; Qt.AlignmentFlag.AlignRight:\n            group_x = widget_rect.right() - group_w\n        else:  # Center (default)\n            group_x = widget_rect.left() + (widget_rect.width() - group_w) // 2\n\n        if alignment &amp; Qt.AlignmentFlag.AlignTop:\n            group_y = widget_rect.top()\n        elif alignment &amp; Qt.AlignmentFlag.AlignBottom:\n            group_y = widget_rect.bottom() - group_h\n        else:  # VCenter (default)\n            group_y = widget_rect.top() + (widget_rect.height() - group_h) // 2\n\n        # Draw icon at the left of the group\n        icon_y = group_y + (group_h - icon_h) // 2\n        icn_rct = QRect(group_x, icon_y, icon_w, icon_h)\n        style.drawItemPixmap(\n            p,\n            icn_rct,\n            Qt.AlignmentFlag.AlignCenter,\n            self.pixmap(),\n        )\n\n        # Draw text at the right of the icon\n        pal = self.palette()\n        if not self._dim:\n            pal.setColor(QPalette.ColorRole.Text, self._resolve_color())\n\n        txt_x = group_x + icon_w + spacing\n        txt_y = group_y + (group_h - text_rect.height()) // 2\n        txt_rct = QRect(txt_x, txt_y, text_rect.width(), text_rect.height())\n        style.drawItemText(\n            p,\n            txt_rct,\n            Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n            pal,\n            self.isEnabled(),\n            self._elided_text,\n            textRole=self.foregroundRole(),\n        )\n\n    def _paint_text_only(self) -&gt; None:\n        \"\"\"Render text-only label.\"\"\"\n        p = QPainter(self)\n        p.setFont(self._font)\n        p.setRenderHint(QPainter.RenderHint.Antialiasing)\n        if self._text_color:\n            # p.setPen(QPen(QColor(self._text_color)))\n            pal = self.palette()\n            pal.setColor(self.foregroundRole(), QColor(self._text_color))\n            self.setPalette(pal)\n\n        self._style.drawItemText(\n            p,\n            self.contentsRect().normalized(),\n            self.alignment(),\n            self.palette(),\n            self.isEnabled(),\n            self._elided_text,\n            textRole=self.foregroundRole(),\n        )\n\n    def _paint_background(self, style_data: dict) -&gt; None:\n        \"\"\"Draw background if specified by style.\"\"\"\n        bg_color = style_data.get(\"background-color\")\n        if bg_color and bg_color != \"transparent\":\n            p = QPainter(self)\n            p.setRenderHint(QPainter.RenderHint.Antialiasing)\n            border_radius = style_data.get(\"border-radius\", 0)\n            border_width = style_data.get(\"border-width\", 0)\n            border_color = style_data.get(\"border-color\", \"#00000000\")\n            p.setBrush(QBrush(QColor(bg_color)))\n            p.setPen(\n                QPen(QColor(border_color), border_width)\n                if border_width &gt; 0\n                else Qt.PenStyle.NoPen\n            )\n            p.drawRoundedRect(self.rect(), border_radius, border_radius)\n\n    def paintEvent(self, arg__1: QPaintEvent) -&gt; None:\n        if not self._style_palette:\n            self._style_palette = self.palette()\n\n        self._ensure_font_setup()\n        self._apply_palette()\n\n        # Resolve style from JSON (guard for non-AYONStyle environments)\n        qt_style = self._style\n        style_data = qt_style.model.get_style(\"QLabel\", self._variant_str)\n\n        # Filled-background rendering (driven by JSON properties)\n        if style_data.get(\"fill-from-foreground\"):\n            self._paint_filled(style_data)\n        else:\n            self._paint_background(style_data)\n            if self._text and self._icon:\n                self._paint_icon_and_text(style_data)\n            elif self._icon and not self._text:\n                super().paintEvent(arg__1)\n            else:\n                self._paint_text_only()\n\n    def sizeHint(self) -&gt; QSize:\n        \"\"\"Compute a size hint driven by QLabel style data from the style JSON.\n\n        For variants with ``auto-size`` (e.g. badge / pill), the size is\n        derived from font-metrics and the ``auto-size-padding`` factor.\n        For variants with an explicit ``padding`` list (e.g. entity-label),\n        the size is padded accordingly.\n        When an icon is present the icon dimensions are added.\n        In all other cases the base ``QLabel.sizeHint()`` is returned.\n\n        Returns:\n            The recommended widget size.\n        \"\"\"\n        self._ensure_font_setup()\n\n        style_data: dict = self._style.model.get_style(\n            \"QLabel\", self._variant_str\n        )\n\n        fm = self._font_metrics\n\n        # --- text size --------------------------------------------------\n        text = self._text or \"\"\n        if text:\n            t_rect = fm.boundingRect(text)\n            text_w = t_rect.width()\n            text_h = t_rect.height()\n        else:\n            text_w = 0\n            text_h = fm.height()\n\n        # --- icon size --------------------------------------------------\n        icon_w = icon_h = 0\n        if self._icon:\n            icon_w = self._icon_size\n            icon_h = self._icon_size\n\n        # --- variant-specific sizing ------------------------------------\n        if style_data.get(\"auto-size\"):\n            # badge / pill: padding is expressed as a fraction of the\n            # character metrics (x-factor of avgCharWidth, y-factor of height)\n            padding = style_data.get(\"auto-size-padding\", [0.0, 0.0])\n            pad_x = int(fm.averageCharWidth() * padding[0])\n            pad_y = int(fm.height() * padding[1])\n\n            content_w = max(text_w, icon_w)\n            content_h = max(text_h, icon_h)\n\n            return QSize(content_w + pad_x, content_h + pad_y)\n\n        explicit_padding = style_data.get(\"padding\", [0, 0])\n        # [vertical, horizontal] convention (same as CSS padding shorthand)\n        pad_v = int(explicit_padding[0])\n        pad_h = int(explicit_padding[1])\n\n        if icon_w and text_w:\n            spacing = int(\n                style_data.get(\"icon-text-spacing\", self._icon_text_spacing)\n            )\n            content_w = icon_w + spacing + text_w\n            content_h = max(text_h, icon_h)\n        elif icon_w:\n            content_w = icon_w\n            content_h = icon_h\n        else:\n            content_w = text_w\n            content_h = text_h\n\n        return QSize(\n            content_w + 2 * pad_h,\n            content_h + 2 * pad_v,\n        )\n\n    def resizeEvent(self, event: QResizeEvent) -&gt; None:\n        \"\"\"Recompute elided text when the widget is resized.\"\"\"\n        super().resizeEvent(event)\n        self._update_elided_text()\n\n    def setText(self, arg__1: str) -&gt; None:\n        super().setText(arg__1)\n        self._text = self.text()\n        self._update_elided_text()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/label.html#client.ayon_ui_qt.components.label.AYLabel.resizeEvent","title":"<code>resizeEvent(event)</code>","text":"<p>Recompute elided text when the widget is resized.</p> Source code in <code>client/ayon_ui_qt/components/label.py</code> <pre><code>def resizeEvent(self, event: QResizeEvent) -&gt; None:\n    \"\"\"Recompute elided text when the widget is resized.\"\"\"\n    super().resizeEvent(event)\n    self._update_elided_text()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/label.html#client.ayon_ui_qt.components.label.AYLabel.sizeHint","title":"<code>sizeHint()</code>","text":"<p>Compute a size hint driven by QLabel style data from the style JSON.</p> <p>For variants with <code>auto-size</code> (e.g. badge / pill), the size is derived from font-metrics and the <code>auto-size-padding</code> factor. For variants with an explicit <code>padding</code> list (e.g. entity-label), the size is padded accordingly. When an icon is present the icon dimensions are added. In all other cases the base <code>QLabel.sizeHint()</code> is returned.</p> <p>Returns:</p> Type Description <code>QSize</code> <p>The recommended widget size.</p> Source code in <code>client/ayon_ui_qt/components/label.py</code> <pre><code>def sizeHint(self) -&gt; QSize:\n    \"\"\"Compute a size hint driven by QLabel style data from the style JSON.\n\n    For variants with ``auto-size`` (e.g. badge / pill), the size is\n    derived from font-metrics and the ``auto-size-padding`` factor.\n    For variants with an explicit ``padding`` list (e.g. entity-label),\n    the size is padded accordingly.\n    When an icon is present the icon dimensions are added.\n    In all other cases the base ``QLabel.sizeHint()`` is returned.\n\n    Returns:\n        The recommended widget size.\n    \"\"\"\n    self._ensure_font_setup()\n\n    style_data: dict = self._style.model.get_style(\n        \"QLabel\", self._variant_str\n    )\n\n    fm = self._font_metrics\n\n    # --- text size --------------------------------------------------\n    text = self._text or \"\"\n    if text:\n        t_rect = fm.boundingRect(text)\n        text_w = t_rect.width()\n        text_h = t_rect.height()\n    else:\n        text_w = 0\n        text_h = fm.height()\n\n    # --- icon size --------------------------------------------------\n    icon_w = icon_h = 0\n    if self._icon:\n        icon_w = self._icon_size\n        icon_h = self._icon_size\n\n    # --- variant-specific sizing ------------------------------------\n    if style_data.get(\"auto-size\"):\n        # badge / pill: padding is expressed as a fraction of the\n        # character metrics (x-factor of avgCharWidth, y-factor of height)\n        padding = style_data.get(\"auto-size-padding\", [0.0, 0.0])\n        pad_x = int(fm.averageCharWidth() * padding[0])\n        pad_y = int(fm.height() * padding[1])\n\n        content_w = max(text_w, icon_w)\n        content_h = max(text_h, icon_h)\n\n        return QSize(content_w + pad_x, content_h + pad_y)\n\n    explicit_padding = style_data.get(\"padding\", [0, 0])\n    # [vertical, horizontal] convention (same as CSS padding shorthand)\n    pad_v = int(explicit_padding[0])\n    pad_h = int(explicit_padding[1])\n\n    if icon_w and text_w:\n        spacing = int(\n            style_data.get(\"icon-text-spacing\", self._icon_text_spacing)\n        )\n        content_w = icon_w + spacing + text_w\n        content_h = max(text_h, icon_h)\n    elif icon_w:\n        content_w = icon_w\n        content_h = icon_h\n    else:\n        content_w = text_w\n        content_h = text_h\n\n    return QSize(\n        content_w + 2 * pad_h,\n        content_h + 2 * pad_v,\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html","title":"layouts","text":""},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout","title":"<code>AYFlowLayout</code>","text":"<p>               Bases: <code>QLayout</code></p> <p>Flow layout that wraps widgets horizontally, then vertically.</p> <p>This layout arranges widgets in a left-to-right flow, wrapping to the next line when the width is exceeded, similar to how text flows in a paragraph.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>class AYFlowLayout(QtWidgets.QLayout):\n    \"\"\"Flow layout that wraps widgets horizontally, then vertically.\n\n    This layout arranges widgets in a left-to-right flow, wrapping to the\n    next line when the width is exceeded, similar to how text flows in a\n    paragraph.\n    \"\"\"\n\n    def __init__(self, parent=None, margin=4, spacing=4):\n        super().__init__(parent)\n        self._item_list = []\n        self._h_spacing = spacing\n        self._v_spacing = spacing\n        self.setContentsMargins(margin, margin, margin, margin)\n\n    def addItem(self, item):\n        \"\"\"Add an item to the layout.\"\"\"\n        self._item_list.append(item)\n\n    def horizontalSpacing(self) -&gt; int:\n        \"\"\"Get the horizontal spacing between items.\"\"\"\n        if self._h_spacing &gt;= 0:\n            return self._h_spacing\n        return self._smart_spacing(QtWidgets.QStyle.PM_LayoutHorizontalSpacing)\n\n    def verticalSpacing(self) -&gt; int:\n        \"\"\"Get the vertical spacing between items.\"\"\"\n        if self._v_spacing &gt;= 0:\n            return self._v_spacing\n        return self._smart_spacing(QtWidgets.QStyle.PM_LayoutVerticalSpacing)\n\n    def count(self) -&gt; int:\n        \"\"\"Return the number of items in the layout.\"\"\"\n        return len(self._item_list)\n\n    def itemAt(self, index: int) -&gt; Optional[QtWidgets.QLayoutItem]:\n        \"\"\"Get the item at the specified index.\"\"\"\n        if 0 &lt;= index &lt; len(self._item_list):\n            return self._item_list[index]\n        return None\n\n    def takeAt(self, index: int) -&gt; Optional[QtWidgets.QLayoutItem]:  # type: ignore\n        \"\"\"Remove and return the item at the specified index.\"\"\"\n        if 0 &lt;= index &lt; len(self._item_list):\n            return self._item_list.pop(index)\n        return None\n\n    def expandingDirections(self) -&gt; Qt.Orientations:\n        \"\"\"Return the expanding directions for this layout.\"\"\"\n        return Qt.Orientations(0)\n\n    def hasHeightForWidth(self) -&gt; bool:\n        \"\"\"Return True to indicate height depends on width.\"\"\"\n        return True\n\n    def heightForWidth(self, width: int) -&gt; int:\n        \"\"\"Calculate the height required for the given width.\"\"\"\n        return self._do_layout(QRect(0, 0, width, 0), True)\n\n    def setGeometry(self, rect: QRect) -&gt; None:\n        \"\"\"Set the geometry of the layout.\"\"\"\n        super().setGeometry(rect)\n        self._do_layout(rect, False)\n\n    def sizeHint(self) -&gt; QSize:\n        \"\"\"Return the preferred size of the layout.\"\"\"\n        return self.minimumSize()\n\n    def minimumSize(self) -&gt; QSize:\n        \"\"\"Calculate and return the minimum size for the layout.\"\"\"\n        size = QSize()\n        for item in self._item_list:\n            size = size.expandedTo(item.minimumSize())\n\n        margins = self.contentsMargins()\n        size += QSize(\n            margins.left() + margins.right(),\n            margins.top() + margins.bottom(),\n        )\n        return size\n\n    def _do_layout(self, rect: QRect, test_only: bool) -&gt; int:\n        \"\"\"Perform the layout calculation and positioning.\n\n        Args:\n            rect: The rectangle to lay out items within.\n            test_only: If True, only calculate height without setting\n                geometry.\n\n        Returns:\n            The height required for the layout.\n        \"\"\"\n        left, top, right, bottom = (\n            self.contentsMargins().left(),\n            self.contentsMargins().top(),\n            self.contentsMargins().right(),\n            self.contentsMargins().bottom(),\n        )\n        effective_rect = rect.adjusted(left, top, -right, -bottom)\n        x = effective_rect.x()\n        y = effective_rect.y()\n        line_height = 0\n\n        for item in self._item_list:\n            widget = item.widget()\n            space_x = self.horizontalSpacing()\n            if space_x == -1:\n                space_x = widget.style().layoutSpacing(\n                    QtWidgets.QSizePolicy.PushButton,\n                    QtWidgets.QSizePolicy.PushButton,\n                    Qt.Horizontal,\n                )\n\n            space_y = self.verticalSpacing()\n            if space_y == -1:\n                space_y = widget.style().layoutSpacing(\n                    QtWidgets.QSizePolicy.PushButton,\n                    QtWidgets.QSizePolicy.PushButton,\n                    Qt.Vertical,\n                )\n\n            next_x = x + item.sizeHint().width() + space_x\n            if next_x - space_x &gt; effective_rect.right() and line_height &gt; 0:\n                x = effective_rect.x()\n                y = y + line_height + space_y\n                next_x = x + item.sizeHint().width() + space_x\n                line_height = 0\n\n            if not test_only:\n                item.setGeometry(QRect(QPoint(x, y), item.sizeHint()))\n\n            x = next_x\n            line_height = max(line_height, item.sizeHint().height())\n\n        return y + line_height - rect.y() + bottom\n\n    def _smart_spacing(self, pm: int) -&gt; int:\n        \"\"\"Get smart spacing from the parent widget's style.\n\n        Args:\n            pm: The pixel metric to query.\n\n        Returns:\n            The spacing value, or -1 if unavailable.\n        \"\"\"\n        parent = self.parent()\n        if parent is None:\n            return -1\n        if parent.isWidgetType():\n            return parent.style().pixelMetric(pm, None, parent)\n        return parent.spacing()\n\n    def clear(self):\n        clear_layout(self)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.addItem","title":"<code>addItem(item)</code>","text":"<p>Add an item to the layout.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def addItem(self, item):\n    \"\"\"Add an item to the layout.\"\"\"\n    self._item_list.append(item)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.count","title":"<code>count()</code>","text":"<p>Return the number of items in the layout.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def count(self) -&gt; int:\n    \"\"\"Return the number of items in the layout.\"\"\"\n    return len(self._item_list)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.expandingDirections","title":"<code>expandingDirections()</code>","text":"<p>Return the expanding directions for this layout.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def expandingDirections(self) -&gt; Qt.Orientations:\n    \"\"\"Return the expanding directions for this layout.\"\"\"\n    return Qt.Orientations(0)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.hasHeightForWidth","title":"<code>hasHeightForWidth()</code>","text":"<p>Return True to indicate height depends on width.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def hasHeightForWidth(self) -&gt; bool:\n    \"\"\"Return True to indicate height depends on width.\"\"\"\n    return True\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.heightForWidth","title":"<code>heightForWidth(width)</code>","text":"<p>Calculate the height required for the given width.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def heightForWidth(self, width: int) -&gt; int:\n    \"\"\"Calculate the height required for the given width.\"\"\"\n    return self._do_layout(QRect(0, 0, width, 0), True)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.horizontalSpacing","title":"<code>horizontalSpacing()</code>","text":"<p>Get the horizontal spacing between items.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def horizontalSpacing(self) -&gt; int:\n    \"\"\"Get the horizontal spacing between items.\"\"\"\n    if self._h_spacing &gt;= 0:\n        return self._h_spacing\n    return self._smart_spacing(QtWidgets.QStyle.PM_LayoutHorizontalSpacing)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.itemAt","title":"<code>itemAt(index)</code>","text":"<p>Get the item at the specified index.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def itemAt(self, index: int) -&gt; Optional[QtWidgets.QLayoutItem]:\n    \"\"\"Get the item at the specified index.\"\"\"\n    if 0 &lt;= index &lt; len(self._item_list):\n        return self._item_list[index]\n    return None\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.minimumSize","title":"<code>minimumSize()</code>","text":"<p>Calculate and return the minimum size for the layout.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def minimumSize(self) -&gt; QSize:\n    \"\"\"Calculate and return the minimum size for the layout.\"\"\"\n    size = QSize()\n    for item in self._item_list:\n        size = size.expandedTo(item.minimumSize())\n\n    margins = self.contentsMargins()\n    size += QSize(\n        margins.left() + margins.right(),\n        margins.top() + margins.bottom(),\n    )\n    return size\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.setGeometry","title":"<code>setGeometry(rect)</code>","text":"<p>Set the geometry of the layout.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def setGeometry(self, rect: QRect) -&gt; None:\n    \"\"\"Set the geometry of the layout.\"\"\"\n    super().setGeometry(rect)\n    self._do_layout(rect, False)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.sizeHint","title":"<code>sizeHint()</code>","text":"<p>Return the preferred size of the layout.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def sizeHint(self) -&gt; QSize:\n    \"\"\"Return the preferred size of the layout.\"\"\"\n    return self.minimumSize()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.takeAt","title":"<code>takeAt(index)</code>","text":"<p>Remove and return the item at the specified index.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def takeAt(self, index: int) -&gt; Optional[QtWidgets.QLayoutItem]:  # type: ignore\n    \"\"\"Remove and return the item at the specified index.\"\"\"\n    if 0 &lt;= index &lt; len(self._item_list):\n        return self._item_list.pop(index)\n    return None\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/layouts.html#client.ayon_ui_qt.components.layouts.AYFlowLayout.verticalSpacing","title":"<code>verticalSpacing()</code>","text":"<p>Get the vertical spacing between items.</p> Source code in <code>client/ayon_ui_qt/components/layouts.py</code> <pre><code>def verticalSpacing(self) -&gt; int:\n    \"\"\"Get the vertical spacing between items.\"\"\"\n    if self._v_spacing &gt;= 0:\n        return self._v_spacing\n    return self._smart_spacing(QtWidgets.QStyle.PM_LayoutVerticalSpacing)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/line_edit.html","title":"line_edit","text":"<p>AYLineEdit component module.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/line_edit.html#client.ayon_ui_qt.components.line_edit.AYLineEdit","title":"<code>AYLineEdit</code>","text":"<p>               Bases: <code>QLineEdit</code></p> <p>Custom styled line edit component.</p> <p>Inherits from QLineEdit and uses the AYON style system for rendering. Paints its own background, border, and focus ring using ayon_style.json data, then calls super().paintEvent() to draw text, cursor, and selection on top.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QWidget | None</code> <p>Parent widget.</p> <code>None</code> <code>placeholder</code> <code>str</code> <p>Placeholder text to display when empty.</p> <code>''</code> <code>variant</code> <code>QLineEditVariants</code> <p>Visual style variant.</p> <code>Default</code> <code>name_id</code> <code>str</code> <p>Object name for identification.</p> <code>''</code> Source code in <code>client/ayon_ui_qt/components/line_edit.py</code> <pre><code>class AYLineEdit(QLineEdit):\n    \"\"\"Custom styled line edit component.\n\n    Inherits from QLineEdit and uses the AYON style system for rendering.\n    Paints its own background, border, and focus ring using ayon_style.json\n    data, then calls super().paintEvent() to draw text, cursor, and\n    selection on top.\n\n    Args:\n        parent: Parent widget.\n        placeholder: Placeholder text to display when empty.\n        variant: Visual style variant.\n        name_id: Object name for identification.\n    \"\"\"\n\n    Variants = QLineEditVariants\n\n    def __init__(\n        self,\n        parent: QWidget | None = None,\n        placeholder: str = \"\",\n        variant: QLineEditVariants = QLineEditVariants.Default,\n        name_id: str = \"\",\n    ) -&gt; None:\n        super().__init__(parent)\n\n        self._variant_str = variant.value\n        self._pal: QPalette | None = None\n        self._variant_styles = {}\n\n        if placeholder:\n            self.setPlaceholderText(placeholder)\n\n        if name_id:\n            self.setObjectName(name_id)\n\n        # Suppress the native Qt frame so initStyleOption reports lineWidth=0\n        self.setFrame(False)\n\n        # Neutralise any ancestor stylesheet that would intercept\n        # PE_PanelLineEdit via QStyleSheetStyle, making it visually transparent.\n        self.setStyleSheet(\n            \"AYLineEdit { background: transparent; border: none; \"\n            \"padding: 0px; selection-background-color: none; \"\n            \"selection-color: none; }\"\n        )\n\n        # Suppress macOS native focus ring (we draw our own)\n        self.setAttribute(Qt.WidgetAttribute.WA_MacShowFocusRect, False)\n\n        # Enable hover events so underMouse() is reliable during paintEvent\n        self.setAttribute(Qt.WidgetAttribute.WA_Hover, True)\n\n        self._apply_style_palette()\n\n        #  this must be called after the palette has been set for it to stick.\n        self.setStyle(get_ayon_style())\n\n    @property\n    def ayon_palette(self) -&gt; QPalette:\n        \"\"\"Return the palette used for this widget.\"\"\"\n        if self._pal is None:\n            self._apply_style_palette()\n        return self._pal\n\n    def variant_style(self, state=None) -&gt; dict:\n        \"\"\"Return the style dict for the current variant.\"\"\"\n        key = (self._variant_str, state)\n        if key not in self._variant_styles:\n            model = get_ayon_style().model\n            self._variant_styles[key] = model.get_style(\n                \"QLineEdit\", variant=self._variant_str, state=state\n            )\n        return self._variant_styles[key]\n\n    def _apply_style_palette(self) -&gt; None:\n        \"\"\"Push text / placeholder colors and padding from ayon_style.json.\"\"\"\n        style = self.variant_style()\n\n        self._pal = self.palette()\n\n        text_color = QColor(style.get(\"color\", \"#ffffff\"))\n        self._pal.setColor(QPalette.ColorRole.Text, text_color)\n        self._pal.setColor(QPalette.ColorRole.BrightText, text_color)\n\n        ph_color = QColor(style.get(\"placeholder-color\", \"#888888\"))\n        self._pal.setColor(QPalette.ColorRole.PlaceholderText, ph_color)\n\n        self._pal.setColor(\n            QPalette.ColorRole.Highlight,\n            QColor(style.get(\"selection-background-color\", \"#4040dd\")),\n        )\n        self._pal.setColor(\n            QPalette.ColorRole.HighlightedText,\n            QColor(style.get(\"selection-color\", \"#ffffff\")),\n        )\n\n        # Transparent base so the background rect we draw is visible\n        self._pal.setColor(QPalette.ColorRole.Base, QColor(0, 0, 0, 0))\n\n        self.setPalette(self._pal)\n\n        # Apply padding as text margins (immune to QSS interception)\n        padding = style.get(\"padding\", [8, 4])\n        pad_h = padding[0]\n        pad_v = padding[1]\n        icon_width = 0\n        if style.get(\"icon\"):\n            icon_width = style.get(\"icon-size\", 16) + style.get(\n                \"icon-padding\", 8\n            )\n        self.setTextMargins(pad_h + icon_width, pad_v, pad_h, pad_v)\n\n    def initStyleOption(self, option: QStyleOptionFrame) -&gt; None:\n        \"\"\"Override the palette used by the style to paint the widget.\"\"\"\n        self.setPalette(self.ayon_palette)\n        super().initStyleOption(option)\n\n    def paintEvent(self, event: QPaintEvent) -&gt; None:\n        \"\"\"Paint background, border, and focus ring, then delegate text rendering.\n\n        Draws the styled background rectangle and border first using QPainter\n        directly (no style or stylesheet involvement), then calls\n        super().paintEvent() which renders the text, cursor, and selection\n        highlight on top.  Qt's PE_PanelLineEdit call inside that base\n        implementation is intercepted by LineEditDrawer which returns\n        immediately for AYLineEdit instances, so our background is preserved.\n        \"\"\"\n\n        is_disabled = not self.isEnabled()\n        is_hover = self.underMouse()\n        has_focus = self.hasFocus()\n\n        if is_disabled:\n            state = \"disabled\"\n        elif is_hover and not has_focus:\n            state = \"hover\"\n        else:\n            state = \"base\"\n\n        style = self.variant_style(state)\n\n        bg_color = QColor(style.get(\"background-color\", \"#272d35\"))\n        border_color = QColor(style.get(\"border-color\", \"#41474d\"))\n        border_width = style.get(\"border-width\", 1)\n        border_radius = style.get(\"border-radius\", 2)\n        opacity = style.get(\"opacity\", 1.0)\n\n        focus_outline_width = style.get(\"focus-outline-width\", 2)\n        focus_outline_color = QColor(\n            style.get(\"focus-outline-color\", \"#8fceff\")\n        )\n\n        painter = QPainter(self)\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n        painter.setOpacity(opacity)\n\n        rect = QRectF(self.rect())\n        half_bw = border_width / 2.0\n\n        # Background\n        bg_rect = rect.adjusted(half_bw, half_bw, -half_bw, -half_bw)\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.setBrush(QBrush(bg_color))\n        painter.drawRoundedRect(bg_rect, border_radius, border_radius)\n\n        # icon\n        icon_name = style.get(\"icon\")\n        if icon_name:\n            icon_color = QColor(style.get(\"icon-color\", \"#888888\"))\n            icon_size = style.get(\"icon-size\", 16)\n            x = style.get(\"padding\", [8, 4])[0]\n            pixmap = get_icon(icon_name, color=icon_color).pixmap(\n                icon_size, icon_size\n            )\n            y = (rect.height() - icon_size) / 2.0\n            painter.drawPixmap(x, y, icon_size, icon_size, pixmap)\n\n        # Border\n        border_pen = QPen(border_color)\n        border_pen.setWidthF(border_width)\n        painter.setPen(border_pen)\n        painter.setBrush(Qt.BrushStyle.NoBrush)\n        painter.drawRoundedRect(bg_rect, border_radius, border_radius)\n\n        # Focus ring (drawn inset so it fits within the widget rect)\n        if has_focus:\n            half_fw = focus_outline_width / 2.0\n            focus_rect = rect.adjusted(half_fw, half_fw, -half_fw, -half_fw)\n            focus_pen = QPen(focus_outline_color)\n            focus_pen.setWidthF(focus_outline_width)\n            painter.setPen(focus_pen)\n            painter.setBrush(Qt.BrushStyle.NoBrush)\n            painter.drawRoundedRect(focus_rect, border_radius, border_radius)\n\n        painter.end()\n\n        # Let QLineEdit draw text, placeholder, cursor, and selection on top.\n        # LineEditDrawer intercepts PE_PanelLineEdit for AYLineEdit and is a\n        # no-op, so the background we just drew is preserved.\n        super().paintEvent(event)\n\n    def sizeHint(self) -&gt; QSize:\n        \"\"\"Override sizeHint to account for padding.\"\"\"\n        size = super().sizeHint()\n        style = self.variant_style()\n        padding = style.get(\"padding\", [8, 4])\n        size.setWidth(size.width() + padding[0] * 2)\n        size.setHeight(size.height() + padding[1] * 2)\n        return size\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/line_edit.html#client.ayon_ui_qt.components.line_edit.AYLineEdit.ayon_palette","title":"<code>ayon_palette</code>  <code>property</code>","text":"<p>Return the palette used for this widget.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/line_edit.html#client.ayon_ui_qt.components.line_edit.AYLineEdit.initStyleOption","title":"<code>initStyleOption(option)</code>","text":"<p>Override the palette used by the style to paint the widget.</p> Source code in <code>client/ayon_ui_qt/components/line_edit.py</code> <pre><code>def initStyleOption(self, option: QStyleOptionFrame) -&gt; None:\n    \"\"\"Override the palette used by the style to paint the widget.\"\"\"\n    self.setPalette(self.ayon_palette)\n    super().initStyleOption(option)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/line_edit.html#client.ayon_ui_qt.components.line_edit.AYLineEdit.paintEvent","title":"<code>paintEvent(event)</code>","text":"<p>Paint background, border, and focus ring, then delegate text rendering.</p> <p>Draws the styled background rectangle and border first using QPainter directly (no style or stylesheet involvement), then calls super().paintEvent() which renders the text, cursor, and selection highlight on top.  Qt's PE_PanelLineEdit call inside that base implementation is intercepted by LineEditDrawer which returns immediately for AYLineEdit instances, so our background is preserved.</p> Source code in <code>client/ayon_ui_qt/components/line_edit.py</code> <pre><code>def paintEvent(self, event: QPaintEvent) -&gt; None:\n    \"\"\"Paint background, border, and focus ring, then delegate text rendering.\n\n    Draws the styled background rectangle and border first using QPainter\n    directly (no style or stylesheet involvement), then calls\n    super().paintEvent() which renders the text, cursor, and selection\n    highlight on top.  Qt's PE_PanelLineEdit call inside that base\n    implementation is intercepted by LineEditDrawer which returns\n    immediately for AYLineEdit instances, so our background is preserved.\n    \"\"\"\n\n    is_disabled = not self.isEnabled()\n    is_hover = self.underMouse()\n    has_focus = self.hasFocus()\n\n    if is_disabled:\n        state = \"disabled\"\n    elif is_hover and not has_focus:\n        state = \"hover\"\n    else:\n        state = \"base\"\n\n    style = self.variant_style(state)\n\n    bg_color = QColor(style.get(\"background-color\", \"#272d35\"))\n    border_color = QColor(style.get(\"border-color\", \"#41474d\"))\n    border_width = style.get(\"border-width\", 1)\n    border_radius = style.get(\"border-radius\", 2)\n    opacity = style.get(\"opacity\", 1.0)\n\n    focus_outline_width = style.get(\"focus-outline-width\", 2)\n    focus_outline_color = QColor(\n        style.get(\"focus-outline-color\", \"#8fceff\")\n    )\n\n    painter = QPainter(self)\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n    painter.setOpacity(opacity)\n\n    rect = QRectF(self.rect())\n    half_bw = border_width / 2.0\n\n    # Background\n    bg_rect = rect.adjusted(half_bw, half_bw, -half_bw, -half_bw)\n    painter.setPen(Qt.PenStyle.NoPen)\n    painter.setBrush(QBrush(bg_color))\n    painter.drawRoundedRect(bg_rect, border_radius, border_radius)\n\n    # icon\n    icon_name = style.get(\"icon\")\n    if icon_name:\n        icon_color = QColor(style.get(\"icon-color\", \"#888888\"))\n        icon_size = style.get(\"icon-size\", 16)\n        x = style.get(\"padding\", [8, 4])[0]\n        pixmap = get_icon(icon_name, color=icon_color).pixmap(\n            icon_size, icon_size\n        )\n        y = (rect.height() - icon_size) / 2.0\n        painter.drawPixmap(x, y, icon_size, icon_size, pixmap)\n\n    # Border\n    border_pen = QPen(border_color)\n    border_pen.setWidthF(border_width)\n    painter.setPen(border_pen)\n    painter.setBrush(Qt.BrushStyle.NoBrush)\n    painter.drawRoundedRect(bg_rect, border_radius, border_radius)\n\n    # Focus ring (drawn inset so it fits within the widget rect)\n    if has_focus:\n        half_fw = focus_outline_width / 2.0\n        focus_rect = rect.adjusted(half_fw, half_fw, -half_fw, -half_fw)\n        focus_pen = QPen(focus_outline_color)\n        focus_pen.setWidthF(focus_outline_width)\n        painter.setPen(focus_pen)\n        painter.setBrush(Qt.BrushStyle.NoBrush)\n        painter.drawRoundedRect(focus_rect, border_radius, border_radius)\n\n    painter.end()\n\n    # Let QLineEdit draw text, placeholder, cursor, and selection on top.\n    # LineEditDrawer intercepts PE_PanelLineEdit for AYLineEdit and is a\n    # no-op, so the background we just drew is preserved.\n    super().paintEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/line_edit.html#client.ayon_ui_qt.components.line_edit.AYLineEdit.sizeHint","title":"<code>sizeHint()</code>","text":"<p>Override sizeHint to account for padding.</p> Source code in <code>client/ayon_ui_qt/components/line_edit.py</code> <pre><code>def sizeHint(self) -&gt; QSize:\n    \"\"\"Override sizeHint to account for padding.\"\"\"\n    size = super().sizeHint()\n    style = self.variant_style()\n    padding = style.get(\"padding\", [8, 4])\n    size.setWidth(size.width() + padding[0] * 2)\n    size.setHeight(size.height() + padding[1] * 2)\n    return size\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/line_edit.html#client.ayon_ui_qt.components.line_edit.AYLineEdit.variant_style","title":"<code>variant_style(state=None)</code>","text":"<p>Return the style dict for the current variant.</p> Source code in <code>client/ayon_ui_qt/components/line_edit.py</code> <pre><code>def variant_style(self, state=None) -&gt; dict:\n    \"\"\"Return the style dict for the current variant.\"\"\"\n    key = (self._variant_str, state)\n    if key not in self._variant_styles:\n        model = get_ayon_style().model\n        self._variant_styles[key] = model.get_style(\n            \"QLineEdit\", variant=self._variant_str, state=state\n        )\n    return self._variant_styles[key]\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/qss_override.html","title":"qss_override","text":""},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html","title":"screenshot_capture","text":"<p>Screenshot capture widget and handler for text box component.</p> <p>Based on AYON core screenshot widget with proper DPI handling.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenMarquee","title":"<code>ScreenMarquee</code>","text":"<p>               Bases: <code>QObject</code></p> <p>Screen marquee selection tool.</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>class ScreenMarquee(QObject):\n    \"\"\"Screen marquee selection tool.\"\"\"\n\n    def __init__(self, parent=None):\n        super().__init__(parent=parent)\n\n        screens_by_id = {}\n        for screen in QApplication.screens():\n            screen_id = uuid.uuid4().hex\n            screen_dialog = ScreenMarqueeDialog(screen, screen_id)\n            screens_by_id[screen_id] = screen_dialog\n            screen_dialog.mouse_moved.connect(self._on_mouse_move)\n            screen_dialog.mouse_pressed.connect(self._on_mouse_press)\n            screen_dialog.mouse_released.connect(self._on_mouse_release)\n            screen_dialog.close_requested.connect(self._on_close_request)\n\n        self._screens_by_id = screens_by_id\n        self._finished = False\n        self._captured = False\n        self._start_pos = None\n        self._end_pos = None\n        self._start_screen_id = None\n        self._pix = None\n\n    def get_captured_pixmap(self):\n        if self._pix is None:\n            return QPixmap()\n        return self._pix\n\n    def _close_dialogs(self):\n        for dialog in self._screens_by_id.values():\n            dialog.close()\n\n    def _on_close_request(self):\n        self._close_dialogs()\n        self._finished = True\n\n    def _on_mouse_release(self, pos):\n        start_screen_dialog = self._screens_by_id.get(self._start_screen_id)\n        if start_screen_dialog is None:\n            self._finished = True\n            self._captured = False\n            return\n\n        end_pos = start_screen_dialog.convert_end_pos(pos)\n        self._close_dialogs()\n        self._end_pos = end_pos\n        self._finished = True\n        self._captured = True\n\n    def _on_mouse_press(self, pos, screen_id):\n        self._start_pos = pos\n        self._start_screen_id = screen_id\n\n    def _on_mouse_move(self):\n        for dialog in self._screens_by_id.values():\n            dialog.repaint()\n\n    def start_capture(self):\n        for dialog in self._screens_by_id.values():\n            dialog.show()\n            dialog.setWindowState(Qt.WindowState.WindowActive)\n\n        app = QApplication.instance()\n        if app is not None:\n            while not self._finished:\n                app.processEvents()\n\n            # Give time to close dialogs\n            for _ in range(2):\n                app.processEvents()\n        else:\n            logger.error(\n                \"No QApplication instance found. \"\n                \"Capture may not work properly.\"\n            )\n            self._finished = True\n\n        if self._captured:\n            self._pix = self.get_desktop_pixmap(self._start_pos, self._end_pos)\n\n    @classmethod\n    def get_desktop_pixmap(cls, pos_start, pos_end):\n        \"\"\"Capture screen area between two points.\"\"\"\n        # Unify start and end points\n        if pos_start.y() &gt; pos_end.y():\n            pos_start, pos_end = pos_end, pos_start\n\n        if pos_start.x() &gt; pos_end.x():\n            new_start = QPoint(pos_end.x(), pos_start.y())\n            new_end = QPoint(pos_start.x(), pos_end.y())\n            pos_start = new_start\n            pos_end = new_end\n\n        # Validate rectangle\n        rect = QRect(pos_start, pos_end)\n        if rect.width() &lt; 1 or rect.height() &lt; 1:\n            return QPixmap()\n\n        screen = QApplication.screenAt(pos_start)\n        if screen is None:\n            return QPixmap()\n\n        return screen.grabWindow(\n            0,\n            pos_start.x() - screen.geometry().x(),\n            pos_start.y() - screen.geometry().y(),\n            pos_end.x() - pos_start.x(),\n            pos_end.y() - pos_start.y(),\n        )\n\n    @classmethod\n    def capture_to_pixmap(cls):\n        \"\"\"Take screenshot with marquee into pixmap.\"\"\"\n        tool = cls()\n        tool.start_capture()\n        return tool.get_captured_pixmap()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenMarquee.capture_to_pixmap","title":"<code>capture_to_pixmap()</code>  <code>classmethod</code>","text":"<p>Take screenshot with marquee into pixmap.</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>@classmethod\ndef capture_to_pixmap(cls):\n    \"\"\"Take screenshot with marquee into pixmap.\"\"\"\n    tool = cls()\n    tool.start_capture()\n    return tool.get_captured_pixmap()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenMarquee.get_desktop_pixmap","title":"<code>get_desktop_pixmap(pos_start, pos_end)</code>  <code>classmethod</code>","text":"<p>Capture screen area between two points.</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>@classmethod\ndef get_desktop_pixmap(cls, pos_start, pos_end):\n    \"\"\"Capture screen area between two points.\"\"\"\n    # Unify start and end points\n    if pos_start.y() &gt; pos_end.y():\n        pos_start, pos_end = pos_end, pos_start\n\n    if pos_start.x() &gt; pos_end.x():\n        new_start = QPoint(pos_end.x(), pos_start.y())\n        new_end = QPoint(pos_start.x(), pos_end.y())\n        pos_start = new_start\n        pos_end = new_end\n\n    # Validate rectangle\n    rect = QRect(pos_start, pos_end)\n    if rect.width() &lt; 1 or rect.height() &lt; 1:\n        return QPixmap()\n\n    screen = QApplication.screenAt(pos_start)\n    if screen is None:\n        return QPixmap()\n\n    return screen.grabWindow(\n        0,\n        pos_start.x() - screen.geometry().x(),\n        pos_start.y() - screen.geometry().y(),\n        pos_end.x() - pos_start.x(),\n        pos_end.y() - pos_start.y(),\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenMarqueeDialog","title":"<code>ScreenMarqueeDialog</code>","text":"<p>               Bases: <code>QWidget</code></p> <p>Dialog for single screen marquee selection.</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>class ScreenMarqueeDialog(QWidget):\n    \"\"\"Dialog for single screen marquee selection.\"\"\"\n\n    mouse_moved = Signal()\n    mouse_pressed = Signal(QPoint, str)\n    mouse_released = Signal(QPoint)\n    close_requested = Signal()\n\n    def __init__(self, screen: QScreen, screen_id: str):\n        super().__init__()\n        self.setWindowFlags(\n            Qt.WindowType.Window\n            | Qt.WindowType.FramelessWindowHint\n            | Qt.WindowType.WindowStaysOnTopHint\n            | Qt.WindowType.CustomizeWindowHint\n        )\n        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)\n        self.setCursor(Qt.CursorShape.CrossCursor)\n        self.setMouseTracking(True)\n\n        screen.geometryChanged.connect(self._fit_screen_geometry)\n\n        self._screen = screen\n        self._opacity = 100\n        self._click_pos = None\n        self._screen_id = screen_id\n\n    def set_click_pos(self, pos):\n        self._click_pos = pos\n        self.repaint()\n\n    def convert_end_pos(self, pos):\n        glob_pos = self.mapFromGlobal(pos)\n        new_pos = self._convert_pos(glob_pos)\n        return self.mapToGlobal(new_pos)\n\n    def paintEvent(self, event):\n        \"\"\"Paint event\"\"\"\n        mouse_pos = self._convert_pos(self.mapFromGlobal(QCursor.pos()))\n        rect = event.rect()\n        fill_path = QPainterPath()\n        fill_path.addRect(rect)\n\n        capture_rect = None\n        if self._click_pos is not None:\n            click_pos = self.mapFromGlobal(self._click_pos)\n            capture_rect = QRect(click_pos, mouse_pos)\n\n            # Clear the capture area\n            sub_path = QPainterPath()\n            sub_path.addRect(capture_rect)\n            fill_path = fill_path.subtracted(sub_path)\n\n        painter = QPainter(self)\n        painter.setRenderHints(\n            QPainter.RenderHint.Antialiasing\n            | QPainter.RenderHint.SmoothPixmapTransform\n        )\n\n        # Draw background\n        painter.setBrush(QColor(0, 0, 0, self._opacity))\n        painter.setPen(Qt.PenStyle.NoPen)\n        painter.drawPath(fill_path)\n\n        # Draw cropping markers at current mouse position\n        pen_color = QColor(255, 255, 255, self._opacity)\n        pen = QPen(pen_color, 1, Qt.PenStyle.DotLine)\n        painter.setPen(pen)\n        painter.drawLine(\n            rect.left(), mouse_pos.y(), rect.right(), mouse_pos.y()\n        )\n        painter.drawLine(\n            mouse_pos.x(), rect.top(), mouse_pos.x(), rect.bottom()\n        )\n\n        # Draw rectangle around selection area\n        if capture_rect is not None:\n            pen_color = QColor(92, 173, 214)\n            pen = QPen(pen_color, 2, Qt.PenStyle.SolidLine)\n            painter.setPen(pen)\n            painter.setBrush(Qt.BrushStyle.NoBrush)\n            l_x = capture_rect.left()\n            r_x = capture_rect.right()\n            if l_x &gt; r_x:\n                l_x, r_x = r_x, l_x\n            t_y = capture_rect.top()\n            b_y = capture_rect.bottom()\n            if t_y &gt; b_y:\n                t_y, b_y = b_y, t_y\n\n            r_x -= 1\n            b_y -= 1\n            sel_rect = QRect(QPoint(l_x, t_y), QPoint(r_x, b_y))\n            painter.drawRect(sel_rect)\n\n        painter.end()\n\n    def mousePressEvent(self, event):\n        \"\"\"Mouse click event\"\"\"\n        if event.button() == Qt.MouseButton.LeftButton:\n            self._click_pos = event.globalPos()\n            self.mouse_pressed.emit(self._click_pos, self._screen_id)\n\n    def mouseReleaseEvent(self, event):\n        \"\"\"Mouse release event\"\"\"\n        if event.button() == Qt.MouseButton.LeftButton:\n            self._click_pos = None\n            self.mouse_released.emit(event.globalPos())\n\n    def mouseMoveEvent(self, event):\n        \"\"\"Mouse move event\"\"\"\n        self.mouse_moved.emit()\n\n    def keyPressEvent(self, event):\n        \"\"\"Key press event\"\"\"\n        if event.key() == Qt.Key.Key_Escape:\n            self._click_pos = None\n            event.accept()\n            self.close_requested.emit()\n            return\n        return super().keyPressEvent(event)\n\n    def showEvent(self, event):\n        super().showEvent(event)\n        self._fit_screen_geometry()\n\n    def closeEvent(self, event):\n        self._click_pos = None\n        super().closeEvent(event)\n\n    def _convert_pos(self, pos):\n        geo = self.geometry()\n        if pos.x() &gt; geo.width():\n            pos.setX(geo.width() - 1)\n        elif pos.x() &lt; 0:\n            pos.setX(0)\n\n        if pos.y() &gt; geo.height():\n            pos.setY(geo.height() - 1)\n        elif pos.y() &lt; 0:\n            pos.setY(0)\n        return pos\n\n    def _fit_screen_geometry(self):\n        if hasattr(self, \"setScreen\"):\n            self.setScreen(self._screen)\n        self.setGeometry(self._screen.geometry())\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenMarqueeDialog.keyPressEvent","title":"<code>keyPressEvent(event)</code>","text":"<p>Key press event</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>def keyPressEvent(self, event):\n    \"\"\"Key press event\"\"\"\n    if event.key() == Qt.Key.Key_Escape:\n        self._click_pos = None\n        event.accept()\n        self.close_requested.emit()\n        return\n    return super().keyPressEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenMarqueeDialog.mouseMoveEvent","title":"<code>mouseMoveEvent(event)</code>","text":"<p>Mouse move event</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>def mouseMoveEvent(self, event):\n    \"\"\"Mouse move event\"\"\"\n    self.mouse_moved.emit()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenMarqueeDialog.mousePressEvent","title":"<code>mousePressEvent(event)</code>","text":"<p>Mouse click event</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>def mousePressEvent(self, event):\n    \"\"\"Mouse click event\"\"\"\n    if event.button() == Qt.MouseButton.LeftButton:\n        self._click_pos = event.globalPos()\n        self.mouse_pressed.emit(self._click_pos, self._screen_id)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenMarqueeDialog.mouseReleaseEvent","title":"<code>mouseReleaseEvent(event)</code>","text":"<p>Mouse release event</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>def mouseReleaseEvent(self, event):\n    \"\"\"Mouse release event\"\"\"\n    if event.button() == Qt.MouseButton.LeftButton:\n        self._click_pos = None\n        self.mouse_released.emit(event.globalPos())\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenMarqueeDialog.paintEvent","title":"<code>paintEvent(event)</code>","text":"<p>Paint event</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>def paintEvent(self, event):\n    \"\"\"Paint event\"\"\"\n    mouse_pos = self._convert_pos(self.mapFromGlobal(QCursor.pos()))\n    rect = event.rect()\n    fill_path = QPainterPath()\n    fill_path.addRect(rect)\n\n    capture_rect = None\n    if self._click_pos is not None:\n        click_pos = self.mapFromGlobal(self._click_pos)\n        capture_rect = QRect(click_pos, mouse_pos)\n\n        # Clear the capture area\n        sub_path = QPainterPath()\n        sub_path.addRect(capture_rect)\n        fill_path = fill_path.subtracted(sub_path)\n\n    painter = QPainter(self)\n    painter.setRenderHints(\n        QPainter.RenderHint.Antialiasing\n        | QPainter.RenderHint.SmoothPixmapTransform\n    )\n\n    # Draw background\n    painter.setBrush(QColor(0, 0, 0, self._opacity))\n    painter.setPen(Qt.PenStyle.NoPen)\n    painter.drawPath(fill_path)\n\n    # Draw cropping markers at current mouse position\n    pen_color = QColor(255, 255, 255, self._opacity)\n    pen = QPen(pen_color, 1, Qt.PenStyle.DotLine)\n    painter.setPen(pen)\n    painter.drawLine(\n        rect.left(), mouse_pos.y(), rect.right(), mouse_pos.y()\n    )\n    painter.drawLine(\n        mouse_pos.x(), rect.top(), mouse_pos.x(), rect.bottom()\n    )\n\n    # Draw rectangle around selection area\n    if capture_rect is not None:\n        pen_color = QColor(92, 173, 214)\n        pen = QPen(pen_color, 2, Qt.PenStyle.SolidLine)\n        painter.setPen(pen)\n        painter.setBrush(Qt.BrushStyle.NoBrush)\n        l_x = capture_rect.left()\n        r_x = capture_rect.right()\n        if l_x &gt; r_x:\n            l_x, r_x = r_x, l_x\n        t_y = capture_rect.top()\n        b_y = capture_rect.bottom()\n        if t_y &gt; b_y:\n            t_y, b_y = b_y, t_y\n\n        r_x -= 1\n        b_y -= 1\n        sel_rect = QRect(QPoint(l_x, t_y), QPoint(r_x, b_y))\n        painter.drawRect(sel_rect)\n\n    painter.end()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenshotHandler","title":"<code>ScreenshotHandler</code>","text":"<p>Handles screenshot capture for text box.</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>class ScreenshotHandler:\n    \"\"\"Handles screenshot capture for text box.\"\"\"\n\n    def __init__(self, parent_widget, screenshot_button):\n        \"\"\"Initialize screenshot handler.\n\n        Args:\n            parent_widget: Parent widget instance (typically AYTextBox)\n            screenshot_button: Screenshot button widget\n        \"\"\"\n        self._parent = parent_widget\n        self.screenshot_btn = screenshot_button\n        self._pending_screenshots = []\n        # Create a dedicated temp directory for this handler\n        self._temp_dir = tempfile.TemporaryDirectory(\n            prefix=\"ayon_screenshots_\"\n        )\n\n    def launch_capture(self):\n        \"\"\"Launch screenshot capture tool.\"\"\"\n        main_window = self._parent.window()\n        if main_window:\n            main_window.showMinimized()\n\n        QTimer.singleShot(200, self._show_snipping_widget)\n\n    def _show_snipping_widget(self):\n        \"\"\"Show snipping widget after window is minimized.\"\"\"\n        pixmap = ScreenMarquee.capture_to_pixmap()\n        self._on_screenshot_captured(pixmap)\n\n    def _on_screenshot_captured(self, pixmap):\n        \"\"\"Handle captured screenshot.\"\"\"\n        if pixmap and not pixmap.isNull():\n            screenshot_num = len(self._pending_screenshots) + 1\n            temp_path = os.path.join(\n                self._temp_dir.name, f\"ss{screenshot_num}.jpg\"\n            )\n            if pixmap.save(temp_path, \"JPEG\"):\n                self._pending_screenshots.append(temp_path)\n\n                # Add to parent's unified attachment system\n                if hasattr(self._parent, \"add_attachment\"):\n                    self._parent.add_attachment(temp_path, \"screenshot\")\n\n                logger.debug(\"Screenshot attached: %s\", temp_path)\n\n        self._restore_window()\n\n    def _restore_window(self):\n        \"\"\"Restore parent window.\"\"\"\n        main_window = self._parent.window()\n        if main_window:\n            main_window.showNormal()\n            main_window.activateWindow()\n\n    def get_screenshot_paths(self):\n        \"\"\"Get list of pending screenshot paths.\n\n        Returns:\n            list: List of screenshot file paths\n        \"\"\"\n        return self._pending_screenshots.copy()\n\n    def clear_screenshots(self):\n        \"\"\"Clear all pending screenshots and their files.\"\"\"\n        self._pending_screenshots.clear()\n        # Recreate the temp dir (deletes old files)\n        self._temp_dir.cleanup()\n        self._temp_dir = tempfile.TemporaryDirectory(\n            prefix=\"ayon_screenshots_\"\n        )\n\n    def cleanup(self):\n        \"\"\"Delete all screenshot files. Call when handler is\n        no longer needed.\"\"\"\n        self._pending_screenshots.clear()\n        self._temp_dir.cleanup()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenshotHandler.__init__","title":"<code>__init__(parent_widget, screenshot_button)</code>","text":"<p>Initialize screenshot handler.</p> <p>Parameters:</p> Name Type Description Default <code>parent_widget</code> <p>Parent widget instance (typically AYTextBox)</p> required <code>screenshot_button</code> <p>Screenshot button widget</p> required Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>def __init__(self, parent_widget, screenshot_button):\n    \"\"\"Initialize screenshot handler.\n\n    Args:\n        parent_widget: Parent widget instance (typically AYTextBox)\n        screenshot_button: Screenshot button widget\n    \"\"\"\n    self._parent = parent_widget\n    self.screenshot_btn = screenshot_button\n    self._pending_screenshots = []\n    # Create a dedicated temp directory for this handler\n    self._temp_dir = tempfile.TemporaryDirectory(\n        prefix=\"ayon_screenshots_\"\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenshotHandler.cleanup","title":"<code>cleanup()</code>","text":"<p>Delete all screenshot files. Call when handler is no longer needed.</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>def cleanup(self):\n    \"\"\"Delete all screenshot files. Call when handler is\n    no longer needed.\"\"\"\n    self._pending_screenshots.clear()\n    self._temp_dir.cleanup()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenshotHandler.clear_screenshots","title":"<code>clear_screenshots()</code>","text":"<p>Clear all pending screenshots and their files.</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>def clear_screenshots(self):\n    \"\"\"Clear all pending screenshots and their files.\"\"\"\n    self._pending_screenshots.clear()\n    # Recreate the temp dir (deletes old files)\n    self._temp_dir.cleanup()\n    self._temp_dir = tempfile.TemporaryDirectory(\n        prefix=\"ayon_screenshots_\"\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenshotHandler.get_screenshot_paths","title":"<code>get_screenshot_paths()</code>","text":"<p>Get list of pending screenshot paths.</p> <p>Returns:</p> Name Type Description <code>list</code> <p>List of screenshot file paths</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>def get_screenshot_paths(self):\n    \"\"\"Get list of pending screenshot paths.\n\n    Returns:\n        list: List of screenshot file paths\n    \"\"\"\n    return self._pending_screenshots.copy()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/screenshot_capture.html#client.ayon_ui_qt.components.screenshot_capture.ScreenshotHandler.launch_capture","title":"<code>launch_capture()</code>","text":"<p>Launch screenshot capture tool.</p> Source code in <code>client/ayon_ui_qt/components/screenshot_capture.py</code> <pre><code>def launch_capture(self):\n    \"\"\"Launch screenshot capture tool.\"\"\"\n    main_window = self._parent.window()\n    if main_window:\n        main_window.showMinimized()\n\n    QTimer.singleShot(200, self._show_snipping_widget)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/scroll_area.html","title":"scroll_area","text":"<p>scroll area</p>"},{"location":"autoapi/client/ayon_ui_qt/components/scroll_area.html#client.ayon_ui_qt.components.scroll_area.AYScrollArea","title":"<code>AYScrollArea</code>","text":"<p>               Bases: <code>QScrollArea</code></p> <p>AYON styled scroll area widget.</p> <p>Overrides Qt's stylesheet painting with AYONStyle custom rendering.</p> <p>Parameters:</p> Name Type Description Default <code>*args</code> <p>Positional arguments passed to QTextEdit.</p> <code>()</code> <code>**kwargs</code> <p>Keyword arguments passed to QTextEdit.</p> <code>{}</code> Source code in <code>client/ayon_ui_qt/components/scroll_area.py</code> <pre><code>class AYScrollArea(QScrollArea):\n    \"\"\"AYON styled scroll area widget.\n\n    Overrides Qt's stylesheet painting with AYONStyle custom rendering.\n\n    Args:\n        *args: Positional arguments passed to QTextEdit.\n        **kwargs: Keyword arguments passed to QTextEdit.\n    \"\"\"\n\n    def __init__(self, *args, **kwargs):\n        super().__init__(*args, **kwargs)\n        self.setStyle(get_ayon_style())\n\n        self.setVerticalScrollBar(AYScrollBar(Qt.Orientation.Vertical))\n        self.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)\n        self.setHorizontalScrollBar(AYScrollBar(Qt.Orientation.Horizontal))\n        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/scroll_area.html#client.ayon_ui_qt.components.scroll_area.AYScrollBar","title":"<code>AYScrollBar</code>","text":"<p>               Bases: <code>QScrollBar</code></p> <p>AYON styled scroll bar widget.</p> <p>Overrides Qt's stylesheet painting with AYONStyle custom rendering.</p> <p>Parameters:</p> Name Type Description Default <code>*args</code> <p>Positional arguments passed to QTextEdit.</p> <code>()</code> <code>**kwargs</code> <p>Keyword arguments passed to QTextEdit.</p> <code>{}</code> Source code in <code>client/ayon_ui_qt/components/scroll_area.py</code> <pre><code>class AYScrollBar(QScrollBar):\n    \"\"\"AYON styled scroll bar widget.\n\n    Overrides Qt's stylesheet painting with AYONStyle custom rendering.\n\n    Args:\n        *args: Positional arguments passed to QTextEdit.\n        **kwargs: Keyword arguments passed to QTextEdit.\n    \"\"\"\n\n    def __init__(self, *args, **kwargs) -&gt; None:\n        super().__init__(*args, **kwargs)\n        self.setStyle(get_ayon_style())\n\n    def initStyleOption(self, option: QStyleOptionSlider) -&gt; None:\n        super().initStyleOption(option)\n        SC = QStyle.SubControl\n        option.subControls = (\n            SC.SC_None\n            | SC.SC_ScrollBarAddPage\n            | SC.SC_ScrollBarSubPage\n            | SC.SC_ScrollBarSlider\n        )\n\n    def paintEvent(self, arg__1: QPaintEvent) -&gt; None:\n        p = QPainter(self)\n        option = QStyleOptionSlider()\n        self.initStyleOption(option)\n        get_ayon_style().drawComplexControl(\n            QStyle.ComplexControl.CC_ScrollBar, option, p, self\n        )\n        return\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/slicer.html","title":"slicer","text":""},{"location":"autoapi/client/ayon_ui_qt/components/slicer.html#client.ayon_ui_qt.components.slicer.AYSlicer","title":"<code>AYSlicer</code>","text":"<p>               Bases: <code>AYContainer</code></p> Source code in <code>client/ayon_ui_qt/components/slicer.py</code> <pre><code>class AYSlicer(AYContainer):\n    category_changed = Signal(str)\n\n    def __init__(self, item_list=None, parent=None, initial_text=\"\"):\n        super().__init__(\n            layout=AYContainer.Layout.HBox,\n            variant=AYContainer.Variants.Low,\n            parent=parent,\n        )\n        self._combo = AYComboBox(\n            items=item_list,\n            variant=AYComboBox.Variants.Low,\n        )\n        if initial_text:\n            self._combo.setCurrentText(initial_text)\n        self._field = AYLineEdit(placeholder=\"Search\")\n        self._button = AYButton(\n            variant=AYButton.Variants.Nav,\n            icon=\"search\",\n            icon_on=\"close\",\n            checkable=True,\n        )\n\n        self.add_widget(self._combo)\n        self.add_widget(self._field, stretch=1)\n        self.add_widget(self._button)\n\n        self._field.setVisible(False)\n\n        # search filter\n        self._proxy: TreeFilterProxyModel | None = None\n\n        self._field.installEventFilter(self)\n\n        # signals\n        self._button.toggled.connect(self._on_button_toggled)\n        self._field.textChanged.connect(self._on_search_changed)\n        self._combo.currentTextChanged.connect(self._on_category_changed)\n\n    def current_category(self) -&gt; str:\n        return self._combo.currentText()\n\n    def _on_category_changed(self, text: str):\n        \"\"\"Notify other widgets of the criteria change.\"\"\"\n        self.category_changed.emit(text)\n\n    def set_model(\n        self,\n        model: QAbstractItemModel,\n        view=None,\n    ):\n        \"\"\"Insert a filter proxy between model and view.\n\n        Args:\n            model: The source model (e.g. LazyTreeModel).\n            view: The QAbstractItemView that displays the model.\n        \"\"\"\n        self._proxy = TreeFilterProxyModel(self)\n        self._proxy.setSourceModel(model)\n        if view is not None:\n            view.setModel(self._proxy)\n        self._view = view\n\n    def _on_search_changed(self, text: str):\n        \"\"\"Update the proxy filter when the user types.\"\"\"\n        if self._proxy is None:\n            return\n        self._proxy.setFilterFixedString(text)\n\n    def _on_button_toggled(self, checked):\n        self._combo.setVisible(not checked)\n        self._field.setVisible(checked)\n        if checked:\n            self._field.setFocus()\n        else:\n            # clear the filter when closing search\n            self._field.clear()\n\n    def eventFilter(self, obj, event):\n        \"\"\"Close search field on Escape key press.\"\"\"\n        if (\n            obj is self._field\n            and event.type() == QEvent.Type.KeyPress\n            and event.key() == Qt.Key.Key_Escape\n        ):\n            self._button.setChecked(False)  # triggers _on_button_toggled\n            return True\n        return super().eventFilter(obj, event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/slicer.html#client.ayon_ui_qt.components.slicer.AYSlicer.eventFilter","title":"<code>eventFilter(obj, event)</code>","text":"<p>Close search field on Escape key press.</p> Source code in <code>client/ayon_ui_qt/components/slicer.py</code> <pre><code>def eventFilter(self, obj, event):\n    \"\"\"Close search field on Escape key press.\"\"\"\n    if (\n        obj is self._field\n        and event.type() == QEvent.Type.KeyPress\n        and event.key() == Qt.Key.Key_Escape\n    ):\n        self._button.setChecked(False)  # triggers _on_button_toggled\n        return True\n    return super().eventFilter(obj, event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/slicer.html#client.ayon_ui_qt.components.slicer.AYSlicer.set_model","title":"<code>set_model(model, view=None)</code>","text":"<p>Insert a filter proxy between model and view.</p> <p>Parameters:</p> Name Type Description Default <code>model</code> <code>QAbstractItemModel</code> <p>The source model (e.g. LazyTreeModel).</p> required <code>view</code> <p>The QAbstractItemView that displays the model.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/slicer.py</code> <pre><code>def set_model(\n    self,\n    model: QAbstractItemModel,\n    view=None,\n):\n    \"\"\"Insert a filter proxy between model and view.\n\n    Args:\n        model: The source model (e.g. LazyTreeModel).\n        view: The QAbstractItemView that displays the model.\n    \"\"\"\n    self._proxy = TreeFilterProxyModel(self)\n    self._proxy.setSourceModel(model)\n    if view is not None:\n        view.setModel(self._proxy)\n    self._view = view\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/slicer.html#client.ayon_ui_qt.components.slicer.TreeFilterProxyModel","title":"<code>TreeFilterProxyModel</code>","text":"<p>               Bases: <code>QSortFilterProxyModel</code></p> <p>Proxy that filters tree items by label, recursively.</p> Source code in <code>client/ayon_ui_qt/components/slicer.py</code> <pre><code>class TreeFilterProxyModel(QSortFilterProxyModel):\n    \"\"\"Proxy that filters tree items by label, recursively.\"\"\"\n\n    def __init__(self, parent=None):\n        super().__init__(parent)\n        self.setFilterCaseSensitivity(Qt.CaseSensitivity.CaseInsensitive)\n        self.setFilterRole(Qt.ItemDataRole.DisplayRole)\n        self.setRecursiveFilteringEnabled(True)  # Qt 5.10+\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_filter.html","title":"table_filter","text":""},{"location":"autoapi/client/ayon_ui_qt/components/table_filter.html#client.ayon_ui_qt.components.table_filter.AYTableFilter","title":"<code>AYTableFilter</code>","text":"<p>               Bases: <code>AYContainer</code></p> <p>Horizontal filter bar bound to a PaginatedTableModel.</p> <p>Displays active criteria as badges and manages a floating two-page dropdown for adding/editing criteria.  Applies filtering via an internal <code>AYTableFilterProxyModel</code>.</p> <p>Typical usage::</p> <pre><code>filter_bar = AYTableFilter(model=source_model)\ntable.setModel(filter_bar.filter_model)\nlayout.addWidget(filter_bar)\nlayout.addWidget(table)\n</code></pre> Signals <p>filters_changed: Emitted after any criteria change.                  Passes the current list of FilterCriterion.</p> Source code in <code>client/ayon_ui_qt/components/table_filter.py</code> <pre><code>class AYTableFilter(AYContainer):\n    \"\"\"Horizontal filter bar bound to a PaginatedTableModel.\n\n    Displays active criteria as badges and manages a floating two-page\n    dropdown for adding/editing criteria.  Applies filtering via an\n    internal ``AYTableFilterProxyModel``.\n\n    Typical usage::\n\n        filter_bar = AYTableFilter(model=source_model)\n        table.setModel(filter_bar.filter_model)\n        layout.addWidget(filter_bar)\n        layout.addWidget(table)\n\n    Signals:\n        filters_changed: Emitted after any criteria change.\n                         Passes the current list of FilterCriterion.\n    \"\"\"\n\n    filters_changed = Signal(list)  # list[FilterCriterion]\n\n    def __init__(\n        self,\n        model: PaginatedTableModel,\n        parent: QWidget | None = None,\n    ) -&gt; None:\n        super().__init__(\n            parent=parent,\n            layout=AYContainer.Layout.HBox,\n            variant=AYContainer.Variants.Low_Framed_Thin,\n            layout_margin=4,\n        )\n        self.setObjectName(\"AYTableFilter\")\n        self.setFixedHeight(32)\n\n        self._model = model\n        self._criteria: list[FilterCriterion] = []\n        self._editing_criterion: FilterCriterion | None = None\n\n        # Proxy model wraps the source model\n        self._proxy = AYTableFilterProxyModel(self)\n        self._proxy.setSourceModel(model)\n        # Re-filter whenever new rows are loaded\n        model.rowsInserted.connect(lambda *_: self._proxy.refresh_filter())\n\n        # Shared dropdown instance (reused across open calls)\n        self._dropdown = _FilterDropdown(model, self)\n        self._dropdown.criterion_ready.connect(self._on_criterion_ready)\n\n        # search button - always visible, opens empty dropdown for new criterion\n        self._search_btn = AYButton(\n            icon=\"search\",\n            variant=AYButton.Variants.Nav_Small,\n        )\n        self._search_btn.clicked.connect(\n            lambda: self._dropdown.open_for_new(self)\n        )\n        self.add_widget(self._search_btn)\n\n        # main container for criteria badges\n        self._criteria_container = AYHBoxLayout(spacing=4, margin=0)\n        self.add_layout(self._criteria_container, stretch=1)\n\n        self._rebuild_bar()\n\n    # ------------------------------------------------------------------\n    # Public API\n    # ------------------------------------------------------------------\n\n    @property\n    def filter_model(self) -&gt; AYTableFilterProxyModel:\n        \"\"\"Return the proxy model to set on the view.\"\"\"\n        return self._proxy\n\n    # ------------------------------------------------------------------\n    # Bar management\n    # ------------------------------------------------------------------\n\n    def _rebuild_bar(self) -&gt; None:\n        \"\"\"Clear and repopulate the bar with current criteria.\"\"\"\n        self._criteria_container.clear()\n\n        if not self._criteria:\n            empty_btn = AYButton(\n                \"Filter\",\n                variant=AYButton.Variants.Table_Filter,\n                label_alignment=Qt.AlignmentFlag.AlignLeft,\n                fixed_width=False,\n            )\n            empty_btn.clicked.connect(\n                lambda: self._dropdown.open_for_new(self)\n            )\n            self._criteria_container.addWidget(empty_btn)\n            return\n\n        for i, criterion in enumerate(self._criteria):\n            if i &gt; 0:\n                sep = AYLabel(\"and\", dim=True)\n                sep.setContentsMargins(2, 0, 2, 0)\n                self._criteria_container.addWidget(sep)\n\n            badge = _CriterionBadge(criterion)\n            badge.edit_requested.connect(self._on_badge_edit)\n            badge.remove_requested.connect(self._on_badge_remove)\n            self._criteria_container.addWidget(badge)\n\n        # \"+\" button to add another criterion\n        add_btn = AYButton(\n            icon=\"add\",\n            variant=AYButton.Variants.Nav_Small,\n        )\n        add_btn.setFixedSize(24, 24)\n        add_btn.clicked.connect(lambda: self._dropdown.open_for_new(self))\n        self._criteria_container.addWidget(add_btn)\n\n        self._criteria_container.addStretch()\n\n    # ------------------------------------------------------------------\n    # Criterion handlers\n    # ------------------------------------------------------------------\n\n    def _on_criterion_ready(\n        self, key: str, values: list[str], use_substring: bool, excludes: bool\n    ) -&gt; None:\n        if not values:\n            # Empty apply \u2014 remove existing criterion for this key if any\n            self._criteria = [c for c in self._criteria if c.key != key]\n        elif self._editing_criterion is not None:\n            # Update in-place\n            self._editing_criterion.values = values\n            self._editing_criterion.use_substring = use_substring\n        else:\n            # Check if criterion for this key already exists\n            existing = next((c for c in self._criteria if c.key == key), None)\n            if existing:\n                existing.values = values\n                existing.use_substring = use_substring\n            else:\n                col = next(\n                    (c for c in self._model.columns if c.key == key), None\n                )\n                label = col.label if col else key\n                self._criteria.append(\n                    FilterCriterion(\n                        key=key,\n                        attribute_label=label,\n                        values=values,\n                        use_substring=use_substring,\n                        exclude=excludes,\n                    )\n                )\n\n        self._editing_criterion = None\n        self._rebuild_bar()\n        self._update_proxy()\n\n    def _on_badge_edit(self, criterion: FilterCriterion) -&gt; None:\n        self._editing_criterion = criterion\n        self._dropdown.open_for_edit(criterion, self)\n\n    def _on_badge_remove(self, criterion: FilterCriterion) -&gt; None:\n        self._criteria = [c for c in self._criteria if c is not criterion]\n        self._rebuild_bar()\n        self._update_proxy()\n\n    def _update_proxy(self) -&gt; None:\n        self._proxy.set_criteria(self._criteria, self._model.columns)\n        self.filters_changed.emit(list(self._criteria))\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_filter.html#client.ayon_ui_qt.components.table_filter.AYTableFilter.filter_model","title":"<code>filter_model</code>  <code>property</code>","text":"<p>Return the proxy model to set on the view.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/table_filter.html#client.ayon_ui_qt.components.table_filter.AYTableFilterProxyModel","title":"<code>AYTableFilterProxyModel</code>","text":"<p>               Bases: <code>QSortFilterProxyModel</code></p> <p>Proxy model that filters rows using a list of FilterCriterion.</p> <p>All criteria are combined with AND; values within a single criterion are combined with OR.  When no criteria are set every row passes.</p> Source code in <code>client/ayon_ui_qt/components/table_filter.py</code> <pre><code>class AYTableFilterProxyModel(QSortFilterProxyModel):\n    \"\"\"Proxy model that filters rows using a list of FilterCriterion.\n\n    All criteria are combined with AND; values within a single criterion\n    are combined with OR.  When no criteria are set every row passes.\n    \"\"\"\n\n    def __init__(self, parent: QWidget | None = None) -&gt; None:\n        super().__init__(parent)\n        self._criteria: list[FilterCriterion] = []\n        self._columns: list[TableColumn] = []\n        self._key_to_col: dict[str, int] = {}\n        self.setFilterCaseSensitivity(Qt.CaseSensitivity.CaseInsensitive)\n\n    def set_criteria(\n        self,\n        criteria: list[FilterCriterion],\n        columns: list[TableColumn],\n    ) -&gt; None:\n        \"\"\"Replace active criteria and refresh the filter.\n\n        Args:\n            criteria: List of active filter criteria.\n            columns: Column definitions from the source model.\n        \"\"\"\n        self._criteria = [c for c in criteria if c.values]\n        self._columns = columns\n        self._key_to_col = {col.key: idx for idx, col in enumerate(columns)}\n        self.invalidateFilter()\n\n    def _direct_match(\n        self,\n        source_row: int,\n        source_parent: QModelIndex | QPersistentModelIndex,\n    ) -&gt; bool:\n        \"\"\"Return True if a single row satisfies every active criterion.\n\n        Args:\n            source_row: Row number in the source model.\n            source_parent: Parent index in the source model.\n\n        Returns:\n            ``True`` when all criteria are satisfied (AND logic).\n        \"\"\"\n        if not self._criteria:\n            return True\n\n        source_model = self.sourceModel()\n        if source_model is None:\n            return True\n\n        for criterion in self._criteria:\n            if not criterion.values:\n                continue\n            col_idx = self._key_to_col.get(criterion.key)\n            if col_idx is None:\n                continue\n            index = source_model.index(source_row, col_idx, source_parent)\n            cell_value = source_model.data(index, Qt.ItemDataRole.DisplayRole)\n            cell_str = str(cell_value).lower() if cell_value else \"\"\n\n            matched = False\n            for val in criterion.values:\n                val_lower = val.lower()\n                if criterion.use_substring:\n                    if val_lower in cell_str:\n                        matched = True\n                        break\n                else:\n                    if cell_str == val_lower:\n                        matched = True\n                        break\n            if not matched:\n                return False\n\n        return True\n\n    def filterAcceptsRow(  # noqa: N802\n        self,\n        source_row: int,\n        source_parent: QModelIndex | QPersistentModelIndex,\n    ) -&gt; bool:\n        \"\"\"Return True if the row (or any of its loaded children) matches.\n\n        In flat mode the recursive child check is a no-op because leaf\n        nodes have ``rowCount() == 0``.  In tree mode parent folders are\n        kept visible as long as at least one loaded descendant passes the\n        criteria, preserving the tree structure.\n\n        Args:\n            source_row: Row number in the source model.\n            source_parent: Parent index in the source model.\n\n        Returns:\n            ``True`` when the row or a descendant satisfies all criteria.\n        \"\"\"\n        if not self._criteria:\n            return True\n\n        # Tentatively accept tree-mode folder nodes whose children haven't\n        # been fetched yet. We can't know whether any descendant will match\n        # until the children are loaded. PaginatedTableModel emits dataChanged\n        # for the node once its children are loaded, which causes this method\n        # to be called again with real data to decide.\n        source_model = self.sourceModel()\n        if (\n            isinstance(source_model, PaginatedTableModel)\n            and source_model._tree_mode\n        ):\n            src_idx = source_model.index(source_row, 0, source_parent)\n            node = src_idx.internalPointer()\n            if (\n                node is not None\n                and node.row_has_children\n                and not node.children_loaded\n            ):\n                return True\n\n        if self._direct_match(source_row, source_parent):\n            return True\n\n        # Tree hierarchy: keep parent visible if any loaded child matches.\n        if source_model is None:\n            return False\n        source_index = source_model.index(source_row, 0, source_parent)\n        for child_row in range(source_model.rowCount(source_index)):\n            if self.filterAcceptsRow(child_row, source_index):\n                return True\n\n        return False\n\n    def refresh_filter(self) -&gt; None:\n        \"\"\"Re-apply the current filter criteria (e.g. after source data changes).\"\"\"\n        self.invalidateFilter()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_filter.html#client.ayon_ui_qt.components.table_filter.AYTableFilterProxyModel.filterAcceptsRow","title":"<code>filterAcceptsRow(source_row, source_parent)</code>","text":"<p>Return True if the row (or any of its loaded children) matches.</p> <p>In flat mode the recursive child check is a no-op because leaf nodes have <code>rowCount() == 0</code>.  In tree mode parent folders are kept visible as long as at least one loaded descendant passes the criteria, preserving the tree structure.</p> <p>Parameters:</p> Name Type Description Default <code>source_row</code> <code>int</code> <p>Row number in the source model.</p> required <code>source_parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Parent index in the source model.</p> required <p>Returns:</p> Type Description <code>bool</code> <p><code>True</code> when the row or a descendant satisfies all criteria.</p> Source code in <code>client/ayon_ui_qt/components/table_filter.py</code> <pre><code>def filterAcceptsRow(  # noqa: N802\n    self,\n    source_row: int,\n    source_parent: QModelIndex | QPersistentModelIndex,\n) -&gt; bool:\n    \"\"\"Return True if the row (or any of its loaded children) matches.\n\n    In flat mode the recursive child check is a no-op because leaf\n    nodes have ``rowCount() == 0``.  In tree mode parent folders are\n    kept visible as long as at least one loaded descendant passes the\n    criteria, preserving the tree structure.\n\n    Args:\n        source_row: Row number in the source model.\n        source_parent: Parent index in the source model.\n\n    Returns:\n        ``True`` when the row or a descendant satisfies all criteria.\n    \"\"\"\n    if not self._criteria:\n        return True\n\n    # Tentatively accept tree-mode folder nodes whose children haven't\n    # been fetched yet. We can't know whether any descendant will match\n    # until the children are loaded. PaginatedTableModel emits dataChanged\n    # for the node once its children are loaded, which causes this method\n    # to be called again with real data to decide.\n    source_model = self.sourceModel()\n    if (\n        isinstance(source_model, PaginatedTableModel)\n        and source_model._tree_mode\n    ):\n        src_idx = source_model.index(source_row, 0, source_parent)\n        node = src_idx.internalPointer()\n        if (\n            node is not None\n            and node.row_has_children\n            and not node.children_loaded\n        ):\n            return True\n\n    if self._direct_match(source_row, source_parent):\n        return True\n\n    # Tree hierarchy: keep parent visible if any loaded child matches.\n    if source_model is None:\n        return False\n    source_index = source_model.index(source_row, 0, source_parent)\n    for child_row in range(source_model.rowCount(source_index)):\n        if self.filterAcceptsRow(child_row, source_index):\n            return True\n\n    return False\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_filter.html#client.ayon_ui_qt.components.table_filter.AYTableFilterProxyModel.refresh_filter","title":"<code>refresh_filter()</code>","text":"<p>Re-apply the current filter criteria (e.g. after source data changes).</p> Source code in <code>client/ayon_ui_qt/components/table_filter.py</code> <pre><code>def refresh_filter(self) -&gt; None:\n    \"\"\"Re-apply the current filter criteria (e.g. after source data changes).\"\"\"\n    self.invalidateFilter()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_filter.html#client.ayon_ui_qt.components.table_filter.AYTableFilterProxyModel.set_criteria","title":"<code>set_criteria(criteria, columns)</code>","text":"<p>Replace active criteria and refresh the filter.</p> <p>Parameters:</p> Name Type Description Default <code>criteria</code> <code>list[FilterCriterion]</code> <p>List of active filter criteria.</p> required <code>columns</code> <code>list[TableColumn]</code> <p>Column definitions from the source model.</p> required Source code in <code>client/ayon_ui_qt/components/table_filter.py</code> <pre><code>def set_criteria(\n    self,\n    criteria: list[FilterCriterion],\n    columns: list[TableColumn],\n) -&gt; None:\n    \"\"\"Replace active criteria and refresh the filter.\n\n    Args:\n        criteria: List of active filter criteria.\n        columns: Column definitions from the source model.\n    \"\"\"\n    self._criteria = [c for c in criteria if c.values]\n    self._columns = columns\n    self._key_to_col = {col.key: idx for idx, col in enumerate(columns)}\n    self.invalidateFilter()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_filter.html#client.ayon_ui_qt.components.table_filter.FilterCriterion","title":"<code>FilterCriterion</code>  <code>dataclass</code>","text":"<p>A single active filter criterion.</p> <p>Attributes:</p> Name Type Description <code>key</code> <code>str</code> <p>Column key this criterion applies to.</p> <code>attribute_label</code> <code>str</code> <p>Human-readable label for the column.</p> <code>values</code> <code>list[str]</code> <p>List of accepted values (OR logic within criterion).</p> <code>use_substring</code> <code>bool</code> <p>When True use case-insensitive substring matching; False uses exact match (used for enum columns).</p> Source code in <code>client/ayon_ui_qt/components/table_filter.py</code> <pre><code>@dataclass\nclass FilterCriterion:\n    \"\"\"A single active filter criterion.\n\n    Attributes:\n        key: Column key this criterion applies to.\n        attribute_label: Human-readable label for the column.\n        values: List of accepted values (OR logic within criterion).\n        use_substring: When True use case-insensitive substring matching;\n            False uses exact match (used for enum columns).\n    \"\"\"\n\n    key: str\n    attribute_label: str\n    values: list[str] = field(default_factory=list)\n    use_substring: bool = False\n    exclude: bool = False\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html","title":"table_model","text":"<p>Paginated Qt table model with lazy loading support.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model--tree-mode-batch-fetching","title":"Tree-mode batch fetching","text":"<p>When a subtree is expanded, Qt calls <code>fetchMore()</code> for every child node that declares <code>has_children=True</code>.  Those calls all arrive in the same event-loop tick.  Without batching each call produces a separate async task and therefore a separate server round-trip.</p> <p>Supply the optional fetch_page_batch callback to collapse all of those calls into a single round-trip::</p> <pre><code>def fetch_batch(\n    requests: list[BatchFetchRequest],\n) -&gt; dict[str | None, list[dict]]:\n    # One HTTP call for all parent_ids in the batch.\n    ...\n</code></pre> <p>The model accumulates pending fetch requests during an event-loop tick, dispatches them as one :class:<code>AsyncTask</code> via a zero-delay <code>QTimer.singleShot(0)</code>, and fans out the results to the per-node <code>_on_page_ready</code> handler when they arrive.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.BatchFetchRequest","title":"<code>BatchFetchRequest</code>  <code>dataclass</code>","text":"<p>Describes a single child-page request within a batch fetch call.</p> <p>A list of these is passed to the optional fetch_page_batch callback of :class:<code>PaginatedTableModel</code>.  Each entry corresponds to one node whose children need to be fetched; the callback should return a dict mapping each <code>parent_id</code> to its list of row dicts.</p> <p>Attributes:</p> Name Type Description <code>page</code> <code>int</code> <p>Page number (0-based).</p> <code>page_size</code> <code>int</code> <p>Maximum number of rows to return.</p> <code>sort_key</code> <code>str | None</code> <p>Column key for server-side sorting, or <code>None</code>.</p> <code>descending</code> <code>bool</code> <p><code>True</code> for descending sort order.</p> <code>parent_id</code> <code>str | None</code> <p>The <code>\"id\"</code> value of the parent row, or <code>None</code> for the invisible root (never used in batch - root is always fetched individually).</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>@dataclass\nclass BatchFetchRequest:\n    \"\"\"Describes a single child-page request within a batch fetch call.\n\n    A list of these is passed to the optional *fetch_page_batch* callback\n    of :class:`PaginatedTableModel`.  Each entry corresponds to one node\n    whose children need to be fetched; the callback should return a dict\n    mapping each ``parent_id`` to its list of row dicts.\n\n    Attributes:\n        page: Page number (0-based).\n        page_size: Maximum number of rows to return.\n        sort_key: Column key for server-side sorting, or ``None``.\n        descending: ``True`` for descending sort order.\n        parent_id: The ``\"id\"`` value of the parent row, or ``None`` for\n            the invisible root (never used in batch - root is always\n            fetched individually).\n    \"\"\"\n\n    page: int\n    page_size: int\n    sort_key: str | None\n    descending: bool\n    parent_id: str | None\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel","title":"<code>PaginatedTableModel</code>","text":"<p>               Bases: <code>QAbstractItemModel</code></p> <p>A Qt model that lazily loads rows page-by-page via a callback.</p> <p>Rows are fetched on demand using Qt's canFetchMore / fetchMore mechanism.  Each call to fetchMore retrieves one page of data from the supplied <code>fetch_page</code> callable.</p> <p>In flat mode (default) the model behaves like a plain table: no disclosure triangles, no nesting.  In tree mode rows whose dict contains <code>\"has_children\": True</code> become expandable folders; expanding them triggers a fresh <code>fetch_page</code> call with the folder's <code>\"id\"</code> value passed as <code>parent_id</code>.</p> <p>Batch fetching (tree mode only): when fetch_page_batch is supplied, all <code>fetchMore()</code> calls that arrive in the same event-loop tick (e.g. Qt calling <code>fetchMore</code> for every child of a just-expanded folder) are coalesced into a single :class:<code>BatchFetchRequest</code> list and dispatched as one async task. This reduces N sibling fetches from N server round-trips to one.</p> <p>Parameters:</p> Name Type Description Default <code>fetch_page</code> <code>Callable[[int, int, str | None, bool, str | None], list[dict[str, Any]]]</code> <p>Callable with signature <code>(page, page_size, sort_key, descending, parent_id) -&gt; list[dict]</code>.  <code>parent_id</code> is <code>None</code> for root-level items and the row's <code>\"id\"</code> value for nested items.</p> required <code>fetch_page_batch</code> <code>Callable[[list[BatchFetchRequest]], dict[str | None, list[dict[str, Any]]]] | None</code> <p>Optional callable with signature <code>(requests: list[BatchFetchRequest]) -&gt; dict[parent_id, list[dict]]</code>.  When supplied, tree-mode child fetches are batched into a single call per event-loop tick instead of one call per node.  The root-level fetch always uses fetch_page and is never batched.</p> <code>None</code> <code>columns</code> <code>list[TableColumn] | None</code> <p>Column definitions.  When <code>None</code>, columns are inferred from the keys of the first fetched row.</p> <code>None</code> <code>page_size</code> <code>int</code> <p>Number of rows per page.</p> <code>50</code> <code>no_async</code> <code>bool</code> <p>When <code>True</code>, pages are fetched synchronously on the main thread instead of via the :class:<code>AsyncTaskQueue</code>. Useful in tests to avoid worker-thread/paint-event races.</p> <code>False</code> <code>parent</code> <code>QObject | None</code> <p>Optional parent QObject.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>class PaginatedTableModel(QAbstractItemModel):\n    \"\"\"A Qt model that lazily loads rows page-by-page via a callback.\n\n    Rows are fetched on demand using Qt's canFetchMore / fetchMore\n    mechanism.  Each call to fetchMore retrieves one page of data from\n    the supplied ``fetch_page`` callable.\n\n    In **flat mode** (default) the model behaves like a plain table:\n    no disclosure triangles, no nesting.  In **tree mode** rows whose\n    dict contains ``\"has_children\": True`` become expandable folders;\n    expanding them triggers a fresh ``fetch_page`` call with the\n    folder's ``\"id\"`` value passed as ``parent_id``.\n\n    **Batch fetching** (tree mode only): when *fetch_page_batch* is\n    supplied, all ``fetchMore()`` calls that arrive in the same\n    event-loop tick (e.g. Qt calling ``fetchMore`` for every child of a\n    just-expanded folder) are coalesced into a single\n    :class:`BatchFetchRequest` list and dispatched as one async task.\n    This reduces N sibling fetches from N server round-trips to one.\n\n    Args:\n        fetch_page: Callable with signature\n            ``(page, page_size, sort_key, descending, parent_id) -&gt;\n            list[dict]``.  ``parent_id`` is ``None`` for root-level\n            items and the row's ``\"id\"`` value for nested items.\n        fetch_page_batch: Optional callable with signature\n            ``(requests: list[BatchFetchRequest]) -&gt;\n            dict[parent_id, list[dict]]``.  When supplied, tree-mode\n            child fetches are batched into a single call per event-loop\n            tick instead of one call per node.  The root-level fetch\n            always uses *fetch_page* and is never batched.\n        columns: Column definitions.  When ``None``, columns are inferred\n            from the keys of the first fetched row.\n        page_size: Number of rows per page.\n        no_async: When ``True``, pages are fetched synchronously on the\n            main thread instead of via the :class:`AsyncTaskQueue`.\n            Useful in tests to avoid worker-thread/paint-event races.\n        parent: Optional parent QObject.\n    \"\"\"\n\n    tree_mode_changed = Signal(bool)\n    loading_changed = Signal(bool)  # True while any fetch is in-flight\n    page_fetched = Signal(int, int)  # (page_number, total_root_rows_loaded)\n    fetch_error = Signal(str)  # error message when a fetch fails\n    pending_count_changed = Signal(int)  # number of in-flight fetch tasks\n\n    def __init__(\n        self,\n        fetch_page: Callable[\n            [int, int, str | None, bool, str | None], list[dict[str, Any]]\n        ],\n        fetch_page_batch: (\n            Callable[\n                [list[BatchFetchRequest]],\n                dict[str | None, list[dict[str, Any]]],\n            ]\n            | None\n        ) = None,\n        columns: list[TableColumn] | None = None,\n        page_size: int = 50,\n        no_async: bool = False,\n        parent: QObject | None = None,\n    ) -&gt; None:\n        \"\"\"Initialise the model and fetch the first page.\n\n        Args:\n            fetch_page: Callable\n                ``(page, page_size, sort_key, descending, parent_id)\n                -&gt; list[dict]``.\n            fetch_page_batch: Optional batch callable\n                ``(requests: list[BatchFetchRequest]) -&gt;\n                dict[parent_id, list[dict]]``.  When provided, non-root\n                child fetches are coalesced per event-loop tick.\n            columns: Explicit column definitions, or ``None`` to infer.\n            page_size: Rows per page.\n            no_async: When ``True``, fetch pages synchronously on the\n                calling thread instead of via the AsyncTaskQueue worker.\n                Useful in tests to avoid worker-thread/paint-event races.\n            parent: Parent QObject.\n        \"\"\"\n        super().__init__(parent)\n        self._fetch_page = fetch_page\n        self._fetch_page_batch: (\n            Callable[\n                [list[BatchFetchRequest]],\n                dict[str | None, list[dict[str, Any]]],\n            ]\n            | None\n        ) = fetch_page_batch\n        self._explicit_columns: list[TableColumn] | None = columns\n        self._columns: list[TableColumn] = columns or []\n        self._page_size: int = page_size\n        self._sort_column: int = -1\n        self._sort_order: Qt.SortOrder = Qt.SortOrder.AscendingOrder\n        self._tree_mode: bool = False\n        self._tree_position: int = -1\n\n        # Internal node tree.  _all_nodes prevents Python GC from collecting\n        # nodes that are held only via QModelIndex.internalPointer().\n        self._root: _TableNode = _TableNode(\n            node_id=None, row_data={}, parent=None\n        )\n        self._all_nodes: set[_TableNode] = {self._root}\n\n        # Async fetch state\n        self._no_async: bool = no_async\n        self._request_id: str = self._generate_request_id()\n        self._pending_tasks: int = 0\n\n        # Batch-fetch coalescing state (populated by _fetch_next_page when\n        # _fetch_page_batch is set, consumed by _dispatch_batch).\n        self._pending_batch_nodes: list[_TableNode] = []\n        self._batch_scheduled: bool = False\n\n        self._fetch_next_page(self._root)\n\n    # Properties --------------------------------------------------------------\n\n    @property\n    def columns(self) -&gt; list[TableColumn]:\n        \"\"\"Return the current column definitions.\n\n        Returns:\n            List of TableColumn instances.\n        \"\"\"\n        return list(self._columns)\n\n    @property\n    def page_count(self) -&gt; int:\n        \"\"\"Return the number of root pages fetched so far.\n\n        Returns:\n            Current root page index.\n        \"\"\"\n        return self._root.current_page\n\n    @property\n    def is_loading(self) -&gt; bool:\n        \"\"\"Return True while at least one fetch task is in-flight.\n\n        Returns:\n            True if any page fetch is currently pending or running.\n        \"\"\"\n        return self._pending_tasks &gt; 0\n\n    @property\n    def tree_position(self) -&gt; int:\n        \"\"\"Return the current tree column index, or 0 if tree mode is off.\"\"\"\n        if self._tree_position == -1:\n            self._tree_position = 0\n            for i, col in enumerate(self._columns):\n                if col.tree_position:\n                    self._tree_position = i\n                    break\n        return self._tree_position if self._tree_mode else 0\n\n    # QAbstractItemModel interface --------------------------------------------\n\n    def index(  # noqa: N802\n        self,\n        row: int,\n        column: int,\n        parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n    ) -&gt; QModelIndex:\n        \"\"\"Return a model index for row/column under parent.\n\n        Args:\n            row: Row number under parent.\n            column: Column number.\n            parent: Parent index (invalid = root).\n\n        Returns:\n            Valid QModelIndex, or invalid if out of range.\n        \"\"\"\n        if not self.hasIndex(row, column, parent):\n            return QModelIndex()\n        parent_node = self._node_from_index(parent)\n        if row &gt;= len(parent_node.children):\n            return QModelIndex()\n        return self.createIndex(row, column, parent_node.children[row])\n\n    def parent(  # type: ignore[override]\n        self,\n        index: QModelIndex | QPersistentModelIndex,\n    ) -&gt; QModelIndex:\n        \"\"\"Return the parent index of the given index.\n\n        Args:\n            index: Child index.\n\n        Returns:\n            Parent QModelIndex, or invalid for root-level items.\n        \"\"\"\n        if not index.isValid():\n            return QModelIndex()\n        node: _TableNode = index.internalPointer()  # type: ignore[assignment]\n        parent_node = node.parent\n        if parent_node is None or parent_node.is_root:\n            return QModelIndex()\n        grandparent = parent_node.parent\n        row = grandparent.children.index(parent_node)  # type: ignore[union-attr]\n        return self.createIndex(row, 0, parent_node)\n\n    def rowCount(  # noqa: N802\n        self,\n        parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n    ) -&gt; int:\n        \"\"\"Return the number of loaded children under parent.\n\n        Args:\n            parent: Parent index (invalid = root).\n\n        Returns:\n            Number of loaded child rows.\n        \"\"\"\n        if parent.column() &gt; 0:\n            return 0\n        return len(self._node_from_index(parent).children)\n\n    def columnCount(  # noqa: N802\n        self,\n        parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n    ) -&gt; int:\n        \"\"\"Return the number of columns.\n\n        Args:\n            parent: Unused; column count is the same for all nodes.\n\n        Returns:\n            Number of columns.\n        \"\"\"\n        return len(self._columns)\n\n    def hasChildren(  # noqa: N802\n        self,\n        parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n    ) -&gt; bool:\n        \"\"\"Return whether the node at parent has or can have children.\n\n        Controls whether Qt draws a disclosure triangle even before\n        children are loaded.\n\n        Args:\n            parent: Parent index (invalid = root).\n\n        Returns:\n            True if the node has loaded children, has more pages, or\n            (in tree mode only) the row data declares ``has_children``.\n        \"\"\"\n        node = self._node_from_index(parent)\n        if node.is_root:\n            return bool(node.children) or node.has_more\n        if not self._tree_mode:\n            return False\n        if node.children_loaded:\n            return bool(node.children)\n        return node.row_has_children\n\n    def canFetchMore(  # noqa: N802\n        self,\n        parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n    ) -&gt; bool:\n        \"\"\"Return whether more rows can be fetched for parent.\n\n        Args:\n            parent: Parent index (invalid = root).\n\n        Returns:\n            ``True`` when more pages are available for this node.\n        \"\"\"\n        node = self._node_from_index(parent)\n        if node.is_root:\n            return node.has_more\n        if not self._tree_mode:\n            return False\n        if not node.row_has_children:\n            return False\n        if not node.children_loaded:\n            return True\n        return node.has_more\n\n    def fetchMore(  # noqa: N802\n        self,\n        parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n    ) -&gt; None:\n        \"\"\"Fetch the next page of rows for parent.\n\n        Args:\n            parent: Parent index (invalid = root).\n        \"\"\"\n        self._fetch_next_page(self._node_from_index(parent))\n\n    def data(\n        self,\n        index: QModelIndex | QPersistentModelIndex,\n        role: int = Qt.ItemDataRole.DisplayRole,\n    ) -&gt; Any:\n        \"\"\"Return data for the given index and role.\n\n        Args:\n            index: Model index identifying the cell.\n            role: Qt item data role.\n\n        Returns:\n            Cell value appropriate for the requested role, or ``None``.\n        \"\"\"\n        if not index.isValid():\n            return None\n        node: _TableNode | None = index.internalPointer()  # type: ignore[assignment]\n        if node is None:\n            return None\n        col = index.column()\n        if col &lt; 0 or col &gt;= len(self._columns):\n            return None\n\n        row_dict = node.row_data\n        col_key = self._columns[col].key\n\n        if role == Qt.ItemDataRole.DisplayRole:\n            value = row_dict.get(col_key)\n            if value is None:\n                return \"\"\n            return str(value)\n\n        if role == Qt.ItemDataRole.DecorationRole:\n            icon_key = f\"{col_key}__icon\"\n            icon_name = row_dict.get(icon_key)\n            if icon_name:\n                icon_color = row_dict.get(f\"{col_key}__color\", \"#ffffff\")\n                icon_fill = row_dict.get(f\"{col_key}__icon_fill\", False)\n                return get_icon(icon_name, color=icon_color, fill=icon_fill)\n            return None\n\n        if role == Qt.ItemDataRole.ForegroundRole:\n            color_key = f\"{col_key}__color\"\n            color = row_dict.get(color_key)\n            if isinstance(color, str):\n                return QBrush(QColor(color))\n            return None\n\n        if role == Qt.ItemDataRole.UserRole:\n            return row_dict\n\n        return None\n\n    def headerData(  # noqa: N802\n        self,\n        section: int,\n        orientation: Qt.Orientation,\n        role: int = Qt.ItemDataRole.DisplayRole,\n    ) -&gt; Any:\n        \"\"\"Return header data for the given section and orientation.\n\n        Args:\n            section: Column (horizontal) or row (vertical) index.\n            orientation: Header orientation.\n            role: Qt item data role.\n\n        Returns:\n            Column label for horizontal DisplayRole, otherwise ``None``.\n        \"\"\"\n        if (\n            orientation == Qt.Orientation.Horizontal\n            and role == Qt.ItemDataRole.DisplayRole\n        ):\n            if 0 &lt;= section &lt; len(self._columns):\n                return self._columns[section].label\n        return None\n\n    def sort(\n        self, column: int, order: Qt.SortOrder = Qt.SortOrder.AscendingOrder\n    ) -&gt; None:\n        \"\"\"Set the active sort column and order, then reload data.\n\n        Sorting always resets from page 0 at all levels.\n\n        Args:\n            column: Zero-based index of the column to sort by. If out of\n                range, the call is ignored.\n            order: Sort order (ascending or descending).\n        \"\"\"\n        if column &lt; 0 or column &gt;= len(self._columns):\n            return\n        self._sort_column = column\n        self._sort_order = order\n        self.reset_data()  # refetch page 0 using new sort\n\n    # Public interface --------------------------------------------------------\n\n    def set_tree_mode(self, enabled: bool) -&gt; None:\n        \"\"\"Switch between flat table mode and hierarchical tree mode.\n\n        Emits ``tree_mode_changed`` and reloads from page 0.\n\n        Args:\n            enabled: ``True`` to enable tree mode, ``False`` for flat.\n        \"\"\"\n        if self._tree_mode == enabled:\n            return\n        self._tree_mode = enabled\n        self.tree_mode_changed.emit(enabled)\n        self.reset_data()\n\n    def set_page(self, page: int) -&gt; None:\n        \"\"\"Reset the model and begin fetching from the given page.\n\n        Args:\n            page: 0-based page number to start from.\n        \"\"\"\n        old_request_id = self._request_id\n        if not self._no_async:\n            get_task_queue().clear_context_tasks(old_request_id)\n        self._request_id = self._generate_request_id()\n        self._pending_tasks = 0\n        self._pending_batch_nodes = []\n        self._batch_scheduled = False\n        self.beginResetModel()\n        self._root = _TableNode(node_id=None, row_data={}, parent=None)\n        self._root.current_page = page\n        self._all_nodes = {self._root}\n        self._columns = self._explicit_columns or []\n        self.endResetModel()\n        # Emit loading signals *after* endResetModel so that any slot\n        # connected to loading_changed observes a consistent model state.\n        self._update_loading_state()\n        self._fetch_next_page(self._root)\n\n    def set_page_size(self, size: int) -&gt; None:\n        \"\"\"Update the page size and reset the model from page 0.\n\n        Args:\n            size: New page size (rows per page).\n        \"\"\"\n        self._page_size = size\n        self.reset_data()\n\n    def set_columns(self, columns: list[TableColumn]) -&gt; None:\n        \"\"\"Set the columns and reset the model from page 0.\n\n        Args:\n            columns: List of columns to display.\n        \"\"\"\n        self._explicit_columns = columns\n        self.reset_data()\n\n    def reset_data(self) -&gt; None:\n        \"\"\"Reset the model and re-fetch from page 0.\"\"\"\n        old_request_id = self._request_id\n        if not self._no_async:\n            get_task_queue().clear_context_tasks(old_request_id)\n        self._request_id = self._generate_request_id()\n        self._pending_tasks = 0\n        self._pending_batch_nodes = []\n        self._batch_scheduled = False\n        self.beginResetModel()\n        self._root = _TableNode(node_id=None, row_data={}, parent=None)\n        self._all_nodes = {self._root}\n        self._columns = self._explicit_columns or []\n        self.endResetModel()\n        # Emit loading signals *after* endResetModel so that any slot\n        # connected to loading_changed observes a consistent model state.\n        self._update_loading_state()\n        self._fetch_next_page(self._root)\n\n    def get_distinct_values(self, key: str) -&gt; list[str]:\n        \"\"\"Return sorted distinct non-empty string values for a column.\n\n        In flat mode scans root-level rows; in tree mode scans all\n        loaded nodes across all levels.\n\n        Args:\n            key: Column key to inspect.\n\n        Returns:\n            Sorted list of unique string values found in loaded rows.\n        \"\"\"\n        seen: set[str] = set()\n        nodes = (\n            self._all_nodes if self._tree_mode else set(self._root.children)\n        )\n        for node in nodes:\n            if node.is_root:\n                continue\n            val = node.row_data.get(key)\n            if val is not None:\n                s = str(val).strip()\n                if s:\n                    seen.add(s)\n        return sorted(seen)\n\n    # Internal helpers --------------------------------------------------------\n\n    def _node_from_index(\n        self, index: QModelIndex | QPersistentModelIndex\n    ) -&gt; _TableNode:\n        \"\"\"Return the internal node for a model index.\n\n        Args:\n            index: A valid or invalid QModelIndex.\n\n        Returns:\n            The corresponding _TableNode; returns root for invalid\n            indexes.\n        \"\"\"\n        if not index.isValid():\n            return self._root\n        return index.internalPointer()  # type: ignore[return-value]\n\n    @staticmethod\n    def _generate_request_id() -&gt; str:\n        \"\"\"Return a unique request identifier for task-queue scoping.\"\"\"\n        return str(uuid.uuid1())\n\n    def _index_for_node(self, node: _TableNode) -&gt; QModelIndex:\n        \"\"\"Return the QModelIndex that identifies node (column 0).\n\n        Args:\n            node: A non-root table node.\n\n        Returns:\n            Valid QModelIndex for non-root nodes, invalid for root.\n        \"\"\"\n        if node.is_root:\n            return QModelIndex()\n        parent = node.parent\n        row = parent.children.index(node)  # type: ignore[union-attr]\n        return self.createIndex(row, 0, node)\n\n    def _update_loading_state(self) -&gt; None:\n        \"\"\"Emit loading-progress signals based on current pending task count.\"\"\"\n        self.pending_count_changed.emit(self._pending_tasks)\n        self.loading_changed.emit(self._pending_tasks &gt; 0)\n\n    def _on_page_ready(\n        self,\n        node: _TableNode,\n        request_id: str,\n        results: list[dict[str, Any]] | None,\n    ) -&gt; None:\n        \"\"\"Handle fetch results on the main thread.\n\n        Called via Qt.QueuedConnection from AsyncTaskQueue so it always\n        executes on the Qt main thread, making it safe to call Qt model\n        mutation methods.\n\n        Args:\n            node: The node whose page was fetched.\n            request_id: The request id that was active when the task was\n                enqueued.  Used to discard stale results.\n            results: Row dicts returned by _fetch_page, or None on error.\n        \"\"\"\n        # Stale callback: release the guard and discard.\n        # Do NOT decrement _pending_tasks for stale callbacks \u2014 the\n        # reset_data() call already set the counter to 0 for the new\n        # context.  Decrementing here would corrupt the new context's count.\n        if request_id != self._request_id or node not in self._all_nodes:\n            # Always release the fetching guard so the node is never stuck\n            # in-flight, even for stale callbacks.\n            node.is_fetching = False\n            log.debug(\n                \"Discarding stale fetch result for node %r (request %s vs %s)\",\n                node.node_id,\n                request_id,\n                self._request_id,\n            )\n            return\n\n        # Confirmed current-context callback: update the in-flight counter.\n        # Keep is_fetching=True until ALL model mutations below are finished.\n        # endInsertRows() emits rowsInserted synchronously, which can cause\n        # Qt's tree-view slot to call canFetchMore/fetchMore re-entrantly.\n        # The guard must still be set at that point so _fetch_next_page\n        # returns immediately and avoids a recursive re-fetch of the same page.\n        self._pending_tasks = max(0, self._pending_tasks - 1)\n\n        _was_children_loaded = node.children_loaded\n\n        if results is None:\n            # Task failed \u2014 fetch_error already logged by AsyncTaskQueue.\n            self.fetch_error.emit(\n                f\"Failed to fetch page {node.current_page} \"\n                f\"(parent_id={node.node_id!r})\"\n            )\n            node.has_more = False\n            node.children_loaded = True\n            node.is_fetching = False\n            # Emit loading state after updating node state.\n            self._update_loading_state()\n            return\n\n        if not results:\n            node.has_more = False\n            node.children_loaded = True\n            node.is_fetching = False\n            self._update_loading_state()\n            return\n\n        if not self._columns and self._explicit_columns is None:\n            self._columns = self._infer_columns(results[0])\n\n        parent_index = self._index_for_node(node)\n        first_new = len(node.children)\n        last_new = first_new + len(results) - 1\n        self.beginInsertRows(parent_index, first_new, last_new)\n        for row_data in results:\n            child = _TableNode(\n                node_id=row_data.get(\"id\"),\n                row_data=row_data,\n                parent=node,\n            )\n            node.children.append(child)\n            self._all_nodes.add(child)\n        self.endInsertRows()\n\n        node.children_loaded = True\n        if len(results) &lt; self._page_size:\n            node.has_more = False\n\n        fetched_page = node.current_page\n        node.current_page += 1\n\n        # Release the re-entrancy guard now that all model mutations are done.\n        # Any canFetchMore/fetchMore calls that arrived re-entrantly during\n        # endInsertRows were blocked by is_fetching=True; they can now proceed\n        # on the next event-loop iteration if the node still has more pages.\n        node.is_fetching = False\n\n        # Emit loading-state signals AFTER rows are in the model so that\n        # any slot reacting to is_loading=False already sees the new rows.\n        self._update_loading_state()\n        self.page_fetched.emit(fetched_page, len(self._root.children))\n\n        # On the first child-load for a non-root node, emit dataChanged so\n        # proxy models (e.g. AYTableFilterProxyModel) re-evaluate this row's\n        # filter status now that real children are available.\n        if (\n            not node.is_root\n            and not _was_children_loaded\n            and node.children_loaded\n        ):\n            idx = self._index_for_node(node)\n            self.dataChanged.emit(idx, idx)\n\n    def _get_fetch_priority(self, node: _TableNode, page: int) -&gt; int:\n        \"\"\"Return the async-task priority for a child-page fetch.\n\n        The default implementation uses priority **1** (High) for the\n        very first page of any node and **2** (Normal) for subsequent\n        pages.  Subclasses may override this method to implement dynamic\n        priority logic \u2014 for example, lowering the priority to **20**\n        (Background prefetch) when the parent node's row is not currently\n        visible in the table's viewport.\n\n        Priority scale (lower value = higher priority):\n\n        - ``0`` - Critical / visible first-page fetches\n        - ``1`` - High / visible subsequent-page fetches\n        - ``2`` - Normal / thumbnail fetches\n        - ``20`` - Low / off-screen prefetch\n\n        Args:\n            node: The parent node whose children are being fetched.\n            page: Zero-based index of the page being requested.\n\n        Returns:\n            Integer task priority passed to\n            :class:`~ayon_ui_qt.components.task_queue.AsyncTask`.\n        \"\"\"\n        return 1 if page == 0 else 2\n\n    def _fetch_next_page(self, node: _TableNode) -&gt; None:\n        \"\"\"Enqueue an async task to fetch the next page of children for *node*.\n\n        Uses a per-node re-entrancy guard (``node.is_fetching``) to\n        prevent duplicate tasks.  The actual data-fetch runs in the\n        shared :class:`AsyncTaskQueue` worker thread; results are\n        delivered back on the main thread via :meth:`_on_page_ready`.\n\n        When *fetch_page_batch* is configured and *node* is not the\n        invisible root, the node is added to ``_pending_batch_nodes`` and\n        a zero-delay timer schedules :meth:`_dispatch_batch`.  This\n        coalesces all sibling fetches that arrive in the same event-loop\n        tick into a single server call.\n\n        Priority is determined by :meth:`_get_fetch_priority`, which\n        defaults to 1 (High) for the first page and 2 (Normal) for\n        subsequent pages.  Subclasses may override\n        :meth:`_get_fetch_priority` to adjust priority dynamically.\n\n        Args:\n            node: The parent node whose next page of children to fetch.\n        \"\"\"\n        if node.is_fetching:\n            return\n        node.is_fetching = True\n\n        sort_key = None\n        if 0 &lt;= self._sort_column &lt; len(self._columns):\n            sort_key = self._columns[self._sort_column].key\n        descending = self._sort_order == Qt.SortOrder.DescendingOrder\n\n        page = node.current_page\n        page_size = self._page_size\n        node_id = node.node_id\n        request_id = self._request_id\n\n        priority = self._get_fetch_priority(node, page)\n\n        self._pending_tasks += 1\n        self._update_loading_state()\n\n        # Batch path: coalesce non-root child fetches when a batch\n        # callback is available.  The root is always fetched individually\n        # because it is the first call and nothing can be batched with it.\n        if self._fetch_page_batch is not None and not node.is_root:\n            self._pending_batch_nodes.append(node)\n            if not self._batch_scheduled:\n                self._batch_scheduled = True\n                QTimer.singleShot(0, self._dispatch_batch)\n            return\n\n        if self._no_async:\n            # Synchronous path: fetch inline and deliver result immediately.\n            # Used in tests to avoid cross-thread paint-event races.\n            try:\n                result = self._fetch_page(\n                    page, page_size, sort_key, descending, node_id\n                )\n            except Exception:\n                result = None\n            self._on_page_ready(node, request_id, result)\n            return\n\n        task = AsyncTask(\n            name=f\"fetch_page_{node_id or 'root'}_{page}\",\n            function=lambda: self._fetch_page(\n                page, page_size, sort_key, descending, node_id\n            ),\n            callback=lambda result: self._on_page_ready(\n                node, request_id, result\n            ),\n            priority=priority,\n            context_id=request_id,\n            cancellable=True,\n        )\n        get_task_queue().enqueue(task)\n\n    def _dispatch_batch(self) -&gt; None:\n        \"\"\"Dispatch all accumulated pending batch-fetch requests.\n\n        Called via ``QTimer.singleShot(0)`` so it runs on the main thread\n        at the start of the next event-loop iteration, after all\n        ``fetchMore()`` calls for the current expansion wave have been\n        collected into ``_pending_batch_nodes``.\n\n        The method creates one :class:`AsyncTask` (or runs synchronously\n        when ``no_async=True``) carrying all pending requests.  Results\n        are fanned out to the per-node ``_on_page_ready`` handler via\n        :meth:`_on_batch_ready`.\n        \"\"\"\n        self._batch_scheduled = False\n        nodes = list(self._pending_batch_nodes)\n        self._pending_batch_nodes = []\n\n        if not nodes:\n            return\n\n        sort_key = None\n        if 0 &lt;= self._sort_column &lt; len(self._columns):\n            sort_key = self._columns[self._sort_column].key\n        descending = self._sort_order == Qt.SortOrder.DescendingOrder\n        request_id = self._request_id\n\n        requests = [\n            BatchFetchRequest(\n                page=node.current_page,\n                page_size=self._page_size,\n                sort_key=sort_key,\n                descending=descending,\n                parent_id=node.node_id,\n            )\n            for node in nodes\n        ]\n\n        log.debug(\n            \"Dispatching batch of %d fetch requests (request=%s)\",\n            len(requests),\n            request_id,\n        )\n\n        assert self._fetch_page_batch is not None  # guarded by caller\n        batch_fn = self._fetch_page_batch\n\n        # Use the highest-urgency (lowest numeric) priority among the\n        # batched nodes so that a batch containing at least one visible\n        # node runs at visible priority rather than the default priority=1.\n        batch_priority = min(\n            self._get_fetch_priority(n, n.current_page) for n in nodes\n        )\n\n        if self._no_async:\n            try:\n                result: dict[str | None, list[dict[str, Any]]] | None = (\n                    batch_fn(requests)\n                )\n            except Exception:\n                log.exception(\"Batch fetch raised\")\n                result = None\n            self._on_batch_ready(nodes, request_id, result)\n            return\n\n        task = AsyncTask(\n            name=f\"fetch_batch_{len(nodes)}_nodes\",\n            function=lambda: batch_fn(requests),\n            callback=lambda res: self._on_batch_ready(nodes, request_id, res),\n            priority=batch_priority,\n            context_id=request_id,\n            cancellable=True,\n        )\n        get_task_queue().enqueue(task)\n\n    def _on_batch_ready(\n        self,\n        nodes: list[_TableNode],\n        request_id: str,\n        results: dict[str | None, list[dict[str, Any]]] | None,\n    ) -&gt; None:\n        \"\"\"Fan out batch results to per-node handlers.\n\n        Delegates each node's slice of the results to :meth:`_on_page_ready`\n        so that all existing insertion, loading-state, and dataChanged\n        logic is reused without duplication.\n\n        Args:\n            nodes: The nodes whose children were requested in the batch.\n            request_id: The request id active when the batch was dispatched.\n                Used to discard stale results.\n            results: Mapping of ``parent_id -&gt; list[row_dict]`` returned by\n                the batch callback, or ``None`` on error.\n        \"\"\"\n        for node in nodes:\n            node_results: list[dict[str, Any]] | None\n            if results is None:\n                node_results = None\n            else:\n                node_results = results.get(node.node_id, [])\n            self._on_page_ready(node, request_id, node_results)\n\n    @staticmethod\n    def _infer_columns(row: dict[str, Any]) -&gt; list[TableColumn]:\n        \"\"\"Infer column definitions from a sample row dictionary.\n\n        Reserved keys (``id``, ``has_children``) and decorator suffixes\n        (``__icon``, ``__color``, ``__fill``) are excluded.\n\n        Args:\n            row: A representative row dictionary.\n\n        Returns:\n            List of inferred TableColumn instances.\n        \"\"\"\n        columns: list[TableColumn] = []\n        for key in row:\n            if key in (\"id\", \"has_children\"):\n                continue\n            if key.endswith((\"__icon\", \"__color\", \"__fill\")):\n                continue\n            label = key.replace(\"_\", \" \").title()\n            columns.append(TableColumn(key=key, label=label))\n        return columns\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.columns","title":"<code>columns</code>  <code>property</code>","text":"<p>Return the current column definitions.</p> <p>Returns:</p> Type Description <code>list[TableColumn]</code> <p>List of TableColumn instances.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.is_loading","title":"<code>is_loading</code>  <code>property</code>","text":"<p>Return True while at least one fetch task is in-flight.</p> <p>Returns:</p> Type Description <code>bool</code> <p>True if any page fetch is currently pending or running.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.page_count","title":"<code>page_count</code>  <code>property</code>","text":"<p>Return the number of root pages fetched so far.</p> <p>Returns:</p> Type Description <code>int</code> <p>Current root page index.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.tree_position","title":"<code>tree_position</code>  <code>property</code>","text":"<p>Return the current tree column index, or 0 if tree mode is off.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.__init__","title":"<code>__init__(fetch_page, fetch_page_batch=None, columns=None, page_size=50, no_async=False, parent=None)</code>","text":"<p>Initialise the model and fetch the first page.</p> <p>Parameters:</p> Name Type Description Default <code>fetch_page</code> <code>Callable[[int, int, str | None, bool, str | None], list[dict[str, Any]]]</code> <p>Callable <code>(page, page_size, sort_key, descending, parent_id) -&gt; list[dict]</code>.</p> required <code>fetch_page_batch</code> <code>Callable[[list[BatchFetchRequest]], dict[str | None, list[dict[str, Any]]]] | None</code> <p>Optional batch callable <code>(requests: list[BatchFetchRequest]) -&gt; dict[parent_id, list[dict]]</code>.  When provided, non-root child fetches are coalesced per event-loop tick.</p> <code>None</code> <code>columns</code> <code>list[TableColumn] | None</code> <p>Explicit column definitions, or <code>None</code> to infer.</p> <code>None</code> <code>page_size</code> <code>int</code> <p>Rows per page.</p> <code>50</code> <code>no_async</code> <code>bool</code> <p>When <code>True</code>, fetch pages synchronously on the calling thread instead of via the AsyncTaskQueue worker. Useful in tests to avoid worker-thread/paint-event races.</p> <code>False</code> <code>parent</code> <code>QObject | None</code> <p>Parent QObject.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def __init__(\n    self,\n    fetch_page: Callable[\n        [int, int, str | None, bool, str | None], list[dict[str, Any]]\n    ],\n    fetch_page_batch: (\n        Callable[\n            [list[BatchFetchRequest]],\n            dict[str | None, list[dict[str, Any]]],\n        ]\n        | None\n    ) = None,\n    columns: list[TableColumn] | None = None,\n    page_size: int = 50,\n    no_async: bool = False,\n    parent: QObject | None = None,\n) -&gt; None:\n    \"\"\"Initialise the model and fetch the first page.\n\n    Args:\n        fetch_page: Callable\n            ``(page, page_size, sort_key, descending, parent_id)\n            -&gt; list[dict]``.\n        fetch_page_batch: Optional batch callable\n            ``(requests: list[BatchFetchRequest]) -&gt;\n            dict[parent_id, list[dict]]``.  When provided, non-root\n            child fetches are coalesced per event-loop tick.\n        columns: Explicit column definitions, or ``None`` to infer.\n        page_size: Rows per page.\n        no_async: When ``True``, fetch pages synchronously on the\n            calling thread instead of via the AsyncTaskQueue worker.\n            Useful in tests to avoid worker-thread/paint-event races.\n        parent: Parent QObject.\n    \"\"\"\n    super().__init__(parent)\n    self._fetch_page = fetch_page\n    self._fetch_page_batch: (\n        Callable[\n            [list[BatchFetchRequest]],\n            dict[str | None, list[dict[str, Any]]],\n        ]\n        | None\n    ) = fetch_page_batch\n    self._explicit_columns: list[TableColumn] | None = columns\n    self._columns: list[TableColumn] = columns or []\n    self._page_size: int = page_size\n    self._sort_column: int = -1\n    self._sort_order: Qt.SortOrder = Qt.SortOrder.AscendingOrder\n    self._tree_mode: bool = False\n    self._tree_position: int = -1\n\n    # Internal node tree.  _all_nodes prevents Python GC from collecting\n    # nodes that are held only via QModelIndex.internalPointer().\n    self._root: _TableNode = _TableNode(\n        node_id=None, row_data={}, parent=None\n    )\n    self._all_nodes: set[_TableNode] = {self._root}\n\n    # Async fetch state\n    self._no_async: bool = no_async\n    self._request_id: str = self._generate_request_id()\n    self._pending_tasks: int = 0\n\n    # Batch-fetch coalescing state (populated by _fetch_next_page when\n    # _fetch_page_batch is set, consumed by _dispatch_batch).\n    self._pending_batch_nodes: list[_TableNode] = []\n    self._batch_scheduled: bool = False\n\n    self._fetch_next_page(self._root)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.canFetchMore","title":"<code>canFetchMore(parent=QModelIndex())</code>","text":"<p>Return whether more rows can be fetched for parent.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Parent index (invalid = root).</p> <code>QModelIndex()</code> <p>Returns:</p> Type Description <code>bool</code> <p><code>True</code> when more pages are available for this node.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def canFetchMore(  # noqa: N802\n    self,\n    parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n) -&gt; bool:\n    \"\"\"Return whether more rows can be fetched for parent.\n\n    Args:\n        parent: Parent index (invalid = root).\n\n    Returns:\n        ``True`` when more pages are available for this node.\n    \"\"\"\n    node = self._node_from_index(parent)\n    if node.is_root:\n        return node.has_more\n    if not self._tree_mode:\n        return False\n    if not node.row_has_children:\n        return False\n    if not node.children_loaded:\n        return True\n    return node.has_more\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.columnCount","title":"<code>columnCount(parent=QModelIndex())</code>","text":"<p>Return the number of columns.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Unused; column count is the same for all nodes.</p> <code>QModelIndex()</code> <p>Returns:</p> Type Description <code>int</code> <p>Number of columns.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def columnCount(  # noqa: N802\n    self,\n    parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n) -&gt; int:\n    \"\"\"Return the number of columns.\n\n    Args:\n        parent: Unused; column count is the same for all nodes.\n\n    Returns:\n        Number of columns.\n    \"\"\"\n    return len(self._columns)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.data","title":"<code>data(index, role=Qt.ItemDataRole.DisplayRole)</code>","text":"<p>Return data for the given index and role.</p> <p>Parameters:</p> Name Type Description Default <code>index</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Model index identifying the cell.</p> required <code>role</code> <code>int</code> <p>Qt item data role.</p> <code>DisplayRole</code> <p>Returns:</p> Type Description <code>Any</code> <p>Cell value appropriate for the requested role, or <code>None</code>.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def data(\n    self,\n    index: QModelIndex | QPersistentModelIndex,\n    role: int = Qt.ItemDataRole.DisplayRole,\n) -&gt; Any:\n    \"\"\"Return data for the given index and role.\n\n    Args:\n        index: Model index identifying the cell.\n        role: Qt item data role.\n\n    Returns:\n        Cell value appropriate for the requested role, or ``None``.\n    \"\"\"\n    if not index.isValid():\n        return None\n    node: _TableNode | None = index.internalPointer()  # type: ignore[assignment]\n    if node is None:\n        return None\n    col = index.column()\n    if col &lt; 0 or col &gt;= len(self._columns):\n        return None\n\n    row_dict = node.row_data\n    col_key = self._columns[col].key\n\n    if role == Qt.ItemDataRole.DisplayRole:\n        value = row_dict.get(col_key)\n        if value is None:\n            return \"\"\n        return str(value)\n\n    if role == Qt.ItemDataRole.DecorationRole:\n        icon_key = f\"{col_key}__icon\"\n        icon_name = row_dict.get(icon_key)\n        if icon_name:\n            icon_color = row_dict.get(f\"{col_key}__color\", \"#ffffff\")\n            icon_fill = row_dict.get(f\"{col_key}__icon_fill\", False)\n            return get_icon(icon_name, color=icon_color, fill=icon_fill)\n        return None\n\n    if role == Qt.ItemDataRole.ForegroundRole:\n        color_key = f\"{col_key}__color\"\n        color = row_dict.get(color_key)\n        if isinstance(color, str):\n            return QBrush(QColor(color))\n        return None\n\n    if role == Qt.ItemDataRole.UserRole:\n        return row_dict\n\n    return None\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.fetchMore","title":"<code>fetchMore(parent=QModelIndex())</code>","text":"<p>Fetch the next page of rows for parent.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Parent index (invalid = root).</p> <code>QModelIndex()</code> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def fetchMore(  # noqa: N802\n    self,\n    parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n) -&gt; None:\n    \"\"\"Fetch the next page of rows for parent.\n\n    Args:\n        parent: Parent index (invalid = root).\n    \"\"\"\n    self._fetch_next_page(self._node_from_index(parent))\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.get_distinct_values","title":"<code>get_distinct_values(key)</code>","text":"<p>Return sorted distinct non-empty string values for a column.</p> <p>In flat mode scans root-level rows; in tree mode scans all loaded nodes across all levels.</p> <p>Parameters:</p> Name Type Description Default <code>key</code> <code>str</code> <p>Column key to inspect.</p> required <p>Returns:</p> Type Description <code>list[str]</code> <p>Sorted list of unique string values found in loaded rows.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def get_distinct_values(self, key: str) -&gt; list[str]:\n    \"\"\"Return sorted distinct non-empty string values for a column.\n\n    In flat mode scans root-level rows; in tree mode scans all\n    loaded nodes across all levels.\n\n    Args:\n        key: Column key to inspect.\n\n    Returns:\n        Sorted list of unique string values found in loaded rows.\n    \"\"\"\n    seen: set[str] = set()\n    nodes = (\n        self._all_nodes if self._tree_mode else set(self._root.children)\n    )\n    for node in nodes:\n        if node.is_root:\n            continue\n        val = node.row_data.get(key)\n        if val is not None:\n            s = str(val).strip()\n            if s:\n                seen.add(s)\n    return sorted(seen)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.hasChildren","title":"<code>hasChildren(parent=QModelIndex())</code>","text":"<p>Return whether the node at parent has or can have children.</p> <p>Controls whether Qt draws a disclosure triangle even before children are loaded.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Parent index (invalid = root).</p> <code>QModelIndex()</code> <p>Returns:</p> Type Description <code>bool</code> <p>True if the node has loaded children, has more pages, or</p> <code>bool</code> <p>(in tree mode only) the row data declares <code>has_children</code>.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def hasChildren(  # noqa: N802\n    self,\n    parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n) -&gt; bool:\n    \"\"\"Return whether the node at parent has or can have children.\n\n    Controls whether Qt draws a disclosure triangle even before\n    children are loaded.\n\n    Args:\n        parent: Parent index (invalid = root).\n\n    Returns:\n        True if the node has loaded children, has more pages, or\n        (in tree mode only) the row data declares ``has_children``.\n    \"\"\"\n    node = self._node_from_index(parent)\n    if node.is_root:\n        return bool(node.children) or node.has_more\n    if not self._tree_mode:\n        return False\n    if node.children_loaded:\n        return bool(node.children)\n    return node.row_has_children\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.headerData","title":"<code>headerData(section, orientation, role=Qt.ItemDataRole.DisplayRole)</code>","text":"<p>Return header data for the given section and orientation.</p> <p>Parameters:</p> Name Type Description Default <code>section</code> <code>int</code> <p>Column (horizontal) or row (vertical) index.</p> required <code>orientation</code> <code>Orientation</code> <p>Header orientation.</p> required <code>role</code> <code>int</code> <p>Qt item data role.</p> <code>DisplayRole</code> <p>Returns:</p> Type Description <code>Any</code> <p>Column label for horizontal DisplayRole, otherwise <code>None</code>.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def headerData(  # noqa: N802\n    self,\n    section: int,\n    orientation: Qt.Orientation,\n    role: int = Qt.ItemDataRole.DisplayRole,\n) -&gt; Any:\n    \"\"\"Return header data for the given section and orientation.\n\n    Args:\n        section: Column (horizontal) or row (vertical) index.\n        orientation: Header orientation.\n        role: Qt item data role.\n\n    Returns:\n        Column label for horizontal DisplayRole, otherwise ``None``.\n    \"\"\"\n    if (\n        orientation == Qt.Orientation.Horizontal\n        and role == Qt.ItemDataRole.DisplayRole\n    ):\n        if 0 &lt;= section &lt; len(self._columns):\n            return self._columns[section].label\n    return None\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.index","title":"<code>index(row, column, parent=QModelIndex())</code>","text":"<p>Return a model index for row/column under parent.</p> <p>Parameters:</p> Name Type Description Default <code>row</code> <code>int</code> <p>Row number under parent.</p> required <code>column</code> <code>int</code> <p>Column number.</p> required <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Parent index (invalid = root).</p> <code>QModelIndex()</code> <p>Returns:</p> Type Description <code>QModelIndex</code> <p>Valid QModelIndex, or invalid if out of range.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def index(  # noqa: N802\n    self,\n    row: int,\n    column: int,\n    parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n) -&gt; QModelIndex:\n    \"\"\"Return a model index for row/column under parent.\n\n    Args:\n        row: Row number under parent.\n        column: Column number.\n        parent: Parent index (invalid = root).\n\n    Returns:\n        Valid QModelIndex, or invalid if out of range.\n    \"\"\"\n    if not self.hasIndex(row, column, parent):\n        return QModelIndex()\n    parent_node = self._node_from_index(parent)\n    if row &gt;= len(parent_node.children):\n        return QModelIndex()\n    return self.createIndex(row, column, parent_node.children[row])\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.parent","title":"<code>parent(index)</code>","text":"<p>Return the parent index of the given index.</p> <p>Parameters:</p> Name Type Description Default <code>index</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Child index.</p> required <p>Returns:</p> Type Description <code>QModelIndex</code> <p>Parent QModelIndex, or invalid for root-level items.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def parent(  # type: ignore[override]\n    self,\n    index: QModelIndex | QPersistentModelIndex,\n) -&gt; QModelIndex:\n    \"\"\"Return the parent index of the given index.\n\n    Args:\n        index: Child index.\n\n    Returns:\n        Parent QModelIndex, or invalid for root-level items.\n    \"\"\"\n    if not index.isValid():\n        return QModelIndex()\n    node: _TableNode = index.internalPointer()  # type: ignore[assignment]\n    parent_node = node.parent\n    if parent_node is None or parent_node.is_root:\n        return QModelIndex()\n    grandparent = parent_node.parent\n    row = grandparent.children.index(parent_node)  # type: ignore[union-attr]\n    return self.createIndex(row, 0, parent_node)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.reset_data","title":"<code>reset_data()</code>","text":"<p>Reset the model and re-fetch from page 0.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def reset_data(self) -&gt; None:\n    \"\"\"Reset the model and re-fetch from page 0.\"\"\"\n    old_request_id = self._request_id\n    if not self._no_async:\n        get_task_queue().clear_context_tasks(old_request_id)\n    self._request_id = self._generate_request_id()\n    self._pending_tasks = 0\n    self._pending_batch_nodes = []\n    self._batch_scheduled = False\n    self.beginResetModel()\n    self._root = _TableNode(node_id=None, row_data={}, parent=None)\n    self._all_nodes = {self._root}\n    self._columns = self._explicit_columns or []\n    self.endResetModel()\n    # Emit loading signals *after* endResetModel so that any slot\n    # connected to loading_changed observes a consistent model state.\n    self._update_loading_state()\n    self._fetch_next_page(self._root)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.rowCount","title":"<code>rowCount(parent=QModelIndex())</code>","text":"<p>Return the number of loaded children under parent.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Parent index (invalid = root).</p> <code>QModelIndex()</code> <p>Returns:</p> Type Description <code>int</code> <p>Number of loaded child rows.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def rowCount(  # noqa: N802\n    self,\n    parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n) -&gt; int:\n    \"\"\"Return the number of loaded children under parent.\n\n    Args:\n        parent: Parent index (invalid = root).\n\n    Returns:\n        Number of loaded child rows.\n    \"\"\"\n    if parent.column() &gt; 0:\n        return 0\n    return len(self._node_from_index(parent).children)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.set_columns","title":"<code>set_columns(columns)</code>","text":"<p>Set the columns and reset the model from page 0.</p> <p>Parameters:</p> Name Type Description Default <code>columns</code> <code>list[TableColumn]</code> <p>List of columns to display.</p> required Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def set_columns(self, columns: list[TableColumn]) -&gt; None:\n    \"\"\"Set the columns and reset the model from page 0.\n\n    Args:\n        columns: List of columns to display.\n    \"\"\"\n    self._explicit_columns = columns\n    self.reset_data()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.set_page","title":"<code>set_page(page)</code>","text":"<p>Reset the model and begin fetching from the given page.</p> <p>Parameters:</p> Name Type Description Default <code>page</code> <code>int</code> <p>0-based page number to start from.</p> required Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def set_page(self, page: int) -&gt; None:\n    \"\"\"Reset the model and begin fetching from the given page.\n\n    Args:\n        page: 0-based page number to start from.\n    \"\"\"\n    old_request_id = self._request_id\n    if not self._no_async:\n        get_task_queue().clear_context_tasks(old_request_id)\n    self._request_id = self._generate_request_id()\n    self._pending_tasks = 0\n    self._pending_batch_nodes = []\n    self._batch_scheduled = False\n    self.beginResetModel()\n    self._root = _TableNode(node_id=None, row_data={}, parent=None)\n    self._root.current_page = page\n    self._all_nodes = {self._root}\n    self._columns = self._explicit_columns or []\n    self.endResetModel()\n    # Emit loading signals *after* endResetModel so that any slot\n    # connected to loading_changed observes a consistent model state.\n    self._update_loading_state()\n    self._fetch_next_page(self._root)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.set_page_size","title":"<code>set_page_size(size)</code>","text":"<p>Update the page size and reset the model from page 0.</p> <p>Parameters:</p> Name Type Description Default <code>size</code> <code>int</code> <p>New page size (rows per page).</p> required Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def set_page_size(self, size: int) -&gt; None:\n    \"\"\"Update the page size and reset the model from page 0.\n\n    Args:\n        size: New page size (rows per page).\n    \"\"\"\n    self._page_size = size\n    self.reset_data()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.set_tree_mode","title":"<code>set_tree_mode(enabled)</code>","text":"<p>Switch between flat table mode and hierarchical tree mode.</p> <p>Emits <code>tree_mode_changed</code> and reloads from page 0.</p> <p>Parameters:</p> Name Type Description Default <code>enabled</code> <code>bool</code> <p><code>True</code> to enable tree mode, <code>False</code> for flat.</p> required Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def set_tree_mode(self, enabled: bool) -&gt; None:\n    \"\"\"Switch between flat table mode and hierarchical tree mode.\n\n    Emits ``tree_mode_changed`` and reloads from page 0.\n\n    Args:\n        enabled: ``True`` to enable tree mode, ``False`` for flat.\n    \"\"\"\n    if self._tree_mode == enabled:\n        return\n    self._tree_mode = enabled\n    self.tree_mode_changed.emit(enabled)\n    self.reset_data()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.PaginatedTableModel.sort","title":"<code>sort(column, order=Qt.SortOrder.AscendingOrder)</code>","text":"<p>Set the active sort column and order, then reload data.</p> <p>Sorting always resets from page 0 at all levels.</p> <p>Parameters:</p> Name Type Description Default <code>column</code> <code>int</code> <p>Zero-based index of the column to sort by. If out of range, the call is ignored.</p> required <code>order</code> <code>SortOrder</code> <p>Sort order (ascending or descending).</p> <code>AscendingOrder</code> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def sort(\n    self, column: int, order: Qt.SortOrder = Qt.SortOrder.AscendingOrder\n) -&gt; None:\n    \"\"\"Set the active sort column and order, then reload data.\n\n    Sorting always resets from page 0 at all levels.\n\n    Args:\n        column: Zero-based index of the column to sort by. If out of\n            range, the call is ignored.\n        order: Sort order (ascending or descending).\n    \"\"\"\n    if column &lt; 0 or column &gt;= len(self._columns):\n        return\n    self._sort_column = column\n    self._sort_order = order\n    self.reset_data()  # refetch page 0 using new sort\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.TableColumn","title":"<code>TableColumn</code>  <code>dataclass</code>","text":"<p>Describes a single column in a PaginatedTableModel.</p> <p>Attributes:</p> Name Type Description <code>key</code> <code>str</code> <p>Dictionary key used to look up cell values in row data.</p> <code>label</code> <code>str</code> <p>Display text shown in the header.</p> <code>width</code> <code>int</code> <p>Preferred column width hint in pixels. 0 means auto.</p> <code>sortable</code> <code>bool</code> <p>Whether the column can be sorted by clicking the header.</p> <code>icon</code> <code>str | None</code> <p>Optional material icon name shown in the filter dropdown.</p> <code>tree_position</code> <code>bool</code> <p>Whether the column is used for tree indentation.</p> <code>widget_factory</code> <code>'Callable[[Any, Any], Any] | None'</code> <p>Optional callable <code>(index, parent) -&gt; QWidget</code>. When set, the delegate opens a persistent editor for every cell in this column instead of painting text/icons.  The factory receives the display-model <code>QModelIndex</code> and the viewport widget as <code>parent</code>.  <code>setEditorData</code> is called automatically by Qt whenever the model emits <code>dataChanged</code> for that index, so server-push updates reach the widget without any extra wiring.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>@dataclass\nclass TableColumn:\n    \"\"\"Describes a single column in a PaginatedTableModel.\n\n    Attributes:\n        key: Dictionary key used to look up cell values in row data.\n        label: Display text shown in the header.\n        width: Preferred column width hint in pixels. 0 means auto.\n        sortable: Whether the column can be sorted by clicking the header.\n        icon: Optional material icon name shown in the filter dropdown.\n        tree_position: Whether the column is used for tree indentation.\n        widget_factory: Optional callable ``(index, parent) -&gt; QWidget``.\n            When set, the delegate opens a persistent editor for every\n            cell in this column instead of painting text/icons.  The\n            factory receives the display-model ``QModelIndex`` and the\n            viewport widget as ``parent``.  ``setEditorData`` is called\n            automatically by Qt whenever the model emits ``dataChanged``\n            for that index, so server-push updates reach the widget\n            without any extra wiring.\n    \"\"\"\n\n    key: str\n    label: str\n    width: int = 0\n    sortable: bool = True\n    icon: str | None = None\n    tree_position: bool = False\n    widget_factory: \"Callable[[Any, Any], Any] | None\" = None\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.make_hierarchical_test_fetch","title":"<code>make_hierarchical_test_fetch(data)</code>","text":"<p>Create a fetch_page callback from hierarchical test data.</p> <p>Parameters:</p> Name Type Description Default <code>data</code> <code>dict[str | None, list[dict[str, Any]]]</code> <p>Mapping of parent_id -&gt; list[row_dict].   <code>None</code> key holds the root-level rows.</p> required <p>Returns:</p> Type Description <code>Callable[[int, int, str | None, bool, str | None], list[dict[str, Any]]]</code> <p>A callable suitable for PaginatedTableModel in tree mode.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def make_hierarchical_test_fetch(\n    data: dict[str | None, list[dict[str, Any]]],\n) -&gt; Callable[[int, int, str | None, bool, str | None], list[dict[str, Any]]]:\n    \"\"\"Create a fetch_page callback from hierarchical test data.\n\n    Args:\n        data: Mapping of parent_id -&gt; list[row_dict].\n              ``None`` key holds the root-level rows.\n\n    Returns:\n        A callable suitable for PaginatedTableModel in tree mode.\n    \"\"\"\n\n    def _fetch(\n        page: int,\n        page_size: int,\n        sort_key: str | None,\n        descending: bool,\n        parent_id: str | None = None,\n    ) -&gt; list[dict[str, Any]]:\n        print(\n            f\"[test]  Fetching page {page} (page_size={page_size}, \"\n            f\"sort_key={sort_key!r}, descending={descending}, \"\n            f\"parent_id={parent_id!r})\"\n        )\n        rows = list(data.get(parent_id, []))\n        if sort_key:\n            rows = sorted(\n                rows,\n                key=lambda r: (\n                    r.get(sort_key) is None,\n                    str(r.get(sort_key, \"\")),\n                ),\n                reverse=descending,\n            )\n        start = page * page_size\n        end = start + page_size\n        return rows[start:end]\n\n    return _fetch\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.make_hierarchical_test_fetch_batch","title":"<code>make_hierarchical_test_fetch_batch(data)</code>","text":"<p>Create a fetch_page_batch callback from hierarchical test data.</p> <p>Wraps :func:<code>make_hierarchical_test_fetch</code> so that several child fetch requests are resolved in one call, mimicking a batched server API.  Use together with <code>fetch_page_batch=</code> on :class:<code>PaginatedTableModel</code> to exercise the batch code path.</p> <p>Parameters:</p> Name Type Description Default <code>data</code> <code>dict[str | None, list[dict[str, Any]]]</code> <p>Mapping of parent_id -&gt; list[row_dict].   <code>None</code> key holds the root-level rows.</p> required <p>Returns:</p> Type Description <code>Callable[[list[BatchFetchRequest]], dict[str | None, list[dict[str, Any]]]]</code> <p>A callable suitable for <code>PaginatedTableModel(fetch_page_batch=\u2026)</code></p> <code>Callable[[list[BatchFetchRequest]], dict[str | None, list[dict[str, Any]]]]</code> <p>in tree mode.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def make_hierarchical_test_fetch_batch(\n    data: dict[str | None, list[dict[str, Any]]],\n) -&gt; Callable[\n    [list[BatchFetchRequest]], dict[str | None, list[dict[str, Any]]]\n]:\n    \"\"\"Create a *fetch_page_batch* callback from hierarchical test data.\n\n    Wraps :func:`make_hierarchical_test_fetch` so that several child\n    fetch requests are resolved in one call, mimicking a batched server\n    API.  Use together with ``fetch_page_batch=`` on\n    :class:`PaginatedTableModel` to exercise the batch code path.\n\n    Args:\n        data: Mapping of parent_id -&gt; list[row_dict].\n              ``None`` key holds the root-level rows.\n\n    Returns:\n        A callable suitable for ``PaginatedTableModel(fetch_page_batch=\u2026)``\n        in tree mode.\n    \"\"\"\n    single_fetch = make_hierarchical_test_fetch(data)\n\n    def _batch_fetch(\n        requests: list[BatchFetchRequest],\n    ) -&gt; dict[str | None, list[dict[str, Any]]]:\n        print(\n            f\"[test]  Batch fetch for {len(requests)} parent(s): \"\n            f\"{[r.parent_id for r in requests]!r}\"\n        )\n        return {\n            req.parent_id: single_fetch(\n                req.page,\n                req.page_size,\n                req.sort_key,\n                req.descending,\n                req.parent_id,\n            )\n            for req in requests\n        }\n\n    return _batch_fetch\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_model.html#client.ayon_ui_qt.components.table_model.make_test_fetch","title":"<code>make_test_fetch(data)</code>","text":"<p>Create a flat fetch_page callback from static data.</p> <p><code>parent_id</code> is accepted but ignored \u2014 all data lives at root level.</p> <p>Parameters:</p> Name Type Description Default <code>data</code> <code>list[dict[str, Any]]</code> <p>The full dataset to paginate.</p> required <p>Returns:</p> Type Description <code>Callable[[int, int, str | None, bool, str | None], list[dict[str, Any]]]</code> <p>A callable suitable for PaginatedTableModel.</p> Source code in <code>client/ayon_ui_qt/components/table_model.py</code> <pre><code>def make_test_fetch(\n    data: list[dict[str, Any]],\n) -&gt; Callable[[int, int, str | None, bool, str | None], list[dict[str, Any]]]:\n    \"\"\"Create a flat fetch_page callback from static data.\n\n    ``parent_id`` is accepted but ignored \u2014 all data lives at root level.\n\n    Args:\n        data: The full dataset to paginate.\n\n    Returns:\n        A callable suitable for PaginatedTableModel.\n    \"\"\"\n\n    def _fetch(\n        page: int,\n        page_size: int,\n        sort_key: str | None,\n        descending: bool,\n        parent_id: str | None = None,  # noqa: ARG001\n    ) -&gt; list[dict[str, Any]]:\n        print(\n            f\"[test]  Fetching page {page} (page_size={page_size}, \"\n            f\"sort_key={sort_key!r}, descending={descending})\"\n        )\n        rows = data\n        if sort_key:\n            rows = sorted(\n                data,\n                key=lambda r: (\n                    r.get(sort_key) is None,\n                    str(r.get(sort_key, \"\")),\n                ),\n                reverse=descending,\n            )\n        start = page * page_size\n        end = start + page_size\n        return rows[start:end]\n\n    return _fetch\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_view.html","title":"table_view","text":"<p>AYTableView component module.</p> <p>A flat, paginated table built on QTreeView with AYON styling.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/table_view.html#client.ayon_ui_qt.components.table_view.AYTableHeader","title":"<code>AYTableHeader</code>","text":"<p>               Bases: <code>QHeaderView</code></p> <p>Custom QHeaderView that paints sections directly, bypassing QSS.</p> <p>Draws header sections using QPainter to avoid interference from QStyleSheetStyle when a QSS stylesheet is loaded at the app level.</p> <p>Parameters:</p> Name Type Description Default <code>orientation</code> <code>Orientation</code> <p>Header orientation (Horizontal or Vertical).</p> required <code>parent</code> <code>QWidget | None</code> <p>Optional parent widget.</p> <code>None</code> <code>style_model</code> <code>StyleData | None</code> <p>Style data model; if None falls back to super().</p> <code>None</code> <code>variant</code> <code>str</code> <p>Visual style variant name.</p> <code>'default'</code> Source code in <code>client/ayon_ui_qt/components/table_view.py</code> <pre><code>class AYTableHeader(QHeaderView):\n    \"\"\"Custom QHeaderView that paints sections directly, bypassing QSS.\n\n    Draws header sections using QPainter to avoid interference from\n    QStyleSheetStyle when a QSS stylesheet is loaded at the app level.\n\n    Args:\n        orientation: Header orientation (Horizontal or Vertical).\n        parent: Optional parent widget.\n        style_model: Style data model; if None falls back to super().\n        variant: Visual style variant name.\n    \"\"\"\n\n    def __init__(\n        self,\n        orientation: Qt.Orientation,\n        parent: QWidget | None = None,\n        style_model: StyleData | None = None,\n        variant: str = \"default\",\n    ) -&gt; None:\n        super().__init__(orientation, parent)\n        self._style_model = style_model\n        self._variant_str = variant\n        self._toggle_btn: QToolButton | None = None\n        # self.setSortIndicatorShown(True)\n\n    def paintSection(\n        self,\n        painter: QPainter,\n        rect: QRect,\n        logical_index: int,\n    ) -&gt; None:\n        \"\"\"Paint a single header section directly with QPainter.\n\n        Falls back to the base implementation when no style model is\n        available.\n\n        Args:\n            painter: The painter to draw with.\n            rect: The bounding rectangle for this section.\n            logical_index: The logical index of the section.\n        \"\"\"\n        if self._style_model is None:\n            super().paintSection(painter, rect, logical_index)\n            return\n\n        tbl_style = self._style_model.get_style(\n            \"AYTableView\", self._variant_str\n        )\n\n        painter.save()\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)\n        painter.setClipRect(rect)\n\n        # draw cell\n        painter.setBrush(\n            QBrush(QColor(tbl_style.get(\"header-background-color\", \"#272d35\")))\n        )\n        painter.setPen(\n            QPen(\n                QColor(tbl_style.get(\"header-border-color\", \"#41474d\")),\n                tbl_style.get(\"header-border-width\", 1),\n            )\n        )\n        painter.drawRect(rect)\n\n        # Label text\n        padding = tbl_style.get(\"header-padding\", [4, 8])\n        h_pad = int(padding[1]) if len(padding) &gt; 1 else 8\n        v_pad = int(padding[0])\n        text_rect = rect.adjusted(h_pad, v_pad, -h_pad, -v_pad)\n\n        text_color = QColor(tbl_style.get(\"header-color\", \"#c1c7ce\"))\n        painter.setPen(text_color)\n\n        font = painter.font()\n        font.setWeight(QFont.Weight.DemiBold)\n        painter.setFont(font)\n\n        model = self.model()\n        if model is not None:\n            label = model.headerData(\n                logical_index,\n                self.orientation(),\n                Qt.ItemDataRole.DisplayRole,\n            )\n            if label is not None:\n                painter.drawText(\n                    text_rect,\n                    Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n                    str(label),\n                )\n\n        # Sort indicator\n        if (\n            self.isSortIndicatorShown()\n            and self.sortIndicatorSection() == logical_index\n        ):\n            # do not draw sort indicator if column is not sortable\n            is_sortable = True\n            if isinstance(model, PaginatedTableModel):\n                cols = model.columns\n                if 0 &lt;= logical_index &lt; len(cols):\n                    is_sortable = cols[logical_index].sortable\n            if not is_sortable:\n                painter.restore()\n                return\n\n            # draw sort indicator (icon if available, otherwise arrow)\n            order = self.sortIndicatorOrder()\n            icon_name = tbl_style.get(\"header-sort-indicator-icon\", None)\n            if icon_name is not None:\n                icon = get_icon(\n                    icon_name,\n                    color=tbl_style.get(\n                        \"header-sort-indicator-color\", \"#ffffff\"\n                    ),\n                )\n                size = tbl_style.get(\"header-sort-indicator-size\", 16)\n                margin = (rect.height() - size) / 2.0\n                pixmap = icon.pixmap(size, size)\n                target = rect.adjusted(\n                    max(rect.width() - (size + h_pad), 0),\n                    margin,\n                    -h_pad,\n                    -margin,\n                )\n\n                if order == Qt.SortOrder.AscendingOrder:\n                    painter.save()\n                    center = target.center()\n                    painter.translate(center)\n                    painter.rotate(180)\n                    painter.translate(-center)\n                    painter.drawPixmap(target, pixmap)\n                    painter.restore()\n                else:\n                    painter.drawPixmap(target, pixmap)\n\n            else:\n                arrow = \"\u25b2\" if order == Qt.SortOrder.AscendingOrder else \"\u25bc\"\n                painter.drawText(\n                    text_rect,\n                    Qt.AlignmentFlag.AlignVCenter\n                    | Qt.AlignmentFlag.AlignRight,\n                    arrow,\n                )\n\n        painter.restore()\n\n    def resizeEvent(self, event: Any) -&gt; None:  # type: ignore[override]\n        \"\"\"Reposition the toggle button after a resize.\n\n        Args:\n            event: Resize event.\n        \"\"\"\n        super().resizeEvent(event)\n        self._reposition_toggle()\n\n    def _reposition_toggle(self) -&gt; None:\n        \"\"\"Move the toggle button to the right-centre of the header.\"\"\"\n        if self._toggle_btn is None:\n            return\n        btn = self._toggle_btn\n        h = self.height()\n        margin = max((h - btn.height()) // 2, 0)\n        x = max(self.width() - btn.width() - margin, 0)\n        btn.move(x, margin)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_view.html#client.ayon_ui_qt.components.table_view.AYTableHeader.paintSection","title":"<code>paintSection(painter, rect, logical_index)</code>","text":"<p>Paint a single header section directly with QPainter.</p> <p>Falls back to the base implementation when no style model is available.</p> <p>Parameters:</p> Name Type Description Default <code>painter</code> <code>QPainter</code> <p>The painter to draw with.</p> required <code>rect</code> <code>QRect</code> <p>The bounding rectangle for this section.</p> required <code>logical_index</code> <code>int</code> <p>The logical index of the section.</p> required Source code in <code>client/ayon_ui_qt/components/table_view.py</code> <pre><code>def paintSection(\n    self,\n    painter: QPainter,\n    rect: QRect,\n    logical_index: int,\n) -&gt; None:\n    \"\"\"Paint a single header section directly with QPainter.\n\n    Falls back to the base implementation when no style model is\n    available.\n\n    Args:\n        painter: The painter to draw with.\n        rect: The bounding rectangle for this section.\n        logical_index: The logical index of the section.\n    \"\"\"\n    if self._style_model is None:\n        super().paintSection(painter, rect, logical_index)\n        return\n\n    tbl_style = self._style_model.get_style(\n        \"AYTableView\", self._variant_str\n    )\n\n    painter.save()\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)\n    painter.setClipRect(rect)\n\n    # draw cell\n    painter.setBrush(\n        QBrush(QColor(tbl_style.get(\"header-background-color\", \"#272d35\")))\n    )\n    painter.setPen(\n        QPen(\n            QColor(tbl_style.get(\"header-border-color\", \"#41474d\")),\n            tbl_style.get(\"header-border-width\", 1),\n        )\n    )\n    painter.drawRect(rect)\n\n    # Label text\n    padding = tbl_style.get(\"header-padding\", [4, 8])\n    h_pad = int(padding[1]) if len(padding) &gt; 1 else 8\n    v_pad = int(padding[0])\n    text_rect = rect.adjusted(h_pad, v_pad, -h_pad, -v_pad)\n\n    text_color = QColor(tbl_style.get(\"header-color\", \"#c1c7ce\"))\n    painter.setPen(text_color)\n\n    font = painter.font()\n    font.setWeight(QFont.Weight.DemiBold)\n    painter.setFont(font)\n\n    model = self.model()\n    if model is not None:\n        label = model.headerData(\n            logical_index,\n            self.orientation(),\n            Qt.ItemDataRole.DisplayRole,\n        )\n        if label is not None:\n            painter.drawText(\n                text_rect,\n                Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,\n                str(label),\n            )\n\n    # Sort indicator\n    if (\n        self.isSortIndicatorShown()\n        and self.sortIndicatorSection() == logical_index\n    ):\n        # do not draw sort indicator if column is not sortable\n        is_sortable = True\n        if isinstance(model, PaginatedTableModel):\n            cols = model.columns\n            if 0 &lt;= logical_index &lt; len(cols):\n                is_sortable = cols[logical_index].sortable\n        if not is_sortable:\n            painter.restore()\n            return\n\n        # draw sort indicator (icon if available, otherwise arrow)\n        order = self.sortIndicatorOrder()\n        icon_name = tbl_style.get(\"header-sort-indicator-icon\", None)\n        if icon_name is not None:\n            icon = get_icon(\n                icon_name,\n                color=tbl_style.get(\n                    \"header-sort-indicator-color\", \"#ffffff\"\n                ),\n            )\n            size = tbl_style.get(\"header-sort-indicator-size\", 16)\n            margin = (rect.height() - size) / 2.0\n            pixmap = icon.pixmap(size, size)\n            target = rect.adjusted(\n                max(rect.width() - (size + h_pad), 0),\n                margin,\n                -h_pad,\n                -margin,\n            )\n\n            if order == Qt.SortOrder.AscendingOrder:\n                painter.save()\n                center = target.center()\n                painter.translate(center)\n                painter.rotate(180)\n                painter.translate(-center)\n                painter.drawPixmap(target, pixmap)\n                painter.restore()\n            else:\n                painter.drawPixmap(target, pixmap)\n\n        else:\n            arrow = \"\u25b2\" if order == Qt.SortOrder.AscendingOrder else \"\u25bc\"\n            painter.drawText(\n                text_rect,\n                Qt.AlignmentFlag.AlignVCenter\n                | Qt.AlignmentFlag.AlignRight,\n                arrow,\n            )\n\n    painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_view.html#client.ayon_ui_qt.components.table_view.AYTableHeader.resizeEvent","title":"<code>resizeEvent(event)</code>","text":"<p>Reposition the toggle button after a resize.</p> <p>Parameters:</p> Name Type Description Default <code>event</code> <code>Any</code> <p>Resize event.</p> required Source code in <code>client/ayon_ui_qt/components/table_view.py</code> <pre><code>def resizeEvent(self, event: Any) -&gt; None:  # type: ignore[override]\n    \"\"\"Reposition the toggle button after a resize.\n\n    Args:\n        event: Resize event.\n    \"\"\"\n    super().resizeEvent(event)\n    self._reposition_toggle()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_view.html#client.ayon_ui_qt.components.table_view.AYTableView","title":"<code>AYTableView</code>","text":"<p>               Bases: <code>QTreeView</code></p> <p>AYON-styled flat table view.</p> <p>Subclasses QTreeView in flat-table mode (no tree indentation or expand toggles). Uses AYONStyle for all painting, a custom item delegate that draws directly bypassing any parent QSS, and AYScrollBar instances for scrollbars.</p> <p>The header is visible and styled via TableHeaderDrawer.</p> <p>When a PaginatedTableModel is set, columns that carry a <code>widget_factory</code> on their :class:<code>TableColumn</code> definition get a persistent editor in every row via <code>openPersistentEditor</code>.  Qt calls <code>setEditorData</code> automatically whenever the model emits <code>dataChanged</code> for those cells, so server-push updates reach the widgets without any extra wiring.</p> <p>In tree mode, persistent editors are opened lazily \u2014 only for rows whose parent node is already expanded.  Rows under collapsed nodes receive their editors when the user (or code) expands that node, via the <code>expanded</code> signal handler.  This avoids creating widgets for the entire off-screen tree when Qt's layout pass eagerly triggers :meth:<code>fetchMore</code> for all visible nodes.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QWidget | None</code> <p>Optional parent widget.</p> <code>None</code> <code>variant</code> <code>Variants</code> <p>Visual style variant controlling colours.</p> <code>Default</code> Source code in <code>client/ayon_ui_qt/components/table_view.py</code> <pre><code>class AYTableView(QTreeView):\n    \"\"\"AYON-styled flat table view.\n\n    Subclasses QTreeView in flat-table mode (no tree indentation or\n    expand toggles). Uses AYONStyle for all painting, a custom item\n    delegate that draws directly bypassing any parent QSS, and\n    AYScrollBar instances for scrollbars.\n\n    The header is visible and styled via TableHeaderDrawer.\n\n    When a PaginatedTableModel is set, columns that carry a\n    ``widget_factory`` on their :class:`TableColumn` definition get a\n    persistent editor in every row via ``openPersistentEditor``.  Qt\n    calls ``setEditorData`` automatically whenever the model emits\n    ``dataChanged`` for those cells, so server-push updates reach the\n    widgets without any extra wiring.\n\n    In tree mode, persistent editors are opened lazily \u2014 only for rows\n    whose parent node is already expanded.  Rows under collapsed nodes\n    receive their editors when the user (or code) expands that node,\n    via the ``expanded`` signal handler.  This avoids creating widgets\n    for the entire off-screen tree when Qt's layout pass eagerly\n    triggers :meth:`fetchMore` for all visible nodes.\n\n    Args:\n        parent: Optional parent widget.\n        variant: Visual style variant controlling colours.\n    \"\"\"\n\n    Variants = AYTableViewVariants\n    selection_changed = Signal(QItemSelection, QItemSelection)\n\n    def __init__(\n        self,\n        parent: QWidget | None = None,\n        variant: Variants = Variants.Default,\n    ) -&gt; None:\n        self._variant_str: str = variant.value\n\n        super().__init__(parent)\n\n        style = get_ayon_style()\n        self.setStyle(style)\n\n        # Custom header \u2014 paints sections directly, bypassing QSS.\n        header = AYTableHeader(\n            Qt.Orientation.Horizontal,\n            parent=self,\n            style_model=style.model,\n            variant=self._variant_str,\n        )\n        self.setHeader(header)\n\n        # Self-contained: do not inherit parent background.\n        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)\n        self.setAttribute(Qt.WidgetAttribute.WA_Hover, True)\n        self.setMouseTracking(True)\n\n        self.viewport().setAttribute(\n            Qt.WidgetAttribute.WA_TranslucentBackground, False\n        )\n        self._sync_viewport_palette()\n\n        # Custom item delegate \u2014 paints cells directly.\n        delegate = TableItemDelegate(\n            parent=self,\n            style_model=style.model,\n            variant=self._variant_str,\n        )\n        self.setItemDelegate(delegate)\n\n        # Styled scrollbars.\n        vsb = AYScrollBar(Qt.Orientation.Vertical, self)\n        self.setVerticalScrollBar(vsb)\n        self.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)\n        hsb = AYScrollBar(Qt.Orientation.Horizontal, self)\n        self.setHorizontalScrollBar(hsb)\n        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)\n\n        # Viewport-aware persistent-editor management (open-only strategy).\n        # Tracks every QPersistentModelIndex for which openPersistentEditor\n        # has already been called so the same editor is never opened twice.\n        # Editors are never explicitly closed while scrolling: once built,\n        # a dormant off-screen persistent editor costs near zero (Qt skips\n        # its paintEvent), whereas re-creating it on scroll-back would cause\n        # widget churn and redundant async thumbnail re-fetches.\n        self._active_editor_pmis: set[QtCore.QPersistentModelIndex] = set()\n        # Single-shot, zero-interval timer \u2014 fires once per event-loop\n        # iteration so multiple rowsInserted bursts produce a single\n        # _sync_viewport_editors call instead of one per batch.\n        self._editor_sync_timer = QtCore.QTimer(self)\n        self._editor_sync_timer.setSingleShot(True)\n        self._editor_sync_timer.setInterval(0)\n        self._editor_sync_timer.timeout.connect(self._sync_viewport_editors)\n        vsb.valueChanged.connect(self._schedule_editor_sync)\n\n        # Flat table \u2014 no tree features.\n        self.setRootIsDecorated(False)\n        self.setItemsExpandable(False)\n        self.setIndentation(0)\n\n        # Header visible.\n        self.setHeaderHidden(False)\n\n        # Selection behaviour.\n        self.setSelectionMode(QTreeView.SelectionMode.SingleSelection)\n        self.setSelectionBehavior(QTreeView.SelectionBehavior.SelectRows)\n\n        # No default frame \u2014 drawn manually in paintEvent.\n        self.setFrameShape(QTreeView.Shape.NoFrame)\n\n        # Alternating row colours disabled \u2014 delegate handles it.\n        self.setAlternatingRowColors(False)\n\n        # Hovered-row tracking: stores the visual rect of the currently\n        # hovered row so we can force-repaint it when the mouse moves to a\n        # different row.  Without this, the branch-indicator area (painted\n        # by PE_IndicatorBranch, not the delegate) is never invalidated on\n        # row transitions and stays highlighted until the next full repaint.\n        self._hovered_row: int = -1\n        self._hovered_row_rect: QRect = QRect()\n\n        # Track model connections for cleanup.  Each entry is (source_object,\n        # connection) so we can call the right object's .disconnect().\n        self._model_connections: list[\n            tuple[Any, QtCore.QMetaObject.Connection]\n        ] = []\n\n        # Node IDs that were expanded when the user last switched away from\n        # tree mode.  Restored row-by-row as data is (re-)loaded in tree mode.\n        self._expanded_node_ids: set[str] = set()\n\n        # Open persistent editors for already-loaded children when a tree node\n        # is expanded.  Complements _on_rows_inserted, which handles the case\n        # where data is loaded after the node is already expanded (async mode).\n        self.expanded.connect(self._schedule_editor_sync)\n\n    def _sync_viewport_palette(self) -&gt; None:\n        \"\"\"Apply the variant background colour to the viewport.\"\"\"\n        style = get_ayon_style()\n        tbl_style = style.model.get_style(\"AYTableView\", self._variant_str)\n        bg = QColor(tbl_style.get(\"background-color\", \"#252a31\"))\n        p = self.viewport().palette()\n        p.setColor(QPalette.ColorRole.Base, bg)\n        p.setColor(QPalette.ColorRole.Window, bg)\n        self.viewport().setPalette(p)\n\n    def paintEvent(self, event: QPaintEvent) -&gt; None:\n        \"\"\"Draw the outer container background before items.\n\n        Args:\n            event: The paint event.\n        \"\"\"\n        painter = QPainter(self.viewport())\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing, False)\n        style = get_ayon_style()\n        tbl_style = style.model.get_style(\"AYTableView\", self._variant_str)\n        bg = QColor(tbl_style.get(\"background-color\", \"#252a31\"))\n        painter.fillRect(self.viewport().rect(), bg)\n        painter.end()\n\n        super().paintEvent(event)\n\n    def setModel(self, model: QtCore.QAbstractItemModel | None) -&gt; None:\n        \"\"\"Set the data model and configure header and widgets.\n\n        Args:\n            model: The data model to display.\n        \"\"\"\n        # Disconnect previous model signals.\n        for obj, conn in self._model_connections:\n            try:\n                obj.disconnect(conn)\n            except (RuntimeError, TypeError):\n                pass\n        self._model_connections.clear()\n\n        # Clear viewport-editor tracking \u2014 the old model's editors are\n        # invalidated by the model swap.\n        self._active_editor_pmis.clear()\n        self._editor_sync_timer.stop()\n\n        super().setModel(model)\n\n        if model is None:\n            return\n\n        # Configure header from column width hints.\n        self._configure_header(model)\n\n        # Schedule viewport-aware editor opening for existing rows.\n        self._schedule_editor_sync()\n\n        # Connect to rowsInserted for lazy-loaded rows.\n        conn = model.rowsInserted.connect(self._on_rows_inserted)\n        if conn is not None:\n            self._model_connections.append((model, conn))\n\n        # Clear editor tracking on model reset so stale PMIs don't linger.\n        conn_reset = model.modelReset.connect(self._on_model_reset)\n        if conn_reset is not None:\n            self._model_connections.append((model, conn_reset))\n\n        # Connect to the source PaginatedTableModel for tree mode changes.\n        source: Any = model\n        if isinstance(model, QSortFilterProxyModel):\n            source = model.sourceModel()\n        if isinstance(source, PaginatedTableModel):\n            conn2 = source.tree_mode_changed.connect(self._apply_tree_mode)\n            if conn2 is not None:\n                self._model_connections.append((source, conn2))\n            self._apply_tree_mode(source._tree_mode)\n\n    def _apply_tree_mode(self, tree_mode: bool) -&gt; None:\n        \"\"\"Configure the view for flat-table or tree display.\n\n        Args:\n            tree_mode: ``True`` to enable tree indentation and expand\n                controls; ``False`` for flat-table layout.\n        \"\"\"\n        if not tree_mode:\n            # Snapshot expansion state before the model resets.\n            self._save_expansion_state()\n        style = get_ayon_style()\n        tbl_style = style.model.get_style(\"AYTableView\", self._variant_str)\n        source = self._source_model()\n        tree_pos = (\n            source.tree_position\n            if isinstance(source, PaginatedTableModel)\n            else 0\n        )\n        if tree_mode:\n            indent = int(tbl_style.get(\"indent\", 16))\n            self.setRootIsDecorated(True)\n            self.setItemsExpandable(True)\n            self.setIndentation(indent)\n        else:\n            self.setRootIsDecorated(False)\n            self.setItemsExpandable(False)\n            self.setIndentation(0)\n        # Set the tree position to the column specified by the model.\n        self.setTreePosition(tree_pos)\n\n    def _source_model(self) -&gt; QtCore.QAbstractItemModel | None:\n        \"\"\"Return the underlying source model, unwrapping any proxy layer.\n\n        Returns:\n            The source model, or ``None`` if no model is set.\n        \"\"\"\n        model = self.model()\n        if isinstance(model, QSortFilterProxyModel):\n            return model.sourceModel()\n        return model\n\n    def _repaint_row(self, row_rect: QRect) -&gt; None:\n        \"\"\"Repaint the full viewport width for a given row rect.\n\n        Args:\n            row_rect: Visual rect of the row to repaint.\n        \"\"\"\n        if row_rect.isNull():\n            return\n        vp = self.viewport()\n        vp.update(QRect(0, row_rect.y(), vp.width(), row_rect.height()))\n\n    def _configure_header(self, model: QtCore.QAbstractItemModel) -&gt; None:\n        \"\"\"Set up header section sizes from model column hints.\n\n        Args:\n            model: The data model (may be a proxy wrapping a\n                :class:`PaginatedTableModel`).\n        \"\"\"\n        header = self.header()\n        if header is None:\n            return\n\n        # Set header height from style.\n        style = get_ayon_style()\n        tbl_style = style.model.get_style(\"AYTableView\", self._variant_str)\n        header_height = int(tbl_style.get(\"header-height\", 36))\n        header.setFixedHeight(header_height)\n\n        # Disable header highlight on selection.\n        header.setHighlightSections(False)\n\n        col_count = model.columnCount()\n        if col_count == 0:\n            return\n\n        # Unwrap proxy to access PaginatedTableModel column definitions.\n        source: Any = model\n        if isinstance(model, QSortFilterProxyModel):\n            source = model.sourceModel()\n\n        # Check if model provides column width hints.\n        has_hints = isinstance(source, PaginatedTableModel) and any(\n            col_def.width &gt; 0 for col_def in source.columns\n        )\n\n        if has_hints:\n            for i, col_def in enumerate(source.columns):\n                if i &gt;= col_count:\n                    break\n                if col_def.width &gt; 0:\n                    header.resizeSection(i, col_def.width)\n                    header.setSectionResizeMode(\n                        i,\n                        QHeaderView.ResizeMode.Interactive,\n                    )\n                else:\n                    header.setSectionResizeMode(\n                        i,\n                        QHeaderView.ResizeMode.Stretch,\n                    )\n        else:\n            # Default: stretch all columns equally.\n            header.setSectionResizeMode(QHeaderView.ResizeMode.Stretch)\n\n        # Enable sorting.\n        # setSectionsClickable enables header click interaction (indicator\n        # toggling + sortIndicatorChanged signal) without QTreeView's internal\n        # sortIndicatorChanged \u2192 model.sort() connection that setSortingEnabled\n        # would create behind our guard.\n        header.setSectionsClickable(True)\n        header.setSortIndicatorShown(True)\n        if isinstance(source, PaginatedTableModel):\n            header.sortIndicatorChanged.connect(\n                lambda section, order: self._on_sort_indicator_changed(\n                    section, order, source\n                )\n            )\n\n    def _on_sort_indicator_changed(\n        self, section: int, order: Qt.SortOrder, model: PaginatedTableModel\n    ) -&gt; None:\n        cols = model.columns\n        if 0 &lt;= section &lt; len(cols) and not cols[section].sortable:\n            header = self.header()\n            header.blockSignals(True)\n            if 0 &lt;= model._sort_column &lt; len(cols):\n                header.setSortIndicator(model._sort_column, model._sort_order)\n            else:\n                header.setSortIndicatorShown(False)\n            header.blockSignals(False)\n            return\n        # Sortable column \u2014 delegate to the model.\n        model.sort(section, order)\n        # model.sort() triggers beginResetModel/endResetModel, which causes\n        # QHeaderView.initializeSections() to wipe the sort indicator state.\n        # Re-apply it explicitly after the reset.\n        header = self.header()\n        header.blockSignals(True)\n        header.setSortIndicatorShown(True)\n        header.setSortIndicator(section, order)\n        header.blockSignals(False)\n\n    def _save_expansion_state(self) -&gt; None:\n        \"\"\"Snapshot the node IDs of all expanded rows into ``_expanded_node_ids``.\n\n        Called just before the model resets when switching from tree to flat\n        mode, while the tree is still fully populated.\n        \"\"\"\n        self._expanded_node_ids.clear()\n        display_model = self.model()\n        if display_model is None:\n            return\n        is_proxy = isinstance(display_model, QSortFilterProxyModel)\n\n        def _collect(parent_view_idx: QModelIndex) -&gt; None:\n            for row in range(display_model.rowCount(parent_view_idx)):\n                child_view_idx = display_model.index(row, 0, parent_view_idx)\n                if not self.isExpanded(child_view_idx):\n                    continue\n                src_idx = (\n                    display_model.mapToSource(child_view_idx)  # type: ignore[union-attr]\n                    if is_proxy\n                    else child_view_idx\n                )\n                node = src_idx.internalPointer()\n                if node is not None and node.node_id is not None:\n                    self._expanded_node_ids.add(node.node_id)\n                _collect(child_view_idx)\n\n        _collect(QModelIndex())\n\n    def _restore_expansion_in_range(\n        self,\n        parent: QModelIndex,\n        first: int,\n        last: int,\n    ) -&gt; None:\n        \"\"\"Expand any newly-inserted rows whose node ID was previously saved.\n\n        Expanding a row triggers lazy child loading which fires more\n        ``rowsInserted`` signals, so the full expansion tree is restored\n        incrementally without extra bookkeeping.\n\n        Args:\n            parent: Parent index of the inserted rows.\n            first: First inserted row index.\n            last: Last inserted row index.\n        \"\"\"\n        if not self._expanded_node_ids:\n            return\n        display_model = self.model()\n        if display_model is None:\n            return\n        source = (\n            display_model.sourceModel()\n            if isinstance(display_model, QSortFilterProxyModel)\n            else display_model\n        )\n        if not isinstance(source, PaginatedTableModel):\n            return\n        if not source._tree_mode:\n            return\n        is_proxy = isinstance(display_model, QSortFilterProxyModel)\n        for row in range(first, last + 1):\n            child_view_idx = display_model.index(row, 0, parent)\n            src_idx = (\n                display_model.mapToSource(child_view_idx)\n                if is_proxy\n                else child_view_idx\n            )\n            node = src_idx.internalPointer()\n            if node is not None and node.node_id in self._expanded_node_ids:\n                self.expand(child_view_idx)\n\n    def _on_rows_inserted(\n        self,\n        parent: QModelIndex,\n        first: int,\n        last: int,\n    ) -&gt; None:\n        \"\"\"Open persistent editors and restore expansion for newly inserted rows.\n\n        Args:\n            parent: Parent index; supports non-root parents in tree mode.\n            first: First inserted row index.\n            last: Last inserted row index.\n        \"\"\"\n        self._schedule_editor_sync()\n        self._restore_expansion_in_range(parent, first, last)\n\n    # ------------------------------------------------------------------\n    # Viewport-aware persistent-editor helpers\n    # ------------------------------------------------------------------\n\n    def _schedule_editor_sync(self) -&gt; None:\n        \"\"\"Schedule :meth:`_sync_viewport_editors` on the next event loop.\n\n        Multiple calls within the same event-loop iteration collapse into\n        a single sync because the timer is single-shot and we only start\n        it when it is not already active.\n        \"\"\"\n        if not self._editor_sync_timer.isActive():\n            self._editor_sync_timer.start()\n\n    def _on_model_reset(self) -&gt; None:\n        \"\"\"Clear editor tracking after a model reset.\n\n        Qt automatically closes all persistent editors on\n        ``beginResetModel``, so ``_active_editor_pmis`` would hold stale\n        entries.  Clearing it ensures :meth:`_sync_viewport_editors` starts\n        from a clean slate, then schedules a sync so visible rows get their\n        editors back.\n        \"\"\"\n        self._active_editor_pmis.clear()\n        self._schedule_editor_sync()\n\n    def _get_visible_widget_indexes(self) -&gt; list[QModelIndex]:\n        \"\"\"Return display-model indexes for visible cells with widget factories.\n\n        Uses :meth:`QTreeView.indexBelow` to walk visible rows from the\n        topmost visible item downwards, stopping as soon as the visual rect\n        passes the viewport bottom.  Works correctly in both flat and tree\n        mode.\n\n        Returns:\n            List of valid ``QModelIndex`` objects, one per (row, col) pair\n            that is both visible and belongs to a widget-factory column.\n        \"\"\"\n        model = self.model()\n        if model is None:\n            return []\n        source: Any = self._source_model()\n        if not isinstance(source, PaginatedTableModel):\n            return []\n        widget_cols = [\n            i\n            for i, col in enumerate(source.columns)\n            if col.widget_factory is not None\n        ]\n        if not widget_cols:\n            return []\n\n        vp_rect = self.viewport().rect()\n        # indexAt() returns an invalid index when the viewport is empty.\n        top_idx = self.indexAt(\n            QtCore.QPoint(vp_rect.left(), vp_rect.top() + 1)\n        )\n        if not top_idx.isValid():\n            return []\n        # Normalise to column 0 so indexBelow() works predictably.\n        top_idx = model.index(top_idx.row(), 0, top_idx.parent())\n\n        results: list[QModelIndex] = []\n        idx = top_idx\n        while idx.isValid():\n            visual = self.visualRect(idx)\n            if visual.top() &gt; vp_rect.bottom():\n                break\n            if not visual.isEmpty():\n                for col in widget_cols:\n                    col_idx = model.index(idx.row(), col, idx.parent())\n                    if col_idx.isValid():\n                        results.append(col_idx)\n            idx = self.indexBelow(idx)\n\n        return results\n\n    def _sync_viewport_editors(self) -&gt; None:\n        \"\"\"Open persistent editors for rows that just became visible.\n\n        Called via :attr:`_editor_sync_timer` (single-shot, zero interval)\n        so that bursts of ``rowsInserted`` signals collapse into a single\n        call per event-loop iteration.  Also triggered on vertical scroll.\n\n        Uses an **open-only** strategy: opens editors for visible rows that\n        do not yet have one, but never closes editors for rows that have\n        scrolled out of view.  A dormant off-screen persistent editor costs\n        near zero (Qt skips its ``paintEvent``), while re-creating it on\n        scroll-back would cause widget churn and redundant thumbnail\n        re-fetches.\n\n        :attr:`_active_editor_pmis` grows monotonically within a model\n        lifetime and is reset by :meth:`_on_model_reset` so stale entries\n        from a previous model do not block new editors after a reset.\n        \"\"\"\n        for idx in self._get_visible_widget_indexes():\n            pmi = QtCore.QPersistentModelIndex(idx)\n            if pmi.isValid() and pmi not in self._active_editor_pmis:\n                self.openPersistentEditor(pmi)  # type: ignore[arg-type]\n                self._active_editor_pmis.add(pmi)\n\n    def mouseMoveEvent(self, event: \"QtGui.QMouseEvent\") -&gt; None:  # type: ignore[override]\n        \"\"\"Track the hovered row and force-repaint it when it changes.\n\n        Qt only invalidates the cell directly under the cursor on hover\n        transitions.  The branch-indicator area (PE_IndicatorBranch) is\n        outside that cell rect, so it never receives a repaint request when\n        the cursor moves to a new row.  We force the viewport to repaint the\n        full width of the previously-hovered row so the indicator clears.\n        \"\"\"\n        new_idx = self.indexAt(event.pos())\n        new_row = new_idx.row() if new_idx.isValid() else -1\n        if new_row != self._hovered_row:\n            # Repaint the old row so its indicator clears.\n            self._repaint_row(self._hovered_row_rect)\n            self._hovered_row = new_row\n            self._hovered_row_rect = (\n                self.visualRect(new_idx) if new_idx.isValid() else QRect()\n            )\n            # Repaint the new row so its indicator lights up immediately.\n            self._repaint_row(self._hovered_row_rect)\n        super().mouseMoveEvent(event)\n\n    def leaveEvent(self, event: \"QtCore.QEvent\") -&gt; None:\n        \"\"\"Clear hover tracking when the mouse exits the widget.\"\"\"\n        self._repaint_row(self._hovered_row_rect)\n        self._hovered_row = -1\n        self._hovered_row_rect = QRect()\n        super().leaveEvent(event)\n\n    def selectionChanged(\n        self,\n        selected: QItemSelection,\n        deselected: QItemSelection,\n    ) -&gt; None:\n        \"\"\"Override to emit a public signal on selection change.\n\n        Args:\n            selected: Newly selected items.\n            deselected: Newly deselected items.\n        \"\"\"\n        super().selectionChanged(selected, deselected)\n        self.selection_changed.emit(selected, deselected)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_view.html#client.ayon_ui_qt.components.table_view.AYTableView.leaveEvent","title":"<code>leaveEvent(event)</code>","text":"<p>Clear hover tracking when the mouse exits the widget.</p> Source code in <code>client/ayon_ui_qt/components/table_view.py</code> <pre><code>def leaveEvent(self, event: \"QtCore.QEvent\") -&gt; None:\n    \"\"\"Clear hover tracking when the mouse exits the widget.\"\"\"\n    self._repaint_row(self._hovered_row_rect)\n    self._hovered_row = -1\n    self._hovered_row_rect = QRect()\n    super().leaveEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_view.html#client.ayon_ui_qt.components.table_view.AYTableView.mouseMoveEvent","title":"<code>mouseMoveEvent(event)</code>","text":"<p>Track the hovered row and force-repaint it when it changes.</p> <p>Qt only invalidates the cell directly under the cursor on hover transitions.  The branch-indicator area (PE_IndicatorBranch) is outside that cell rect, so it never receives a repaint request when the cursor moves to a new row.  We force the viewport to repaint the full width of the previously-hovered row so the indicator clears.</p> Source code in <code>client/ayon_ui_qt/components/table_view.py</code> <pre><code>def mouseMoveEvent(self, event: \"QtGui.QMouseEvent\") -&gt; None:  # type: ignore[override]\n    \"\"\"Track the hovered row and force-repaint it when it changes.\n\n    Qt only invalidates the cell directly under the cursor on hover\n    transitions.  The branch-indicator area (PE_IndicatorBranch) is\n    outside that cell rect, so it never receives a repaint request when\n    the cursor moves to a new row.  We force the viewport to repaint the\n    full width of the previously-hovered row so the indicator clears.\n    \"\"\"\n    new_idx = self.indexAt(event.pos())\n    new_row = new_idx.row() if new_idx.isValid() else -1\n    if new_row != self._hovered_row:\n        # Repaint the old row so its indicator clears.\n        self._repaint_row(self._hovered_row_rect)\n        self._hovered_row = new_row\n        self._hovered_row_rect = (\n            self.visualRect(new_idx) if new_idx.isValid() else QRect()\n        )\n        # Repaint the new row so its indicator lights up immediately.\n        self._repaint_row(self._hovered_row_rect)\n    super().mouseMoveEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_view.html#client.ayon_ui_qt.components.table_view.AYTableView.paintEvent","title":"<code>paintEvent(event)</code>","text":"<p>Draw the outer container background before items.</p> <p>Parameters:</p> Name Type Description Default <code>event</code> <code>QPaintEvent</code> <p>The paint event.</p> required Source code in <code>client/ayon_ui_qt/components/table_view.py</code> <pre><code>def paintEvent(self, event: QPaintEvent) -&gt; None:\n    \"\"\"Draw the outer container background before items.\n\n    Args:\n        event: The paint event.\n    \"\"\"\n    painter = QPainter(self.viewport())\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing, False)\n    style = get_ayon_style()\n    tbl_style = style.model.get_style(\"AYTableView\", self._variant_str)\n    bg = QColor(tbl_style.get(\"background-color\", \"#252a31\"))\n    painter.fillRect(self.viewport().rect(), bg)\n    painter.end()\n\n    super().paintEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_view.html#client.ayon_ui_qt.components.table_view.AYTableView.selectionChanged","title":"<code>selectionChanged(selected, deselected)</code>","text":"<p>Override to emit a public signal on selection change.</p> <p>Parameters:</p> Name Type Description Default <code>selected</code> <code>QItemSelection</code> <p>Newly selected items.</p> required <code>deselected</code> <code>QItemSelection</code> <p>Newly deselected items.</p> required Source code in <code>client/ayon_ui_qt/components/table_view.py</code> <pre><code>def selectionChanged(\n    self,\n    selected: QItemSelection,\n    deselected: QItemSelection,\n) -&gt; None:\n    \"\"\"Override to emit a public signal on selection change.\n\n    Args:\n        selected: Newly selected items.\n        deselected: Newly deselected items.\n    \"\"\"\n    super().selectionChanged(selected, deselected)\n    self.selection_changed.emit(selected, deselected)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/table_view.html#client.ayon_ui_qt.components.table_view.AYTableView.setModel","title":"<code>setModel(model)</code>","text":"<p>Set the data model and configure header and widgets.</p> <p>Parameters:</p> Name Type Description Default <code>model</code> <code>QAbstractItemModel | None</code> <p>The data model to display.</p> required Source code in <code>client/ayon_ui_qt/components/table_view.py</code> <pre><code>def setModel(self, model: QtCore.QAbstractItemModel | None) -&gt; None:\n    \"\"\"Set the data model and configure header and widgets.\n\n    Args:\n        model: The data model to display.\n    \"\"\"\n    # Disconnect previous model signals.\n    for obj, conn in self._model_connections:\n        try:\n            obj.disconnect(conn)\n        except (RuntimeError, TypeError):\n            pass\n    self._model_connections.clear()\n\n    # Clear viewport-editor tracking \u2014 the old model's editors are\n    # invalidated by the model swap.\n    self._active_editor_pmis.clear()\n    self._editor_sync_timer.stop()\n\n    super().setModel(model)\n\n    if model is None:\n        return\n\n    # Configure header from column width hints.\n    self._configure_header(model)\n\n    # Schedule viewport-aware editor opening for existing rows.\n    self._schedule_editor_sync()\n\n    # Connect to rowsInserted for lazy-loaded rows.\n    conn = model.rowsInserted.connect(self._on_rows_inserted)\n    if conn is not None:\n        self._model_connections.append((model, conn))\n\n    # Clear editor tracking on model reset so stale PMIs don't linger.\n    conn_reset = model.modelReset.connect(self._on_model_reset)\n    if conn_reset is not None:\n        self._model_connections.append((model, conn_reset))\n\n    # Connect to the source PaginatedTableModel for tree mode changes.\n    source: Any = model\n    if isinstance(model, QSortFilterProxyModel):\n        source = model.sourceModel()\n    if isinstance(source, PaginatedTableModel):\n        conn2 = source.tree_mode_changed.connect(self._apply_tree_mode)\n        if conn2 is not None:\n            self._model_connections.append((source, conn2))\n        self._apply_tree_mode(source._tree_mode)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag.html","title":"tag","text":""},{"location":"autoapi/client/ayon_ui_qt/components/tag.html#client.ayon_ui_qt.components.tag.AYTag","title":"<code>AYTag</code>","text":"<p>               Bases: <code>AYFrame</code></p> <p>A widget used to display a tag as a pill with a color and text, a delete and an expand button.</p> Source code in <code>client/ayon_ui_qt/components/tag.py</code> <pre><code>class AYTag(AYFrame):\n    \"\"\"A widget used to display a tag as a pill with a color and text,\n    a delete and an expand button.\"\"\"\n\n    tag_removed = QtCore.Signal(str)\n    tag_expanded = QtCore.Signal(str)\n\n    def __init__(\n        self,\n        name: str,\n        color: QtGui.QColor,\n        label: str | None = None,\n        parent=None,\n    ):\n        super().__init__(parent, variant=QFrameVariants.Tag, margin=0)\n        self._tag_name = name\n        self._tag_label = label\n        self._bg_color = color\n        self._fg_color = (\n            QtGui.QColor(\"#ffffff\")\n            if color.lightness() &lt; 128\n            else QtGui.QColor(\"#000000\")\n        )\n        self._fg_hover_color = (\n            QtGui.QColor(\"#000000\")\n            if color.lightness() &lt; 128\n            else QtGui.QColor(\"#ffffff\")\n        )\n        self.init_ui()\n\n    @property\n    def background_color(self) -&gt; QtGui.QColor:\n        return self._bg_color\n\n    def init_ui(self):\n        self.lyt = QtWidgets.QHBoxLayout(self)\n        self.lyt.setContentsMargins(2, 2, 2, 2)\n        self.lyt.setSpacing(4)\n        self.lyt.setSizeConstraint(\n            QtWidgets.QLayout.SizeConstraint.SetMinimumSize\n        )\n\n        self.delete_button = AYButton(\n            icon=\"close\",\n            icon_color=self._fg_color.name(),\n            icon_size=16,\n            variant=AYButton.Variants.Tag,\n            contrast_color=self.background_color,\n            tooltip=f\"Remove tag {self._tag_name!r}\",\n        )\n\n        self.label = AYLabel(\n            self._tag_label or self._tag_name,\n            variant=AYLabel.Variants.Tag,\n            contrast_color=self.background_color,\n        )\n        self.label.setSizePolicy(\n            QtWidgets.QSizePolicy.Policy.Minimum,\n            QtWidgets.QSizePolicy.Policy.Minimum,\n        )\n\n        self.expand_button = AYButton(\n            icon=\"arrow_drop_down\",\n            icon_color=self._fg_color.name(),\n            icon_size=16,\n            variant=AYButton.Variants.Tag,\n            contrast_color=self.background_color,\n            tooltip=f\"Expand tag {self._tag_name!r}\",\n        )\n\n        self.lyt.addWidget(self.delete_button)\n        self.lyt.addWidget(self.label)\n        self.lyt.addWidget(self.expand_button)\n\n        self.delete_button.clicked.connect(self._delete_tag)\n        self.expand_button.clicked.connect(self._expand_tag)\n\n    def _delete_tag(self):\n        self.tag_removed.emit(self._tag_name)\n\n    def _expand_tag(self):\n        self.tag_expanded.emit(self._tag_name)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html","title":"tag_selector","text":"<p>Tag selector component for displaying and managing tags.</p> <p>This module provides an AYTagSelector widget that displays a button with selected tags as badges, and opens a floating dropdown for tag selection.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.AYTagSelector","title":"<code>AYTagSelector</code>","text":"<p>               Bases: <code>QWidget</code></p> <p>A tag selector widget with button and floating dropdown.</p> <p>Displays a button with a tag icon. When tags are selected, they appear as badges next to the button. Clicking the button opens a floating dropdown for tag selection.</p> <p>Attributes:</p> Name Type Description <code>tags_changed</code> <p>Signal emitted when selected tags change.</p> Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>class AYTagSelector(QWidget):\n    \"\"\"A tag selector widget with button and floating dropdown.\n\n    Displays a button with a tag icon. When tags are selected, they appear\n    as badges next to the button. Clicking the button opens a floating\n    dropdown for tag selection.\n\n    Attributes:\n        tags_changed: Signal emitted when selected tags change.\n    \"\"\"\n\n    tags_changed = Signal(list)\n\n    def __init__(\n        self,\n        available_tags: list[TagData] | list[dict] | list[str] | None = None,\n        selected_tags: list[str] | None = None,\n        max_visible_tags: int = 4,\n        min_width: int = 200,\n        parent: QWidget | None = None,\n    ):\n        \"\"\"Initialize the tag selector.\n\n        Args:\n            available_tags: List of available tags. Can be TagData objects,\n                dicts with 'name' and 'color' keys, or simple strings.\n            selected_tags: List of initially selected tag names.\n            parent: Optional parent widget.\n        \"\"\"\n        super().__init__(parent)\n        self.setStyle(get_ayon_style())\n\n        self._available_tags = self._normalize_tags(available_tags or [])\n        self._selected_tags: list[str] = list(selected_tags or [])\n        self._dropdown: TagDropdown | None = None\n        self._max_visible_tags = max_visible_tags\n        self._min_width = min_width\n\n        self.setSizePolicy(\n            QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed\n        )\n\n        self._build()\n        self._update_badges()\n\n    @staticmethod\n    def _normalize_tags(\n        tags: list[TagData] | list[dict] | list[str],\n    ) -&gt; list[TagData]:\n        \"\"\"Normalize various tag input formats to TagData objects.\n\n        Args:\n            tags: List of tags in any supported format.\n\n        Returns:\n            List of TagData objects.\n        \"\"\"\n        normalized: list[TagData] = []\n        for tag in tags:\n            if isinstance(tag, TagData):\n                normalized.append(tag)\n            elif isinstance(tag, dict):\n                name = tag.get(\"name\") or tag.get(\"text\") or str(tag)\n                color = tag.get(\"color\", \"#8b9198\")\n                normalized.append(TagData(name=name, color=color))\n            else:\n                normalized.append(TagData(name=str(tag)))\n        return sorted(normalized, key=lambda t: t.name.lower())\n\n    def _build(self) -&gt; None:\n        \"\"\"Build the main widget UI layout.\"\"\"\n        self._main_layout = AYHBoxLayout(margin=0, spacing=4)\n        self.setLayout(self._main_layout)\n\n        # Main button with tag icon\n        self._button = AYButton(\n            icon=\"sell\",\n            variant=AYButton.Variants.Nav,\n            tooltip=\"Select tags\",\n        )\n        self._button.clicked.connect(self._show_dropdown)\n        self._main_layout.addWidget(self._button)\n\n        # Container for selected tag badges\n        self._badges_container = AYFrame(variant=AYFrame.Variants.Low)\n        self._badges_layout = AYHBoxLayout(margin=0, spacing=4)\n        self._badges_container.setLayout(self._badges_layout)\n        self._main_layout.addWidget(self._badges_container)\n\n        self._main_layout.addStretch()\n\n    def _update_badges(self) -&gt; None:\n        \"\"\"Update the display of selected tag badges.\"\"\"\n        # Clear existing badges\n        while self._badges_layout.count() &gt; 0:\n            item = self._badges_layout.takeAt(0)\n            widget = item.widget()\n            if widget is not None:\n                widget.deleteLater()\n\n        # Create badges for selected tags\n        tag_color_map = {tag.name: tag.color for tag in self._available_tags}\n        for i, tag_name in enumerate(self._selected_tags):\n            if i &gt;= self._max_visible_tags:\n                remaining_tags = (\n                    len(self._selected_tags) - self._max_visible_tags\n                )\n                badge = AYLabel(\n                    f\"+{remaining_tags}\",\n                    variant=AYLabel.Variants.Default,\n                    rel_text_size=-2,\n                )\n                self._badges_layout.addWidget(badge)\n                break\n            color = tag_color_map.get(tag_name, \"#8b9198\")\n            badge = AYLabel(\n                tag_name,\n                icon_color=color,\n                variant=AYLabel.Variants.Badge,\n                rel_text_size=-2,\n                contrast_color=QColor(color),\n            )\n            self._badges_layout.addWidget(badge)\n\n    def _show_dropdown(self) -&gt; None:\n        \"\"\"Show the floating dropdown for tag selection.\"\"\"\n        if self._dropdown is not None:\n            self._dropdown.close()\n            self._dropdown = None\n            return\n\n        self._dropdown = TagDropdown(\n            tags=self._available_tags,\n            selected_tags=self._selected_tags,\n            min_width=self._min_width,\n            parent=None,\n        )\n        self._dropdown.tag_toggled.connect(self._on_tag_toggled)\n        self._dropdown.add_new_tag.connect(self._on_add_new_tag)\n        self._dropdown.closed.connect(self._on_dropdown_closed)\n\n        # Position dropdown below the button\n        button_pos = self._button.mapToGlobal(QPoint(0, self._button.height()))\n        self._dropdown.move(button_pos)\n        self._dropdown.show()\n\n    def _on_tag_toggled(self, tag_name: str, selected: bool) -&gt; None:\n        \"\"\"Handle tag toggle from dropdown.\n\n        Args:\n            tag_name: The name of the toggled tag.\n            selected: Whether the tag is now selected.\n        \"\"\"\n        if selected:\n            if tag_name not in self._selected_tags:\n                self._selected_tags.append(tag_name)\n        else:\n            if tag_name in self._selected_tags:\n                self._selected_tags.remove(tag_name)\n\n        self._update_badges()\n        self.tags_changed.emit(self._selected_tags.copy())\n\n    def _on_add_new_tag(self, tag_name: str) -&gt; None:\n        \"\"\"Handle adding a new tag.\n\n        Args:\n            tag_name: The name of the new tag to add.\n        \"\"\"\n        # Check if tag already exists\n        existing_names = {tag.name.lower() for tag in self._available_tags}\n        if tag_name.lower() in existing_names:\n            logger.warning(\"Tag '%s' already exists\", tag_name)\n            return\n\n        # Add new tag with default color\n        new_tag = TagData(name=tag_name, color=\"#8b9198\")\n        self._available_tags.append(new_tag)\n        self._available_tags.sort(key=lambda t: t.name.lower())\n\n        # Select the new tag\n        if tag_name not in self._selected_tags:\n            self._selected_tags.append(tag_name)\n\n        self._update_badges()\n        self.tags_changed.emit(self._selected_tags.copy())\n\n        # Refresh dropdown if open\n        if self._dropdown:\n            self._dropdown.close()\n            self._show_dropdown()\n\n    def _on_dropdown_closed(self) -&gt; None:\n        \"\"\"Handle dropdown close event.\"\"\"\n        self._dropdown = None\n\n    def get_selected_tags(self) -&gt; list[str]:\n        \"\"\"Get the list of selected tag names.\n\n        Returns:\n            List of selected tag names.\n        \"\"\"\n        return self._selected_tags.copy()\n\n    def set_selected_tags(self, tags: list[str]) -&gt; None:\n        \"\"\"Set the selected tags.\n\n        Args:\n            tags: List of tag names to select.\n        \"\"\"\n        self._selected_tags = list(tags)\n        self._update_badges()\n        self.tags_changed.emit(self._selected_tags.copy())\n\n    def set_available_tags(\n        self,\n        tags: list[TagData] | list[dict] | list[str],\n    ) -&gt; None:\n        \"\"\"Set the available tags.\n\n        Args:\n            tags: List of tags in any supported format.\n        \"\"\"\n        self._available_tags = self._normalize_tags(tags)\n        # Remove selected tags that no longer exist\n        available_names = {tag.name for tag in self._available_tags}\n        self._selected_tags = [\n            t for t in self._selected_tags if t in available_names\n        ]\n        self._update_badges()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.AYTagSelector.__init__","title":"<code>__init__(available_tags=None, selected_tags=None, max_visible_tags=4, min_width=200, parent=None)</code>","text":"<p>Initialize the tag selector.</p> <p>Parameters:</p> Name Type Description Default <code>available_tags</code> <code>list[TagData] | list[dict] | list[str] | None</code> <p>List of available tags. Can be TagData objects, dicts with 'name' and 'color' keys, or simple strings.</p> <code>None</code> <code>selected_tags</code> <code>list[str] | None</code> <p>List of initially selected tag names.</p> <code>None</code> <code>parent</code> <code>QWidget | None</code> <p>Optional parent widget.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>def __init__(\n    self,\n    available_tags: list[TagData] | list[dict] | list[str] | None = None,\n    selected_tags: list[str] | None = None,\n    max_visible_tags: int = 4,\n    min_width: int = 200,\n    parent: QWidget | None = None,\n):\n    \"\"\"Initialize the tag selector.\n\n    Args:\n        available_tags: List of available tags. Can be TagData objects,\n            dicts with 'name' and 'color' keys, or simple strings.\n        selected_tags: List of initially selected tag names.\n        parent: Optional parent widget.\n    \"\"\"\n    super().__init__(parent)\n    self.setStyle(get_ayon_style())\n\n    self._available_tags = self._normalize_tags(available_tags or [])\n    self._selected_tags: list[str] = list(selected_tags or [])\n    self._dropdown: TagDropdown | None = None\n    self._max_visible_tags = max_visible_tags\n    self._min_width = min_width\n\n    self.setSizePolicy(\n        QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed\n    )\n\n    self._build()\n    self._update_badges()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.AYTagSelector.get_selected_tags","title":"<code>get_selected_tags()</code>","text":"<p>Get the list of selected tag names.</p> <p>Returns:</p> Type Description <code>list[str]</code> <p>List of selected tag names.</p> Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>def get_selected_tags(self) -&gt; list[str]:\n    \"\"\"Get the list of selected tag names.\n\n    Returns:\n        List of selected tag names.\n    \"\"\"\n    return self._selected_tags.copy()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.AYTagSelector.set_available_tags","title":"<code>set_available_tags(tags)</code>","text":"<p>Set the available tags.</p> <p>Parameters:</p> Name Type Description Default <code>tags</code> <code>list[TagData] | list[dict] | list[str]</code> <p>List of tags in any supported format.</p> required Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>def set_available_tags(\n    self,\n    tags: list[TagData] | list[dict] | list[str],\n) -&gt; None:\n    \"\"\"Set the available tags.\n\n    Args:\n        tags: List of tags in any supported format.\n    \"\"\"\n    self._available_tags = self._normalize_tags(tags)\n    # Remove selected tags that no longer exist\n    available_names = {tag.name for tag in self._available_tags}\n    self._selected_tags = [\n        t for t in self._selected_tags if t in available_names\n    ]\n    self._update_badges()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.AYTagSelector.set_selected_tags","title":"<code>set_selected_tags(tags)</code>","text":"<p>Set the selected tags.</p> <p>Parameters:</p> Name Type Description Default <code>tags</code> <code>list[str]</code> <p>List of tag names to select.</p> required Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>def set_selected_tags(self, tags: list[str]) -&gt; None:\n    \"\"\"Set the selected tags.\n\n    Args:\n        tags: List of tag names to select.\n    \"\"\"\n    self._selected_tags = list(tags)\n    self._update_badges()\n    self.tags_changed.emit(self._selected_tags.copy())\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.TagData","title":"<code>TagData</code>  <code>dataclass</code>","text":"<p>Data class representing a tag with name and color.</p> <p>Attributes:</p> Name Type Description <code>name</code> <code>str</code> <p>The display name of the tag.</p> <code>color</code> <code>str</code> <p>The hex color string for the tag (e.g., \"#4ECDC4\").</p> Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>@dataclass\nclass TagData:\n    \"\"\"Data class representing a tag with name and color.\n\n    Attributes:\n        name: The display name of the tag.\n        color: The hex color string for the tag (e.g., \"#4ECDC4\").\n    \"\"\"\n\n    name: str\n    color: str = \"#8b9198\"\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.TagDropdown","title":"<code>TagDropdown</code>","text":"<p>               Bases: <code>AYContainer</code></p> <p>A floating dropdown window for tag selection.</p> <p>Features a search field and a scrollable list of tags. New tags can be created by typing a non-existing tag name and pressing Enter.</p> <p>Attributes:</p> Name Type Description <code>tag_toggled</code> <p>Signal emitted when a tag is toggled (name, selected).</p> <code>add_new_tag</code> <p>Signal emitted when user wants to add a new tag (name).</p> <code>closed</code> <p>Signal emitted when the dropdown is closed.</p> Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>class TagDropdown(AYContainer):\n    \"\"\"A floating dropdown window for tag selection.\n\n    Features a search field and a scrollable list of tags. New tags can be\n    created by typing a non-existing tag name and pressing Enter.\n\n    Attributes:\n        tag_toggled: Signal emitted when a tag is toggled (name, selected).\n        add_new_tag: Signal emitted when user wants to add a new tag (name).\n        closed: Signal emitted when the dropdown is closed.\n    \"\"\"\n\n    tag_toggled = Signal(str, bool)\n    add_new_tag = Signal(str)\n    closed = Signal()\n\n    def __init__(\n        self,\n        tags: list[TagData],\n        selected_tags: list[str],\n        min_width: int = 200,\n        parent: QWidget | None = None,\n    ):\n        \"\"\"Initialize the dropdown window.\n\n        Args:\n            tags: List of all available tags.\n            selected_tags: List of currently selected tag names.\n            parent: Optional parent widget.\n        \"\"\"\n        super().__init__(\n            parent,\n            layout=AYContainer.Layout.VBox,\n            variant=AYContainer.Variants.Low_Framed,\n            layout_margin=1,\n        )\n        self._tags = tags\n        self._selected_tags = set(selected_tags)\n        self._tag_widgets: dict[str, TagItemWidget] = {}\n\n        self.setWindowFlags(\n            Qt.WindowType.Popup\n            | Qt.WindowType.FramelessWindowHint\n            | Qt.WindowType.NoDropShadowWindowHint\n        )\n        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, False)\n        self.setMinimumWidth(min_width)\n        self.setMaximumHeight(400)\n\n        self._build()\n\n    def _build(self) -&gt; None:\n        \"\"\"Build the dropdown UI layout.\"\"\"\n\n        # Search field with icon\n        search_container = AYContainer(\n            layout=AYContainer.Layout.HBox,\n            variant=AYFrame.Variants.Low_Square,\n            layout_margin=6,\n            layout_spacing=6,\n        )\n\n        self.search_icon = AYLabel(\n            icon=\"search\",\n            icon_size=18,\n            icon_color=\"#ffffff\",\n            variant=AYLabel.Variants.Default,\n        )\n        search_container.add_widget(self.search_icon)\n\n        self._search_field = AYLineEdit()\n        self._search_field.setPlaceholderText(\"Search tags...\")\n        self._search_field.textChanged.connect(self._on_search_changed)\n        self._search_field.returnPressed.connect(self._on_enter_pressed)\n        search_container.add_widget(self._search_field)\n\n        self.add_widget(search_container)\n\n        # Scrollable tag list\n        scroll_area = QScrollArea()\n        scroll_area.setWidgetResizable(True)\n        scroll_area.setHorizontalScrollBarPolicy(\n            Qt.ScrollBarPolicy.ScrollBarAlwaysOff\n        )\n        scroll_area.setVerticalScrollBarPolicy(\n            Qt.ScrollBarPolicy.ScrollBarAsNeeded\n        )\n        scroll_area.setFrameShape(QFrame.Shape.NoFrame)\n\n        self._tags_container = AYFrame(variant=AYFrame.Variants.Low)\n        self._tags_layout = AYVBoxLayout(margin=0, spacing=0)\n        self._tags_container.setLayout(self._tags_layout)\n        scroll_area.setWidget(self._tags_container)\n\n        self.add_widget(scroll_area)\n\n        # Populate tags\n        self._populate_tags()\n\n    def _populate_tags(self) -&gt; None:\n        \"\"\"Populate the tag list with tag item widgets.\"\"\"\n        if not self._tags:\n            tag = TagData(\"No available tags\", color=\"#ffffff\")\n            tag_widget = TagItemWidget(tag)\n            tag_widget.setEnabled(False)\n            self._tag_widgets[tag.name] = tag_widget\n            self._tags_layout.addWidget(tag_widget)\n            return\n\n        for tag in self._tags:\n            selected = tag.name in self._selected_tags\n            tag_widget = TagItemWidget(tag, selected=selected)\n            tag_widget.tag_clicked.connect(self._on_tag_clicked)\n            self._tag_widgets[tag.name] = tag_widget\n            self._tags_layout.addWidget(tag_widget)\n\n        self._tags_layout.addStretch()\n\n    def _on_search_changed(self, text: str) -&gt; None:\n        \"\"\"Filter tags based on search input.\n\n        Args:\n            text: The current search text.\n        \"\"\"\n        search_lower = text.lower().strip()\n\n        # Show/hide tags based on search\n        for tag_name, widget in self._tag_widgets.items():\n            visible = not search_lower or search_lower in tag_name.lower()\n            widget.setVisible(visible)\n\n        self._adjust_height()\n\n    def _on_enter_pressed(self) -&gt; None:\n        \"\"\"Handle Enter key press to create new tag if it doesn't exist.\"\"\"\n        text = self._search_field.text().strip()\n        if not text:\n            return\n\n        # Check if the tag already exists (case-insensitive)\n        existing_tag = None\n        for tag in self._tags:\n            if tag.name.lower() == text.lower():\n                existing_tag = tag\n                break\n\n        if existing_tag:\n            # Toggle the existing tag\n            widget = self._tag_widgets.get(existing_tag.name)\n            if widget:\n                new_state = not widget.isChecked()\n                widget.setChecked(new_state)\n                if new_state:\n                    self._selected_tags.add(existing_tag.name)\n                else:\n                    self._selected_tags.discard(existing_tag.name)\n                self.tag_toggled.emit(existing_tag.name, new_state)\n        else:\n            # Create new tag\n            self.add_new_tag.emit(text)\n\n        self._search_field.clear()\n\n    def _on_tag_clicked(self, tag_name: str) -&gt; None:\n        \"\"\"Handle tag item click to toggle selection.\n\n        Args:\n            tag_name: The name of the clicked tag.\n        \"\"\"\n        widget = self._tag_widgets.get(tag_name)\n        if widget:\n            new_state = widget.isChecked()\n            if new_state:\n                self._selected_tags.add(tag_name)\n            else:\n                self._selected_tags.discard(tag_name)\n            self.tag_toggled.emit(tag_name, new_state)\n\n    def focusOutEvent(self, event: QFocusEvent) -&gt; None:\n        \"\"\"Handle focus out to close dropdown.\"\"\"\n        # Check if focus is going to a child widget\n        focus_widget = QApplication.focusWidget()\n        if focus_widget and self.isAncestorOf(focus_widget):\n            return\n        self.close()\n        self.closed.emit()\n        super().focusOutEvent(event)\n\n    def get_selected_tags(self) -&gt; list[str]:\n        \"\"\"Return the list of currently selected tag names.\n\n        Returns:\n            List of selected tag names.\n        \"\"\"\n        return list(self._selected_tags)\n\n    def _calculate_content_height(self) -&gt; int:\n        \"\"\"Calculate the ideal height based on visible content.\"\"\"\n        search_height = 40  # search field + margins\n\n        tags_height = 0\n        for widget in self._tag_widgets.values():\n            if widget.isVisible():\n                tags_height += widget.sizeHint().height()\n\n        margin = 2  # layout_margin from __init__\n        return search_height + tags_height + (margin * 2)\n\n    def _adjust_height(self) -&gt; None:\n        \"\"\"Adjust dropdown height to fit content up to max height.\"\"\"\n        max_height = 400\n        content_height = self._calculate_content_height()\n        self.setFixedHeight(min(content_height, max_height))\n\n    def showEvent(self, event: QShowEvent) -&gt; None:\n        super().showEvent(event)\n        self._search_field.setFocus()\n        self._adjust_height()  # Add this\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.TagDropdown.__init__","title":"<code>__init__(tags, selected_tags, min_width=200, parent=None)</code>","text":"<p>Initialize the dropdown window.</p> <p>Parameters:</p> Name Type Description Default <code>tags</code> <code>list[TagData]</code> <p>List of all available tags.</p> required <code>selected_tags</code> <code>list[str]</code> <p>List of currently selected tag names.</p> required <code>parent</code> <code>QWidget | None</code> <p>Optional parent widget.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>def __init__(\n    self,\n    tags: list[TagData],\n    selected_tags: list[str],\n    min_width: int = 200,\n    parent: QWidget | None = None,\n):\n    \"\"\"Initialize the dropdown window.\n\n    Args:\n        tags: List of all available tags.\n        selected_tags: List of currently selected tag names.\n        parent: Optional parent widget.\n    \"\"\"\n    super().__init__(\n        parent,\n        layout=AYContainer.Layout.VBox,\n        variant=AYContainer.Variants.Low_Framed,\n        layout_margin=1,\n    )\n    self._tags = tags\n    self._selected_tags = set(selected_tags)\n    self._tag_widgets: dict[str, TagItemWidget] = {}\n\n    self.setWindowFlags(\n        Qt.WindowType.Popup\n        | Qt.WindowType.FramelessWindowHint\n        | Qt.WindowType.NoDropShadowWindowHint\n    )\n    self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, False)\n    self.setMinimumWidth(min_width)\n    self.setMaximumHeight(400)\n\n    self._build()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.TagDropdown.focusOutEvent","title":"<code>focusOutEvent(event)</code>","text":"<p>Handle focus out to close dropdown.</p> Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>def focusOutEvent(self, event: QFocusEvent) -&gt; None:\n    \"\"\"Handle focus out to close dropdown.\"\"\"\n    # Check if focus is going to a child widget\n    focus_widget = QApplication.focusWidget()\n    if focus_widget and self.isAncestorOf(focus_widget):\n        return\n    self.close()\n    self.closed.emit()\n    super().focusOutEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.TagDropdown.get_selected_tags","title":"<code>get_selected_tags()</code>","text":"<p>Return the list of currently selected tag names.</p> <p>Returns:</p> Type Description <code>list[str]</code> <p>List of selected tag names.</p> Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>def get_selected_tags(self) -&gt; list[str]:\n    \"\"\"Return the list of currently selected tag names.\n\n    Returns:\n        List of selected tag names.\n    \"\"\"\n    return list(self._selected_tags)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.TagItemWidget","title":"<code>TagItemWidget</code>","text":"<p>               Bases: <code>AYButton</code></p> <p>A clickable tag item widget used in the dropdown list.</p> <p>Displays a tag with its color and handles selection state. Inherits from AYButton to leverage built-in click handling, hover states, and checkable functionality.</p> <p>Attributes:</p> Name Type Description <code>tag_clicked</code> <p>Signal emitted when the tag item is clicked (tag name).</p> Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>class TagItemWidget(AYButton):\n    \"\"\"A clickable tag item widget used in the dropdown list.\n\n    Displays a tag with its color and handles selection state.\n    Inherits from AYButton to leverage built-in click handling,\n    hover states, and checkable functionality.\n\n    Attributes:\n        tag_clicked: Signal emitted when the tag item is clicked (tag name).\n    \"\"\"\n\n    tag_clicked = Signal(str)\n\n    def __init__(\n        self,\n        tag: TagData,\n        selected: bool = False,\n        parent: QWidget | None = None,\n    ):\n        \"\"\"Initialize the tag item widget.\n\n        Args:\n            tag: The TagData object with name and color.\n            selected: Whether the tag is currently selected.\n            parent: Optional parent widget.\n        \"\"\"\n        super().__init__(\n            tag.name,\n            variant=AYButton.Variants.Tag_Menu,\n            fixed_width=False,\n            icon_color=tag.color,\n            checkable=True,\n            parent=parent,\n        )\n        self._tag = tag\n\n        self.setChecked(selected)\n        self.setSizePolicy(\n            QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed\n        )\n\n        # Connect the built-in clicked signal to emit tag name\n        self.clicked.connect(self._on_clicked)\n\n    def _on_clicked(self) -&gt; None:\n        \"\"\"Handle button click to emit tag_clicked signal with tag name.\"\"\"\n        self.tag_clicked.emit(self._tag.name)\n\n    @property\n    def tag(self) -&gt; TagData:\n        \"\"\"Return the tag data.\"\"\"\n        return self._tag\n\n    @property\n    def selected(self) -&gt; bool:\n        \"\"\"Return the selection state.\"\"\"\n        return self.isChecked()\n\n    @selected.setter\n    def selected(self, value: bool) -&gt; None:\n        \"\"\"Set the selection state.\"\"\"\n        self.setChecked(value)\n\n    @property\n    def tag_color(self) -&gt; str:\n        \"\"\"Return the tag color.\"\"\"\n        return self._tag.color\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.TagItemWidget.selected","title":"<code>selected</code>  <code>property</code> <code>writable</code>","text":"<p>Return the selection state.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.TagItemWidget.tag","title":"<code>tag</code>  <code>property</code>","text":"<p>Return the tag data.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.TagItemWidget.tag_color","title":"<code>tag_color</code>  <code>property</code>","text":"<p>Return the tag color.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/tag_selector.html#client.ayon_ui_qt.components.tag_selector.TagItemWidget.__init__","title":"<code>__init__(tag, selected=False, parent=None)</code>","text":"<p>Initialize the tag item widget.</p> <p>Parameters:</p> Name Type Description Default <code>tag</code> <code>TagData</code> <p>The TagData object with name and color.</p> required <code>selected</code> <code>bool</code> <p>Whether the tag is currently selected.</p> <code>False</code> <code>parent</code> <code>QWidget | None</code> <p>Optional parent widget.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/tag_selector.py</code> <pre><code>def __init__(\n    self,\n    tag: TagData,\n    selected: bool = False,\n    parent: QWidget | None = None,\n):\n    \"\"\"Initialize the tag item widget.\n\n    Args:\n        tag: The TagData object with name and color.\n        selected: Whether the tag is currently selected.\n        parent: Optional parent widget.\n    \"\"\"\n    super().__init__(\n        tag.name,\n        variant=AYButton.Variants.Tag_Menu,\n        fixed_width=False,\n        icon_color=tag.color,\n        checkable=True,\n        parent=parent,\n    )\n    self._tag = tag\n\n    self.setChecked(selected)\n    self.setSizePolicy(\n        QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed\n    )\n\n    # Connect the built-in clicked signal to emit tag name\n    self.clicked.connect(self._on_clicked)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html","title":"task_queue","text":"<p>Priority-based async task queue backed by a dispatch QThread + worker pool.</p> <p>This module provides a generic priority-based task queue system.  A single dispatch <code>QThread</code> dequeues tasks from a <code>PriorityQueue</code> and submits them to a <code>ThreadPoolExecutor</code>  (default: 4 workers) so that independent fetches \u2014 for instance all children of simultaneously-expanded tree nodes \u2014 run in parallel rather than serially.</p> <p>Key optimisations vs. the original single-worker design:</p> <ul> <li>No polling sleep - the dispatch loop blocks on a <code>threading.Event</code>   that is set by :meth:<code>AsyncTaskQueue.enqueue</code> the instant a new task   arrives, so there is zero idle wait between tree-expansion waves.</li> <li>Parallel execution - up to <code>num_workers</code> fetch tasks run at the   same time, halving the effective latency when expanding N sibling nodes   from O(N \u00d7 round-trip) to O(round-trip / num_workers \u00d7 N).</li> </ul> <p>Each task carries an optional <code>context_id</code> label. External components can call :meth:<code>AsyncTaskQueue.clear_context_tasks</code> to remove all pending tasks for a given context when the associated state becomes stale (e.g. a selection change).  Multiple distinct context IDs can coexist in the queue at the same time.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTask","title":"<code>AsyncTask</code>  <code>dataclass</code>","text":"<p>Represents a task to be executed by the async task queue.</p> <p>This class holds all the information needed to execute an asynchronous operation, including the work function, callback, priority, and context tracking for cancellation support.</p> <p>Attributes:</p> Name Type Description <code>name</code> <code>str</code> <p>Descriptive name for the task (e.g., \"fetch_activity_data\").</p> <code>function</code> <code>Callable[[], Any]</code> <p>Callable that performs the work.</p> <code>callback</code> <code>Callable[[Any], None]</code> <p>Function to call with the result when task completes.</p> <code>priority</code> <code>int</code> <p>Priority level (lower numbers = higher priority). 0 = Critical (UI blocking operations) 1 = High (User-initiated operations) 5 = Normal (Background fetches) 10 = Low (Prefetching)</p> <code>context_id</code> <code>str</code> <p>Optional label grouping related tasks. Pass the same id to :meth:<code>AsyncTaskQueue.clear_context_tasks</code> to remove all pending tasks for that group at once.</p> <code>cancellable</code> <code>bool</code> <p>If True, the task can be removed by :meth:<code>AsyncTaskQueue.clear_context_tasks</code>.</p> Example <p>task = AsyncTask(     name=\"fetch_activities\",     function=lambda: fetch_data(context),     callback=on_data_ready,     priority=1,     context_id=\"project:item_id\",     cancellable=True )</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>@dataclass\n@total_ordering\nclass AsyncTask:\n    \"\"\"Represents a task to be executed by the async task queue.\n\n    This class holds all the information needed to execute an asynchronous\n    operation, including the work function, callback, priority, and context\n    tracking for cancellation support.\n\n    Attributes:\n        name: Descriptive name for the task (e.g., \"fetch_activity_data\").\n        function: Callable that performs the work.\n        callback: Function to call with the result when task completes.\n        priority: Priority level (lower numbers = higher priority).\n            0 = Critical (UI blocking operations)\n            1 = High (User-initiated operations)\n            5 = Normal (Background fetches)\n            10 = Low (Prefetching)\n        context_id: Optional label grouping related tasks. Pass the same\n            id to :meth:`AsyncTaskQueue.clear_context_tasks` to remove all\n            pending tasks for that group at once.\n        cancellable: If True, the task can be removed by\n            :meth:`AsyncTaskQueue.clear_context_tasks`.\n\n    Example:\n        task = AsyncTask(\n            name=\"fetch_activities\",\n            function=lambda: fetch_data(context),\n            callback=on_data_ready,\n            priority=1,\n            context_id=\"project:item_id\",\n            cancellable=True\n        )\n    \"\"\"\n\n    name: str\n    function: Callable[[], Any]\n    callback: Callable[[Any], None]\n    priority: int = 5\n    context_id: str = \"\"\n    cancellable: bool = True\n\n    # Internal state\n    _counter: int = field(default=0, init=False, compare=True)\n    _cancelled: bool = field(default=False, init=False, repr=False)\n\n    def cancel(self) -&gt; None:\n        \"\"\"Mark this task as cancelled.\n\n        Only affects the task if cancellable is True.\n        \"\"\"\n        if self.cancellable:\n            self._cancelled = True\n\n    def is_cancelled(self) -&gt; bool:\n        \"\"\"Check if this task has been cancelled.\n\n        Returns:\n            True if the task has been cancelled, False otherwise.\n        \"\"\"\n        return self._cancelled\n\n    def __lt__(self, other: AsyncTask) -&gt; bool:\n        \"\"\"Compare tasks by priority, then by counter for FIFO ordering.\n\n        Args:\n            other: Another AsyncTask to compare with.\n\n        Returns:\n            True if this task should be processed before the other task.\n        \"\"\"\n        if self.priority != other.priority:\n            return self.priority &lt; other.priority\n        return self._counter &lt; other._counter\n\n    def __eq__(self, other: object) -&gt; bool:\n        \"\"\"Check equality based on priority and counter.\n\n        Args:\n            other: Object to compare with.\n\n        Returns:\n            True if tasks have equal priority and counter.\n        \"\"\"\n        if not isinstance(other, AsyncTask):\n            return NotImplemented\n        return (self.priority, self._counter) == (\n            other.priority,\n            other._counter,\n        )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTask.__eq__","title":"<code>__eq__(other)</code>","text":"<p>Check equality based on priority and counter.</p> <p>Parameters:</p> Name Type Description Default <code>other</code> <code>object</code> <p>Object to compare with.</p> required <p>Returns:</p> Type Description <code>bool</code> <p>True if tasks have equal priority and counter.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def __eq__(self, other: object) -&gt; bool:\n    \"\"\"Check equality based on priority and counter.\n\n    Args:\n        other: Object to compare with.\n\n    Returns:\n        True if tasks have equal priority and counter.\n    \"\"\"\n    if not isinstance(other, AsyncTask):\n        return NotImplemented\n    return (self.priority, self._counter) == (\n        other.priority,\n        other._counter,\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTask.__lt__","title":"<code>__lt__(other)</code>","text":"<p>Compare tasks by priority, then by counter for FIFO ordering.</p> <p>Parameters:</p> Name Type Description Default <code>other</code> <code>AsyncTask</code> <p>Another AsyncTask to compare with.</p> required <p>Returns:</p> Type Description <code>bool</code> <p>True if this task should be processed before the other task.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def __lt__(self, other: AsyncTask) -&gt; bool:\n    \"\"\"Compare tasks by priority, then by counter for FIFO ordering.\n\n    Args:\n        other: Another AsyncTask to compare with.\n\n    Returns:\n        True if this task should be processed before the other task.\n    \"\"\"\n    if self.priority != other.priority:\n        return self.priority &lt; other.priority\n    return self._counter &lt; other._counter\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTask.cancel","title":"<code>cancel()</code>","text":"<p>Mark this task as cancelled.</p> <p>Only affects the task if cancellable is True.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def cancel(self) -&gt; None:\n    \"\"\"Mark this task as cancelled.\n\n    Only affects the task if cancellable is True.\n    \"\"\"\n    if self.cancellable:\n        self._cancelled = True\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTask.is_cancelled","title":"<code>is_cancelled()</code>","text":"<p>Check if this task has been cancelled.</p> <p>Returns:</p> Type Description <code>bool</code> <p>True if the task has been cancelled, False otherwise.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def is_cancelled(self) -&gt; bool:\n    \"\"\"Check if this task has been cancelled.\n\n    Returns:\n        True if the task has been cancelled, False otherwise.\n    \"\"\"\n    return self._cancelled\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue","title":"<code>AsyncTaskQueue</code>","text":"<p>               Bases: <code>QThread</code></p> <p>Dispatch thread + pool that processes async tasks from a priority queue.</p> <p>A single <code>QThread</code> (the dispatch loop) continuously dequeues the highest-priority task and submits it to an internal <code>ThreadPoolExecutor</code> so that multiple tasks can execute in parallel.</p> <p>This removes two performance bottlenecks that made multi-level tree expansion slow in the original single-worker design:</p> <ol> <li> <p>No idle polling - instead of sleeping 50 ms when the queue is    empty, the dispatch loop blocks on a <code>threading.Event</code> that    :meth:<code>enqueue</code> sets immediately, so there is zero dead time between    a tree-level's results arriving on the main thread, new    <code>fetchMore</code> calls being enqueued, and those fetches starting.</p> </li> <li> <p>Parallel execution - up to <code>num_workers</code> fetches run    concurrently, so expanding a folder with N children takes    <code>ceil(N / num_workers)</code> round-trips instead of N.</p> </li> </ol> Signals <p>task_completed: Emitted when a task finishes (task_name, result). task_failed: Emitted when a task raises exception (task_name, err). task_cancelled: Emitted when task is cancelled (task_name, ctx_id). queue_empty: Emitted when all tasks are processed.</p> <p>Multiple :attr:<code>~AsyncTask.context_id</code> values can coexist in the queue. Call :meth:<code>clear_context_tasks</code> to remove all pending tasks for a given context when external state changes make them irrelevant.</p> <p>Parameters:</p> Name Type Description Default <code>num_workers</code> <code>int</code> <p>Number of parallel pool workers (default 4).</p> <code>_DEFAULT_NUM_WORKERS</code> <code>parent</code> <code>Any</code> <p>Optional parent QObject.</p> <code>None</code> Example <p>queue = AsyncTaskQueue() queue.task_completed.connect(handle_completion) queue.start()</p> <p>task = AsyncTask(...) queue.enqueue(task)</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>class AsyncTaskQueue(QThread):\n    \"\"\"Dispatch thread + pool that processes async tasks from a priority queue.\n\n    A single ``QThread`` (the *dispatch loop*) continuously dequeues the\n    highest-priority task and submits it to an internal\n    ``ThreadPoolExecutor`` so that multiple tasks can execute in parallel.\n\n    This removes two performance bottlenecks that made multi-level tree\n    expansion slow in the original single-worker design:\n\n    1. **No idle polling** - instead of sleeping 50 ms when the queue is\n       empty, the dispatch loop blocks on a ``threading.Event`` that\n       :meth:`enqueue` sets immediately, so there is zero dead time between\n       a tree-level's results arriving on the main thread, new\n       ``fetchMore`` calls being enqueued, and those fetches starting.\n\n    2. **Parallel execution** - up to ``num_workers`` fetches run\n       concurrently, so expanding a folder with N children takes\n       ``ceil(N / num_workers)`` round-trips instead of N.\n\n    Signals:\n        task_completed: Emitted when a task finishes (task_name, result).\n        task_failed: Emitted when a task raises exception (task_name, err).\n        task_cancelled: Emitted when task is cancelled (task_name, ctx_id).\n        queue_empty: Emitted when all tasks are processed.\n\n    Multiple :attr:`~AsyncTask.context_id` values can coexist in the queue.\n    Call :meth:`clear_context_tasks` to remove all pending tasks for a given\n    context when external state changes make them irrelevant.\n\n    Args:\n        num_workers: Number of parallel pool workers (default 4).\n        parent: Optional parent QObject.\n\n    Example:\n        queue = AsyncTaskQueue()\n        queue.task_completed.connect(handle_completion)\n        queue.start()\n\n        task = AsyncTask(...)\n        queue.enqueue(task)\n\n        # When the context is no longer relevant:\n        queue.clear_context_tasks(context_id)\n\n        # Later...\n        queue.stop()\n    \"\"\"\n\n    # Qt Signals\n    task_completed = Signal(str, object)  # (task_name, result)\n    task_failed = Signal(str, str)  # (task_name, error_message)\n    task_cancelled = Signal(str, str)  # (task_name, context_id)\n    task_enqueued = Signal(str, int)  # (task_name, priority)\n    task_started = Signal(str)  # (task_name)\n    queue_empty = Signal()\n    # No-arg ping signal: tells the main thread to drain _callback_queue.\n    # Never passes Python objects through Qt's cross-thread signal system.\n    invoke_callback = Signal()\n\n    def __init__(\n        self,\n        parent: Any = None,\n        num_workers: int = _DEFAULT_NUM_WORKERS,\n    ) -&gt; None:\n        \"\"\"Initialise the dispatch thread and pool.\n\n        Args:\n            num_workers: Number of parallel pool workers. Defaults to\n                :data:`_DEFAULT_NUM_WORKERS` (4).\n            parent: Optional parent QObject.\n        \"\"\"\n        super().__init__(parent)\n        self._task_queue: queue.PriorityQueue = queue.PriorityQueue()\n        # Thread-safe Python queue for ferrying (callback, result) pairs.\n        # Using Python's own ref-counting rather than Qt's marshaling avoids\n        # PySide6 issues with Python-callable arguments in QueuedConnection.\n        self._callback_queue: queue.SimpleQueue = queue.SimpleQueue()\n        self._running: bool = False\n        self._paused: threading.Event = threading.Event()\n        self._paused.set()  # Start unpaused\n        self._task_counter: int = 0\n        self._counter_lock: threading.Lock = threading.Lock()\n        # Serialises drain-and-rebuild operations in _filter_queue so that\n        # the worker thread cannot dequeue a task between two get_nowait()\n        # calls while the main thread is rebuilding the queue.\n        self._queue_lock: threading.Lock = threading.Lock()\n        # Set by enqueue() to wake the dispatch loop immediately instead of\n        # waiting for the polling timeout.\n        self._task_available: threading.Event = threading.Event()\n        self._num_workers: int = num_workers\n        self._executor: concurrent.futures.ThreadPoolExecutor | None = None\n\n        # Connect the no-arg ping to the drain slot on the main thread.\n        self.invoke_callback.connect(\n            self._drain_callback_queue,\n            Qt.ConnectionType.QueuedConnection,\n        )\n\n    @Slot()\n    def _drain_callback_queue(self) -&gt; None:\n        \"\"\"Process a small batch of pending callbacks, then yield.\n\n        Called via a QueuedConnection so it always runs on the Qt main\n        thread regardless of which thread emitted invoke_callback.\n\n        Up to ``_CALLBACK_BATCH_LIMIT`` callbacks are executed per\n        invocation, subject to a ``_CALLBACK_TIME_BUDGET_MS`` millisecond\n        wall-clock budget.  Stopping after each batch allows the event\n        loop to process paint events, keeping the UI responsive when many\n        async tasks complete simultaneously (e.g. auto-expand with\n        many folders).\n\n        If callbacks remain after the budget is exhausted, a 1 ms\n        single-shot timer re-schedules this method so that paint events\n        can be processed before the next batch.\n        \"\"\"\n        _BATCH_LIMIT = 5\n        _TIME_BUDGET_MS = 8\n\n        t0 = time.monotonic()\n        for _ in range(_BATCH_LIMIT):\n            try:\n                callback, result = self._callback_queue.get_nowait()\n            except queue.Empty:\n                return\n            try:\n                callback(result)\n            except Exception as e:\n                log.exception(\"Callback execution failed: %s\", e)\n            elapsed_ms = (time.monotonic() - t0) * 1000\n            if elapsed_ms &gt;= _TIME_BUDGET_MS:\n                break\n\n        # If more items remain, schedule the next drain after yielding\n        # to the event loop so paint events can be processed.\n        if not self._callback_queue.empty():\n            QTimer.singleShot(1, self._drain_callback_queue)\n\n    def run(self) -&gt; None:\n        \"\"\"Dispatch loop - runs in the QThread context.\n\n        Dequeues the highest-priority pending task and submits it to the\n        thread pool.  Blocks on ``_task_available`` when the queue is empty\n        so it wakes the instant :meth:`enqueue` adds a new task, eliminating\n        the 50 ms polling delay of the previous single-worker design.\n        \"\"\"\n        self._running = True\n        self._executor = concurrent.futures.ThreadPoolExecutor(\n            max_workers=self._num_workers,\n            thread_name_prefix=\"ayon_task_worker\",\n        )\n        log.debug(\n            \"Task queue dispatch loop started (num_workers=%d)\",\n            self._num_workers,\n        )\n\n        try:\n            while self._running:\n                # Wait if paused\n                self._paused.wait()\n\n                try:\n                    # Acquire the queue lock before dequeuing so that\n                    # _filter_queue drain-and-rebuild on the main thread is\n                    # atomic with respect to this get() call.\n                    with self._queue_lock:\n                        try:\n                            priority, task = self._task_queue.get_nowait()\n                        except queue.Empty:\n                            task = None\n\n                    if task is None:\n                        # Block until a new task is enqueued (enqueue() sets\n                        # _task_available) or the 0.5 s safety timeout fires.\n                        # This replaces the original time.sleep(0.05) busy-\n                        # poll, eliminating idle dead-time between expansion\n                        # waves without wasting CPU.\n                        self._task_available.wait(timeout=0.5)\n                        self._task_available.clear()\n                        continue\n\n                    if task.is_cancelled():\n                        log.debug(\"Skipping cancelled task: %s\", task.name)\n                        self.task_cancelled.emit(task.name, task.context_id)\n                        if self._task_queue.empty():\n                            self.queue_empty.emit()\n                        continue\n\n                    log.debug(\n                        \"Submitting task to pool: %s (context=%s)\",\n                        task.name,\n                        task.context_id,\n                    )\n                    self._executor.submit(self._run_task_in_pool, task)\n\n                    if self._task_queue.empty():\n                        self.queue_empty.emit()\n\n                except Exception as e:\n                    log.exception(\"Unexpected error in dispatch loop: %s\", e)\n        finally:\n            # cancel_futures=True (Python \u2265 3.9) drops queued-but-not-\n            # started futures; already-running ones are awaited.\n            self._executor.shutdown(wait=True, cancel_futures=True)\n            self._executor = None\n\n        log.debug(\"Task queue dispatch loop stopped\")\n\n    def _run_task_in_pool(self, task: AsyncTask) -&gt; None:\n        \"\"\"Execute a single task inside a pool worker thread.\n\n        Results are delivered back to the main thread via\n        :meth:`_invoke_callback_safely`.\n\n        Args:\n            task: The task to execute.\n        \"\"\"\n        # Re-check cancellation: the task may have been cancelled while\n        # waiting in the executor's internal work queue.\n        if task.is_cancelled():\n            log.debug(\"Skipping cancelled task (pool): %s\", task.name)\n            return\n\n        log.debug(\n            \"Processing task: %s (context=%s)\", task.name, task.context_id\n        )\n\n        try:\n            self.task_started.emit(task.name)\n        except Exception:\n            log.debug(\n                \"Failed to emit task_started for %s.\", task.name, exc_info=True\n            )\n\n        try:\n            result = task.function()\n\n            # Double-check cancellation after execution.\n            if task.is_cancelled():\n                log.debug(\n                    \"Task %s completed but was cancelled, discarding result\",\n                    task.name,\n                )\n                return\n\n            if task.callback:\n                self._invoke_callback_safely(task.callback, result, task.name)\n\n            try:\n                self.task_completed.emit(task.name, result)\n            except Exception:\n                log.debug(\n                    \"Failed to emit task_completed for %s.\",\n                    task.name,\n                    exc_info=True,\n                )\n\n            log.debug(\"Task completed successfully: %s\", task.name)\n\n        except Exception as e:\n            log.exception(\"Task %s failed: %s\", task.name, e)\n\n            if task.callback:\n                self._invoke_callback_safely(task.callback, None, task.name)\n\n            try:\n                self.task_failed.emit(task.name, str(e))\n            except Exception:\n                log.debug(\n                    \"Failed to emit task_failed for %s.\",\n                    task.name,\n                    exc_info=True,\n                )\n\n    def _invoke_callback_safely(\n        self, callback: Callable, result: Any, task_name: str\n    ) -&gt; None:\n        \"\"\"Invoke callback safely with unified error handling.\n\n        Pushes (callback, result) onto a Python SimpleQueue so that\n        Python callables never travel through Qt's cross-thread\n        signal marshaling (which is unreliable for arbitrary callables\n        in PySide6).  A no-arg ping signal then wakes the main thread.\n\n        Args:\n            callback: The callback function to invoke.\n            result: The result to pass to the callback.\n            task_name: Name of the task (for logging).\n        \"\"\"\n        try:\n            self._callback_queue.put_nowait((callback, result))\n            self.invoke_callback.emit()\n        except Exception as e:\n            log.exception(\n                \"Error invoking callback for %s: %s\",\n                task_name,\n                e,\n            )\n\n    def enqueue(self, task: AsyncTask) -&gt; None:\n        \"\"\"Add a task to the queue (thread-safe).\n\n        Assigns a monotonically increasing counter to the task to ensure\n        FIFO ordering within the same priority level.  Sets\n        ``_task_available`` so the dispatch loop wakes immediately instead\n        of waiting for its polling timeout.\n\n        Args:\n            task: The task to enqueue.\n        \"\"\"\n        # Assign a counter value for FIFO ordering within priority\n        with self._counter_lock:\n            task._counter = self._task_counter\n            self._task_counter += 1\n\n        # Add to priority queue\n        self._task_queue.put((task.priority, task))\n        # Notify observers that a task has been enqueued.\n        try:\n            self.task_enqueued.emit(task.name, task.priority)\n        except Exception:\n            log.debug(\n                \"Failed to emit task_enqueued for %s.\",\n                task.name,\n                exc_info=True,\n            )\n        # Wake the dispatch loop immediately \u2014 no idle wait.\n        self._task_available.set()\n        log.debug(\n            \"Enqueued task: %s (priority=%d, queue_size=%d)\",\n            task.name,\n            task.priority,\n            self._task_queue.qsize(),\n        )\n\n    def pause(self) -&gt; None:\n        \"\"\"Pause task dispatching.\n\n        The dispatch loop finishes submitting the current task and then\n        waits until resumed.  Tasks can still be enqueued while paused.\n        \"\"\"\n        self._paused.clear()\n        log.debug(\"Task queue paused\")\n\n    def resume(self) -&gt; None:\n        \"\"\"Resume task dispatching.\n\n        Dispatching resumes from where it was paused.\n        \"\"\"\n        self._paused.set()\n        log.debug(\"Task queue resumed\")\n\n    def stop(self) -&gt; None:\n        \"\"\"Stop the dispatch thread and pool workers gracefully.\n\n        Sets ``_running = False``, then wakes the dispatch loop so it can\n        exit immediately.  The loop's ``finally`` block shuts the executor\n        down (cancelling queued-but-not-started futures; already-running\n        ones complete normally).  Waits up to 5 seconds for everything to\n        finish.\n\n        Any pending (callback, result) pairs left in ``_callback_queue``\n        are discarded so that stale model callbacks from a previous test\n        (or a discarded context) cannot fire after teardown.\n        \"\"\"\n        log.debug(\"Stopping task queue worker\")\n        self._running = False\n        self._paused.set()  # Unpause if paused\n        # Wake the dispatch loop so it can observe _running=False without\n        # waiting for the 0.5 s timeout.\n        self._task_available.set()\n\n        # Wait for the QThread (dispatch loop + executor shutdown) to finish.\n        if not self.wait(5000):\n            log.warning(\"Task queue worker did not stop within timeout\")\n\n        # Discard any pending callbacks.  Any invoke_callback ping events\n        # already in the Qt event queue will call _drain_callback_queue,\n        # which will safely find an empty queue and return immediately.\n        while True:\n            try:\n                self._callback_queue.get_nowait()\n            except queue.Empty:\n                break\n\n    def is_paused(self) -&gt; bool:\n        \"\"\"Check if the worker is currently paused.\n\n        Returns:\n            True if paused, False otherwise.\n        \"\"\"\n        return not self._paused.is_set()\n\n    def queue_size(self) -&gt; int:\n        \"\"\"Get the current number of tasks in the priority queue.\n\n        Returns:\n            Number of pending tasks (does not include tasks already\n            submitted to the pool).\n        \"\"\"\n        return self._task_queue.qsize()\n\n    def _filter_queue(\n        self, predicate: Callable[[AsyncTask, str], tuple[bool, bool]]\n    ) -&gt; int:\n        \"\"\"Filter queue items based on predicate function.\n\n        Drains queue, applies predicate to each task, and rebuilds queue\n        with filtered items. This is a generic helper for both cancel\n        and clear operations.\n\n        The entire drain-and-rebuild is performed while holding\n        ``_queue_lock`` so that the dispatch thread cannot dequeue a task\n        between two ``get_nowait()`` calls, making the operation atomic\n        with respect to the dispatch loop.\n\n        Note:\n            Tasks already submitted to the pool cannot be removed here;\n            the cancellation flag on :class:`AsyncTask` is the only\n            mechanism that can stop an already-submitted task.\n\n        Args:\n            predicate: Function that takes (task, context_id) and returns\n                (keep_in_queue, emit_cancelled_signal).\n\n        Returns:\n            Number of tasks affected (cancelled or removed).\n        \"\"\"\n        affected_count = 0\n        items_to_keep = []\n\n        with self._queue_lock:\n            while True:\n                try:\n                    priority, task = self._task_queue.get_nowait()\n                    keep, emit_signal = predicate(task, task.context_id)\n\n                    if keep:\n                        items_to_keep.append((priority, task))\n                    else:\n                        affected_count += 1\n                        if emit_signal:\n                            self.task_cancelled.emit(\n                                task.name, task.context_id\n                            )\n\n                except queue.Empty:\n                    break\n\n            # Rebuild queue with remaining items\n            for item in items_to_keep:\n                self._task_queue.put(item)\n\n        return affected_count\n\n    def clear_context_tasks(self, context_id: str) -&gt; int:\n        \"\"\"Completely remove tasks for a specific context from queue.\n\n        More aggressive than cancel - actually removes from queue rather\n        than just marking as cancelled.\n\n        Note:\n            Tasks already submitted to the pool executor (i.e. currently\n            running or waiting for a free pool slot) are *not* removed\n            here.  Their results will be discarded by the model's stale-\n            context check in the callback.\n\n        Args:\n            context_id: Context identifier to clear.\n\n        Returns:\n            Number of tasks removed.\n        \"\"\"\n\n        def should_remove(task: AsyncTask, ctx: str) -&gt; tuple[bool, bool]:\n            \"\"\"Return (keep_in_queue, emit_signal).\"\"\"\n            if task.context_id == context_id and task.cancellable:\n                return (False, True)  # Remove and signal\n            return (True, False)  # Keep, no signal\n\n        removed_count = self._filter_queue(should_remove)\n        if removed_count &gt; 0:\n            log.debug(\n                \"Removed %d tasks for context: %s\",\n                removed_count,\n                context_id,\n            )\n\n        return removed_count\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue--when-the-context-is-no-longer-relevant","title":"When the context is no longer relevant:","text":"<p>queue.clear_context_tasks(context_id)</p>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue--later","title":"Later...","text":"<p>queue.stop()</p>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue.__init__","title":"<code>__init__(parent=None, num_workers=_DEFAULT_NUM_WORKERS)</code>","text":"<p>Initialise the dispatch thread and pool.</p> <p>Parameters:</p> Name Type Description Default <code>num_workers</code> <code>int</code> <p>Number of parallel pool workers. Defaults to :data:<code>_DEFAULT_NUM_WORKERS</code> (4).</p> <code>_DEFAULT_NUM_WORKERS</code> <code>parent</code> <code>Any</code> <p>Optional parent QObject.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def __init__(\n    self,\n    parent: Any = None,\n    num_workers: int = _DEFAULT_NUM_WORKERS,\n) -&gt; None:\n    \"\"\"Initialise the dispatch thread and pool.\n\n    Args:\n        num_workers: Number of parallel pool workers. Defaults to\n            :data:`_DEFAULT_NUM_WORKERS` (4).\n        parent: Optional parent QObject.\n    \"\"\"\n    super().__init__(parent)\n    self._task_queue: queue.PriorityQueue = queue.PriorityQueue()\n    # Thread-safe Python queue for ferrying (callback, result) pairs.\n    # Using Python's own ref-counting rather than Qt's marshaling avoids\n    # PySide6 issues with Python-callable arguments in QueuedConnection.\n    self._callback_queue: queue.SimpleQueue = queue.SimpleQueue()\n    self._running: bool = False\n    self._paused: threading.Event = threading.Event()\n    self._paused.set()  # Start unpaused\n    self._task_counter: int = 0\n    self._counter_lock: threading.Lock = threading.Lock()\n    # Serialises drain-and-rebuild operations in _filter_queue so that\n    # the worker thread cannot dequeue a task between two get_nowait()\n    # calls while the main thread is rebuilding the queue.\n    self._queue_lock: threading.Lock = threading.Lock()\n    # Set by enqueue() to wake the dispatch loop immediately instead of\n    # waiting for the polling timeout.\n    self._task_available: threading.Event = threading.Event()\n    self._num_workers: int = num_workers\n    self._executor: concurrent.futures.ThreadPoolExecutor | None = None\n\n    # Connect the no-arg ping to the drain slot on the main thread.\n    self.invoke_callback.connect(\n        self._drain_callback_queue,\n        Qt.ConnectionType.QueuedConnection,\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue.clear_context_tasks","title":"<code>clear_context_tasks(context_id)</code>","text":"<p>Completely remove tasks for a specific context from queue.</p> <p>More aggressive than cancel - actually removes from queue rather than just marking as cancelled.</p> Note <p>Tasks already submitted to the pool executor (i.e. currently running or waiting for a free pool slot) are not removed here.  Their results will be discarded by the model's stale- context check in the callback.</p> <p>Parameters:</p> Name Type Description Default <code>context_id</code> <code>str</code> <p>Context identifier to clear.</p> required <p>Returns:</p> Type Description <code>int</code> <p>Number of tasks removed.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def clear_context_tasks(self, context_id: str) -&gt; int:\n    \"\"\"Completely remove tasks for a specific context from queue.\n\n    More aggressive than cancel - actually removes from queue rather\n    than just marking as cancelled.\n\n    Note:\n        Tasks already submitted to the pool executor (i.e. currently\n        running or waiting for a free pool slot) are *not* removed\n        here.  Their results will be discarded by the model's stale-\n        context check in the callback.\n\n    Args:\n        context_id: Context identifier to clear.\n\n    Returns:\n        Number of tasks removed.\n    \"\"\"\n\n    def should_remove(task: AsyncTask, ctx: str) -&gt; tuple[bool, bool]:\n        \"\"\"Return (keep_in_queue, emit_signal).\"\"\"\n        if task.context_id == context_id and task.cancellable:\n            return (False, True)  # Remove and signal\n        return (True, False)  # Keep, no signal\n\n    removed_count = self._filter_queue(should_remove)\n    if removed_count &gt; 0:\n        log.debug(\n            \"Removed %d tasks for context: %s\",\n            removed_count,\n            context_id,\n        )\n\n    return removed_count\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue.enqueue","title":"<code>enqueue(task)</code>","text":"<p>Add a task to the queue (thread-safe).</p> <p>Assigns a monotonically increasing counter to the task to ensure FIFO ordering within the same priority level.  Sets <code>_task_available</code> so the dispatch loop wakes immediately instead of waiting for its polling timeout.</p> <p>Parameters:</p> Name Type Description Default <code>task</code> <code>AsyncTask</code> <p>The task to enqueue.</p> required Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def enqueue(self, task: AsyncTask) -&gt; None:\n    \"\"\"Add a task to the queue (thread-safe).\n\n    Assigns a monotonically increasing counter to the task to ensure\n    FIFO ordering within the same priority level.  Sets\n    ``_task_available`` so the dispatch loop wakes immediately instead\n    of waiting for its polling timeout.\n\n    Args:\n        task: The task to enqueue.\n    \"\"\"\n    # Assign a counter value for FIFO ordering within priority\n    with self._counter_lock:\n        task._counter = self._task_counter\n        self._task_counter += 1\n\n    # Add to priority queue\n    self._task_queue.put((task.priority, task))\n    # Notify observers that a task has been enqueued.\n    try:\n        self.task_enqueued.emit(task.name, task.priority)\n    except Exception:\n        log.debug(\n            \"Failed to emit task_enqueued for %s.\",\n            task.name,\n            exc_info=True,\n        )\n    # Wake the dispatch loop immediately \u2014 no idle wait.\n    self._task_available.set()\n    log.debug(\n        \"Enqueued task: %s (priority=%d, queue_size=%d)\",\n        task.name,\n        task.priority,\n        self._task_queue.qsize(),\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue.is_paused","title":"<code>is_paused()</code>","text":"<p>Check if the worker is currently paused.</p> <p>Returns:</p> Type Description <code>bool</code> <p>True if paused, False otherwise.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def is_paused(self) -&gt; bool:\n    \"\"\"Check if the worker is currently paused.\n\n    Returns:\n        True if paused, False otherwise.\n    \"\"\"\n    return not self._paused.is_set()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue.pause","title":"<code>pause()</code>","text":"<p>Pause task dispatching.</p> <p>The dispatch loop finishes submitting the current task and then waits until resumed.  Tasks can still be enqueued while paused.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def pause(self) -&gt; None:\n    \"\"\"Pause task dispatching.\n\n    The dispatch loop finishes submitting the current task and then\n    waits until resumed.  Tasks can still be enqueued while paused.\n    \"\"\"\n    self._paused.clear()\n    log.debug(\"Task queue paused\")\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue.queue_size","title":"<code>queue_size()</code>","text":"<p>Get the current number of tasks in the priority queue.</p> <p>Returns:</p> Type Description <code>int</code> <p>Number of pending tasks (does not include tasks already</p> <code>int</code> <p>submitted to the pool).</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def queue_size(self) -&gt; int:\n    \"\"\"Get the current number of tasks in the priority queue.\n\n    Returns:\n        Number of pending tasks (does not include tasks already\n        submitted to the pool).\n    \"\"\"\n    return self._task_queue.qsize()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue.resume","title":"<code>resume()</code>","text":"<p>Resume task dispatching.</p> <p>Dispatching resumes from where it was paused.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def resume(self) -&gt; None:\n    \"\"\"Resume task dispatching.\n\n    Dispatching resumes from where it was paused.\n    \"\"\"\n    self._paused.set()\n    log.debug(\"Task queue resumed\")\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue.run","title":"<code>run()</code>","text":"<p>Dispatch loop - runs in the QThread context.</p> <p>Dequeues the highest-priority pending task and submits it to the thread pool.  Blocks on <code>_task_available</code> when the queue is empty so it wakes the instant :meth:<code>enqueue</code> adds a new task, eliminating the 50 ms polling delay of the previous single-worker design.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def run(self) -&gt; None:\n    \"\"\"Dispatch loop - runs in the QThread context.\n\n    Dequeues the highest-priority pending task and submits it to the\n    thread pool.  Blocks on ``_task_available`` when the queue is empty\n    so it wakes the instant :meth:`enqueue` adds a new task, eliminating\n    the 50 ms polling delay of the previous single-worker design.\n    \"\"\"\n    self._running = True\n    self._executor = concurrent.futures.ThreadPoolExecutor(\n        max_workers=self._num_workers,\n        thread_name_prefix=\"ayon_task_worker\",\n    )\n    log.debug(\n        \"Task queue dispatch loop started (num_workers=%d)\",\n        self._num_workers,\n    )\n\n    try:\n        while self._running:\n            # Wait if paused\n            self._paused.wait()\n\n            try:\n                # Acquire the queue lock before dequeuing so that\n                # _filter_queue drain-and-rebuild on the main thread is\n                # atomic with respect to this get() call.\n                with self._queue_lock:\n                    try:\n                        priority, task = self._task_queue.get_nowait()\n                    except queue.Empty:\n                        task = None\n\n                if task is None:\n                    # Block until a new task is enqueued (enqueue() sets\n                    # _task_available) or the 0.5 s safety timeout fires.\n                    # This replaces the original time.sleep(0.05) busy-\n                    # poll, eliminating idle dead-time between expansion\n                    # waves without wasting CPU.\n                    self._task_available.wait(timeout=0.5)\n                    self._task_available.clear()\n                    continue\n\n                if task.is_cancelled():\n                    log.debug(\"Skipping cancelled task: %s\", task.name)\n                    self.task_cancelled.emit(task.name, task.context_id)\n                    if self._task_queue.empty():\n                        self.queue_empty.emit()\n                    continue\n\n                log.debug(\n                    \"Submitting task to pool: %s (context=%s)\",\n                    task.name,\n                    task.context_id,\n                )\n                self._executor.submit(self._run_task_in_pool, task)\n\n                if self._task_queue.empty():\n                    self.queue_empty.emit()\n\n            except Exception as e:\n                log.exception(\"Unexpected error in dispatch loop: %s\", e)\n    finally:\n        # cancel_futures=True (Python \u2265 3.9) drops queued-but-not-\n        # started futures; already-running ones are awaited.\n        self._executor.shutdown(wait=True, cancel_futures=True)\n        self._executor = None\n\n    log.debug(\"Task queue dispatch loop stopped\")\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.AsyncTaskQueue.stop","title":"<code>stop()</code>","text":"<p>Stop the dispatch thread and pool workers gracefully.</p> <p>Sets <code>_running = False</code>, then wakes the dispatch loop so it can exit immediately.  The loop's <code>finally</code> block shuts the executor down (cancelling queued-but-not-started futures; already-running ones complete normally).  Waits up to 5 seconds for everything to finish.</p> <p>Any pending (callback, result) pairs left in <code>_callback_queue</code> are discarded so that stale model callbacks from a previous test (or a discarded context) cannot fire after teardown.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def stop(self) -&gt; None:\n    \"\"\"Stop the dispatch thread and pool workers gracefully.\n\n    Sets ``_running = False``, then wakes the dispatch loop so it can\n    exit immediately.  The loop's ``finally`` block shuts the executor\n    down (cancelling queued-but-not-started futures; already-running\n    ones complete normally).  Waits up to 5 seconds for everything to\n    finish.\n\n    Any pending (callback, result) pairs left in ``_callback_queue``\n    are discarded so that stale model callbacks from a previous test\n    (or a discarded context) cannot fire after teardown.\n    \"\"\"\n    log.debug(\"Stopping task queue worker\")\n    self._running = False\n    self._paused.set()  # Unpause if paused\n    # Wake the dispatch loop so it can observe _running=False without\n    # waiting for the 0.5 s timeout.\n    self._task_available.set()\n\n    # Wait for the QThread (dispatch loop + executor shutdown) to finish.\n    if not self.wait(5000):\n        log.warning(\"Task queue worker did not stop within timeout\")\n\n    # Discard any pending callbacks.  Any invoke_callback ping events\n    # already in the Qt event queue will call _drain_callback_queue,\n    # which will safely find an empty queue and return immediately.\n    while True:\n        try:\n            self._callback_queue.get_nowait()\n        except queue.Empty:\n            break\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.get_task_queue","title":"<code>get_task_queue()</code>","text":"<p>Return the shared AsyncTaskQueue, creating and starting it on first use.</p> <p>The queue is a module-level singleton so all components (table models, tree models, etc.) share one dispatch thread and one pool.</p> <p>On first creation the queue is automatically connected to <code>QApplication.aboutToQuit</code> so it stops cleanly when the application exits \u2014 no manual :func:<code>shutdown_task_queue</code> call is required.</p> <p>Returns:</p> Type Description <code>AsyncTaskQueue</code> <p>The running shared :class:<code>AsyncTaskQueue</code> instance.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def get_task_queue() -&gt; AsyncTaskQueue:\n    \"\"\"Return the shared AsyncTaskQueue, creating and starting it on first use.\n\n    The queue is a module-level singleton so all components (table models,\n    tree models, etc.) share one dispatch thread and one pool.\n\n    On first creation the queue is automatically connected to\n    ``QApplication.aboutToQuit`` so it stops cleanly when the application\n    exits \u2014 no manual :func:`shutdown_task_queue` call is required.\n\n    Returns:\n        The running shared :class:`AsyncTaskQueue` instance.\n    \"\"\"\n    global _shared_queue\n    if _shared_queue is None:\n        from qtpy.QtWidgets import QApplication  # local import avoids circular\n\n        _shared_queue = AsyncTaskQueue()\n        _shared_queue.start()\n        log.debug(\"Shared task queue started\")\n\n        app = QApplication.instance()\n        if app is not None:\n            # Guard: connect at most once to avoid accumulating\n            # connections during test runs where the queue is\n            # repeatedly created and destroyed.\n            try:\n                app.aboutToQuit.disconnect(shutdown_task_queue)\n            except RuntimeError:\n                pass  # was not connected yet\n            app.aboutToQuit.connect(shutdown_task_queue)\n        else:\n            log.warning(\n                \"get_task_queue() called before QApplication exists; \"\n                \"automatic shutdown will not be registered.\"\n            )\n\n    return _shared_queue\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue.html#client.ayon_ui_qt.components.task_queue.shutdown_task_queue","title":"<code>shutdown_task_queue()</code>","text":"<p>Stop and discard the shared :class:<code>AsyncTaskQueue</code>.</p> <p>Called automatically when the <code>QApplication</code> emits <code>aboutToQuit</code> (wired by :func:<code>get_task_queue</code> on first use).  Safe to call manually before that if an early teardown is needed; subsequent calls are no-ops.  After this call :func:<code>get_task_queue</code> will create a fresh queue on next access.</p> Source code in <code>client/ayon_ui_qt/components/task_queue.py</code> <pre><code>def shutdown_task_queue() -&gt; None:\n    \"\"\"Stop and discard the shared :class:`AsyncTaskQueue`.\n\n    Called automatically when the ``QApplication`` emits ``aboutToQuit``\n    (wired by :func:`get_task_queue` on first use).  Safe to call\n    manually before that if an early teardown is needed; subsequent calls\n    are no-ops.  After this call :func:`get_task_queue` will create a\n    fresh queue on next access.\n    \"\"\"\n    global _shared_queue\n    if _shared_queue is not None:\n        _shared_queue.stop()\n        _shared_queue = None\n        log.debug(\"Shared task queue stopped\")\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue_monitor.html","title":"task_queue_monitor","text":""},{"location":"autoapi/client/ayon_ui_qt/components/task_queue_monitor.html#client.ayon_ui_qt.components.task_queue_monitor.AsyncTaskQueueMonitor","title":"<code>AsyncTaskQueueMonitor</code>","text":"<p>               Bases: <code>QWidget</code></p> <p>Compact segmented progress bar that mirrors an :class:<code>AsyncTaskQueue</code>.</p> <p>Each task observed from the queue is rendered as a color-coded segment. Segment colors map to priority: high (orange), medium (green), low (blue).  The currently running task pulses to indicate activity.</p> <p>The widget has a fixed maximum height of 24 px and expands horizontally to fill its container.</p> <p>A rich tooltip (shown on hover) reports totals by status, a percentage breakdown per priority bucket, and the name of the currently active task.</p> <p>Redraws are debounced so that bursts of rapid task completions do not cause excessive paint events.</p> <p>Parameters:</p> Name Type Description Default <code>task_queue</code> <code>AsyncTaskQueue</code> <p>The :class:<code>AsyncTaskQueue</code> instance to observe.</p> required <code>update_interval_ms</code> <code>int</code> <p>Debounce interval in milliseconds between successive redraws (default 50 ms).</p> <code>_DEBOUNCE_MS</code> <code>parent</code> <code>Any</code> <p>Optional parent :class:<code>QWidget</code>.</p> <code>None</code> Example <p>::</p> <pre><code>queue = get_task_queue()\nbar = AsyncTaskQueueMonitor(queue)\nlayout.addWidget(bar)\n</code></pre> Source code in <code>client/ayon_ui_qt/components/task_queue_monitor.py</code> <pre><code>class AsyncTaskQueueMonitor(QWidget):\n    \"\"\"Compact segmented progress bar that mirrors an :class:`AsyncTaskQueue`.\n\n    Each task observed from the queue is rendered as a color-coded segment.\n    Segment colors map to priority: high (orange), medium (green), low\n    (blue).  The currently running task pulses to indicate activity.\n\n    The widget has a fixed maximum height of 24 px and expands horizontally\n    to fill its container.\n\n    A rich tooltip (shown on hover) reports totals by status, a percentage\n    breakdown per priority bucket, and the name of the currently active task.\n\n    Redraws are debounced so that bursts of rapid task completions do not\n    cause excessive paint events.\n\n    Args:\n        task_queue: The :class:`AsyncTaskQueue` instance to observe.\n        update_interval_ms: Debounce interval in milliseconds between\n            successive redraws (default 50 ms).\n        parent: Optional parent :class:`QWidget`.\n\n    Example:\n        ::\n\n            queue = get_task_queue()\n            bar = AsyncTaskQueueMonitor(queue)\n            layout.addWidget(bar)\n    \"\"\"\n\n    #: Fixed maximum height in pixels.\n    MAX_HEIGHT: int = 10\n\n    def __init__(\n        self,\n        task_queue: AsyncTaskQueue,\n        update_interval_ms: int = _DEBOUNCE_MS,\n        parent: Any = None,\n    ) -&gt; None:\n        \"\"\"Initialise and connect to *task_queue* signals.\n\n        Args:\n            task_queue: Queue instance to observe.\n            update_interval_ms: Debounce redraw interval in ms.\n            parent: Optional parent widget.\n        \"\"\"\n        super().__init__(parent)\n\n        self._queue: AsyncTaskQueue = task_queue\n        self._tasks: list[_TrackedTask] = []\n        self._pulse_phase: float = 0.0\n\n        # Load style configuration from AYON style system\n        style_data = get_ayon_style_data(\"AsyncTaskQueueMonitor\") or {}\n        if not style_data:\n            log.warning(\n                \"AsyncTaskQueueMonitor: Style data not available, using defaults\"\n            )\n\n        # Colors\n        self._bg_color = QColor(style_data.get(\"background-color\", \"#1c2026\"))\n        self._bg_outline_color = QColor(\n            style_data.get(\"outline-color\", \"#3F4552\")\n        )\n        self._priority_colors = {\n            \"high\": QColor(style_data.get(\"high-priority-color\", \"#E87D0D\")),\n            \"medium\": QColor(\n                style_data.get(\"medium-priority-color\", \"#4CAF50\")\n            ),\n            \"low\": QColor(style_data.get(\"low-priority-color\", \"#2196F3\")),\n        }\n        self._failed_color = QColor(style_data.get(\"failed-color\", \"#F44336\"))\n\n        # Alphas (opacity values)\n        self._completed_alpha = style_data.get(\"completed-alpha\", 0.45)\n        self._pending_alpha = style_data.get(\"pending-alpha\", 0.70)\n\n        # Dimensions\n        self._segment_gap = style_data.get(\"segment-gap\", 2)\n        self._bar_radius = style_data.get(\"bar-radius\", 3)\n\n        # Debounce timer \u2014 single-shot, restarted on every state change.\n        self._update_timer = QTimer(self)\n        self._update_timer.setSingleShot(True)\n        self._update_timer.setInterval(update_interval_ms)\n        self._update_timer.timeout.connect(self._on_debounced_update)\n\n        # Pulse animation timer.\n        self._pulse_timer = QTimer(self)\n        self._pulse_timer.setInterval(_PULSE_INTERVAL_MS)\n        self._pulse_timer.timeout.connect(self._advance_pulse)\n\n        # Clear timer.\n        self._clear_timer = QTimer(self)\n        self._clear_timer.setSingleShot(True)\n        self._clear_timer.timeout.connect(self._clear_finished)\n\n        # Connect queue signals.\n        task_queue.task_enqueued.connect(self._on_task_enqueued)\n        task_queue.task_started.connect(self._on_task_started)\n        task_queue.task_completed.connect(self._on_task_completed)\n        task_queue.task_failed.connect(self._on_task_failed)\n        task_queue.task_cancelled.connect(self._on_task_cancelled)\n        task_queue.queue_empty.connect(self._on_queue_empty)\n\n        # Widget appearance.\n        self.setMaximumHeight(self.MAX_HEIGHT)\n        self.setMinimumHeight(self.MAX_HEIGHT)\n        self.setSizePolicy(\n            QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed\n        )\n        self.setAttribute(Qt.WidgetAttribute.WA_Hover, True)\n        self.setMouseTracking(True)\n\n    # ------------------------------------------------------------------\n    # Signal handlers\n    # ------------------------------------------------------------------\n\n    @Slot(str, int)\n    def _on_task_enqueued(self, name: str, priority: int) -&gt; None:\n        \"\"\"Record a newly enqueued task.\n\n        Args:\n            name: Task name.\n            priority: Numeric priority.\n        \"\"\"\n        self._tasks.append(_TrackedTask(name, priority, _TaskStatus.PENDING))\n        self._schedule_update()\n\n    @Slot(str)\n    def _on_task_started(self, name: str) -&gt; None:\n        \"\"\"Transition the first matching pending task to running.\n\n        Args:\n            name: Task name.\n        \"\"\"\n        has_running = False\n        for task in reversed(self._tasks):\n            if task.name == name and task.status == _TaskStatus.PENDING:\n                task.status = _TaskStatus.RUNNING\n                has_running = True\n                break\n        if has_running and not self._pulse_timer.isActive():\n            self._pulse_timer.start()\n        self._schedule_update()\n\n    @Slot(str, object)\n    def _on_task_completed(self, name: str, _result: object) -&gt; None:\n        \"\"\"Mark the first matching active task as completed.\n\n        Args:\n            name: Task name.\n            _result: Unused task result.\n        \"\"\"\n        self._transition(name, _TaskStatus.COMPLETED)\n\n    @Slot(str, str)\n    def _on_task_failed(self, name: str, _error: str) -&gt; None:\n        \"\"\"Mark the first matching active task as failed.\n\n        Args:\n            name: Task name.\n            _error: Unused error message.\n        \"\"\"\n        self._transition(name, _TaskStatus.FAILED)\n\n    @Slot(str, str)\n    def _on_task_cancelled(self, name: str, _ctx: str) -&gt; None:\n        \"\"\"Mark the first matching active task as cancelled.\n\n        Args:\n            name: Task name.\n            _ctx: Unused context id.\n        \"\"\"\n        self._transition(name, _TaskStatus.CANCELLED)\n\n    @Slot()\n    def _on_queue_empty(self) -&gt; None:\n        \"\"\"Schedule removal of finished segments after a short delay.\"\"\"\n        self._schedule_clear()\n\n    # ------------------------------------------------------------------\n    # Internal helpers\n    # ------------------------------------------------------------------\n\n    def _transition(self, name: str, status: _TaskStatus) -&gt; None:\n        \"\"\"Move the first active (pending/running) task with *name* to *status*.\n\n        Args:\n            name: Task name to look up.\n            status: Target status.\n        \"\"\"\n        active = (_TaskStatus.PENDING, _TaskStatus.RUNNING)\n        for task in reversed(self._tasks):\n            if task.name == name and task.status in active:\n                task.status = status\n                break\n        self._schedule_update()\n\n        # If no active tasks remain, schedule cleanup so completed\n        # segments don't linger after pool tasks finish.\n        if self._tasks and not any(t.status in active for t in self._tasks):\n            self._schedule_clear()\n\n    def _schedule_update(self) -&gt; None:\n        \"\"\"Restart the debounce timer to coalesce rapid state changes.\"\"\"\n        self._update_timer.start()\n\n    def _schedule_clear(self) -&gt; None:\n        # ensure clear is never earlier than pending debounced paint cadence\n        delay = max(_CLEAR_DELAY_MS, self._update_timer.interval())\n        self._clear_timer.start(delay)\n\n    def _on_debounced_update(self) -&gt; None:\n        \"\"\"Slot called by the debounce timer; triggers a repaint and tooltip.\"\"\"\n        self.update()\n\n    def _advance_pulse(self) -&gt; None:\n        \"\"\"Advance the pulse phase and repaint if any task is running.\"\"\"\n        self._pulse_phase = (self._pulse_phase + 0.06) % 1.0\n        has_running = any(t.status == _TaskStatus.RUNNING for t in self._tasks)\n        if has_running:\n            self.update()\n        else:\n            self._pulse_timer.stop()\n\n    def _clear_finished(self) -&gt; None:\n        \"\"\"Remove all terminal-state tasks, keeping only active ones.\"\"\"\n        # don't clear before pending debounced repaint runs\n        if self._update_timer.isActive():\n            self._clear_timer.start(self._update_timer.remainingTime() + 1)\n            return\n\n        terminal = (\n            _TaskStatus.COMPLETED,\n            _TaskStatus.FAILED,\n            _TaskStatus.CANCELLED,\n        )\n        self._tasks = [t for t in self._tasks if t.status not in terminal]\n        self.update()\n\n    def _active_task_name(self) -&gt; str:\n        \"\"\"Return the name of the first running task, or an empty string.\"\"\"\n        for task in self._tasks:\n            if task.status == _TaskStatus.RUNNING:\n                return task.name\n        return \"\"\n\n    def _build_tooltip(self) -&gt; str:\n        \"\"\"Compose the hover tooltip text from current task state.\n\n        Returns:\n            A multi-line string describing queue status, priority breakdown,\n            and the currently active task name.\n        \"\"\"\n        total = len(self._tasks)\n        if total == 0:\n            return \"No tasks\"\n\n        by_status: dict[_TaskStatus, int] = {s: 0 for s in _TaskStatus}\n        by_bucket: dict[str, int] = {\"high\": 0, \"medium\": 0, \"low\": 0}\n\n        for t in self._tasks:\n            by_status[t.status] += 1\n            by_bucket[_priority_bucket(t.priority)] += 1\n\n        lines: list[str] = [\n            f\"&lt;b&gt;Tasks: {total}&lt;/b&gt;\",\n            (\n                f\"Pending: {by_status[_TaskStatus.PENDING]}  \"\n                f\"Running: {by_status[_TaskStatus.RUNNING]}  \"\n                f\"Completed: {by_status[_TaskStatus.COMPLETED]}  \"\n                f\"Failed: {by_status[_TaskStatus.FAILED]}\"\n            ),\n        ]\n\n        # Priority breakdown percentages.\n        bucket_parts: list[str] = []\n        for bucket, label in (\n            (\"high\", \"High\"),\n            (\"medium\", \"Medium\"),\n            (\"low\", \"Low\"),\n        ):\n            count = by_bucket[bucket]\n            if count:\n                pct = round(100 * count / total)\n                bucket_parts.append(f\"{label}: {pct}%\")\n        if bucket_parts:\n            lines.append(\"Priority \u2014 \" + \"  \".join(bucket_parts))\n\n        active = self._active_task_name()\n        if active:\n            lines.append(f\"Active: &lt;i&gt;{active}&lt;/i&gt;\")\n\n        return \"&lt;br&gt;\".join(lines)\n\n    # ------------------------------------------------------------------\n    # Qt overrides\n    # ------------------------------------------------------------------\n\n    def event(self, event: QEvent) -&gt; bool:\n        \"\"\"Handle tooltip requests to provide dynamic hover content.\n\n        Args:\n            event: Incoming Qt event.\n\n        Returns:\n            Forwarded return value from the base implementation.\n        \"\"\"\n        if event.type() == QEvent.Type.Enter:\n            QToolTip.showText(\n                event.globalPos(),  # type: ignore\n                self._build_tooltip(),\n                self,\n                self.rect(),\n            )\n            return True\n        return super().event(event)\n\n    def paintEvent(self, _event: Any) -&gt; None:\n        \"\"\"Render the segmented progress bar.\n\n        Segments are drawn left-to-right in enqueue order.  Completed and\n        cancelled segments are dimmed; failed segments are drawn in red;\n        the running segment pulses.\n\n        Args:\n            _event: Unused paint event.\n        \"\"\"\n        tasks = self._tasks\n\n        painter = QPainter(self)\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n        painter.save()\n        painter.setBrush(self._bg_color)\n        painter.setPen(QPen(self._bg_outline_color, 1))\n        painter.drawRoundedRect(\n            self.rect(), self._bar_radius, self._bar_radius\n        )  # Background\n        painter.restore()\n\n        if not tasks:\n            return\n\n        margin = 3\n        width = self.width() - 2 * margin\n        height = self.height() - 2 * margin\n\n        n = len(tasks)\n        total_gap = self._segment_gap * (n - 1)\n        seg_w = max(1.0, (width - total_gap) / n)\n        h = float(height)\n\n        for i, task in enumerate(tasks):\n            x = i * (seg_w + self._segment_gap)\n\n            # Determine base colour.\n            if task.status == _TaskStatus.FAILED:\n                base_color = QColor(self._failed_color)\n            else:\n                base_color = QColor(\n                    self._priority_colors[_priority_bucket(task.priority)]\n                )\n\n            # Apply alpha based on status.\n            if task.status in (\n                _TaskStatus.COMPLETED,\n                _TaskStatus.CANCELLED,\n            ):\n                base_color.setAlphaF(self._completed_alpha)\n            elif task.status == _TaskStatus.RUNNING:\n                pulse = 0.65 + 0.35 * math.sin(self._pulse_phase * 2 * math.pi)\n                base_color.setAlphaF(pulse)\n            else:\n                base_color.setAlphaF(self._pending_alpha)\n\n            painter.setBrush(base_color)\n            painter.setPen(Qt.PenStyle.NoPen)\n\n            path = QPainterPath()\n            path.addRoundedRect(\n                QRectF(x + margin, margin, seg_w, h),\n                self._bar_radius,\n                self._bar_radius,\n            )\n            painter.drawPath(path)\n\n        painter.end()\n\n    def closeEvent(self, event: QCloseEvent) -&gt; None:\n        \"\"\"Clean up signal connections on widget destruction.\"\"\"\n        self._queue.task_enqueued.disconnect(self._on_task_enqueued)\n        self._queue.task_started.disconnect(self._on_task_started)\n        self._queue.task_completed.disconnect(self._on_task_completed)\n        self._queue.task_failed.disconnect(self._on_task_failed)\n        self._queue.task_cancelled.disconnect(self._on_task_cancelled)\n        self._queue.queue_empty.disconnect(self._on_queue_empty)\n        super().closeEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue_monitor.html#client.ayon_ui_qt.components.task_queue_monitor.AsyncTaskQueueMonitor.__init__","title":"<code>__init__(task_queue, update_interval_ms=_DEBOUNCE_MS, parent=None)</code>","text":"<p>Initialise and connect to task_queue signals.</p> <p>Parameters:</p> Name Type Description Default <code>task_queue</code> <code>AsyncTaskQueue</code> <p>Queue instance to observe.</p> required <code>update_interval_ms</code> <code>int</code> <p>Debounce redraw interval in ms.</p> <code>_DEBOUNCE_MS</code> <code>parent</code> <code>Any</code> <p>Optional parent widget.</p> <code>None</code> Source code in <code>client/ayon_ui_qt/components/task_queue_monitor.py</code> <pre><code>def __init__(\n    self,\n    task_queue: AsyncTaskQueue,\n    update_interval_ms: int = _DEBOUNCE_MS,\n    parent: Any = None,\n) -&gt; None:\n    \"\"\"Initialise and connect to *task_queue* signals.\n\n    Args:\n        task_queue: Queue instance to observe.\n        update_interval_ms: Debounce redraw interval in ms.\n        parent: Optional parent widget.\n    \"\"\"\n    super().__init__(parent)\n\n    self._queue: AsyncTaskQueue = task_queue\n    self._tasks: list[_TrackedTask] = []\n    self._pulse_phase: float = 0.0\n\n    # Load style configuration from AYON style system\n    style_data = get_ayon_style_data(\"AsyncTaskQueueMonitor\") or {}\n    if not style_data:\n        log.warning(\n            \"AsyncTaskQueueMonitor: Style data not available, using defaults\"\n        )\n\n    # Colors\n    self._bg_color = QColor(style_data.get(\"background-color\", \"#1c2026\"))\n    self._bg_outline_color = QColor(\n        style_data.get(\"outline-color\", \"#3F4552\")\n    )\n    self._priority_colors = {\n        \"high\": QColor(style_data.get(\"high-priority-color\", \"#E87D0D\")),\n        \"medium\": QColor(\n            style_data.get(\"medium-priority-color\", \"#4CAF50\")\n        ),\n        \"low\": QColor(style_data.get(\"low-priority-color\", \"#2196F3\")),\n    }\n    self._failed_color = QColor(style_data.get(\"failed-color\", \"#F44336\"))\n\n    # Alphas (opacity values)\n    self._completed_alpha = style_data.get(\"completed-alpha\", 0.45)\n    self._pending_alpha = style_data.get(\"pending-alpha\", 0.70)\n\n    # Dimensions\n    self._segment_gap = style_data.get(\"segment-gap\", 2)\n    self._bar_radius = style_data.get(\"bar-radius\", 3)\n\n    # Debounce timer \u2014 single-shot, restarted on every state change.\n    self._update_timer = QTimer(self)\n    self._update_timer.setSingleShot(True)\n    self._update_timer.setInterval(update_interval_ms)\n    self._update_timer.timeout.connect(self._on_debounced_update)\n\n    # Pulse animation timer.\n    self._pulse_timer = QTimer(self)\n    self._pulse_timer.setInterval(_PULSE_INTERVAL_MS)\n    self._pulse_timer.timeout.connect(self._advance_pulse)\n\n    # Clear timer.\n    self._clear_timer = QTimer(self)\n    self._clear_timer.setSingleShot(True)\n    self._clear_timer.timeout.connect(self._clear_finished)\n\n    # Connect queue signals.\n    task_queue.task_enqueued.connect(self._on_task_enqueued)\n    task_queue.task_started.connect(self._on_task_started)\n    task_queue.task_completed.connect(self._on_task_completed)\n    task_queue.task_failed.connect(self._on_task_failed)\n    task_queue.task_cancelled.connect(self._on_task_cancelled)\n    task_queue.queue_empty.connect(self._on_queue_empty)\n\n    # Widget appearance.\n    self.setMaximumHeight(self.MAX_HEIGHT)\n    self.setMinimumHeight(self.MAX_HEIGHT)\n    self.setSizePolicy(\n        QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed\n    )\n    self.setAttribute(Qt.WidgetAttribute.WA_Hover, True)\n    self.setMouseTracking(True)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue_monitor.html#client.ayon_ui_qt.components.task_queue_monitor.AsyncTaskQueueMonitor.closeEvent","title":"<code>closeEvent(event)</code>","text":"<p>Clean up signal connections on widget destruction.</p> Source code in <code>client/ayon_ui_qt/components/task_queue_monitor.py</code> <pre><code>def closeEvent(self, event: QCloseEvent) -&gt; None:\n    \"\"\"Clean up signal connections on widget destruction.\"\"\"\n    self._queue.task_enqueued.disconnect(self._on_task_enqueued)\n    self._queue.task_started.disconnect(self._on_task_started)\n    self._queue.task_completed.disconnect(self._on_task_completed)\n    self._queue.task_failed.disconnect(self._on_task_failed)\n    self._queue.task_cancelled.disconnect(self._on_task_cancelled)\n    self._queue.queue_empty.disconnect(self._on_queue_empty)\n    super().closeEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue_monitor.html#client.ayon_ui_qt.components.task_queue_monitor.AsyncTaskQueueMonitor.event","title":"<code>event(event)</code>","text":"<p>Handle tooltip requests to provide dynamic hover content.</p> <p>Parameters:</p> Name Type Description Default <code>event</code> <code>QEvent</code> <p>Incoming Qt event.</p> required <p>Returns:</p> Type Description <code>bool</code> <p>Forwarded return value from the base implementation.</p> Source code in <code>client/ayon_ui_qt/components/task_queue_monitor.py</code> <pre><code>def event(self, event: QEvent) -&gt; bool:\n    \"\"\"Handle tooltip requests to provide dynamic hover content.\n\n    Args:\n        event: Incoming Qt event.\n\n    Returns:\n        Forwarded return value from the base implementation.\n    \"\"\"\n    if event.type() == QEvent.Type.Enter:\n        QToolTip.showText(\n            event.globalPos(),  # type: ignore\n            self._build_tooltip(),\n            self,\n            self.rect(),\n        )\n        return True\n    return super().event(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/task_queue_monitor.html#client.ayon_ui_qt.components.task_queue_monitor.AsyncTaskQueueMonitor.paintEvent","title":"<code>paintEvent(_event)</code>","text":"<p>Render the segmented progress bar.</p> <p>Segments are drawn left-to-right in enqueue order.  Completed and cancelled segments are dimmed; failed segments are drawn in red; the running segment pulses.</p> <p>Parameters:</p> Name Type Description Default <code>_event</code> <code>Any</code> <p>Unused paint event.</p> required Source code in <code>client/ayon_ui_qt/components/task_queue_monitor.py</code> <pre><code>def paintEvent(self, _event: Any) -&gt; None:\n    \"\"\"Render the segmented progress bar.\n\n    Segments are drawn left-to-right in enqueue order.  Completed and\n    cancelled segments are dimmed; failed segments are drawn in red;\n    the running segment pulses.\n\n    Args:\n        _event: Unused paint event.\n    \"\"\"\n    tasks = self._tasks\n\n    painter = QPainter(self)\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing)\n\n    painter.save()\n    painter.setBrush(self._bg_color)\n    painter.setPen(QPen(self._bg_outline_color, 1))\n    painter.drawRoundedRect(\n        self.rect(), self._bar_radius, self._bar_radius\n    )  # Background\n    painter.restore()\n\n    if not tasks:\n        return\n\n    margin = 3\n    width = self.width() - 2 * margin\n    height = self.height() - 2 * margin\n\n    n = len(tasks)\n    total_gap = self._segment_gap * (n - 1)\n    seg_w = max(1.0, (width - total_gap) / n)\n    h = float(height)\n\n    for i, task in enumerate(tasks):\n        x = i * (seg_w + self._segment_gap)\n\n        # Determine base colour.\n        if task.status == _TaskStatus.FAILED:\n            base_color = QColor(self._failed_color)\n        else:\n            base_color = QColor(\n                self._priority_colors[_priority_bucket(task.priority)]\n            )\n\n        # Apply alpha based on status.\n        if task.status in (\n            _TaskStatus.COMPLETED,\n            _TaskStatus.CANCELLED,\n        ):\n            base_color.setAlphaF(self._completed_alpha)\n        elif task.status == _TaskStatus.RUNNING:\n            pulse = 0.65 + 0.35 * math.sin(self._pulse_phase * 2 * math.pi)\n            base_color.setAlphaF(pulse)\n        else:\n            base_color.setAlphaF(self._pending_alpha)\n\n        painter.setBrush(base_color)\n        painter.setPen(Qt.PenStyle.NoPen)\n\n        path = QPainterPath()\n        path.addRoundedRect(\n            QRectF(x + margin, margin, seg_w, h),\n            self._bar_radius,\n            self._bar_radius,\n        )\n        painter.drawPath(path)\n\n    painter.end()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html","title":"text_box","text":""},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextBox","title":"<code>AYTextBox</code>","text":"<p>               Bases: <code>AYContainer</code></p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>class AYTextBox(AYContainer):\n    signals = AYTextBoxSignals()\n    Variants = QFrameVariants\n    style_icons = {\n        \"stl_h1\": \"format_h1\",\n        \"stl_bold\": \"format_bold\",\n        \"stl_italic\": \"format_italic\",\n        \"stl_link\": \"link\",\n        \"stl_code\": \"code\",\n    }\n    format_icons = {\n        \"fmt_number\": \"format_list_numbered\",\n        \"fmt_bullet\": \"format_list_bulleted\",\n        \"fmt_checklist\": \"checklist\",\n    }\n    mention_map = {\n        \"person\": \"@\",\n        # TODO: Implement support for version and task mentions in completer\n        #  before enabling these\n        # \"layers\": \"@@\",\n        # \"check_circle\": \"@@@\",\n    }\n\n    def __init__(\n        self,\n        *args,\n        num_lines=0,\n        show_categories=False,\n        user_list: list[User] | None = None,\n        variant: Variants = Variants.Default,\n        **kwargs,\n    ):\n        self._variant_str: str = variant.value\n        super().__init__(\n            *args,\n            layout=AYContainer.Layout.VBox,\n            variant=variant,\n            margin=0,\n            **kwargs,\n        )\n\n        self.show_categories = show_categories\n        self.comment_categories: list[dict] = _dict_from_comment_category([])\n        self.category = self.comment_categories[0][\"text\"]\n        self._user_list: list[User] = user_list or []\n        # Store attachments - unified list for both screenshots and files\n        self._attachments = []  # List of dicts: {'type': 'screenshot'|'file', 'path': str, 'filename': str}\n        self.screenshot_handler = None  # Will be initialized in _build\n        self._build(num_lines)\n\n    def _build_upper_bar(self):\n        grp_spacing = 16\n        lyt = AYHBoxLayout(spacing=0, margin=0)\n        # comment category if available\n        if self.show_categories:\n            self.com_cat = AYComboBox(\n                parent=self, items=self.comment_categories\n            )\n            self.com_cat.currentTextChanged.connect(self._on_category_changed)\n            lyt.addWidget(self.com_cat)\n        lyt.addStretch()\n        # styling buttons\n        for var, icn in self.style_icons.items():\n            setattr(\n                self,\n                var,\n                AYButton(self, variant=AYButton.Variants.Nav, icon=icn),\n            )\n            lyt.addWidget(getattr(self, var))\n        # formatting buttons\n        for var, icn in self.format_icons.items():\n            setattr(\n                self,\n                var,\n                AYButton(self, variant=AYButton.Variants.Nav, icon=icn),\n            )\n            lyt.addWidget(getattr(self, var))\n        lyt.addSpacing(grp_spacing)\n        self.screenshot_btn = AYButton(\n            self, variant=AYButton.Variants.Nav, icon=\"photo_camera\"\n        )\n        lyt.addWidget(self.screenshot_btn)\n        self.attach_file_btn = AYButton(\n            self, variant=AYButton.Variants.Nav, icon=\"attach_file\"\n        )\n        self.attach_file_btn.clicked.connect(self._on_attach_file_clicked)\n        lyt.addWidget(self.attach_file_btn)\n        return lyt\n\n    def _build_attachment_area(self):\n        \"\"\"Build the unified scrollable attachment display area for both screenshots and files.\"\"\"\n        # Container for attachments\n        self.attachment_container = QtWidgets.QWidget(self)\n        self.attachment_layout = AYHBoxLayout(\n            self.attachment_container, margin=4, spacing=4\n        )\n\n        # Scroll area\n        self.attachment_scroll = QScrollArea(self)\n        self.attachment_scroll.setWidget(self.attachment_container)\n        self.attachment_scroll.setWidgetResizable(True)\n        self.attachment_scroll.setFixedHeight(100)\n        self.attachment_scroll.setHorizontalScrollBarPolicy(\n            Qt.ScrollBarPolicy.ScrollBarAsNeeded\n        )\n        self.attachment_scroll.setVerticalScrollBarPolicy(\n            Qt.ScrollBarPolicy.ScrollBarAlwaysOff\n        )\n        self.attachment_scroll.hide()  # Hidden by default\n\n        return self.attachment_scroll\n\n    def _build_edit_field(self, num_lines):\n        self.edit_field = AYTextEditor(\n            self,\n            num_lines=num_lines,\n            user_list=self._user_list,\n            variant=AYTextEditor.Variants.Default,\n        )\n        for var in self.style_icons:\n            getattr(self, var).clicked.connect(\n                partial(self.edit_field.set_style, var)\n            )\n        for var in self.format_icons:\n            getattr(self, var).clicked.connect(\n                partial(self.edit_field.set_format, var)\n            )\n\n        self.edit_field.submitted.connect(self._on_comment_clicked)\n\n        return self.edit_field\n\n    def _build_lower_bar(self):\n        lyt = AYHBoxLayout(margin=0, spacing=0)\n\n        for icn, mention in self.mention_map.items():\n            btn = AYButton(self, variant=AYButton.Variants.Nav, icon=icn)\n            btn.clicked.connect(partial(self._add_mention_to_editor, mention))\n            lyt.addWidget(btn)\n\n        lyt.addSpacerItem(\n            QtWidgets.QSpacerItem(0, 0, QSizePolicy.Policy.MinimumExpanding)\n        )\n        self.comment_button = AYButton(\n            \"Comment\", variant=AYButton.Variants.Filled\n        )\n        self.comment_button.clicked.connect(self._on_comment_clicked)\n        lyt.addWidget(self.comment_button)\n        return lyt\n\n    def _on_comment_clicked(self) -&gt; None:\n        \"\"\"Handle comment button click and emit signal with markdown content.\"\"\"\n        markdown_content = self.edit_field.as_markdown()\n\n        # Get all attachment paths\n        all_attachment_paths = [att['path'] for att in self._attachments]\n\n        self.signals.comment_submitted.emit(\n            markdown_content, self.category, all_attachment_paths\n        )\n        self.edit_field.clear()\n        if self.show_categories:\n            self.com_cat.setCurrentIndex(0)\n        self.clear_all_attachments()\n\n        # Clear screenshots after submission\n        if self.screenshot_handler:\n            self.screenshot_handler.clear_screenshots()\n\n    def _add_mention_to_editor(self, mention: str) -&gt; None:\n        \"\"\"Add mention text to the editor at cursor position.\"\"\"\n        cursor = self.edit_field.textCursor()\n        cursor.insertText(mention)\n        self.edit_field.setTextCursor(cursor)\n        self.edit_field.setFocus()\n\n    def _on_category_changed(self, category: str) -&gt; None:\n        self.category = category if category != NO_CATEGORY[\"text\"] else \"\"\n\n    def _on_attach_file_clicked(self) -&gt; None:\n        \"\"\"Handle attach file button click and open file dialog.\"\"\"\n        file_paths, _ = QtWidgets.QFileDialog.getOpenFileNames(\n            self,\n            \"Select files to attach\",\n            \"\",\n            \"Image Files (*.png *.jpeg *.jpg);;All Files (*)\",\n        )\n\n        if file_paths:\n            for file_path in file_paths:\n                self.add_attachment(file_path, 'file')\n\n    def _on_attachment_removed(self, index: int, attachment_type: str) -&gt; None:\n        \"\"\"Handle removal of an attachment.\"\"\"\n        if 0 &lt;= index &lt; len(self._attachments):\n            attachment = self._attachments[index]\n            # Optionally delete temp files (screenshots)\n            if attachment['type'] == 'screenshot':\n                file_path = attachment['path']\n                if os.path.exists(file_path):\n                    try:\n                        os.remove(file_path)\n                    except Exception as e:\n                        logger.warning(f\"Failed to remove temp file {file_path}: {e}\")\n\n            self._attachments.pop(index)\n            self._refresh_attachment_display()\n            self._update_attachment_buttons()\n\n    def _on_thumbnail_clicked(self, index: int, attachment_type: str) -&gt; None:\n        \"\"\"Handle thumbnail click to open gallery.\"\"\"\n        if not self._attachments:\n            return\n\n        from .gallery_dialog import GalleryDialog\n\n        # Prepare images list for GalleryDialog\n        images = [\n            (att['path'], att['filename'])\n            for att in self._attachments\n        ]\n\n        dialog = GalleryDialog(images, current_index=index, parent=self)\n        dialog.setWindowTitle(\"Attachments Preview\")\n        dialog.exec_()\n\n    def _refresh_attachment_display(self) -&gt; None:\n        \"\"\"Refresh the unified attachment display area.\"\"\"\n        # Clear existing widgets\n        while self.attachment_layout.count():\n            item = self.attachment_layout.takeAt(0)\n            widget = item.widget()\n            if widget is not None:\n                widget.deleteLater()\n\n        # Add attachment widgets\n        if self._attachments:\n            for idx, attachment in enumerate(self._attachments):\n                widget = AttachmentWidget(\n                    parent=self.attachment_container,\n                    index=idx,\n                    filename=attachment['filename'],\n                    file_path=attachment['path'],\n                    attachment_type=attachment['type']\n                )\n                widget.remove_clicked.connect(self._on_attachment_removed)\n                widget.thumbnail_clicked.connect(self._on_thumbnail_clicked)\n                self.attachment_layout.addWidget(widget)\n\n            self.attachment_layout.addStretch()\n            self.attachment_scroll.show()\n        else:\n            self.attachment_scroll.hide()\n\n        self.attachment_container.update()\n        self.attachment_scroll.viewport().update()\n\n    def add_attachment(self, file_path: str, attachment_type: str = 'file') -&gt; None:\n        \"\"\"Add a single attachment (screenshot or file).\n\n        Args:\n            file_path: Path to the file\n            attachment_type: 'screenshot' or 'file'\n        \"\"\"\n        if not file_path or file_path in [att['path'] for att in self._attachments]:\n            return\n\n        filename = os.path.basename(file_path)\n        if attachment_type == 'screenshot':\n            # Generate screenshot number\n            screenshot_count = sum(1 for att in self._attachments if att['type'] == 'screenshot')\n            filename = f\"Screenshot {screenshot_count + 1}\"\n\n        self._attachments.append({\n            'type': attachment_type,\n            'path': file_path,\n            'filename': filename\n        })\n\n        self._refresh_attachment_display()\n        self._update_attachment_buttons()\n\n    def _update_attachment_buttons(self) -&gt; None:\n        \"\"\"Update button badges to show counts.\"\"\"\n        screenshot_count = sum(1 for att in self._attachments if att['type'] == 'screenshot')\n        file_count = sum(1 for att in self._attachments if att['type'] == 'file')\n\n        # Update screenshot button\n        if screenshot_count &gt; 0:\n            self.screenshot_btn.setText(f\"{screenshot_count}\")\n            self.screenshot_btn.setStyleSheet(\"background-color: rgba(92, 173, 214, .4);\")\n        else:\n            self.screenshot_btn.setText(\"\")\n            self.screenshot_btn.setStyleSheet(\"\")\n\n        # Update attach file button\n        if file_count &gt; 0:\n            self.attach_file_btn.setText(f\"{file_count}\")\n            self.attach_file_btn.setStyleSheet(\"background-color: rgba(92, 173, 214, .4);\")\n        else:\n            self.attach_file_btn.setText(\"\")\n            self.attach_file_btn.setStyleSheet(\"\")\n\n    def clear_all_attachments(self) -&gt; None:\n        \"\"\"Clear all attachments.\"\"\"\n        self._attachments.clear()\n        self._refresh_attachment_display()\n        self._update_attachment_buttons()\n\n    def get_attachments(self) -&gt; list[dict]:\n        \"\"\"Get the current list of attachments.\n\n        Returns:\n            List of attachment dictionaries\n        \"\"\"\n        return self._attachments.copy()\n\n    @Slot(ProjectData)\n    def on_ctlr_project_changed(self, data: ProjectData):\n        self.comment_categories = _dict_from_comment_category(\n            data.comment_category\n        )\n        if self.show_categories:\n            self.com_cat.update_items(self.comment_categories)\n        self.edit_field._user_list = self._user_list = data.users\n        on_users_updated(self.edit_field)\n\n    def _build(self, num_lines):\n        self.add_layout(self._build_upper_bar())\n\n        # Initialize screenshot handler after screenshot_btn is created\n        from .screenshot_capture import ScreenshotHandler\n        self.screenshot_handler = ScreenshotHandler(self, self.screenshot_btn)\n\n        # Click to capture, but if screenshots exist, show gallery\n        self.screenshot_btn.clicked.connect(self._on_screenshot_btn_clicked)\n\n        self.add_widget(\n            self._build_attachment_area()\n        )  # Add unified attachment area\n        self.add_widget(self._build_edit_field(num_lines), stretch=10)\n        self.add_layout(self._build_lower_bar())\n\n    def set_markdown(self, md: str):\n        \"\"\"Set markdown content with checkbox support.\n\n        Args:\n            md: Markdown text to display\n        \"\"\"\n        self.edit_field.set_markdown(md)\n\n    def _on_screenshot_btn_clicked(self):\n        \"\"\"Handle screenshot button click - always capture new screenshot.\"\"\"\n        self.screenshot_handler.launch_capture()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextBox.add_attachment","title":"<code>add_attachment(file_path, attachment_type='file')</code>","text":"<p>Add a single attachment (screenshot or file).</p> <p>Parameters:</p> Name Type Description Default <code>file_path</code> <code>str</code> <p>Path to the file</p> required <code>attachment_type</code> <code>str</code> <p>'screenshot' or 'file'</p> <code>'file'</code> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def add_attachment(self, file_path: str, attachment_type: str = 'file') -&gt; None:\n    \"\"\"Add a single attachment (screenshot or file).\n\n    Args:\n        file_path: Path to the file\n        attachment_type: 'screenshot' or 'file'\n    \"\"\"\n    if not file_path or file_path in [att['path'] for att in self._attachments]:\n        return\n\n    filename = os.path.basename(file_path)\n    if attachment_type == 'screenshot':\n        # Generate screenshot number\n        screenshot_count = sum(1 for att in self._attachments if att['type'] == 'screenshot')\n        filename = f\"Screenshot {screenshot_count + 1}\"\n\n    self._attachments.append({\n        'type': attachment_type,\n        'path': file_path,\n        'filename': filename\n    })\n\n    self._refresh_attachment_display()\n    self._update_attachment_buttons()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextBox.clear_all_attachments","title":"<code>clear_all_attachments()</code>","text":"<p>Clear all attachments.</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def clear_all_attachments(self) -&gt; None:\n    \"\"\"Clear all attachments.\"\"\"\n    self._attachments.clear()\n    self._refresh_attachment_display()\n    self._update_attachment_buttons()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextBox.get_attachments","title":"<code>get_attachments()</code>","text":"<p>Get the current list of attachments.</p> <p>Returns:</p> Type Description <code>list[dict]</code> <p>List of attachment dictionaries</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def get_attachments(self) -&gt; list[dict]:\n    \"\"\"Get the current list of attachments.\n\n    Returns:\n        List of attachment dictionaries\n    \"\"\"\n    return self._attachments.copy()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextBox.set_markdown","title":"<code>set_markdown(md)</code>","text":"<p>Set markdown content with checkbox support.</p> <p>Parameters:</p> Name Type Description Default <code>md</code> <code>str</code> <p>Markdown text to display</p> required Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def set_markdown(self, md: str):\n    \"\"\"Set markdown content with checkbox support.\n\n    Args:\n        md: Markdown text to display\n    \"\"\"\n    self.edit_field.set_markdown(md)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextEditor","title":"<code>AYTextEditor</code>","text":"<p>               Bases: <code>AYTextEdit</code></p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>class AYTextEditor(AYTextEdit):\n    Variants = QTextEditVariants\n\n    submitted = Signal()  # Signal emitted when Ctrl+Enter is pressed\n    checklist_changed = Signal()  # Signal emitted when checkbox state changes\n\n    def __init__(\n        self,\n        *args,\n        num_lines: int = 0,\n        read_only: bool = False,\n        user_list: list[User] | None,\n        variant: Variants = Variants.Default,\n        **kwargs,\n    ):\n        # remove our kwargs\n        self.num_lines: int = num_lines\n        self._read_only: bool = read_only\n        self._user_list: list[User] = user_list or []\n        self._variant_str: str = variant.value\n        self._checkbox_handler: CheckboxHandler | None = None\n        # Guard flag: when True, format_comment_on_change is a no-op.\n        self._suppress_formatting: bool = False\n\n        super().__init__(*args, variant=variant, **kwargs)\n        self.setStyle(get_ayon_style())\n        # Enable mouse tracking on viewport to receive mouseMoveEvent\n        self.viewport().setMouseTracking(True)\n\n        self.document().setIndentWidth(22)  # pixels per indent level\n\n        if self.num_lines:\n            doc = self.document()\n            fm = self.fontMetrics()\n            frame_w = self.frameWidth()\n            cm = self.contentsMargins()\n            height = (\n                fm.lineSpacing() * self.num_lines\n                + int(doc.documentMargin()) * 2\n                + frame_w * 2\n                + cm.top()\n                + cm.bottom()\n            )\n            self.setFixedHeight(height)\n\n        self.setSizePolicy(\n            QSizePolicy.Policy.Expanding,\n            QSizePolicy.Policy.Expanding\n            if self.num_lines\n            else QSizePolicy.Policy.Fixed,\n        )\n\n        # automatic bullet lists\n        self.setAutoFormatting(QTextEdit.AutoFormattingFlag.AutoAll)\n\n        if not self._read_only:\n            self.setPlaceholderText(\n                \"Comment or mention with @user, @@version, @@@task...\"\n            )\n        self.setReadOnly(self._read_only)\n        palette = self.palette()\n        palette.setColor(QPalette.ColorRole.PlaceholderText, QColor(\"white\"))\n        self.setPalette(palette)\n        # Setup user completer\n        setup_user_completer(\n            self,\n            self._on_completer_activated,\n            self._on_text_changed,\n        )\n\n        self.document().contentsChanged.connect(self._on_contents_changed)\n\n    def _on_contents_changed(self) -&gt; None:\n        \"\"\"Forward contentsChanged to format_comment_on_change.\n\n        Skipped when ``_suppress_formatting`` is True so that checkbox\n        insertion code can mutate the document without triggering a\n        full re-format pass.\n        \"\"\"\n        if not self._suppress_formatting:\n            format_comment_on_change(self)\n            apply_code_block_backgrounds(self)\n\n    def _on_text_changed(self) -&gt; None:\n        \"\"\"Handle text changes to show/hide completer.\"\"\"\n        on_completer_text_changed(self)\n\n    def _on_completer_activated(self, text: str) -&gt; None:\n        \"\"\"Handle completer selection.\"\"\"\n        on_completer_activated(self, text)\n\n    def keyPressEvent(self, event) -&gt; None:\n        \"\"\"Handle key press events for completer.\"\"\"\n        if on_completer_key_press(self, event):\n            event.accept()\n            return\n\n        # ctrl/cmd-enter to submit\n        if (\n            event.key() in {Qt.Key.Key_Return, Qt.Key.Key_Enter}\n            and event.modifiers() &amp; Qt.KeyboardModifier.ControlModifier\n        ):\n            self.submitted.emit()\n\n        # Auto-continue checkbox on Enter\n        if (\n            event.key() in {Qt.Key.Key_Return, Qt.Key.Key_Enter}\n            and self._checkbox_handler\n            and self._checkbox_handler.has_checkboxes()\n        ):\n            cursor = self.textCursor()\n            block_text = cursor.block().text()\n\n            if \"\\ufffc\" in block_text:\n                # Extract text after the checkbox object char\n                parts = block_text.split(\"\\ufffc\", 1)\n                after_checkbox = parts[1].strip() if len(parts) &gt; 1 else \"\"\n\n                if not after_checkbox:\n                    # Empty checkbox line \u2192 end the list\n                    # Remove the checkbox content from current block\n                    cursor.movePosition(\n                        QTextCursor.MoveOperation.StartOfBlock,\n                        QTextCursor.MoveMode.MoveAnchor,\n                    )\n                    cursor.movePosition(\n                        QTextCursor.MoveOperation.EndOfBlock,\n                        QTextCursor.MoveMode.KeepAnchor,\n                    )\n                    cursor.removeSelectedText()\n                    # Remove the last checkbox from handler\n                    self._checkbox_handler.remove_last_checkbox()\n                    # Insert a plain newline\n                    super().keyPressEvent(event)\n                    return\n\n                # Non-empty checkbox line \u2192 insert new checkbox\n                event.accept()\n                self._suppress_formatting = True\n\n                cursor.beginEditBlock()\n                cursor.movePosition(QTextCursor.MoveOperation.EndOfBlock)\n                cursor.insertBlock()\n                self._insert_checkbox_at_cursor(cursor)\n                cursor.endEditBlock()\n\n                self._suppress_formatting = False\n                self.setTextCursor(cursor)\n                return\n\n        super().keyPressEvent(event)\n\n    def _setup_checkbox_handler(self) -&gt; None:\n        \"\"\"Initialize checkbox handler if not already done.\"\"\"\n        if self._checkbox_handler is None:\n            self._checkbox_handler = CheckboxHandler(self)\n            self._checkbox_handler.checklist_changed.connect(\n                self._on_checklist_changed\n            )\n\n    def _on_checklist_changed(self) -&gt; None:\n        \"\"\"Handle checkbox state changes.\"\"\"\n        self.checklist_changed.emit()\n\n    def _insert_checkbox_at_cursor(self, cursor: QTextCursor) -&gt; None:\n        \"\"\"Insert a new unchecked checkbox object at the cursor position.\n\n        Inserts a two-space prefix, the custom checkbox object character\n        (``\\\\ufffc``), and a trailing space, then records the document\n        position on the :class:`CheckboxItem` for fast hit-testing.\n        The checkbox handler must already be initialised via\n        :meth:`_setup_checkbox_handler`.\n\n        Args:\n            cursor: Cursor at the insertion point; advanced past the\n                inserted characters on return.\n        \"\"\"\n        assert self._checkbox_handler is not None\n        new_item = self._checkbox_handler.add_checkbox()\n        fmt = QTextCharFormat()\n        fmt.setObjectType(CHECKBOX_FORMAT_TYPE)\n        fmt.setProperty(CHECKBOX_CHECKED_PROP, False)\n        fmt.setProperty(CHECKBOX_INDEX_PROP, new_item.index)\n        fmt.setVerticalAlignment(\n            QTextCharFormat.VerticalAlignment.AlignBaseline\n        )\n        cursor.insertText(\"  \")\n        new_item.doc_position = cursor.position()\n        cursor.insertText(\"\\ufffc\", fmt)\n        cursor.insertText(\" \")\n\n    def set_markdown(self, md: str) -&gt; None:\n        \"\"\"Set markdown content with checkbox support.\n\n        Args:\n            md: Markdown text to display\n        \"\"\"\n        if CheckboxHandler.contains_checkboxes(md):\n            self._setup_checkbox_handler()\n            assert self._checkbox_handler is not None\n            self._checkbox_handler.parse_and_render(md)\n        else:\n            self.document().setMarkdown(md, MD_DIALECT)\n        apply_code_block_backgrounds(self)\n\n    def as_markdown(self) -&gt; str:\n        \"\"\"Get the content as GitHub-flavored markdown.\n\n        Returns:\n            Markdown string.\n        \"\"\"\n        if self._checkbox_handler and self._checkbox_handler.has_checkboxes():\n            return self._checkbox_handler.to_markdown()\n        return self.document().toMarkdown(MD_DIALECT)\n\n    def _is_checkbox_at_cursor(\n        self, click_pos: QPoint\n    ) -&gt; tuple[bool, int | None]:\n        \"\"\"Check if a click position hits a checkbox bounding rect.\n\n        Delegates to :meth:`CheckboxHandler.find_checkbox_at_click` which\n        uses stored document positions instead of scanning the full text.\n\n        Args:\n            click_pos: QPoint from event.pos(), viewport coords.\n\n        Returns:\n            Tuple of (is_checkbox, document_position_for_lookup).\n        \"\"\"\n        if not self._checkbox_handler:\n            return False, None\n\n        # Account for scroll offset\n        scroll_offset = QPoint(\n            -self.horizontalScrollBar().value(),\n            -self.verticalScrollBar().value(),\n        )\n        result = self._checkbox_handler.find_checkbox_at_click(\n            click_pos, scroll_offset\n        )\n        if result is None:\n            return False, None\n        return result\n\n    def mousePressEvent(self, event) -&gt; None:\n        \"\"\"Handle mouse press events for checkboxes.\n\n        Checkboxes can be toggled even in read-only mode.\n        \"\"\"\n        is_cb, cb_pos = self._is_checkbox_at_cursor(event.pos())\n        if is_cb and cb_pos is not None:\n            assert self._checkbox_handler is not None  # implied by is_cb==True\n            checkbox_idx = self._checkbox_handler.get_checkbox_at_position(\n                cb_pos\n            )\n            if checkbox_idx is not None:\n                self._checkbox_handler.toggle_checkbox(checkbox_idx)\n                self.viewport().update()\n                event.accept()\n                return\n\n        super().mousePressEvent(event)\n\n    def mouseMoveEvent(self, event):\n        \"\"\"Show arrow cursor over checkboxes, hand over links, I-beam else.\"\"\"\n        pos = event.pos()\n        cursor = self.cursorForPosition(pos)\n        fmt = cursor.charFormat()\n        if fmt.objectType() == CHECKBOX_FORMAT_TYPE:\n            self.viewport().setCursor(Qt.CursorShape.ArrowCursor)\n        elif fmt.isAnchor():\n            self.viewport().setCursor(Qt.CursorShape.PointingHandCursor)\n        else:\n            self.viewport().setCursor(Qt.CursorShape.IBeamCursor)\n        super().mouseMoveEvent(event)\n\n    def set_style(self, style: str) -&gt; None:\n        \"\"\"Apply a character style to the current selection or cursor.\n\n        Styles are merged with the existing character formatting so that\n        multiple styles (e.g. bold + italic) can be combined without\n        removing previously applied styles.\n\n        Args:\n            style: Style identifier string (e.g. ``\"stl_bold\"``).\n        \"\"\"\n        cursor = self.textCursor()\n\n        # Suppress formatting during style application\n        self._suppress_formatting = True\n\n        cursor.beginEditBlock()\n\n        if style == \"stl_bold\":\n            # Toggle bold, preserving all other formatting\n            current_weight = cursor.charFormat().fontWeight()\n            new_weight = (\n                QFont.Weight.Normal\n                if current_weight == QFont.Weight.Bold\n                else QFont.Weight.Bold\n            )\n            fmt = QTextCharFormat()\n            fmt.setFontWeight(new_weight)\n\n            if cursor.hasSelection():\n                cursor.mergeCharFormat(fmt)\n            else:\n                self.mergeCurrentCharFormat(fmt)\n\n            self.setTextCursor(cursor)\n\n        elif style == \"stl_italic\":\n            # Toggle italic, preserving all other formatting\n            new_italic = not cursor.charFormat().fontItalic()\n            fmt = QTextCharFormat()\n            fmt.setFontItalic(new_italic)\n\n            if cursor.hasSelection():\n                cursor.mergeCharFormat(fmt)\n            else:\n                self.mergeCurrentCharFormat(fmt)\n\n            self.setTextCursor(cursor)\n\n        elif style == \"stl_h1\":\n            # Toggle heading size, preserving all other formatting\n            base_size = self.font().pointSize()\n            current_size = cursor.charFormat().fontPointSize()\n\n            fmt = QTextCharFormat()\n            if current_size &gt; base_size:  # Already a header\n                fmt.setFontPointSize(base_size)\n                fmt.setFontWeight(QFont.Weight.Normal)\n            else:  # Make it a header\n                fmt.setFontPointSize(base_size * 1.5)\n                fmt.setFontWeight(QFont.Weight.Bold)\n\n            if cursor.hasSelection():\n                cursor.mergeCharFormat(fmt)\n            else:\n                self.mergeCurrentCharFormat(fmt)\n\n            self.setTextCursor(cursor)\n\n        elif style == \"stl_link\":\n            pw = self.parentWidget()\n            if not pw:\n                return\n\n            selected_text = (\n                cursor.selectedText() if cursor.hasSelection() else \"\"\n            )\n            field = QtWidgets.QLineEdit(selected_text, parent=pw)\n\n            def _make_link():\n                link = field.text()\n                fmt = QTextCharFormat()\n                fmt.setAnchor(True)\n                fmt.setAnchorHref(link)\n                fmt.setFontUnderline(True)\n\n                if cursor.hasSelection():\n                    cursor.mergeCharFormat(fmt)\n                else:\n                    self.mergeCurrentCharFormat(fmt)\n\n                field.close()\n                field.deleteLater()\n                self.setFocus()\n                self.update()\n\n            # open link edit field\n            field.show()\n            fr = field.rect()\n            field.setGeometry(4, 0, self.rect().width(), fr.height())\n            field.selectAll()\n            field.setFocus()\n            field.returnPressed.connect(_make_link)\n\n        elif style == \"stl_code\":\n            # Detect if already in code style\n            is_code = cursor.charFormat().fontFixedPitch()\n            fmt = QTextCharFormat()\n\n            if is_code:\n                # Toggle off: revert code-specific properties to widget defaults\n                fmt.setFontFixedPitch(False)\n                fmt.setFontFamilies([self.font().family()])\n                fmt.setBackground(\n                    self.palette().color(QPalette.ColorRole.Base)\n                )\n                fmt.setForeground(\n                    self.palette().color(QPalette.ColorRole.Text)\n                )\n            else:\n                # Toggle on: apply code style\n                fmt.setFontFixedPitch(True)\n                fmt.setFontFamilies(\n                    [\"Courier New\", \"Menlo\", \"Monaco\", \"monospace\"]\n                )\n                fmt.setBackground(CODE_BG)\n                fmt.setForeground(CODE_FG)\n\n            if cursor.hasSelection():\n                cursor.mergeCharFormat(fmt)\n            else:\n                self.mergeCurrentCharFormat(fmt)\n\n            self.setTextCursor(cursor)\n\n        cursor.endEditBlock()\n        self._suppress_formatting = False\n        self.setFocus()\n\n    def _insert_fmt_checklist(self) -&gt; None:\n        \"\"\"Insert an unchecked checklist checkbox at the current cursor.\n\n        If the cursor is on a bullet or numbered list line, the list\n        item is converted into a checkbox line, preserving its text.\n        Otherwise inserts on the current (empty) block, or on a new\n        block inserted above when the current line is non-empty.\n        \"\"\"\n        self._setup_checkbox_handler()\n        assert self._checkbox_handler is not None\n\n        self._suppress_formatting = True\n        cursor = self.textCursor()\n        cursor.beginEditBlock()\n\n        block = cursor.block()\n        text_list = block.textList()\n\n        if text_list is not None:\n            # Convert existing list item to checkbox.\n            # Qt stores block text WITHOUT the list marker,\n            # so block.text() gives us the clean content.\n            line_text = block.text().strip()\n\n            # Remove this block from the QTextList\n            text_list.remove(block)\n\n            # Reset the block indent that the QTextList left behind\n            block_fmt = cursor.blockFormat()\n            block_fmt.setIndent(0)\n            cursor.setBlockFormat(block_fmt)\n\n            # Select all content in the block and delete it\n            cursor.movePosition(QTextCursor.MoveOperation.StartOfBlock)\n            cursor.movePosition(\n                QTextCursor.MoveOperation.EndOfBlock,\n                QTextCursor.MoveMode.KeepAnchor,\n            )\n            cursor.removeSelectedText()\n\n            # Insert checkbox + original text\n            self._insert_checkbox_at_cursor(cursor)\n            cursor.insertText(line_text)\n        else:\n            # Original behavior for plain text\n            cursor.movePosition(QTextCursor.MoveOperation.StartOfBlock)\n            if cursor.block().text().strip():\n                cursor.insertBlock()\n                cursor.movePosition(QTextCursor.MoveOperation.PreviousBlock)\n                cursor.movePosition(QTextCursor.MoveOperation.StartOfBlock)\n\n            self._insert_checkbox_at_cursor(cursor)\n\n        cursor.endEditBlock()\n        self._suppress_formatting = False\n        self.setTextCursor(cursor)\n        self.setFocus()\n\n    def set_format(self, format: str) -&gt; None:\n        \"\"\"Set up the bullet/numbered/checklist formatting.\"\"\"\n        if format == \"fmt_checklist\":\n            self._insert_fmt_checklist()\n            return\n\n        cursor = self.textCursor()\n        cursor.beginEditBlock()\n        cursor.movePosition(QTextCursor.MoveOperation.StartOfBlock)\n\n        if format == \"fmt_bullet\":\n            list_fmt = QTextListFormat()\n            list_fmt.setStyle(QTextListFormat.Style.ListDisc)\n            cursor.createList(list_fmt)\n        elif format == \"fmt_number\":\n            list_fmt = QTextListFormat()\n            list_fmt.setStyle(QTextListFormat.Style.ListDecimal)\n            cursor.createList(list_fmt)\n\n        cursor.endEditBlock()\n        self.setTextCursor(cursor)\n        self.setFocus()\n\n    def paintEvent(self, event) -&gt; None:\n        \"\"\"Override paintEvent to make sure the placeholder text is not\n        displayed when an empty list is added to an empty document.\"\"\"\n        if (\n            self.placeholderText()\n            and self.document().isEmpty()\n            and self._has_list_block()\n        ):\n            self._suppress_formatting = True\n            saved = self.placeholderText()\n            super().setPlaceholderText(\"\")\n            super().paintEvent(event)\n            super().setPlaceholderText(saved)\n            self._suppress_formatting = False\n            return\n        super().paintEvent(event)\n\n    def _has_list_block(self) -&gt; bool:\n        block = self.document().begin()\n        while block.isValid():\n            if block.textList() is not None:\n                return True\n            block = block.next()\n        return False\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextEditor.as_markdown","title":"<code>as_markdown()</code>","text":"<p>Get the content as GitHub-flavored markdown.</p> <p>Returns:</p> Type Description <code>str</code> <p>Markdown string.</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def as_markdown(self) -&gt; str:\n    \"\"\"Get the content as GitHub-flavored markdown.\n\n    Returns:\n        Markdown string.\n    \"\"\"\n    if self._checkbox_handler and self._checkbox_handler.has_checkboxes():\n        return self._checkbox_handler.to_markdown()\n    return self.document().toMarkdown(MD_DIALECT)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextEditor.keyPressEvent","title":"<code>keyPressEvent(event)</code>","text":"<p>Handle key press events for completer.</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def keyPressEvent(self, event) -&gt; None:\n    \"\"\"Handle key press events for completer.\"\"\"\n    if on_completer_key_press(self, event):\n        event.accept()\n        return\n\n    # ctrl/cmd-enter to submit\n    if (\n        event.key() in {Qt.Key.Key_Return, Qt.Key.Key_Enter}\n        and event.modifiers() &amp; Qt.KeyboardModifier.ControlModifier\n    ):\n        self.submitted.emit()\n\n    # Auto-continue checkbox on Enter\n    if (\n        event.key() in {Qt.Key.Key_Return, Qt.Key.Key_Enter}\n        and self._checkbox_handler\n        and self._checkbox_handler.has_checkboxes()\n    ):\n        cursor = self.textCursor()\n        block_text = cursor.block().text()\n\n        if \"\\ufffc\" in block_text:\n            # Extract text after the checkbox object char\n            parts = block_text.split(\"\\ufffc\", 1)\n            after_checkbox = parts[1].strip() if len(parts) &gt; 1 else \"\"\n\n            if not after_checkbox:\n                # Empty checkbox line \u2192 end the list\n                # Remove the checkbox content from current block\n                cursor.movePosition(\n                    QTextCursor.MoveOperation.StartOfBlock,\n                    QTextCursor.MoveMode.MoveAnchor,\n                )\n                cursor.movePosition(\n                    QTextCursor.MoveOperation.EndOfBlock,\n                    QTextCursor.MoveMode.KeepAnchor,\n                )\n                cursor.removeSelectedText()\n                # Remove the last checkbox from handler\n                self._checkbox_handler.remove_last_checkbox()\n                # Insert a plain newline\n                super().keyPressEvent(event)\n                return\n\n            # Non-empty checkbox line \u2192 insert new checkbox\n            event.accept()\n            self._suppress_formatting = True\n\n            cursor.beginEditBlock()\n            cursor.movePosition(QTextCursor.MoveOperation.EndOfBlock)\n            cursor.insertBlock()\n            self._insert_checkbox_at_cursor(cursor)\n            cursor.endEditBlock()\n\n            self._suppress_formatting = False\n            self.setTextCursor(cursor)\n            return\n\n    super().keyPressEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextEditor.mouseMoveEvent","title":"<code>mouseMoveEvent(event)</code>","text":"<p>Show arrow cursor over checkboxes, hand over links, I-beam else.</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def mouseMoveEvent(self, event):\n    \"\"\"Show arrow cursor over checkboxes, hand over links, I-beam else.\"\"\"\n    pos = event.pos()\n    cursor = self.cursorForPosition(pos)\n    fmt = cursor.charFormat()\n    if fmt.objectType() == CHECKBOX_FORMAT_TYPE:\n        self.viewport().setCursor(Qt.CursorShape.ArrowCursor)\n    elif fmt.isAnchor():\n        self.viewport().setCursor(Qt.CursorShape.PointingHandCursor)\n    else:\n        self.viewport().setCursor(Qt.CursorShape.IBeamCursor)\n    super().mouseMoveEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextEditor.mousePressEvent","title":"<code>mousePressEvent(event)</code>","text":"<p>Handle mouse press events for checkboxes.</p> <p>Checkboxes can be toggled even in read-only mode.</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def mousePressEvent(self, event) -&gt; None:\n    \"\"\"Handle mouse press events for checkboxes.\n\n    Checkboxes can be toggled even in read-only mode.\n    \"\"\"\n    is_cb, cb_pos = self._is_checkbox_at_cursor(event.pos())\n    if is_cb and cb_pos is not None:\n        assert self._checkbox_handler is not None  # implied by is_cb==True\n        checkbox_idx = self._checkbox_handler.get_checkbox_at_position(\n            cb_pos\n        )\n        if checkbox_idx is not None:\n            self._checkbox_handler.toggle_checkbox(checkbox_idx)\n            self.viewport().update()\n            event.accept()\n            return\n\n    super().mousePressEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextEditor.paintEvent","title":"<code>paintEvent(event)</code>","text":"<p>Override paintEvent to make sure the placeholder text is not displayed when an empty list is added to an empty document.</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def paintEvent(self, event) -&gt; None:\n    \"\"\"Override paintEvent to make sure the placeholder text is not\n    displayed when an empty list is added to an empty document.\"\"\"\n    if (\n        self.placeholderText()\n        and self.document().isEmpty()\n        and self._has_list_block()\n    ):\n        self._suppress_formatting = True\n        saved = self.placeholderText()\n        super().setPlaceholderText(\"\")\n        super().paintEvent(event)\n        super().setPlaceholderText(saved)\n        self._suppress_formatting = False\n        return\n    super().paintEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextEditor.set_format","title":"<code>set_format(format)</code>","text":"<p>Set up the bullet/numbered/checklist formatting.</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def set_format(self, format: str) -&gt; None:\n    \"\"\"Set up the bullet/numbered/checklist formatting.\"\"\"\n    if format == \"fmt_checklist\":\n        self._insert_fmt_checklist()\n        return\n\n    cursor = self.textCursor()\n    cursor.beginEditBlock()\n    cursor.movePosition(QTextCursor.MoveOperation.StartOfBlock)\n\n    if format == \"fmt_bullet\":\n        list_fmt = QTextListFormat()\n        list_fmt.setStyle(QTextListFormat.Style.ListDisc)\n        cursor.createList(list_fmt)\n    elif format == \"fmt_number\":\n        list_fmt = QTextListFormat()\n        list_fmt.setStyle(QTextListFormat.Style.ListDecimal)\n        cursor.createList(list_fmt)\n\n    cursor.endEditBlock()\n    self.setTextCursor(cursor)\n    self.setFocus()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextEditor.set_markdown","title":"<code>set_markdown(md)</code>","text":"<p>Set markdown content with checkbox support.</p> <p>Parameters:</p> Name Type Description Default <code>md</code> <code>str</code> <p>Markdown text to display</p> required Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def set_markdown(self, md: str) -&gt; None:\n    \"\"\"Set markdown content with checkbox support.\n\n    Args:\n        md: Markdown text to display\n    \"\"\"\n    if CheckboxHandler.contains_checkboxes(md):\n        self._setup_checkbox_handler()\n        assert self._checkbox_handler is not None\n        self._checkbox_handler.parse_and_render(md)\n    else:\n        self.document().setMarkdown(md, MD_DIALECT)\n    apply_code_block_backgrounds(self)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AYTextEditor.set_style","title":"<code>set_style(style)</code>","text":"<p>Apply a character style to the current selection or cursor.</p> <p>Styles are merged with the existing character formatting so that multiple styles (e.g. bold + italic) can be combined without removing previously applied styles.</p> <p>Parameters:</p> Name Type Description Default <code>style</code> <code>str</code> <p>Style identifier string (e.g. <code>\"stl_bold\"</code>).</p> required Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def set_style(self, style: str) -&gt; None:\n    \"\"\"Apply a character style to the current selection or cursor.\n\n    Styles are merged with the existing character formatting so that\n    multiple styles (e.g. bold + italic) can be combined without\n    removing previously applied styles.\n\n    Args:\n        style: Style identifier string (e.g. ``\"stl_bold\"``).\n    \"\"\"\n    cursor = self.textCursor()\n\n    # Suppress formatting during style application\n    self._suppress_formatting = True\n\n    cursor.beginEditBlock()\n\n    if style == \"stl_bold\":\n        # Toggle bold, preserving all other formatting\n        current_weight = cursor.charFormat().fontWeight()\n        new_weight = (\n            QFont.Weight.Normal\n            if current_weight == QFont.Weight.Bold\n            else QFont.Weight.Bold\n        )\n        fmt = QTextCharFormat()\n        fmt.setFontWeight(new_weight)\n\n        if cursor.hasSelection():\n            cursor.mergeCharFormat(fmt)\n        else:\n            self.mergeCurrentCharFormat(fmt)\n\n        self.setTextCursor(cursor)\n\n    elif style == \"stl_italic\":\n        # Toggle italic, preserving all other formatting\n        new_italic = not cursor.charFormat().fontItalic()\n        fmt = QTextCharFormat()\n        fmt.setFontItalic(new_italic)\n\n        if cursor.hasSelection():\n            cursor.mergeCharFormat(fmt)\n        else:\n            self.mergeCurrentCharFormat(fmt)\n\n        self.setTextCursor(cursor)\n\n    elif style == \"stl_h1\":\n        # Toggle heading size, preserving all other formatting\n        base_size = self.font().pointSize()\n        current_size = cursor.charFormat().fontPointSize()\n\n        fmt = QTextCharFormat()\n        if current_size &gt; base_size:  # Already a header\n            fmt.setFontPointSize(base_size)\n            fmt.setFontWeight(QFont.Weight.Normal)\n        else:  # Make it a header\n            fmt.setFontPointSize(base_size * 1.5)\n            fmt.setFontWeight(QFont.Weight.Bold)\n\n        if cursor.hasSelection():\n            cursor.mergeCharFormat(fmt)\n        else:\n            self.mergeCurrentCharFormat(fmt)\n\n        self.setTextCursor(cursor)\n\n    elif style == \"stl_link\":\n        pw = self.parentWidget()\n        if not pw:\n            return\n\n        selected_text = (\n            cursor.selectedText() if cursor.hasSelection() else \"\"\n        )\n        field = QtWidgets.QLineEdit(selected_text, parent=pw)\n\n        def _make_link():\n            link = field.text()\n            fmt = QTextCharFormat()\n            fmt.setAnchor(True)\n            fmt.setAnchorHref(link)\n            fmt.setFontUnderline(True)\n\n            if cursor.hasSelection():\n                cursor.mergeCharFormat(fmt)\n            else:\n                self.mergeCurrentCharFormat(fmt)\n\n            field.close()\n            field.deleteLater()\n            self.setFocus()\n            self.update()\n\n        # open link edit field\n        field.show()\n        fr = field.rect()\n        field.setGeometry(4, 0, self.rect().width(), fr.height())\n        field.selectAll()\n        field.setFocus()\n        field.returnPressed.connect(_make_link)\n\n    elif style == \"stl_code\":\n        # Detect if already in code style\n        is_code = cursor.charFormat().fontFixedPitch()\n        fmt = QTextCharFormat()\n\n        if is_code:\n            # Toggle off: revert code-specific properties to widget defaults\n            fmt.setFontFixedPitch(False)\n            fmt.setFontFamilies([self.font().family()])\n            fmt.setBackground(\n                self.palette().color(QPalette.ColorRole.Base)\n            )\n            fmt.setForeground(\n                self.palette().color(QPalette.ColorRole.Text)\n            )\n        else:\n            # Toggle on: apply code style\n            fmt.setFontFixedPitch(True)\n            fmt.setFontFamilies(\n                [\"Courier New\", \"Menlo\", \"Monaco\", \"monospace\"]\n            )\n            fmt.setBackground(CODE_BG)\n            fmt.setForeground(CODE_FG)\n\n        if cursor.hasSelection():\n            cursor.mergeCharFormat(fmt)\n        else:\n            self.mergeCurrentCharFormat(fmt)\n\n        self.setTextCursor(cursor)\n\n    cursor.endEditBlock()\n    self._suppress_formatting = False\n    self.setFocus()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AttachmentWidget","title":"<code>AttachmentWidget</code>","text":"<p>               Bases: <code>QWidget</code></p> <p>Widget to display a single attachment thumbnail with remove button.</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>class AttachmentWidget(QtWidgets.QWidget):\n    \"\"\"Widget to display a single attachment thumbnail with remove button.\"\"\"\n\n    remove_clicked = Signal(int, str)  # Signal emits (index, type: 'screenshot' or 'file')\n    thumbnail_clicked = Signal(int, str)  # Signal emits (index, type) when thumbnail clicked\n\n    def __init__(self, parent=None, index=0, filename=\"\", file_path=\"\", attachment_type=\"file\"):\n        super().__init__(parent)\n        self.index = index\n        self.filename = filename\n        self.file_path = file_path\n        self.attachment_type = attachment_type  # 'screenshot' or 'file'\n        self.setup_ui()\n        self.load_image()\n\n    def setup_ui(self):\n        # Use a container for the thumbnail with overlay button\n        container = QtWidgets.QWidget(self)\n        container.setFixedSize(80, 60)\n        container.setCursor(Qt.CursorShape.PointingHandCursor)\n\n        # Thumbnail\n        self.thumbnail_label = QLabel(container)\n        self.thumbnail_label.setFixedSize(80, 60)\n        self.thumbnail_label.setScaledContents(True)\n        self.thumbnail_label.setAlignment(Qt.AlignmentFlag.AlignCenter)\n        self.thumbnail_label.setStyleSheet(\n            \"QLabel { background-color: #2b2b2b; border: 1px solid #3d3d3d; }\"\n        )\n\n        # Make thumbnail clickable\n        self.thumbnail_label.mousePressEvent = lambda e: self.thumbnail_clicked.emit(\n            self.index, self.attachment_type\n        )\n\n        # Remove button overlaid on top-right corner\n        self.remove_btn = AYButton(\n            \"\u00d7\", variant=AYButton.Variants.Nav, parent=container\n        )\n        self.remove_btn.setFixedSize(18, 18)\n        self.remove_btn.move(62, 0)  # Position at top-right corner\n        self.remove_btn.clicked.connect(\n            lambda: self.remove_clicked.emit(self.index, self.attachment_type)\n        )\n        self.remove_btn.raise_()\n\n        # Main layout\n        layout = AYVBoxLayout(margin=4, spacing=2)\n        layout.addWidget(container)\n\n        # Filename label (truncated)\n        self.filename_label = QLabel(self)\n        self.filename_label.setAlignment(Qt.AlignmentFlag.AlignCenter)\n        self.filename_label.setStyleSheet(\"font-size: 10px; color: #9aa4ad;\")\n        layout.addWidget(self.filename_label)\n\n        self.setLayout(layout)\n        self.update_display()\n\n        # Set tooltip\n        self.setToolTip(self.filename)\n\n    def load_image(self):\n        \"\"\"Load thumbnail from file_path\"\"\"\n        pixmap = QPixmap(self.file_path)\n        if not pixmap.isNull():\n            self.thumbnail_label.setPixmap(\n                pixmap.scaled(\n                    80,\n                    60,\n                    Qt.AspectRatioMode.KeepAspectRatio,\n                    Qt.TransformationMode.SmoothTransformation,\n                )\n            )\n        else:\n            self.thumbnail_label.setText(\"Image\")\n\n    def update_display(self):\n        \"\"\"Update the display with current filename and image\"\"\"\n        # Update filename label\n        display_name = self.filename[:10] + \"...\" if len(self.filename) &gt; 10 else self.filename\n        self.filename_label.setText(display_name)\n        self.load_image()\n\n    def update_content(self, filename=\"\", file_path=\"\"):\n        \"\"\"Update the widget content\"\"\"\n        if filename:\n            self.filename = filename\n            self.setToolTip(filename)\n        if file_path:\n            self.file_path = file_path\n        self.update_display()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AttachmentWidget.load_image","title":"<code>load_image()</code>","text":"<p>Load thumbnail from file_path</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def load_image(self):\n    \"\"\"Load thumbnail from file_path\"\"\"\n    pixmap = QPixmap(self.file_path)\n    if not pixmap.isNull():\n        self.thumbnail_label.setPixmap(\n            pixmap.scaled(\n                80,\n                60,\n                Qt.AspectRatioMode.KeepAspectRatio,\n                Qt.TransformationMode.SmoothTransformation,\n            )\n        )\n    else:\n        self.thumbnail_label.setText(\"Image\")\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AttachmentWidget.update_content","title":"<code>update_content(filename='', file_path='')</code>","text":"<p>Update the widget content</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def update_content(self, filename=\"\", file_path=\"\"):\n    \"\"\"Update the widget content\"\"\"\n    if filename:\n        self.filename = filename\n        self.setToolTip(filename)\n    if file_path:\n        self.file_path = file_path\n    self.update_display()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_box.html#client.ayon_ui_qt.components.text_box.AttachmentWidget.update_display","title":"<code>update_display()</code>","text":"<p>Update the display with current filename and image</p> Source code in <code>client/ayon_ui_qt/components/text_box.py</code> <pre><code>def update_display(self):\n    \"\"\"Update the display with current filename and image\"\"\"\n    # Update filename label\n    display_name = self.filename[:10] + \"...\" if len(self.filename) &gt; 10 else self.filename\n    self.filename_label.setText(display_name)\n    self.load_image()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_edit.html","title":"text_edit","text":"<p>text edit</p>"},{"location":"autoapi/client/ayon_ui_qt/components/text_edit.html#client.ayon_ui_qt.components.text_edit.AYTextEdit","title":"<code>AYTextEdit</code>","text":"<p>               Bases: <code>QTextEdit</code></p> <p>AYON styled text edit widget.</p> <p>Overrides Qt's stylesheet painting with AYONStyle custom rendering.</p> <p>Parameters:</p> Name Type Description Default <code>*args</code> <p>Positional arguments passed to QTextEdit.</p> <code>()</code> <code>**kwargs</code> <p>Keyword arguments passed to QTextEdit.</p> <code>{}</code> Source code in <code>client/ayon_ui_qt/components/text_edit.py</code> <pre><code>class AYTextEdit(QTextEdit):\n    \"\"\"AYON styled text edit widget.\n\n    Overrides Qt's stylesheet painting with AYONStyle custom rendering.\n\n    Args:\n        *args: Positional arguments passed to QTextEdit.\n        **kwargs: Keyword arguments passed to QTextEdit.\n    \"\"\"\n\n    Variants = QTextEditVariants\n\n    def __init__(\n        self,\n        *args,\n        variant: Variants = Variants.Default,\n        **kwargs,\n    ):\n        \"\"\"Initialize AYTextEdit widget.\n\n        Args:\n            *args: Positional arguments passed to QTextEdit.\n            variant: Text edit variant.\n            **kwargs: Keyword arguments passed to QTextEdit.\n        \"\"\"\n        self._variant_str: str = variant.value\n        super().__init__(*args, **kwargs)\n        self.setStyle(get_ayon_style())\n        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/text_edit.html#client.ayon_ui_qt.components.text_edit.AYTextEdit.__init__","title":"<code>__init__(*args, variant=Variants.Default, **kwargs)</code>","text":"<p>Initialize AYTextEdit widget.</p> <p>Parameters:</p> Name Type Description Default <code>*args</code> <p>Positional arguments passed to QTextEdit.</p> <code>()</code> <code>variant</code> <code>Variants</code> <p>Text edit variant.</p> <code>Default</code> <code>**kwargs</code> <p>Keyword arguments passed to QTextEdit.</p> <code>{}</code> Source code in <code>client/ayon_ui_qt/components/text_edit.py</code> <pre><code>def __init__(\n    self,\n    *args,\n    variant: Variants = Variants.Default,\n    **kwargs,\n):\n    \"\"\"Initialize AYTextEdit widget.\n\n    Args:\n        *args: Positional arguments passed to QTextEdit.\n        variant: Text edit variant.\n        **kwargs: Keyword arguments passed to QTextEdit.\n    \"\"\"\n    self._variant_str: str = variant.value\n    super().__init__(*args, **kwargs)\n    self.setStyle(get_ayon_style())\n    self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html","title":"tree_model","text":"<p>Lazy-loading tree model for AYON UI Qt components.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel","title":"<code>LazyTreeModel</code>","text":"<p>               Bases: <code>QAbstractItemModel</code></p> <p>Qt model that lazily loads children via a callback.</p> <p>Children are fetched on demand using Qt's canFetchMore/fetchMore protocol. The root level is loaded asynchronously on construction.</p> <p>Parameters:</p> Name Type Description Default <code>fetch_children</code> <code>Callable[[str | None], list[TreeNode]]</code> <p>Callable that takes a parent node ID (<code>None</code> for root) and returns a list of :class:<code>TreeNode</code> instances.</p> required <code>no_async</code> <code>bool</code> <p>When <code>True</code>, children are fetched synchronously on the main thread instead of via the :class:<code>AsyncTaskQueue</code>. Useful in tests to avoid worker-thread/paint-event races.</p> <code>False</code> <code>parent</code> <code>QObject | None</code> <p>Optional parent QObject.</p> <code>None</code> <p>.. warning::     Async mode and <code>expandAll()</code>: Because root children are     fetched asynchronously, calling <code>view.expandAll()</code> immediately     after constructing the model will silently expand nothing \u2014     <code>hasChildren()</code> returns <code>False</code> until the first fetch     completes.  Connect to :attr:<code>loading_changed</code> and call     <code>expandAll()</code> once it emits <code>False</code>::</p> <pre><code>    model.loading_changed.connect(\n        lambda loading: view.expandAll() if not loading else None\n    )\n</code></pre> <p>Example::</p> <pre><code>def fetch(parent_id):\n    if parent_id is None:\n        return [TreeNode(\"root\", \"Root\", has_children=True)]\n    return []\n\nmodel = LazyTreeModel(fetch_children=fetch)\n</code></pre> Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>class LazyTreeModel(QAbstractItemModel):\n    \"\"\"Qt model that lazily loads children via a callback.\n\n    Children are fetched on demand using Qt's canFetchMore/fetchMore\n    protocol. The root level is loaded asynchronously on construction.\n\n    Args:\n        fetch_children: Callable that takes a parent node ID (``None``\n            for root) and returns a list of :class:`TreeNode` instances.\n        no_async: When ``True``, children are fetched synchronously on\n            the main thread instead of via the :class:`AsyncTaskQueue`.\n            Useful in tests to avoid worker-thread/paint-event races.\n        parent: Optional parent QObject.\n\n    .. warning::\n        **Async mode and ``expandAll()``**: Because root children are\n        fetched asynchronously, calling ``view.expandAll()`` immediately\n        after constructing the model will silently expand nothing \u2014\n        ``hasChildren()`` returns ``False`` until the first fetch\n        completes.  Connect to :attr:`loading_changed` and call\n        ``expandAll()`` once it emits ``False``::\n\n            model.loading_changed.connect(\n                lambda loading: view.expandAll() if not loading else None\n            )\n\n    Example::\n\n        def fetch(parent_id):\n            if parent_id is None:\n                return [TreeNode(\"root\", \"Root\", has_children=True)]\n            return []\n\n        model = LazyTreeModel(fetch_children=fetch)\n    \"\"\"\n\n    loading_changed = Signal(bool)  # True while any fetch is in-flight\n    fetch_error = Signal(str)  # error message when a fetch fails\n    pending_count_changed = Signal(int)  # number of in-flight fetch tasks\n\n    def __init__(\n        self,\n        fetch_children: Callable[[str | None], list[TreeNode]],\n        no_async: bool = False,\n        parent: QObject | None = None,\n    ) -&gt; None:\n        super().__init__(parent)\n        self._fetch_children = fetch_children\n        self._no_async: bool = no_async\n        self._reset_counter: int = 0\n        self._context_id: str = f\"ltm_{id(self)}_v0\"\n        self._pending_tasks: int = 0\n        self._root = _InternalNode(tree_node=None, parent=None)\n        # _all_nodes keeps every node reachable so Python's GC does not\n        # collect objects that are held only via QModelIndex.internalPointer().\n        self._all_nodes: set[_InternalNode] = {self._root}\n        self._fetch_children_async(self._root)\n\n    def _update_loading_state(self) -&gt; None:\n        \"\"\"Emit loading-progress signals based on current pending task count.\"\"\"\n        self.pending_count_changed.emit(self._pending_tasks)\n        self.loading_changed.emit(self._pending_tasks &gt; 0)\n\n    def _index_for_node(self, node: _InternalNode) -&gt; QModelIndex:\n        \"\"\"Return the QModelIndex that identifies node (column 0).\n\n        Args:\n            node: A non-root internal node.\n\n        Returns:\n            Valid QModelIndex for non-root nodes, invalid for root.\n        \"\"\"\n        if node.is_root:\n            return QModelIndex()\n        parent = node.parent\n        row = parent.children.index(node)  # type: ignore[union-attr]\n        return self.createIndex(row, 0, node)\n\n    def _on_children_ready(\n        self,\n        node: _InternalNode,\n        context_id: str,\n        results: list[TreeNode] | None,\n    ) -&gt; None:\n        \"\"\"Handle fetch results on the main thread.\n\n        Called via Qt.QueuedConnection from AsyncTaskQueue so it always\n        executes on the Qt main thread, making it safe to call Qt model\n        mutation methods.\n\n        Args:\n            node: The node whose children were fetched.\n            context_id: The context_id active when the task was enqueued.\n                Used to discard stale results.\n            results: TreeNode list returned by fetch_children, or None on\n                error.\n        \"\"\"\n        # Always release the fetching guard so the node is never stuck\n        # in-flight, even for stale callbacks.\n        node.is_fetching = False\n\n        # Discard stale results (model was reset while this task was running).\n        if context_id != self._context_id or node not in self._all_nodes:\n            log.debug(\n                \"Discarding stale fetch result for node %r (ctx %s vs %s)\",\n                node.tree_node.id if node.tree_node else \"root\",\n                context_id,\n                self._context_id,\n            )\n            return\n\n        self._pending_tasks = max(0, self._pending_tasks - 1)\n\n        if results is None:\n            node_id = node.tree_node.id if node.tree_node else \"root\"\n            self.fetch_error.emit(\n                f\"Failed to fetch children for node {node_id!r}\"\n            )\n            # Do NOT set children_loaded=True on error so that the\n            # caller can retry by calling reset().  The node stays in\n            # a \"not loaded\" state; is_fetching was already cleared\n            # above so a subsequent fetchMore() or reset() can re-try.\n            self._update_loading_state()\n            return\n\n        new_nodes = [\n            _InternalNode(tree_node=tn, parent=node) for tn in results\n        ]\n        if new_nodes:\n            parent_index = self._index_for_node(node)\n            self.beginInsertRows(parent_index, 0, len(new_nodes) - 1)\n            node.children = new_nodes\n            for child in new_nodes:\n                self._all_nodes.add(child)\n            node.children_loaded = True\n            self.endInsertRows()\n        else:\n            node.children_loaded = True\n\n        self._update_loading_state()\n\n    def _fetch_children_async(self, node: _InternalNode) -&gt; None:\n        \"\"\"Enqueue an async task to fetch children for *node*.\n\n        Uses a per-node re-entrancy guard (``node.is_fetching``) to\n        prevent duplicate tasks.  Results are delivered back on the main\n        thread via :meth:`_on_children_ready`.\n\n        Args:\n            node: The node whose children to fetch.\n        \"\"\"\n        if node.is_fetching or node.children_loaded:\n            return\n        node.is_fetching = True\n\n        parent_id = None if node.is_root else node.tree_node.id  # type: ignore[union-attr]\n        ctx = self._context_id\n\n        self._pending_tasks += 1\n        self._update_loading_state()\n\n        if self._no_async:\n            try:\n                result: list[TreeNode] | None = self._fetch_children(parent_id)\n            except Exception:\n                log.exception(\n                    \"fetch_children raised for parent_id=%r\", parent_id\n                )\n                result = None\n            self._on_children_ready(node, ctx, result)\n            return\n\n        task = AsyncTask(\n            name=f\"fetch_children_{parent_id or 'root'}\",\n            function=lambda: self._fetch_children(parent_id),\n            callback=lambda result: self._on_children_ready(node, ctx, result),\n            priority=1,\n            context_id=ctx,\n            cancellable=True,\n        )\n        get_task_queue().enqueue(task)\n\n    def _node_from_index(\n        self, index: QModelIndex | QPersistentModelIndex\n    ) -&gt; _InternalNode:\n        \"\"\"Return the internal node for a model index.\n\n        Args:\n            index: A valid or invalid QModelIndex.\n\n        Returns:\n            The corresponding _InternalNode; returns root for invalid\n            indexes.\n        \"\"\"\n        if not index.isValid():\n            return self._root\n        return index.internalPointer()  # type: ignore[return-value]\n\n    # keep old name as alias for backward compatibility\n    def _node_for_index(self, index: QModelIndex) -&gt; _InternalNode:\n        \"\"\"Alias for _node_from_index.\"\"\"\n        return self._node_from_index(index)\n\n    def index(\n        self,\n        row: int,\n        column: int,\n        parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n    ) -&gt; QModelIndex:\n        \"\"\"Create a model index for the given row/column under parent.\n\n        Args:\n            row: Row number under the parent.\n            column: Column number (always 0).\n            parent: Parent index.\n\n        Returns:\n            A valid QModelIndex, or an invalid one if out of range.\n        \"\"\"\n        parent_node = self._node_from_index(parent)\n        if row &lt; 0 or row &gt;= len(parent_node.children):\n            return QModelIndex()\n        child_node = parent_node.children[row]\n        return self.createIndex(row, column, child_node)\n\n    def parent(self, index: QModelIndex) -&gt; QModelIndex:  # type: ignore[override]\n        \"\"\"Return the parent index of the given index.\n\n        Args:\n            index: A model index whose parent is requested.\n\n        Returns:\n            Parent QModelIndex, or an invalid index if parent is root.\n        \"\"\"\n        if not index.isValid():\n            return QModelIndex()\n\n        node: _InternalNode = index.internalPointer()  # type: ignore[assignment]\n        parent_node = node.parent\n        if parent_node is None or parent_node.is_root:\n            return QModelIndex()\n\n        # grandparent is always non-None for a non-root parent_node\n        grandparent = parent_node.parent\n        row = grandparent.children.index(parent_node)  # type: ignore[union-attr]\n        return self.createIndex(row, 0, parent_node)\n\n    def rowCount(\n        self, parent: QModelIndex | QPersistentModelIndex = QModelIndex()\n    ) -&gt; int:\n        \"\"\"Return the number of rows under the given parent.\n\n        Args:\n            parent: The parent index.\n\n        Returns:\n            Number of loaded children. Returns 0 for nodes whose\n            children have not been fetched yet; Qt uses hasChildren()\n            to decide whether to show a disclosure triangle.\n        \"\"\"\n        node = self._node_from_index(parent)\n        return len(node.children)\n\n    def columnCount(\n        self, parent: QModelIndex | QPersistentModelIndex = QModelIndex()\n    ) -&gt; int:\n        \"\"\"Return the number of columns (always 1).\n\n        Args:\n            parent: Unused parent index.\n\n        Returns:\n            Always 1.\n        \"\"\"\n        return 1\n\n    def data(\n        self,\n        index: QModelIndex | QPersistentModelIndex,\n        role: int = Qt.ItemDataRole.DisplayRole,\n    ) -&gt; object:\n        \"\"\"Return data for the given index and role.\n\n        Args:\n            index: The model index to query.\n            role: The data role.\n\n        Returns:\n            The node label for DisplayRole, None otherwise.\n        \"\"\"\n        if not index.isValid():\n            return None\n        node: _InternalNode = index.internalPointer()  # type: ignore[assignment]\n        if role == Qt.ItemDataRole.DisplayRole:\n            return node.tree_node.label if node.tree_node else None\n        elif role == Qt.ItemDataRole.DecorationRole:\n            if node.tree_node and node.tree_node.icon:\n                return get_icon(\n                    node.tree_node.icon,\n                    node.tree_node.icon_color,\n                    fill=node.tree_node.icon_fill,\n                )\n        elif role == Qt.ItemDataRole.UserRole:\n            if node.tree_node and node.tree_node.data:\n                return node.tree_node.data\n        return None\n\n    def hasChildren(\n        self, parent: QModelIndex | QPersistentModelIndex = QModelIndex()\n    ) -&gt; bool:\n        \"\"\"Return whether the node at parent has or can have children.\n\n        This is used by Qt to decide whether to draw the disclosure\n        triangle, even before children are loaded.\n\n        Args:\n            parent: The parent index.\n\n        Returns:\n            True if the node has loaded children or has_children is\n            True on the TreeNode.\n        \"\"\"\n        node = self._node_from_index(parent)\n        if node.is_root:\n            return bool(node.children)\n        # node.tree_node is non-None here (is_root is False)\n        if node.children_loaded:\n            return bool(node.children)\n        return node.tree_node.has_children  # type: ignore[union-attr]\n\n    def canFetchMore(\n        self, parent: QModelIndex | QPersistentModelIndex\n    ) -&gt; bool:\n        \"\"\"Return True if more children can be fetched for parent.\n\n        Args:\n            parent: The parent index to check.\n\n        Returns:\n            True if the node has potential children but they have not\n            been loaded yet.\n        \"\"\"\n        node = self._node_from_index(parent)\n        if node.is_root:\n            return False\n        # node.tree_node is non-None here (is_root is False)\n        return (  # type: ignore[union-attr]\n            node.tree_node.has_children and not node.children_loaded\n        )\n\n    def fetchMore(self, parent: QModelIndex | QPersistentModelIndex) -&gt; None:\n        \"\"\"Fetch and insert children for the node at parent.\n\n        Args:\n            parent: The parent index whose children should be loaded.\n        \"\"\"\n        self._fetch_children_async(self._node_from_index(parent))\n\n    def get_node_id(self, index: QModelIndex) -&gt; str | None:\n        \"\"\"Return the TreeNode.id for the given model index.\n\n        Args:\n            index: A valid QModelIndex.\n\n        Returns:\n            The node's string ID, or None if the index is invalid.\n        \"\"\"\n        if not index.isValid():\n            return None\n        node: _InternalNode = index.internalPointer()  # type: ignore[assignment]\n        if node.tree_node is None:\n            return None\n        return node.tree_node.id\n\n    @property\n    def is_loading(self) -&gt; bool:\n        \"\"\"Return True while at least one fetch task is in-flight.\"\"\"\n        return self._pending_tasks &gt; 0\n\n    def reset(self) -&gt; None:\n        \"\"\"Reset the model to its initial state and re-fetch root children.\n\n        This is the recommended recovery path after a failed root fetch\n        (i.e. when :attr:`fetch_error` was emitted for the root node).\n        \"\"\"\n        old_ctx = self._context_id\n        if not self._no_async:\n            get_task_queue().clear_context_tasks(old_ctx)\n        self._reset_counter += 1\n        self._context_id = f\"ltm_{id(self)}_v{self._reset_counter}\"\n        self._pending_tasks = 0\n        self.beginResetModel()\n        self._root = _InternalNode(tree_node=None, parent=None)\n        self._all_nodes = {self._root}\n        self.endResetModel()\n        # Emit loading signals *after* endResetModel so that any slot\n        # connected to loading_changed observes a consistent model state.\n        self._update_loading_state()\n        self._fetch_children_async(self._root)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel.is_loading","title":"<code>is_loading</code>  <code>property</code>","text":"<p>Return True while at least one fetch task is in-flight.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel.canFetchMore","title":"<code>canFetchMore(parent)</code>","text":"<p>Return True if more children can be fetched for parent.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>The parent index to check.</p> required <p>Returns:</p> Type Description <code>bool</code> <p>True if the node has potential children but they have not</p> <code>bool</code> <p>been loaded yet.</p> Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>def canFetchMore(\n    self, parent: QModelIndex | QPersistentModelIndex\n) -&gt; bool:\n    \"\"\"Return True if more children can be fetched for parent.\n\n    Args:\n        parent: The parent index to check.\n\n    Returns:\n        True if the node has potential children but they have not\n        been loaded yet.\n    \"\"\"\n    node = self._node_from_index(parent)\n    if node.is_root:\n        return False\n    # node.tree_node is non-None here (is_root is False)\n    return (  # type: ignore[union-attr]\n        node.tree_node.has_children and not node.children_loaded\n    )\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel.columnCount","title":"<code>columnCount(parent=QModelIndex())</code>","text":"<p>Return the number of columns (always 1).</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Unused parent index.</p> <code>QModelIndex()</code> <p>Returns:</p> Type Description <code>int</code> <p>Always 1.</p> Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>def columnCount(\n    self, parent: QModelIndex | QPersistentModelIndex = QModelIndex()\n) -&gt; int:\n    \"\"\"Return the number of columns (always 1).\n\n    Args:\n        parent: Unused parent index.\n\n    Returns:\n        Always 1.\n    \"\"\"\n    return 1\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel.data","title":"<code>data(index, role=Qt.ItemDataRole.DisplayRole)</code>","text":"<p>Return data for the given index and role.</p> <p>Parameters:</p> Name Type Description Default <code>index</code> <code>QModelIndex | QPersistentModelIndex</code> <p>The model index to query.</p> required <code>role</code> <code>int</code> <p>The data role.</p> <code>DisplayRole</code> <p>Returns:</p> Type Description <code>object</code> <p>The node label for DisplayRole, None otherwise.</p> Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>def data(\n    self,\n    index: QModelIndex | QPersistentModelIndex,\n    role: int = Qt.ItemDataRole.DisplayRole,\n) -&gt; object:\n    \"\"\"Return data for the given index and role.\n\n    Args:\n        index: The model index to query.\n        role: The data role.\n\n    Returns:\n        The node label for DisplayRole, None otherwise.\n    \"\"\"\n    if not index.isValid():\n        return None\n    node: _InternalNode = index.internalPointer()  # type: ignore[assignment]\n    if role == Qt.ItemDataRole.DisplayRole:\n        return node.tree_node.label if node.tree_node else None\n    elif role == Qt.ItemDataRole.DecorationRole:\n        if node.tree_node and node.tree_node.icon:\n            return get_icon(\n                node.tree_node.icon,\n                node.tree_node.icon_color,\n                fill=node.tree_node.icon_fill,\n            )\n    elif role == Qt.ItemDataRole.UserRole:\n        if node.tree_node and node.tree_node.data:\n            return node.tree_node.data\n    return None\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel.fetchMore","title":"<code>fetchMore(parent)</code>","text":"<p>Fetch and insert children for the node at parent.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>The parent index whose children should be loaded.</p> required Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>def fetchMore(self, parent: QModelIndex | QPersistentModelIndex) -&gt; None:\n    \"\"\"Fetch and insert children for the node at parent.\n\n    Args:\n        parent: The parent index whose children should be loaded.\n    \"\"\"\n    self._fetch_children_async(self._node_from_index(parent))\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel.get_node_id","title":"<code>get_node_id(index)</code>","text":"<p>Return the TreeNode.id for the given model index.</p> <p>Parameters:</p> Name Type Description Default <code>index</code> <code>QModelIndex</code> <p>A valid QModelIndex.</p> required <p>Returns:</p> Type Description <code>str | None</code> <p>The node's string ID, or None if the index is invalid.</p> Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>def get_node_id(self, index: QModelIndex) -&gt; str | None:\n    \"\"\"Return the TreeNode.id for the given model index.\n\n    Args:\n        index: A valid QModelIndex.\n\n    Returns:\n        The node's string ID, or None if the index is invalid.\n    \"\"\"\n    if not index.isValid():\n        return None\n    node: _InternalNode = index.internalPointer()  # type: ignore[assignment]\n    if node.tree_node is None:\n        return None\n    return node.tree_node.id\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel.hasChildren","title":"<code>hasChildren(parent=QModelIndex())</code>","text":"<p>Return whether the node at parent has or can have children.</p> <p>This is used by Qt to decide whether to draw the disclosure triangle, even before children are loaded.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>The parent index.</p> <code>QModelIndex()</code> <p>Returns:</p> Type Description <code>bool</code> <p>True if the node has loaded children or has_children is</p> <code>bool</code> <p>True on the TreeNode.</p> Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>def hasChildren(\n    self, parent: QModelIndex | QPersistentModelIndex = QModelIndex()\n) -&gt; bool:\n    \"\"\"Return whether the node at parent has or can have children.\n\n    This is used by Qt to decide whether to draw the disclosure\n    triangle, even before children are loaded.\n\n    Args:\n        parent: The parent index.\n\n    Returns:\n        True if the node has loaded children or has_children is\n        True on the TreeNode.\n    \"\"\"\n    node = self._node_from_index(parent)\n    if node.is_root:\n        return bool(node.children)\n    # node.tree_node is non-None here (is_root is False)\n    if node.children_loaded:\n        return bool(node.children)\n    return node.tree_node.has_children  # type: ignore[union-attr]\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel.index","title":"<code>index(row, column, parent=QModelIndex())</code>","text":"<p>Create a model index for the given row/column under parent.</p> <p>Parameters:</p> Name Type Description Default <code>row</code> <code>int</code> <p>Row number under the parent.</p> required <code>column</code> <code>int</code> <p>Column number (always 0).</p> required <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>Parent index.</p> <code>QModelIndex()</code> <p>Returns:</p> Type Description <code>QModelIndex</code> <p>A valid QModelIndex, or an invalid one if out of range.</p> Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>def index(\n    self,\n    row: int,\n    column: int,\n    parent: QModelIndex | QPersistentModelIndex = QModelIndex(),\n) -&gt; QModelIndex:\n    \"\"\"Create a model index for the given row/column under parent.\n\n    Args:\n        row: Row number under the parent.\n        column: Column number (always 0).\n        parent: Parent index.\n\n    Returns:\n        A valid QModelIndex, or an invalid one if out of range.\n    \"\"\"\n    parent_node = self._node_from_index(parent)\n    if row &lt; 0 or row &gt;= len(parent_node.children):\n        return QModelIndex()\n    child_node = parent_node.children[row]\n    return self.createIndex(row, column, child_node)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel.parent","title":"<code>parent(index)</code>","text":"<p>Return the parent index of the given index.</p> <p>Parameters:</p> Name Type Description Default <code>index</code> <code>QModelIndex</code> <p>A model index whose parent is requested.</p> required <p>Returns:</p> Type Description <code>QModelIndex</code> <p>Parent QModelIndex, or an invalid index if parent is root.</p> Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>def parent(self, index: QModelIndex) -&gt; QModelIndex:  # type: ignore[override]\n    \"\"\"Return the parent index of the given index.\n\n    Args:\n        index: A model index whose parent is requested.\n\n    Returns:\n        Parent QModelIndex, or an invalid index if parent is root.\n    \"\"\"\n    if not index.isValid():\n        return QModelIndex()\n\n    node: _InternalNode = index.internalPointer()  # type: ignore[assignment]\n    parent_node = node.parent\n    if parent_node is None or parent_node.is_root:\n        return QModelIndex()\n\n    # grandparent is always non-None for a non-root parent_node\n    grandparent = parent_node.parent\n    row = grandparent.children.index(parent_node)  # type: ignore[union-attr]\n    return self.createIndex(row, 0, parent_node)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel.reset","title":"<code>reset()</code>","text":"<p>Reset the model to its initial state and re-fetch root children.</p> <p>This is the recommended recovery path after a failed root fetch (i.e. when :attr:<code>fetch_error</code> was emitted for the root node).</p> Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>def reset(self) -&gt; None:\n    \"\"\"Reset the model to its initial state and re-fetch root children.\n\n    This is the recommended recovery path after a failed root fetch\n    (i.e. when :attr:`fetch_error` was emitted for the root node).\n    \"\"\"\n    old_ctx = self._context_id\n    if not self._no_async:\n        get_task_queue().clear_context_tasks(old_ctx)\n    self._reset_counter += 1\n    self._context_id = f\"ltm_{id(self)}_v{self._reset_counter}\"\n    self._pending_tasks = 0\n    self.beginResetModel()\n    self._root = _InternalNode(tree_node=None, parent=None)\n    self._all_nodes = {self._root}\n    self.endResetModel()\n    # Emit loading signals *after* endResetModel so that any slot\n    # connected to loading_changed observes a consistent model state.\n    self._update_loading_state()\n    self._fetch_children_async(self._root)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.LazyTreeModel.rowCount","title":"<code>rowCount(parent=QModelIndex())</code>","text":"<p>Return the number of rows under the given parent.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QModelIndex | QPersistentModelIndex</code> <p>The parent index.</p> <code>QModelIndex()</code> <p>Returns:</p> Type Description <code>int</code> <p>Number of loaded children. Returns 0 for nodes whose</p> <code>int</code> <p>children have not been fetched yet; Qt uses hasChildren()</p> <code>int</code> <p>to decide whether to show a disclosure triangle.</p> Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>def rowCount(\n    self, parent: QModelIndex | QPersistentModelIndex = QModelIndex()\n) -&gt; int:\n    \"\"\"Return the number of rows under the given parent.\n\n    Args:\n        parent: The parent index.\n\n    Returns:\n        Number of loaded children. Returns 0 for nodes whose\n        children have not been fetched yet; Qt uses hasChildren()\n        to decide whether to show a disclosure triangle.\n    \"\"\"\n    node = self._node_from_index(parent)\n    return len(node.children)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_model.html#client.ayon_ui_qt.components.tree_model.TreeNode","title":"<code>TreeNode</code>  <code>dataclass</code>","text":"<p>Represents a single node in a lazy-loaded tree.</p> <p>Attributes:</p> Name Type Description <code>id</code> <code>str</code> <p>Unique identifier for this node.</p> <code>label</code> <code>str</code> <p>Display label shown in the view.</p> <code>has_children</code> <code>bool</code> <p>Whether this node can have children.</p> <code>icon</code> <code>str</code> <p>Optional icon name or path.</p> <code>data</code> <code>dict</code> <p>Arbitrary extra data associated with this node.</p> Source code in <code>client/ayon_ui_qt/components/tree_model.py</code> <pre><code>@dataclass\nclass TreeNode:\n    \"\"\"Represents a single node in a lazy-loaded tree.\n\n    Attributes:\n        id: Unique identifier for this node.\n        label: Display label shown in the view.\n        has_children: Whether this node can have children.\n        icon: Optional icon name or path.\n        data: Arbitrary extra data associated with this node.\n    \"\"\"\n\n    id: str\n    label: str\n    has_children: bool = False\n    icon: str = \"\"\n    icon_color: str = \"#f4f5f5\"\n    icon_fill: bool = False\n    data: dict = field(default_factory=dict)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_view.html","title":"tree_view","text":"<p>AYTreeView component module.</p>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_view.html#client.ayon_ui_qt.components.tree_view.AYTreeView","title":"<code>AYTreeView</code>","text":"<p>               Bases: <code>QTreeView</code></p> <p>AYON-styled tree view.</p> <p>Fully self-contained: uses AYONStyle for all painting, a custom item delegate that draws directly bypassing any parent QSS, and AYScrollBar instances for scrollbars.</p> <p>Parameters:</p> Name Type Description Default <code>parent</code> <code>QWidget | None</code> <p>Optional parent widget.</p> <code>None</code> <code>variant</code> <code>QTreeViewVariants</code> <p>Visual style variant controlling background colour and item-state colours.</p> <code>Default</code> Source code in <code>client/ayon_ui_qt/components/tree_view.py</code> <pre><code>class AYTreeView(QTreeView):\n    \"\"\"AYON-styled tree view.\n\n    Fully self-contained: uses AYONStyle for all painting, a custom\n    item delegate that draws directly bypassing any parent QSS, and\n    AYScrollBar instances for scrollbars.\n\n    Args:\n        parent: Optional parent widget.\n        variant: Visual style variant controlling background colour and\n            item-state colours.\n    \"\"\"\n\n    Variants = QTreeViewVariants\n    selection_changed = Signal(QItemSelection, QItemSelection)\n\n    def __init__(\n        self,\n        parent: QWidget | None = None,\n        variant: QTreeViewVariants = QTreeViewVariants.Default,\n    ) -&gt; None:\n        self._variant_str: str = variant.value\n\n        super().__init__(parent)\n\n        style = get_ayon_style()\n        self.setStyle(style)\n\n        # Self-contained: do not inherit parent background or stylesheet.\n        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)\n        self.setAttribute(Qt.WidgetAttribute.WA_Hover, True)\n        self.setMouseTracking(True)\n\n        # Viewport must also be opaque with our colour.\n        self.viewport().setAttribute(\n            Qt.WidgetAttribute.WA_TranslucentBackground, False\n        )\n        self._sync_viewport_palette()\n\n        # Custom item delegate \u2014 paints items directly, avoids QSS.\n        delegate = TreeViewItemDelegate(\n            parent=self,\n            style_model=style.model,\n            variant=self._variant_str,\n        )\n        self.setItemDelegate(delegate)\n\n        # Styled scrollbars.\n        vsb = AYScrollBar(Qt.Orientation.Vertical, self)\n        self.setVerticalScrollBar(vsb)\n        self.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)\n        hsb = AYScrollBar(Qt.Orientation.Horizontal, self)\n        self.setHorizontalScrollBar(hsb)\n        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)\n\n        # No header \u2014 single-column hierarchical browser.\n        self.setHeaderHidden(True)\n\n        # Indentation from style data.\n        tv_style = style.model.get_style(\"QTreeView\", self._variant_str)\n        self.setIndentation(int(tv_style.get(\"indent\", 20)))\n\n        # Selection behaviour.\n        self.setSelectionMode(QTreeView.SelectionMode.SingleSelection)\n        self.setSelectionBehavior(QTreeView.SelectionBehavior.SelectRows)\n\n        # No default frame \u2014 drawn manually in paintEvent.\n        self.setFrameShape(QTreeView.Shape.NoFrame)\n\n    def _sync_viewport_palette(self) -&gt; None:\n        \"\"\"Apply the variant background colour to the viewport palette.\"\"\"\n        style = get_ayon_style()\n        tv_style = style.model.get_style(\"QTreeView\", self._variant_str)\n        bg = QColor(tv_style.get(\"background-color\", \"#252a31\"))\n        p = self.viewport().palette()\n        p.setColor(QPalette.ColorRole.Base, bg)\n        p.setColor(QPalette.ColorRole.Window, bg)\n        self.viewport().setPalette(p)\n\n    def paintEvent(self, event: QPaintEvent) -&gt; None:\n        \"\"\"Draw the outer container background before the items.\n\n        Args:\n            event: The paint event.\n        \"\"\"\n        painter = QPainter(self.viewport())\n        painter.setRenderHint(QPainter.RenderHint.Antialiasing, False)\n        style = get_ayon_style()\n        tv_style = style.model.get_style(\"QTreeView\", self._variant_str)\n        bg = QColor(tv_style.get(\"background-color\", \"#252a31\"))\n        painter.fillRect(self.viewport().rect(), bg)\n        painter.end()\n\n        # Let QTreeView draw its items on top.\n        super().paintEvent(event)\n\n    def mousePressEvent(self, event) -&gt; None:\n        \"\"\"Deselect all items when clicking in an empty area.\"\"\"\n        index = self.indexAt(event.pos())\n        if not index.isValid():\n            self.clearSelection()\n            self.setCurrentIndex(self.rootIndex())\n            return\n        super().mousePressEvent(event)\n\n    def selectionChanged(\n        self,\n        selected: QItemSelection,\n        deselected: QItemSelection,\n    ) -&gt; None:\n        \"\"\"Override to emit a public signal on selection change.\n\n        Args:\n            selected: Newly selected items.\n            deselected: Newly deselected items.\n        \"\"\"\n        super().selectionChanged(selected, deselected)\n        self.selection_changed.emit(selected, deselected)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_view.html#client.ayon_ui_qt.components.tree_view.AYTreeView.mousePressEvent","title":"<code>mousePressEvent(event)</code>","text":"<p>Deselect all items when clicking in an empty area.</p> Source code in <code>client/ayon_ui_qt/components/tree_view.py</code> <pre><code>def mousePressEvent(self, event) -&gt; None:\n    \"\"\"Deselect all items when clicking in an empty area.\"\"\"\n    index = self.indexAt(event.pos())\n    if not index.isValid():\n        self.clearSelection()\n        self.setCurrentIndex(self.rootIndex())\n        return\n    super().mousePressEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_view.html#client.ayon_ui_qt.components.tree_view.AYTreeView.paintEvent","title":"<code>paintEvent(event)</code>","text":"<p>Draw the outer container background before the items.</p> <p>Parameters:</p> Name Type Description Default <code>event</code> <code>QPaintEvent</code> <p>The paint event.</p> required Source code in <code>client/ayon_ui_qt/components/tree_view.py</code> <pre><code>def paintEvent(self, event: QPaintEvent) -&gt; None:\n    \"\"\"Draw the outer container background before the items.\n\n    Args:\n        event: The paint event.\n    \"\"\"\n    painter = QPainter(self.viewport())\n    painter.setRenderHint(QPainter.RenderHint.Antialiasing, False)\n    style = get_ayon_style()\n    tv_style = style.model.get_style(\"QTreeView\", self._variant_str)\n    bg = QColor(tv_style.get(\"background-color\", \"#252a31\"))\n    painter.fillRect(self.viewport().rect(), bg)\n    painter.end()\n\n    # Let QTreeView draw its items on top.\n    super().paintEvent(event)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/tree_view.html#client.ayon_ui_qt.components.tree_view.AYTreeView.selectionChanged","title":"<code>selectionChanged(selected, deselected)</code>","text":"<p>Override to emit a public signal on selection change.</p> <p>Parameters:</p> Name Type Description Default <code>selected</code> <code>QItemSelection</code> <p>Newly selected items.</p> required <code>deselected</code> <code>QItemSelection</code> <p>Newly deselected items.</p> required Source code in <code>client/ayon_ui_qt/components/tree_view.py</code> <pre><code>def selectionChanged(\n    self,\n    selected: QItemSelection,\n    deselected: QItemSelection,\n) -&gt; None:\n    \"\"\"Override to emit a public signal on selection change.\n\n    Args:\n        selected: Newly selected items.\n        deselected: Newly deselected items.\n    \"\"\"\n    super().selectionChanged(selected, deselected)\n    self.selection_changed.emit(selected, deselected)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/user_image.html","title":"user_image","text":""},{"location":"autoapi/client/ayon_ui_qt/components/user_image.html#client.ayon_ui_qt.components.user_image.AYUserImage","title":"<code>AYUserImage</code>","text":"<p>               Bases: <code>QLabel</code></p> Source code in <code>client/ayon_ui_qt/components/user_image.py</code> <pre><code>class AYUserImage(QtWidgets.QLabel):\n    Variants = AYUserImageVariants\n\n    def __init__(\n        self,\n        *args,\n        src: Path | str = \"\",\n        name: str = \"\",\n        full_name: str = \"\",\n        size: int = 30,\n        highlight: bool = False,\n        outline: bool = True,\n        file_cacher: Callable | None = None,\n        variant=Variants.Default,\n        **kwargs,\n    ):\n        # file path to icon\n        self._src = src\n        # short user name\n        self._name = name\n        # full user name\n        self._full_name = full_name\n        # pixmap size\n        self._size = size\n        # green outline if true, light grey otherwise\n        self._highlight = highlight\n        # enable / disable outline\n        self._outline = outline\n        # a file loader function for the image cache: src is the cache key.\n        self._file_cacher = file_cacher\n        # Variant string for looking up style data\n        self._variant_str = variant.value\n\n        super().__init__(*args, **kwargs)\n        stl = get_ayon_style()\n        self.setStyle(stl)\n        self._style = stl.model.get_style(\n            \"AYUserImage\", variant=self._variant_str\n        )\n\n        self.set_image()\n\n    def _get_colors(\n        self,\n    ) -&gt; tuple[QtGui.QColor, QtGui.QColor, QtGui.QColor, QtGui.QColor]:\n        \"\"\"Read image colors from the AYUserImage style data.\n\n        Returns:\n            A tuple of (initials_bg, outline_color, highlight_color).\n        \"\"\"\n        style = self._style\n        fg = QtGui.QColor(style.get(\"initials-color\", \"#ffffff\"))\n        bg = QtGui.QColor(style.get(\"initials-background-color\", \"#484875\"))\n        outline = QtGui.QColor(style.get(\"outline-color\", \"#e1e1e1\"))\n        highlight = QtGui.QColor(style.get(\"highlight-color\", \"#6be1ac\"))\n        return fg, bg, outline, highlight\n\n    def set_image(self) -&gt; None:\n        \"\"\"Render the user avatar pixmap and assign it to this label.\"\"\"\n        fg_color, bg_color, outline_color, highlight_color = self._get_colors()\n        active_outline = highlight_color if self._highlight else outline_color\n\n        self.pxm = QtGui.QPixmap(self._size, self._size)\n        self.pxm.fill(QtCore.Qt.GlobalColor.transparent)\n        painter = QtGui.QPainter(self.pxm)\n        painter.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)\n\n        if self._src:\n            if not Path(str(self._src)).exists() and self._file_cacher:\n                ic = ImageCache.get_instance()\n                self._src = ic.get(\n                    str(self._src), partial(self._file_cacher, self._src)\n                )\n\n            # Load and draw src icon file in a circle\n            source_pixmap = QtGui.QPixmap(self._src)\n            if not source_pixmap.isNull():\n                # Scale the source image to fit within the circle (with some\n                # margin for outline)\n\n                # Leave space for outline\n                inner_size = self._size - (2 if self._outline else 0)\n                scaled_pixmap = source_pixmap.scaled(\n                    inner_size,\n                    inner_size,\n                    QtCore.Qt.AspectRatioMode.KeepAspectRatioByExpanding,\n                    QtCore.Qt.TransformationMode.SmoothTransformation,\n                )\n\n                # Create circular clipping path\n                clip_path = QtGui.QPainterPath()\n                clip_path.addEllipse(0, 0, self._size, self._size)\n                painter.setClipPath(clip_path)\n\n                # Draw the scaled image centered\n                x = (self._size - scaled_pixmap.width()) // 2\n                y = (self._size - scaled_pixmap.height()) // 2\n                painter.drawPixmap(x, y, scaled_pixmap)\n\n                # Reset clipping\n                painter.setClipping(False)\n            else:\n                log.warning(\"Could not load src %s\", self._src)\n        else:\n            initials = \"?\"\n            if self._full_name:\n                initials = \"\".join([p[0] for p in self._full_name.split()])\n            elif self._name:\n                initials = self._name[0]\n\n            # Draw a circle with white initials over a color background\n\n            # Fill circle with background color from style\n            painter.setBrush(QtGui.QBrush(bg_color))\n            painter.setPen(QtCore.Qt.PenStyle.NoPen)\n            painter.drawEllipse(0, 0, self._size, self._size)\n\n            # Draw white initials\n            painter.setPen(QtGui.QPen(fg_color))\n            font = painter.font()\n            point_size = max(8, self._size // 2)\n            font.setPointSize(point_size)\n            painter.setFont(font)\n\n            painter.drawText(\n                QtCore.QRect(0, 0, self._size, self._size),\n                QtCore.Qt.AlignmentFlag.AlignCenter,\n                initials.upper(),\n            )\n\n        # Draw outline\n        if self._outline or self._highlight:\n            painter.setBrush(QtCore.Qt.BrushStyle.NoBrush)\n            painter.setPen(QtGui.QPen(active_outline, 1))\n            painter.drawEllipse(1, 1, self._size - 2, self._size - 2)\n\n        painter.end()\n\n        # Set the pixmap to the label\n        self.setPixmap(self.pxm)\n\n    def update_params(self, src, full_name):\n        self._src = src\n        self._full_name = full_name\n        self.set_image()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/components/user_image.html#client.ayon_ui_qt.components.user_image.AYUserImage.set_image","title":"<code>set_image()</code>","text":"<p>Render the user avatar pixmap and assign it to this label.</p> Source code in <code>client/ayon_ui_qt/components/user_image.py</code> <pre><code>def set_image(self) -&gt; None:\n    \"\"\"Render the user avatar pixmap and assign it to this label.\"\"\"\n    fg_color, bg_color, outline_color, highlight_color = self._get_colors()\n    active_outline = highlight_color if self._highlight else outline_color\n\n    self.pxm = QtGui.QPixmap(self._size, self._size)\n    self.pxm.fill(QtCore.Qt.GlobalColor.transparent)\n    painter = QtGui.QPainter(self.pxm)\n    painter.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)\n\n    if self._src:\n        if not Path(str(self._src)).exists() and self._file_cacher:\n            ic = ImageCache.get_instance()\n            self._src = ic.get(\n                str(self._src), partial(self._file_cacher, self._src)\n            )\n\n        # Load and draw src icon file in a circle\n        source_pixmap = QtGui.QPixmap(self._src)\n        if not source_pixmap.isNull():\n            # Scale the source image to fit within the circle (with some\n            # margin for outline)\n\n            # Leave space for outline\n            inner_size = self._size - (2 if self._outline else 0)\n            scaled_pixmap = source_pixmap.scaled(\n                inner_size,\n                inner_size,\n                QtCore.Qt.AspectRatioMode.KeepAspectRatioByExpanding,\n                QtCore.Qt.TransformationMode.SmoothTransformation,\n            )\n\n            # Create circular clipping path\n            clip_path = QtGui.QPainterPath()\n            clip_path.addEllipse(0, 0, self._size, self._size)\n            painter.setClipPath(clip_path)\n\n            # Draw the scaled image centered\n            x = (self._size - scaled_pixmap.width()) // 2\n            y = (self._size - scaled_pixmap.height()) // 2\n            painter.drawPixmap(x, y, scaled_pixmap)\n\n            # Reset clipping\n            painter.setClipping(False)\n        else:\n            log.warning(\"Could not load src %s\", self._src)\n    else:\n        initials = \"?\"\n        if self._full_name:\n            initials = \"\".join([p[0] for p in self._full_name.split()])\n        elif self._name:\n            initials = self._name[0]\n\n        # Draw a circle with white initials over a color background\n\n        # Fill circle with background color from style\n        painter.setBrush(QtGui.QBrush(bg_color))\n        painter.setPen(QtCore.Qt.PenStyle.NoPen)\n        painter.drawEllipse(0, 0, self._size, self._size)\n\n        # Draw white initials\n        painter.setPen(QtGui.QPen(fg_color))\n        font = painter.font()\n        point_size = max(8, self._size // 2)\n        font.setPointSize(point_size)\n        painter.setFont(font)\n\n        painter.drawText(\n            QtCore.QRect(0, 0, self._size, self._size),\n            QtCore.Qt.AlignmentFlag.AlignCenter,\n            initials.upper(),\n        )\n\n    # Draw outline\n    if self._outline or self._highlight:\n        painter.setBrush(QtCore.Qt.BrushStyle.NoBrush)\n        painter.setPen(QtGui.QPen(active_outline, 1))\n        painter.drawEllipse(1, 1, self._size - 2, self._size - 2)\n\n    painter.end()\n\n    # Set the pixmap to the label\n    self.setPixmap(self.pxm)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/index.html","title":"vendor","text":""},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/index.html","title":"qtmaterialsymbols","text":""},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/index.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.IconicFont","title":"<code>IconicFont</code>","text":"<p>               Bases: <code>QObject</code></p> <p>Main class for managing icons.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.py</code> <pre><code>class IconicFont(QtCore.QObject):\n    \"\"\"Main class for managing icons.\"\"\"\n\n    def __init__(self):\n        super().__init__()\n        self._painter = CharIconPainter()\n        self._icon_cache = {}\n\n    def get_charmap(self) -&gt; Dict[str, int]:\n        return get_char_mapping()\n\n    def get_font(self, size: int, filled: bool) -&gt; QtGui.QFont:\n        \"\"\"Return a QFont corresponding to the given size.\"\"\"\n        if filled:\n            font = QtGui.QFont(_get_font_name_filled())\n        else:\n            font = QtGui.QFont(_get_font_name())\n        font.setPixelSize(round(size))\n        return font\n\n    def get_icon_with_options(self, options: IconOptions) -&gt; QtGui.QIcon:\n        \"\"\"Return a QIcon object corresponding to the provided icon name.\"\"\"\n        if QtWidgets.QApplication.instance() is None:\n            warnings.warn(\n                \"You need to have a running QApplication!\"\n            )\n            return QtGui.QIcon()\n\n        cache_key = options.identifier\n        if cache_key in self._icon_cache:\n            return self._icon_cache[cache_key]\n\n        output = self._icon_by_painter(self._painter, options)\n        self._icon_cache[cache_key] = output\n        return output\n\n    def get_icon(\n        self,\n        icon_name: Optional[str] = None,\n        color: Optional[Union[QtGui.QColor, str]] = None,\n        opacity: Optional[float] = None,\n        scale_factor: Optional[float] = None,\n        offset: Optional[Position] = None,\n        hflip: bool = False,\n        vflip: bool = False,\n        rotate: int = 0,\n        fill: bool = True,\n        **kwargs\n    ) -&gt; QtGui.QIcon:\n        \"\"\"Return a QIcon object corresponding to the provided icon name.\"\"\"\n        if QtWidgets.QApplication.instance() is None:\n            warnings.warn(\n                \"You need to have a running QApplication!\"\n            )\n            return QtGui.QIcon()\n\n        options = IconOptions.from_data(\n            icon_name=icon_name,\n            color=color,\n            opacity=opacity,\n            scale_factor=scale_factor,\n            offset=offset,\n            hflip=hflip,\n            vflip=vflip,\n            rotate=rotate,\n            fill=fill,\n            **kwargs\n        )\n        cache_key = options.identifier\n        if cache_key in self._icon_cache:\n            return self._icon_cache[cache_key]\n        return self.get_icon_with_options(options)\n\n    def _icon_by_painter(self, painter, options):\n        \"\"\"Return the icon corresponding to the given painter.\"\"\"\n        engine = CharIconEngine(self, painter, options)\n        return QtGui.QIcon(engine)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/index.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.IconicFont.get_font","title":"<code>get_font(size, filled)</code>","text":"<p>Return a QFont corresponding to the given size.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.py</code> <pre><code>def get_font(self, size: int, filled: bool) -&gt; QtGui.QFont:\n    \"\"\"Return a QFont corresponding to the given size.\"\"\"\n    if filled:\n        font = QtGui.QFont(_get_font_name_filled())\n    else:\n        font = QtGui.QFont(_get_font_name())\n    font.setPixelSize(round(size))\n    return font\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/index.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.IconicFont.get_icon","title":"<code>get_icon(icon_name=None, color=None, opacity=None, scale_factor=None, offset=None, hflip=False, vflip=False, rotate=0, fill=True, **kwargs)</code>","text":"<p>Return a QIcon object corresponding to the provided icon name.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.py</code> <pre><code>def get_icon(\n    self,\n    icon_name: Optional[str] = None,\n    color: Optional[Union[QtGui.QColor, str]] = None,\n    opacity: Optional[float] = None,\n    scale_factor: Optional[float] = None,\n    offset: Optional[Position] = None,\n    hflip: bool = False,\n    vflip: bool = False,\n    rotate: int = 0,\n    fill: bool = True,\n    **kwargs\n) -&gt; QtGui.QIcon:\n    \"\"\"Return a QIcon object corresponding to the provided icon name.\"\"\"\n    if QtWidgets.QApplication.instance() is None:\n        warnings.warn(\n            \"You need to have a running QApplication!\"\n        )\n        return QtGui.QIcon()\n\n    options = IconOptions.from_data(\n        icon_name=icon_name,\n        color=color,\n        opacity=opacity,\n        scale_factor=scale_factor,\n        offset=offset,\n        hflip=hflip,\n        vflip=vflip,\n        rotate=rotate,\n        fill=fill,\n        **kwargs\n    )\n    cache_key = options.identifier\n    if cache_key in self._icon_cache:\n        return self._icon_cache[cache_key]\n    return self.get_icon_with_options(options)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/index.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.IconicFont.get_icon_with_options","title":"<code>get_icon_with_options(options)</code>","text":"<p>Return a QIcon object corresponding to the provided icon name.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.py</code> <pre><code>def get_icon_with_options(self, options: IconOptions) -&gt; QtGui.QIcon:\n    \"\"\"Return a QIcon object corresponding to the provided icon name.\"\"\"\n    if QtWidgets.QApplication.instance() is None:\n        warnings.warn(\n            \"You need to have a running QApplication!\"\n        )\n        return QtGui.QIcon()\n\n    cache_key = options.identifier\n    if cache_key in self._icon_cache:\n        return self._icon_cache[cache_key]\n\n    output = self._icon_by_painter(self._painter, options)\n    self._icon_cache[cache_key] = output\n    return output\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/browser.html","title":"browser","text":""},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/browser.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.browser.IconBrowser","title":"<code>IconBrowser</code>","text":"<p>               Bases: <code>QMainWindow</code></p> <p>A small browser window that allows the user to search through all icons from the available version of QtAwesome.  You can also copy the name and python code for the currently selected icon.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/browser.py</code> <pre><code>class IconBrowser(QtWidgets.QMainWindow):\n    \"\"\"\n    A small browser window that allows the user to search through all icons from\n    the available version of QtAwesome.  You can also copy the name and python\n    code for the currently selected icon.\n    \"\"\"\n\n    def __init__(self):\n        super().__init__()\n        self.setMinimumSize(630, 420)\n        self.setWindowTitle(\"Material Symbols Browser\")\n\n        # Prepare icons data\n        instance = get_instance()\n        font_maps = instance.get_charmap()\n\n        icon_names = list(font_maps)\n\n        center_widget = QtWidgets.QWidget(self)\n\n        # Filtering inputs\n        header_widget = QtWidgets.QWidget(center_widget)\n\n        filter_input = QtWidgets.QLineEdit(header_widget)\n        filter_input.setPlaceholderText(\"Filter by name...\")\n\n        filled_check = QtWidgets.QCheckBox(\"Fill\", header_widget)\n        filled_check.setToolTip(\"Filled icons\")\n\n        copy_btn = QtWidgets.QPushButton(\"&lt; no selection &gt;\", header_widget)\n        copy_btn.setToolTip(\"Copy name\")\n\n        header_layout = QtWidgets.QHBoxLayout(header_widget)\n        header_layout.setContentsMargins(0, 0, 0, 0)\n        header_layout.addWidget(filter_input, 4)\n        header_layout.addWidget(filled_check, 1)\n        header_layout.addWidget(copy_btn, 0)\n\n        # Icons view\n        icons_view = IconListView(center_widget)\n        icons_view.setUniformItemSizes(True)\n        icons_view.setResizeMode(QtWidgets.QListView.Adjust)\n        icons_view.setViewMode(QtWidgets.QListView.IconMode)\n        icons_view.setContextMenuPolicy(QtCore.Qt.CustomContextMenu)\n\n        model = IconModel(QtGui.QColor(\"#444746\"))\n        model.setStringList(sorted(icon_names))\n\n        proxy_model = QtCore.QSortFilterProxyModel()\n        proxy_model.setSourceModel(model)\n        proxy_model.setFilterCaseSensitivity(QtCore.Qt.CaseInsensitive)\n\n        icons_view.setModel(proxy_model)\n\n        center_layout = QtWidgets.QVBoxLayout(center_widget)\n        center_layout.setContentsMargins(15, 15, 15, 15)\n        center_layout.setSpacing(5)\n        center_layout.addWidget(header_widget, 0)\n        center_layout.addWidget(icons_view, 1)\n\n        self.setCentralWidget(center_widget)\n\n        filter_timer = QtCore.QTimer(self)\n        filter_timer.setSingleShot(True)\n        filter_timer.setInterval(AUTO_SEARCH_TIMEOUT)\n\n        filter_input.textChanged.connect(self._on_filter_change)\n        filter_input.returnPressed.connect(self._on_filter_confirm)\n        filled_check.stateChanged.connect(self._on_filled_change)\n        icons_view.doubleClicked.connect(self._copy_icon_name)\n        icons_view.selectionModel().selectionChanged.connect(\n            self._on_selection_change\n        )\n        copy_btn.clicked.connect(self._copy_icon_name)\n        filter_timer.timeout.connect(self._update_filter)\n\n        QtWidgets.QShortcut(\n            QtGui.QKeySequence(QtCore.Qt.Key_Return),\n            self,\n            self._copy_icon_name,\n        )\n        QtWidgets.QShortcut(\n            QtGui.QKeySequence(\"Ctrl+F\"),\n            self,\n            filter_input.setFocus,\n        )\n\n        self._filled_check = filled_check\n        self._copy_btn = copy_btn\n        self._filter_input = filter_input\n        self._icons_view = icons_view\n        self._model = model\n        self._proxy_model = proxy_model\n        self._filter_timer = filter_timer\n\n    def showEvent(self, event):\n        super().showEvent(event)\n        self._filter_input.setFocus()\n        self.setStyleSheet(load_stylesheet())\n\n    def _update_filter(self):\n        regex = \"\"\n        search_term = self._filter_input.text()\n        if search_term:\n            regex = f\".*{search_term}.*$\"\n\n        self._proxy_model.setFilterRegularExpression(regex)\n\n    def _on_filled_change(self):\n        self._model.set_filled(self._filled_check.isChecked())\n\n    def _on_selection_change(self, _new_selection, _old_selection):\n        indexes = self._icons_view.selectedIndexes()\n        if not indexes:\n            self._copy_btn.setText(\"&lt; nothing &gt;\")\n            return\n\n        index = indexes[0]\n        icon_name = index.data()\n        self._copy_btn.setText(icon_name)\n\n    def _on_filter_change(self):\n        self._filter_timer.start()\n\n    def _on_filter_confirm(self):\n        self._filter_timer.stop()\n        self._update_filter()\n\n    def _copy_icon_name(self):\n        indexes = self._icons_view.selectedIndexes()\n        for index in indexes:\n            clipboard = QtWidgets.QApplication.instance().clipboard()\n            clipboard.setText(index.data())\n            break\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/browser.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.browser.IconListView","title":"<code>IconListView</code>","text":"<p>               Bases: <code>QListView</code></p> <p>A QListView that scales it's grid size to ensure the same number of columns are always drawn.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/browser.py</code> <pre><code>class IconListView(QtWidgets.QListView):\n    \"\"\"\n    A QListView that scales it's grid size to ensure the same number of\n    columns are always drawn.\n    \"\"\"\n\n    def __init__(self, parent=None):\n        super().__init__(parent)\n        self.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOn)\n        self.set_icon_size(54)\n\n    def set_icon_size(self, size):\n        \"\"\"\n        Set the icon size for the icons in the view.\n        \"\"\"\n        grid_size = (size / 8.0) * 12.0\n        self.setGridSize(QtCore.QSize(grid_size, grid_size))\n        self.setIconSize(QtCore.QSize(size, size))\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/browser.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.browser.IconListView.set_icon_size","title":"<code>set_icon_size(size)</code>","text":"<p>Set the icon size for the icons in the view.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/browser.py</code> <pre><code>def set_icon_size(self, size):\n    \"\"\"\n    Set the icon size for the icons in the view.\n    \"\"\"\n    grid_size = (size / 8.0) * 12.0\n    self.setGridSize(QtCore.QSize(grid_size, grid_size))\n    self.setIconSize(QtCore.QSize(size, size))\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/browser.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.browser.run","title":"<code>run()</code>","text":"<p>Start the IconBrowser and block until the process exits.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/browser.py</code> <pre><code>def run():\n    \"\"\"\n    Start the IconBrowser and block until the process exits.\n    \"\"\"\n    app = QtWidgets.QApplication([])\n\n    browser = IconBrowser()\n    browser.show()\n\n    sys.exit(app.exec_())\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/exceptions.html","title":"exceptions","text":""},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/exceptions.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.exceptions.ApplicationNotRunning","title":"<code>ApplicationNotRunning</code>","text":"<p>               Bases: <code>Exception</code></p> <p>Raised when the QApplication is not running.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/exceptions.py</code> <pre><code>class ApplicationNotRunning(Exception):\n    \"\"\"Raised when the QApplication is not running.\"\"\"\n    pass\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/exceptions.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.exceptions.FontError","title":"<code>FontError</code>","text":"<p>               Bases: <code>Exception</code></p> <p>Raised when there is an issue with font.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/exceptions.py</code> <pre><code>class FontError(Exception):\n    \"\"\"Raised when there is an issue with font.\"\"\"\n    pass\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.html","title":"iconic_font","text":""},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.iconic_font--iconic-font","title":"Iconic Font","text":"<p>A lightweight module handling iconic fonts.</p> <p>It is designed to provide a simple way for creating QIcons from glyphs.</p> <p>From a user's viewpoint, the main entry point is the <code>IconicFont</code> class which contains methods for loading new iconic fonts with their character map and methods returning instances of <code>QIcon</code>.</p>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.iconic_font.CharIconEngine","title":"<code>CharIconEngine</code>","text":"<p>               Bases: <code>QIconEngine</code></p> <p>Specialization of QIconEngine used to draw font-based icons.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.py</code> <pre><code>class CharIconEngine(QtGui.QIconEngine):\n    \"\"\"Specialization of QIconEngine used to draw font-based icons.\"\"\"\n\n    def __init__(\n        self,\n        iconic: \"IconicFont\",\n        painter: QtGui.QPainter,\n        options: IconOptions\n    ):\n        super().__init__()\n        self._iconic = iconic\n        self._painter = painter\n        self._options = options\n\n    def paint(self, painter, rect, mode, state):\n        self._painter.paint(\n            self._iconic,\n            painter,\n            rect,\n            mode,\n            state,\n            self._options\n        )\n\n    def pixmap(self, size, mode, state):\n        pm = QtGui.QPixmap(size)\n        pm.fill(QtCore.Qt.transparent)\n        painter = QtGui.QPainter(pm)\n        self.paint(\n            painter,\n            QtCore.QRect(QtCore.QPoint(0, 0), size),\n            mode,\n            state\n        )\n        return pm\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.iconic_font.CharIconPainter","title":"<code>CharIconPainter</code>","text":"<p>Char icon painter.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.py</code> <pre><code>class CharIconPainter:\n    \"\"\"Char icon painter.\"\"\"\n    def paint(self, iconic, painter, rect, mode, state, options):\n        \"\"\"Main paint method.\"\"\"\n        self._paint_icon(iconic, painter, rect, mode, state, options)\n\n    def _paint_icon(self, iconic, painter, rect, mode, state, options):\n        \"\"\"Paint a single icon.\"\"\"\n        painter.save()\n\n        color = options.get_color_for_state(state, mode)\n        char = options.get_char_for_state(state, mode)\n\n        painter.setPen(QtGui.QColor(color))\n\n        draw_size = round(rect.height() * options.scale_factor)\n\n        font = iconic.get_font(\n            draw_size,\n            options.get_fill_for_state(state, mode)\n        )\n\n        painter.setFont(font)\n        if options.offset is not None:\n            rect = QtCore.QRect(rect)\n            rect.translate(\n                round(options.offset.x * rect.width()),\n                round(options.offset.y * rect.height())\n            )\n\n        scale_x = -1 if options.hflip else 1\n        scale_y = -1 if options.vflip else 1\n\n        if options.vflip or options.hflip or options.rotate:\n            x_center = rect.width() * 0.5\n            y_center = rect.height() * 0.5\n            painter.translate(x_center, y_center)\n\n            transfrom = QtGui.QTransform()\n            transfrom.scale(scale_x, scale_y)\n            painter.setTransform(transfrom, True)\n\n            if options.rotate:\n                painter.rotate(options.rotate)\n            painter.translate(-x_center, -y_center)\n\n        painter.setOpacity(options.opacity)\n\n        painter.drawText(rect, QtCore.Qt.AlignCenter, char)\n        painter.restore()\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.iconic_font.CharIconPainter.paint","title":"<code>paint(iconic, painter, rect, mode, state, options)</code>","text":"<p>Main paint method.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.py</code> <pre><code>def paint(self, iconic, painter, rect, mode, state, options):\n    \"\"\"Main paint method.\"\"\"\n    self._paint_icon(iconic, painter, rect, mode, state, options)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.iconic_font.IconicFont","title":"<code>IconicFont</code>","text":"<p>               Bases: <code>QObject</code></p> <p>Main class for managing icons.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.py</code> <pre><code>class IconicFont(QtCore.QObject):\n    \"\"\"Main class for managing icons.\"\"\"\n\n    def __init__(self):\n        super().__init__()\n        self._painter = CharIconPainter()\n        self._icon_cache = {}\n\n    def get_charmap(self) -&gt; Dict[str, int]:\n        return get_char_mapping()\n\n    def get_font(self, size: int, filled: bool) -&gt; QtGui.QFont:\n        \"\"\"Return a QFont corresponding to the given size.\"\"\"\n        if filled:\n            font = QtGui.QFont(_get_font_name_filled())\n        else:\n            font = QtGui.QFont(_get_font_name())\n        font.setPixelSize(round(size))\n        return font\n\n    def get_icon_with_options(self, options: IconOptions) -&gt; QtGui.QIcon:\n        \"\"\"Return a QIcon object corresponding to the provided icon name.\"\"\"\n        if QtWidgets.QApplication.instance() is None:\n            warnings.warn(\n                \"You need to have a running QApplication!\"\n            )\n            return QtGui.QIcon()\n\n        cache_key = options.identifier\n        if cache_key in self._icon_cache:\n            return self._icon_cache[cache_key]\n\n        output = self._icon_by_painter(self._painter, options)\n        self._icon_cache[cache_key] = output\n        return output\n\n    def get_icon(\n        self,\n        icon_name: Optional[str] = None,\n        color: Optional[Union[QtGui.QColor, str]] = None,\n        opacity: Optional[float] = None,\n        scale_factor: Optional[float] = None,\n        offset: Optional[Position] = None,\n        hflip: bool = False,\n        vflip: bool = False,\n        rotate: int = 0,\n        fill: bool = True,\n        **kwargs\n    ) -&gt; QtGui.QIcon:\n        \"\"\"Return a QIcon object corresponding to the provided icon name.\"\"\"\n        if QtWidgets.QApplication.instance() is None:\n            warnings.warn(\n                \"You need to have a running QApplication!\"\n            )\n            return QtGui.QIcon()\n\n        options = IconOptions.from_data(\n            icon_name=icon_name,\n            color=color,\n            opacity=opacity,\n            scale_factor=scale_factor,\n            offset=offset,\n            hflip=hflip,\n            vflip=vflip,\n            rotate=rotate,\n            fill=fill,\n            **kwargs\n        )\n        cache_key = options.identifier\n        if cache_key in self._icon_cache:\n            return self._icon_cache[cache_key]\n        return self.get_icon_with_options(options)\n\n    def _icon_by_painter(self, painter, options):\n        \"\"\"Return the icon corresponding to the given painter.\"\"\"\n        engine = CharIconEngine(self, painter, options)\n        return QtGui.QIcon(engine)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.iconic_font.IconicFont.get_font","title":"<code>get_font(size, filled)</code>","text":"<p>Return a QFont corresponding to the given size.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.py</code> <pre><code>def get_font(self, size: int, filled: bool) -&gt; QtGui.QFont:\n    \"\"\"Return a QFont corresponding to the given size.\"\"\"\n    if filled:\n        font = QtGui.QFont(_get_font_name_filled())\n    else:\n        font = QtGui.QFont(_get_font_name())\n    font.setPixelSize(round(size))\n    return font\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.iconic_font.IconicFont.get_icon","title":"<code>get_icon(icon_name=None, color=None, opacity=None, scale_factor=None, offset=None, hflip=False, vflip=False, rotate=0, fill=True, **kwargs)</code>","text":"<p>Return a QIcon object corresponding to the provided icon name.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.py</code> <pre><code>def get_icon(\n    self,\n    icon_name: Optional[str] = None,\n    color: Optional[Union[QtGui.QColor, str]] = None,\n    opacity: Optional[float] = None,\n    scale_factor: Optional[float] = None,\n    offset: Optional[Position] = None,\n    hflip: bool = False,\n    vflip: bool = False,\n    rotate: int = 0,\n    fill: bool = True,\n    **kwargs\n) -&gt; QtGui.QIcon:\n    \"\"\"Return a QIcon object corresponding to the provided icon name.\"\"\"\n    if QtWidgets.QApplication.instance() is None:\n        warnings.warn(\n            \"You need to have a running QApplication!\"\n        )\n        return QtGui.QIcon()\n\n    options = IconOptions.from_data(\n        icon_name=icon_name,\n        color=color,\n        opacity=opacity,\n        scale_factor=scale_factor,\n        offset=offset,\n        hflip=hflip,\n        vflip=vflip,\n        rotate=rotate,\n        fill=fill,\n        **kwargs\n    )\n    cache_key = options.identifier\n    if cache_key in self._icon_cache:\n        return self._icon_cache[cache_key]\n    return self.get_icon_with_options(options)\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.html#client.ayon_ui_qt.vendor.qtmaterialsymbols.iconic_font.IconicFont.get_icon_with_options","title":"<code>get_icon_with_options(options)</code>","text":"<p>Return a QIcon object corresponding to the provided icon name.</p> Source code in <code>client/ayon_ui_qt/vendor/qtmaterialsymbols/iconic_font.py</code> <pre><code>def get_icon_with_options(self, options: IconOptions) -&gt; QtGui.QIcon:\n    \"\"\"Return a QIcon object corresponding to the provided icon name.\"\"\"\n    if QtWidgets.QApplication.instance() is None:\n        warnings.warn(\n            \"You need to have a running QApplication!\"\n        )\n        return QtGui.QIcon()\n\n    cache_key = options.identifier\n    if cache_key in self._icon_cache:\n        return self._icon_cache[cache_key]\n\n    output = self._icon_by_painter(self._painter, options)\n    self._icon_cache[cache_key] = output\n    return output\n</code></pre>"},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/structures.html","title":"structures","text":""},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/utils.html","title":"utils","text":""},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/version.html","title":"version","text":""},{"location":"autoapi/client/ayon_ui_qt/vendor/qtmaterialsymbols/resources/index.html","title":"resources","text":""},{"location":"autoapi/server/index.html","title":"server","text":"<p>Server-side addon definition for AYON UI Qt.</p> <p>This addon primarily provides client-side functionality (Qt widgets), so server-side configuration is minimal.</p>"},{"location":"autoapi/server/index.html#server.UIQtAddon","title":"<code>UIQtAddon</code>","text":"<p>               Bases: <code>BaseServerAddon</code></p> <p>Server-side addon for UI Qt library.</p> <p>This addon provides a library of Qt widgets styled to match AYON's frontend design system. Server-side functionality is limited to enabling/disabling the addon and optional theme customization.</p> Source code in <code>server/__init__.py</code> <pre><code>class UIQtAddon(BaseServerAddon):\n    \"\"\"Server-side addon for UI Qt library.\n\n    This addon provides a library of Qt widgets styled to match\n    AYON's frontend design system. Server-side functionality is\n    limited to enabling/disabling the addon and optional theme\n    customization.\n    \"\"\"\n\n    name = \"ui_qt\"\n    title = \"AYON UI Qt\"\n    version = \"0.1.0\"\n</code></pre>"}]}